# ── Fonts ──────────────────────────────────────────────────────────────────────
# ── Languages: every piece of text goes through TFont -> tr() ──────────────────
import re as _re
LANG_CODES = ("EN","ES","HE")
TR = {"ES":{}, "HE":{}}            # exact English text -> translation (filled below)
TR_TEMPLATES = []                   # (regex, {"ES":fmt,"HE":fmt}) for text with numbers/names
_tr_cache = {}
_HEB = _re.compile(r'[֐-׿]')
_LTR_RUN = _re.compile(r'[A-Za-z0-9@#%][A-Za-z0-9@#.:/%+\-_\' ]*[A-Za-z0-9%@#]|[A-Za-z0-9@#%]')
_STR_LOG = set() if os.environ.get("CUP_LOG_STRINGS") else None

def lang_code():
    c=str(globals().get("current_lang","EN")).upper()
    return c if c in LANG_CODES else "EN"

def tr(text):
    """Translate an English UI string to the current language (exact match, then templates)."""
    if _STR_LOG is not None and text: _STR_LOG.add(text)
    L=lang_code()
    if L=="EN" or not text: return text
    key=(L,text)
    if key in _tr_cache: return _tr_cache[key]
    out=TR[L].get(text)
    if out is None:
        s=text.strip(); lead=text[:len(text)-len(text.lstrip())]
        out=TR[L].get(s)
        if out is not None: out=lead+out
    if out is None:
        for rx,fm in TR_TEMPLATES:
            m=rx.match(text)
            if m and L in fm:
                out=fm[L].format(*[tr(g) if g else "" for g in m.groups()]); break
    if out is None: out=text
    if len(_tr_cache)>6000: _tr_cache.clear()
    _tr_cache[key]=out; return out

_MIRROR = str.maketrans("()[]{}<>",")(][}{><")
def bidi(text):
    """Visual order for Hebrew (pygame draws left-to-right)."""
    if not _HEB.search(text): return text
    v=text[::-1].translate(_MIRROR)
    return _LTR_RUN.sub(lambda m: m.group(0)[::-1].translate(_MIRROR), v)

