_HE_FONTS="arial,segoeui,tahoma,dejavusans,freesans"

def _font_has_hebrew(path):
    """True only if the font really draws Hebrew letters (not empty boxes)."""
    try:
        f=pygame.font.Font(path,24)
        a=f.render("\u05d0\u05d1\u05d2\u05e9",True,(255,255,255))
        z=f.render("\ue000\ue001\ue002\ue003",True,(255,255,255))
        return a.get_size()!=z.get_size() or pygame.image.tostring(a,"RGBA")!=pygame.image.tostring(z,"RGBA")
    except Exception:
        return False

_HE_FONT_PATH=None
def find_hebrew_font():
    """Find a font file with Hebrew letters: Windows Fonts folder first, then installed fonts."""
    global _HE_FONT_PATH
    if _HE_FONT_PATH is not None: return _HE_FONT_PATH
    fonts_dir=os.path.join(os.environ.get("WINDIR",r"C:\Windows"),"Fonts")
    cands=[os.path.join(fonts_dir,f) for f in ("arialbd.ttf","arial.ttf","segoeuib.ttf","segoeui.ttf","tahomabd.ttf",
           "tahoma.ttf","calibrib.ttf","calibri.ttf","davidbd.ttf","david.ttf","micross.ttf","gisha.ttf")]
    for n in ("arial","segoeui","tahoma","calibri","david","miriam","gisha","microsoftsansserif",
              "notosanshebrew","dejavusans","freesans","liberationsans"):
        for b in (True,False):
            try: cands.append(pygame.font.match_font(n,bold=b))
            except Exception: pass
    seen=set()
    for p in cands:
        if not p or p in seen or not os.path.exists(p): continue
        seen.add(p)
        if _font_has_hebrew(p): _HE_FONT_PATH=p; print("Hebrew font:",p); return p
    try:                                                    # last resort: scan every installed font
        for n in pygame.font.get_fonts():
            p=pygame.font.match_font(n)
            if p and p not in seen and os.path.exists(p):
                seen.add(p)
                if _font_has_hebrew(p): _HE_FONT_PATH=p; print("Hebrew font:",p); return p
    except Exception: pass
    _HE_FONT_PATH=""; print("WARNING: no Hebrew font found on this computer"); return ""
_GLYPH_FIX={"←":"<","→":">","◄":"<","►":">","◀":"<","▶":">","⚡":"","♥":"","♡":"","✓":"","★":"*"}
def _ascii_safe(t):
    """The default game font has no arrows/emoji (they showed as boxes) - swap or drop them."""
    if t.isascii(): return t
    t="".join(_GLYPH_FIX.get(ch,ch) for ch in t)
    return "".join(ch for ch in t if ord(ch)<0x2190 or ch in "•–—…").strip() if any(ord(ch)>=0x2190 for ch in t) else t

class TFont:
    """pygame Font wrapper: translates, and switches to a Hebrew font + RTL when needed."""
    def __init__(self, size):
        self._px=max(8,int(size)); self._f=pygame.font.SysFont(None,self._px); self._h=None
    def _hf(self):
        if self._h is None:
            path=find_hebrew_font(); sz=max(8,int(self._px*0.70))
            self._h=pygame.font.Font(path,sz) if path else pygame.font.SysFont(_HE_FONTS,sz,bold=True)
        return self._h
    def _prep(self, text):
        t=tr(str(text))
        if _HEB.search(t): return self._hf(), bidi(t)
        return self._f, _ascii_safe(t)
    def render(self, text, aa=True, color=(255,255,255), bg=None):
        f,t=self._prep(text)
        return f.render(t,aa,color) if bg is None else f.render(t,aa,color,bg)
    def size(self, text): f,t=self._prep(text); return f.size(t)
    def get_height(self): return self._f.get_height()
    def get_linesize(self): return self._f.get_linesize()
    def __getattr__(self, n): return getattr(self._f, n)

def make_fonts():
    global FONT_BIG,FONT_MED,FONT_SM,FONT_TINY
    base=min(WIDTH,HEIGHT)
    FONT_BIG =TFont(max(22,int(base*0.092)))
    FONT_MED =TFont(max(16,int(base*0.062)))
    FONT_SM  =TFont(max(13,int(base*0.040)))
    FONT_TINY=TFont(max(10,int(base*0.028)))

FONT_BIG=FONT_MED=FONT_SM=FONT_TINY=None
make_fonts()

# ── Sounds ─────────────────────────────────────────────────────────────────────
def _beep(freq=440, dur=0.08, vol=0.4, wave="sine"):
    sr=44100; n=int(sr*dur); buf=[]
    for i in range(n):
        t=i/sr
        v=math.sin(2*math.pi*freq*t) if wave=="sine" else (1.0 if math.sin(2*math.pi*freq*t)>0 else -1.0)
        fade=min(1.0,(n-i)/(sr*0.02))
        val=max(-32767,min(32767,int(v*vol*fade*32767)))
        buf+=[val&0xFF,(val>>8)&0xFF]
    return pygame.mixer.Sound(buffer=bytes(buf*2))

SND_CORRECT = _beep(660,0.12,0.5)
SND_WRONG   = _beep(180,0.22,0.6,"square")
SND_TICK    = _beep(880,0.04,0.2)
SND_BOSS    = _beep(440,0.3,0.5,"square")
SND_SELECT  = _beep(528,0.08,0.3)

# ── Music ──────────────────────────────────────────────────────────────────────
def _make_music(notes, bpm=130, vol=0.18):
    """Generate looping chiptune music."""
    sr=44100; beat=int(sr*60/bpm); buf=[]
    for freq,dur_beats in notes:
        n=int(beat*dur_beats)
        for i in range(n):
            t=i/sr
            if freq>0:
                v=math.sin(2*math.pi*freq*t)*0.7+math.sin(2*math.pi*freq*2*t)*0.2+math.sin(2*math.pi*freq*0.5*t)*0.1
            else: v=0
            fade=min(1.0, min(i/(sr*0.01),(n-i)/(sr*0.02)))
            val=max(-32767,min(32767,int(v*vol*fade*32767)))
            buf+=[val&0xFF,(val>>8)&0xFF]
    snd=pygame.mixer.Sound(buffer=bytes(buf*2))
    snd.set_volume(0.5)
    return snd

MUSIC_MENU    = _make_music([(262,.5),(294,.5),(330,.5),(349,.5),(392,.5),(349,.5),(330,.5),(294,.5)],120)
MUSIC_CLASSIC = _make_music([(330,.5),(294,.5),(262,.5),(294,.5),(330,.5),(330,.5),(330,1)],130)
