try:
    import numpy as _np
except Exception:
    _np = None

def _m_hz(n): return 440.0*2**((n-69)/12.0)

def _m_note(instr, midi, dur):
    """One note as a list (or numpy array) of floats. Includes a short release tail."""
    sr=MUSIC_SR; rel={"pad":0.45,"epiano":0.35,"bell":0.9,"pluck":0.3,"marimba":0.25,"bass":0.06,"lead":0.08,"flute":0.12}.get(instr,0.1)
    n=int((dur+rel)*sr); hz=_m_hz(midi) if midi else 0
    if _np is not None:
        t=_np.arange(n)/sr; w=2*_np.pi*hz
        if instr=="epiano": v=(_np.sin(w*t)+0.35*_np.sin(2*w*t)*_np.exp(-t*6)+0.12*_np.sin(3*w*t)*_np.exp(-t*10))*_np.exp(-t*1.8)
        elif instr=="pluck": v=(_np.sin(w*t)+0.5*_np.sin(2*w*t)*_np.exp(-t*4)+0.25*_np.sin(3*w*t)*_np.exp(-t*8))*_np.exp(-t*5.5)
        elif instr=="bell": v=_np.sin(w*t)*_np.exp(-t*2.6)+0.35*_np.sin(3*w*t)*_np.exp(-t*6)+0.18*_np.sin(4.2*w*t)*_np.exp(-t*9)
        elif instr=="marimba": v=_np.sin(w*t)*_np.exp(-t*7)+0.3*_np.sin(4*w*t)*_np.exp(-t*24)
        elif instr=="bass": v=(_np.sin(w*t)+0.28*_np.sin(2*w*t)+0.08*_np.sin(3*w*t))*(0.75+0.25*_np.exp(-t*4))
        elif instr=="pad": v=(_np.sin(w*t)+_np.sin(w*1.004*t)+_np.sin(w*0.996*t)+0.4*_np.sin(2*w*t))/3.0*_np.minimum(1,t/0.35)
        elif instr in ("lead","flute"):
            vib=1+0.004*_np.sin(2*_np.pi*5.5*t)*_np.minimum(1,_np.maximum(0,(t-0.15)/0.2)); ph=_np.cumsum(w*vib/sr)
            v=(_np.sin(ph)+0.18*_np.sin(3*ph)+0.06*_np.sin(5*ph)+0.2*_np.sin(2*ph)) if instr=="lead" else (_np.sin(ph)+0.12*_np.sin(2*ph))
            v=v*_np.minimum(1,t/(0.012 if instr=="lead" else 0.05))*(0.85+0.15*_np.exp(-t*5))
        elif instr=="kick":
            f=48+95*_np.exp(-t*32); v=_np.sin(_np.cumsum(2*_np.pi*f/sr))*_np.exp(-t*8)*1.4
        elif instr=="snare":
            rnd=_np.random.RandomState(5); x=rnd.uniform(-1,1,n); x=(x+_np.roll(x,1)+_np.roll(x,2))/3   # softer noise
            v=x*_np.exp(-t*20)*0.5+_np.sin(2*_np.pi*190*t)*_np.exp(-t*24)*0.55
        elif instr=="hat":
            rnd=_np.random.RandomState(9); x=rnd.uniform(-1,1,n); v=_np.diff(x,prepend=0)*_np.exp(-t*70)*0.12
        elif instr=="shaker":
            rnd=_np.random.RandomState(11); x=rnd.uniform(-1,1,n); v=_np.diff(x,prepend=0)*_np.minimum(1,t/0.02)*_np.exp(-t*35)*0.1
        else: v=_np.zeros(n)
        if instr not in ("kick","snare","hat","shaker"):     # note-off: smooth release after the note's length
            d=int(dur*sr); rl=_np.ones(n)
            if n>d: rl[d:]=_np.exp(-_np.arange(n-d)/sr/ (rel/4.0))
            v=v*rl*_np.minimum(1,_np.arange(n)/(sr*0.004))
        return v
    # ---- pure Python (no numpy) ----
    out=[0.0]*n; e=math.exp; s=math.sin; tp=2*math.pi; d=int(dur*sr); ph=0.0; rnd=random.Random(5); prev=0.0
    for i in range(n):
        t=i/sr; w=tp*hz
        if instr=="epiano": v=(s(w*t)+0.35*s(2*w*t)*e(-t*6))*e(-t*1.8)
        elif instr=="pluck": v=(s(w*t)+0.5*s(2*w*t)*e(-t*4))*e(-t*5.5)
        elif instr=="bell": v=s(w*t)*e(-t*2.6)+0.35*s(3*w*t)*e(-t*6)
        elif instr=="marimba": v=s(w*t)*e(-t*7)+0.3*s(4*w*t)*e(-t*24)
        elif instr=="bass": v=(s(w*t)+0.28*s(2*w*t))*(0.75+0.25*e(-t*4))
        elif instr=="pad": v=(s(w*t)+s(w*1.004*t)+0.4*s(2*w*t))/2.4*min(1,t/0.35)
        elif instr in ("lead","flute"):
            vib=1+0.004*s(tp*5.5*t)*min(1,max(0,(t-0.15)/0.2)); ph+=w*vib/sr
            v=(s(ph)+0.18*s(3*ph)+0.06*s(5*ph)+0.2*s(2*ph)) if instr=="lead" else (s(ph)+0.12*s(2*ph))
            v*=min(1,t/(0.012 if instr=="lead" else 0.05))*(0.85+0.15*e(-t*5))
        elif instr=="kick":
            ph+=tp*(48+95*e(-t*32))/sr; v=s(ph)*e(-t*8)*1.4
        elif instr=="snare": x=rnd.uniform(-1,1); v=(x+prev)/2*e(-t*20)*0.5+s(tp*190*t)*e(-t*24)*0.55; prev=x
        elif instr in ("hat","shaker"):
            x=rnd.uniform(-1,1); v=(x-prev)*(e(-t*70)*0.12 if instr=="hat" else min(1,t/0.02)*e(-t*35)*0.1); prev=x
        else: v=0.0
        if instr not in ("kick","snare","hat","shaker"):
            if i>d: v*=e(-(i-d)/sr/(rel/4.0))
            if i<88: v*=i/88
        out[i]=v
    return out

