def _render_song(sp):
    sr=MUSIC_SR; spb=60.0/sp["bpm"]; bars=len(sp["chords"]); N=int(bars*4*spb*sr)
    dry=_np.zeros(N) if _np is not None else [0.0]*N
    wet=_np.zeros(N) if _np is not None else [0.0]*N            # sent to the room / echo
    cache={}
    def add(instr,midi,beat,dur_beats,vol):
        key=(instr,midi,round(dur_beats,3))
        if key not in cache: cache[key]=_m_note(instr,midi,dur_beats*spb)
        nb=cache[key]; o=int(beat*spb*sr)%N; L=len(nb)
        for buf in ((dry,wet) if instr not in ("kick","snare","hat","shaker","bass") else (dry,)):
            if _np is not None:
                end=min(N,o+L); buf[o:end]+=nb[:end-o]*vol
                if o+L>N: buf[:o+L-N]+=nb[end-o:]*vol         # wrap the tail -> seamless loop
            else:
                for i in range(L): buf[(o+i)%N]+=nb[i]*vol
    for b,ch in enumerate(sp["chords"]):
        notes=_C[ch]; root=_ROOT[ch]; b0=b*4
        if sp.get("pad"):
            for n_ in notes[:3]: add("pad",n_,b0,4,0.06)
        if sp.get("arp"):
            for k,ix in enumerate(sp["arp"]): add(sp["comp"],notes[ix]+(12 if k>=4 and ix<2 else 0),b0+k*0.5,0.5,sp["comp_vol"])
        else:
            for st,du in sp["comp_rhythm"]:
                for n_ in notes: add(sp["comp"],n_,b0+st,du,sp["comp_vol"]/2.2)
        for st,du,iv in sp["bass"]: add("bass",root+12+iv,b0+st,du,sp["bass_vol"])
        mel=sp["mel"][b%len(sp["mel"])]
        for bt,mi,du in _mel(mel): add(sp["lead"],mi,b0+bt,du,sp["lead_vol"])
        drums=dict(sp["drums"])
        if sp.get("hat2") and b>=bars//2: drums["hat"]=sp["hat2"]
        for dn,pat in drums.items():
            for k,c in enumerate(pat):
                if c=="x": add(dn,0,b0+k*0.25,0.25,sp["drum_vol"]*(0.8 if dn=="hat" and k%4 else 1.0))
    # small room + soft echo on the music (not the drums) -> sounds like a real track, not beeps
    taps=[(0.029,.20),(0.043,.17),(0.061,.14),(0.083,.11),(0.109,.08),(0.75*spb,.16),(1.5*spb,.07)]
    if _np is not None:
        buf=dry.copy()
        for d_,g_ in taps: buf+=_np.roll(wet,int(d_*sr))*g_
    else:
        buf=dry[:]
        for d_,g_ in taps:
            k_=int(d_*sr)
            for i in range(N): buf[i]+=wet[i-k_]*g_
    # gentle limiter -> 16-bit
    if _np is not None:
        pk=float(_np.max(_np.abs(buf))) or 1.0; y=_np.tanh(buf/pk*1.2)/math.tanh(1.2)*0.6
        return (y*32767).astype(_np.int16).tobytes()
    pk=max(abs(x) for x in buf) or 1.0; th=math.tanh(1.2); out=bytearray()
    for x in buf:
        v=int(math.tanh(x/pk*1.2)/th*0.6*32767); out+=bytes((v&0xFF,(v>>8)&0xFF))
    return bytes(out)

def _music_cache_dir():
    d=os.path.join(_data_dir(),"music_cache")
    try: os.makedirs(d,exist_ok=True)
    except Exception: pass
    return d

def _music2_worker():
    import wave
    for key in ("menu","classic","boss","fall","vibe","haunt"):
        try:
            p=os.path.join(_music_cache_dir(),f"{key}_v{MUSIC_VER}.wav")
            if not os.path.exists(p):
                data=_render_song(SONGS[key]); tmp=p+".tmp"
                with wave.open(tmp,"wb") as w: w.setnchannels(1); w.setsampwidth(2); w.setframerate(MUSIC_SR); w.writeframes(data)
                os.replace(tmp,p)
            MUSIC2[key]=pygame.mixer.Sound(p); _MUSIC2_SWAP.append(key)
        except Exception as e: print("[music]",key,"->",e)


# =============================================================================
#  MUSIC 3.0 — studio-style songs made by the game itself (needs numpy; without it -> MUSIC 2.0)
#  Real song structure (verse / chorus / breakdown + drum fills), stereo, FM e-piano,
#  plucked guitar (Karplus-Strong), supersaw pads, warm bass, real-sounding drums,
#  convolution reverb, sidechain pump, soft master limiter. Rendered in the background.
# =============================================================================
M3_SR = 44100
M3_VER = 1                     # change this number -> every song is rendered again
_M3_NOTE = {"C":0,"C#":1,"Db":1,"D":2,"D#":3,"Eb":3,"E":4,"F":5,"F#":6,"Gb":6,"G":7,"G#":8,"Ab":8,"A":9,"A#":10,"Bb":10,"B":11}
def _nn(s):
    """'F#5' -> MIDI note."""
    i=2 if len(s)>2 and s[1] in "#b" else 1
    return 12*(int(s[i:])+1)+_M3_NOTE[s[:i]]
def _m3_mel(s):
    out=[]
    for p in s.split():
        n_,b_,d_=p.split(":"); out.append((float(b_),_nn(n_),float(d_)))
    return out

# ---------------- DSP helpers (numpy) ----------------
def _m3_lp(x, fc, order=2):
    """Lowpass via FFT (smooth Butterworth-like curve)."""
    if fc<=0: return x*0
    X=_np.fft.rfft(x); f=_np.fft.rfftfreq(len(x),1/M3_SR)
    X*=1/_np.sqrt(1+(f/fc)**(2*order)); return _np.fft.irfft(X,len(x))
def _m3_hp(x, fc, order=2):
    X=_np.fft.rfft(x); f=_np.fft.rfftfreq(len(x),1/M3_SR)+1e-9
    X*=1/_np.sqrt(1+(fc/f)**(2*order)); return _np.fft.irfft(X,len(x))
def _m3_bp(x, lo, hi): return _m3_hp(_m3_lp(x,hi),lo)
def _m3_saw(ph, f, bright=1.0, nmax=40):
    """Band-limited saw (additive) - no harsh aliasing."""
    v=_np.zeros_like(ph); top=min(nmax,int((M3_SR*0.45)/max(f,1)))
    for k in range(1,top+1): v+=_np.sin(k*ph)/k*(1/(1+(k*f/(4000*bright))**2))
    return v
def _m3_adsr(n, a, d, s, r, dur):
    t=_np.arange(n)/M3_SR; e=_np.ones(n)
    e=_np.where(t<a,t/max(a,1e-4),_np.where(t<a+d,1-(1-s)*(t-a)/max(d,1e-4),s))
    off=t>dur; e[off]=e[off]*_np.exp(-(t[off]-dur)/max(r/4,1e-4))
    return e
def _m3_ks(f, n, damp=0.996, bright=0.6, seed=1):
    """Karplus-Strong plucked string, 4x oversampled for exact tuning."""
    os_=4; sr=M3_SR*os_; P=max(2,int(round(sr/f-0.5))); N=n*os_+P+2
    rnd=_np.random.RandomState(seed); exc=rnd.uniform(-1,1,P)
    k=max(1,int(1+(1-bright)*6))
    for _ in range(k): exc=(exc+_np.roll(exc,1))/2
    y=_np.zeros(N); y[:P]=exc; y[P]=damp*0.5*(y[0]+exc[-1])
    st=P+1
    while st<N:
        en=min(N,st+P); y[st:en]=damp*0.5*(y[st-P:en-P]+y[st-P-1:en-P-1]); st=en
    y=y[:n*os_].reshape(n,os_).mean(axis=1)
    return y/ (_np.max(_np.abs(y[:2000]))+1e-9)

_M3_CACHE={}
def _m3_inst(name, midi, dur, vel=1.0, seed=0):
    """One note -> (L, R) arrays. Includes the release tail."""
    key=(name,midi,round(dur,4),round(vel,2),seed%4)
    if key in _M3_CACHE: return _M3_CACHE[key]
    f=440.0*2**((midi-69)/12.0) if midi else 0.0
    rel={"ep":0.6,"pad":0.9,"strings":0.7,"guitar":1.2,"pluck":0.35,"bell":1.6,"musicbox":1.4,"bass":0.12,"sub":0.12,
         "lead":0.18,"flute":0.2,"stab":0.25,"arp":0.12,"pizz":0.4}.get(name,0.4)
    n=int((dur+rel)*M3_SR); t=_np.arange(n)/M3_SR; w=2*_np.pi*f; L=R=None
    if name=="ep":                                                    # FM electric piano (Rhodes-like)
        I=1.4*_np.exp(-t*3.5)*vel+0.25
        v=_np.sin(w*t+I*_np.sin(w*t))+0.18*_np.sin(14*w*t)*_np.exp(-t*40)+0.12*_np.sin(2*w*t+0.5*_np.sin(w*t))*_np.exp(-t*2)
        v*=_m3_adsr(n,0.003,1.6,0.35,rel,dur)*_np.exp(-t*0.6)
        trem=0.12*_np.sin(2*_np.pi*4.2*t); L=v*(1+trem); R=v*(1-trem)
    elif name in ("pad","strings"):                                   # detuned saws, chorus -> wide stereo
        L=_np.zeros(n); R=_np.zeros(n)
        dets=(-0.11,-0.05,0.0,0.06,0.12) if name=="pad" else (-0.07,0.0,0.08)
        for j,d in enumerate(dets):
            fr=f*2**(d/12); vib=1+0.003*_np.sin(2*_np.pi*(5.0+j*0.3)*t+j) if name=="strings" else _np.ones(n)
            ph=_np.cumsum(2*_np.pi*fr*vib/M3_SR)+j*1.3
            s=_m3_saw(ph,fr,0.6 if name=="pad" else 0.9,24)
            pan=(j/(len(dets)-1))*2-1; L+=s*(1-pan*0.7); R+=s*(1+pan*0.7)
        L=_m3_lp(L,2600 if name=="pad" else 4200); R=_m3_lp(R,2600 if name=="pad" else 4200)
        e=_m3_adsr(n,0.45 if name=="pad" else 0.18,0.3,0.85,rel,dur)/len(dets); L*=e; R*=e
    elif name=="guitar":                                              # plucked nylon/steel string
        v=_m3_ks(f,n,0.9965 if f<300 else 0.994,0.55,seed+midi); v=_m3_lp(v,4200)
        v*=_m3_adsr(n,0.001,0.1,1,rel,dur+0.4)
    elif name=="pizz":
        v=_m3_lp(_m3_ks(f,n,0.985,0.5,seed+midi),3800)*_m3_adsr(n,0.001,0.1,1,rel,dur)
    elif name=="pluck":                                               # bright synth pluck
        ph=w*t; v=_m3_saw(ph,f,1.0,30); v=_m3_lp(v,2200)*0.6+_m3_lp(v,7000)*_np.exp(-t*30)*0.4
        v*=_np.exp(-t*6)*_m3_adsr(n,0.002,0.1,1,rel,dur)
    elif name in ("bell","musicbox"):                                 # FM bell / music box
        ratio=3.5 if name=="bell" else 4.0; idx=(1.5 if name=="bell" else 1.1)*min(1.0,700/max(f,1))**0.5   # softer on high notes
        v=_np.sin(w*t+idx*_np.exp(-t*4)*_np.sin(w*ratio*t))*_np.exp(-t*(1.6 if name=="bell" else 2.6))
        v+=0.25*_np.sin(2*w*t)*_np.exp(-t*5)
        v=_m3_lp(v,5500)*_m3_adsr(n,0.002,0.1,1,rel,dur+0.8)
    elif name=="bass":                                                # warm synth bass (sub + soft saw)
        ph=w*t; v=_np.sin(ph)*0.6+_m3_lp(_m3_saw(ph,f,1,20),1400)*0.5
        v*=_m3_adsr(n,0.004,0.25,0.75,rel,dur)
    elif name=="sub":
        v=0.7*_np.sin(w*t)+0.25*_np.sin(2*w*t)+0.08*_np.sin(3*w*t); v*=_m3_adsr(n,0.006,0.3,0.85,rel,dur)
    elif name=="lead":                                                # singing saw lead with vibrato
        vib=1+0.0045*_np.sin(2*_np.pi*5.6*t)*_np.clip((t-0.18)/0.25,0,1)
        L=_np.zeros(n); R=_np.zeros(n)
        for d,p in ((-0.06,-0.5),(0.0,0.0),(0.07,0.5)):
            ph=_np.cumsum(2*_np.pi*f*2**(d/12)*vib/M3_SR); s=_m3_saw(ph,f,0.8,22)
            L+=s*(1-p); R+=s*(1+p)
        e=_m3_adsr(n,0.012,0.2,0.8,rel,dur)/3; L=_m3_lp(L,3400)*e; R=_m3_lp(R,3400)*e
    elif name=="flute":
        vib=1+0.004*_np.sin(2*_np.pi*5.0*t)*_np.clip((t-0.2)/0.3,0,1); ph=_np.cumsum(w*vib/M3_SR)
        rnd=_np.random.RandomState(3); br=_m3_bp(rnd.uniform(-1,1,n),f*0.9,f*3)*0.06
        v=(_np.sin(ph)+0.22*_np.sin(2*ph)+0.06*_np.sin(3*ph)+br)*_m3_adsr(n,0.07,0.2,0.85,rel,dur)
    elif name=="stab":                                                # string/brass stab
        ph=w*t; v=_m3_lp(_m3_saw(ph,f,1,30),3000)*_m3_adsr(n,0.005,0.15,0.5,rel,dur)
    elif name=="arp":
        ph=w*t; v=(_np.sin(ph)+_np.sin(3*ph)/3+_np.sin(5*ph)/5*0.6)*_np.exp(-t*9)*_m3_adsr(n,0.002,0.05,1,rel,dur)
    # ---------------- drums ----------------
    elif name=="kick":
        n=int(0.45*M3_SR); t=_np.arange(n)/M3_SR
        fq=46+110*_np.exp(-t*28); v=_np.sin(_np.cumsum(2*_np.pi*fq/M3_SR))*_np.exp(-t*7.5)
        rnd=_np.random.RandomState(1); v+=_m3_lp(rnd.uniform(-1,1,n),3500)*_np.exp(-t*180)*0.35
        v=_np.tanh(v*1.6)*vel
    elif name=="snare":
        n=int(0.35*M3_SR); t=_np.arange(n)/M3_SR; rnd=_np.random.RandomState(2)
        nz=_m3_bp(rnd.uniform(-1,1,n),1200,9000)*_np.exp(-t*16)
        tone=(_np.sin(2*_np.pi*185*t)+0.5*_np.sin(2*_np.pi*330*t))*_np.exp(-t*25)
        v=(nz*0.75+tone*0.55)*vel
    elif name=="clap":
        n=int(0.4*M3_SR); t=_np.arange(n)/M3_SR; rnd=_np.random.RandomState(4)
        nz=_m3_bp(rnd.uniform(-1,1,n),900,6000); env=_np.zeros(n)
        for o in (0.0,0.011,0.022): env+=_np.where(t>=o,_np.exp(-(t-o)*120),0)*(t>=o)
        env+=_np.where(t>=0.03,_np.exp(-(t-0.03)*18),0)*0.6
        v=nz*env*0.7*vel
    elif name=="rim":
        n=int(0.12*M3_SR); t=_np.arange(n)/M3_SR
        v=(_np.sin(2*_np.pi*1700*t)*0.5+_np.sin(2*_np.pi*820*t))*_np.exp(-t*60)*0.5*vel
    elif name in ("hat","ohat","shaker","crash"):
        ln={"hat":0.08,"ohat":0.45,"shaker":0.12,"crash":2.2}[name]; n=int(ln*M3_SR); t=_np.arange(n)/M3_SR
        rnd=_np.random.RandomState({"hat":5,"ohat":6,"shaker":7,"crash":8}[name]); nz=rnd.uniform(-1,1,n)
        if name=="hat": v=_m3_bp(nz,7000,12500)*_np.exp(-t*55)*0.55
        elif name=="ohat": v=_m3_bp(nz,6000,12500)*_np.exp(-t*7)*0.42
        elif name=="shaker": v=_m3_bp(nz,4000,11000)*_np.clip(t/0.025,0,1)*_np.exp(-t*30)*0.35
        else:
            v=_m3_bp(nz,4000,12000)*_np.exp(-t*2.2)*0.45
            v+=_np.sin(2*_np.pi*f*t)*0 if f else 0
        v*=vel
    elif name=="tom":
        n=int(0.4*M3_SR); t=_np.arange(n)/M3_SR; fq=f*(1+0.5*_np.exp(-t*20))
        v=_np.sin(_np.cumsum(2*_np.pi*fq/M3_SR))*_np.exp(-t*9)*vel
    elif name=="riser":                                               # white-noise build-up + rising tone (DASH songs)
        n=int(dur*M3_SR); t=_np.arange(n)/M3_SR; k=t/max(1e-6,dur)
        rnd=_np.random.RandomState(11+seed); nz=rnd.uniform(-1,1,n)
        lo=_m3_hp(_m3_lp(nz,1400),250); hi=_m3_hp(nz,3500)
        v=(lo*(1-k)+hi*k)*(k**2)*0.55+_np.sin(_np.cumsum(2*_np.pi*(f*(1+3*k**2))/M3_SR))*(k**3)*0.14
        L=v; R=_np.roll(v,int(0.011*M3_SR))
    else: v=_np.zeros(n)
    if L is None: L=R=v*vel if name not in ("kick","snare","clap","rim","hat","ohat","shaker","crash","tom") else v
    _M3_CACHE[key]=(L,R); return L,R

