def _up(mel):                                       # the same tune, one octave up (for the big drop)
    out = []
    for line in mel:
        notes = []
        for p in line.split():
            n_, b_, d_ = p.split(":"); i = 2 if len(n_) > 2 and n_[1] in "#b" else 1
            notes.append(f"{n_[:i]}{int(n_[i:]) + 1}:{b_}:{d_}")
        out.append(" ".join(notes))
    return out
