def _m3_render(song):
    sp=SONGS3[song]; bpm=sp["bpm"]; spb=60.0/bpm; sr=M3_SR
    bars=sum(len(s["chords"]) for s in sp["sections"]); N=int(round(bars*4*spb*sr))
    dry=_np.zeros((2,N)); rv=_np.zeros((2,N)); duck=_np.zeros((2,N)); kicks=[]
    def put(name, midi, beat, dur_b, vol, buf="dry", pan=None, seed=0):
        if vol<=0: return
        L,R=_m3_inst({"riff":"arp"}.get(name,name),midi,dur_b*spb,1.0,seed)
        p=M3_PAN.get(name,0.0) if pan is None else pan
        gl=vol*min(1,1-p); gr=vol*min(1,1+p)
        o=int(round(beat*spb*sr))%N; ln=len(L); tgt=duck if buf=="duck" else dry
        for ch,(sig,g) in enumerate(((L,gl),(R,gr))):
            e=min(N,o+ln); tgt[ch,o:e]+=sig[:e-o]*g
            if o+ln>N: tgt[ch,:o+ln-N]+=sig[e-o:e-o+(o+ln-N)]*g      # wrap the tail -> perfect loop
            s=M3_SEND.get(name,0.0)
            if s:
                rv[ch,o:e]+=sig[:e-o]*g*s
                if o+ln>N: rv[ch,:o+ln-N]+=sig[e-o:e-o+(o+ln-N)]*g*s
    sw=sp.get("swing",0.0)
    def step_beat(b0,k): return b0+k*0.25+(sw if k%2 else 0)
    bar=0; side_amt=_np.zeros(N)
    for si,sec in enumerate(sp["sections"]):
        Ly=sec["layers"]; nb=len(sec["chords"])
        for bi,ch in enumerate(sec["chords"]):
            b0=bar*4; notes=M3_CH[ch]; root=M3_ROOT[ch]; last=(bi==nb-1); first=(bi==0)
            if Ly.get("side"): side_amt[int(b0*spb*sr):int((b0+4)*spb*sr)]=Ly["side"]
            # ---- harmony ----
            if Ly.get("ep"):
                for st,du in ((0,1.5),(1.5,1.0),(2.75,1.25)):
                    for j,n_ in enumerate(notes): put("ep",n_,b0+st+j*0.012,du,Ly["ep"]*(0.33 if st==0 else 0.26),"duck",seed=j)
            if Ly.get("ep_stab"):
                for st in (0.5,1.5,2.5,3.5) if bi%2==0 else (0.5,1.5,2.75,3.5):
                    for j,n_ in enumerate(notes): put("ep",n_,b0+st,0.3,Ly["ep_stab"]*0.3,"duck",seed=j)
            for nm in ("pad","supersaw","strings"):
                if Ly.get(nm):
                    for j,n_ in enumerate(notes[:3]+[notes[0]-12]): put("pad" if nm!="strings" else "strings",n_,b0,4,Ly[nm]*(0.7 if nm=="supersaw" else 0.5),"duck")
            if Ly.get("stab"):
                for st in (0,0.75,1.5,3.0):
                    for n_ in notes[:3]: put("stab",n_,b0+st,0.3,Ly["stab"]*0.35)
            if Ly.get("guitar_arp"):
                g=M3_GTR.get(ch,[n_-12 for n_ in notes]+[notes[0]]); pat=[0,2,3,4,1,3,4,2]
                for k,ix in enumerate(pat): put("guitar",g[ix],b0+k*0.5,0.5,Ly["guitar_arp"],seed=k)
            if Ly.get("guitar_pick"):
                g=M3_GTR.get(ch); pat=[0,2,4,3,1,2,4,3]
                for k,ix in enumerate(pat): put("guitar",g[ix],b0+k*0.5+(0.01*k%3),0.5,Ly["guitar_pick"]*(1.0 if k in (0,4) else 0.8),seed=k)
            if Ly.get("pizz_arp"):
                g=M3_GTR.get(ch); pat=[0,2,3,4,3,2,1,2]
                for k,ix in enumerate(pat): put("pizz",g[ix]+12,b0+k*0.5,0.5,Ly["pizz_arp"],seed=k)
            if Ly.get("arp16"):
                seq=notes+[notes[1]+12,notes[2]+12,notes[1]+12,notes[0]+12]
                for k in range(16): put("arp",seq[k%8]+12,b0+k*0.25,0.25,Ly["arp16"]*(1 if k%4==0 else 0.7))
            # ---- bass ----
            if Ly.get("sub"):
                for st,du,iv in ((0,1.5,0),(1.5,0.5,0),(2,1.5,7),(3.5,0.5,12)): put("sub",root+iv,b0+st,du,Ly["sub"],"duck")
            if Ly.get("bass8"):
                for k in range(8): put("bass",root+(12 if k%2 else 0)+(7 if k==6 and bi%2 else 0),b0+k*0.5,0.45,Ly["bass8"]*0.7,"duck")
            if Ly.get("bass16"):
                for k in range(16): put("bass",root+(12 if k%4==2 else 0),b0+k*0.25,0.22,Ly["bass16"]*0.55*(1 if k%4==0 else 0.75),"duck")
            if Ly.get("bass_off"):
                for k in range(4): put("bass",root+(12 if k==3 else 0),b0+k+0.5,0.4,Ly["bass_off"]*0.65,"duck")
            # ---- melodies ----
            mi=sec["mel"][bi%len(sec["mel"])] if sec["mel"] else ""
            for key_ in ("bell","musicbox","flute","lead","pluck","riff"):
                if Ly.get(key_) and mi:
                    for bt,m_,du in _m3_mel(mi): put(key_,m_,b0+bt,du,Ly[key_])
            if sec["mel2"]:
                for bt,m_,du in _m3_mel(sec["mel2"][bi%len(sec["mel2"])]):
                    put("strings" if song!="vibe" else "bell",m_,b0+bt,du,0.16 if song!="vibe" else 0.14)
            if Ly.get("riser") and bi==max(0,nb-2): put("riser",60,b0,8,Ly["riser"])     # the build-up before a drop
            # ---- drums ----
            kit=M3_DRUMS.get(Ly.get("drums",""),{})
            for dn,pat in kit.items():
                for k,c in enumerate(pat):
                    if c!="x": continue
                    if last and sec["fill"] and k>=12 and dn in ("hat","snare","clap","ohat","rim"): continue
                    v={"kick":0.6,"snare":0.6,"clap":0.5,"hat":0.42,"ohat":0.34,"shaker":0.36,"rim":0.4}.get(dn,0.4)
                    if dn in ("hat","shaker") and k%4: v*=0.6
                    put(dn,0,step_beat(b0,k),0.25,v)
                    if dn=="kick": kicks.append(int(step_beat(b0,k)*spb*sr)%N)
            if last and sec["fill"] and kit:
                for k,(nm,mi_,v) in enumerate((("snare",0,.45),("snare",0,.5),("tom",50,.5),("tom",45,.55))):
                    put(nm,mi_,b0+3+k*0.25,0.25,v)
            if first and sec["crash"] and kit and "kick" in kit: put("crash",0,b0,2,0.32)
            bar+=1
    # ---- sidechain "pump" from the kick ----
    tt=_np.arange(int(0.32*sr))/sr; curve=1-_np.exp(-tt/0.09); full=_np.ones(N)
    for kpos in kicks:
        e=min(N,kpos+len(curve)); full[kpos:e]=_np.minimum(full[kpos:e],curve[:e-kpos])
    pump=1-side_amt*(1-full)
    mix=dry+duck*pump
    # ---- convolution reverb (circular -> the tail wraps into the loop start) ----
    rl=int(2.4*sr); t=_np.arange(rl)/sr; rnd=_np.random.RandomState(42)
    ir=[]
    for ch in range(2):
        x=rnd.uniform(-1,1,rl)*_np.exp(-t*3.2); x=_m3_lp(x,6500); x[:int(0.012*sr)]=0
        for d,g in ((0.013,0.5),(0.021,0.35),(0.034,0.28),(0.047,0.2)): x[int((d+ch*0.003)*sr)]+=g
        ir.append(x/_np.sqrt(_np.sum(x**2)))
    wet=_np.zeros((2,N))
    for ch in range(2):
        h=_np.zeros(N); h[:min(rl,N)]=ir[ch][:min(rl,N)]
        src=rv[ch]
        wet[ch]=_np.fft.irfft(_np.fft.rfft(src)*_np.fft.rfft(h),N)
    out=mix+wet*sp["rev"]*4.0
    # ---- master: low cut, gentle high shelf, soft limiter ----
    for ch in range(2):                                # low cut + "air": tilt the mix brighter, tame the mud
        X=_np.fft.rfft(out[ch]); f=_np.fft.rfftfreq(N,1/sr)+1e-9
        X*=1/_np.sqrt(1+(32/f)**2)                                        # rumble cut
        X*=1-0.35*_np.exp(-((_np.log2(f/180))**2)/0.5)                     # -4 dB around 180 Hz (mud)
        X*=1+0.6/(1+(3500/f)**2)                                          # +4 dB high shelf from 3.5 kHz
        X*=1/_np.sqrt(1+(f/15000)**4)                                     # no harsh fizz at the very top
        out[ch]=_np.fft.irfft(X,N)
    rms=_np.sqrt(_np.mean(out**2))+1e-9; out*=0.16/rms
    out=_np.tanh(out*1.25)/1.25
    pk=_np.max(_np.abs(out)); out*=min(1.0,0.8/pk)
    return (out.T*32767).astype(_np.int16)

def _music3_worker():
    """Render all songs (menu first). Without numpy: the MUSIC 2.0 songs."""
    if _np is None: return _music2_worker()
    import wave
    for key in ("menu","classic","boss","fall","vibe","haunt","dsh1","dsh2","dsh3","dsh4","osd"):
        try:
            cp=os.path.join(_music_cache_dir(),f"{key}_m3v{M3_VER}.wav")
            if os.path.exists(cp):                            # rendered on an earlier launch -> instant
                MUSIC2[key]=pygame.mixer.Sound(cp); _MUSIC2_SWAP.append(key); continue
            a=_m3_render(key); _M3_CACHE.clear()
            try:
                with wave.open(cp+".tmp","wb") as w: w.setnchannels(2); w.setsampwidth(2); w.setframerate(M3_SR); w.writeframes(_np.ascontiguousarray(a).tobytes())
                os.replace(cp+".tmp",cp)
            except Exception as e: print("[music3] cache:",e)
            ini=pygame.mixer.get_init()
            if ini and ini[0]==M3_SR and ini[2]==2 and abs(ini[1])==16:
                MUSIC2[key]=pygame.mixer.Sound(buffer=_np.ascontiguousarray(a).tobytes())
            else:                                             # unusual sound card setup -> let pygame convert a .wav
                import wave; p=os.path.join(_music_cache_dir(),f"{key}_m3.wav")
                with wave.open(p,"wb") as w: w.setnchannels(2); w.setsampwidth(2); w.setframerate(M3_SR); w.writeframes(_np.ascontiguousarray(a).tobytes())
                MUSIC2[key]=pygame.mixer.Sound(p)
            _MUSIC2_SWAP.append(key)
        except Exception as e:
            print("[music3]",key,"->",e)

def music2_start():
    threading.Thread(target=_music3_worker,daemon=True).start()

GAME_MUSIC_STATES = ("playing","ranked_game","mp_game","tournament_game","flow","timeline_playing","training")
def music_pump(state):
    """Every frame: swap in a new song when it's ready, and use the game song while playing."""
    global _cur_music
    while _MUSIC2_SWAP:
        k=_MUSIC2_SWAP.pop(0)
        if _cur_music==k: _cur_music=None; play_music(k)
    if state in GAME_MUSIC_STATES and _cur_music=="menu": play_music("classic")
    elif _cur_music in ("classic","boss") and state not in GAME_MUSIC_STATES and state not in ("boss","countdown","pause","paused"): play_music("menu")

def play_music(key):
    global _cur_music
    if _cur_music == key: return
    pygame.mixer.stop()
    try: pygame.mixer.music.stop()
    except Exception: pass
    vol = globals()["gd"].get("music_volume", 0.8) if "gd" in globals() else 0.8   # (was dir() -> always 0.8: the bug)
    tracks = {"menu":MUSIC_MENU,"classic":MUSIC_CLASSIC,"boss":MUSIC_BOSS,"summer":MUSIC_SUMMER}
    if "MUSIC_FALL" in globals(): tracks["fall"]=MUSIC_FALL
    if "MUSIC_VIBE" in globals(): tracks["vibe"]=MUSIC_VIBE
    if "MUSIC_HAUNT" in globals(): tracks["haunt"]=MUSIC_HAUNT
    if "MUSIC2" in globals(): tracks.update(MUSIC2)          # the new songs, as soon as they're ready
    if "SONGS3" in globals() and key in SONGS3 and key not in MUSIC2 and _np is not None:
        _cur_music=key; return                                 # still rendering: a moment of quiet, not the old beeps
    if key in tracks:
        tracks[key].set_volume(vol * 0.5)
        tracks[key].play(-1)
    _cur_music = key

def stop_music():
    global _cur_music
    pygame.mixer.stop()
    _cur_music = None

def update_music_volume():
    """Apply the saved Music + Sound effects volume to EVERYTHING (call it whenever the volume or the save changes)."""
    vol = gd.get("music_volume", 0.8); sfx = gd.get("sfx_volume", 0.8)
    try:
        if str(_cur_music)=="haunt_file": pygame.mixer.music.set_volume(min(1.0,vol*0.9))
        elif str(_cur_music)=="other_file": pygame.mixer.music.set_volume(min(1.0,vol*0.6))
        elif str(_cur_music).startswith("haunt_"): pygame.mixer.music.set_volume(min(1.0,vol*0.7))
    except Exception: pass
    g=globals()
    for k,v in list(g.items()):
        if not isinstance(v,pygame.mixer.Sound): continue
        if k.startswith("MUSIC_"): v.set_volume(vol*0.5)          # every music loop (menu, boss, fall, vibe, haunt...)
        elif k.startswith("SND_"): v.set_volume(sfx)               # every sound effect
    for v in globals().get("MUSIC2",{}).values(): v.set_volume(vol*0.5)

# ── Particles ──────────────────────────────────────────────────────────────────
particles = []
def spawn_particles(x,y,color,count=20):
    for _ in range(count):
        a=random.uniform(0,2*math.pi); sp=random.uniform(2,9)
        particles.append({"x":x,"y":y,"vx":math.cos(a)*sp,"vy":math.sin(a)*sp,
                          "color":color,"life":random.randint(20,45),"size":random.randint(3,8)})
def draw_particles(surf):
    dead=[]
    for p in particles:
        p["x"]+=p["vx"]; p["y"]+=p["vy"]; p["vy"]+=0.2; p["life"]-=1
        al=max(0,p["life"]/45); r,g,b=p["color"]
        pygame.draw.circle(surf,(int(r*al),int(g*al),int(b*al)),(int(p["x"]),int(p["y"])),max(1,int(p["size"]*al)))
        if p["life"]<=0: dead.append(p)
    for p in dead: particles.remove(p)

# ── Screen shake ───────────────────────────────────────────────────────────────
shake_timer=0; shake_amount=0
def start_shake(a=8,d=18):
    global shake_timer,shake_amount; shake_timer=d; shake_amount=a
def get_shake():
    global shake_timer
    if shake_timer>0: shake_timer-=1; return (random.randint(-shake_amount,shake_amount),random.randint(-shake_amount,shake_amount))
    return (0,0)

# ── Button ─────────────────────────────────────────────────────────────────────
class Button:
    def __init__(self,x,y,w,h,text,color=(70,70,110)):
        self.x=x;self.y=y;self.w=w;self.h=h;self.text=text;self.color=color;self.hover=False
        self._cx_rel=None; self._cy_rel=None
    @property
    def rect(self): return pygame.Rect(self.x,self.y,self.w,self.h)
    def draw(self,surf):
        if "halloween_theme" in globals() and halloween_theme():
            _ht_pill(surf,"btn_%d_%d"%(self.x,self.y),self.rect,self.text,self.color,0.016,pygame.mouse.get_pos()); return
        _col=gold_col(self.color) if ("gold_theme" in globals() and gold_theme()) else (winter_col(self.color) if ("winter_theme" in globals() and winter_theme()) else (retro86_col(self.color) if ("retro86_theme" in globals() and retro86_theme()) else self.color))
        c=tuple(min(255,v+40) for v in _col) if self.hover else _col
        pygame.draw.rect(surf,c,self.rect,border_radius=12)
        pygame.draw.rect(surf,WHITE,self.rect,2,border_radius=12)
        s=FONT_SM.render(self.text,True,WHITE); surf.blit(s,s.get_rect(center=self.rect.center))
    def update(self,mouse): self.hover=self.rect.collidepoint(mouse)
    def clicked(self,ev): return ev.type==pygame.MOUSEBUTTONDOWN and ev.button==1 and self.rect.collidepoint(ev.pos)

def mk(x,y,w,h,text,color=(70,70,110)): return Button(x-w//2,y-h//2,w,h,text,color)

# ── Data / Save ────────────────────────────────────────────────────────────────
def _data_dir():
    """Where the save lives. As a script: next to color_rush.py. As an EXE/MSIX: in AppData
    (PyInstaller runs the game from a temp folder that is deleted when the game closes)."""
    if getattr(sys,"frozen",False):
        base=os.environ.get("LOCALAPPDATA") or os.environ.get("APPDATA") or os.path.expanduser("~")
        d=os.path.join(base,"ManStudio","ColorUnderPressure")
        try: os.makedirs(d,exist_ok=True); return d
        except Exception: return os.path.dirname(os.path.abspath(sys.executable))
    return os.path.dirname(os.path.abspath(__file__))
DATA_FILE = os.path.join(_data_dir(),"gamedata.json")
if getattr(sys,"frozen",False) and not os.path.exists(DATA_FILE):      # bring an old save along if there is one
    try:
        _old=os.path.join(os.path.dirname(os.path.abspath(sys.executable)),"gamedata.json")
        if os.path.exists(_old):
            import shutil; shutil.copy(_old,DATA_FILE)
    except Exception: pass
# ── CRASH LOG ────────────────────────────────────────────────────────────────
# Packaged as an EXE/MSIX the game runs with no console, so an error just closes
# the window and nobody ever sees why. Everything that goes wrong is written here.
CRASH_FILE = os.path.join(_data_dir(),"crash.txt")
LOG_FILE   = os.path.join(_data_dir(),"log.txt")
_LOGGED=set()

def _scrub(text):
    """Players are asked to copy the crash report and send it in. Tracebacks are
    full of paths like C:\\Users\\<their real name>\\... - take the name out."""
    try:
        import re as _r
        home = os.path.expanduser("~")
        user = os.path.basename(home.rstrip("\\/")) or ""
        if user and len(user) > 1:
            text = _r.sub(_r.escape(user), "<user>", text, flags=_r.IGNORECASE)
        text = _r.sub(r"([A-Za-z]:\\Users\\)[^\\\r\n\"\']+", r"\1<user>", text)
        text = _r.sub(r"(/(?:home|Users)/)[^/\r\n\"\']+", r"\1<user>", text)
    except Exception: pass
    return text

def log_problem(where, exc=None, fatal=False):
    """Append one problem to crash.txt. Never raises."""
    try:
        import traceback as _tb, datetime as _dtm
        key=(str(where),type(exc).__name__ if exc else "",str(exc)[:90] if exc else "")
        if not fatal and key in _LOGGED: return
        _LOGGED.add(key)
        with open(CRASH_FILE,"a",encoding=("utf-8-sig" if not os.path.exists(CRASH_FILE) else "utf-8")) as f:
            f.write("\n"+"="*70+"\n")
            f.write("%s  %s\n"%(_dtm.datetime.now().strftime("%Y-%m-%d %H:%M:%S"),"CRASH" if fatal else "problem"))
            f.write("where   : %s\n"%where)
            f.write("version : %s\n"%GAME_VERSION)
            f.write("build   : %s  frozen=%s  python=%s\n"%(BUILD_PLATFORM if "BUILD_PLATFORM" in globals() else "?",
                                                             getattr(sys,"frozen",False),sys.version.split()[0]))
            try: f.write("pygame  : %s  sdl=%s\n"%(pygame.version.ver,".".join(str(x) for x in pygame.get_sdl_version())))
            except Exception: pass
            if exc is not None:
                f.write(_scrub("".join(_tb.format_exception(type(exc),exc,exc.__traceback__))))
            else:
                f.write(_scrub(_tb.format_exc()))
    except Exception:
        pass

# ── WATCHDOG ─────────────────────────────────────────────────────────────────
# A freeze is not an error: no exception is raised, so nothing can catch it.
# This thread watches the heartbeat of the main loop. If a frame has not
# finished for 6 seconds, it writes the stack of EVERY thread to crash.txt -
# which says exactly which line the game is stuck on.
_HB={"t":0.0,"where":"?","dumped":0.0,"n":0}

def _watchdog():
    import traceback as _tb, datetime as _dtm
    while True:
        time.sleep(0.4)
        try:
            if _HB["t"]<=0: continue
            late=time.time()-_HB["t"]
            if late<3.0 or time.time()-_HB["dumped"]<12: continue
            _HB["dumped"]=time.time(); _HB["n"]+=1
            with open(CRASH_FILE,"a",encoding=("utf-8-sig" if not os.path.exists(CRASH_FILE) else "utf-8")) as f:
                f.write("\n"+"="*70+"\n")
                f.write("%s  FROZEN\n"%_dtm.datetime.now().strftime("%Y-%m-%d %H:%M:%S"))
                f.write("stuck for : %.1f seconds\n"%late)
                f.write("screen    : %s\n"%_HB["where"])
                f.write("version   : %s   frozen=%s\n"%(GAME_VERSION,bool(getattr(sys,"frozen",False))))
                for tid,frame in sys._current_frames().items():
                    f.write("\n--- thread %s%s ---\n"%(tid," (MAIN)" if tid==_HB.get("main") else ""))
                    f.write(_scrub("".join(_tb.format_stack(frame))[-2600:]))
        except Exception:
            pass

def _start_watchdog():
    try:
        _HB["main"]=threading.get_ident(); _HB["t"]=time.time()
        threading.Thread(target=_watchdog,daemon=True).start()
    except Exception: pass

_LOG_FH=None
def _tee_output():
    """Keep print(), warnings and hard crashes in log.txt (an EXE has no console)."""
    global _LOG_FH
    try:
        _LOG_FH=open(LOG_FILE,"a",encoding="utf-8",buffering=1)
        _LOG_FH.write("\n--- started %s  v%s  frozen=%s ---\n"%(
            time.strftime("%Y-%m-%d %H:%M:%S"),GAME_VERSION,bool(getattr(sys,"frozen",False))))
        if getattr(sys,"frozen",False):
            sys.stdout=_LOG_FH; sys.stderr=_LOG_FH
    except Exception: _LOG_FH=None
    try:
        import faulthandler
        if _LOG_FH is not None:
            faulthandler.enable(file=_LOG_FH,all_threads=True)   # hard crashes (access violation)
            _HB["fh"]=faulthandler                               # armed per frame, see _hb_arm
    except Exception: pass

def _hb_arm():
    """Re-arm the C watchdog. If the NEXT 2 seconds pass without this being
    called again, faulthandler dumps the stack - even from inside SDL."""
    fh=_HB.get("fh")
    if fh is None: return
    try:
        fh.cancel_dump_traceback_later()
        fh.dump_traceback_later(3.5,repeat=False,exit=False,file=_LOG_FH)
    except Exception: _HB["fh"]=None

