LEGACY_FILE = os.path.join(_data_dir(),"gamedata_old_progress.json")
def _acct_backup_file(uid): return os.path.join(_data_dir(),f"account_backup_{''.join(ch for ch in str(uid) if ch.isalnum())}.json")
def save_account_backup(uid, data):
    """Safety net: a copy of the account's progress on this computer (no login token inside)."""
    if not uid: return
    try:
        out={k:v for k,v in data.items() if k!="cloud_login"}
        with open(_acct_backup_file(uid),"w",encoding="utf-8") as f: json.dump(out,f)
    except Exception: pass
def load_account_backup(uid):
    try:
        with open(_acct_backup_file(uid),encoding="utf-8") as f: d=json.load(f)
        return d if isinstance(d,dict) else None
    except Exception: return None
