OTHER_BADGE_IDS = ("night_rider","lights_on","through_the_gate","outran_it","back_home")

def _fresh_gd(): return json.loads(json.dumps(_DEF))

def _has_progress(d):
    if not isinstance(d,dict): return False
    st=d.get("stats",{}) or {}
    return bool(d.get("coins",0) or st.get("games_played",0) or st.get("total_correct",0) or d.get("rank_points",0)
                or d.get("pass_xp",0) or len(d.get("unlocked_skins",[]) or [])>1)

def _load_legacy():
    try:
        with open(LEGACY_FILE,encoding="utf-8") as f: d=json.load(f)
        return d if isinstance(d,dict) else {}
    except Exception: return {}

def _stash_legacy(d):
    """Keep progress from before accounts so it can be moved into a new account. Returns True if it is safe."""
    try:
        if os.path.exists(LEGACY_FILE): return True
        snap={k:v for k,v in d.items() if k!="cloud_login"}
        with open(LEGACY_FILE,"w",encoding="utf-8") as f: json.dump(snap,f,indent=2)
        return True
    except Exception: return False

def load_gd():
    try:
        with open(DATA_FILE,encoding="utf-8") as f: d=json.load(f)
        if not isinstance(d,dict): d={}
    except Exception: d={}
    if not d.get("cloud_login") and _has_progress(d) and _stash_legacy(d):   # old save without an account
        d={k:d[k] for k in DEVICE_KEYS if k in d}
        try:
            with open(DATA_FILE,"w",encoding="utf-8") as f: json.dump(d,f,indent=2)
        except Exception: pass
    for k,v in _DEF.items():
        if k not in d: d[k]=json.loads(json.dumps(v))
    if not d.get("cloud_login"): d["player_name"]="Guest"
    return d

def save_gd(d):
    try:
        d["_saved_at"]=time.time()
        out=d if d.get("cloud_login") else {k:d[k] for k in DEVICE_KEYS if k in d}   # guest: only settings are saved
        with open(DATA_FILE,"w",encoding="utf-8") as f: json.dump(out,f,indent=2)
        if "_cloud" in globals(): _cloud["dirty"]=True
    except: pass

