def _make_beep(freq, dur, vol=0.6):
    sr=44100; n=int(sr*dur); buf=[]
    for i in range(n):
        t=i/sr; v=math.sin(2*math.pi*freq*t)
        fade=min(1.0,min(i/(sr*0.01),(n-i)/(sr*0.02)))
        val=max(-32767,min(32767,int(v*vol*fade*32767)))
        buf+=[val&0xFF,(val>>8)&0xFF]
    return pygame.mixer.Sound(buffer=bytes(buf*2))

def _make_static(dur=0.5, vol=0.15):
    sr=44100; n=int(sr*dur); buf=[]
    for i in range(n):
        v=random.uniform(-1,1)
        val=max(-32767,min(32767,int(v*vol*32767)))
        buf+=[val&0xFF,(val>>8)&0xFF]
    return pygame.mixer.Sound(buffer=bytes(buf*2))

SND_SHORT_BEEP = _make_beep(880, 0.15, 0.7)
SND_LONG_BEEP  = _make_beep(440, 0.45, 0.7)
SND_STATIC     = _make_static(2.0, 0.12)
SND_FLASHBANG  = _make_beep(200, 0.8, 0.5)

