# Player for RUN sequence
class EggPlayer:
    def __init__(self):
        self.x=WIDTH//2; self.y=HEIGHT//2
        self.speed=5; self.size=20
    def move(self,keys):
        if keys[pygame.K_w] or keys[pygame.K_UP]:    self.y=max(self.size,self.y-self.speed)
        if keys[pygame.K_s] or keys[pygame.K_DOWN]:  self.y=min(HEIGHT-self.size,self.y+self.speed)
        if keys[pygame.K_a] or keys[pygame.K_LEFT]:  self.x=max(self.size,self.x-self.speed)
        if keys[pygame.K_d] or keys[pygame.K_RIGHT]: self.x=min(WIDTH-self.size,self.x+self.speed)
    def draw(self,surf):
        pygame.draw.circle(surf,(255,100,100),(self.x,self.y),self.size)
        pygame.draw.circle(surf,(255,200,200),(self.x,self.y),self.size,2)
        # Eyes
        pygame.draw.circle(surf,(255,255,255),(self.x-7,self.y-5),4)
        pygame.draw.circle(surf,(255,255,255),(self.x+7,self.y-5),4)
        pygame.draw.circle(surf,(200,0,0),(self.x-7,self.y-5),2)
        pygame.draw.circle(surf,(200,0,0),(self.x+7,self.y-5),2)

# HIM — the entity chasing the player
class TheHim:
    def __init__(self):
        self.x=random.choice([-60,WIDTH+60])
        self.y=random.randint(50,HEIGHT-50)
        self.speed=2.5
    def update(self,px,py):
        dx=px-self.x; dy=py-self.y
        dist=max(1,math.sqrt(dx*dx+dy*dy))
        self.speed=min(6,self.speed+0.003)
        self.x+=dx/dist*self.speed
        self.y+=dy/dist*self.speed
    def draw(self,surf,t):
        # Tall dark figure with red eyes
        blink=(int(t*4))%8>1
        # Body
        pygame.draw.rect(surf,(15,0,0),(int(self.x)-12,int(self.y)-40,24,60),border_radius=4)
        # Head
        pygame.draw.ellipse(surf,(10,0,0),(int(self.x)-15,int(self.y)-70,30,35))
        # Eyes - glowing red
        if blink:
            for ex,ey in [(int(self.x)-6,int(self.y)-56),(int(self.x)+6,int(self.y)-56)]:
                glow=pygame.Surface((20,20),pygame.SRCALPHA)
                pygame.draw.circle(glow,(255,0,0,100),(10,10),10)
                surf.blit(glow,(ex-10,ey-10))
                pygame.draw.circle(surf,(255,30,0),(ex,ey),4)
        # Arms
        pygame.draw.line(surf,(15,0,0),(int(self.x)-12,int(self.y)-20),(int(self.x)-35,int(self.y)+10),4)
        pygame.draw.line(surf,(15,0,0),(int(self.x)+12,int(self.y)-20),(int(self.x)+35,int(self.y)+10),4)
    def touching(self,px,py):
        return math.sqrt((self.x-px)**2+(self.y-py)**2)<40

# Door for escape
class EscapeDoor:
    def __init__(self):
        self.x=WIDTH-80; self.y=HEIGHT//2-60; self.w=50; self.h=100
    def draw(self,surf,t):
        # Glow
        glow=pygame.Surface((self.w+40,self.h+40),pygame.SRCALPHA)
        alpha=int(abs(math.sin(t*3))*100+80)
        pygame.draw.rect(glow,(255,255,200,alpha),(0,0,self.w+40,self.h+40),border_radius=8)
        surf.blit(glow,(self.x-20,self.y-20))
        pygame.draw.rect(surf,(150,100,50),(self.x,self.y,self.w,self.h),border_radius=6)
        pygame.draw.rect(surf,(200,160,80),(self.x,self.y,self.w,self.h),3,border_radius=6)
        pygame.draw.circle(surf,(200,180,50),(self.x+8,self.y+self.h//2),5)
        ds=FONT_TINY.render("EXIT",True,(255,220,100))
        surf.blit(ds,ds.get_rect(centerx=self.x+self.w//2,y=self.y-18))
    def touching(self,px,py):
        return pygame.Rect(self.x-10,self.y-10,self.w+20,self.h+20).collidepoint(px,py)

def draw_old_tv(surf, lines, timer, beep_times=None):
    """Epic old CRT TV animation."""
    W,H=surf.get_size()
    tv_x=int(W*0.08); tv_y=int(H*0.06)
    tv_w=int(W*0.84); tv_h=int(H*0.72)

    # Dark room bg
    surf.fill((3,2,2))
    # Vignette
    for i in range(10):
        r2=int(min(W,H)*0.06*i)
        g2=pygame.Surface((r2*2,r2*2),pygame.SRCALPHA)
        pygame.draw.circle(g2,(0,0,0,int(25*(10-i))),(r2,r2),r2)
        surf.blit(g2,(W//2-r2,H//2-r2-30))

    # TV wooden cabinet
    pygame.draw.rect(surf,(45,28,12),(tv_x-30,tv_y-25,tv_w+60,tv_h+90),border_radius=25)
    pygame.draw.rect(surf,(60,38,18),(tv_x-30,tv_y-25,tv_w+60,tv_h+90),4,border_radius=25)
    # Wood grain lines
    for i in range(8):
        y2=tv_y-20+i*15
        pygame.draw.line(surf,(50,32,14),(tv_x-28,y2),(tv_x+tv_w+26,y2),1)

    # Screen bezel
    pygame.draw.rect(surf,(15,12,8),(tv_x-8,tv_y-8,tv_w+16,tv_h+16),border_radius=12)

    # Screen glow - green phosphor
    glow_surf=pygame.Surface((tv_w+40,tv_h+40),pygame.SRCALPHA)
    pygame.draw.rect(glow_surf,(0,180,0,25),(0,0,tv_w+40,tv_h+40),border_radius=14)
    surf.blit(glow_surf,(tv_x-20,tv_y-20))

    # Screen
    pygame.draw.rect(surf,(5,18,5),(tv_x,tv_y,tv_w,tv_h),border_radius=8)

    # Heavy static at start
    static_amount = max(0, 1.0-timer*0.5)
    for _ in range(int(200*static_amount)):
        sx=random.randint(tv_x,tv_x+tv_w)
        sy=random.randint(tv_y,tv_y+tv_h)
        sw=random.randint(3,40); sh=random.randint(1,4)
        sb=(random.randint(0,60),random.randint(30,100),random.randint(0,40))
        pygame.draw.rect(surf,sb,(sx,sy,sw,sh))

    # Horizontal roll lines (TV interference)
    roll=int(timer*30)%tv_h
    pygame.draw.line(surf,(0,80,0),(tv_x,tv_y+roll),(tv_x+tv_w,tv_y+roll),2)
    pygame.draw.line(surf,(0,120,0),(tv_x,tv_y+(roll+3)%tv_h),(tv_x+tv_w,tv_y+(roll+3)%tv_h),1)

    # Scanlines
    scan_surf=pygame.Surface((tv_w,tv_h),pygame.SRCALPHA)
    for sy in range(0,tv_h,2):
        pygame.draw.line(scan_surf,(0,0,0,80),(0,sy),(tv_w,sy),1)
    surf.blit(scan_surf,(tv_x,tv_y))

    # Screen curvature reflection
    refl=pygame.Surface((tv_w,tv_h),pygame.SRCALPHA)
    for i in range(30):
        r2=int(tv_w*0.6*(1-i/30))
        pygame.draw.circle(refl,(255,255,255,max(0,3-i//10)),(tv_w//4,tv_h//4),r2)
    surf.blit(refl,(tv_x,tv_y))

    # Text with phosphor glow effect
    text_y=tv_y+40; line_h=44
    for i,line in enumerate(lines[-8:]):
        if not line: continue
        age=len(lines)-i
        brightness=max(60,220-age*15)
        green=(0,brightness,0)
        # Glow
        glow_t=FONT_SM.render(line,True,(0,min(255,brightness+40),0))
        glow_t.set_alpha(40)
        surf.blit(glow_t,glow_t.get_rect(centerx=tv_x+tv_w//2,y=text_y+i*line_h).move(2,2))
        # Main text
        txt=FONT_SM.render(line,True,green)
        # Random flicker
        if random.random()<0.03: txt.set_alpha(random.randint(100,200))
        surf.blit(txt,txt.get_rect(centerx=tv_x+tv_w//2,y=text_y+i*line_h))

    # Blinking cursor
    if (pygame.time.get_ticks()//500)%2==0:
        pygame.draw.rect(surf,(0,200,0),(tv_x+tv_w//2,text_y+min(len(lines),8)*line_h,12,22))

    # "FROM TAPE" badge
    badge_surf=pygame.Surface((130,24),pygame.SRCALPHA)
    pygame.draw.rect(badge_surf,(0,100,0,180),(0,0,130,24),border_radius=4)
    surf.blit(badge_surf,(tv_x+6,tv_y+6))
    ft=FONT_TINY.render("◄ FROM TAPE ►",True,(0,220,0))
    surf.blit(ft,(tv_x+10,tv_y+8))

    # Antennas
    pygame.draw.line(surf,(55,38,20),(tv_x+tv_w//2-30,tv_y-25),(tv_x+tv_w//2-80,tv_y-85),5)
    pygame.draw.line(surf,(55,38,20),(tv_x+tv_w//2+30,tv_y-25),(tv_x+tv_w//2+90,tv_y-85),5)
    # Antenna tips
    pygame.draw.circle(surf,(70,50,25),(tv_x+tv_w//2-80,tv_y-85),5)
    pygame.draw.circle(surf,(70,50,25),(tv_x+tv_w//2+90,tv_y-85),5)

    # Control panel below screen
    panel_y=tv_y+tv_h+8
    pygame.draw.rect(surf,(35,22,10),(tv_x,panel_y,tv_w,35),border_radius=4)
    # Knobs
    for kx in [tv_x+tv_w//2-80, tv_x+tv_w//2-30, tv_x+tv_w//2+30, tv_x+tv_w//2+80]:
        pygame.draw.circle(surf,(25,15,8),(kx,panel_y+17),12)
        pygame.draw.circle(surf,(40,25,12),(kx,panel_y+17),12,2)
        # Knob line
        ang2=timer*0.5+kx*0.1
        nx=kx+int(math.cos(ang2)*8); ny=panel_y+17+int(math.sin(ang2)*8)
        pygame.draw.line(surf,(60,40,18),(kx,panel_y+17),(nx,ny),2)
    # Speaker grille
    for i in range(8):
        pygame.draw.circle(surf,(25,15,8),(tv_x+25,panel_y+8+i*4),2)

    # Screen border
    pygame.draw.rect(surf,(0,100,0),(tv_x,tv_y,tv_w,tv_h),2,border_radius=8)

    # Overall screen flicker
    if random.random()<0.04:
        flk=pygame.Surface((tv_w,tv_h),pygame.SRCALPHA)
        flk.fill((0,random.randint(10,40),0,20))
        surf.blit(flk,(tv_x,tv_y))

def draw_tape_insert(surf, progress, t):
    """Tape going into VCR animation."""
    surf.fill((5,3,2))
    # VCR machine
    vcr_x=WIDTH//2-150; vcr_y=int(HEIGHT*0.55)
    vcr_w=300; vcr_h=80
    pygame.draw.rect(surf,(20,15,10),(vcr_x,vcr_y,vcr_w,vcr_h),border_radius=8)
    pygame.draw.rect(surf,(35,25,15),(vcr_x,vcr_y,vcr_w,vcr_h),2,border_radius=8)
    # Slot
    slot_x=vcr_x+vcr_w//4; slot_y=vcr_y+20
    pygame.draw.rect(surf,(5,3,2),(slot_x,slot_y,vcr_w//2,25),border_radius=4)
    pygame.draw.rect(surf,(60,40,20),(slot_x,slot_y,vcr_w//2,25),1,border_radius=4)
    # LED
    led_col=(0,200,0) if (int(t*4))%2==0 else (0,100,0)
    pygame.draw.circle(surf,led_col,(vcr_x+20,vcr_y+20),5)
    pygame.draw.circle(surf,(200,0,0),(vcr_x+35,vcr_y+20),5)
    # Tape cassette moving down
    tape_x=WIDTH//2-40; tape_y=int(HEIGHT*0.10)+int(progress*(slot_y-int(HEIGHT*0.10)))
    tape_w=80; tape_h=50
    pygame.draw.rect(surf,(30,20,10),(tape_x,tape_y,tape_w,tape_h),border_radius=6)
    pygame.draw.rect(surf,(60,40,20),(tape_x,tape_y,tape_w,tape_h),2,border_radius=6)
    # Tape reels
    pygame.draw.circle(surf,(50,35,15),(tape_x+25,tape_y+25),12)
    pygame.draw.circle(surf,(50,35,15),(tape_x+55,tape_y+25),12)
    pygame.draw.circle(surf,(20,12,5),(tape_x+25,tape_y+25),5)
    pygame.draw.circle(surf,(20,12,5),(tape_x+55,tape_y+25),5)
    # Label
    lbl=FONT_TINY.render("TAPE 001",True,(180,120,60))
    surf.blit(lbl,lbl.get_rect(centerx=tape_x+tape_w//2,y=tape_y+5))
    # Text
    tx=FONT_SM.render("Inserting tape...",True,(120,80,40))
    surf.blit(tx,tx.get_rect(centerx=WIDTH//2,y=int(HEIGHT*0.82)))

