# ── Game Class ─────────────────────────────────────────────────────────────────
class Game:
    BASE_COLS=5; BASE_ROWS=4; BASE_TIME=5.0; MIN_TIME=1.3; TIME_DECAY=0.05; BOSS_SCORE=50
    def __init__(self): self.high_score=0; self.state="menu"; self.reset()
    def reset(self):
        self.score=0; self.lives=3; self.time_limit=self.BASE_TIME
        self.cols=self.BASE_COLS; self.rows=self.BASE_ROWS
        self.target_name=""; self.cmd_color=WHITE; self.deadline=0
        self.flash_timer=0; self.flash_color=BG; self.boss_mode=False
        self.blink_timer=0; self._last_tick=-1; self._boss_coins=False
        self.combo=0; self.best_combo=0; self.hits=0; self.misses=0; self.survival=False
        self.last_gain=0; self.gain_t=0.0; self.glasses_t=0; self.combo_lost_t=0.0
        self.round_start=time.time(); self.start_t=time.time(); self._rb=set(); self._one_life_at=None
        self.grid=[]
        self._build_grid(); self._new_round()

    def _tl_init_grid(self, tgt):
        import random as _r
        for c in self.grid:
            c["tl_name"] = _r.choice(["ASH","MUD","SAND","OBSID","FLAME"])
        for p in _r.sample(range(len(self.grid)), min(3,len(self.grid))):
            self.grid[p]["tl_name"] = tgt

    def _build_grid(self):
        if self.boss_mode: self.cols,self.rows=7,5
        else: self.cols,self.rows=self.BASE_COLS,self.BASE_ROWS
        m=60; top=180; cw=(WIDTH-m*2)//self.cols; ch=(HEIGHT-top-80)//self.rows
        skin=SKINS.get(gd.get("current_skin","Classic"),SKINS["Classic"])
        self.grid=[]
        names=COLOR_NAMES*(self.cols*self.rows//len(COLOR_NAMES)+1); random.shuffle(names)
        for row in range(self.rows):
            for col in range(self.cols):
                cx=m+col*cw+cw//2; cy=top+row*ch+ch//2; w=cw-8; h=ch-8; name=names[row*self.cols+col]
                self.grid.append({"rect":pygame.Rect(cx-w//2,cy-h//2,w,h),"name":name,"cx":cx,"cy":cy,"pulse":random.uniform(0,math.pi*2)})

    def _new_round(self):
        names=COLOR_NAMES*(self.cols*self.rows//len(COLOR_NAMES)+2); random.shuffle(names)
        for i,cell in enumerate(self.grid): cell["name"]=names[i]
        self.target_name=random.choice(COLOR_NAMES)
        easy=(self.hits<CLASSIC_EASY_START and not self.survival and not self.boss_mode
              and self.state not in ("ranked_game","timeline_playing","tournament_game","mp_game"))
        if easy: self.cmd_color=NEON[self.target_name]        # warm-up: the first answers match their color
        elif random.random()<0.3:
            others=[c for c in COLOR_NAMES if c!=self.target_name]; self.cmd_color=NEON[random.choice(others)]
        else: self.cmd_color=NEON[self.target_name]
        self.deadline=time.time()+self.time_limit; self.blink_timer=0; self.round_start=time.time()
    def _update_time(self): self.time_limit=max(self.MIN_TIME,self.BASE_TIME*((1-self.TIME_DECAY)**self.hits))   # speed follows correct answers, not combo points
    def handle_click(self,pos):
        for cell in self.grid:
            if cell["rect"].collidepoint(pos):
                if cell["name"]==self.target_name: self._correct(cell)
                else: self._wrong()
                return
    def combo_mult(self):
        c=self.combo
        return 1 if c<3 else 2 if c<5 else 3 if c<8 else 4 if c<12 else 5 if c<18 else 6
    def _correct(self,cell):
        self.hits+=1; self.combo+=1; self.best_combo=max(self.best_combo,self.combo)
        gain=self.combo_mult(); self.score+=gain; self.last_gain=gain; self.gain_t=time.time()
        if self.deadline-time.time()<0.3: award_badge("photo_finish")
        if self.combo>=8: award_badge("chain_reaction")
        if self.score>=1000: award_badge("advanced_pp")
        if (self.score>=100 and not self.survival and self.state in ("playing","boss")
                and not getattr(self,"glasses_t",0)):
            self.glasses_t=time.time(); self.deadline+=3.0; award_badge("i_need_glasses")
        maple_add_point()
        if self.combo>gd["stats"].get("best_combo",0): gd["stats"]["best_combo"]=self.combo
        if self.combo>=18: award_badge("combo_king")
        if time.time()-self.round_start<=0.5: award_badge("speed_demon")
        if self.score>=50 and self.misses==0: award_badge("unstoppable")
        if self.survival and self.score>=200: award_badge("survivor")
        if self.score>=50 and not self.boss_mode: award_badge("first_blood")
        if self.score>=100: award_badge("century")
        if self.state in ("playing","boss"):                                 # GAMEPLAY extras
            rb=getattr(self,"_rb",set()); rb.add(self.target_name); self._rb=rb
            if len(rb)>=6: award_badge("rainbow")
            if self.lives==1:
                if self.score>=1000: award_badge("last_breath")
                if getattr(self,"_one_life_at",None) is not None and self.score-self._one_life_at>=500: award_badge("comeback")
            if self.score>=100 and time.time()-getattr(self,"start_t",0)<=60: award_badge("minute_man")
            if self.survival and self.misses==0 and self.score>=10000: award_badge("untouchable")
        if self.state in ("playing","boss"):                                 # MODES + CHALLENGES (Classic / Survival)
            if self.survival:
                if self.score>=100000: award_badge("survival_clear")
            else:
                if self.score>=50000: award_badge("classic_clear")
                if self.misses==0 and self.score>=25000: award_badge("not_good_game")
                if self.misses==0 and self.score>=50000: award_badge("hell_of_colors")
        if self.score>self.high_score: self.high_score=self.score
        SND_CORRECT.play(); spawn_particles(cell["cx"],cell["cy"],NEON[self.target_name],30)
        self.flash_timer=8; self.flash_color=NEON[self.target_name]; self._update_time()
        gd["stats"]["total_correct"]=gd["stats"].get("total_correct",0)+1
        if gd["stats"]["total_correct"]%10==0:
            pass_add_xp(5)
            save_gd(gd)
        if self.score>=self.BOSS_SCORE and not self.boss_mode: self._enter_boss()
        elif self.state != "timeline_playing": self._new_round()
    def _wrong(self):
        if self.combo>=3: self.combo_lost_t=time.time()
        self.combo=0; self.misses+=1; self._rb=set()
        self.lives-=1; SND_WRONG.play(); start_shake(10,22)
        if self.lives==1: self._one_life_at=self.score
        self.flash_timer=10; self.flash_color=(200,0,0)
        gd["stats"]["total_wrong"]=gd["stats"].get("total_wrong",0)+1
        if self.lives<=0: self.state="gameover"; gd["stats"]["games_played"]=gd["stats"].get("games_played",0)+1; save_gd(gd)
        elif self.state != "timeline_playing": self._new_round()
    def _enter_boss(self):
        self.boss_mode=True; award_badge("first_blood")
        # Don't change state if in timeline mode
        if self.state not in ("timeline_playing","fall_mode","vibe_rush"):
            self.state="boss"
        SND_BOSS.play(); start_shake(6,30); play_music("boss")
        if not self._boss_coins:
            self._boss_coins=True; gd["coins"]=gd.get("coins",0)+COINS_BOSS; coins_earned(COINS_BOSS); check_coin_badges()
            if "_REWARD_FX" in globals(): _badge_toasts.append({"custom":True,"title":"BOSS MODE!","name":f"+{COINS_BOSS} coins","desc":"You reached 50 points","col":(255,200,40),"icon":"coin","t":None})
            if self.lives==1: award_badge("glass_cannon")
            pass_add_xp(1)
            save_gd(gd)
        self._build_grid(); self._new_round()
    def draw(self,surf):
        surf.fill(BG)
        if "halloween_theme" in globals() and halloween_theme():
            surf.blit(haunt_background(WIDTH,HEIGHT),(0,0)); draw_cobweb(surf,0,0,90); draw_cobweb(surf,WIDTH,0,90,True)
        elif "gold_theme" in globals() and gold_theme():
            surf.blit(_gd_backdrop(WIDTH,HEIGHT),(0,0)); _gd_sparks(surf,pygame.time.get_ticks()/1000.0,18)
        elif "winter_theme" in globals() and winter_theme():
            surf.blit(_wt_backdrop(WIDTH,HEIGHT),(0,0)); draw_snowfall(surf,pygame.time.get_ticks()/1000.0,0.7,0.2); _wt_edges(surf,0.45)
        elif "retro86_theme" in globals() and retro86_theme():
            draw_retro86_menu_bg(surf,pygame.time.get_ticks()/1000.0)
        if self.flash_timer>0:
            alpha=int(self.flash_timer/10*120); o=pygame.Surface((WIDTH,HEIGHT),pygame.SRCALPHA)
            r,g,b=self.flash_color; o.fill((r,g,b,alpha)); surf.blit(o,(0,0)); self.flash_timer-=1
        if self.boss_mode:
            self.blink_timer+=1
            if self.blink_timer%20<10:
                bl=pygame.Surface((WIDTH,HEIGHT),pygame.SRCALPHA); bl.fill((255,50,0,18)); surf.blit(bl,(0,0))
        _ht="halloween_theme" in globals() and halloween_theme()
        title=FONT_MED.render("BOSS MODE" if self.boss_mode else ("Color Under Pressure" if not _ht else "HAUNTED  •  Color Under Pressure"),True,(255,80,30) if self.boss_mode else ((255,140,50) if _ht else GRAY))
        _tr=title.get_rect(centerx=WIDTH//2,y=10); surf.blit(title,_tr)
        if self.boss_mode:                                   # lightning icons (the font has no ⚡ glyph)
            _bs=_tr.h*0.30
            for _bx in (_tr.left-_bs*1.7,_tr.right+_bs*1.7): ui_icon2(surf,"bolt",_bx,_tr.centery,_bs,(255,200,40))
        surf.blit(FONT_SM.render(f"Score: {self.score}",True,WHITE),(20,18))
        _ga=time.time()-getattr(self,"gain_t",0)
        if getattr(self,"last_gain",0)>1 and _ga<0.8:
            _gs=FONT_SM.render(f"+{self.last_gain}",True,(255,215,80)); _gs.set_alpha(int(255*(1-_ga/0.8)))
            surf.blit(_gs,(FONT_SM.size(f"Score: {self.score}")[0]+34,18-int(_ga*30)))
        surf.blit(FONT_TINY.render(f"Best: {self.high_score}",True,GRAY),(20,52))
        _cl=time.time()-getattr(self,"combo_lost_t",0)
        if _cl<1.0 and self.combo<3:
            cl_=FONT_SM.render("COMBO LOST",True,(255,80,80)); cl_.set_alpha(int(255*(1-_cl))); surf.blit(cl_,(20+int(math.sin(_cl*40)*4*(1-_cl)),76))
        if self.combo>=3:
            cm=FONT_SM.render(f"x{self.combo_mult()} COMBO",True,(255,215,80) if self.combo_mult()<6 else (255,90,60))
            cm=pygame.transform.rotozoom(cm,0,1+0.06*math.sin(pygame.time.get_ticks()/80)); surf.blit(cm,(20,76))
        if _ht:
            for k in range(max(3,min(self.lives,10))): ui_icon2(surf,"pumpkin" if k<self.lives else "skull",WIDTH-28-k*30,32,11,(255,120,20) if k<self.lives else (70,60,80))
        else:
            draw_lives(surf,min(self.lives,10),WIDTH-15,18,(255,80,80),max(0,3-self.lives))
        skin=SKINS.get(gd.get("current_skin","Classic"),SKINS["Classic"])
        cmd=FONT_BIG.render(f"GO TO  {self.target_name}!",True,self.cmd_color)
        surf.blit(cmd,cmd.get_rect(centerx=WIDTH//2,y=68))
        rem=max(0,self.deadline-time.time()); ratio=rem/self.time_limit if self.time_limit>0 else 0
        bx,by,bw,bh=50,145,WIDTH-100,14
        pygame.draw.rect(surf,DARK,(bx,by,bw,bh),border_radius=7)
        fw=int(bw*ratio)
        if fw>0:
            bc=(50,220,100) if ratio>0.5 else (255,200,40) if ratio>0.25 else (255,50,50)
            pygame.draw.rect(surf,bc,(bx,by,fw,bh),border_radius=7)
        pygame.draw.rect(surf,GRAY,(bx,by,bw,bh),2,border_radius=7)
        t=pygame.time.get_ticks()/1000
        for cell in self.grid:
            col=skin[cell["name"]]; pulse=0.06*math.sin(t*2+cell["pulse"])
            r2=cell["rect"].inflate(int(pulse*cell["rect"].width),int(pulse*cell["rect"].height))
            gw=pygame.Surface((r2.width+20,r2.height+20),pygame.SRCALPHA)
            cr,cg,cb=col; pygame.draw.rect(gw,(cr,cg,cb,40),gw.get_rect(),border_radius=14)
            surf.blit(gw,(r2.x-10,r2.y-10))
            pygame.draw.rect(surf,col,r2,border_radius=10)
            lbl=FONT_TINY.render(cell["name"],True,DARK); surf.blit(lbl,lbl.get_rect(center=r2.center))
            if _ht:
                pygame.draw.rect(surf,(25,10,30),r2,2,border_radius=10)
                draw_cobweb(surf,r2.right-1,r2.y+1,int(r2.h*0.32),True,70)
        if _ht:
            vg=_vignette(WIDTH,HEIGHT); surf.blit(vg,(0,0))
        draw_particles(surf)
        if rem<=0 and self.state in ("playing","boss","ranked_game"): self._wrong()
    def run_frame(self,events):
        for ev in events:
            if ev.type==pygame.MOUSEBUTTONDOWN and ev.button==1: self.handle_click(ev.pos)
        rem=self.deadline-time.time()
        if 0<rem<2 and int(rem*4)!=self._last_tick: self._last_tick=int(rem*4); SND_TICK.play()
        if rem<=0 and self.state not in ("gameover","timeline_playing","timeline_over"): self._wrong()

CLASSIC_EASY_START = 10      # Classic: the first 10 right answers are written in their own color (no tricks yet)

