_auth=None; _uid=None; _poll={}; _polling=False

def _auth_init():
    global _auth,_uid
    try:
        url=f"https://identitytoolkit.googleapis.com/v1/accounts:signUp?key={FB_KEY}"
        req=urllib.request.Request(url,data=json.dumps({"returnSecureToken":True}).encode(),method="POST",headers={"Content-Type":"application/json"})
        with urllib.request.urlopen(req,timeout=8) as r:
            d=json.loads(r.read()); _auth=d.get("idToken"); _uid=d.get("localId")
    except Exception as e: print("Auth:",e)
threading.Thread(target=_auth_init,daemon=True).start()

def _fb(method,path,data=None):
    url=FB_DB+path+".json"+("?auth="+_auth if _auth else "")
    body=json.dumps(data).encode() if data is not None else None
    req=urllib.request.Request(url,data=body,method=method,headers={"Content-Type":"application/json"})
    try:
        with urllib.request.urlopen(req,timeout=8) as r:
            txt=r.read(); return json.loads(txt) if txt.strip() not in (b"null",b"") else None
    except Exception as e: print(f"FB {method} {path}:",e); return None

def _fba(method,path,data=None,cb=None):
    def _r(): res=_fb(method,path,data);(cb(res) if cb else None)
    threading.Thread(target=_r,daemon=True).start()

# ── ANONYMOUS MEASUREMENT  (added in 2.2.0.1) ─────────────────────────────────
# Why this is here: out of 66 downloads, exactly ONE person outside the studio
# ever opened an account. Signing in is optional, so there was no way to tell
# whether people actually PLAY the game or close it after two minutes. This
# counts the playing. It does not count the person.
#
# WHAT IS SENT: a random number this computer makes up for itself, the first and
#   last day the game was opened, how many different days / how many times / how
#   many seconds / how many games were finished, the best Classic score, which
#   modes were opened, the language, whether they ever signed in, and how far
#   they got the FIRST time they played.
# WHAT IS NEVER SENT: no name, no e-mail, no password, no score with a name on
#   it, no file path, no computer name, no address. Nothing that says who it is.
#   Two players with the same numbers are indistinguishable.
# The player can switch it off in SETTINGS -> ACCOUNT, and then nothing leaves
# this computer at all.
METRICS_ON  = True                      # one switch for the whole feature
_MET_FILE   = os.path.join(_data_dir(), "metrics.json")
_MET_SEND_EVERY = 90.0                  # seconds between sends

# The funnel. The only number that really matters is where a FIRST-TIME player stops.
#   1 opened the game   2 reached the menu   3 opened a screen   4 started a game
#   5 finished a game   6 started a second one   7 finished five
_MET_PLAY_STATES = {
    "playing","boss","survival","fall_mode","flow","flow_win_anim","ranked_game",
    "vibe_rush","summer","timeline_playing","training","tutorial","mp_game",
    "tournament_game","haunt","him","frost","ore","liyvibe","egg_run","maple_tree","dash","other",
}
# state -> the short name of the mode, for "which modes did anyone actually open"
_MET_MODE_OF = {
    "playing":"classic","boss":"classic","survival":"survival","fall_mode":"fall",
    "flow":"flow","ranked_game":"ranked","vibe_rush":"vibe","summer":"summer",
    "timeline_playing":"timeline","training":"training","tutorial":"tutorial",
    "mp_game":"mp","tournament_game":"tournament","haunt":"haunt","him":"him",
    "frost":"frost","ore":"ore","liyvibe":"liyvibe","maple_tree":"maple","dash":"dash","other":"other",
}

_MET = {"id":"", "d":{}, "t0":0.0, "sent":0.0, "run1":False, "started":False}

def _met_today(): return __import__("datetime").date.today().isoformat()

def _met_build():
    """Which kind of copy this is - nothing about the computer itself."""
    if not getattr(sys,"frozen",False): return "py"
    return "msix" if os.environ.get("LOCALAPPDATA") and "WindowsApps" in sys.executable else "exe"

def _met_blank():
    return {"id":"", "off":False, "first":_met_today(), "last":_met_today(), "days":0,
            "runs":0, "secs":0, "games":0, "best":0, "step":1, "step1":1,
            "modes":[], "lang":"en", "signed":False, "build":_met_build(), "ver":GAME_VERSION}

def _met_heal(d):
    """Self-healing, like haunt_data and ore_data: a broken or hand-edited file
    must never take the game down."""
    out = _met_blank()
    if not isinstance(d, dict): return out
    def _i(k, lo, hi):
        try: v = int(d.get(k, out[k]))
        except Exception: v = out[k]
        return max(lo, min(hi, v))
    def _s(k, n):
        v = d.get(k, out[k])
        return v[:n] if isinstance(v, str) else out[k]
    import re as _r
    for k in ("first","last"):
        v = d.get(k)
        out[k] = v if isinstance(v,str) and _r.fullmatch(r"\d{4}-\d{2}-\d{2}", v) else out[k]
    # a clock that went backwards: the first day can only ever move EARLIER, never later,
    # or a changed clock would quietly swallow a day that really happened.
    if out["last"] < out["first"]: out["first"] = out["last"]
    out["id"]     = _s("id", 32)
    out["off"]    = bool(d.get("off"))
    out["days"]   = _i("days", 0, 100000)
    out["runs"]   = _i("runs", 0, 10**7)
    out["secs"]   = _i("secs", 0, 10**8)
    out["games"]  = _i("games", 0, 10**7)
    out["best"]   = _i("best", 0, 10**7)
    out["step"]   = _i("step", 1, 7)
    out["step1"]  = _i("step1", 1, 7)
    out["lang"]   = _s("lang", 4)
    out["build"]  = _met_build()
    out["ver"]    = GAME_VERSION
    out["signed"] = bool(d.get("signed"))
    m = d.get("modes")
    out["modes"]  = sorted({x[:14] for x in m if isinstance(x,str)})[:24] if isinstance(m,list) else []
    return out

def _met_read_file():
    try:
        with open(_MET_FILE, encoding="utf-8") as f: return json.load(f)
    except Exception: return None

def _met_write_file():
    try:
        with open(_MET_FILE, "w", encoding="utf-8") as f: json.dump(_MET["d"], f)
    except Exception: pass

def metrics_is_off():
    return (not METRICS_ON) or bool(_MET["d"].get("off"))

def metrics_set_off(flag):
    """The SETTINGS switch. Off means nothing is sent from this computer again."""
    if not _MET["started"]: return
    _MET["d"]["off"] = bool(flag); _met_write_file()

def _met_send():
    """Send in a side thread. A failure is silent - measuring must never be felt."""
    if metrics_is_off() or not _MET["id"]: return
    d = _MET["d"]
    payload = {k: d[k] for k in ("first","last","days","runs","secs","games","best",
                                 "step","step1","modes","lang","signed","build","ver")}
    def _go():
        try:
            url = FB_DB + "/metrics/" + _MET["id"] + ".json"
            tok = globals().get("_auth")
            if tok: url += "?auth=" + tok
            req = urllib.request.Request(url, data=json.dumps(payload).encode(),
                                         method="PATCH", headers={"Content-Type":"application/json"})
            urllib.request.urlopen(req, timeout=8).read()
        except Exception: pass
    threading.Thread(target=_go, daemon=True).start()
    _MET["sent"] = time.time()

def metrics_start():
    """Called once, when the game opens."""
    if not METRICS_ON: return
    try:
        raw = _met_read_file()
        fresh = raw is None
        d = _met_heal(raw)
        if not d["id"]: d["id"] = hashlib.sha256(os.urandom(32)).hexdigest()[:32]
        today = _met_today()
        if fresh:
            d["first"] = today; d["days"] = 1; d["runs"] = 0; d["step1"] = 1
        elif d["last"] != today:
            d["days"] += 1
        d["last"] = today
        d["runs"] += 1
        _MET["id"] = d["id"]; _MET["d"] = d
        _MET["t0"] = time.time(); _MET["sent"] = 0.0
        _MET["run1"] = (d["runs"] <= 1)
        _MET["started"] = True
        metrics_step(2)                      # the menu is up, the game really opened
        _met_write_file()                    # write AFTER the step, or run 1 looks like it never got in
    except Exception as _e:
        _MET["started"] = False
        try: log_problem("metrics_start", _e)
        except Exception: pass

def metrics_step(n):
    """Record how far the player got. Only ever goes up."""
    if not _MET["started"]: return
    try:
        n = int(n)
        d = _MET["d"]
        if n > d.get("step",1): d["step"] = min(7, n)
        if _MET["run1"] and n > d.get("step1",1): d["step1"] = min(7, n)
    except Exception: pass

def metrics_state(state):
    """One hook, called when the screen changes. Turns screens into funnel steps."""
    if not _MET["started"]: return
    try:
        d = _MET["d"]
        if state in _MET_PLAY_STATES:
            metrics_step(4)
            m = _MET_MODE_OF.get(state)
            if m and m not in d["modes"] and len(d["modes"]) < 24:
                d["modes"] = sorted(d["modes"] + [m])
        elif state not in ("menu",):
            metrics_step(3)
    except Exception: pass

def metrics_game_finished():
    """One finished game, whatever the mode."""
    if not _MET["started"]: return
    try:
        d = _MET["d"]
        d["games"] = min(10**7, d.get("games",0) + 1)
        metrics_step(5)
        if d["games"] >= 2: metrics_step(6)
        if d["games"] >= 5: metrics_step(7)
    except Exception: pass

def metrics_tick():
    """Every frame. Counts the seconds and sends now and then."""
    if not _MET["started"] or metrics_is_off(): return
    try:
        now = time.time()
        if now - _MET["sent"] < _MET_SEND_EVERY: return
        metrics_collect()
        _met_write_file()
        _met_send()
    except Exception: pass

def metrics_collect():
    """Copy the numbers the game already keeps into the anonymous record."""
    if not _MET["started"]: return
    try:
        d = _MET["d"]
        d["secs"] = min(10**8, int(d.get("secs",0)) + int(max(0.0, time.time() - _MET["t0"])))
        _MET["t0"] = time.time()
        g = globals().get("gd", {}) or {}
        hs = g.get("high_scores", {}) or {}
        try: d["best"] = max(int(d.get("best",0)), int(hs.get("classic",0) or 0))
        except Exception: pass
        d["lang"] = str(g.get("language", d.get("lang","en")))[:4]
        if (globals().get("AUTH_STATE", {}) or {}).get("user"): d["signed"] = True
        d["ver"] = GAME_VERSION
    except Exception: pass

def metrics_quit():
    """Last send, when the game closes."""
    if not _MET["started"] or metrics_is_off(): return
    try:
        metrics_collect(); _met_write_file()
        d = _MET["d"]
        payload = {k: d[k] for k in ("first","last","days","runs","secs","games","best",
                                     "step","step1","modes","lang","signed","build","ver")}
        url = FB_DB + "/metrics/" + _MET["id"] + ".json"
        tok = globals().get("_auth")
        if tok: url += "?auth=" + tok
        req = urllib.request.Request(url, data=json.dumps(payload).encode(),
                                     method="PATCH", headers={"Content-Type":"application/json"})
        urllib.request.urlopen(req, timeout=3).read()        # short wait: closing must stay quick
    except Exception: pass

# The multiplayer PIN login used to live here: a username plus four digits,
# kept as MD5 in /usernames where any signed-in player could read it. Four digits
# is ten thousand guesses, so it protected nothing. MULTIPLAYER now uses the same
# account as the rest of the game, and there is no second password to break.

def mp_signed_in():
    """Multiplayer needs the real account - nothing else counts as logged in."""
    return bool((globals().get("AUTH_STATE") or {}).get("user"))

def mp_register_name():
    """Put this account in the public name directory, so a friend can be found
    by name. It holds a uid and a display name and NOTHING secret."""
    try:
        u = (globals().get("AUTH_STATE") or {}).get("user") or {}
        key = str(u.get("name_key", "")).lower().strip()
        if not key or not _uid: return
        _fba("PUT", f"/usernames/{key}", {"uid": _uid, "display": u.get("displayName", key)})
    except Exception: pass

def mp_add_friend(fname):
    key=fname.lower().strip()
    if not key: return False,"Enter a username!"
    data=_fb("GET",f"/usernames/{key}")
    if data is None: return False,"Player not found!"
    fuid=data.get("uid")
    if fuid==_uid: return False,"That's you!"
    _fb("PUT",f"/friends/{_uid}/{fuid}",{"name":data.get("display",fname)}); return True,f"Added {data.get('display',fname)}!"

def mp_friends():
    data=_fb("GET",f"/friends/{_uid}")
    if not data: return []
    return [{"name":v.get("name","?"),"uid":k} for k,v in data.items()]

def mp_create():
    code="".join(random.choices("ABCDEFGHJKLMNPQRSTUVWXYZ23456789",k=6))
    my=gd.get("player_name","Player")
    _fb("PUT",f"/parties/{code}",{"host":_uid,"state":"waiting","target":"","round":0,"winner":"","players":{_uid:{"name":my,"score":0}}})
    return code

def mp_join(code):
    code=code.strip().upper()
    if not code: return False,"Enter a code!"
    p=_fb("GET",f"/parties/{code}")
    if p is None: return False,"Party not found!"
    if len(p.get("players",{}))>=4: return False,"Party full!"
    _fb("PUT",f"/parties/{code}/players/{_uid}",{"name":gd.get("player_name","Player"),"score":0})
    return True,p

def mp_get(code): return _fb("GET",f"/parties/{code}")
def mp_score(code,sc): _fba("PATCH",f"/parties/{code}/players/{_uid}",{"score":sc})
def mp_winner(code,name): _fba("PATCH",f"/parties/{code}",{"state":"finished","winner":name})
def mp_round(code,tgt,rnd): _fba("PATCH",f"/parties/{code}",{"target":tgt,"round":rnd,"state":"playing"})
def mp_leave(code):
    if code and _uid: _fba("DELETE",f"/parties/{code}/players/{_uid}")

def mp_poll_start(code):
    global _polling
    _polling=True
    def _p():
        while _polling:
            try:
                d=mp_get(code)
                if d: _poll.clear(); _poll.update(d)
            except: pass
            time.sleep(1.5)
    threading.Thread(target=_p,daemon=True).start()

def mp_poll_stop():
    global _polling,_poll; _polling=False; _poll.clear()

