current_lang = "EN"

def T(key):
    """Get translation for current language."""
    return LANGS.get(current_lang, LANGS["EN"]).get(key, LANGS["EN"].get(key, key))

# Font cache for non-Latin scripts
_font_cache = {}
def get_font(size, lang=None):
    lang = lang or current_lang
    key = (size, lang)
    if key not in _font_cache:
        _font_cache[key] = TFont(size)
    return _font_cache[key]

def render_text(text, size, color):
    """Render text with correct font for current language."""
    font = get_font(size)
    return font.render(text, True, color)


