#  RANKED & TOURNAMENT SYSTEM
# ═══════════════════════════════════════════════════════════════════════════════
RANKS = [
    ("Bronze III",    0),    ("Bronze II",   200),  ("Bronze I",    400),
    ("Silver III",  700),    ("Silver II",   1000), ("Silver I",    1400),
    ("Gold III",    1800),   ("Gold II",     2300),  ("Gold I",      2900),
    ("Platinum III",3600),   ("Platinum II", 4400),  ("Platinum I",  5300),
    ("Diamond III", 6300),   ("Diamond II",  7400),  ("Diamond I",   8600),
    ("Master",      10000),  ("Grandmaster", 13000), ("Challenger",  17000),
]
RANK_COLORS = {
    "Bronze":   (180, 100, 40),
    "Silver":   (180, 180, 200),
    "Gold":     (255, 200, 40),
    "Platinum": (100, 220, 220),
    "Diamond":  (100, 180, 255),
    "Master":   (200, 80, 255),
    "Grandmaster": (255, 50, 150),
    "Challenger":  (255, 200, 0),
}

def get_rank(rp):
    """Return (rank_name, color) for given rank points."""
    rank_name = RANKS[0][0]
    for name, threshold in RANKS:
        if rp >= threshold: rank_name = name
        else: break
    base = rank_name.split()[0]
    return rank_name, RANK_COLORS.get(base, WHITE)

def rp_for_win(rp):  return 25 + max(0, (5000-rp)//200)
def rp_for_loss(rp): return -min(40, 15 + rp//500)

def ranked_score_to_rp(score, won):
    """Convert game score to rank points change."""
    base = rp_for_win(gd.get("rank_points",0)) if won else rp_for_loss(gd.get("rank_points",0))
    bonus = score // 10
    return base + bonus if won else base

# Firebase ranked
def fb_submit_ranked(name, score, rp):
    def _r():
        _fb("PATCH", f"/ranked/{_uid}", {"name": name, "score": score, "rp": rp, "ts": int(time.time())})
    threading.Thread(target=_r, daemon=True).start()

def fb_get_leaderboard():
    """Every row here was written by some other player, and the rules let anyone
    write anything - so nothing in it can be trusted to be the right shape."""
    data = _fb("GET", "/ranked")
    if not isinstance(data, dict): return []
    def _num(x, hi=10**9):
        try: return max(0, min(hi, int(x)))
        except Exception: return 0
    players = []
    for v in data.values():
        if not isinstance(v, dict): continue           # a row that is a string or a number
        nm = v.get("name", "?")
        nm = nm[:24] if isinstance(nm, str) else "?"
        nm = "".join(c for c in nm if c.isprintable()) or "?"   # no newlines, no control codes
        players.append((nm, _num(v.get("rp")), _num(v.get("score"))))
    return sorted(players, key=lambda x: x[1], reverse=True)[:20]

# Tournament (simple 1v1 via Firebase)
def fb_create_tournament():
    code = "".join(random.choices("ABCDEFGHJKLMNP23456789", k=6))
    my = gd.get("player_name","Player")
    _fb("PUT", f"/tournaments/{code}", {
        "host": _uid, "state": "waiting", "target": "",
        "players": {_uid: {"name": my, "score": 0}},
        "winner": "", "round": 0
    })
    return code

def fb_join_tournament(code):
    t = _fb("GET", f"/tournaments/{code}")
    if not t: return False, "Not found!"
    if len(t.get("players",{})) >= 2: return False, "Full!"
    my = gd.get("player_name","Player")
    _fb("PUT", f"/tournaments/{code}/players/{_uid}", {"name": my, "score": 0})
    return True, t

def fb_get_tournament(code): return _fb("GET", f"/tournaments/{code}")
def fb_tournament_score(code, sc): _fba("PATCH", f"/tournaments/{code}/players/{_uid}", {"score": sc})
def fb_tournament_start(code, tgt): _fba("PATCH", f"/tournaments/{code}", {"target": tgt, "state": "playing", "round": 1})
def fb_tournament_winner(code, name): _fba("PATCH", f"/tournaments/{code}", {"state": "finished", "winner": name})
def fb_tournament_round(code, tgt, rnd): _fba("PATCH", f"/tournaments/{code}", {"target": tgt, "round": rnd})

_t_poll = {}; _t_polling = False

def t_poll_start(code):
    global _t_polling
    _t_polling = True
    def _p():
        while _t_polling:
            try:
                d = fb_get_tournament(code)
                if d: _t_poll.clear(); _t_poll.update(d)
            except: pass
            time.sleep(1.5)
    threading.Thread(target=_p, daemon=True).start()

def t_poll_stop():
    global _t_polling; _t_polling = False; _t_poll.clear()


# ═══════════════════════════════════════════════════════════════════════════════
#  RANDOM FLOW LEVEL GENERATOR
# ═══════════════════════════════════════════════════════════════════════════════
def generate_flow_level(gs, n_pairs, seed=None):
    """Generate a guaranteed-solvable random Flow level."""
    if seed is not None: random.seed(seed)
    for _ in range(300):
        grid = [[None]*gs for _ in range(gs)]
        pairs = []
        ok = True
        for pi in range(n_pairs):
            empty = [(r,c) for r in range(gs) for c in range(gs) if grid[r][c] is None]
            if len(empty) < 2: ok=False; break
            random.shuffle(empty)
            start = end = None
            for i,s in enumerate(empty):
                for e in empty[i+1:]:
                    if abs(s[0]-e[0])+abs(s[1]-e[1]) >= gs//2:
                        start,end=s,e; break
                if start: break
            if not start: ok=False; break
            # BFS path
            visited={start}; stack=[(start,[start])]
            path=None
            while stack:
                idx=random.randint(0,len(stack)-1)
                (r,c),cur_path=stack.pop(idx)
                if (r,c)==end: path=cur_path; break
                dirs=[(0,1),(0,-1),(1,0),(-1,0)]; random.shuffle(dirs)
                for dr,dc in dirs:
                    nr,nc=r+dr,c+dc
                    if 0<=nr<gs and 0<=nc<gs and (nr,nc) not in visited:
                        if grid[nr][nc] is None or (nr,nc)==end:
                            visited.add((nr,nc)); stack.append(((nr,nc),cur_path+[(nr,nc)]))
            if not path: ok=False; break
            for r,c in path: grid[r][c]=pi
            pairs.append((pi,start,end))
        if ok and len(pairs)==n_pairs:
            return pairs
    return None  # fallback

def get_random_flow_level(level_num):
    """Get a random flow level based on level number (deterministic by level)."""
    # Scale difficulty
    if level_num < 3:   gs,np = 5,3
    elif level_num < 6: gs,np = 6,4
    elif level_num < 9: gs,np = 7,5
    elif level_num < 12:gs,np = 8,6
    else:               gs,np = 9,7
    t = max(30, 60-level_num*2)
    seed = level_num * 137 + 42  # deterministic per level number
    pairs = generate_flow_level(gs, np, seed)
    if pairs is None:
        # Emergency fallback
        pairs = [(i,(0,i*2),(gs-1,(i+1)*2%gs)) for i in range(min(np,3))]
    return gs, pairs, t


# ── Tutorial Draw ──────────────────────────────────────────────────────────────
def draw_tutorial(surf, step_idx, t_anim, mouse):
    surf.fill(BG)
    step = TUTORIAL_STEPS[step_idx]
    total = len(TUTORIAL_STEPS)
    # Progress bar
    pw=int(WIDTH*0.7); px=WIDTH//2-pw//2
    pygame.draw.rect(surf,(20,20,40),(px,20,pw,8),border_radius=4)
    pygame.draw.rect(surf,NEON["BLUE"],(px,20,int(pw*(step_idx+1)/total),8),border_radius=4)
    st_s=FONT_TINY.render(f"Step {step_idx+1} / {total}",True,GRAY)
    surf.blit(st_s,st_s.get_rect(right=WIDTH-20,y=18))
    # Title
    tit=FONT_MED.render(step["title"],True,WHITE)
    surf.blit(tit,tit.get_rect(centerx=WIDTH//2,y=int(HEIGHT*0.10)))
    # Demo box
    dy=int(HEIGHT*0.22); dh=int(HEIGHT*0.42)
    pygame.draw.rect(surf,(15,15,35),(40,dy,WIDTH-80,dh),border_radius=14)
    pygame.draw.rect(surf,(30,30,60),(40,dy,WIDTH-80,dh),2,border_radius=14)
    demo=step["demo"]
    if demo=="command":
        cmd=FONT_BIG.render("GO TO  RED!",True,NEON["BLUE"])
        surf.blit(cmd,cmd.get_rect(centerx=WIDTH//2,centery=dy+dh//2))
        arr=FONT_SM.render("↑ This is the command — find RED!",True,NEON["YELLOW"])
        surf.blit(arr,arr.get_rect(centerx=WIDTH//2,y=dy+dh-44))
    elif demo=="stroop":
        e1=FONT_MED.render("GO TO  RED!",True,NEON["RED"])
        e2=FONT_MED.render("GO TO  RED!",True,NEON["BLUE"])
        ok=FONT_TINY.render("Easy — word and color match",True,NEON["GREEN"])
        hard=FONT_SM.render("HARD — word says RED but text is BLUE! Still click RED!",True,NEON["YELLOW"])
        surf.blit(e1,e1.get_rect(centerx=WIDTH//2,y=dy+20))
        surf.blit(ok,ok.get_rect(centerx=WIDTH//2,y=dy+72))
        surf.blit(e2,e2.get_rect(centerx=WIDTH//2,y=dy+100))
        surf.blit(hard,hard.get_rect(centerx=WIDTH//2,y=dy+152))
    elif demo=="grid":
        cols_t=4; rows_t=2; cw_t=(WIDTH-160)//cols_t; ch_t=int(dh*0.5)//rows_t
        names_t=["RED","BLUE","GREEN","YELLOW","PURPLE","ORANGE","RED","BLUE"]
        target_t="GREEN"
        for row in range(rows_t):
            for col in range(cols_t):
                n=names_t[row*cols_t+col]; c2=NEON[n]
                rx=80+col*cw_t; ry=dy+20+row*ch_t
                if n==target_t:
                    pulse=int(abs(math.sin(t_anim*3))*10)
                    pygame.draw.rect(surf,c2,(rx-pulse,ry-pulse,cw_t-8+pulse*2,ch_t-8+pulse*2),border_radius=10)
                    ar=FONT_TINY.render("← CLICK!",True,NEON["YELLOW"])
                    surf.blit(ar,(rx+cw_t,ry+ch_t//4))
                else:
                    pygame.draw.rect(surf,c2,(rx,ry,cw_t-8,ch_t-8),border_radius=10)
                lb=FONT_TINY.render(n,True,(10,10,20))
                surf.blit(lb,lb.get_rect(center=(rx+(cw_t-8)//2,ry+(ch_t-8)//2)))
        cmd2=FONT_SM.render(f"GO TO  {target_t}!",True,NEON["GREEN"])
        surf.blit(cmd2,cmd2.get_rect(centerx=WIDTH//2,y=dy+dh-44))
    elif demo=="boss":
        blink=(int(t_anim*3))%2==0
        bs=FONT_BIG.render("BOSS MODE",True,(255,80,30) if blink else (200,50,10))
        surf.blit(bs,bs.get_rect(centerx=WIDTH//2,y=dy+20))
        combos=[("3+ combo","x2",NEON["GREEN"]),("5+ combo","x3",NEON["YELLOW"]),
                ("8+ combo","x4",NEON["ORANGE"]),("12+ combo","x5",(255,100,100)),("18+ combo","x6",NEON["RED"])]
        for i,(lb,ml,c2) in enumerate(combos):
            ls=FONT_SM.render(f"{lb}  →  {ml}",True,c2)
            surf.blit(ls,ls.get_rect(centerx=WIDTH//2,y=dy+80+i*36))
    elif demo is None:
        em=FONT_BIG.render("READY!" if step_idx>0 else "LETS GO!",True,NEON["YELLOW"])
        surf.blit(em,em.get_rect(centerx=WIDTH//2,centery=dy+dh//2))
