def _acct_email(uid):
    local=uid if re.fullmatch(r"[a-z0-9_-]{1,40}",uid) else "u"+uid.encode("utf-8").hex()[:60]
    return f"{local}@{FB_EMAIL_DOMAIN}"

def _acct_password(password): return "CUP-"+str(password)       # Firebase needs 6+ chars; a 4-digit PIN still works

def _auth_refresh():
    """Keep the ID token fresh (they expire after 1 hour)."""
    rt=AUTH_STATE.get("refresh")
    if not rt or time.time()<AUTH_STATE.get("exp",0)-300: return
    d,err=_fb_auth_call(None,{"grant_type":"refresh_token","refresh_token":rt},host="securetoken")
    if d: AUTH_STATE["token"]=d.get("id_token"); AUTH_STATE["exp"]=time.time()+int(d.get("expires_in",3600))

def _current_token():
    if AUTH_STATE.get("user"):
        _auth_refresh(); return AUTH_STATE.get("token")
    return globals().get("_auth")                     # anonymous token (read-only things like announcements)

def _fb_req(method, path, data=None, token=None):
    """Firebase REST request, always sent with a real auth token."""
    tok = token or _current_token()
    url = FIREBASE_DB + path + ".json" + (f"?auth={tok}" if tok else "")
    body = json.dumps(data).encode() if data is not None else None
    req  = urllib.request.Request(url, data=body, method=method)
    req.add_header("Content-Type","application/json")
    try:
        with urllib.request.urlopen(req, timeout=8) as r:
            txt=r.read(); return json.loads(txt) if txt.strip() else None
    except: return None

def cloud_save(key, value):
    """Save value to Firebase under current user."""
    if not AUTH_STATE["user"] or not AUTH_STATE["token"]: return False
    uid = AUTH_STATE["user"]["uid"]
    return _fb_req("PUT", f"/users/{uid}/{key}", value) is not None

def cloud_load(key, default=None):
    """Load value from Firebase under current user."""
    if not AUTH_STATE["user"] or not AUTH_STATE["token"]: return default
    uid = AUTH_STATE["user"]["uid"]
    result = _fb_req("GET", f"/users/{uid}/{key}")
    return result if result is not None else default

_cloud = {"dirty":False,"last_save":0.0,"status":"","status_t":0.0}
SAVE_VER = 210                 # bump in every update. A save written by a NEWER version is never overwritten by an older one
NEWER_SAVE = {"on":False,"base_coins":0}
CLOUD_UNION_KEYS = ["redeemed_codes","badges","unlocked_skins","unlocked_titles","unlocked_modes","days_played","claimed_free","claimed_premium"]

def _sane_save(d):
    """A save loaded from the cloud is whatever that account wrote there, and the
    rules let it write anything. Force the shapes the rest of the game assumes,
    or one bad value bricks the account on every launch."""
    if not isinstance(d, dict): return {}
    out = dict(d)
    for k in ("badges","unlocked_skins","unlocked_titles","unlocked_modes",
              "days_played","claimed_free","claimed_premium","redeemed_codes"):
        v = out.get(k)
        out[k] = [x for x in v if isinstance(x, str)] if isinstance(v, list) else []
    for k in ("stats","high_scores","maple","pass2"):
        if k in out and not isinstance(out[k], dict): out[k] = {}
    for k in ("coins","pass_xp","pass_level","rank_points","games_finished"):
        if k in out:
            try: out[k] = max(0, min(10**12, int(out[k])))
            except Exception: out[k] = 0
    nm = out.get("player_name")
    if isinstance(nm, str):
        out["player_name"] = "".join(c for c in nm if c.isprintable())[:24] or "Player"
    return out

def merge_saves(local, cloud):
    """Newest save wins, but collections are merged so nothing unlocked is ever lost."""
    local, cloud = _sane_save(local), _sane_save(cloud)
    def _progress(d):
        st=d.get("stats",{}) or {}
        return (st.get("total_correct",0)+st.get("games_played",0), d.get("_saved_at",0))
    newer_cloud=_progress(cloud)>_progress(local)      # more real progress wins, time breaks ties
    out=dict(cloud if newer_cloud else local); other=local if newer_cloud else cloud
    for k in CLOUD_UNION_KEYS:
        a=list(out.get(k,[]) or []); 
        for v in (other.get(k,[]) or []):
            if v not in a: a.append(v)
        if a: out[k]=a
    for k in ("high_scores","stats"):
        m=dict(other.get(k,{}) or {}); m.update({kk:max(vv,(other.get(k,{}) or {}).get(kk,vv)) if isinstance(vv,(int,float)) else vv
                                                  for kk,vv in (out.get(k,{}) or {}).items()})
        out[k]=m
    ml,mc=out.get("maple",{}) or {},other.get("maple",{}) or {}
    if mc.get("waters",0)>ml.get("waters",0): out["maple"]=mc
    out["has_premium"]=bool(out.get("has_premium") or other.get("has_premium"))
    if out.get("pass2") or other.get("pass2"): out["pass2"]=merge_pass2(out.get("pass2"),other.get("pass2"))
    out["season_seen"]=max(out.get("season_seen",1) or 1,other.get("season_seen",1) or 1)
    return out

def merge_into_newer(newer, mine):
    """This game is OLDER than the version that last saved the account (e.g. the last itch.io build).
    Keep everything the newer version saved; only ADD what we earned here (badges, skins, best scores, coins)."""
    out=dict(newer)
    for k in CLOUD_UNION_KEYS:
        a=list(out.get(k,[]) or [])
        for v in (mine.get(k,[]) or []):
            if v not in a: a.append(v)
        if a: out[k]=a
    for k in ("high_scores","stats"):
        m=dict(out.get(k,{}) or {})
        for kk,vv in (mine.get(k,{}) or {}).items():
            if isinstance(vv,(int,float)) and isinstance(m.get(kk,0),(int,float)): m[kk]=max(vv,m.get(kk,0))
            elif kk not in m: m[kk]=vv
        out[k]=m
    out["coins"]=int(newer.get("coins",0) or 0)+max(0,int(mine.get("coins",0) or 0)-int(NEWER_SAVE["base_coins"]))
    out["has_premium"]=bool(newer.get("has_premium") or mine.get("has_premium"))
    for k in DEVICE_KEYS:
        if k in mine: out[k]=mine[k]
    return out

def cloud_save_all():
    """Upload the whole save (runs in a thread)."""
    if not AUTH_STATE["user"]: return False
    _cloud["status"]="saving"; _cloud["status_t"]=time.time()
    if NEWER_SAVE["on"]:                                   # protect progress made in a newer version of the game
        fresh=cloud_load("gd",{}) or {}
        if int(fresh.get("_save_ver",0) or 0)>SAVE_VER:
            out=merge_into_newer(fresh,gd); ok=cloud_save("gd",out)
            if ok:
                keep={k:gd[k] for k in DEVICE_KEYS if k in gd}; gd.clear(); gd.update(out); gd.update(keep)
                NEWER_SAVE["base_coins"]=int(gd.get("coins",0) or 0)
            if AUTH_STATE.get("user"): save_account_backup(AUTH_STATE["user"].get("uid"),gd)
            _cloud["status"]="saved" if ok else "error"; _cloud["status_t"]=time.time()
            _cloud["last_save"]=time.time(); _cloud["dirty"]=not ok
            return ok
    gd["_save_ver"]=max(int(gd.get("_save_ver",0) or 0),SAVE_VER)
    ok=cloud_save("gd",gd)
    if AUTH_STATE.get("user"): save_account_backup(AUTH_STATE["user"].get("uid"),gd)
    _cloud["status"]="saved" if ok else "error"; _cloud["status_t"]=time.time()
    _cloud["last_save"]=time.time(); _cloud["dirty"]=not ok
    return ok

def cloud_autosave_tick():
    """Call every frame: uploads at most every 30s, only when something changed."""
    if (AUTH_STATE["user"] and _cloud["dirty"] and _cloud["status"]!="saving"
            and time.time()-_cloud["last_save"]>30):
        _cloud["last_save"]=time.time(); threading.Thread(target=cloud_save_all,daemon=True).start()
    if AUTH_STATE["user"] and time.time()-_RNG_SYNC["t"]>60:          # coins spent in COLOR UNDER PRESSURE: RNG
        _RNG_SYNC["t"]=time.time(); threading.Thread(target=rng_apply_spent,daemon=True).start()

_RNG_SYNC = {"t":0.0}
def rng_apply_spent():
    """COLOR UNDER PRESSURE: RNG uses the same coins. RNG writes what it spent to /users/<uid>/rng/spent;
    here we take off only the part we haven't taken off yet (gd["rng_applied"])."""
    if not AUTH_STATE.get("user"): return
    try:
        uid=AUTH_STATE["user"]["uid"]; rng=_fb_req("GET",f"/users/{uid}/rng")
        if not isinstance(rng,dict): return
        if (rng.get("found") or {}).get("man"): award_badge("rng_dev")       # rolled MAN STUDIO (1 in 1,000,000) in RNG
        # net = spent in RNG - earned in RNG (selling characters + new character bonus, RNG 1.5.0)
        net=int(rng.get("spent",0) or 0)-int(rng.get("earned",0) or 0); done=int(gd.get("rng_applied",0) or 0)
        if net!=done:
            gd["coins"]=max(0,int(gd.get("coins",0) or 0)-(net-done)); gd["rng_applied"]=net
            save_gd(gd); _cloud["dirty"]=True
    except Exception as e: print("rng coins:",e)

