def cloud_sign_in(username=None, password=None, pass_hash=None, silent=False):
    """Name + password account (Firebase Authentication). silent=True = automatic sign-in at startup."""
    if not username or AUTH_STATE["loading"]: return
    AUTH_STATE["loading"]=True; AUTH_STATE["error"]=None
    def _fail(msg):
        AUTH_STATE["error"]=None if silent else msg; AUTH_STATE["loading"]=False
    def _do_login():
        try:
            name=username.strip(); uid_key=name.lower().replace(" ","_")
            prev=gd.get("cloud_login") or {}; new_acct=False
            if password:
                email=_acct_email(uid_key); pw=_acct_password(password)
                d,err=_fb_auth_call("signInWithPassword",{"email":email,"password":pw,"returnSecureToken":True})
                if not d:
                    if err=="OFFLINE": return _fail("No connection")
                    d,err2=_fb_auth_call("signUp",{"email":email,"password":pw,"returnSecureToken":True})
                    if not d:
                        if err2=="EMAIL_EXISTS": return _fail("Wrong password")
                        if err2 and "OPERATION_NOT_ALLOWED" in err2: return _fail("Accounts are off (server)")
                        return _fail("Sign in failed")
                new_acct=err is not None                          # sign-in failed but sign-up worked = brand new account
                tok,rt,fuid,exp=d.get("idToken"),d.get("refreshToken"),d.get("localId"),int(d.get("expiresIn",3600))
            else:                                               # automatic sign-in with the saved refresh token
                rt=prev.get("refresh")
                if not rt: return _fail(None)
                d,err=_fb_auth_call(None,{"grant_type":"refresh_token","refresh_token":rt},host="securetoken")
                if not d:
                    if err!="OFFLINE": gd.pop("cloud_login",None); _become_guest()   # account gone / password changed
                    return _fail(None)
                tok,rt,fuid,exp=d.get("id_token"),d.get("refresh_token",rt),d.get("user_id"),int(d.get("expires_in",3600))
            AUTH_STATE.update({"token":tok,"refresh":rt,"exp":time.time()+exp})
            AUTH_STATE["user"]={"uid":fuid,"name_key":uid_key,"displayName":name}
            try:                                  # multiplayer is this account now
                globals()["_uid"]=fuid
                mp["logged_in"]=True
                mp_register_name()
            except Exception: pass
            try: award_badge("signed_in")
            except Exception: pass
            _fb_req("PATCH",f"/users/{fuid}/profile",{"displayName":name,"name_key":uid_key,"lastLogin":int(time.time())})
            gd["player_name"]=name; gd["cloud_login"]={"name":name,"refresh":rt}
            AUTH_STATE["dev_ok"]=False
            # DEV MODE needs BOTH: the account really is a developer account on the
            # server (the uid comes from the signed token), AND the password matches.
            # The name and the cached fingerprint live in gamedata.json, so on their
            # own they prove nothing - a player could simply type them in.
            real_key=globals().get("DEV_UIDS",{}).get(fuid)
            want=globals().get("DEV_ACCOUNTS",{}).get(real_key) if real_key else None
            if want and real_key==uid_key:
                fp=_dev_fingerprint(real_key,password) if password else prev.get("dev","")
                if fp==want: AUTH_STATE["dev_ok"]=True; gd["cloud_login"]["dev"]=fp
            try: frost_visible()          # a DEV account gets FIRST FROST right away
            except Exception: pass
            if password and not prev.get("refresh"):        # signing in from GUEST
                if not _switch_to_account(fuid,name,new_acct): return
            else:                                             # same account again (automatic sign-in)
                save_gd(gd); cloud_load_all()
            check_account_age(tok); award_dev_badges()
            AUTH_STATE["loading"]=False; AUTH_STATE["error"]=None
        except Exception as e:
            _fail(str(e))
    threading.Thread(target=_do_login,daemon=True).start()

def google_login_web(username=None, password=None):      # old name, kept for compatibility
    cloud_sign_in(username,password)

def auto_cloud_sign_in():
    cl=gd.get("cloud_login")
    if cl and cl.get("name") and cl.get("refresh"): cloud_sign_in(cl["name"],silent=True)
    elif cl:                                                  # old-style login (before Firebase Auth) — sign in again once
        gd.pop("cloud_login",None)
        if _stash_legacy(gd): _become_guest()

def _become_guest():
    """Back to a fresh guest (nothing saved). Computer settings stay."""
    keep={k:gd[k] for k in DEVICE_KEYS if k in gd}
    gd.clear(); gd.update(_fresh_gd()); gd.update(keep); gd["player_name"]="Guest"
    try: clean_badges()
    except Exception: pass
    save_gd(gd); _cloud["dirty"]=False

def logout():
    """The account's progress stays in the account (cloud). This computer goes back to a fresh guest."""
    if AUTH_STATE["user"]: save_account_backup(AUTH_STATE["user"].get("uid"),gd)
    if AUTH_STATE["user"] and not cloud_save_all(): return      # offline: stay signed in so nothing is lost
    AUTH_STATE["dev_ok"]=False; AUTH_STATE.pop("transfer",None)
    try: mp["logged_in"]=False; mp["friends"]=[]; mp["party_code"]=""
    except Exception: pass
    AUTH_STATE["user"]=None; AUTH_STATE["token"]=None; AUTH_STATE["refresh"]=None; AUTH_STATE["loading"]=False; AUTH_STATE["error"]=None
    try: frost_visible()                  # ...and loses it again on sign out
    except Exception: pass
    _become_guest()

def _switch_to_account(fuid, name, new_acct):
    """Guest -> account (runs in the sign-in thread).
    Existing account: its cloud save REPLACES the guest - nothing is mixed in.
    New account: starts fresh; if the guest or an old save has progress, the player is asked if to move it."""
    login=dict(gd.get("cloud_login") or {}); keep={k:gd[k] for k in DEVICE_KEYS if k in gd}
    guest_now=json.loads(json.dumps(gd))
    saved={}; restored=False
    if not new_acct:
        saved=_fb_req("GET",f"/users/{fuid}/gd")
        if saved is None and _fb_req("GET",f"/users/{fuid}/profile") is None:   # no connection -> stay a guest
            gd.pop("cloud_login",None)
            AUTH_STATE.update({"user":None,"token":None,"refresh":None,"dev_ok":False,"loading":False,"error":"No connection"})
            return False
        if not isinstance(saved,dict): saved={}
        if not _has_progress(saved):                     # cloud is empty (server wiped?) -> use this computer's copy
            bk=load_account_backup(fuid)
            if bk and _has_progress(bk): saved=merge_saves(bk,saved) if saved else bk; restored=True
    new=_fresh_gd(); new.update(saved); new.update(keep); new["player_name"]=name; new["cloud_login"]=login
    gd.clear(); gd.update(new)
    try: clean_badges()
    except Exception: pass
    try: grant_all_badges()
    except Exception: pass
    save_gd(gd)
    if restored: cloud_save_all()                         # put the progress back on the server
    if new_acct:
        offer=_load_legacy()
        if _has_progress(guest_now): offer=merge_saves(guest_now,offer) if _has_progress(offer) else guest_now
        if _has_progress(offer): AUTH_STATE["transfer"]=offer
        cloud_save_all()
    return True

def accept_transfer():
    """YES on 'Move your progress?' - the guest / old progress becomes the new account's progress."""
    data=AUTH_STATE.pop("transfer",None)
    if not data: return
    keep={k:gd[k] for k in DEVICE_KEYS if k in gd}; login=gd.get("cloud_login"); name=gd.get("player_name","Player")
    new=_fresh_gd(); new.update({k:v for k,v in data.items() if k!="cloud_login"}); new.update(keep)
    new["player_name"]=name; new["cloud_login"]=login
    gd.clear(); gd.update(new)
    try: clean_badges()
    except Exception: pass
    save_gd(gd)
    try: os.remove(LEGACY_FILE)
    except Exception: pass
    threading.Thread(target=cloud_save_all,daemon=True).start()

def quit_game():
    """Save to the cloud (if signed in) before closing."""
    try:
        save_gd(gd)
        if AUTH_STATE["user"]: cloud_save_all()
    except Exception: pass
    try: metrics_quit()
    except Exception: pass
    pygame.quit(); sys.exit()

