def coins_earned(n):
    """Count every coin you EARN (for COIN RAIN)."""
    if n>0:
        st=gd.setdefault("stats",{}); st["coins_earned"]=st.get("coins_earned",0)+int(n)
        if st["coins_earned"]>=5000: award_badge("coin_rain")
def check_coin_badges():
    if gd.get("coins",0)>=500: award_badge("piggy_bank")
def check_skin_badges():
    if gd.get("current_skin","Classic")!="Classic": award_badge("fresh_paint")
    if "Galaxy" in (gd.get("unlocked_skins") or []): award_badge("galaxy_keeper")      # LEGACY: Galaxy is retired after Season 1
    if len(set(gd.get("unlocked_skins",["Classic"])))>=6: award_badge("color_collector")

def get_badge(badge_id): return next((b for b in ALL_BADGES if b["id"]==badge_id), None)
def visible_badges(include_test=False):
    """Badges shown in the game. 'hidden' ones (secret, e.g. Steam) appear only once you have them.
    TEST (dev_only) badges: only in the TEST tab, only for DEV MODE, never counted."""
    today=time.strftime("%Y-%m-%d")
    if include_test and dev_mode(): return [b for b in ALL_BADGES if b.get("dev_only")]
    _hide = (FROST_BADGE_IDS if not frost_visible() else ()) \
          + (ORE_BADGE_IDS   if not ore_visible()   else ()) \
          + (DASH_BADGE_IDS  if not dash_visible()  else ()) \
          + (OTHER_BADGE_IDS if not other_visible() else ())     # an event's badges appear with the event
    return [b for b in ALL_BADGES if not b.get("dev_only") and b["id"] not in _hide
            and (not b.get("hidden") or has_badge(b["id"]) or (b.get("show_from") and today>=b["show_from"])
            or (b.get("show_until") and today<=b["show_until"]))]       # show_until: visible while you can still get it
def has_badge(badge_id): return badge_id in gd.get("badges",[])
_badge_toasts = []          # queue of badge ids waiting to pop up
def award_badge(badge_id):
    if "badges" not in gd: gd["badges"]=[]
    if badge_id not in gd["badges"]:
        gd["badges"].append(badge_id)
        if not (get_badge(badge_id) or {}).get("dev_only"): gd["coins"]=gd.get("coins",0)+BADGE_COINS; coins_earned(BADGE_COINS)    # TEST badge: no coins
        try: gold_check()
        except Exception: pass
        save_gd(gd)
        _badge_toasts.append({"id":badge_id,"t":None})
        if AUTH_STATE.get("user"): threading.Thread(target=cloud_save,args=("badges",gd["badges"]),daemon=True).start()
        return True
    return False

# Event badges: you get them just by playing during the event
FOUNDER_END    = "2027-03-04"     # FOUNDER: played (or made an account) before the Steam launch on 5/3/2027
FOUNDER_REVEAL = "2026-12-30"     # Steam is secret until MNC - FOUNDER is handed out (and shown) only from this day
NEXT_FEST_2027 = ("2027-02-22","2027-03-01")   # Steam Next Fest - only in the Steam demo
OG_PLAYER_END = "2026-11-14"        # OG PLAYER badge: play at least once until this day. After it - never again.
EVENT_WINDOWS = [
    ("maple_soul",     "2026-10-08","2026-10-29"),
    ("haunted",        "2026-10-25","2026-11-14"),
    ("frost_born",     "2026-11-20","2026-12-04"),
    ("winter_child",   "2026-12-05","2026-12-24"),
    ("holiday_spirit", "2026-12-25","2026-12-31"),
    ("new_era",        "2027-01-01","2027-01-07"),
]
def clean_badges():
    """Drop badges that no longer exist (e.g. the removed STORY badges)."""
    if int(gd.get("_save_ver",0) or 0)>SAVE_VER: return    # badges from a newer version: keep them (we just can't show them)
    known={b["id"] for b in ALL_BADGES}
    bl=gd.get("badges",[]) or []
    if any(x not in known for x in bl): gd["badges"]=[x for x in bl if x in known]; save_gd(gd)

# ── the studio account carries every badge ───────────────────────────────────
# man_studio is the showcase account: it is the one used for screenshots, trailers
# and for checking how a finished collection looks. It should never be missing a
# badge because of a new computer, a fresh install, or a badge added in a later
# version. This fills them back in, every time that account is loaded.
MAN_STUDIO_ALL_BADGES = True

def man_studio_account():
    """True ONLY for the studio's own login name. Deliberately not dev_mode():
    a DEV build on somebody else's computer must not hand out the whole collection."""
    try:
        u = (globals().get("AUTH_STATE", {}) or {}).get("user") or {}
        return str(u.get("name_key", u.get("uid", ""))).lower() == "man_studio"
    except Exception:
        return False

def grant_all_badges():
    """Give man_studio every badge it is missing. Returns how many were added.
    TEST badges (dev_only) are left out - they are not real badges and never count.
    They go straight into the list instead of through award_badge(), so there is no
    avalanche of ninety pop-ups."""
    if not (MAN_STUDIO_ALL_BADGES and man_studio_account()): return 0
    try:
        bl = gd.get("badges")
        if not isinstance(bl, list):        # a broken or hand-edited save heals right here
            bl = []; gd["badges"] = bl
        have = {x for x in bl if isinstance(x, str)}
        add = [b["id"] for b in ALL_BADGES if not b.get("dev_only") and b["id"] not in have]
        if not add: return 0
        gd["badges"] = [x for x in bl if isinstance(x, str)] + add
        save_gd(gd)
        try: _cloud["dirty"] = True          # and push it up, so it is there on every computer
        except Exception: pass
        return len(add)
    except Exception as e:
        try: log_problem("grant_all_badges", e)
        except Exception: pass
        return 0

def check_daily_badges():
    """Record today's play day, then award time + event badges."""
    grant_all_badges()
    import datetime as _d
    today=_d.date.today(); iso=today.isoformat()
    days=set(gd.get("days_played",[]))
    if iso not in days:
        days.add(iso); gd["days_played"]=sorted(days); save_gd(gd)
    award_badge("first_day")
    if gd.get("has_premium"): award_badge("golden_ticket")
    check_skin_badges()
    streak=0; d=today
    while d.isoformat() in days: streak+=1; d-=_d.timedelta(days=1)
    gd["day_streak"]=streak
    if streak>=7: award_badge("week_warrior")
    if len(days)>=30: award_badge("dedicated")
    if len(days)>=100: award_badge("veteran")
    for bid,a,b in EVENT_WINDOWS:
        if a<=iso<=b: award_badge(bid)
    if any(d_<=OG_PLAYER_END for d_ in days): award_badge("og_player")
    if iso>=FOUNDER_REVEAL and any(d_<=FOUNDER_END for d_ in days): award_badge("founder")
    award_dev_badges()
    if (BUILD_DEMO or steam_build()) and NEXT_FEST_2027[0]<=iso<=NEXT_FEST_2027[1]: award_badge("next_fest_2027")    # played even once before the end of THE HAUNT 2026
    _hr=_d.datetime.now().hour
    if _hr<5: award_badge("night_owl")
    elif _hr<8: award_badge("early_bird")
    check_coin_badges(); check_skin_badges()

def changelog_live():
    """Only the versions that have actually come out. A build can ship an event early
    (its code is date-gated), and its notes must not show up before its day."""
    out=[]
    for e in CHANGELOG:
        d=str(e.get("date","")).split("/")
        try:
            iso="%04d-%02d-%02d"%(int(d[2]),int(d[1]),int(d[0]))
        except Exception:
            out.append(e); continue
        if not frost_visible() and e.get("frost"): continue
        if not other_visible() and e.get("other"): continue
        if dev_mode() or iso<=_today(): out.append(e)
    return out

