# =============================================================================
#  MAPLE BLOSSOM — FALL MODE: COLOR STORM
# =============================================================================
# Fall Mode has its OWN autumn colors (like Timeline -1 has ASH, MUD...).
# Internally the game still uses COLOR_NAMES, each one is mapped to an autumn color.
FALL_NAME = {"RED":"MAPLE", "ORANGE":"PUMPKIN", "YELLOW":"AMBER",
             "GREEN":"MOSS", "BLUE":"CHESTNUT", "PURPLE":"PLUM"}
FALL_COLORS = {
    "MAPLE":   (200, 42, 30),
    "PUMPKIN": (245, 128, 25),
    "AMBER":   (242, 196, 48),
    "MOSS":    (112, 152, 44),
    "CHESTNUT":(128, 76, 40),
    "PLUM":    (132, 56, 138),
}
FALL_NAMES = list(FALL_COLORS.keys())
def fall_col(internal):  return FALL_COLORS[FALL_NAME[internal]]
_FALL_BY_NEON = {NEON[k]: fall_col(k) for k in COLOR_NAMES}

# Wind levels — the storm gets stronger as you score
WIND_LEVELS = [
    {"name":"BREEZE",  "from":0,  "gap":8.0, "leaves":55,  "col":(170,200,120)},
    {"name":"GALE",    "from":15, "gap":6.5, "leaves":90,  "col":(245,170,50)},
    {"name":"TEMPEST", "from":35, "gap":5.0, "leaves":140, "col":(235,70,40)},
]
STORM_DURATION   = 1.2    # seconds the storm covers the board
STORM_WARNING    = 2.0    # seconds of "STORM INCOMING" before it hits
STORM_MIN_GAP    = 4.0
GOLD_LEAF_CHANCE = 0.22   # chance per second that a golden leaf starts falling
GOLD_LEAF_BONUS  = 1.5    # seconds added to the timer
GOLD_LEAF_POINTS = 3
INTRO_TIME       = 3.2

# ── Sounds & music (generated, like the rest of the game) ──────────────────────
def _make_whoosh(dur=1.1, vol=0.35):
    sr=22050; n=int(sr*dur); buf=[]; prev=0.0
    for i in range(n):
        env=math.sin(math.pi*i/n)**1.5
        prev=prev*0.93+random.uniform(-1,1)*0.07          # low-passed noise = wind
        val=max(-32767,min(32767,int(prev*env*vol*32767*6)))
        buf+=[val&0xFF,(val>>8)&0xFF]*2                    # 22k -> 44k
    return pygame.mixer.Sound(buffer=bytes(buf*2))

def _make_chime():
    sr=44100; buf=[]
    for freq in (988,1319,1568):
        n=int(sr*0.09)
        for i in range(n):
            v=math.sin(2*math.pi*freq*i/sr)*(1-i/n)
            val=int(v*0.35*32767); buf+=[val&0xFF,(val>>8)&0xFF]
    return pygame.mixer.Sound(buffer=bytes(buf*2))

SND_WHOOSH = _make_whoosh()
SND_CHIME  = _make_chime()
SND_LEVEL  = _beep(330,0.25,0.4,"square")
MUSIC_FALL = _make_music([(220,.5),(262,.5),(330,.5),(294,.5),(262,.5),(247,.5),(220,1),
                          (196,.5),(247,.5),(294,.5),(262,.5),(247,.5),(220,.5),(196,1)],110,0.16)

# ── Drawing helpers ────────────────────────────────────────────────────────────
def maple_points(cx, cy, size, angle=0.0):
    """Points of a 5-lobed maple leaf."""
    pts=[]; N=40
    for i in range(N):
        th=-math.pi/2+i*2*math.pi/N
        lobe=abs(math.cos(2.5*(th+math.pi/2)))
        r=size*(0.45+0.55*lobe**1.6)
        if math.sin(th)>0.75: r*=0.55                      # notch at the stem
        a=th+angle; pts.append((cx+math.cos(a)*r, cy+math.sin(a)*r))
    return pts

def draw_maple(surf, cx, cy, size, col, angle=0.0, alpha=255, stem=True):
    alpha=max(0,min(255,int(alpha)))
    if size<2 or alpha==0: return
    s=int(size*2.6)+4; tmp=pygame.Surface((s,s),pygame.SRCALPHA); c=s/2
    r,g,b=(max(0,min(255,int(v))) for v in col[:3])
    pygame.draw.polygon(tmp,(r,g,b,alpha),maple_points(c,c,size,angle))
    if stem:
        dx=math.cos(angle+math.pi/2); dy=math.sin(angle+math.pi/2)
        pygame.draw.line(tmp,(r//2,g//2,b//2,alpha),(c,c),(c+dx*size*1.25,c+dy*size*1.25),max(1,int(size/6)))
    surf.blit(tmp,(cx-c,cy-c))

def _lum(c): return 0.299*c[0]+0.587*c[1]+0.114*c[2]
def _text_on(c): return (40,20,10) if _lum(c)>135 else (255,240,220)

_fall_bg_cache = {}
def fall_background(W, H):
    """Layered autumn landscape: dusk sky, low sun, hills, maple trees, leaf ground."""
    key=(W,H)
    if key in _fall_bg_cache: return _fall_bg_cache[key]
    _fall_bg_cache.clear()
    bg=pygame.Surface((W,H)); hz=int(H*0.62)
    for y in range(H):                                     # sky gradient
        if y<hz:
            r=y/hz; col=(int(38+r*190),int(16+r*80),int(42+r*8))
        else:
            r=(y-hz)/max(1,H-hz); col=(int(80-r*40),int(36-r*16),int(22-r*10))
        bg.fill(col,(0,y,W,1))
    sx,sy,sr=int(W*0.78),int(H*0.56),int(min(W,H)*0.09)   # low sun + glow
    for i in range(6,0,-1):
        g=pygame.Surface((sr*2*i,sr*2*i),pygame.SRCALPHA)
        pygame.draw.circle(g,(255,170,70,14),(sr*i,sr*i),sr*i); bg.blit(g,(sx-sr*i,sy-sr*i))
    pygame.draw.circle(bg,(255,196,110),(sx,sy),sr)
    rnd=random.Random(1008)                                # fixed seed = same scenery
    for layer,(col,base,amp) in enumerate([((92,38,40),0.60,0.07),((62,24,24),0.68,0.06)]):
        pts=[(0,H)]
        for x in range(0,W+40,40):
            y=H*base-math.sin(x*0.006+layer*2)*H*amp-math.sin(x*0.017+layer)*H*amp*0.4
            pts.append((x,int(y)))
        pts.append((W,H)); pygame.draw.polygon(bg,col,pts)
        for _ in range(7+layer*5):                         # maple tree silhouettes
            tx=rnd.randint(0,W); ty=int(H*base-math.sin(tx*0.006+layer*2)*H*amp)+4
            th=int(H*(0.06+0.03*layer)); tcol=(col[0]-18,col[1]-10,col[2]-10)
            pygame.draw.line(bg,tcol,(tx,ty),(tx,ty-th),max(2,th//10))
            for k in range(5):
                pygame.draw.circle(bg,(min(255,col[0]+40+layer*30),col[1]+8,col[2]),
                                   (tx+rnd.randint(-th//3,th//3),ty-th+rnd.randint(-th//4,th//5)),
                                   rnd.randint(th//5,th//3))
    for _ in range(int(W*0.35)):                           # leaves on the ground
        lx=rnd.randint(0,W); ly=rnd.randint(int(H*0.80),H)
        c=rnd.choice(list(FALL_COLORS.values()))
        draw_maple(bg,lx,ly,rnd.randint(3,7),(c[0]*3//4,c[1]*3//4,c[2]*3//4),rnd.uniform(0,6.3),200,False)
    _fall_bg_cache[key]=bg
    return bg

# ── State ──────────────────────────────────────────────────────────────────────
def fall_new_state():
    now=time.time()
    return {"intro":INTRO_TIME, "next_storm":now+INTRO_TIME+WIND_LEVELS[0]["gap"],
            "storm_start":None, "shuffled":False, "storms":0, "storm_leaves":[], "streaks":[],
            "gold":None, "gold_check":now, "gold_got":0,
            "points":0, "combo":0, "best_combo":0, "level":0, "banner":None,
            "bits":[], "pops":[], "last_score":0, "last_lives":3, "new_best":False}

def fall_wind_level(score):
    lv=0
    for i,w in enumerate(WIND_LEVELS):
        if score>=w["from"]: lv=i
    return lv

def fall_storm_gap(fs, score):
    return max(STORM_MIN_GAP, WIND_LEVELS[fs["level"]]["gap"]-score*0.03)

def fall_combo_mult(combo):
    return 1 if combo<3 else 2 if combo<6 else 3 if combo<10 else 4 if combo<15 else 5

def _spawn_bits(fs, x, y, col, n=14):
    for _ in range(n):
        a=random.uniform(0,2*math.pi); sp=random.uniform(90,320)
        fs["bits"].append({"x":x,"y":y,"vx":math.cos(a)*sp,"vy":math.sin(a)*sp-120,
                           "rot":random.uniform(0,6.3),"vr":random.uniform(-8,8),
                           "col":col,"life":random.uniform(0.6,1.1),"size":random.uniform(5,10)})

def _pop(fs, text, x, y, col):
    fs["pops"].append({"t":text,"x":x,"y":y,"col":col,"life":1.0})

def fall_shuffle_board(game, fs):
    """The storm passes: every cell gets a new color. Target word stays the same."""
    names=COLOR_NAMES*(len(game.grid)//len(COLOR_NAMES)+2); random.shuffle(names)
    for i,cell in enumerate(game.grid): cell["name"]=names[i]
    if not any(c["name"]==game.target_name for c in game.grid):
        random.choice(game.grid)["name"]=game.target_name
    if fs["level"]>=2:                                     # TEMPEST: the ink lies too
        others=[c for c in COLOR_NAMES if c!=game.target_name]
        game.cmd_color=NEON[random.choice(others)]

def fall_start_storm(fs, game):
    fs["storm_start"]=time.time(); fs["shuffled"]=False
    game.deadline+=STORM_DURATION                          # the storm never eats your time
    W,H=WIDTH,HEIGHT; fs["storm_leaves"]=[]
    for _ in range(WIND_LEVELS[fs["level"]]["leaves"]):
        fs["storm_leaves"].append({"x":random.uniform(-W*1.2,-10),"y":random.uniform(-20,H),
            "vx":random.uniform(1000,1800),"vy":random.uniform(-60,140),"rot":random.uniform(0,6.3),
            "vr":random.uniform(-10,10),"size":random.uniform(8,20),
            "col":random.choice(list(FALL_COLORS.values()))})
    fs["streaks"]=[{"x":random.uniform(-W,0),"y":random.uniform(0,H),"len":random.uniform(80,260),
                    "v":random.uniform(1600,2400)} for _ in range(18+fs["level"]*10)]
    SND_WHOOSH.play(); start_shake(4+fs["level"]*3,24)

def fall_update(fs, game, dt):
    now=time.time()
    # Intro countdown: freeze timers
    if fs["intro"]>0:
        fs["intro"]-=dt
        game.deadline=now+game.time_limit
        fs["next_storm"]=now+max(0,fs["intro"])+WIND_LEVELS[0]["gap"]
        return
    # Score / lives changes -> combo, points, effects
    if game.score>fs["last_score"]:
        fs["combo"]+=1; fs["best_combo"]=max(fs["best_combo"],fs["combo"])
        m=fall_combo_mult(fs["combo"]); fs["points"]+=m
        mx,my=pygame.mouse.get_pos()
        _pop(fs,f"+{m}" if m==1 else f"+{m}  x{m} COMBO",mx,my-20,(255,220,120) if m>1 else WHITE)
        if fs["combo"] in (3,6,10,15): SND_LEVEL.play()
    if game.lives<fs["last_lives"]: fs["combo"]=0
    fs["last_score"]=game.score; fs["last_lives"]=game.lives
    # Wind level
    lv=fall_wind_level(game.score)
    if lv>fs["level"]:
        fs["level"]=lv; fs["banner"]={"text":f"THE WIND IS RISING — {WIND_LEVELS[lv]['name']}","life":2.2}
        SND_LEVEL.play()
    if fs["banner"]:
        fs["banner"]["life"]-=dt
        if fs["banner"]["life"]<=0: fs["banner"]=None
    # Storm
    if fs["storm_start"] is None:
        if now>=fs["next_storm"]: fall_start_storm(fs,game)
    else:
        el=now-fs["storm_start"]
        if el>=STORM_DURATION/2 and not fs["shuffled"]:
            fall_shuffle_board(game,fs); fs["shuffled"]=True
        for lf in fs["storm_leaves"]:
            lf["x"]+=lf["vx"]*dt; lf["y"]+=lf["vy"]*dt; lf["rot"]+=lf["vr"]*dt
        for st in fs["streaks"]: st["x"]+=st["v"]*dt
        if el>=STORM_DURATION:
            fs["storm_start"]=None; fs["storms"]+=1; fs["storm_leaves"]=[]; fs["streaks"]=[]
            fs["next_storm"]=now+fall_storm_gap(fs,game.score)
            _pop(fs,f"STORM {fs['storms']} SURVIVED",WIDTH//2,HEIGHT//2,(255,200,110))
            if fs["storms"]>=10: award_badge("storm_chaser")
    # Golden leaf — falls from the sky, swaying
    g=fs["gold"]
    if g:
        g["t"]+=dt; g["y"]+=g["vy"]*dt; g["x"]=g["x0"]+math.sin(g["t"]*2.2)*38
        if g["y"]>HEIGHT-60: fs["gold"]=None
    if fs["gold"] is None and fs["storm_start"] is None and now-fs["gold_check"]>=1.0:
        fs["gold_check"]=now
        if random.random()<GOLD_LEAF_CHANCE:
            x0=random.randint(90,max(91,WIDTH-90))
            fs["gold"]={"x0":x0,"x":x0,"y":170.0,"vy":random.uniform(55,85),"t":0.0,
                        "r":max(16,int(min(WIDTH,HEIGHT)*0.032))}
    # Effects
    for b in fs["bits"]:
        b["x"]+=b["vx"]*dt; b["y"]+=b["vy"]*dt; b["vy"]+=420*dt; b["vx"]*=0.98
        b["rot"]+=b["vr"]*dt; b["life"]-=dt
    fs["bits"]=[b for b in fs["bits"] if b["life"]>0]
    for p in fs["pops"]: p["y"]-=45*dt; p["life"]-=dt*0.9
    fs["pops"]=[p for p in fs["pops"] if p["life"]>0]

def fall_click(fs, game, pos):
    """Returns True if the click was used (intro / storm / golden leaf)."""
    if fs["intro"]>0 or fs["storm_start"] is not None: return True
    g=fs["gold"]
    if g and math.hypot(pos[0]-g["x"],pos[1]-g["y"])<=g["r"]+10:
        game.deadline+=GOLD_LEAF_BONUS; fs["gold"]=None; fs["gold_got"]+=1
        fs["points"]+=GOLD_LEAF_POINTS
        SND_CHIME.play(); spawn_particles(pos[0],pos[1],(255,210,60),30)
        _spawn_bits(fs,pos[0],pos[1],(255,205,50),18)
        _pop(fs,f"+{GOLD_LEAF_POINTS}  +{GOLD_LEAF_BONUS}s",pos[0],pos[1]-24,(255,225,90))
        gd["leaves_collected"]=gd.get("leaves_collected",0)+1
        if gd["leaves_collected"]>=50: award_badge("leaf_collector")
        return True
    for cell in game.grid:                                 # leaf burst on the clicked cell
        if cell["rect"].collidepoint(pos) and cell["name"]==game.target_name:
            _spawn_bits(fs,cell["cx"],cell["cy"],fall_col(cell["name"]),16)
    return False

# ── Draw ───────────────────────────────────────────────────────────────────────
def draw_fall(surf, fs, game):
    W,H=surf.get_size(); now=time.time(); t=pygame.time.get_ticks()/1000
    storming=fs["storm_start"] is not None
    cover=0.0
    if storming:
        el=(now-fs["storm_start"])/STORM_DURATION; cover=max(0.0,1-abs(el-0.5)*2)
    surf.blit(fall_background(W,H),(0,0))
    if game.flash_timer>0:
        fc=_FALL_BY_NEON.get(game.flash_color,game.flash_color)
        o=pygame.Surface((W,H),pygame.SRCALPHA); o.fill((*fc[:3],int(game.flash_timer/10*90)))
        surf.blit(o,(0,0)); game.flash_timer-=1
    # Board panel
    if game.grid:
        gx=min(c["rect"].left for c in game.grid); gy=min(c["rect"].top for c in game.grid)
        gr=max(c["rect"].right for c in game.grid); gb=max(c["rect"].bottom for c in game.grid)
        panel=pygame.Surface((gr-gx+28,gb-gy+28),pygame.SRCALPHA)
        pygame.draw.rect(panel,(25,10,8,150),panel.get_rect(),border_radius=18)
        pygame.draw.rect(panel,(150,85,45,160),panel.get_rect(),2,border_radius=18)
        surf.blit(panel,(gx-14,gy-14))
    # HUD
    lvl=WIND_LEVELS[fs["level"]]
    title=FONT_MED.render("MAPLE STORM BOSS" if game.boss_mode else "FALL MODE",True,
                          (255,110,50) if game.boss_mode else (235,170,100))
    surf.blit(title,title.get_rect(centerx=W//2,y=10))
    surf.blit(FONT_SM.render(f"Score: {fs['points']}",True,WHITE),(20,14))
    best=gd.get("high_scores",{}).get("fall",0)
    surf.blit(FONT_TINY.render(f"Best: {max(best,fs['points'])}",True,(210,170,120)),(20,44))
    m=fall_combo_mult(fs["combo"])
    if fs["combo"]>=3:
        cs=FONT_SM.render(f"x{m} COMBO ({fs['combo']})",True,(255,210,90))
        cs=pygame.transform.rotozoom(cs,0,1+0.05*math.sin(t*10)); surf.blit(cs,(20,64))
    draw_lives(surf,game.lives,W-15,14,(255,110,70),max(0,3-game.lives))
    wl=FONT_TINY.render(f"WIND: {lvl['name']}   STORMS: {fs['storms']}",True,lvl["col"])
    surf.blit(wl,wl.get_rect(right=W-15,y=48))
    # Command: autumn word, autumn ink (Stroop)
    word=FALL_NAME.get(game.target_name,game.target_name)
    ink=_FALL_BY_NEON.get(game.cmd_color,fall_col(game.target_name))
    cmd=FONT_BIG.render(f"FIND  {word}!",True,ink)
    sh=FONT_BIG.render(f"FIND  {word}!",True,(20,8,5))
    r=cmd.get_rect(centerx=W//2,y=70); surf.blit(sh,r.move(3,3)); surf.blit(cmd,r)
    # Timer bar
    rem=max(0,game.deadline-now); ratio=min(1.0,rem/game.time_limit) if game.time_limit>0 else 0
    bx,by,bw,bh=50,140,W-100,13
    pygame.draw.rect(surf,(40,20,12),(bx,by,bw,bh),border_radius=7)
    if int(bw*ratio)>0:
        bc=(150,190,60) if ratio>0.5 else (240,180,40) if ratio>0.25 else (230,60,40)
        pygame.draw.rect(surf,bc,(bx,by,int(bw*ratio),bh),border_radius=7)
    pygame.draw.rect(surf,(130,85,50),(bx,by,bw,bh),2,border_radius=7)
    # Storm meter: fills up as the next storm approaches
    if not storming and fs["intro"]<=0:
        gap=fall_storm_gap(fs,game.score); left=max(0,fs["next_storm"]-now)
        sr=1-min(1,left/gap); warn=left<=STORM_WARNING
        pygame.draw.rect(surf,(35,18,12),(bx,by+17,bw,6),border_radius=3)
        pygame.draw.rect(surf,(235,80,40) if warn else lvl["col"],(bx,by+17,int(bw*sr),6),border_radius=3)
        draw_maple(surf,bx+int(bw*sr),by+20,7,(255,200,120),t*6,255,False)
    # Cells — shake sideways while the storm blows
    for cell in game.grid:
        col=fall_col(cell["name"]); pulse=0.04*math.sin(t*2+cell["pulse"])
        r2=cell["rect"].inflate(int(pulse*cell["rect"].width),int(pulse*cell["rect"].height))
        if storming: r2=r2.move(int(math.sin(t*40+cell["cx"])*6*cover),int(math.cos(t*33+cell["cy"])*3*cover))
        pygame.draw.rect(surf,(col[0]//3,col[1]//3,col[2]//3),r2.move(0,4),border_radius=12)
        pygame.draw.rect(surf,col,r2,border_radius=12)
        hl=pygame.Surface((r2.width,r2.height//2),pygame.SRCALPHA)
        pygame.draw.rect(hl,(255,255,255,28),hl.get_rect(),border_radius=12); surf.blit(hl,r2.topleft)
        light=(min(255,col[0]+45),min(255,col[1]+45),min(255,col[2]+45))
        draw_maple(surf,r2.right-int(r2.height*0.22),r2.top+int(r2.height*0.24),
                   max(4,int(r2.height*0.13)),light,0.4+cell["pulse"]*0.2,150,True)
        pygame.draw.rect(surf,light,r2,2,border_radius=12)
        name=FALL_NAME[cell["name"]]
        lbl=FONT_TINY.render(name,True,_text_on(col)); surf.blit(lbl,lbl.get_rect(center=r2.center))
    # Golden leaf
    g=fs["gold"]
    if g:
        gl=pygame.Surface((g["r"]*5,g["r"]*5),pygame.SRCALPHA)
        pygame.draw.circle(gl,(255,210,70,int(55+35*math.sin(t*7))),(g["r"]*5//2,g["r"]*5//2),int(g["r"]*2.2))
        surf.blit(gl,(g["x"]-g["r"]*5//2,g["y"]-g["r"]*5//2))
        draw_maple(surf,g["x"],g["y"],g["r"],(255,205,45),math.sin(g["t"]*3)*0.5)
        for k in range(3):
            a=t*4+k*2.1; pygame.draw.circle(surf,(255,245,180),(int(g["x"]+math.cos(a)*g["r"]*1.4),int(g["y"]+math.sin(a)*g["r"]*1.4)),2)
    # Effects
    for b in fs["bits"]:
        draw_maple(surf,b["x"],b["y"],b["size"],b["col"],b["rot"],int(255*min(1,b["life"]*1.5)),False)
    draw_particles(surf)
    for p in fs["pops"]:
        ps=FONT_SM.render(p["t"],True,p["col"]); ps.set_alpha(int(255*min(1,p["life"]*1.6)))
        surf.blit(ps,ps.get_rect(center=(int(p["x"]),int(p["y"]))))
    # Warning
    if not storming and fs["intro"]<=0 and 0<fs["next_storm"]-now<=STORM_WARNING and int(t*6)%2==0:
        w=FONT_MED.render("STORM INCOMING",True,(255,175,70))
        box=w.get_rect(centerx=W//2,y=H-56).inflate(28,12)
        pygame.draw.rect(surf,(60,22,10),box,border_radius=10)
        pygame.draw.rect(surf,(255,140,50),box,2,border_radius=10)
        surf.blit(w,w.get_rect(center=box.center))
    # The storm itself
    if storming:
        o=pygame.Surface((W,H),pygame.SRCALPHA); o.fill((80,36,12,int(215*cover))); surf.blit(o,(0,0))
        for st in fs["streaks"]:
            pygame.draw.line(surf,(255,230,200),(int(st["x"]),int(st["y"])),(int(st["x"]-st["len"]),int(st["y"])),1)
        for lf in fs["storm_leaves"]:
            if -30<lf["x"]<W+30: draw_maple(surf,lf["x"],lf["y"],lf["size"],lf["col"],lf["rot"],235)
        if cover>0.35:
            z=1+0.15*cover
            st=pygame.transform.rotozoom(FONT_BIG.render("COLOR STORM!",True,(255,195,90)),math.sin(t*20)*3,z)
            surf.blit(st,st.get_rect(center=(W//2,H//2)))
    # Wind level banner
    if fs["banner"]:
        a=max(0,int(255*min(1,fs["banner"]["life"])))
        bs=FONT_MED.render(fs["banner"]["text"],True,lvl["col"]); bs.set_alpha(a)
        bb=pygame.Surface((bs.get_width()+40,bs.get_height()+18),pygame.SRCALPHA); bb.fill((30,10,6,min(200,a)))
        surf.blit(bb,bb.get_rect(center=(W//2,int(H*0.40)))); surf.blit(bs,bs.get_rect(center=(W//2,int(H*0.40))))
    # Intro
    if fs["intro"]>0:
        o=pygame.Surface((W,H),pygame.SRCALPHA); o.fill((20,8,6,190)); surf.blit(o,(0,0))
        n=int(math.ceil(fs["intro"]))
        t1=FONT_BIG.render("FALL MODE",True,(245,160,70)); surf.blit(t1,t1.get_rect(center=(W//2,int(H*0.24))))
        t2=FONT_MED.render("COLOR STORM",True,(220,120,60)); surf.blit(t2,t2.get_rect(center=(W//2,int(H*0.33))))
        frac=fs["intro"]-math.floor(fs["intro"])
        num=pygame.transform.rotozoom(FONT_BIG.render(str(n) if n<=3 else "3",True,(255,220,140)),0,1.4+frac*0.8)
        surf.blit(num,num.get_rect(center=(W//2,int(H*0.52))))
        for i,line in enumerate(["The colors of autumn: MAPLE, PUMPKIN, AMBER, MOSS, CHESTNUT, PLUM",
                                 "When the storm hits, every color on the board changes!",
                                 "Catch golden leaves for bonus time"]):
            ls=FONT_TINY.render(line,True,(230,200,160)); surf.blit(ls,ls.get_rect(center=(W//2,int(H*0.70)+i*26)))

def draw_fall_over(surf, fs, game, mouse):
    W,H=surf.get_size(); t=pygame.time.get_ticks()/1000
    surf.blit(fall_background(W,H),(0,0))
    o=pygame.Surface((W,H),pygame.SRCALPHA); o.fill((20,8,6,120)); surf.blit(o,(0,0))
    cw,ch=int(W*0.62),int(H*0.56); card=pygame.Rect(W//2-cw//2,int(H*0.16),cw,ch)
    cs=pygame.Surface(card.size,pygame.SRCALPHA)
    pygame.draw.rect(cs,(35,14,10,225),cs.get_rect(),border_radius=18)
    pygame.draw.rect(cs,(190,110,55),cs.get_rect(),2,border_radius=18); surf.blit(cs,card.topleft)
    draw_maple(surf,card.left+30,card.top+28,16,(200,42,30),t,255)
    draw_maple(surf,card.right-30,card.top+28,16,(245,128,25),-t,255)
    go=FONT_BIG.render("THE STORM WON",True,(245,125,55)); surf.blit(go,go.get_rect(centerx=W//2,y=int(H*0.05)))
    sc=FONT_BIG.render(str(fs["points"]),True,WHITE); surf.blit(sc,sc.get_rect(centerx=W//2,y=card.top+18))
    if fs["new_best"] and int(t*3)%2==0:
        nb=FONT_SM.render("NEW BEST!",True,(255,215,80)); surf.blit(nb,nb.get_rect(centerx=W//2,y=card.top+18+sc.get_height()))
    rows=[("Best",str(gd.get("high_scores",{}).get("fall",0))),("Storms survived",str(fs["storms"])),
          ("Golden leaves",str(fs["gold_got"])),("Best combo",f"{fs['best_combo']}  (x{fall_combo_mult(fs['best_combo'])})"),
          ("Strongest wind",WIND_LEVELS[fs["level"]]["name"])]
    y=card.top+int(ch*0.36)
    for k,v in rows:
        surf.blit(FONT_SM.render(k,True,(210,170,120)),(card.left+36,y))
        vs=FONT_SM.render(v,True,WHITE); surf.blit(vs,vs.get_rect(right=card.right-36,y=y)); y+=int(ch*0.11)
    b_fa=Button(W//2-130,int(H*0.76),260,52,"PLAY AGAIN",(160,80,20))
    b_fm=Button(W//2-100,int(H*0.86),200,44,"<  BACK",(70,38,22))
    for b in (b_fa,b_fm): b.update(mouse); b.draw(surf)
    return b_fa,b_fm


# =============================================================================
#  MENU UI — animated background, title, vector icons, cards
# =============================================================================
_ui_hover = {}
def ui_hover(key, target, dt):
    v=_ui_hover.get(key,0.0); v+=(target-v)*min(1.0,dt*12); _ui_hover[key]=v; return v

def _mix(a, b, k): return tuple(int(a[i]+(b[i]-a[i])*k) for i in range(3))

_font_cache2 = {}
def ui_font(size):
    size=max(8,int(size))
    if size not in _font_cache2: _font_cache2[size]=TFont(size)
    return _font_cache2[size]

def render_fit(font, text, col, maxw):
    s=font.render(text,True,col)
    if s.get_width()>maxw>0:
        s=pygame.transform.smoothscale(s,(int(maxw),max(1,int(s.get_height()*maxw/s.get_width()))))
    return s

_mask_cache = {}
def _round_mask(w, h, rad):
    k=(w,h,rad)
    if k not in _mask_cache:
        if len(_mask_cache)>80: _mask_cache.clear()
        m=pygame.Surface((w,h),pygame.SRCALPHA)
        pygame.draw.rect(m,(255,255,255,255),(0,0,w,h),border_radius=rad); _mask_cache[k]=m
    return _mask_cache[k]

_grad_cache = {}
def _card_grad(w, h, col, rad=16):
    k=(w,h,col,rad)
    if k not in _grad_cache:
        if len(_grad_cache)>80: _grad_cache.clear()
        s=pygame.Surface((w,h),pygame.SRCALPHA)
        top=_mix((12,12,22),col,0.34); bot=(10,10,18)
        for y in range(h): s.fill((*_mix(top,bot,y/max(1,h-1)),235),(0,y,w,1))
        s.blit(_round_mask(w,h,rad),(0,0),special_flags=pygame.BLEND_RGBA_MIN)
        _grad_cache[k]=s
    return _grad_cache[k]

_glow_cache = {}
def _glow(radius, col, alpha):
    k=(radius,col,alpha)
    if k not in _glow_cache:
        if len(_glow_cache)>60: _glow_cache.clear()
        s=pygame.Surface((radius*2,radius*2),pygame.SRCALPHA)
        for i in range(12,0,-1):
            pygame.draw.circle(s,(*col,int(alpha*(1-i/13))),(radius,radius),int(radius*i/12))
        _glow_cache[k]=s
    return _glow_cache[k]

# ── Background ─────────────────────────────────────────────────────────────────
_bg_base_cache = {}
_bg_words = [{"w":random.choice(COLOR_NAMES),"c":random.choice(list(NEON.values())),
              "x":random.random(),"y":random.random(),"v":random.uniform(0.01,0.03),
              "s":random.choice((0.05,0.07,0.09))} for _ in range(14)]
_word_surf_cache = {}
def draw_menu_bg(surf, t, accent=None):
    if "halloween_theme" in globals() and halloween_theme(): return draw_haunted_menu_bg(surf,t,accent)
    if "gold_theme" in globals() and gold_theme(): return draw_gold_menu_bg(surf,t,accent)
    if "winter_theme" in globals() and winter_theme(): return draw_winter_menu_bg(surf,t,accent)
    if "retro86_theme" in globals() and retro86_theme(): return draw_retro86_menu_bg(surf,t,accent)
    W,H=surf.get_size(); k=(W,H)
    if k not in _bg_base_cache:
        _bg_base_cache.clear(); b=pygame.Surface((W,H))
        for y in range(H): b.fill(_mix((7,7,18),(16,6,28),y/H),(0,y,W,1))
        _bg_base_cache[k]=b
    surf.blit(_bg_base_cache[k],(0,0))
    m=min(W,H); cols=list(NEON.values())
    if accent: cols=[accent]*2+cols[:3]
    for i,c in enumerate(cols[:5]):                        # drifting color orbs
        r=int(m*(0.28+0.06*math.sin(t*0.3+i)))
        x=W*(0.5+0.42*math.sin(t*0.07+i*1.9)); y=H*(0.45+0.35*math.cos(t*0.05+i*2.3))
        surf.blit(_glow(r,c,34),(x-r,y-r))
    for wd in _bg_words:                                   # floating Stroop words
        wd["y"]-=wd["v"]*0.016
        if wd["y"]<-0.1: wd["y"]=1.1; wd["x"]=random.random(); wd["w"]=random.choice(COLOR_NAMES)
        size=int(m*wd["s"]); key=(wd["w"],wd["c"],size,lang_code())
        if key not in _word_surf_cache:
            if len(_word_surf_cache)>60: _word_surf_cache.clear()
            ws=ui_font(size).render(wd["w"],True,wd["c"]); ws.set_alpha(26); _word_surf_cache[key]=ws
        surf.blit(_word_surf_cache[key],(int(wd["x"]*W),int(wd["y"]*H)))
    hz=int(H*0.64); gc=accent or (90,60,190)               # synthwave floor
    for i in range(12):
        p=((i+(t*0.45)%1)/12); y=hz+int((H-hz)*p*p)
        pygame.draw.line(surf,_mix((10,8,22),gc,0.15+0.45*p),(0,y),(W,y),1)
    for j in range(-12,13):
        pygame.draw.line(surf,_mix((10,8,22),gc,0.28),(W//2+j*W*0.015,hz),(W//2+j*W*0.16,H),1)
    fade=pygame.Surface((W,24),pygame.SRCALPHA)
    for y in range(24): fade.fill((12,7,24,int(255*(1-y/24))),(0,y,W,1))
    surf.blit(fade,(0,hz))
    if "spooky_menu" in globals() and haunt_state()=="active": draw_spooky_overlay(surf,t)

# ── Title ──────────────────────────────────────────────────────────────────────
def draw_title(surf, t, y, scale=1.0):
    if "halloween_theme" in globals() and halloween_theme(): return draw_haunted_title(surf,t,y,scale)
    if "gold_theme" in globals() and gold_theme(): return draw_gold_title(surf,t,y,scale)
    if "winter_theme" in globals() and winter_theme(): return draw_winter_title(surf,t,y,scale)
    if "retro86_theme" in globals() and retro86_theme(): return draw_retro86_title(surf,t,y,scale)
    W,H=surf.get_size(); m=min(W,H)
    f1=ui_font(m*0.15*scale); cols=list(NEON.values())
    letters=[f1.render(ch,True,cols[(i+int(t*1.4))%6]) for i,ch in enumerate("COLOR")]
    tw=sum(l.get_width() for l in letters)+6*4; x=W//2-tw//2
    for i,l in enumerate(letters):
        dy=int(math.sin(t*2.4+i*0.7)*4*scale)
        sh=f1.render("COLOR"[i],True,(0,0,0)); sh.set_alpha(120); surf.blit(sh,(x+3,y+dy+5))
        surf.blit(l,(x,y+dy)); x+=l.get_width()+6
    f2=ui_font(m*0.075*scale); y2=y+int(m*0.12*scale)
    glitch=(t*1.3)%6<0.12
    jx=random.randint(-6,6) if glitch else 0
    for off,c,a in ((-2,(255,40,90),150),(2,(40,160,255),150)):
        g=f2.render("UNDER PRESSURE",True,c); g.set_alpha(a); surf.blit(g,g.get_rect(centerx=W//2+off+jx,y=y2))
    u=f2.render("UNDER PRESSURE",True,WHITE); surf.blit(u,u.get_rect(centerx=W//2+jx,y=y2))
    f3=ui_font(m*0.03*scale); st=f3.render("R U S H Y   S T U D I O S",True,(120,120,170))
    r=st.get_rect(centerx=W//2,y=y2+u.get_height()+6); surf.blit(st,r)
    pygame.draw.line(surf,(60,60,100),(r.left-60,r.centery),(r.left-12,r.centery),1)
    pygame.draw.line(surf,(60,60,100),(r.right+12,r.centery),(r.right+60,r.centery),1)
    return r.bottom

def draw_header(surf, title, sub, col, t):
    if "halloween_theme" in globals() and halloween_theme(): return _ht_header(surf,title,sub,col,t)
    if "gold_theme" in globals() and gold_theme(): col=gold_col(col)
    elif "winter_theme" in globals() and winter_theme(): col=winter_col(col)
    elif "retro86_theme" in globals() and retro86_theme(): col=retro86_col(col)
    W,H=surf.get_size(); m=min(W,H)
    f=ui_font(m*0.10); s=f.render(title,True,WHITE); r=s.get_rect(centerx=W//2,y=int(H*0.04))
    g=f.render(title,True,col); g.set_alpha(110); surf.blit(g,r.move(3,3)); surf.blit(s,r)
    bw=int(r.width*(0.5+0.5*abs(math.sin(t*1.2))))
    pygame.draw.rect(surf,col,(W//2-bw//2,r.bottom+6,bw,3),border_radius=2)
    if sub:
        ss=ui_font(m*0.034).render(sub,True,(150,150,190)); surf.blit(ss,ss.get_rect(centerx=W//2,y=r.bottom+16))
    return r.bottom+16+int(m*0.04)

# ── Vector icons ───────────────────────────────────────────────────────────────
_HOLE=(16,12,26)
def ui_icon(surf, name, cx, cy, s, col, t=0.0):
    cx,cy=int(cx),int(cy); s=max(6,int(s)); lw=max(2,s//6)
    P=lambda pts:[(cx+a*s,cy+b*s) for a,b in pts]
    if name=="play":
        pygame.draw.polygon(surf,col,P([(-0.55,-0.8),(-0.55,0.8),(0.85,0)]))
    elif name=="globe":
        pygame.draw.circle(surf,col,(cx,cy),s,lw)
        pygame.draw.ellipse(surf,col,(cx-s*0.45,cy-s,s*0.9,s*2),lw)
        pygame.draw.line(surf,col,(cx-s,cy),(cx+s,cy),lw)
        for yy in (-0.5,0.5): pygame.draw.line(surf,col,(cx-s*0.85,cy+yy*s),(cx+s*0.85,cy+yy*s),max(1,lw-1))
    elif name=="ticket":
        pygame.draw.rect(surf,col,(cx-s,cy-s*0.62,s*2,s*1.24),border_radius=max(3,s//5))
        for sx in (-1,1): pygame.draw.circle(surf,_HOLE,(cx+sx*s,cy),int(s*0.24))
        for yy in range(-3,4,2): pygame.draw.line(surf,_HOLE,(cx+s*0.35,cy+yy*s*0.15),(cx+s*0.35,cy+(yy+1)*s*0.15),max(1,lw-1))
        pts=[]
        for i in range(10):
            a=-math.pi/2+i*math.pi/5; r=s*(0.34 if i%2==0 else 0.15)
            pts.append((cx-s*0.3+math.cos(a)*r,cy+math.sin(a)*r))
        pygame.draw.polygon(surf,_HOLE,pts)
    elif name=="folder":
        pygame.draw.polygon(surf,col,P([(-1,-0.62),(-0.35,-0.62),(-0.2,-0.42),(1,-0.42),(1,0.72),(-1,0.72)]))
        pygame.draw.line(surf,_HOLE,(cx-s,cy-s*0.22),(cx+s,cy-s*0.22),max(1,lw-1))
    elif name=="gear":
        pts=[]
        for i in range(32):
            a=t*0.6+i*2*math.pi/32; r=s if (i//2)%2==0 else s*0.74
            pts.append((cx+math.cos(a)*r,cy+math.sin(a)*r))
        pygame.draw.polygon(surf,col,pts); pygame.draw.circle(surf,_HOLE,(cx,cy),int(s*0.34))
    elif name=="trophy":
        pygame.draw.polygon(surf,col,P([(-0.7,-0.85),(0.7,-0.85),(0.52,0.05),(0.16,0.3),(-0.16,0.3),(-0.52,0.05)]))
        for sx in (-1,1): pygame.draw.circle(surf,col,(int(cx+sx*s*0.72),int(cy-s*0.48)),int(s*0.3),lw)
        pygame.draw.rect(surf,col,(cx-s*0.12,cy+s*0.28,s*0.24,s*0.34))
        pygame.draw.rect(surf,col,(cx-s*0.5,cy+s*0.6,s,s*0.26),border_radius=3)
        pygame.draw.circle(surf,_HOLE,(cx,int(cy-s*0.35)),int(s*0.16))
    elif name=="gamepad":
        pygame.draw.rect(surf,col,(cx-s,cy-s*0.55,s*2,s*1.1),border_radius=int(s*0.5))
        pygame.draw.rect(surf,_HOLE,(cx-s*0.72,cy-s*0.08,s*0.5,s*0.16))
        pygame.draw.rect(surf,_HOLE,(cx-s*0.55,cy-s*0.25,s*0.16,s*0.5))
        for dx,dy in ((0.45,-0.12),(0.68,0.1)): pygame.draw.circle(surf,_HOLE,(int(cx+dx*s),int(cy+dy*s)),max(2,int(s*0.12)))
    elif name=="leaf":
        draw_maple(surf,cx,cy,s*0.95,col,math.sin(t*2)*0.25)
    elif name=="sun":
        pygame.draw.circle(surf,col,(cx,cy),int(s*0.46))
        for i in range(8):
            a=t*0.5+i*math.pi/4
            pygame.draw.line(surf,col,(cx+math.cos(a)*s*0.62,cy+math.sin(a)*s*0.62),(cx+math.cos(a)*s,cy+math.sin(a)*s),lw)
    elif name=="skull":
        pygame.draw.circle(surf,col,(cx,int(cy-s*0.15)),int(s*0.78))
        pygame.draw.rect(surf,col,(cx-s*0.45,cy+s*0.3,s*0.9,s*0.5),border_radius=4)
        for sx in (-1,1): pygame.draw.circle(surf,_HOLE,(int(cx+sx*s*0.32),int(cy-s*0.15)),int(s*0.22))
        for i in (-1,0,1): pygame.draw.line(surf,_HOLE,(cx+i*s*0.2,cy+s*0.45),(cx+i*s*0.2,cy+s*0.8),max(1,lw-1))
    elif name=="flow":
        a=(cx-s*0.7,cy+s*0.55); b=(cx+s*0.7,cy-s*0.55)
        pygame.draw.lines(surf,col,False,[a,(cx-s*0.7,cy-s*0.55),b],lw+2)
        for p,c2 in ((a,NEON["RED"]),(b,NEON["RED"])): pygame.draw.circle(surf,c2,(int(p[0]),int(p[1])),int(s*0.3))
        a2=(cx-s*0.1,cy+s*0.55); b2=(cx+s*0.7,cy+s*0.1)
        pygame.draw.lines(surf,NEON["BLUE"],False,[a2,(cx+s*0.7,cy+s*0.55),b2],lw+2)
        for p in (a2,b2): pygame.draw.circle(surf,NEON["BLUE"],(int(p[0]),int(p[1])),int(s*0.24))
    elif name=="book":
        pygame.draw.polygon(surf,col,P([(0,-0.6),(-1,-0.8),(-1,0.7),(0,0.9)]))
        pygame.draw.polygon(surf,_mix(col,WHITE,0.3),P([(0,-0.6),(1,-0.8),(1,0.7),(0,0.9)]))
        for yy in (-0.35,-0.05,0.25): pygame.draw.line(surf,_HOLE,(cx+s*0.2,cy+yy*s),(cx+s*0.8,cy+(yy-0.1)*s),max(1,lw-1))
    elif name=="swords":
        for sx in (-1,1):
            pygame.draw.line(surf,col,(cx-sx*s*0.85,cy-s*0.85),(cx+sx*s*0.55,cy+s*0.55),lw+1)
            gx,gy=cx+sx*s*0.45,cy+s*0.45
            pygame.draw.line(surf,col,(gx-s*0.28,gy+sx*0.0-s*0.28*sx),(gx+s*0.28,gy+s*0.28*sx),lw)
            pygame.draw.circle(surf,col,(int(cx+sx*s*0.78),int(cy+s*0.78)),max(2,int(s*0.14)))
    elif name=="back":
        pygame.draw.line(surf,col,(cx-s*0.6,cy),(cx+s*0.8,cy),lw+1)
        pygame.draw.polygon(surf,col,P([(-0.95,0),(-0.35,-0.55),(-0.35,0.55)]))
    elif name=="power":
        pygame.draw.arc(surf,col,(cx-s*0.8,cy-s*0.7,s*1.6,s*1.6),math.radians(120),math.radians(420),lw+1)
        pygame.draw.line(surf,col,(cx,cy-s*0.95),(cx,cy-s*0.1),lw+1)
    elif name=="tape":
        pygame.draw.rect(surf,col,(cx-s,cy-s*0.62,s*2,s*1.24),border_radius=4)
        for sx in (-1,1): pygame.draw.circle(surf,_HOLE,(int(cx+sx*s*0.45),cy),int(s*0.28))
    elif name=="store":
        for i,(dx,dy) in enumerate(((-1,-1),(1,-1),(-1,1),(1,1))):
            c2=[(242,80,34),(127,186,0),(0,164,239),(255,185,0)][i]
            pygame.draw.rect(surf,c2,(cx+(dx-1)*s*0.5+ (2 if dx>0 else -2)//2,cy+(dy-1)*s*0.5+(2 if dy>0 else -2)//2,s*0.9,s*0.9))
    elif name=="itch":
        pygame.draw.rect(surf,col,(cx-s,cy-s*0.3,s*2,s*1.1),border_radius=3)
        pygame.draw.polygon(surf,col,P([(-1.05,-0.35),(-0.8,-0.85),(0.8,-0.85),(1.05,-0.35)]))
        for sx in (-0.4,0.4): pygame.draw.circle(surf,_HOLE,(int(cx+sx*s),int(cy+s*0.2)),max(2,int(s*0.16)))

# ── Card / pill / chips ────────────────────────────────────────────────────────
def ui_card(surf, key, rect, col, icon, title, sub, t, dt, mouse, tag=None, extra=None, big=False, locked=False):
    if globals().get("BUILD_DEMO") and key in DEMO_LOCK_CARDS and not dev_mode(): locked=True; tag="FULL GAME"; extra="Wishlist on Steam"
    elif key in globals().get("GUEST_LOCK_CARDS",()) and is_guest(): locked=True; tag="ACCOUNT"; extra="Sign in to play"
    if "halloween_theme" in globals() and halloween_theme(): return _ht_card(surf,key,rect,col,icon,title,sub,t,dt,mouse,tag,extra,big,locked)
    if "gold_theme" in globals() and gold_theme(): col=gold_col(col)
    elif "winter_theme" in globals() and winter_theme(): col=winter_col(col)
    elif "retro86_theme" in globals() and retro86_theme(): col=retro86_col(col)
    _ht=False
    hov=rect.collidepoint(mouse) and not locked
    h=ui_hover(key,1.0 if hov else 0.0,dt)
    r=rect.move(0,-int(7*h)); W,H=surf.get_size(); rad=18
    sh=pygame.Surface((r.w,r.h),pygame.SRCALPHA); pygame.draw.rect(sh,(0,0,0,110),sh.get_rect(),border_radius=rad)
    surf.blit(sh,(r.x,r.y+10+int(4*h)))
    if h>0.02:
        g=pygame.Surface((r.w+36,r.h+36),pygame.SRCALPHA)
        for i in range(4): pygame.draw.rect(g,(*col,int(22*h)),(i*4,i*4,r.w+36-i*8,r.h+36-i*8),border_radius=rad+12-i*3)
        surf.blit(g,(r.x-18,r.y-18))
    c=col if not locked else (70,70,90)
    surf.blit(_card_grad(r.w,r.h,c,rad),r.topleft)
    if h>0.25:                                            # shine sweep
        sw=pygame.Surface((r.w,r.h),pygame.SRCALPHA)
        px=int(((t*0.9)%1.6-0.3)*r.w)
        pygame.draw.polygon(sw,(255,255,255,int(30*h)),[(px,0),(px+r.w*0.18,0),(px-r.w*0.12,r.h),(px-r.w*0.3,r.h)])
        sw.blit(_round_mask(r.w,r.h,rad),(0,0),special_flags=pygame.BLEND_RGBA_MIN); surf.blit(sw,r.topleft)
    bar=int((r.w-2*rad)*(0.35+0.65*(0.5+0.5*math.sin(t*1.6+r.x*0.01))))
    pygame.draw.rect(surf,c,(r.centerx-bar//2,r.y+5,bar,3),border_radius=2)
    pygame.draw.rect(surf,_mix(c,WHITE,0.45*h),r,2,border_radius=rad)
    m=min(r.w,r.h)
    isz=m*(0.22 if big else 0.17)*(1+0.08*h)
    iy=r.y+r.h*(0.34 if big else 0.33)+math.sin(t*2+r.x)*3*h
    surf.blit(_glow(int(isz*1.9),c,70),(r.centerx-int(isz*1.9),iy-int(isz*1.9)))
    ui_icon2(surf,icon,r.centerx,iy,isz,_mix(c,WHITE,0.25) if not locked else (90,90,110),t)
    tf=ui_font(min(W,H)*(0.085 if big else 0.052))
    ts=render_fit(tf,title,WHITE if not locked else (120,120,140),r.w-24)
    surf.blit(ts,ts.get_rect(centerx=r.centerx,y=int(r.y+r.h*(0.58 if big else 0.60))))
    if sub:
        ss=render_fit(ui_font(min(W,H)*0.029),sub,(185,185,215) if not locked else (100,100,120),r.w-24)
        surf.blit(ss,ss.get_rect(centerx=r.centerx,y=int(r.y+r.h*(0.58 if big else 0.60))+ts.get_height()+6))
    if extra:
        es=render_fit(ui_font(min(W,H)*0.028),extra,_mix(c,WHITE,0.35),r.w-24)
        surf.blit(es,es.get_rect(centerx=r.centerx,bottom=r.bottom-12))
    if tag:
        tf2=ui_font(min(W,H)*0.026); tsf=tf2.render(tag,True,(20,12,8))
        tr=tsf.get_rect(topright=(r.right-12,r.y+12)).inflate(14,6)
        pul=0.5+0.5*math.sin(t*5)
        pygame.draw.rect(surf,_mix(c,WHITE,0.3+0.3*pul),tr,border_radius=tr.h//2)
        surf.blit(tsf,tsf.get_rect(center=tr.center))
    if locked:
        ls=ui_font(min(W,H)*0.03).render("LOCKED",True,(150,150,170)); surf.blit(ls,ls.get_rect(center=(r.centerx,r.y+r.h*0.2)))
    if _ht: draw_cobweb(surf,r.x+2,r.y+2,int(min(r.w,r.h)*0.28)); draw_cobweb(surf,r.right-2,r.y+2,int(min(r.w,r.h)*0.18),True,60)
    return r

def ui_pill(surf, key, rect, text, col, dt, mouse, icon=None):
    if "halloween_theme" in globals() and halloween_theme(): return _ht_pill(surf,key,rect,text,col,dt,mouse,icon)
    if "gold_theme" in globals() and gold_theme(): col=gold_col(col)
    elif "winter_theme" in globals() and winter_theme(): col=winter_col(col)
    elif "retro86_theme" in globals() and retro86_theme(): col=retro86_col(col)
    h=ui_hover(key,1.0 if rect.collidepoint(mouse) else 0.0,dt)
    r=rect.inflate(int(6*h),int(4*h))
    pygame.draw.rect(surf,_mix((14,14,26),col,0.35+0.35*h),r,border_radius=r.h//2)
    pygame.draw.rect(surf,_mix(col,WHITE,0.3*h),r,2,border_radius=r.h//2)
    f=ui_font(min(surf.get_size())*0.032); s=f.render(text,True,WHITE)
    if not icon and s.get_width()>r.w-16: s=render_fit(f,text,WHITE,r.w-16)      # long words fit inside small pills
    if icon:
        isz=r.h*0.26; total=isz*2+8+s.get_width(); x0=r.centerx-total/2
        ui_icon2(surf,icon,x0+isz,r.centery,isz,WHITE)
        surf.blit(s,s.get_rect(midleft=(x0+isz*2+8,r.centery)))
    else: surf.blit(s,s.get_rect(center=r.center))
    return r

def ui_back(surf, dt, mouse):
    W,H=surf.get_size(); r=pygame.Rect(20,H-62,150,42)
    ui_pill(surf,"back",r,"BACK",(90,90,140),dt,mouse,"back"); return r

def draw_equipped_badge(surf, cx, cy, r):
    """The one badge the player chose to show off (EQUIP in the badge window)."""
    bid=gd.get("equipped_badge")
    if not bid or not has_badge(bid): return False
    b=get_badge(bid)
    if not b: return False
    draw_badge_medal(surf,b,int(cx),int(cy),int(r),True,pygame.time.get_ticks()/1000,0.0); return True

def ui_profile(surf, x, y):
    pn=gd.get("player_name","Player"); rp=gd.get("rank_points",0); rname,rcol=get_rank(rp); co=gd.get("coins",0)
    _gst=is_guest()
    if _gst: pn="Guest"
    W,H=surf.get_size(); w=int(min(300,W*0.32)); h=58
    p=pygame.Surface((w,h),pygame.SRCALPHA)
    pygame.draw.rect(p,(16,16,32,210),p.get_rect(),border_radius=16)
    pygame.draw.rect(p,(*rcol,160),p.get_rect(),2,border_radius=16); surf.blit(p,(x,y))
    pygame.draw.circle(surf,rcol,(x+30,y+29),21); pygame.draw.circle(surf,WHITE,(x+30,y+29),21,2)
    ini=ui_font(30).render((pn[:1] or "P").upper(),True,(20,15,30)); surf.blit(ini,ini.get_rect(center=(x+30,y+30)))
    draw_equipped_badge(surf,x+48,y+44,12)
    title=gd.get("current_title","")
    ns=render_fit(ui_font(26),(f'"{title}" ' if title else "")+pn,WHITE,w-130); surf.blit(ns,(x+60,y+9))
    rs=render_fit(ui_font(19),"Not saved • sign in!" if _gst else f"{rname}  {rp} RP",(255,150,60) if _gst else rcol,w-130); surf.blit(rs,(x+60,y+35))
    pygame.draw.circle(surf,(255,200,40),(x+w-52,y+29),10); pygame.draw.circle(surf,(200,140,20),(x+w-52,y+29),10,2)
    cs=ui_font(22).render(str(co),True,(255,220,90)); surf.blit(cs,(x+w-38,y+21))

def draw_rank_emblem(surf, cx, cy, s, rname, rcol, t):
    pts=[(cx,cy-s),(cx+s*0.85,cy-s*0.6),(cx+s*0.75,cy+s*0.35),(cx,cy+s),(cx-s*0.75,cy+s*0.35),(cx-s*0.85,cy-s*0.6)]
    surf.blit(_glow(int(s*1.8),rcol,60),(cx-int(s*1.8),cy-int(s*1.8)))
    pygame.draw.polygon(surf,_mix(rcol,(0,0,0),0.55),pts)
    inner=[(cx+(x-cx)*0.8,cy+(y-cy)*0.8) for x,y in pts]
    pygame.draw.polygon(surf,rcol,inner,3); pygame.draw.polygon(surf,rcol,pts,3)
    tier=rname.split()[-1] if len(rname.split())>1 else ""
    ls=ui_font(s*0.9).render(rname[:1],True,WHITE); surf.blit(ls,ls.get_rect(center=(cx,cy-s*0.08)))
    if tier:
        ts=ui_font(s*0.36).render(tier,True,_mix(rcol,WHITE,0.5)); surf.blit(ts,ts.get_rect(center=(cx,cy+s*0.52)))
    a=t*1.5
    for i in range(3):
        aa=a+i*2.09; pygame.draw.circle(surf,_mix(rcol,WHITE,0.6),(int(cx+math.cos(aa)*s*1.15),int(cy+math.sin(aa)*s*1.15)),3)

def ui_click(events, rect):
    return any(ev.type==pygame.MOUSEBUTTONDOWN and ev.button==1 and rect.collidepoint(ev.pos) for ev in events)

def ui_esc(events):
    return any(ev.type==pygame.KEYDOWN and ev.key==pygame.K_ESCAPE for ev in events)


