BADGE_FX = {"hell_of_colors":"spin","galaxy_keeper":"spin","rng_dev":"spin","rainbow":"spin"}
for _b in ALL_BADGES:
    if _b["cat"] in ("legacy","unlisted") or _b["id"] in ("golden_ticket","ranked_legend","flawless_flow","mansion_master","classic_clear","survival_clear","not_good_game",
                                                          "coin_rain","tournament_winner","untouchable","flow_speedrun"):
        BADGE_FX.setdefault(_b["id"],"shine")
def badge_grad(b):
    return BADGE_GRAD.get(b["id"]) or [CAT_COL.get(b["cat"],WHITE),_mix(CAT_COL.get(b["cat"],WHITE),(0,0,0),0.55)]
_GRAD_CACHE={}
def _grad_surf(w,h,cols,ang=35):
    """Smooth multi-color gradient at an angle (cached)."""
    key=(w,h,tuple(map(tuple,cols)),int(ang)%360)
    g=_GRAD_CACHE.get(key)
    if g is None:
        strip=pygame.Surface((len(cols),1))
        for i,c in enumerate(cols): strip.set_at((i,0),c)
        D=int(math.hypot(w,h))+4
        big=pygame.transform.smoothscale(pygame.transform.scale(strip,(len(cols)*8,1)),(D,D))
        rot=pygame.transform.rotate(big,ang)
        g=pygame.Surface((w,h)); g.blit(rot,(w//2-rot.get_width()//2,h//2-rot.get_height()//2))
        if len(_GRAD_CACHE)>600: _GRAD_CACHE.clear()
        _GRAD_CACHE[key]=g
    return g
def _grad_shape(S,cols,poly,ang=35,dark=0.8):
    g=_grad_surf(S,S,cols,ang).convert_alpha() if pygame.display.get_surface() else _grad_surf(S,S,cols,ang).copy()
    out=pygame.Surface((S,S),pygame.SRCALPHA); out.blit(g,(0,0))
    if dark<1: out.fill((int(255*dark),)*3,special_flags=pygame.BLEND_RGB_MULT)
    m=pygame.Surface((S,S),pygame.SRCALPHA)
    if poly: pygame.draw.polygon(m,(255,255,255,255),poly)
    else: pygame.draw.circle(m,(255,255,255,255),(S//2,S//2),S//2)
    out.blit(m,(0,0),special_flags=pygame.BLEND_RGBA_MIN); return out
def grad_text(font,text,cols,maxw=None,ang=0):
    """Text painted with a real gradient (like the DOORS achievement names)."""
    base=render_fit(font,text,WHITE,maxw) if maxw else font.render(text,True,WHITE)
    w,h=base.get_size(); w,h=max(1,w),max(1,h)
    g=pygame.Surface((w,h),pygame.SRCALPHA); g.blit(_grad_surf(w,h,cols,ang),(0,0))
    g.blit(base,(0,0),special_flags=pygame.BLEND_RGBA_MIN)
    out=pygame.Surface((w+2,h+2),pygame.SRCALPHA); sh=base.copy(); sh.fill((0,0,0,170),special_flags=pygame.BLEND_RGBA_MULT)
    out.blit(sh,(2,2)); out.blit(g,(0,0)); return out
def grad_rect(surf,rect,cols,width=3,radius=14,ang=0,fill=None):
    """Rounded rect with a gradient border (and an optional gradient fill, 0..255 brightness)."""
    r=pygame.Rect(rect); g=_grad_surf(r.w,r.h,cols,ang).copy()
    out=pygame.Surface(r.size,pygame.SRCALPHA)
    if fill is not None:
        f=g.copy(); f.fill((fill,fill,fill),special_flags=pygame.BLEND_RGB_MULT); fm=pygame.Surface(r.size,pygame.SRCALPHA)
        pygame.draw.rect(fm,(255,255,255,255),fm.get_rect(),border_radius=radius); tmp=pygame.Surface(r.size,pygame.SRCALPHA); tmp.blit(f,(0,0)); tmp.blit(fm,(0,0),special_flags=pygame.BLEND_RGBA_MIN); out.blit(tmp,(0,0))
    bm=pygame.Surface(r.size,pygame.SRCALPHA); pygame.draw.rect(bm,(255,255,255,255),bm.get_rect(),width,border_radius=radius)
    tmp=pygame.Surface(r.size,pygame.SRCALPHA); tmp.blit(g,(0,0)); tmp.blit(bm,(0,0),special_flags=pygame.BLEND_RGBA_MIN); out.blit(tmp,(0,0))
    surf.blit(out,r.topleft)
def badge_frame(b,t):
    return int(t*8)%24 if BADGE_FX.get(b["id"])=="spin" else 0
_SHINE_MASK={}
def _badge_shine(surf,b,m,x,y,t):
    """A diagonal light sweeping over the medal every few seconds."""
    S=m.get_width(); k=(t*0.45+(hash(b["id"])%100)/100)%1.6
    if k>1: return
    msk=_SHINE_MASK.get(id(m))
    if msk is None:
        msk=m.copy(); msk.fill((255,255,255),special_flags=pygame.BLEND_RGB_MAX)
        if len(_SHINE_MASK)>500: _SHINE_MASK.clear()
        _SHINE_MASK[id(m)]=msk
    band=pygame.Surface((S,S),pygame.SRCALPHA); bx=-S+k*S*2.2
    pygame.draw.polygon(band,(255,255,255,120),[(bx,0),(bx+S*0.22,0),(bx+S*0.22-S*0.5,S),(bx-S*0.5,S)])
    pygame.draw.polygon(band,(255,255,255,60),[(bx+S*0.28,0),(bx+S*0.36,0),(bx+S*0.36-S*0.5,S),(bx+S*0.28-S*0.5,S)])
    band.blit(msk,(0,0),special_flags=pygame.BLEND_RGBA_MIN); surf.blit(band,(x,y))

def draw_lives(surf, full, right, top, col=(255,80,80), empty=0):
    """Hearts drawn as icons (the game font has no ♥ glyph, it showed boxes)."""
    full=max(0,int(full)); empty=max(0,int(empty)); n=full+empty
    if n<=0: return
    s=max(7,int(min(WIDTH,HEIGHT)*0.017)); step=int(s*2.6); cy=int(top)+int(s*1.4)
    x=int(right)-step*n+step//2
    for k in range(n):
        ui_icon2(surf,"heart",x,cy,s,col if k<full else (70,60,85)); x+=step

def ui_icon2(surf, name, cx, cy, s, col, t=0.0):
    """Extra icons (badges); falls back to ui_icon."""
    cx,cy=int(cx),int(cy); s=max(6,int(s)); lw=max(2,s//6)
    P=lambda pts:[(cx+a*s,cy+b*s) for a,b in pts]
    if name=="bolt":
        pygame.draw.polygon(surf,col,P([(0.15,-1),(-0.55,0.1),(-0.05,0.1),(-0.2,1),(0.55,-0.15),(0.05,-0.15)]))
    elif name=="star":
        pts=[]
        for i in range(10):
            a=-math.pi/2+i*math.pi/5; r=s*(1 if i%2==0 else 0.45); pts.append((cx+math.cos(a)*r,cy+math.sin(a)*r))
        pygame.draw.polygon(surf,col,pts)
    elif name=="flame":
        pygame.draw.polygon(surf,col,P([(0,-1),(0.5,-0.2),(0.7,0.35),(0.4,0.85),(0,1),(-0.4,0.85),(-0.7,0.35),(-0.45,-0.1),(-0.2,0.1)]))
        pygame.draw.polygon(surf,_mix(col,WHITE,0.5),P([(0,-0.2),(0.3,0.35),(0.2,0.75),(0,0.85),(-0.2,0.75),(-0.3,0.4)]))
    elif name=="shield":
        pygame.draw.polygon(surf,col,P([(0,-1),(0.85,-0.65),(0.75,0.3),(0,1),(-0.75,0.3),(-0.85,-0.65)]))
        pygame.draw.polygon(surf,_HOLE,P([(0,-0.6),(0.5,-0.4),(0.45,0.2),(0,0.6),(-0.45,0.2),(-0.5,-0.4)]),lw)
    elif name=="heart":
        for sx in (-1,1): pygame.draw.circle(surf,col,(int(cx+sx*s*0.45),int(cy-s*0.25)),int(s*0.5))
        pygame.draw.polygon(surf,col,P([(-0.93,-0.1),(0.93,-0.1),(0,0.95)]))
    elif name=="crown":
        pygame.draw.polygon(surf,col,P([(-0.95,0.6),(-0.95,-0.5),(-0.45,0.05),(0,-0.8),(0.45,0.05),(0.95,-0.5),(0.95,0.6)]))
        for x in (-0.95,0,0.95): pygame.draw.circle(surf,_mix(col,WHITE,0.5),(int(cx+x*s),int(cy+(-0.8 if x==0 else -0.5)*s)),max(2,s//7))
    elif name=="calendar":
        pygame.draw.rect(surf,col,(cx-s*0.9,cy-s*0.7,s*1.8,s*1.6),border_radius=4)
        pygame.draw.rect(surf,_HOLE,(cx-s*0.75,cy-s*0.3,s*1.5,s*1.05),border_radius=2)
        for i in range(7):
            pygame.draw.circle(surf,col,(int(cx-s*0.55+(i%4)*s*0.37),int(cy-s*0.05+(i//4)*s*0.45)),max(1,s//9))
        for sx in (-0.45,0.45): pygame.draw.line(surf,col,(cx+sx*s,cy-s*0.95),(cx+sx*s,cy-s*0.55),lw)
    elif name=="tree":
        pygame.draw.rect(surf,_mix(col,(0,0,0),0.4),(cx-s*0.14,cy+s*0.1,s*0.28,s*0.9))
        for dx,dy,r in ((0,-0.35,0.55),(-0.45,0.0,0.4),(0.45,0.0,0.4),(0,-0.8,0.35)):
            pygame.draw.circle(surf,col,(int(cx+dx*s),int(cy+dy*s)),int(r*s))
    elif name=="clock":
        pygame.draw.circle(surf,col,(cx,cy),s,lw+1)
        pygame.draw.line(surf,col,(cx,cy),(cx,cy-s*0.6),lw+1)
        a=t*1.5; pygame.draw.line(surf,col,(cx,cy),(cx+math.cos(a)*s*0.45,cy+math.sin(a)*s*0.45),lw)
    elif name=="eye":
        pygame.draw.ellipse(surf,col,(cx-s,cy-s*0.55,s*2,s*1.1))
        pygame.draw.circle(surf,_HOLE,(cx,cy),int(s*0.42)); pygame.draw.circle(surf,(255,40,40),(cx,cy),int(s*0.2))
    elif name=="door":
        pygame.draw.rect(surf,col,(cx-s*0.6,cy-s,s*1.2,s*2),border_radius=3)
