def dev_mode():
    """DEV MODE for everyone (DEV_MODE=True) or only for the developer accounts in DEV_USERS."""
    if DEV_MODE: return True
    a=globals().get("AUTH_STATE",{}); u=a.get("user")
    return bool(u and u.get("name_key",u.get("uid","")).lower() in DEV_USERS and a.get("dev_ok"))

_FROST_SHOWN = {"v": FROST_ENABLED}
def _frost_sync(vis):
    """The Deep Freeze skin lives in SKINS only while FIRST FROST is visible. Both directions,
    so signing out of a DEV account puts it away again."""
    if vis == _FROST_SHOWN["v"]: return
    _FROST_SHOWN["v"] = vis
    if vis:
        if _FROST_SKIN is not None: SKINS["Deep Freeze"] = _FROST_SKIN
    else:
        SKINS.pop("Deep Freeze", None)

def frost_visible():
    """FIRST FROST is hidden from players until 15/11 - a DEV account sees it today.
    This is the ONLY question the rest of the game should ask about the event."""
    v = True if FROST_ENABLED else dev_mode()
    _frost_sync(v)
    return v

_OTHER_SHOWN = {"v": OTHER_ENABLED}
def other_visible():
    """THE OTHER SIDE is hidden from players until 15/11 - a DEV account sees it today.
    This is the ONLY question the rest of the game should ask about the event."""
    v = True if OTHER_ENABLED else dev_mode()
    if v != _OTHER_SHOWN["v"]:
        _OTHER_SHOWN["v"] = v
        if v and _OTHER_SKIN is not None: SKINS["The Other Side"] = _OTHER_SKIN
        elif not v: SKINS.pop("The Other Side", None)
    return v

def _dev_fingerprint(uid, password):
    return hashlib.pbkdf2_hmac("sha256",str(password).encode(),("cup-dev|"+uid).encode(),200000).hex()
                          #    (lets you test events before their date; F8 on the tree = next day)

SEASONS = {
    "fall":  {"start":"2026-10-08","end":"2026-10-29","name":"Maple Blossom"},
    "haunt": {"start":"2026-10-25","end":"2026-11-14","name":"THE HAUNT","yearly":True},
}
MAPLE_DAILY_PTS = 25
MAPLE_DAYS      = 10

def _today(): return __import__("datetime").date.today().isoformat()

def season_state(mode):
    """'before' / 'active' / 'after' for a seasonal event."""
    s=SEASONS[mode]; d=_today()
    if dev_mode() and mode=="fall": return "active"
    return "before" if d<s["start"] else ("after" if d>s["end"] else "active")

def is_mode_unlocked(mode):
    """Permanent unlock: finished the event challenge, OR a Steam player (except THE HAUNT — it comes back every year)."""
    if mode in gd.get("unlocked_modes",[]): return True
    if BUILD_PLATFORM=="steam" and not SEASONS.get(mode,{}).get("yearly"): return True
    return False

def is_mode_available(mode):
    return season_state(mode)=="active" or is_mode_unlocked(mode)

# ── Maple tree data ────────────────────────────────────────────────────────────
def maple_data():
    m=gd.setdefault("maple",{"waters":0,"last_water":"","day":"","today_pts":0})
    if m.get("day")!=_today(): m["day"]=_today(); m["today_pts"]=0
    return m

def maple_complete(): return maple_data()["waters"]>=MAPLE_DAYS
def maple_can_water():
    m=maple_data()
    return (season_state("fall")=="active" and not maple_complete()
            and m["today_pts"]>=MAPLE_DAILY_PTS and m["last_water"]!=_today())

def maple_add_point():
    """Called on every correct answer, in any mode."""
    return                                                # THE HAUNT update: the Maple Tree was removed
    if season_state("fall")!="active" or maple_complete(): return
    m=maple_data()
    if m["last_water"]==_today() or m["today_pts"]>=MAPLE_DAILY_PTS: return
    m["today_pts"]+=1
    if m["today_pts"]==MAPLE_DAILY_PTS:
        _badge_toasts.append({"id":None,"t":None,"custom":True,"title":"THE MAPLE TREE",
                              "name":"Ready to water!","desc":f"You earned {MAPLE_DAILY_PTS} points today","col":(245,128,25)})
        save_gd(gd)

def maple_water():
    m=maple_data(); m["waters"]=min(MAPLE_DAYS,m["waters"]+1); m["last_water"]=_today()
    if m["waters"]>=5:
        us=gd.setdefault("unlocked_skins",["Classic"])
        if "Maple" not in us:
            us.append("Maple")
            _badge_toasts.append({"id":None,"t":None,"custom":True,"title":"NEW SKIN!","name":"Maple",
                                  "desc":"Equip it in PASS > INVENTORY","col":(245,128,25)})
    if m["waters"]>=MAPLE_DAYS:
        um=gd.setdefault("unlocked_modes",[])
        if "fall" not in um: um.append("fall")
        award_badge("maple_keeper")
    save_gd(gd)
    if AUTH_STATE.get("user"): threading.Thread(target=cloud_save,args=("maple",m),daemon=True).start()

# ── Procedural tree ────────────────────────────────────────────────────────────
_TREE_SEGS=None
def _tree_structure():
    """Grow a full tree once (fixed seed); stages reveal it level by level."""
    global _TREE_SEGS
    if _TREE_SEGS: return _TREE_SEGS
    rnd=random.Random(810); segs=[]
    def br(x,y,ang,ln,lvl):
        x2=x+math.cos(ang)*ln; y2=y+math.sin(ang)*ln
        segs.append({"lvl":lvl,"a":(x,y),"b":(x2,y2),"id":len(segs)})
        if lvl>=6: return
        n=2 if lvl<2 else rnd.choice((2,2,3))
        for k in range(n):
            a=ang+(k-(n-1)/2)*rnd.uniform(0.45,0.7)+rnd.uniform(-0.18,0.18)
            br(x2,y2,a,ln*rnd.uniform(0.66,0.8),lvl+1)
    br(0,0,-math.pi/2,1.0,0)
    _TREE_SEGS=segs; return segs

_tree_cache={}
def tree_surface(stage, W, H):
    key=(stage,W,H)
    if key in _tree_cache: return _tree_cache[key]
    if len(_tree_cache)>12: _tree_cache.clear()
    s=pygame.Surface((W,H),pygame.SRCALPHA); cx=W//2; by=H-24
    pygame.draw.ellipse(s,(60,34,20),(cx-W*0.34,by-14,W*0.68,34))            # soil mound
    pygame.draw.ellipse(s,(88,52,28),(cx-W*0.30,by-10,W*0.60,20))
    if stage==0:                                                              # seedling
        pygame.draw.line(s,(110,160,60),(cx,by),(cx,by-40),4)
        draw_maple(s,cx-12,by-44,10,(120,170,60),-0.6,255,False); draw_maple(s,cx+12,by-50,11,(140,185,70),0.6,255,False)
        _tree_cache[key]=s; return s
    g=stage/MAPLE_DAYS; vis=1+stage*0.55
    segs=_tree_structure()
    maxh=max(-min(sg["a"][1],sg["b"][1]) for sg in segs)+0.25
    maxw=max(max(abs(sg["a"][0]),abs(sg["b"][0])) for sg in segs)+0.25
    S=min((H-60)/maxh,(W*0.5)/maxw)*(0.42+0.58*g)
    rnd=random.Random(99)
    for seg in _tree_structure():
        if seg["lvl"]>vis: continue
        part=min(1.0,vis-seg["lvl"]) if seg["lvl"]>vis-1 else 1.0
        (x1,y1),(x2,y2)=seg["a"],seg["b"]
        x2=x1+(x2-x1)*part; y2=y1+(y2-y1)*part
        th=max(1,int((4+14*g)*(0.68**seg["lvl"])))
        c=_mix((74,44,26),(110,70,40),seg["lvl"]/6)
        pygame.draw.line(s,c,(cx+x1*S,by+y1*S),(cx+x2*S,by+y2*S),th)
        if th>3: pygame.draw.circle(s,c,(int(cx+x2*S),int(by+y2*S)),th//2)
    pal=[(200,42,30),(230,90,30),(245,128,25),(242,196,48),(170,40,35)]
    if stage<4: pal=[(120,165,50),(150,180,60),(200,170,50),(230,120,30)]
    leaf_lvl=max(1,int(vis)-1)
    for seg in _tree_structure():
        if seg["lvl"]<leaf_lvl or seg["lvl"]>vis: continue
        r2=random.Random(seg["id"]*7+1); (x2,y2)=seg["b"]
        for k in range(1+int(g*4)):
            ox=r2.uniform(-0.12,0.12)*S; oy=r2.uniform(-0.12,0.10)*S
            col=pal[r2.randrange(len(pal))]
            if stage>=MAPLE_DAYS and r2.random()<0.18: col=(255,210,60)
            draw_maple(s,cx+x2*S+ox,by+y2*S+oy,4+g*7*r2.uniform(0.7,1.2),col,r2.uniform(0,6.3),240,False)
    _tree_cache[key]=s; return s

def blit_rotate_pivot(surf, img, pos, origin, angle):
    r=img.get_rect(topleft=(pos[0]-origin[0],pos[1]-origin[1]))
    off=pygame.math.Vector2(pos)-r.center; ro=off.rotate(-angle)
    ri=pygame.transform.rotate(img,angle); surf.blit(ri,ri.get_rect(center=(pos[0]-ro.x,pos[1]-ro.y)))

def draw_watering_can(surf, x, y, s, tilt, col=(90,160,220)):
    c=pygame.Surface((int(s*3),int(s*2.2)),pygame.SRCALPHA); ox,oy=int(s*1.1),int(s*1.1)
    pygame.draw.rect(c,col,(ox-s*0.8,oy-s*0.6,s*1.6,s*1.3),border_radius=int(s*0.3))
    pygame.draw.line(c,col,(ox+s*0.7,oy),(ox+s*1.8,oy-s*0.7),max(3,int(s*0.22)))
    pygame.draw.circle(c,_mix(col,WHITE,0.3),(int(ox+s*1.85),int(oy-s*0.75)),int(s*0.2))
    pygame.draw.arc(c,col,(ox-s*0.6,oy-s*1.05,s*1.1,s*0.9),0,math.pi,max(3,int(s*0.15)))
    pygame.draw.line(c,_mix(col,WHITE,0.4),(ox-s*0.6,oy-s*0.25),(ox+s*0.6,oy-s*0.25),2)
    r=pygame.transform.rotate(c,-tilt); surf.blit(r,r.get_rect(center=(x,y)))

tree_fx={"anim":None,"drops":[],"burst":[],"pop":None,"celebrate":0.0}

def _secs_to_midnight():
    import datetime as _d
    n=_d.datetime.now(); m=(n+_d.timedelta(days=1)).replace(hour=0,minute=0,second=0,microsecond=0)
    return int((m-n).total_seconds())

def draw_maple_tree_screen(surf, t, dt, mouse, events):
    """Returns 'back' when the player leaves."""
    W,H=surf.get_size(); m=maple_data(); st=season_state("fall")
    surf.blit(fall_background(W,H),(0,0))
    o=pygame.Surface((W,H),pygame.SRCALPHA); o.fill((10,4,4,70)); surf.blit(o,(0,0))
    top=draw_header(surf,"THE MAPLE TREE","Water it on 10 days to keep Fall Mode forever",(245,128,25),t)
    stage=m["waters"]; done=stage>=MAPLE_DAYS
    # Tree (left)
    tw,th=int(W*0.52),int(H-top-30); tx=int(W*0.04); ty=top+6
    if done: surf.blit(_glow(int(th*0.55),(255,190,60),60),(tx+tw//2-int(th*0.55),ty+th//2-int(th*0.55)))
    ts=tree_surface(stage,tw,th)
    blit_rotate_pivot(surf,ts,(tx+tw//2,ty+th-24),(tw//2,th-24),math.sin(t*0.9)*1.2)
    if done and random.random()<0.3:
        tree_fx["burst"].append({"x":tx+tw//2+random.uniform(-tw*0.3,tw*0.3),"y":ty+th*0.2,"vx":random.uniform(-30,30),
                                 "vy":random.uniform(30,70),"rot":0,"vr":random.uniform(-3,3),"life":3.0,"col":(255,210,60),"size":6})
    # Watering animation
    an=tree_fx["anim"]
    if an is not None:
        an["t"]+=dt; k=an["t"]
        cx_=tx+tw//2+int(tw*0.18); cy_=ty+int(th*0.18)
        draw_watering_can(surf,cx_,cy_,min(W,H)*0.045,min(40,k*80))
        if 0.35<k<1.5:
            for _ in range(3):
                tree_fx["drops"].append({"x":cx_+min(W,H)*0.08+random.uniform(-6,6),"y":cy_-min(W,H)*0.02,"vy":random.uniform(180,260),"life":1.2})
        if k>=1.6 and not an.get("applied"):
            an["applied"]=True; maple_water(); SND_CHIME.play(); start_shake(3,12)
            for _ in range(50):
                a=random.uniform(0,6.3); sp=random.uniform(80,300)
                tree_fx["burst"].append({"x":tx+tw//2,"y":ty+th*0.45,"vx":math.cos(a)*sp,"vy":math.sin(a)*sp-100,
                    "rot":random.uniform(0,6),"vr":random.uniform(-8,8),"life":1.4,
                    "col":random.choice(list(FALL_COLORS.values())),"size":random.uniform(5,11)})
            tree_fx["pop"]={"text":f"DAY {maple_data()['waters']} / {MAPLE_DAYS}","life":1.8}
            if maple_complete(): tree_fx["celebrate"]=4.0
        if k>=2.2: tree_fx["anim"]=None
    for d in tree_fx["drops"]:
        d["y"]+=d["vy"]*dt; d["life"]-=dt
        pygame.draw.line(surf,(120,190,255),(d["x"],d["y"]),(d["x"],d["y"]+8),2)
    tree_fx["drops"]=[d for d in tree_fx["drops"] if d["life"]>0 and d["y"]<ty+th-30]
    for b in tree_fx["burst"]:
        b["x"]+=b["vx"]*dt; b["y"]+=b["vy"]*dt; b["vy"]+=160*dt; b["rot"]+=b["vr"]*dt; b["life"]-=dt
        draw_maple(surf,b["x"],b["y"],b["size"],b["col"],b["rot"],int(255*min(1,b["life"])),False)
    tree_fx["burst"]=[b for b in tree_fx["burst"] if b["life"]>0]
    # Right panel
    pr=pygame.Rect(int(W*0.58),top+6,int(W*0.38),H-top-90); cy=ui_panel(surf,pr,"GROWTH",(245,128,25))
    f=ui_font(min(W,H)*0.034)
    ds=ui_font(min(W,H)*0.07).render(f"{stage} / {MAPLE_DAYS}",True,WHITE); surf.blit(ds,ds.get_rect(centerx=pr.centerx,y=cy))
    y=cy+ds.get_height()+6; ls=(pr.w-40)//MAPLE_DAYS
    for i in range(MAPLE_DAYS):
        c=(245,128,25) if i<stage else (60,50,50)
        draw_maple(surf,pr.x+20+ls*i+ls//2,y+12,ls*0.36,c,0,255 if i<stage else 160,False)
    y+=40
    msg=None; wr=None
    if done:
        msg=("FULLY GROWN!",(255,210,60)); sub="Fall Mode is yours forever"
    elif st=="before": msg=("Starts 8/10",(200,200,225)); sub="Come back when Maple Blossom begins"
    elif st=="after": msg=("The season is over",(200,160,140)); sub="The tree rests until next autumn"
    else:
        surf.blit(f.render("TODAY",True,(210,170,120)),(pr.x+20,y)); y+=f.get_height()+4
        bw=pr.w-40; pygame.draw.rect(surf,(40,24,16),(pr.x+20,y,bw,14),border_radius=7)
        tp=min(MAPLE_DAILY_PTS,m["today_pts"]) if m["last_water"]!=_today() else MAPLE_DAILY_PTS
        if tp: pygame.draw.rect(surf,(245,128,25) if tp<MAPLE_DAILY_PTS else (80,200,110),(pr.x+20,y,int(bw*tp/MAPLE_DAILY_PTS),14),border_radius=7)
        pt=ui_font(22).render(f"{tp} / {MAPLE_DAILY_PTS} points",True,(220,200,180)); surf.blit(pt,(pr.x+20,y+18)); y+=48
        if m["last_water"]==_today():
            sec=_secs_to_midnight(); sub=f"Watered today!  Next in {sec//3600}h {(sec%3600)//60}m"
            msg=("See you tomorrow",(120,200,255))
        elif maple_can_water() and an is None:
            wr=ui_pill(surf,"water",pygame.Rect(pr.centerx-120,y,240,50),"WATER THE TREE",(60,150,230),dt,mouse,"tree")
            sub="Your tree is thirsty!"
        else: sub="Answer correctly in any mode to earn points"
    if msg:
        ms=ui_font(min(W,H)*0.045).render(msg[0],True,msg[1]); surf.blit(ms,ms.get_rect(centerx=pr.centerx,y=y)); y+=ms.get_height()+4
    if not wr:
        ss=render_fit(ui_font(22),sub,(190,170,160),pr.w-30); surf.blit(ss,ss.get_rect(centerx=pr.centerx,y=y))
    else:
        ss=ui_font(20).render(sub,True,(190,170,160)); surf.blit(ss,ss.get_rect(centerx=pr.centerx,y=y+56))
    ry=pr.bottom-96; surf.blit(f.render("REWARDS",True,(210,170,120)),(pr.x+20,ry))
    ry-=28
    for i,(ic,txt,ok_) in enumerate((("ticket","Day 5: Maple skin",stage>=5),("tree","Day 10: Badge Maple Keeper",done),("leaf","Day 10: Fall Mode forever",done))):
        yy=ry+34+i*28; ui_icon2(surf,ic,pr.x+32,yy+8,9,(255,210,60) if ok_ else (150,130,120))
        surf.blit(ui_font(22).render(txt,True,WHITE if ok_ else (180,170,165)),(pr.x+50,yy))
    if BUILD_PLATFORM=="steam" and not done:
        sn=ui_font(20).render("Steam player: Fall Mode is already yours!",True,(120,200,255)); surf.blit(sn,sn.get_rect(centerx=pr.centerx,y=pr.bottom+8))
    if tree_fx["pop"]:
        p=tree_fx["pop"]; p["life"]-=dt
        ps=ui_font(min(W,H)*0.08).render(p["text"],True,(255,220,120)); ps.set_alpha(int(255*min(1,p["life"])))
        surf.blit(ps,ps.get_rect(center=(tx+tw//2,ty+int(th*0.12))))
        if p["life"]<=0: tree_fx["pop"]=None
    if tree_fx["celebrate"]>0:
        tree_fx["celebrate"]-=dt; a=max(0,int(255*min(1,tree_fx["celebrate"])))
        cs=ui_font(min(W,H)*0.1).render("FULLY GROWN!",True,(255,210,60)); cs.set_alpha(a)
        surf.blit(cs,cs.get_rect(center=(W//2,H//2)))
    if dev_mode():
        dv=ui_font(18).render("DEV: F8 = +25 points & next day",True,(255,120,120)); surf.blit(dv,dv.get_rect(right=W-16,y=H-24))
    bk=ui_back(surf,dt,mouse)
    for ev in events:
        if dev_mode() and ev.type==pygame.KEYDOWN and ev.key==pygame.K_F8 and not maple_complete():
            mm=maple_data(); mm["last_water"]=""; mm["today_pts"]=MAPLE_DAILY_PTS
    if wr and ui_click(events,wr): tree_fx["anim"]={"t":0.0}; SND_SELECT.play()
    if (ui_click(events,bk) or ui_esc(events)) and tree_fx["anim"] is None: return "back"
    return None


