LIYVIBE_URL      = "https://www.youtube.com/@LiyVibe"
LIYVIBE_BADGE    = ("2026-10-08","2026-10-12")   # first 5 days of Maple Blossom
VIBE_TIME        = 60.0
VIBE_BURST_TIME  = 5.0
VIBE_BPM         = 124
VIBE_PINK        = (255,70,200)
VIBE_CYAN        = (60,230,255)
MUSIC_VIBE = _make_music([(392,.25),(0,.25),(392,.25),(494,.25),(587,.5),(494,.25),(440,.25),
                          (392,.25),(0,.25),(330,.25),(392,.25),(440,.5),(392,.5)],VIBE_BPM,0.17)

def liyvibe_badge_state():
    d=_today(); a,b=LIYVIBE_BADGE
    if dev_mode(): return "active"
    return "before" if d<a else ("after" if d>b else "active")

def vibe_new_state():
    return {"intro":3.0,"left":VIBE_TIME,"points":0,"meter":0.0,"burst":0.0,"bursts":0,
            "last_score":0,"last_lives":99,"pops":[],"rings":[],"new_best":False,"combo":0,"best_combo":0}

def vibe_update(vs, game, dt):
    game.deadline=time.time()+999                    # no per-round timer in Vibe Rush
    if vs["intro"]>0: vs["intro"]-=dt; return
    vs["left"]-=dt
    if vs["burst"]>0: vs["burst"]=max(0.0,vs["burst"]-dt)
    if game.score>vs["last_score"]:
        n=game.score-vs["last_score"]; mult=2 if vs["burst"]>0 else 1
        vs["points"]+=n*mult; vs["combo"]+=n; vs["best_combo"]=max(vs["best_combo"],vs["combo"])
        if vs["burst"]<=0:
            vs["meter"]=min(1.0,vs["meter"]+0.125)
            if vs["meter"]>=1.0:
                vs["burst"]=VIBE_BURST_TIME; vs["meter"]=0.0; vs["bursts"]+=1; SND_LEVEL.play(); start_shake(5,20)
        mx,my=pygame.mouse.get_pos()
        vs["pops"].append({"t":f"+{mult}","x":mx,"y":my-20,"life":0.8,"col":VIBE_CYAN if mult==1 else (255,230,90)})
        vs["rings"].append({"x":mx,"y":my,"r":10,"life":0.5})
    if game.lives<vs["last_lives"]:
        vs["left"]-=2.0; vs["combo"]=0; vs["meter"]=max(0.0,vs["meter"]-0.25)
        vs["pops"].append({"t":"-2s","x":WIDTH//2,"y":150,"life":0.9,"col":(255,80,80)})
    game.lives=99; vs["last_lives"]=99; vs["last_score"]=game.score
    for p in vs["pops"]: p["y"]-=50*dt; p["life"]-=dt
    vs["pops"]=[p for p in vs["pops"] if p["life"]>0]
    for r in vs["rings"]: r["r"]+=260*dt; r["life"]-=dt
    vs["rings"]=[r for r in vs["rings"] if r["life"]>0]

def draw_vibe(surf, vs, game, t):
    W,H=surf.get_size(); beat=(t*VIBE_BPM/60)%1; pulse=max(0.0,1-beat*3)
    burst=vs["burst"]>0
    draw_menu_bg(surf,t,VIBE_PINK if not burst else _mix(VIBE_PINK,VIBE_CYAN,0.5+0.5*math.sin(t*8)))
    o=pygame.Surface((W,H),pygame.SRCALPHA); o.fill((*(VIBE_CYAN if burst else VIBE_PINK),int(26*pulse))); surf.blit(o,(0,0))
    # HUD
    tt=ui_font(min(W,H)*0.05).render("VIBE RUSH",True,VIBE_PINK); surf.blit(tt,tt.get_rect(centerx=W//2,y=10))
    sub=ui_font(18).render("LiyVibe  x  Color Under Pressure",True,(200,170,230)); surf.blit(sub,sub.get_rect(centerx=W//2,y=12+tt.get_height()))
    surf.blit(ui_font(34).render(f"Score: {vs['points']}",True,WHITE),(20,14))
    best=gd.get("high_scores",{}).get("vibe",0)
    surf.blit(ui_font(22).render(f"Best: {max(best,vs['points'])}",True,(200,170,230)),(20,46))
    tl=max(0,vs["left"]); tc=WHITE if tl>10 else (255,90,90)
    ts=ui_font(min(W,H)*0.07).render(f"{int(math.ceil(tl))}",True,tc); surf.blit(ts,ts.get_rect(right=W-20,y=8))
    ink=game.cmd_color if not burst else NEON[game.target_name]
    cmd=ui_font(min(W,H)*0.09*(1+0.04*pulse)).render(f"GO TO  {game.target_name}!",True,ink)
    surf.blit(cmd,cmd.get_rect(centerx=W//2,y=78))
    # Vibe meter
    bx,by,bw,bh=50,145,W-100,14
    pygame.draw.rect(surf,(30,14,40),(bx,by,bw,bh),border_radius=7)
    if burst:
        k=vs["burst"]/VIBE_BURST_TIME
        for i in range(int(bw*k)//6):
            c=_mix(VIBE_PINK,VIBE_CYAN,(math.sin(t*6+i*0.3)+1)/2); pygame.draw.rect(surf,c,(bx+i*6,by,5,bh))
        bl=ui_font(22).render("VIBE BURST  x2",True,(255,230,90)); surf.blit(bl,bl.get_rect(centerx=W//2,y=by+17))
    else:
        if vs["meter"]>0: pygame.draw.rect(surf,VIBE_PINK,(bx,by,int(bw*vs["meter"]),bh),border_radius=7)
        bl=ui_font(18).render("VIBE METER",True,(170,130,200)); surf.blit(bl,bl.get_rect(centerx=W//2,y=by+17))
    pygame.draw.rect(surf,(120,70,150),(bx,by,bw,bh),2,border_radius=7)
    # Grid, pulsing on the beat
    skin=SKINS.get(gd.get("current_skin","Classic"),SKINS["Classic"])
    for cell in game.grid:
        col=skin[cell["name"]]; k=0.05*pulse
        r2=cell["rect"].inflate(int(k*cell["rect"].w),int(k*cell["rect"].h))
        surf.blit(_glow(int(r2.w*0.6),col,int(30+50*pulse)),(r2.centerx-int(r2.w*0.6),r2.centery-int(r2.w*0.6)))
        pygame.draw.rect(surf,col,r2,border_radius=14)
        pygame.draw.rect(surf,_mix(col,WHITE,0.5*pulse),r2,2,border_radius=14)
        lb=FONT_TINY.render(cell["name"],True,DARK); surf.blit(lb,lb.get_rect(center=r2.center))
    for r in vs["rings"]:
        pygame.draw.circle(surf,VIBE_CYAN,(int(r["x"]),int(r["y"])),int(r["r"]),max(1,int(4*r["life"]*2)))
    draw_particles(surf)
    for p in vs["pops"]:
        ps=ui_font(34).render(p["t"],True,p["col"]); ps.set_alpha(max(0,int(255*min(1,p["life"]*1.5))))
        surf.blit(ps,ps.get_rect(center=(int(p["x"]),int(p["y"]))))
    if vs["combo"]>=3:
        cs=ui_font(26).render(f"{vs['combo']} STREAK",True,(255,230,90)); surf.blit(cs,(20,70))
    if vs["intro"]>0:
        o2=pygame.Surface((W,H),pygame.SRCALPHA); o2.fill((20,6,26,200)); surf.blit(o2,(0,0))
        a=ui_font(min(W,H)*0.12).render("VIBE RUSH",True,VIBE_PINK); surf.blit(a,a.get_rect(center=(W//2,int(H*0.25))))
        b=ui_font(min(W,H)*0.04).render("LiyVibe  x  Color Under Pressure",True,VIBE_CYAN); surf.blit(b,b.get_rect(center=(W//2,int(H*0.34))))
        n=pygame.transform.rotozoom(ui_font(min(W,H)*0.15).render(str(int(math.ceil(vs["intro"]))),True,WHITE),0,1.2+(vs["intro"]%1)*0.6)
        surf.blit(n,n.get_rect(center=(W//2,int(H*0.53))))
        for i,l in enumerate(["60 seconds. No lives. Just vibes.","Fill the VIBE METER for a x2 VIBE BURST","Wrong answer = -2 seconds"]):
            ls=ui_font(24).render(l,True,(230,200,240)); surf.blit(ls,ls.get_rect(center=(W//2,int(H*0.70)+i*30)))

def draw_liyvibe_page(surf, t, dt, mouse):
    """LiyVibe collab hub. Returns dict of clickable rects."""
    W,H=surf.get_size()
    draw_menu_bg(surf,t,VIBE_PINK)
    top=draw_header(surf,"LIYVIBE","x  Color Under Pressure  •  Maple Blossom collab",VIBE_PINK,t)
    ch=max(150,H-90-top-10); gp=int(W*0.025)
    pr=pygame.Rect(int(W*0.05),top+10,int(W*0.44),ch)
    cr=pygame.Rect(pr.right+gp,top+10,int(W*0.46)-gp,(ch-gp)//2)
    br=pygame.Rect(pr.right+gp,cr.bottom+gp,int(W*0.46)-gp,ch-cr.h-gp)
    ui_card(surf,"lv_play",pr,VIBE_PINK,"note","VIBE RUSH","60 seconds  •  no lives  •  just vibes",t,dt,mouse,
            tag="MINI-MODE",extra=f"Best: {gd.get('high_scores',{}).get('vibe',0)}",big=True)
    ui_card(surf,"lv_chan",cr,VIBE_CYAN,"play","LIYVIBE'S CHANNEL","YouTube  •  @LiyVibe",t,dt,mouse,
            extra=("Opens in your browser" if LIYVIBE_URL else "Link coming soon"))
    ui_panel(surf,br,"COLLAB BADGE",(255,200,60))
    b=next(x for x in ALL_BADGES if x["id"]=="liyvibe_fan"); got=has_badge("liyvibe_fan")
    rr=int(min(br.h*0.28,br.w*0.14))
    draw_badge_medal(surf,b,br.x+30+rr,br.centery+10,rr,got,t,0.3)
    st=liyvibe_badge_state()
    line=("Unlocked!" if got else ("Play Vibe Rush between 8/10 and 12/10" if st!="after" else "This badge is gone forever"))
    surf.blit(render_fit(ui_font(28),b["name"],WHITE,br.w-rr*2-70),(br.x+50+rr*2,br.centery-20))
    surf.blit(render_fit(ui_font(22),line,(60,220,110) if got else (220,190,230),br.w-rr*2-70),(br.x+50+rr*2,br.centery+10))
    return {"play":pr,"chan":cr}


# ── LiyVibe portal animation ───────────────────────────────────────────────────
PORTAL_OPEN_AT = 1.75      # seconds: flash + browser opens
PORTAL_TOTAL   = 2.7
portal_fx = {"t":0.0,"origin":(0,0),"stars":[],"opened":False,"sparks":[]}

def portal_start(origin, url=None, label="WARPING TO  @LiyVibe", c1=None, c2=None):
    c1=c1 or VIBE_PINK; c2=c2 or VIBE_CYAN
    portal_fx.update({"t":0.0,"origin":origin,"opened":False,"sparks":[],"url":url or LIYVIBE_URL,"label":label,"c1":c1,"c2":c2,
                      "stars":[{"a":random.uniform(0,6.283),"d":random.uniform(5,60),"sp":random.uniform(1.8,3.2),
                                "c":random.choice((c1,c2,(255,255,255)))} for _ in range(90)]})
    SND_WHOOSH.play()

def _ease(x): x=max(0.0,min(1.0,x)); return x*x*(3-2*x)

def draw_portal(surf, dt):
    """Draws the portal on top of the page. Returns 'done' when finished."""
    W,H=surf.get_size(); pf=portal_fx; pf["t"]+=dt; t=pf["t"]
    VIBE_PINK=pf.get("c1",(255,70,200)); VIBE_CYAN=pf.get("c2",(60,230,255)); LIYVIBE_URL=pf.get("url","")
    diag=int(math.hypot(W,H))+20
    ox,oy=pf["origin"]
    # portal center slides from the card to the middle of the screen
    k=_ease(t/0.9); cx=int(ox+(W//2-ox)*k); cy=int(oy+(H//2-oy)*k)
    if t<0.35: R=int(70*_ease(t/0.35))
    elif t<PORTAL_OPEN_AT: R=int(70+(diag-70)*_ease((t-0.35)/(PORTAL_OPEN_AT-0.35))**1.6)
    else: R=diag
    closing=t>PORTAL_OPEN_AT
    if not closing and R>2:
        # tunnel
        tun=pygame.Surface((W,H),pygame.SRCALPHA); tun.fill((14,3,26,255))
        N=20; spin=t*2.2
        for i in range(N):
            p=((i+t*2.4)%N)/N; rr=int(8+diag*0.75*p**2.3)
            col=VIBE_PINK if i%2 else VIBE_CYAN; w=max(1,int(1+9*p))
            box=pygame.Rect(cx-rr,cy-rr,rr*2,rr*2)
            a0=spin*(1 if i%2 else -1)+i*0.5
            for seg in range(3):
                s0=a0+seg*2.094
                pygame.draw.arc(tun,(*col,int(60+170*p)),box,s0,s0+1.5,w)
        for st in pf["stars"]:                               # warp-speed streaks
            st["d"]*=1+dt*st["sp"]*(1.5+t)
            if st["d"]>diag: st["d"]=random.uniform(4,30); st["a"]=random.uniform(0,6.283)
            x1=cx+math.cos(st["a"])*st["d"]; y1=cy+math.sin(st["a"])*st["d"]
            x2=cx+math.cos(st["a"])*st["d"]*1.18; y2=cy+math.sin(st["a"])*st["d"]*1.18
            pygame.draw.line(tun,(*st["c"],230),(x1,y1),(x2,y2),2 if st["d"]>120 else 1)
        core=int(24+30*_ease(t/PORTAL_OPEN_AT)+6*math.sin(t*14))
        tun.blit(_glow(core*3,(255,255,255),120),(cx-core*3,cy-core*3))
        pygame.draw.circle(tun,VIBE_PINK,(cx,cy),core)
        pygame.draw.polygon(tun,WHITE,[(cx-core*0.35,cy-core*0.5),(cx-core*0.35,cy+core*0.5),(cx+core*0.55,cy)])
        # cut it into a circle
        mask=pygame.Surface((W,H),pygame.SRCALPHA); pygame.draw.circle(mask,(255,255,255,255),(cx,cy),R)
        tun.blit(mask,(0,0),special_flags=pygame.BLEND_RGBA_MIN); surf.blit(tun,(0,0))
        # glowing rim + electric sparks
        if R<diag-10:
            for w_,c_ in ((10,(*VIBE_PINK,)),(4,WHITE),(2,VIBE_CYAN)):
                pygame.draw.circle(surf,c_,(cx,cy),R,w_ if R>w_ else 0)
            for _ in range(6):
                a=random.uniform(0,6.283); r1=R; r2=R+random.uniform(8,26)
                pygame.draw.line(surf,random.choice((VIBE_CYAN,WHITE)),(cx+math.cos(a)*r1,cy+math.sin(a)*r1),
                                 (cx+math.cos(a+0.05)*r2,cy+math.sin(a+0.05)*r2),2)
        if t>0.5:
            m=min(W,H); txt=bidi(tr(pf.get("label","WARPING TO  @LiyVibe")))
            f=ui_font(m*0.06); x=W//2-f.size(txt)[0]//2; y=int(H*0.80)
            for j,ch in enumerate(txt):
                cs=f.render(ch,True,VIBE_CYAN if j%2 else VIBE_PINK)
                surf.blit(cs,(x,y+int(math.sin(t*10+j*0.6)*5))); x+=cs.get_width()
    if t>=PORTAL_OPEN_AT and not pf["opened"]:
        pf["opened"]=True; SND_CHIME.play(); start_shake(8,18)
        try: webbrowser.open(LIYVIBE_URL)
        except Exception: pass
    if t>PORTAL_OPEN_AT-0.12:                                # white flash, then fade back
        a=1.0-max(0.0,(t-PORTAL_OPEN_AT)/(PORTAL_TOTAL-PORTAL_OPEN_AT))
        if t<PORTAL_OPEN_AT: a=(t-(PORTAL_OPEN_AT-0.12))/0.12
        fl=pygame.Surface((W,H)); fl.fill((255,245,255)); fl.set_alpha(max(0,min(255,int(255*a)))); surf.blit(fl,(0,0))
        if closing:
            ms=ui_font(min(W,H)*0.07).render("See you on the channel!",True,VIBE_PINK)
            ms.set_alpha(max(0,min(255,int(255*min(1,(PORTAL_TOTAL-t)*3))))); surf.blit(ms,ms.get_rect(center=(W//2,H//2)))
    return "done" if t>=PORTAL_TOTAL else None


# =============================================================================
#  ANNOUNCEMENTS — the developer writes, every player sees a popup
# =============================================================================
ANN = {"show":None,"checked":0.0,"status":"","status_t":0.0,"t0":0.0}

def ann_poll():
    def _r():
        d=_fb_req("GET","/announcements/latest")
        if isinstance(d,dict) and d.get("id") and d.get("id")!=gd.get("ann_seen") and ANN["show"] is None:
            ANN["show"]=d; ANN["t0"]=time.time()
    threading.Thread(target=_r,daemon=True).start()

def ann_tick():
    if time.time()-ANN["checked"]>60: ANN["checked"]=time.time(); ann_poll()

def ann_send(title, text):
    def _r():
        ANN["status"]="Sending..."; ANN["status_t"]=time.time()
        d={"id":int(time.time()*1000),"title":title.strip()[:60],"text":text.strip()[:400],
           "author":(AUTH_STATE.get("user") or {}).get("displayName","Man Studio"),"ts":int(time.time())}
        ok=_fb_req("PUT","/announcements/latest",d) is not None
        if ok:
            _fb_req("PUT",f"/announcements/history/{d['id']}",d)
            gd["ann_seen"]=d["id"]; save_gd(gd)
        ANN["status"]="Sent to everyone!" if ok else "Send failed — check your connection"; ANN["status_t"]=time.time()
    threading.Thread(target=_r,daemon=True).start()

def ann_remove():
    def _r():
        _fb_req("DELETE","/announcements/latest")
        ANN["status"]="Announcement removed"; ANN["status_t"]=time.time()
    threading.Thread(target=_r,daemon=True).start()

# ══════════════════════════════════════════════════════════════════════════════
#  EVENTS — the player can sign up for an event and get a message when it starts
# ══════════════════════════════════════════════════════════════════════════════
# Each event: id, name, start, end (YYYY-MM-DD), what, icon, col.
# "show_from" = the day it appears in the list (default: 30 days before it starts),
# so events that are not announced yet stay hidden.
EVENTS_BUILTIN = [
    {"id":"haunt_2026","name":"THE HAUNT","start":"2026-10-25","end":"2026-11-14",
     "what":"The mansion opens. 20 rooms, Trick or Treat, candy, a shop and the Ghost's quests.",
     "icon":"pumpkin","col":(210,90,30),"show_from":"2026-09-20"},
    {"id":"ore_mode_2026","name":"ORE MODE","start":"2026-11-15","end":"2026-12-05",
     "what":"A collab with BURGERS STUDIOS. Mine ores for Mine Coins, buy better pickaxes, and on the last day the two studios fight.",
     "icon":"star","col":(255,206,60),"show_from":"2026-10-26"},
    {"id":"other_side_2026","name":"THE OTHER SIDE","start":"2026-11-15","end":"2026-11-25",
     "what":"An 80s night in a small town - and the world behind it. NIGHT RIDE, LIGHT WALL and FLIP SIDE.",
     "icon":"moon","col":(255,70,170),"show_from":"2026-11-07"},
    {"id":"first_frost_2026","name":"FIRST FROST","start":"2026-11-20","end":"2026-12-05",
     "what":"The first frost arrives. The colors freeze over, and the cold brings new friends.",
     "icon":"snow","col":(120,200,255),"show_from":"2026-10-15"},
    {"id":"winter_wonderland_2026","name":"WINTER WONDERLAND","start":"2026-12-05","end":"2026-12-20",
     "what":"Snow covers everything, and the Advent Calendar opens: a gift a day until Dec 31.",
     "icon":"tree","col":(120,230,215),"show_from":"2026-10-15"},
    {"id":"holiday_sparkle_2026","name":"HOLIDAY SPARKLE","start":"2026-12-20","end":"2026-12-31",
     "what":"Lights, presents and sparkle. The Advent Calendar keeps going to the last day.",
     "icon":"spark","col":(255,200,90),"show_from":"2026-10-15"},
]
EV = {"extra":[], "pulled":0.0, "popup":None, "busy":False}

def ev_days_to(date_str):
    try:
        import datetime as _dt
        a=_dt.date.fromisoformat(_today()); b=_dt.date.fromisoformat(str(date_str))
        return (b-a).days
    except Exception: return 999

def ev_show_from(e):
    if e.get("show_from"): return str(e["show_from"])
    try:
        import datetime as _dt
        return (_dt.date.fromisoformat(str(e["start"]))-_dt.timedelta(days=30)).isoformat()
    except Exception: return "1970-01-01"

def ev_state(e):
    d=_today()
    if d < str(e["start"]): return "before"
    if d > str(e.get("end",e["start"])): return "after"
    return "active"

def ev_all():
    """Everything the player may see now: built in + anything added on the server."""
    out={}
    for e in EVENTS_BUILTIN+list(EV["extra"]):
        if not isinstance(e,dict) or not e.get("id") or not e.get("start"): continue
        if e.get("hidden") and not dev_mode(): continue
        if not dev_mode() and _today() < ev_show_from(e): continue
        if ev_state(e)=="after" and ev_days_to(e.get("end",e["start"]))< -14: continue   # old news
        out[str(e["id"])]=e
    return sorted(out.values(), key=lambda e: (ev_state(e)!="active", str(e["start"])))

def ev_subs(): return gd.setdefault("event_subs",{})
def ev_subbed(e): return bool(ev_subs().get(str(e["id"])))
def ev_toggle(e):
    s=ev_subs(); k=str(e["id"])
    if s.get(k): s.pop(k,None)
    else:
        s[k]=True
        if ev_state(e)=="active": gd.setdefault("event_told",{})[k]=True   # already running: no late message
    save_gd(gd); return bool(s.get(k))

def ev_pull():
    """Extra events from Firebase (/events) so new ones don't need a game update."""
    if EV["busy"]: return
    EV["busy"]=True
    def _r():
        try:
            d=_fb_req("GET","/events")
            if isinstance(d,dict):
                EV["extra"]=[v for v in d.values() if isinstance(v,dict) and v.get("id") and v.get("start")]
        except Exception as e: print("events:",e)
        EV["busy"]=False
    threading.Thread(target=_r,daemon=True).start()

def ev_tick():
    """Every minute: refresh the list, and show a message for an event that just started."""
    if time.time()-EV["pulled"]>300: EV["pulled"]=time.time(); ev_pull()
    if EV["popup"] or ANN.get("show"): return
    told=gd.setdefault("event_told",{})
    for e in ev_all():
        k=str(e["id"])
        if ev_state(e)=="active" and ev_subbed(e) and not told.get(k):
            EV["popup"]=e; ANN["t0"]=time.time(); return

def ev_popup_data(e):
    d1=str(e["start"])[8:10]+"/"+str(e["start"])[5:7]
    d2=str(e.get("end",e["start"]))[8:10]+"/"+str(e.get("end",e["start"]))[5:7]
    return {"title":tr(str(e.get("name","EVENT"))),
            "text":tr(str(e.get("what","")))+"\n\n"+tr("It is on now")+"  •  "+d1+" - "+d2,
            "author":"Man Studio"}

def ev_close_popup():
    e=EV["popup"]
    if e: gd.setdefault("event_told",{})[str(e["id"])]=True; save_gd(gd)
    EV["popup"]=None

def ev_when_text(e):
    """'in 6 days' / 'ON NOW' / 'ends in 3 days'"""
    st=ev_state(e)
    if st=="before":
        n=ev_days_to(e["start"])
        if n<=0: return tr("starts today")
        if n==1: return tr("starts tomorrow")
        return f"{n} "+tr("days to go")
    if st=="active":
        n=ev_days_to(e.get("end",e["start"]))
        if n<=0: return tr("last day!")
        if n==1: return tr("ends tomorrow")
        return tr("ends in")+f" {n} "+tr("days")
    return tr("finished")

def draw_events_screen(surf, dt, mouse, events):
    """The EVENTS screen: every event, when it is, and a REMIND ME button."""
    W,H=surf.get_size(); m=min(W,H); t=pygame.time.get_ticks()/1000
    COL=(120,205,255)
    draw_menu_bg(surf,t,COL)
    lst=ev_all()
    n_sub=sum(1 for e in lst if ev_subbed(e))
    top=draw_header(surf,"EVENTS",tr("Sign up and the game will tell you when it starts"),COL,t)
    if not lst:
        ns=ui_font(m*0.04).render(tr("No events right now. Come back soon!"),True,(150,160,190))
        surf.blit(ns,ns.get_rect(center=(W//2,H//2)))
        bk=ui_back(surf,dt,mouse)
        return ("back" if (ui_click(events,bk) or ui_esc(events)) else None)
    rows=lst[:5]
    rh=min(int(m*0.155),(H-top-110)//max(1,len(rows))-10)
    rw=int(W*0.76); x0=(W-rw)//2; y=top+8
    hit=[]
    for e in rows:
        st=ev_state(e); col=tuple(e.get("col",COL))
        r=pygame.Rect(x0,y,rw,rh)
        hov=r.collidepoint(mouse)
        hh=ui_hover("ev_"+str(e["id"]),1.0 if hov else 0.0,dt)
        rr=r.move(0,-int(4*hh))
        sh=pygame.Surface((rr.w,rr.h),pygame.SRCALPHA); pygame.draw.rect(sh,(0,0,0,110),sh.get_rect(),border_radius=16)
        surf.blit(sh,(rr.x,rr.y+8))
        base=(26,26,46) if st!="active" else (30,38,58)
        pygame.draw.rect(surf,_mix(base,col,0.10+0.10*hh),rr,border_radius=16)
        pygame.draw.rect(surf,col if st=="active" else _mix(col,(50,50,80),0.45),rr,2,border_radius=16)
        pygame.draw.rect(surf,col,(rr.x,rr.y+10,5,rr.h-20),border_radius=3)
        ui_icon2(surf,str(e.get("icon","star")),rr.x+48,rr.centery,int(rh*0.22),col,t)
        nm=render_fit(ui_font(m*0.042),tr(str(e.get("name","EVENT"))),WHITE,rw-430)
        surf.blit(nm,(rr.x+86,rr.y+int(rh*0.16)))
        d1=str(e["start"])[8:10]+"/"+str(e["start"])[5:7]; d2=str(e.get("end",e["start"]))[8:10]+"/"+str(e.get("end",e["start"]))[5:7]
        wh=render_fit(ui_font(m*0.028),d1+"  -  "+d2+"   •   "+ev_when_text(e),(185,195,225),rw-430)
        surf.blit(wh,(rr.x+86,rr.y+int(rh*0.16)+nm.get_height()+4))
        if st=="active":
            tagw=ui_font(m*0.026).render(tr("ON NOW"),True,(12,16,10))
            tr_=pygame.Rect(rr.right-tagw.get_width()-250,rr.y+14,tagw.get_width()+24,26)
            pygame.draw.rect(surf,(70,225,120),tr_,border_radius=13)
            surf.blit(tagw,tagw.get_rect(center=tr_.center))
        subbed=ev_subbed(e)
        bw=200; br=pygame.Rect(rr.right-bw-22,rr.centery-23,bw,46)
        ui_pill(surf,"evb_"+str(e["id"]),br,tr("REMINDER ON") if subbed else tr("REMIND ME"),
                (60,200,110) if subbed else (70,120,200),dt,mouse,"star" if subbed else "clock")
        hit.append((br,e))
        y+=rh+10
    _it=(tr("Signed up for")+f"  {n_sub}") if n_sub else tr("You are not signed up for any event yet")
    inf=ui_font(m*0.026).render(_it,True,(140,150,180))
    surf.blit(inf,inf.get_rect(centerx=W//2,y=H-86))
    bk=ui_back(surf,dt,mouse)
    for br,e in hit:
        if ui_click(events,br):
            on=ev_toggle(e)
            (SND_SELECT if on else SND_TICK).play()
            _badge_toasts.append({"id":None,"t":None,"custom":True,
                "title":"REMINDER ON" if on else "REMINDER OFF",
                "name":tr(str(e["name"])),
                "desc":tr("We will tell you when it starts") if on else tr("You will not be told"),
                "col":tuple(e.get("col",COL)),"icon":"clock"})
            return None
    if ui_click(events,bk) or ui_esc(events): return "back"
    return None

def wrap_lines(font, text, maxw):
    out=[]
    for para in str(text).split("\n"):
        line=""
        for w in para.split(" "):
            t=(line+" "+w) if line else w
            if font.size(t)[0]<=maxw or not line: line=t
            else: out.append(line); line=w
        out.append(line)
    return out

def draw_announcement_popup(surf, ann, dt, mouse, events):
    """Returns True when the player closes it."""
    W,H=surf.get_size(); m=min(W,H); t=pygame.time.get_ticks()/1000
    k=min(1.0,(time.time()-ANN.get("t0",0))/0.35); ease=1-(1-k)**3
    o=pygame.Surface((W,H),pygame.SRCALPHA); o.fill((4,4,12,int(190*ease))); surf.blit(o,(0,0))
    cw=int(W*0.62); fb=ui_font(m*0.034)
    lines=wrap_lines(fb,ann.get("text",""),cw-60)[:9]
    ch=int(m*0.30)+len(lines)*int(fb.get_linesize()*1.1)
    card=pygame.Rect(0,0,cw,ch); card.center=(W//2,int(H//2+(1-ease)*60))
    col=(255,120,60)
    surf.blit(_glow(int(cw*0.55),col,int(50*ease)),(card.centerx-int(cw*0.55),card.centery-int(cw*0.55)))
    ui_panel(surf,card,None,col)
    ui_icon2(surf,"megaphone",card.x+46,card.y+44,20,col,t)
    surf.blit(ui_font(22).render("ANNOUNCEMENT",True,col),(card.x+80,card.y+22))
    surf.blit(render_fit(ui_font(20),"from "+str(ann.get("author","Man Studio")),(160,160,190),cw-120),(card.x+80,card.y+46))
    ts=render_fit(ui_font(m*0.06),ann.get("title","") or "Man Studio",WHITE,cw-40)
    surf.blit(ts,ts.get_rect(centerx=card.centerx,y=card.y+int(m*0.11)))
    y=card.y+int(m*0.11)+ts.get_height()+12
    for ln in lines:
        ls=fb.render(ln,True,(215,215,235)); surf.blit(ls,ls.get_rect(centerx=card.centerx,y=y)); y+=int(fb.get_linesize()*1.1)
    ok=ui_pill(surf,"ann_ok",pygame.Rect(card.centerx-80,card.bottom-62,160,44),"OK",col,dt,mouse,"star")
    return ui_click(events,ok) or any(ev.type==pygame.KEYDOWN and ev.key in (pygame.K_RETURN,pygame.K_ESCAPE) for ev in events)

def draw_announce_screen(surf, dt, mouse, events, st):
    """Developer-only composer. st = {"title","text","field"}. Returns 'back' to leave."""
    W,H=surf.get_size(); m=min(W,H); t=pygame.time.get_ticks()/1000; col=(255,120,60)
    draw_menu_bg(surf,t,col)
    top=draw_header(surf,"ANNOUNCE","Send a message to every player",col,t)
    pn=pygame.Rect(int(W*0.08),top+6,int(W*0.84),H-top-90); cy=ui_panel(surf,pn,None,col)
    fl=ui_font(22)
    tr_=pygame.Rect(pn.x+24,pn.y+44,pn.w-48,46)
    surf.blit(fl.render("TITLE",True,(200,170,150)),(tr_.x,tr_.y-24))
    ui_input(surf,tr_,st["title"],"e.g. Maple Blossom is here!",st["field"]=="title",col)
    mr=pygame.Rect(pn.x+24,tr_.bottom+40,pn.w-48,pn.bottom-tr_.bottom-120)
    surf.blit(fl.render("MESSAGE",True,(200,170,150)),(mr.x,mr.y-24))
    pygame.draw.rect(surf,(16,16,32),mr,border_radius=12); pygame.draw.rect(surf,col if st["field"]=="text" else (60,60,90),mr,2,border_radius=12)
    fb=ui_font(m*0.032); y=mr.y+10
    lines=wrap_lines(fb,st["text"],mr.w-28) if st["text"] else []
    if not st["text"] and st["field"]!="text":
        surf.blit(fb.render("Write your message... (Enter = new line)",True,(90,90,120)),(mr.x+14,y))
    for i,ln in enumerate(lines[-8:]):
        cur="|" if st["field"]=="text" and i==len(lines[-8:])-1 and (pygame.time.get_ticks()//500)%2==0 else ""
        surf.blit(fb.render(ln+cur,True,WHITE),(mr.x+14,y)); y+=int(fb.get_linesize()*1.1)
    if not lines and st["field"]=="text" and (pygame.time.get_ticks()//500)%2==0:
        pygame.draw.line(surf,WHITE,(mr.x+14,y),(mr.x+14,y+fb.get_height()),2)
    cnt=fl.render(f"{len(st['text'])}/400",True,(120,120,150)); surf.blit(cnt,cnt.get_rect(right=mr.right-8,bottom=mr.bottom-6))
    ready=bool(st["title"].strip() or st["text"].strip())
    send=ui_pill(surf,"ann_send",pygame.Rect(pn.right-300,pn.bottom-62,276,46),"SEND TO EVERYONE",col if ready else (80,80,100),dt,mouse,"megaphone")
    rem=ui_pill(surf,"ann_rem",pygame.Rect(pn.x+24,pn.bottom-62,210,46),"REMOVE LAST",(120,60,70),dt,mouse)
    if ANN["status"] and time.time()-ANN["status_t"]<4:
        sc=(60,220,110) if "Sent" in ANN["status"] or "removed" in ANN["status"] else ((255,200,60) if "Sending" in ANN["status"] else (255,90,90))
        ss=ui_font(24).render(ANN["status"],True,sc); surf.blit(ss,ss.get_rect(centerx=W//2+60,y=H-50))
    bk=ui_back(surf,dt,mouse)
    for ev in events:
        if ev.type==pygame.MOUSEBUTTONDOWN and ev.button==1:
            if tr_.collidepoint(ev.pos): st["field"]="title"
            elif mr.collidepoint(ev.pos): st["field"]="text"
        if ev.type==pygame.KEYDOWN:
            f=st["field"]
            if ev.key==pygame.K_ESCAPE: return "back"
            if ev.key==pygame.K_TAB: st["field"]="text" if f=="title" else "title"
            elif ev.key==pygame.K_BACKSPACE: st[f]=st[f][:-1]
            elif ev.key==pygame.K_RETURN:
                if f=="text" and len(st["text"])<400: st["text"]+="\n"
                else: st["field"]="text"
            elif ev.unicode and ev.unicode.isprintable():
                lim=60 if f=="title" else 400
                if len(st[f])<lim: st[f]+=ev.unicode
    if ready and ui_click(events,send): ann_send(st["title"],st["text"]); st["title"]=""; st["text"]=""; SND_CHIME.play()
    if ui_click(events,rem): ann_remove(); SND_SELECT.play()
    if ui_click(events,bk): return "back"
    return None

