# =============================================================================
#  DAILY CHALLENGES + COIN ECONOMY
# =============================================================================
DAILY_REWARD   = (25, 35, 50)          # easy / medium / hard
DAILY_ALL_BONUS= 40                    # all 3 done
DAILY_STREAK   = 10                    # +10 per streak day (max 50)
COINS_PER_PTS  = 1                     # 1 coin per point
COINS_GAME_MAX = 1000000

# (type, target, text, mode, icon)  — text uses {n}
_DAILY_POOL = [
    [("play",3,"Play {n} games",None,"gamepad"), ("correct",40,"Get {n} correct answers",None,"star"),
     ("score",20,"Score {n} in one Classic game","classic","gamepad"), ("training",1,"Finish a Training lesson",None,"book"),
     ("combo",5,"Get a x{n} combo",None,"flame")],
    [("boss",1,"Reach BOSS MODE",None,"bolt"), ("score",35,"Score {n} in one Classic game","classic","gamepad"),
     ("combo",8,"Get a x{n} combo",None,"flame"), ("modeplay",1,"Play a Ranked game","ranked","trophy"),
     ("score",30,"Score {n} in Survival","survival","skull"), ("correct",100,"Get {n} correct answers",None,"star"),
     ("modeplay",2,"Play {n} Fall Mode games","fall","leaf")],
    [("score",50,"Score {n} in one Classic game","classic","gamepad"), ("combo",12,"Get a x{n} combo",None,"flame"),
     ("boss",3,"Reach BOSS MODE {n} times",None,"bolt"), ("accuracy",90,"Score 25+ with {n}% accuracy",None,"shield"),
     ("score",60,"Score {n} in Survival","survival","skull")],
]
_REWARD_FX = {"coins":0,"t":0.0}

def _daily_make(day):
    rng=random.Random("cup-daily-"+day)                # same challenges for every player on the same day
    out=[]
    for tier,pool in enumerate(_DAILY_POOL):
        opts=[m for m in pool if m[3]!="fall" or is_mode_available("fall")]
        ty,n,txt,mode,ic=rng.choice(opts)
        out.append({"type":ty,"target":n,"text":txt,"mode":mode,"icon":ic,"tier":tier,
                    "reward":DAILY_REWARD[tier],"progress":0,"done":False})
    return out

def daily_data():
    d=gd.setdefault("daily",{"day":"","missions":[],"streak":0,"last_all":"","bonus":False})
    if d.get("day")!=_today():
        d.update({"day":_today(),"missions":_daily_make(_today()),"bonus":False})
        import datetime as _d
        y=(_d.date.today()-_d.timedelta(days=1)).isoformat()
        if d.get("last_all") not in (y,_today()): d["streak"]=0      # streak broken
        save_gd(gd)
    return d

def daily_text(m): return m["text"].replace("{n}",str(m["target"]))
def daily_done_count(): return sum(1 for m in daily_data()["missions"] if m["done"])

def _daily_toast(title,name,desc,col=(255,200,60),icon="star"):
    _badge_toasts.append({"custom":True,"title":title,"name":name,"desc":desc,"col":col,"icon":icon,"t":None})

def add_coins(n):
    gd["coins"]=gd.get("coins",0)+int(n); coins_earned(n); save_gd(gd); check_coin_badges()

def daily_event(kind, mode=None, score=0, combo=0, hits=0, boss=0, acc=0):
    """Feed one finished game (kind='game') or finished lesson (kind='training')."""
    d=daily_data(); changed=False
    for m in d["missions"]:
        if m["done"]: continue
        ty,old=m["type"],m["progress"]
        if kind=="training":
            if ty=="training": m["progress"]+=1
        else:
            if ty=="play": m["progress"]+=1
            elif ty=="correct": m["progress"]+=hits
            elif ty=="score" and m["mode"]==mode: m["progress"]=max(old,score)
            elif ty=="combo": m["progress"]=max(old,combo)
            elif ty=="boss": m["progress"]+=boss
            elif ty=="modeplay" and m["mode"]==mode: m["progress"]+=1
            elif ty=="accuracy" and score>=25: m["progress"]=max(old,acc)
        if m["progress"]!=old: changed=True
        if m["progress"]>=m["target"]:
            m["progress"]=m["target"]; m["done"]=True; add_coins(m["reward"])
            _daily_toast("CHALLENGE COMPLETE!",daily_text(m),f"+{m['reward']} coins",(255,200,60),m["icon"])
    if all(m["done"] for m in d["missions"]) and not d["bonus"]:
        d["bonus"]=True; award_badge("daily_grind")
        import datetime as _d
        y=(_d.date.today()-_d.timedelta(days=1)).isoformat()
        d["streak"]=d.get("streak",0)+1 if d.get("last_all")==y else 1
        d["last_all"]=_today()
        bonus=DAILY_ALL_BONUS+min(50,DAILY_STREAK*d["streak"]); add_coins(bonus)
        _daily_toast("ALL CHALLENGES DONE!",f"Streak: {d['streak']} days",f"+{bonus} bonus coins",(255,120,60),"flame")
        changed=True
    if changed: save_gd(gd)

def game_end_rewards(mode, score, game=None):
    """Coins for every finished game + daily challenge progress."""
    score=int(score or 0)
    coins=min(COINS_GAME_MAX, score//COINS_PER_PTS)
    if mode=="flow": coins=score//10            # Flow points are 10x bigger (time bonus), so 10 points = 1 coin
    if mode=="flow": gd.setdefault("stats",{})["flow_games"]=gd.get("stats",{}).get("flow_games",0)+1
    if coins>0: add_coins(coins)
    _REWARD_FX.update({"coins":coins,"t":time.time()})
    gd["games_finished"]=gd.get("games_finished",0)+1
    metrics_game_finished()
    if gd["games_finished"]>=25: award_badge("marathon_mind")
    hits=getattr(game,"hits",0) if game else 0; miss=getattr(game,"misses",0) if game else 0
    daily_event("game",mode=mode,score=score,combo=getattr(game,"best_combo",0) if game else 0,hits=hits,
                boss=1 if (game and getattr(game,"boss_mode",False)) else 0,acc=int(hits*100/max(1,hits+miss)))

def draw_reward_chip(surf, card):
    """'+N coins' chip on result screens (the coins from the game that just ended)."""
    n=_REWARD_FX["coins"]; age=time.time()-_REWARD_FX["t"]
    if n<=0 or age>30: return
    k=min(1.0,age/0.4); txt=f"+{n} coins"
    f=ui_font(min(surf.get_size())*0.034); s=f.render(txt,True,(255,220,90))
    r=s.get_rect(topright=(card.right-18,card.y+16)).inflate(34,12); r.x-=int((1-k)*30)
    pygame.draw.rect(surf,(50,38,8),r,border_radius=r.h//2); pygame.draw.rect(surf,(255,200,40),r,2,border_radius=r.h//2)
    pygame.draw.circle(surf,(255,200,40),(r.x+14,r.centery),7); surf.blit(s,s.get_rect(midleft=(r.x+26,r.centery)))

def draw_daily_screen(surf, t, dt, mouse):
    """Returns the back button rect."""
    W,H=surf.get_size(); m=min(W,H); col=(255,190,40); d=daily_data()
    draw_menu_bg(surf,t,col)
    import datetime as _d
    now=_d.datetime.now(); left=(_d.datetime.combine(now.date()+_d.timedelta(days=1),_d.time())-now).seconds
    top=draw_header(surf,"DAILY CHALLENGES",f"New challenges in {left//3600}h {(left%3600)//60}m",col,t)
    lw=int(W*0.60); x0=int(W*0.05); rh=max(70,int((H-top-100-2*14)/3.4)); y=top+10
    TIER=[("EASY",(60,220,110)),("MEDIUM",(255,190,40)),("HARD",(255,80,90))]
    for i,ms in enumerate(d["missions"]):
        r=pygame.Rect(x0,y,lw,rh); tn,tc=TIER[ms["tier"]]
        h=ui_hover(f"dly{i}",1.0 if r.collidepoint(mouse) else 0.0,dt)
        ui_panel(surf,r,None,(60,220,110) if ms["done"] else _mix(tc,(80,80,100),0.4-0.3*h))
        ic=ms["icon"]; isz=rh*0.2
        surf.blit(_glow(int(isz*2),tc,50),(r.x+rh//2-int(isz*2),r.centery-int(isz*2)))
        ui_icon2(surf,ic,r.x+rh//2,r.centery,isz,tc,t)
        tx=r.x+rh; tw_=r.w-rh-150
        surf.blit(ui_font(m*0.024).render(tn,True,tc),(tx,r.y+10))
        surf.blit(render_fit(ui_font(m*0.038),daily_text(ms),WHITE if not ms["done"] else (170,230,190),tw_),(tx,r.y+10+m*0.028))
        bw=tw_; by=r.bottom-22; k=ms["progress"]/max(1,ms["target"])
        pygame.draw.rect(surf,(30,30,50),(tx,by,bw,10),border_radius=5)
        if k>0: pygame.draw.rect(surf,(60,220,110) if ms["done"] else tc,(tx,by,max(10,int(bw*k)),10),border_radius=5)
        pr=f"{ms['progress']}%" if ms["type"]=="accuracy" else f"{ms['progress']}/{ms['target']}"
        ps=ui_font(m*0.026).render(pr,True,(180,180,210)); surf.blit(ps,ps.get_rect(right=tx+bw,bottom=by-4))
        cx_=r.right-75
        if ms["done"]:
            pygame.draw.circle(surf,(60,220,110),(cx_,r.centery),int(rh*0.26))
            pygame.draw.lines(surf,WHITE,False,[(cx_-rh*0.12,r.centery),(cx_-rh*0.02,r.centery+rh*0.1),(cx_+rh*0.14,r.centery-rh*0.1)],4)
        else:
            pygame.draw.circle(surf,(255,200,40),(cx_-28,r.centery),11); pygame.draw.circle(surf,(200,140,20),(cx_-28,r.centery),11,2)
            surf.blit(ui_font(m*0.04).render(f"+{ms['reward']}",True,(255,220,90)),(cx_-12,r.centery-m*0.02))
        y+=rh+14
    # right side: streak + bonus + premium progress
    rx=x0+lw+int(W*0.03); rw=W-rx-int(W*0.05)
    p1=pygame.Rect(rx,top+10,rw,int((y-top-24)*0.52)); cy=ui_panel(surf,p1,"STREAK",(255,120,60))
    st_=d.get("streak",0); fl=ui_font(m*0.11).render(str(st_),True,WHITE)
    ui_icon2(surf,"flame",p1.centerx-fl.get_width()//2-m*0.04,p1.centery+m*0.015,m*0.035,(255,120,60),t)
    surf.blit(fl,fl.get_rect(midleft=(p1.centerx-fl.get_width()//2+m*0.005,p1.centery+m*0.02)))
    nb=DAILY_ALL_BONUS+min(50,DAILY_STREAK*(st_+1 if not d["bonus"] else st_))
    bl=("Bonus collected today!" if d["bonus"] else f"Finish all 3: +{nb} bonus")
    surf.blit(render_fit(ui_font(m*0.028),bl,(255,200,160),p1.w-30),(p1.x+16,p1.bottom-m*0.05))
    p2=pygame.Rect(rx,p1.bottom+14,rw,y-14-p1.bottom-14); ui_panel(surf,p2,"PREMIUM PASS",(255,200,50))
    co=gd.get("coins",0)
    if pass_premium():
        surf.blit(render_fit(ui_font(m*0.034),"You have Premium!",(255,220,90),p2.w-30),(p2.x+16,p2.centery-m*0.01))
    else:
        k=min(1.0,co/PREM_COST)
        surf.blit(render_fit(ui_font(m*0.03),f"{co} / {PREM_COST} coins",WHITE,p2.w-30),(p2.x+16,p2.centery-m*0.035))
        bb=pygame.Rect(p2.x+16,p2.centery+m*0.01,p2.w-32,12)
        pygame.draw.rect(surf,(30,30,50),bb,border_radius=6)
        if k>0: pygame.draw.rect(surf,(255,200,40),(bb.x,bb.y,max(12,int(bb.w*k)),12),border_radius=6)
        surf.blit(render_fit(ui_font(m*0.024),"Buy it in PASS > COLOR PASS",(170,170,200),p2.w-30),(p2.x+16,bb.bottom+8))
    hint=render_fit(ui_font(m*0.026),"Every game gives coins: 1 point = 1 coin  •  Boss Mode = +100  •  Badge = +2",(150,150,190),W-400)
    surf.blit(hint,hint.get_rect(centerx=W//2+80,y=H-48))
    return ui_back(surf,dt,mouse)


# =============================================================================
#  TRAINING MODE — learn the Stroop effect at your own pace
# =============================================================================
TRAIN_LESSONS = [
    {"id":"rule","title":"THE RULE","sub":"Go to the color the WORD says","ink":"white","n":10,"col":(60,200,255),
     "intro":["The screen says  GO TO  and a color name.","Click the square with that color.","Take your time — there is no timer here."],
     "tip":"Read the word, then find its color"},
    {"id":"match","title":"EASY MATCH","sub":"The ink matches the word","ink":"same","n":10,"col":(60,220,110),
     "intro":["Now the word is painted in its own color.","RED is written in red, BLUE in blue...","Easy, right? Your eyes and brain agree."],
     "tip":"The word and the ink agree"},
    {"id":"trap","title":"THE TRAP","sub":"The ink LIES — follow the word","ink":"other","n":12,"col":(255,80,90),
     "intro":["This is the Stroop Effect.","The word says one color, the ink shows another.","Your brain sees the INK first. Ignore it — follow the WORD!"],
     "tip":"Ignore the ink color!"},
    {"id":"test","title":"STROOP TEST","sub":"Measure your own Stroop effect","ink":"mixed","n":20,"col":(175,50,255),
     "intro":["Half the words match their ink, half are traps.","We time every answer.","At the end you'll see how much the trap slows YOU down."],
     "tip":None},
    {"id":"free","title":"FREE PRACTICE","sub":"Endless  •  no timer  •  no lives","ink":"mixed","n":0,"col":(255,190,40),
     "intro":["Practice as long as you want.","No timer, no lives, no pressure.","Press BACK when you're done."],
     "tip":None},
]
TRAIN_ABOUT = ["The Stroop Effect (1935):","reading a word is automatic,","naming a color takes effort.",
               "When they disagree, your brain","has to fight itself — that's","the pressure in this game!"]

def train_new(i):
    L=TRAIN_LESSONS[i]
    st={"lesson":i,"n":0,"total":L["n"],"intro":True,"hits":0,"miss":0,"rt_c":[],"rt_i":[],"fb":None,"done":False,
        "cells":[],"word":"","ink":WHITE,"cong":True,"t0":0.0,"tried":False,"wrong_cells":set()}
    return st

def _train_prompt(st):
    L=TRAIN_LESSONS[st["lesson"]]; names=COLOR_NAMES[:]
    random.shuffle(names); st["cells"]=names
    word=random.choice(COLOR_NAMES)
    while word==st.get("word") : word=random.choice(COLOR_NAMES)
    mode=L["ink"]
    if mode=="mixed": mode="same" if random.random()<0.5 else "other"
    if mode=="white": ink=(235,235,245); cong=True
    elif mode=="same": ink=NEON[word]; cong=True
    else: ink=NEON[random.choice([c for c in COLOR_NAMES if c!=word])]; cong=False
    st.update({"word":word,"ink":ink,"cong":cong,"t0":time.time(),"tried":False,"wrong_cells":set()})

def _train_cells_rects(W,H,top):
    gw=int(W*0.70); gh=int((H-top-120)); x0=(W-gw)//2; cols,rows=3,2; gap=18
    cw=(gw-gap*(cols-1))//cols; chh=min(int(cw*0.62),(gh-gap)//rows)
    y0=top+max(0,(gh-(chh*rows+gap))//2)
    return [pygame.Rect(x0+(i%cols)*(cw+gap),y0+(i//cols)*(chh+gap),cw,chh) for i in range(6)]

def draw_training(surf, st, t, dt, mouse, events):
    """Returns 'back' / 'done' / None."""
    W,H=surf.get_size(); m=min(W,H); L=TRAIN_LESSONS[st["lesson"]]; col=L["col"]
    draw_menu_bg(surf,t,col)
    hs=ui_font(m*0.03).render(f"TRAINING  •  {L['title']}",True,col); surf.blit(hs,(24,18))
    if st["total"]: prog=f"{st['n']}/{st['total']}"
    else: prog=f"{st['hits']} correct"
    ps=ui_font(m*0.03).render(prog,True,WHITE); surf.blit(ps,ps.get_rect(right=W-24,y=18))
    if st["total"]:
        pygame.draw.rect(surf,(30,30,50),(24,52,W-48,8),border_radius=4)
        pygame.draw.rect(surf,col,(24,52,max(8,int((W-48)*st["n"]/st["total"])),8),border_radius=4)
    if st["intro"]:
        card=pygame.Rect(W//2-int(W*0.33),int(H*0.16),int(W*0.66),int(H*0.62)); ui_panel(surf,card,None,col)
        ui_icon2(surf,"book",card.centerx,card.y+m*0.08,m*0.045,col,t)
        tt=ui_font(m*0.07).render(L["title"],True,WHITE); surf.blit(tt,tt.get_rect(centerx=card.centerx,y=card.y+m*0.14))
        for j,ln in enumerate(L["intro"]):
            ls=render_fit(ui_font(m*0.034),ln,(210,210,235),card.w-50); surf.blit(ls,ls.get_rect(centerx=card.centerx,y=card.y+m*0.26+j*m*0.055))
        go=ui_pill(surf,"tr_go",pygame.Rect(card.centerx-100,card.bottom-70,200,50),"START",col,dt,mouse,"play")
        bk=ui_back(surf,dt,mouse)
        if ui_click(events,go) or any(e.type==pygame.KEYDOWN and e.key in (pygame.K_RETURN,pygame.K_SPACE) for e in events):
            st["intro"]=False; _train_prompt(st); SND_SELECT.play()
        if ui_click(events,bk) or ui_esc(events): return "back"
        return None
    # prompt
    cmd=ui_font(m*0.10).render(f"GO TO  {st['word']}!",True,st["ink"])
    surf.blit(ui_font(m*0.10).render(f"GO TO  {st['word']}!",True,(0,0,0)),cmd.get_rect(centerx=W//2+3,y=int(H*0.10)+3))
    surf.blit(cmd,cmd.get_rect(centerx=W//2,y=int(H*0.10)))
    top=int(H*0.10)+cmd.get_height()+int(H*0.06)
    if L["tip"]:
        tp=ui_font(m*0.028).render(L["tip"],True,(170,170,205)); surf.blit(tp,tp.get_rect(centerx=W//2,y=top-int(H*0.045)))
    rects=_train_cells_rects(W,H,top)
    for i,r in enumerate(rects):
        name=st["cells"][i]; c=NEON[name]; h=ui_hover(f"trc{i}",1.0 if r.collidepoint(mouse) else 0.0,dt)
        rr=r.inflate(int(8*h),int(8*h))
        if i in st["wrong_cells"]: c=_mix(c,(40,40,50),0.65)
        surf.blit(_glow(int(rr.w*0.55),c,int(25+35*h)),(rr.centerx-int(rr.w*0.55),rr.centery-int(rr.w*0.55)))
        pygame.draw.rect(surf,c,rr,border_radius=16); pygame.draw.rect(surf,_mix(c,WHITE,0.4+0.3*h),rr,2,border_radius=16)
        lb=ui_font(m*0.03).render(name,True,(12,12,20)); surf.blit(lb,lb.get_rect(center=rr.center))
    # feedback
    if st["fb"] and time.time()-st["fb"][2]<2.2:
        ok,msg,_=st["fb"]; fc=(60,220,110) if ok else (255,90,90)
        fs=ui_font(m*0.036).render(msg,True,fc); surf.blit(fs,fs.get_rect(centerx=W//2,y=H-104))
    bk=ui_back(surf,dt,mouse)
    for ev in events:
        if ev.type==pygame.MOUSEBUTTONDOWN and ev.button==1:
            for i,r in enumerate(rects):
                if not r.collidepoint(ev.pos) or i in st["wrong_cells"]: continue
                name=st["cells"][i]
                if name==st["word"]:
                    rt=time.time()-st["t0"]
                    if not st["tried"]:
                        st["hits"]+=1; (st["rt_c"] if st["cong"] else st["rt_i"]).append(rt)
                    st["fb"]=(True,f"Correct!  {rt:.2f}s",time.time()); SND_CORRECT.play()
                    st["n"]+=1
                    if st["total"] and st["n"]>=st["total"]: st["done"]=True; return "done"
                    _train_prompt(st)
                else:
                    if not st["tried"]: st["miss"]+=1
                    st["tried"]=True; st["wrong_cells"].add(i); SND_WRONG.play()
                    ink_name=next((k for k,v in NEON.items() if v==st["ink"]),None)
                    st["fb"]=(False,"That's the INK color — follow the WORD!" if name==ink_name and not st["cong"]
                              else f"Not quite — the word says {st['word']}",time.time())
                break
    if ui_click(events,bk) or ui_esc(events):
        if st["lesson"]==len(TRAIN_LESSONS)-1 and st["hits"]+st["miss"]>0: st["done"]=True; return "done"
        return "back"
    return None

def train_finish(st):
    """Save progress + rewards. Returns result dict."""
    L=TRAIN_LESSONS[st["lesson"]]
    done=gd.setdefault("training_done",[])
    first=L["id"] not in done
    if first and L["id"]!="free": done.append(L["id"])
    if len(set(done)&{x["id"] for x in TRAIN_LESSONS if x["id"]!="free"})>=len([x for x in TRAIN_LESSONS if x["id"]!="free"]): award_badge("stroop_scholar")
    tot=st["hits"]+st["miss"]; acc=int(st["hits"]*100/max(1,tot))
    allrt=st["rt_c"]+st["rt_i"]; avg=sum(allrt)/len(allrt) if allrt else 0
    eff=None
    if st["rt_c"] and st["rt_i"]: eff=sum(st["rt_i"])/len(st["rt_i"])-sum(st["rt_c"])/len(st["rt_c"])
    coins=10 if (first and L["id"]!="free") else 0
    if coins: add_coins(coins)
    if L["id"]!="free" or tot>=10: daily_event("training")
    save_gd(gd)
    return {"acc":acc,"avg":avg,"eff":eff,"coins":coins,"lesson":st["lesson"],"hits":st["hits"],"tot":tot}

def draw_training_menu(surf, t, dt, mouse, events):
    """Returns lesson index, 'back' or None."""
    W,H=surf.get_size(); m=min(W,H); col=(60,200,255)
    draw_menu_bg(surf,t,col)
    top=draw_header(surf,"TRAINING","Learn the Stroop Effect at your own pace",col,t)
    ab=pygame.Rect(int(W*0.05),top+10,int(W*0.30),H-top-100); cy=ui_panel(surf,ab,"WHAT IS IT?",col)
    for j,ln in enumerate(TRAIN_ABOUT):
        ls=render_fit(ui_font(m*0.029),ln,(205,205,230) if j else col,ab.w-32); surf.blit(ls,(ab.x+18,cy+8+j*m*0.047))
    ex=ab.bottom-m*0.13
    w1=ui_font(m*0.05).render("BLUE",True,NEON["RED"]); surf.blit(w1,(ab.x+18,ex))
    surf.blit(render_fit(ui_font(m*0.026),"= go to BLUE, not red!",(170,170,205),ab.w-40-w1.get_width()),(ab.x+30+w1.get_width(),ex+m*0.015))
    done=gd.get("training_done",[])
    lx=ab.right+int(W*0.03); lw=W-lx-int(W*0.05); n=len(TRAIN_LESSONS); gap=10
    rh=int((H-top-100-gap*(n-1))/n); pick=None
    for i,L in enumerate(TRAIN_LESSONS):
        r=pygame.Rect(lx,top+10+i*(rh+gap),lw,rh); h=ui_hover(f"trl{i}",1.0 if r.collidepoint(mouse) else 0.0,dt)
        rr=r.move(int(6*h),0); c=L["col"]
        pygame.draw.rect(surf,_mix((16,16,30),c,0.12+0.18*h),rr,border_radius=14); pygame.draw.rect(surf,_mix(c,WHITE,0.3*h),rr,2,border_radius=14)
        if i<4: nm=ui_font(rh*0.42).render(str(i+1),True,c); surf.blit(nm,nm.get_rect(center=(rr.x+rh*0.5,rr.centery)))
        else: ui_icon2(surf,"flow",rr.x+rh*0.5,rr.centery,rh*0.2,c,t)
        surf.blit(render_fit(ui_font(min(rh*0.34,m*0.042)),L["title"],WHITE,rr.w-rh-80),(rr.x+rh,rr.y+rh*0.14))
        surf.blit(render_fit(ui_font(min(rh*0.25,m*0.028)),L["sub"],(175,175,205),rr.w-rh-80),(rr.x+rh,rr.y+rh*0.56))
        if L["id"] in done:
            cx_,cy_=rr.right-34,rr.centery
            pygame.draw.circle(surf,(60,220,110),(cx_,cy_),14)
            pygame.draw.lines(surf,WHITE,False,[(cx_-7,cy_),(cx_-2,cy_+5),(cx_+7,cy_-5)],3)
        if ui_click(events,r): pick=i
    bk=ui_back(surf,dt,mouse)
    if pick is not None: SND_SELECT.play(); return pick
    if ui_click(events,bk) or ui_esc(events): return "back"
    return None

def draw_training_result(surf, res, t, dt, mouse, events):
    """Returns 'next' / 'again' / 'back' / None."""
    L=TRAIN_LESSONS[res["lesson"]]; col=L["col"]
    rows=[("Accuracy",f"{res['acc']}%"),("Average time",f"{res['avg']:.2f}s")]
    sub="Lesson complete!"
    if res["eff"] is not None:
        ms_=int(res["eff"]*1000)
        rows.append(("Your Stroop effect",f"{'+' if ms_>=0 else ''}{ms_} ms"))
        sub=("The trap slowed you down — that's the Stroop effect!" if ms_>40 else "Wow — the trap barely slowed you down!")
    if res["coins"]: rows.append(("First time bonus",f"+{res['coins']} coins"))
    card=draw_result_screen(surf,t,"TRAINING",col,f"{res['hits']}/{res['tot']}",rows,col,sub)
    labels=[]
    if res["lesson"]<len(TRAIN_LESSONS)-1: labels.append(("next","NEXT LESSON",col,"play"))
    labels+= [("again","AGAIN",(90,150,90),"flow"),("back","LESSONS",(90,90,140),"back")]
    bt=result_buttons(surf,card,dt,mouse,labels)
    for k in ("next","again","back"):
        if k in bt and ui_click(events,bt[k]): SND_SELECT.play(); return k
    if ui_esc(events): return "back"
    return None


