SHARE = {"msg":"","t":0.0}
SHARE_URL = steam_url() if steam_build() else "https://manstudio.itch.io/color-under-pressure"

def _share_dir():
    home=os.path.expanduser("~")
    for base in (os.path.join(home,"Pictures"),os.path.join(home,"OneDrive","Pictures"),home):
        if os.path.isdir(base):
            d=os.path.join(base,"Color Under Pressure")
            try: os.makedirs(d,exist_ok=True); return d
            except Exception: continue
    return os.path.abspath(".")

def _copy_text(text):
    try:
        if sys.platform.startswith("win"):
            import subprocess
            subprocess.run(["clip"],input=text.encode("utf-16-le"),check=True,creationflags=0x08000000)
            return True
    except Exception: pass
    try:
        if not pygame.scrap.get_init(): pygame.scrap.init()
        pygame.scrap.put(pygame.SCRAP_TEXT,text.encode("utf-8")); return True
    except Exception: return False

def make_share_card(mode, score, rows, accent):
    W,H=1200,630; s=pygame.Surface((W,H)); t=pygame.time.get_ticks()/1000
    draw_menu_bg(s,t,accent)
    pygame.draw.rect(s,accent,(0,0,W,H),6)
    tl=ui_font(64).render("COLOR UNDER PRESSURE",True,WHITE); s.blit(tl,tl.get_rect(centerx=W//2,y=40))
    ms=ui_font(40).render(mode.upper(),True,accent); s.blit(ms,ms.get_rect(centerx=W//2,y=120))
    s.blit(_glow(200,accent,60),(W//2-200,300-200))
    sc=ui_font(210).render(str(score),True,WHITE); s.blit(sc,sc.get_rect(center=(W//2,300)))
    y=410
    line="   •   ".join(f"{k}: {v}" for k,v in rows[:3])
    ls=render_fit(ui_font(34),line,(210,210,235),W-120); s.blit(ls,ls.get_rect(centerx=W//2,y=y))
    pn=gd.get("player_name","Player"); rp=gd.get("rank_points",0); rname,rcol=get_rank(rp)
    ps=ui_font(34).render(f"{pn}  •  {rname}",True,rcol); s.blit(ps,ps.get_rect(centerx=W//2,y=470))
    import datetime as _d
    ft=ui_font(28).render(f"Can you beat me?   {SHARE_URL.replace('https://','')}   •   {_d.date.today().strftime('%d/%m/%Y')}",True,(160,160,195))
    s.blit(ft,ft.get_rect(centerx=W//2,y=H-60))
    return s

def share_score(mode, score, rows=(), accent=(40,145,255)):
    award_badge("show_off")
    """Saves a share image + copies a message. Opens the folder on Windows."""
    try:
        img=make_share_card(mode,score,list(rows),accent)
        import datetime as _d
        path=os.path.join(_share_dir(),f"score_{_d.datetime.now().strftime('%Y%m%d_%H%M%S')}.png")
        pygame.image.save(img,path)
        text=f"I scored {score} in Color Under Pressure ({mode})! Can you beat me? {SHARE_URL}"
        copied=_copy_text(text)
        SHARE["msg"]="Image saved to Pictures  •  "+("Message copied — paste it anywhere!" if copied else "Share the image with your friends!")
        SHARE["t"]=time.time(); SND_CHIME.play()
        if sys.platform.startswith("win"):
            try:
                import subprocess; subprocess.Popen(["explorer","/select,",path])
            except Exception: pass
        return path
    except Exception as e:
        SHARE["msg"]="Could not save the image"; SHARE["t"]=time.time(); print("share:",e); return None

def draw_share_msg(surf):
    if SHARE["msg"] and time.time()-SHARE["t"]<5:
        W,H=surf.get_size(); s=render_fit(ui_font(min(W,H)*0.03),SHARE["msg"],(120,230,160),W-60)
        surf.blit(s,s.get_rect(centerx=W//2,y=H-40))

