HAUNT_DATE_TXT = "25.10"
HAUNT_ORANGE   = (255,120,20)
MUSIC_HAUNT = _make_music([(110,.5),(0,.25),(104,.25),(98,.5),(0,.5),(92,.5),(87,.5),(0,.25),(82,1),
                           (0,.5),(130,.25),(123,.25),(110,1)],70,0.22)

def _make_thunder(dur=1.8, vol=0.55):
    sr=22050; n=int(sr*dur); out=bytearray(); v=0.0
    for i in range(n):
        v=v*0.985+random.uniform(-1,1)*0.15                       # low rumble (smoothed noise)
        env=min(1.0,i/(sr*0.03))*math.exp(-3.0*i/n)*(0.75+0.25*math.sin(i/sr*22))
        s=max(-32767,min(32767,int(v*env*vol*32767*3)))
        out+=bytes([s&0xFF,(s>>8)&0xFF])*2
    snd=pygame.mixer.Sound(buffer=bytes(out))
    return snd
def _make_thump(freq=55, dur=0.18, vol=0.8):
    sr=22050; n=int(sr*dur); out=bytearray()
    for i in range(n):
        t=i/sr; s=int(math.sin(2*math.pi*freq*t*(1-0.4*i/n))*math.exp(-9*t)*vol*32767)
        out+=bytes([s&0xFF,(s>>8)&0xFF])*2
    return pygame.mixer.Sound(buffer=bytes(out))
try:
    SND_THUNDER=_make_thunder(); SND_THUMP=_make_thump()
except Exception:
    SND_THUNDER=SND_BOSS; SND_THUMP=SND_TICK

_TEASER = {"t":0.0,"back":"limited_menu"}
TEASER_LEN = 24.0

TEASER_MUSIC_FILE="haunt_teaser.mp3"
TEASER_MUSIC_START=0.0
def _res_path(name):
    here=os.path.dirname(os.path.abspath(sys.executable if getattr(sys,'frozen',False) else __file__))
    base=getattr(sys,'_MEIPASS',here)
    for d in (base, here, os.path.join(here,"audio"), os.path.join(os.path.dirname(here),"audio")):
        p=os.path.join(d,name)
        if os.path.exists(p): return p
    stem=os.path.splitext(name)[0].lower()
    for d in (base, here, os.path.join(here,"audio"), os.path.join(os.path.dirname(here),"audio")):
        try:
            for f in sorted(os.listdir(d)):
                if f.lower().startswith(stem) and f.lower().endswith((".mp3",".ogg",".wav")): return os.path.join(d,f)
        except Exception: pass
    return os.path.join(base,name)
def _teaser_music_play():
    p=_res_path(TEASER_MUSIC_FILE)
    print("[teaser music]",p,"found" if os.path.exists(p) else "NOT FOUND")
    if not os.path.exists(p): return False
    try:
        global _cur_music
        pygame.mixer.stop(); _cur_music="haunt_file"
        pygame.mixer.music.load(p)
        pygame.mixer.music.set_volume(min(1.0,gd.get("music_volume",0.8)*0.9))
        pygame.mixer.music.play(0,start=TEASER_MUSIC_START)
        pygame.mixer.music.set_volume(min(1.0,gd.get("music_volume",0.8)*0.9))
        return True
    except Exception as e:
        print("[teaser music] error:",e)
        return False
def _teaser_music_stop():
    try:
        if pygame.mixer.music.get_busy(): pygame.mixer.music.fadeout(600)
    except Exception: pass

def teaser_start(back_state):
    W,H=WIDTH,HEIGHT
    def bolt():
        x=random.uniform(0.25,0.85); pts=[(x,0.0)]; y=0.0
        while y<0.62:
            y+=random.uniform(0.04,0.08); x+=random.uniform(-0.05,0.05); pts.append((x,y))
        return pts
    grain=[]
    for _ in range(3):
        g=pygame.Surface((W,H),pygame.SRCALPHA)
        for _ in range(int(W*H/180)):
            c=random.randint(140,255); g.set_at((random.randrange(W),random.randrange(H)),(c,c,c,random.randint(10,28)))
        grain.append(g)
    _TEASER.update({"t":0.0,"back":back_state,"fired":set(),"grain":grain,"size":(W,H),
        "rain":[[random.random(),random.random(),random.uniform(0.6,1.4)] for _ in range(160)],
        "fog":[[random.uniform(-0.2,1.2),random.uniform(0.62,0.9),random.uniform(0.25,0.5),random.uniform(0.01,0.03)] for _ in range(9)],
        "bolts":{3.0:bolt(),10.6:bolt(),11.0:bolt(),15.5:bolt()},
        "ghosts":[(random.choice(COLOR_NAMES),random.uniform(0.12,0.88),6.4+i*0.45,random.uniform(0,6)) for i in range(9)],
        "bats":[(random.uniform(-0.3,-0.05),random.uniform(0.15,0.4),random.uniform(0.25,0.45),random.uniform(0,6),random.uniform(0.6,1.2)) for _ in range(7)],
        "smoke":[[random.uniform(-0.6,0.6),random.uniform(0,1),random.uniform(0.5,1)] for _ in range(14)]})
    if not _teaser_music_play(): play_music("haunt")

def _jagged_light(surf,pts,W,H,a):
    P=[(int(x*W),int(y*H)) for x,y in pts]
    if len(P)>1:
        pygame.draw.lines(surf,(160,140,255),False,P,7)
        pygame.draw.lines(surf,(235,230,255),False,P,3)
        mid=P[len(P)//2]; br=[mid]
        for i in range(4): br.append((br[-1][0]+random.randint(10,30),br[-1][1]+random.randint(15,30)))
        pygame.draw.lines(surf,(220,215,255),False,br,2)

def _pumpkin2(surf,cx,cy,r,lit,t):
    if lit>0: surf.blit(_glow(int(r*2.6),HAUNT_ORANGE,int(85*lit)),(cx-int(r*2.6),cy-int(r*2.6)))
    for dx,w,c in ((-0.55,0.72,(185,75,8)),(0.55,0.72,(185,75,8)),(-0.25,0.7,(215,95,12)),(0.25,0.7,(215,95,12)),(0,0.62,(230,110,18))):
        pygame.draw.ellipse(surf,c,(cx+dx*r-w*r,cy-r*0.85,2*w*r,1.7*r))
    for dx in (-0.45,0,0.45):
        pygame.draw.arc(surf,(140,55,5),(cx+dx*r-r*0.4,cy-r*0.8,r*0.8,r*1.6),-1.2,1.2,max(1,int(r*0.03)))
    pygame.draw.rect(surf,(60,80,25),(cx-r*0.09,cy-r*1.12,r*0.18,r*0.34),border_radius=int(r*0.06))
    pygame.draw.arc(surf,(60,80,25),(cx,cy-r*1.25,r*0.5,r*0.4),2.0,3.4,max(2,int(r*0.04)))
    fl=0.75+0.25*math.sin(t*17)*math.sin(t*5.3)
    ec=_mix((25,8,3),_mix((255,230,120),(255,100,10),0.5+0.5*math.sin(t*7)),max(0.0,min(1.0,lit*fl)))
    for s in (-1,1):
        pygame.draw.polygon(surf,ec,[(cx+s*r*0.46,cy-r*0.38),(cx+s*r*0.18,cy+r*0.02),(cx+s*r*0.72,cy+r*0.02)])
    pygame.draw.polygon(surf,ec,[(cx-r*0.12,cy+r*0.08),(cx+r*0.12,cy+r*0.08),(cx,cy-r*0.12)])
    mouth=[(cx-r*0.62,cy+r*0.22),(cx-r*0.45,cy+r*0.4),(cx-r*0.32,cy+r*0.28),(cx-r*0.18,cy+r*0.46),(cx-r*0.04,cy+r*0.3),
           (cx+r*0.1,cy+r*0.47),(cx+r*0.24,cy+r*0.3),(cx+r*0.38,cy+r*0.42),(cx+r*0.62,cy+r*0.22),(cx+r*0.38,cy+r*0.62),(cx-r*0.38,cy+r*0.62)]
    pygame.draw.polygon(surf,ec,mouth)

def draw_haunt_teaser(surf, dt, events):
    """~24s cinematic trailer. Returns True when finished / skipped."""
    W,H=surf.get_size(); m=min(W,H); T=_TEASER; T["t"]+=dt; t=T["t"]
    if T.get("size")!=(W,H): teaser_start(T["back"]); T["t"]=t
    fired=T["fired"]
    def once(key,fn):
        if key not in fired: fired.add(key); fn()
    # ---------- the world (drawn on its own layer, then a slow camera push) ----------
    sc=pygame.Surface((W,H))
    for i in range(0,H,8):                                         # sky gradient
        k=i/H; pygame.draw.rect(sc,_mix((22,8,36),(6,4,10),min(1,k*1.3)),(0,i,W,8))
    mx,my=int(W*0.88),int(H*0.3)
    sc.blit(_glow(int(m*0.2),(255,215,160),40),(mx-int(m*0.2),my-int(m*0.2)))
    pygame.draw.circle(sc,(235,220,195),(mx,my),int(m*0.075))
    for cxo,cyo,cr in ((-0.02,-0.01,0.02),(0.025,0.02,0.015),(0.0,0.03,0.01)):
        pygame.draw.circle(sc,(205,190,170),(mx+int(cxo*m),my+int(cyo*m)),int(cr*m))
    for i in range(3):                                             # clouds drifting over the moon
        cx=int(((t*0.02+i*0.37)%1.4-0.2)*W); cy=int(H*(0.16+i*0.05))
        cl=pygame.Surface((int(W*0.3),int(H*0.06)),pygame.SRCALPHA)
        pygame.draw.ellipse(cl,(30,20,45,170),cl.get_rect()); sc.blit(cl,(cx,cy))
    pygame.draw.polygon(sc,(18,12,26),[(0,H*0.72),(W*0.2,H*0.64),(W*0.45,H*0.7),(W*0.7,H*0.62),(W,H*0.68),(W,H),(0,H)])
    pygame.draw.polygon(sc,(11,8,16),[(0,H*0.8),(W*0.3,H*0.74),(W*0.6,H*0.79),(W*0.85,H*0.73),(W,H*0.77),(W,H),(0,H)])
    hx,hy=int(W*0.16),int(H*0.74)                                 # haunted house
    pygame.draw.polygon(sc,(8,6,12),[(hx-70,hy),(hx-70,hy-90),(hx-82,hy-90),(hx-5,hy-160),(hx+78,hy-92),(hx+66,hy-92),(hx+70,hy)])
    pygame.draw.rect(sc,(8,6,12),(hx+30,hy-175,16,50))
    win=_mix((40,18,4),HAUNT_ORANGE,max(0.0,0.4+0.6*math.sin(t*2.7)*math.sin(t*1.3)))
    for wx,wy in ((-40,-70),(18,-68),(-12,-118)): pygame.draw.rect(sc,win,(hx+wx,hy+wy,20,24))
    pygame.draw.rect(sc,(5,3,8),(hx-10,hy-40,22,40))
    for bx,sz in ((0.38,1.0),(0.6,0.75),(0.93,1.15)):             # dead trees
        x=int(W*bx); y=int(H*0.78); s=sz*m*0.15
        pygame.draw.line(sc,(8,6,12),(x,y),(x,y-s),max(3,int(m*0.009)))
        for a,l,h in ((-0.8,0.55,0.7),(0.7,0.5,0.75),(-0.35,0.4,0.95),(1.0,0.35,0.9),(0.2,0.3,1.0)):
            pygame.draw.line(sc,(8,6,12),(x,y-s*h),(x+math.sin(a)*s*l,y-s*h-math.cos(a)*s*l),max(2,int(m*0.005)))
    for b in T["bats"]:                                            # bats
        x0,y0,sp,ph,sz=b
        if 10.4<t<14.5:
            x=(x0+(t-10.4)*sp)*W; y=(y0+0.04*math.sin(t*3+ph))*H; f=math.sin(t*22+ph)*0.6; s=m*0.02*sz
            pygame.draw.polygon(sc,(4,3,6),[(x,y),(x-s*1.6,y-s*f),(x-s*0.8,y+s*0.3),(x,y+s*0.4),(x+s*0.8,y+s*0.3),(x+s*1.6,y-s*f)])
    for f in T["fog"]:                                             # fog bands
        f[0]+=f[3]*dt
        if f[0]>1.3: f[0]=-0.3
        fs=pygame.Surface((int(W*f[2]),int(H*0.1)),pygame.SRCALPHA)
        pygame.draw.ellipse(fs,(90,80,110,38),fs.get_rect()); sc.blit(fs,(int(f[0]*W),int(f[1]*H)))
    for d in T["rain"]:                                            # rain
        d[1]=(d[1]+dt*1.1*d[2])%1.05; x=d[0]*W+d[1]*30; y=d[1]*H
        pygame.draw.line(sc,(75,75,110),(x,y),(x-4,y+13*d[2]),1)
    # ghost colour words rising out of the ground (they're scared...)
    for nm,gx,t0,ph in T["ghosts"]:
        if t0<t<t0+4.0:
            k=(t-t0)/4.0; a=int(200*math.sin(math.pi*k))
            gs=ui_font(m*0.05).render(nm,True,NEON[nm]); gs.set_alpha(a)
            sc.blit(gs,gs.get_rect(center=(int(gx*W+math.sin(t*2+ph)*24),int(H*(0.82-0.55*k)))))
    # pumpkin rising through the fog
    if t>12.8:
        k=min(1.0,(t-12.8)/2.2); ease=1-(1-k)**3
        lit=0.0 if t<15.0 else min(1.0,(t-15.0)*2.5)
        if 21.6<t<22.4: lit=1.0+0.6*math.sin(t*40)
        pr=int(m*0.15); pcx,pcy=W//2,int(H*1.2-H*0.5*ease)
        for s_ in T["smoke"]:
            s_[1]=(s_[1]+dt*0.25*s_[2])%1.0
            sm=pygame.Surface((int(pr*0.6),int(pr*0.6)),pygame.SRCALPHA)
            pygame.draw.circle(sm,(120,110,130,int(60*(1-s_[1]))),(sm.get_width()//2,)*2,sm.get_width()//2)
            sc.blit(sm,(pcx+int(s_[0]*pr)-sm.get_width()//2,pcy-int(pr*(0.9+s_[1]*1.8))))
        _pumpkin2(sc,pcx,pcy,pr,lit,t)
    # camera push-in
    z=1.07-0.07*min(1.0,max(0.0,(t-2.5)/18))
    shx,shy=(random.randint(-6,6),random.randint(-6,6)) if any(bt<=t<bt+0.25 for bt in (15.5,15.7)) else (0,0)
    if t>2.0:
        big=pygame.transform.smoothscale(sc,(int(W*z),int(H*z)))
        surf.blit(big,(-(big.get_width()-W)//2+shx,-(big.get_height()-H)//2+shy))
        fin=min(1.0,(t-2.0)/1.2)
        if fin<1:
            o=pygame.Surface((W,H)); o.set_alpha(int(255*(1-fin))); surf.blit(o,(0,0))
    else: surf.fill((0,0,0))
    # heartbeat (red pulse)
    for bt in (11.3,12.0,12.6,13.1,13.5,13.85,14.15):
        if bt<=t<bt+0.3:
            once(("hb",bt),SND_THUMP.play)
            a=int(70*(1-(t-bt)/0.3)); o=pygame.Surface((W,H),pygame.SRCALPHA); o.fill((120,0,0,a)); surf.blit(o,(0,0))
    # lightning
    for bt,pts in T["bolts"].items():
        if bt<=t<bt+0.35:
            once(("th",bt),lambda: (SND_THUNDER.play(),start_shake(10,16)))
            k=(t-bt)/0.35
            if k<0.5: _jagged_light(surf,pts,W,H,1)
            fl=pygame.Surface((W,H)); fl.fill((225,220,255)); fl.set_alpha(int(210*(1-k)*(0.6+0.4*math.sin(k*30)))); surf.blit(fl,(0,0))
    # ---------- text layer ----------
    def line(txt,a0,a1,y,col=(215,205,235),size=0.046):
        if a0<=t<=a1:
            al=max(0.0,min(1.0,(t-a0)/0.6,(a1-t)/0.6))
            s=ui_font(m*size).render(txt,True,col); s.set_alpha(int(255*al))
            surf.blit(s,s.get_rect(centerx=W//2,y=int(H*y)))
    line("MAN STUDIO PRESENTS",0.5,2.4,0.46,(170,150,190),0.035)
    line("The leaves have fallen...",3.6,6.2,0.3)
    line("...and the colors are scared.",5.0,7.6,0.38)
    if 7.8<t<10.4:                                                 # Stroop command glitches into RUN.
        glitch=t>9.2 and int(t*20)%3!=0
        cmd="RUN." if t>9.6 else "GO TO  RED!"
        col=(255,60,60) if t>9.6 else NEON["BLUE"]
        cs=ui_font(m*0.1).render(cmd,True,col)
        al=min(1.0,(t-7.8)/0.4,(10.4-t)/0.3); cs.set_alpha(int(255*al))
        ox=random.randint(-8,8) if glitch else 0
        if glitch:
            c2=ui_font(m*0.1).render(cmd,True,(60,230,255)); c2.set_alpha(int(150*al))
            surf.blit(c2,c2.get_rect(center=(W//2+ox+6,int(H*0.36))))
        surf.blit(cs,cs.get_rect(center=(W//2+ox,int(H*0.36))))
    line("Something is coming for them.",11.0,14.6,0.28,(255,165,110))
    # title slam, letter by letter
    if t>15.6:
        title="THE HAUNT"; f=ui_font(m*0.15); xs=[]; tw=0
        for chh in title: w_=f.size(chh)[0]; xs.append(w_); tw+=w_
        x=W//2-tw//2; y0=int(H*0.09)
        for i,chh in enumerate(title):
            t0=15.6+i*0.12
            if t<t0: x+=xs[i]; continue
            if chh!=" ": once(("l",i),SND_THUMP.play)
            k=min(1.0,(t-t0)/0.15); s=f.render(chh,True,HAUNT_ORANGE)
            sz=2.2-1.2*k; s2=pygame.transform.rotozoom(s,0,sz); s2.set_alpha(int(255*k))
            r=s2.get_rect(center=(x+xs[i]//2,y0+s.get_height()//2)); surf.blit(s2,r)
            if k>=1 and chh!=" ":
                L=int(min(1.0,(t-t0-0.2)/1.8)*m*0.05*(0.4+((i*37)%10)/12))
                if L>0: pygame.draw.line(surf,(190,60,0),(x+xs[i]//2,y0+int(s.get_height()*0.85)),(x+xs[i]//2,y0+int(s.get_height()*0.85)+L),max(2,int(m*0.006)))
            x+=xs[i]
        if t>16.8:
            g=_glow(int(tw*0.45),(255,80,0),int(40*min(1,(t-16.8)))); surf.blit(g,(W//2-int(tw*0.45),y0+int(m*0.07)-int(tw*0.45)))
    if t>17.6:
        k=min(1.0,(t-17.6)/0.6)
        d=ui_font(m*0.11).render(HAUNT_DATE_TXT,True,WHITE); d.set_alpha(int(255*k))
        surf.blit(d,d.get_rect(centerx=W//2,y=int(H*0.29)))
        try:
            import datetime as _d
            days=(_d.date.fromisoformat(SEASONS["haunt"]["start"])-_d.date.today()).days
        except Exception: days=-1
        sub=("IN 1 DAY" if days==1 else (f"IN {days} DAYS" if days>1 else ("TODAY" if days==0 else "")))
        if sub:
            ss=ui_font(m*0.036).render(sub,True,(255,170,90)); ss.set_alpha(int(255*k))
            surf.blit(ss,ss.get_rect(centerx=W//2,y=int(H*0.29)+d.get_height()+4))
    line("Candy.  Ghosts.  Pressure.",18.8,23.6,0.47,(230,200,170),0.038)
    line("Color Under Pressure  •  Halloween update",19.6,23.6,0.53,(170,150,190),0.03)
    if 22.0<t<22.5:                                                # glitch whisper
        o=pygame.Surface((W,H),pygame.SRCALPHA); o.fill((0,0,0,170)); surf.blit(o,(random.randint(-10,10),0))
        ws=ui_font(m*0.04).render("don't look behind you",True,(200,30,30))
        surf.blit(ws,ws.get_rect(center=(W//2+random.randint(-6,6),int(H*0.5))))
    # letterbox + grain + vignette
    bar=int(H*0.085*min(1.0,t/0.8)); pygame.draw.rect(surf,(0,0,0),(0,0,W,bar)); pygame.draw.rect(surf,(0,0,0),(0,H-bar,W,bar))
    surf.blit(T["grain"][int(t*24)%3],(0,0))
    v=pygame.Surface((W,H),pygame.SRCALPHA)
    for i in range(7): pygame.draw.rect(v,(0,0,0,34),(i*12,i*12,W-i*24,H-i*24),14)
    surf.blit(v,(0,0))
    sk=ui_font(m*0.024).render("Click or ESC to close" if t>17.6 else "Click or ESC to skip",True,(110,100,130))
    surf.blit(sk,sk.get_rect(right=W-14,bottom=H-6))
    done=t>TEASER_LEN or (t>0.4 and any((e.type==pygame.MOUSEBUTTONDOWN and e.button==1) or (e.type==pygame.KEYDOWN and e.key in (pygame.K_ESCAPE,pygame.K_SPACE,pygame.K_RETURN)) for e in events))
    if done: _teaser_music_stop(); play_music("menu")
    return done

