def draw_skin_deco(c, sname, t, w, h):
    """Little themed art behind each skin card, so every skin looks like its name."""
    rnd=random.Random(sum(map(ord,sname)))
    A=lambda col,a: (*col,int(a))
    if sname=="Classic":
        for x in range(0,w,24): pygame.draw.line(c,(255,255,255,14),(x,0),(x,h))
        for y in range(0,h,24): pygame.draw.line(c,(255,255,255,14),(0,y),(w,y))
    elif sname=="Pastel":
        for i in range(5):
            x=(rnd.random()*w+t*12*(1+i%2))%(w+80)-40; y=h*0.75+rnd.random()*h*0.2
            for dx,rr in ((-18,16),(0,22),(20,15)): pygame.draw.circle(c,(255,255,255,40),(int(x+dx),int(y)),rr)
    elif sname=="Dark Gold":
        for i in range(-2,8): pygame.draw.line(c,(255,210,80,22),(i*50,h),(i*50+h,0),6)
        for i in range(10):
            x,y=rnd.random()*w,rnd.random()*h; tw=0.5+0.5*math.sin(t*4+i)
            pygame.draw.line(c,(255,225,120,int(160*tw)),(x-5,y),(x+5,y),2); pygame.draw.line(c,(255,225,120,int(160*tw)),(x,y-5),(x,y+5),2)
    elif sname=="Retro":
        for y in range(0,h,4): pygame.draw.line(c,(0,0,0,55),(0,y),(w,y))
        for i in range(8):
            x=int(rnd.random()*(w-12)); y=int(h*0.72+rnd.random()*h*0.2)
            pygame.draw.rect(c,A(rnd.choice([(216,40,0),(0,88,248),(0,168,0),(248,184,0)]),110),(x,y,10,10))
    elif sname=="Neon Fire":
        for i in range(12):
            x=i*w/11; fh=h*(0.18+0.12*abs(math.sin(t*5+i*1.7)))
            pygame.draw.polygon(c,(255,60,20,120),[(x-22,h),(x+22,h),(x,h-fh)]); pygame.draw.polygon(c,(255,200,40,120),[(x-10,h),(x+10,h),(x,h-fh*0.55)])
    elif sname=="Ocean":
        for k,(col,a) in enumerate((((40,140,255),70),((20,210,200),60),((255,255,255),40))):
            pts=[(0,h)]+[(x,h*(0.78+0.06*k)+math.sin(x/28+t*2+k)*6) for x in range(0,w+12,12)]+[(w,h)]
            pygame.draw.polygon(c,(*col,a),pts)
        for i in range(6):
            yy=(h-((t*30+i*40)%h)); pygame.draw.circle(c,(255,255,255,70),(int(15+rnd.random()*(w-30)),int(yy)),3+i%3,1)
    elif sname=="Galaxy":
        for i in range(40):
            tw=0.5+0.5*math.sin(t*3+i); pygame.draw.circle(c,(255,255,255,int(60+150*tw)),(int(rnd.random()*w),int(rnd.random()*h)),1+(i%7==0))
        px,py,pr=int(w*0.82),int(h*0.82),int(min(w,h)*0.12)
        pygame.draw.circle(c,(180,90,255,140),(px,py),pr); pygame.draw.ellipse(c,(255,200,255,120),(px-pr*1.7,py-pr*0.3,pr*3.4,pr*0.6),2)
    elif sname=="Maple":
        for i in range(7):
            x=(rnd.random()*w+math.sin(t+i)*20)%w; y=(rnd.random()*h+t*25*(0.6+rnd.random()))%(h+30)-15
            draw_maple(c,int(x),int(y),9+i%3*3,rnd.choice([(235,90,30),(250,160,40),(200,50,30)]),t+i,140)
    elif sname=="Lava Lamp":
        for i in range(6):
            ph=(t*0.12+i/6)%1.0; x=w*(0.15+0.7*rnd.random())+math.sin(t+i)*10; y=h*(1.1-ph*1.3); rr=int(14+10*math.sin(t*1.3+i))
            pygame.draw.circle(c,(255,110,40,120),(int(x),int(y)),max(6,rr)); pygame.draw.circle(c,(255,200,80,90),(int(x-rr*0.3),int(y-rr*0.3)),max(3,rr//3))
    elif sname=="Candy Shop":
        off=int(t*20)%40
        for i in range(-2,w//20+4): pygame.draw.polygon(c,(255,255,255,26),[(i*40-off,0),(i*40+20-off,0),(i*40+20-off-h,h),(i*40-off-h,h)])
        for i in range(5):
            x,y=int(rnd.random()*w),int(h*0.78+rnd.random()*h*0.16); col=rnd.choice([(255,90,140),(110,200,255),(255,230,100)])
            pygame.draw.circle(c,(*col,170),(x,y),8); pygame.draw.polygon(c,(*col,170),[(x-8,y),(x-16,y-6),(x-16,y+6)]); pygame.draw.polygon(c,(*col,170),[(x+8,y),(x+16,y-6),(x+16,y+6)])
    elif sname=="Arctic Aurora":
        for k,col in enumerate(((60,255,180),(150,110,255),(70,170,255))):
            pts=[(x,h*(0.2+0.1*k)+math.sin(x/40+t*1.2+k*2)*14) for x in range(0,w+10,10)]
            for j in range(1,len(pts)): pygame.draw.line(c,(*col,70),pts[j-1],pts[j],10)
        for i in range(12):
            y=(rnd.random()*h+t*18)%h; pygame.draw.circle(c,(255,255,255,140),(int(rnd.random()*w),int(y)),2)
    elif sname=="Pumpkin Patch":
        for i in range(3):
            x=int(w*(0.2+i*0.3)); y=int(h*0.86)+int(math.sin(t*2+i)*2)
            pygame.draw.circle(c,(255,120,20,int(60+30*math.sin(t*3+i))),(x,y),16)
            ui_icon2(c,"pumpkin",x,y,11,(255,130,30),t)
        for i in range(2):
            x=(t*30+i*130)%(w+40)-20; draw_bat(c,x,int(h*0.15)+i*14,7,t+i,(25,10,30))
    elif sname=="The Him":
        for i,w_ in enumerate(("SCARY","ALONE","FREAK")):
            s_=ui_font(13).render(w_,True,(120,10,16)); s_.set_alpha(int(110+60*math.sin(t*1.5+i))); c.blit(s_,(int(w*(0.06+0.32*i)),int(h*(0.12+0.3*(i%2)))))
        bl_=(int(t*3)%9)!=0
        for ex in (-1,1):
            pygame.draw.ellipse(c,(255,30,30) if bl_ else (60,0,0),(w//2+ex*int(w*0.08)-6,int(h*0.82)-3,12,6))
    elif sname=="Moonlight":
        for i in range(30):
            tw=0.5+0.5*math.sin(t*2.5+i); pygame.draw.circle(c,(220,230,255,int(50+140*tw)),(int(rnd.random()*w),int(rnd.random()*h*0.8)),1+(i%9==0))
        mx,my,mr=int(w*0.8),int(h*0.8),int(min(w,h)*0.14)
        pygame.draw.circle(c,(230,235,255,50),(mx,my),int(mr*1.6)); pygame.draw.circle(c,(235,240,255,170),(mx,my),mr)
        pygame.draw.circle(c,(*SKIN_BG["Moonlight"][0],200),(mx+int(mr*0.45),my-int(mr*0.25)),mr)
    elif sname=="Frostbite":
        for i in range(9):
            x=(rnd.random()*w+math.sin(t+i)*8)%w; y=(rnd.random()*h+t*14*(0.6+rnd.random()))%h; sz=4+i%3*2
            for a_ in range(3):
                ang=a_*math.pi/3+t*0.5; dx,dy=math.cos(ang)*sz,math.sin(ang)*sz
                pygame.draw.line(c,(230,250,255,150),(x-dx,y-dy),(x+dx,y+dy),1)
        pts=[(0,h*0.78)]+[(x,h*0.78+(-10 if (x//14)%2 else 0)) for x in range(0,w+14,14)]+[(w,h),(0,h)]
        pygame.draw.polygon(c,(200,240,255,60),pts)
    elif sname=="Ember":
        for i in range(16):
            ph=(t*0.35+rnd.random())%1.0; x=rnd.random()*w+math.sin(t*2+i)*10; y=h*(1-ph)
            pygame.draw.circle(c,(255,int(120+100*(1-ph)),30,int(200*(1-ph))),(int(x),int(y)),2+(i%3==0))
        pygame.draw.rect(c,(255,90,10,40),(0,int(h*0.85),w,int(h*0.15)))
    elif sname=="Phantom":
        for i in range(3):
            gx=(t*18*(1+i*0.3)+i*w*0.4)%(w+60)-30; gy=h*(0.72+0.06*math.sin(t*2+i)); gs=10+i*3
            pygame.draw.circle(c,(220,240,255,70),(int(gx),int(gy)),gs); pygame.draw.rect(c,(220,240,255,70),(int(gx-gs),int(gy),gs*2,gs))
            for ex in (-0.35,0.35): pygame.draw.circle(c,(20,20,40,120),(int(gx+ex*gs),int(gy-2)),2)
        for k in range(3):
            pts=[(x,h*(0.15+0.1*k)+math.sin(x/30+t*1.5+k)*6) for x in range(0,w+10,10)]
            for j in range(1,len(pts)): pygame.draw.line(c,(160,220,255,30),pts[j-1],pts[j],6)
    elif sname=="Witching Hour":
        cx,cy,cr=int(w*0.82),int(h*0.2),int(min(w,h)*0.12)
        pygame.draw.circle(c,(230,220,255,60),(cx,cy),cr,2)
        for a_,ln in ((t*0.6,0.8),(t*0.05,0.55)): pygame.draw.line(c,(230,220,255,110),(cx,cy),(cx+math.sin(a_)*cr*ln,cy-math.cos(a_)*cr*ln),2)
        bx,by=int(w*0.18),int(h*0.88); pygame.draw.ellipse(c,(20,10,25,170),(bx-18,by-12,36,22))
        for i in range(5):
            ph=(t*0.6+i/5)%1.0; pygame.draw.circle(c,(130,255,60,int(170*(1-ph))),(bx-8+i*4,int(by-12-ph*30)),3)
    elif sname=="Eclipse":
        ex,ey,er=int(w*0.5),int(h*0.5),int(min(w,h)*0.22)
        for k in range(5,0,-1): pygame.draw.circle(c,(255,190,60,int(14*k*(0.8+0.2*math.sin(t*2)))),(ex,ey),er+k*5)
        pygame.draw.circle(c,(255,220,120,120),(ex,ey),er+2,2); pygame.draw.circle(c,(0,0,0,235),(ex,ey),er)
        for i in range(10):
            a_=i*0.628+t*0.3; pygame.draw.line(c,(255,200,80,50),(ex+math.cos(a_)*er*1.1,ey+math.sin(a_)*er*1.1),(ex+math.cos(a_)*er*1.6,ey+math.sin(a_)*er*1.6),2)
    elif sname=="Midnight Arcade":
        hy=int(h*0.62)
        for i in range(-8,9): pygame.draw.line(c,(255,40,200,80),(w//2+i*16,hy),(w//2+i*60,h),1)
        for k in range(6):
            z=((k+t*1.5)%6)/6; y=int(hy+(h-hy)*z*z); pygame.draw.line(c,(0,220,255,int(40+100*z)),(0,y),(w,y),1)
        inv=["..X.....X..","...X...X...","..XXXXXXX..",".XX.XXX.XX.","XXXXXXXXXXX","X.XXXXXXX.X"]
        bx=int(w*0.72+math.sin(t*2)*8); by=int(h*0.08)+2
        for yy,row in enumerate(inv):
            for xx,ch in enumerate(row):
                if ch=="X": pygame.draw.rect(c,(0,255,120,90),(bx+xx*3,by+yy*3,3,3))

_skin_msg={"text":"","col":(255,255,255),"t":0}
def draw_skin_card_classic(canvas, r0, sname, locked, is_eq, t, dt, mouse):
    W,H=WIDTH,HEIGHT; cw_s=r0.w
    hv=ui_hover("sk_"+sname,1.0 if r0.collidepoint(mouse) and not locked else 0.0,dt); r=r0.move(0,-int(6*hv))
    bc=(255,215,60) if is_eq else ((70,70,95) if locked else _mix((90,90,160),WHITE,0.4*hv))
    if is_eq: canvas.blit(_glow(int(cw_s*0.6),(255,215,60),40),(r.centerx-int(cw_s*0.6),r.centery-int(cw_s*0.6)))
    pygame.draw.rect(canvas,(16,16,30),r,border_radius=16); pygame.draw.rect(canvas,bc,r,2,border_radius=16)
    sk2=SKINS[sname]; sw=(r.w-32)//3; sh_=int(r.h*0.22)
    for j,cn in enumerate(["RED","BLUE","GREEN","YELLOW","PURPLE","ORANGE"]):
        c_=sk2[cn] if not locked else _mix(sk2[cn],(20,20,30),0.7)
        pygame.draw.rect(canvas,c_,(r.x+12+(j%3)*(sw+4),r.y+12+(j//3)*(sh_+4),sw,sh_),border_radius=6)
    nm_=render_fit(ui_font(min(W,H)*0.036),sname,WHITE if not locked else (110,110,130),r.w-20)
    canvas.blit(nm_,nm_.get_rect(centerx=r.centerx,y=r.y+24+2*sh_))
    if is_eq: stt,stc="EQUIPPED",(255,215,60)
    elif not locked: stt,stc="EQUIP",(120,180,255)
    elif skin_cost(sname): stt,stc=f"{skin_cost(sname)[0]} {skin_cost(sname)[1]}",(255,210,90)
    else: stt,stc=SKIN_HINT.get(sname,"LOCKED"),(130,130,160)
    ss_=ui_font(min(W,H)*0.026).render(stt,True,stc); canvas.blit(ss_,ss_.get_rect(centerx=r.centerx,bottom=r.bottom-10))
    if locked: ui_icon2(canvas,"lock",r.right-18,r.y+18,8,(130,130,160))

def draw_skin_card(surf, r0, sname, locked, is_eq, t, dt, mouse):
    if classic_design(): return draw_skin_card_classic(surf,r0,sname,locked,is_eq,t,dt,mouse)
    W,H=surf.get_size(); sk=SKINS[sname]; rar=SKIN_RARITY.get(sname,"COMMON"); rc=RARITY_COL[rar]
    _sc=skin_cost(sname) if locked else None; price=_sc[0] if _sc else None; cur_=_sc[1] if _sc else "coins"
    can_buy=locked and price is not None and (haunt_data()["candy"]>=price and haunt_state()=="active" if cur_=="candy" else gd.get("coins",0)>=price)
    hv=ui_hover("sk_"+sname,1.0 if r0.collidepoint(mouse) else 0.0,dt); r=r0.move(0,-int(6*hv))
    if is_eq: surf.blit(_glow(int(r.w*0.6),(255,215,60),45),(r.centerx-int(r.w*0.6),r.centery-int(r.w*0.6)))
    elif rar in ("LEGENDARY","EVENT") and not locked: surf.blit(_glow(int(r.w*0.5),rc,25),(r.centerx-int(r.w*0.5),r.centery-int(r.w*0.5)))
    c1,c2=SKIN_BG.get(sname,((30,30,60),(10,10,22)))
    card=pygame.Surface(r.size,pygame.SRCALPHA)
    for yy in range(r.h):
        k=yy/max(1,r.h-1); pygame.draw.line(card,_mix(c1,c2,k)+(255,),(0,yy),(r.w,yy))
    draw_skin_deco(card,sname,t,r.w,r.h)
    # moving shine
    sx=int(((t*0.35+sum(map(ord,sname))%100/100)%1.6-0.3)*r.w)
    pygame.draw.polygon(card,(255,255,255,18),[(sx,0),(sx+40,0),(sx-40,r.h),(sx-80,r.h)])
    mask=pygame.Surface(r.size,pygame.SRCALPHA); pygame.draw.rect(mask,(255,255,255,255),mask.get_rect(),border_radius=16)
    card.blit(mask,(0,0),special_flags=pygame.BLEND_RGBA_MIN); surf.blit(card,r.topleft)
    # mini game preview: 3x2 tiles with color words, like the real game
    names=["RED","BLUE","GREEN","YELLOW","PURPLE","ORANGE"]; pad=10; tw=(r.w-2*pad-8)//3; th=int(r.h*0.2)
    for j,cn in enumerate(names):
        c_=sk[cn]; tr_=pygame.Rect(r.x+pad+(j%3)*(tw+4),r.y+30+(j//3)*(th+4),tw,th)
        pygame.draw.rect(surf,_mix(c_,(0,0,0),0.35),tr_.move(0,3),border_radius=8)
        pygame.draw.rect(surf,c_,tr_,border_radius=8); pygame.draw.rect(surf,_mix(c_,WHITE,0.35),tr_.inflate(-tr_.w*0.2,-tr_.h*0.75).move(0,-tr_.h*0.28),border_radius=4)
        wl=render_fit(ui_font(th*0.42),names[(j+2)%6],WHITE,tw-6); surf.blit(wl,wl.get_rect(center=tr_.center))
    # rarity ribbon
    rs_=ui_font(min(W,H)*0.018).render(rar,True,(15,15,25)); rb=rs_.get_rect(topleft=(r.x+10,r.y+7)).inflate(14,4)
    pygame.draw.rect(surf,rc,rb,border_radius=rb.h//2); surf.blit(rs_,rs_.get_rect(center=rb.center))
    # name + status
    ny=r.y+34+2*th+10
    nm_=render_fit(ui_font(min(W,H)*0.034),sname,WHITE,r.w-20); surf.blit(nm_,nm_.get_rect(centerx=r.centerx,y=ny))
    if is_eq: stt,stc,fill=("EQUIPPED",(30,25,5),(255,215,60))
    elif not locked: stt,stc,fill=("EQUIP",(10,20,40),(120,180,255))
    elif price is not None and cur_=="candy" and haunt_state()!="active": stt,stc,fill=("THE HAUNT ONLY",(200,200,220),None); price=None
    elif price is not None: stt,stc,fill=(f"BUY  {price}",(30,25,5) if can_buy else (230,225,240),(255,200,40) if can_buy else (95,88,110))
    else: stt,stc,fill=(SKIN_HINT.get(sname,"LOCKED"),(200,200,220),None)
    bf=ui_font(min(W,H)*0.024); bs=bf.render(stt,True,stc if fill else (150,150,175))
    br=bs.get_rect(centerx=r.centerx,bottom=r.bottom-10).inflate(26,10)
    if fill: pygame.draw.rect(surf,fill,br,border_radius=br.h//2)
    if price is not None and locked:
        if cur_=="candy": draw_candy(surf,br.x+14,br.centery,7,(255,120,170) if can_buy else (140,110,120))
        else: ui_icon2(surf,"coin",br.x+14,br.centery,7,(255,215,60) if can_buy else (140,130,90))
    surf.blit(bs,bs.get_rect(center=(br.centerx+(8 if (price is not None and locked) else 0),br.centery)))
    if locked:
        dim=pygame.Surface(r.size,pygame.SRCALPHA); pygame.draw.rect(dim,(0,0,0,85 if not can_buy else 45),dim.get_rect(),border_radius=16)
        surf.blit(dim,r.topleft); ui_icon2(surf,"lock",r.right-18,r.y+18,8,(200,200,220))
        surf.blit(bs,bs.get_rect(center=(br.centerx+(8 if price is not None else 0),br.centery)))
    pygame.draw.rect(surf,(255,215,60) if is_eq else _mix(rc,WHITE,0.3*hv),r,2+int(is_eq),border_radius=16)

_badge_pop={"id":None,"t":0}
def draw_badge_popup(surf, events, t):
    """Big card for the clicked badge: description + unlocked or not. Returns True while open."""
    if not _badge_pop["id"]: return False
    b=get_badge(_badge_pop["id"])
    if not b: _badge_pop["id"]=None; return False
    W,H=surf.get_size(); m=min(W,H); earned=has_badge(b["id"]); col=badge_grad(b)[0] if earned else CAT_COL.get(b["cat"],WHITE)
    k=min(1.0,(time.time()-_badge_pop["t"])/0.25); e=1-(1-k)**3
    sh=pygame.Surface((W,H),pygame.SRCALPHA); sh.fill((0,0,0,int(170*e))); surf.blit(sh,(0,0))
    pw,ph=int(min(W*0.5,620)),int(m*0.62); pr=pygame.Rect(0,0,pw,ph); pr.center=(W//2,H//2+int((1-e)*60))
    pygame.draw.rect(surf,(12,12,24),pr,border_radius=16)
    if earned:
        _gp=_grad_surf(pr.w,pr.h,badge_grad(b),35+badge_frame(b,t)*15).copy(); _gp.fill((95,95,95),special_flags=pygame.BLEND_RGB_MULT)
        _gm=pygame.Surface(pr.size,pygame.SRCALPHA); pygame.draw.rect(_gm,(255,255,255,255),_gm.get_rect(),border_radius=16)
        _gs=pygame.Surface(pr.size,pygame.SRCALPHA); _gs.blit(_gp,(0,0)); _gs.blit(_gm,(0,0),special_flags=pygame.BLEND_RGBA_MIN); surf.blit(_gs,pr.topleft)
    if earned: grad_rect(surf,pr,badge_grad(b),4,16,35+badge_frame(b,t)*15)
    else: ui_panel(surf,pr,None,col)
    draw_badge_medal(surf,b,pr.centerx,pr.y+int(ph*0.2),int(ph*0.13),earned,t,0.6)
    cat_names=dict(CAT_NAME); cat_names["unlisted"]="UNLISTED" if not b.get("dev_only") else "UNLISTED  (DEV ONLY)"
    ct=ui_font(m*0.024).render(cat_names.get(b["cat"],""),True,col); surf.blit(ct,ct.get_rect(centerx=pr.centerx,y=pr.y+int(ph*0.45)))
    nm=grad_text(ui_font(m*0.06),b["name"],[_mix(c_,WHITE,0.25) for c_ in badge_grad(b)],pw-40) if earned else render_fit(ui_font(m*0.06),b["name"],WHITE,pw-40)
    surf.blit(nm,nm.get_rect(centerx=pr.centerx,y=pr.y+int(ph*0.5)))
    ds=render_fit(ui_font(m*0.032),b["desc"],(205,205,225),pw-40); surf.blit(ds,ds.get_rect(centerx=pr.centerx,y=pr.y+int(ph*0.62)))
    if earned: st,sc,bg=("UNLOCKED",(15,40,20),(70,220,120))
    else: st,sc,bg=("NOT UNLOCKED YET",(230,230,240),(70,70,95))
    ss=ui_font(m*0.03).render(st,True,sc); sr=ss.get_rect(centerx=pr.centerx,y=pr.y+int(ph*0.74)).inflate(30,12)
    pygame.draw.rect(surf,bg,sr,border_radius=sr.h//2); surf.blit(ss,ss.get_rect(center=sr.center))
    rw=ui_font(m*0.022).render(f"Reward: +{BADGE_COINS} coins",True,(255,215,90)); surf.blit(rw,rw.get_rect(centerx=pr.centerx,y=sr.bottom+10))
    hint=ui_font(m*0.02).render("Click anywhere to close",True,(130,130,160)); surf.blit(hint,hint.get_rect(centerx=pr.centerx,bottom=pr.bottom-10))
    eq_r=None
    if earned:                                            # EQUIP: show this badge next to your name
        is_eq=gd.get("equipped_badge")==b["id"]
        eq_r=pygame.Rect(0,0,170,36); eq_r.midtop=(pr.centerx,rw.get_rect(centerx=pr.centerx,y=sr.bottom+10).bottom+8)
        mo=pygame.mouse.get_pos(); hv=eq_r.collidepoint(mo)
        pygame.draw.rect(surf,(255,200,40) if is_eq else ((90,90,150) if hv else (60,60,100)),eq_r,border_radius=18)
        es_=ui_font(m*0.026).render("EQUIPPED" if is_eq else "EQUIP",True,(30,20,5) if is_eq else WHITE); surf.blit(es_,es_.get_rect(center=eq_r.center))
    for ev in events:
        if eq_r and ev.type==pygame.MOUSEBUTTONDOWN and ev.button==1 and eq_r.collidepoint(ev.pos):
            gd["equipped_badge"]=None if gd.get("equipped_badge")==b["id"] else b["id"]; save_gd(gd); SND_CHIME.play()
            if gd["equipped_badge"]: award_badge("style_points")
            return True
        if (ev.type==pygame.MOUSEBUTTONDOWN and ev.button==1 and time.time()-_badge_pop["t"]>0.15) or (ev.type==pygame.KEYDOWN and ev.key in (pygame.K_ESCAPE,pygame.K_RETURN,pygame.K_SPACE)):
            _badge_pop["id"]=None; SND_SELECT.play(); break
    return True

_coin_anim={"shown":None,"pop":0.0}
def draw_coin_chip(surf, mouse, dt, x, y):
    """Big coin counter for the top of the main menu. Returns its rect (click = skins shop)."""
    co=gd.get("coins",0)
    if _coin_anim["shown"] is None: _coin_anim["shown"]=co
    if _coin_anim["shown"]!=co:
        diff=co-_coin_anim["shown"]; step=max(1,abs(diff)//12)
        _coin_anim["shown"]+=step if diff>0 else -step
        if abs(co-_coin_anim["shown"])<step: _coin_anim["shown"]=co
        _coin_anim["pop"]=1.0
    _coin_anim["pop"]=max(0.0,_coin_anim["pop"]-dt*3)
    f=ui_font(30); ts=f.render(f"{_coin_anim['shown']:,}",True,(255,225,110))
    r=pygame.Rect(0,y,ts.get_width()+78,44)
    r.x=x if x is not None else surf.get_width()-r.w-16
    hv=ui_hover("coinchip",1.0 if r.collidepoint(mouse) else 0.0,dt)
    pygame.draw.rect(surf,_mix((40,30,6),(70,52,10),hv),r,border_radius=22); pygame.draw.rect(surf,(255,200,40),r,2,border_radius=22)
    ui_icon2(surf,"coin",r.x+24,r.centery,int(13+3*_coin_anim["pop"]),(255,200,40))
    surf.blit(ts,ts.get_rect(midleft=(r.x+44,r.centery)))
    pl=ui_font(18).render("+",True,(255,200,40)); pygame.draw.circle(surf,(255,200,40),(r.right-14,r.centery),9,2); surf.blit(pl,pl.get_rect(center=(r.right-14,r.centery)))
    return r

