# ---------- FX: "I Need Glasses" blur, Flow celebrations ----------
GLASSES_LEN=5.5
def draw_glasses_fx(surf, game):
    t0=getattr(game,"glasses_t",0)
    if not t0: return
    el=time.time()-t0
    if el>GLASSES_LEN: return
    k=min(1.0,el/0.8) if el<GLASSES_LEN-1.2 else max(0.0,(GLASSES_LEN-el)/1.2)
    W,H=surf.get_size(); f=max(4,int(14*k))
    small=pygame.transform.smoothscale(surf,(max(1,W//f),max(1,H//f))); blur=pygame.transform.smoothscale(small,(W,H))
    blur.set_alpha(int(255*k)); surf.blit(blur,(0,0))
    wob=math.sin(el*3)*6
    ui_icon2(surf,"glasses",W//2,int(H*0.36+wob),int(min(W,H)*0.07),(255,255,255))
    tt=ui_font(min(W,H)*0.075).render("I NEED GLASSES",True,(255,255,255)); tt.set_alpha(int(255*min(1,k*1.5)))
    surf.blit(tt,tt.get_rect(center=(W//2,int(H*0.5))))
    st=ui_font(min(W,H)*0.03).render("100 points! Your eyes need a break...",True,(220,220,240)); st.set_alpha(int(220*k))
    surf.blit(st,st.get_rect(center=(W//2,int(H*0.58))))


