FLOW_FX={"clear_t":0,"lvl":0,"win_t":0}
_FLOW_COLS=[(255,60,80),(40,150,255),(40,220,100),(255,215,40),(180,70,255),(255,140,30),(60,220,230),(255,100,180)]
def draw_flow_clear(surf):
    el=time.time()-FLOW_FX["clear_t"]
    if el>1.0 or not FLOW_FX["clear_t"]: return
    W,H=surf.get_size(); k=1-el
    for i in range(10):
        a=i/10*math.tau; r=int(min(W,H)*0.08+el*min(W,H)*0.4)
        pygame.draw.circle(surf,_FLOW_COLS[i%8],(int(W/2+math.cos(a)*r),int(H/2+math.sin(a)*r)),max(2,int(10*k)))
    ts=ui_font(min(W,H)*0.07).render(f"LEVEL {FLOW_FX['lvl']} CLEAR!",True,(255,255,255))
    sc=1+0.3*max(0,1-el*4); ts=pygame.transform.rotozoom(ts,0,sc); ts.set_alpha(int(255*min(1,k*2)))
    surf.blit(ts,ts.get_rect(center=(W//2,H//2)))

def draw_flow_win(surf, events, score):
    """Big 'all 20 levels done' celebration. Returns True when finished (or skipped)."""
    el=time.time()-FLOW_FX["win_t"]; W,H=surf.get_size(); m=min(W,H)
    surf.fill((6,8,20))
    # pipes racing across the screen, like a giant Flow board being solved
    for i in range(8):
        y=int(H*(0.12+i*0.11)); col=_FLOW_COLS[i]; prog_=min(1.0,max(0.0,(el-i*0.12)/1.2))
        x1=int(W*prog_); pts=[]
        for x in range(0,x1+1,max(1,W//60)):
            pts.append((x,y+int(math.sin(x/90+i)*H*0.02)))
        if len(pts)>1: pygame.draw.lines(surf,col,False,pts,max(6,m//60))
        if pts: pygame.draw.circle(surf,col,pts[-1],max(10,m//35)); pygame.draw.circle(surf,col,(0,y),max(10,m//35))
    # fireworks
    rng_=random.Random(7)
    for b in range(6):
        bt=0.8+b*0.45; age=el-bt
        cx,cy=rng_.randint(int(W*0.15),int(W*0.85)),rng_.randint(int(H*0.15),int(H*0.6))
        if 0<age<1.4:
            col=_FLOW_COLS[b%8]
            for j in range(18):
                a=j/18*math.tau; r=age*m*0.22
                pygame.draw.circle(surf,_mix(col,(255,255,255),0.3),(int(cx+math.cos(a)*r),int(cy+math.sin(a)*r+age*age*40)),max(2,int(6*(1-age/1.4))))
    if el>1.2:
        k=min(1.0,(el-1.2)/0.5); e=1+(1.9+1)*(k-1)**3+1.9*(k-1)**2
        ts=ui_font(m*0.13).render("FLOW MASTER!",True,(255,255,255)); ts=pygame.transform.rotozoom(ts,0,max(0.01,e))
        gl=ui_font(m*0.13).render("FLOW MASTER!",True,(40,150,255)); gl=pygame.transform.rotozoom(gl,0,max(0.01,e))
        surf.blit(gl,gl.get_rect(center=(W//2+5,H//2+5))); surf.blit(ts,ts.get_rect(center=(W//2,H//2)))
    if el>2.0:
        st=ui_font(m*0.04).render(f"All 20 levels cleared  •  {score} points",True,(255,215,90)); st.set_alpha(int(255*min(1,(el-2.0)*2)))
        surf.blit(st,st.get_rect(center=(W//2,int(H*0.64))))
    if el>3.0:
        hn=ui_font(m*0.024).render("Click to continue",True,(150,150,180)); surf.blit(hn,hn.get_rect(center=(W//2,int(H*0.9))))
    skip=el>1.0 and any(ev.type==pygame.MOUSEBUTTONDOWN and ev.button==1 or (ev.type==pygame.KEYDOWN and ev.key in (pygame.K_ESCAPE,pygame.K_RETURN,pygame.K_SPACE)) for ev in events)
    return el>6.0 or skip

