def _h_today(): return __import__("datetime").date.today()

def haunt_state():
    """'before' / 'active' / 'after' for THE HAUNT (DEV MODE opens it early)."""
    if dev_mode(): return "active"
    return season_state("haunt")

def haunt_data():
    h=gd.setdefault("haunt",{})
    yr=_h_today().year
    if h.get("year")!=yr:                      # THE HAUNT comes back every year: fresh mansion
        keep=h.get("design_unlocked",False)
        h.clear(); h["design_unlocked"]=keep; h["year"]=yr
    h.setdefault("rooms",[0]*HAUNT_ROOMS)       # 0 = never, 1 = tricked, 2 = treat
    h.setdefault("visited",[False]*HAUNT_ROOMS)
    # an older save (or a save from a newer build) can hold a different number of rooms:
    # keep what the player did and resize the lists to THIS build. Never crash on it.
    for _k,_fill in (("rooms",0),("visited",False)):
        _v=h.get(_k)
        if not isinstance(_v,list): _v=[]
        if len(_v)!=HAUNT_ROOMS:
            _v=(list(_v)+[_fill]*HAUNT_ROOMS)[:HAUNT_ROOMS]
        h[_k]=_v
    for k,v in (("candy",0),("candy_total",0),("shadow_found",False),("shadow_closed",False),
                ("treat_streak",0),("intro_seen",False),("lia_best",0),("tricks",0),("treats",0)):
        h.setdefault(k,v)
    h.setdefault("inv",{"freeze":0,"life":0,"flash":0})
    return h

def haunt_quests():
    h=haunt_data(); vis=sum(1 for v in h["visited"] if v)
    return [("Trick or treat in 10 rooms",min(vis,10),10),
            ("Collect 100 candies",min(h["candy_total"],100),100),
            ("Collect 500 candies",min(h["candy_total"],500),500),
            ("Find THE SHADOW",1 if h["shadow_found"] else 0,1),
            ("Slam the door on THE SHADOW",1 if h["shadow_closed"] else 0,1)]

def haunt_quests_done(): return sum(1 for _,a,b in haunt_quests() if a>=b)
def haunt_all_rooms(): return all(r==2 for r in haunt_data()["rooms"])

def haunt_check_rewards():
    h=haunt_data(); q=haunt_quests()
    if q[0][1]>=10: award_badge("trick_or_treater")
    if h["candy_total"]>=100: award_badge("sugar_rush")
    if h["candy_total"]>=500: award_badge("sugar_attack")
    if haunt_all_rooms(): award_badge("mansion_master")
    if haunt_quests_done()==5:
        um=gd.setdefault("unlocked_modes",[])
        if "halloween" not in um:
            um.append("halloween")
            _badge_toasts.append({"id":None,"t":None,"custom":True,"title":"HALLOWEEN MODE","name":"Yours forever!",
                                  "desc":"All 5 quests done","col":H_ORANGE,"icon":"pumpkin"})
    if haunt_quests_done()==5 and haunt_all_rooms() and not h.get("design_unlocked"):
        h["design_unlocked"]=True
        _badge_toasts.append({"id":None,"t":None,"custom":True,"title":"HALLOWEEN DESIGN","name":"Unlocked!",
                              "desc":"Settings > DESIGN","col":H_PURPLE,"icon":"pumpkin"})
    save_gd(gd)

def haunt_add_candy(n):
    h=haunt_data(); h["candy"]+=n; h["candy_total"]+=n; haunt_check_rewards()

def halloween_available(): return haunt_state()=="active" or "halloween" in gd.get("unlocked_modes",[])
def lia_forever():         return has_badge("listened_lia") and has_badge("ignored_lia")      # both Lia badges = Lia Said forever
def lia_extra():           return haunt_state()=="after" and _today()<=gd.get("lia_extra_until","")   # code LIASAID: 5 more days (15-19/11)
def lia_available():
    hs=haunt_state()
    if hs=="before": return False
    return hs=="active" or lia_forever() or lia_extra()
def halloween_design_on(): return gd.get("design")=="halloween" and haunt_data().get("design_unlocked")
def spooky_menu():         return haunt_state()=="active" or halloween_design_on()

# ── sounds ────────────────────────────────────────────────────────────────────
def _h_noise(dur, vol, f0, f1, rough=0.5):
    sr=22050; n=int(sr*dur); buf=bytearray(); ph=0.0
    for i in range(n):
        k=i/n; f=f0+(f1-f0)*k; ph+=2*math.pi*f/sr
        v=(math.sin(ph)*(1-rough)+random.uniform(-1,1)*rough)*math.sin(math.pi*k)**0.6
        val=max(-32767,min(32767,int(v*vol*32767)))
        buf+=bytes([val&0xFF,(val>>8)&0xFF])*2
    return pygame.mixer.Sound(buffer=bytes(buf*2))
SND_SCREAM = _h_noise(0.9,0.55,900,240,0.55)
SND_CREAK  = _h_noise(0.8,0.30,95,60,0.15)
SND_SLAM   = _h_noise(0.35,0.7,70,40,0.8)

# ── drawing helpers ───────────────────────────────────────────────────────────
_h_bg_cache={}
def haunt_background(W, H):
    key=(W,H)
    if key in _h_bg_cache: return _h_bg_cache[key]
    s=pygame.Surface((W,H))
    for y in range(H):
        k=y/H; pygame.draw.line(s,_mix((22,8,40),(6,4,12),k),(0,y),(W,y))
    rnd=random.Random(31)
    for _ in range(90):
        x=rnd.randint(0,W); y=rnd.randint(0,int(H*0.6)); c=rnd.randint(90,200)
        s.set_at((x,y),(c,c,c+20))
    for i in range(7):                                       # far hills
        pygame.draw.circle(s,(14,8,22),(int(W*(i/6)),H+int(H*0.25)),int(H*0.42))
    _h_bg_cache[key]=s; return s

def draw_moon(surf, cx, cy, r):
    surf.blit(_glow(int(r*2.4),(255,230,170),70),(cx-int(r*2.4),cy-int(r*2.4)))
    pygame.draw.circle(surf,(250,236,190),(cx,cy),r)
    for dx,dy,rr in ((-0.3,-0.2,0.18),(0.25,0.15,0.13),(-0.05,0.35,0.1)):
        pygame.draw.circle(surf,(225,208,160),(int(cx+dx*r),int(cy+dy*r)),max(2,int(rr*r)))

def draw_bat(surf, x, y, s, t, col=(10,6,16)):
    f=math.sin(t*14)*0.6
    pygame.draw.polygon(surf,col,[(x,y),(x-s,y-s*0.5*(1+f)),(x-s*0.6,y+s*0.1),(x-s*1.3,y+s*0.1*(1-f)),(x-s*0.4,y+s*0.45),
                                  (x,y+s*0.3),(x+s*0.4,y+s*0.45),(x+s*1.3,y+s*0.1*(1-f)),(x+s*0.6,y+s*0.1),(x+s,y-s*0.5*(1+f))])

def draw_ghost(surf, cx, cy, s, t, alpha=235, eyes=(20,10,30)):
    g=pygame.Surface((int(s*2.4),int(s*3)),pygame.SRCALPHA); ox=int(s*1.2); oy=int(s*1.1)
    bob=0
    pygame.draw.circle(g,(240,240,255,alpha),(ox,oy),int(s))
    pygame.draw.rect(g,(240,240,255,alpha),(ox-int(s),oy,int(s*2),int(s*1.2)))
    for i in range(4):
        wx=ox-int(s)+int(i*s*0.5)+int(s*0.25); wy=oy+int(s*1.2)+int(math.sin(t*6+i)*s*0.08)
        pygame.draw.circle(g,(240,240,255,alpha),(wx,wy),int(s*0.25))
    pygame.draw.ellipse(g,eyes+(255,),(ox-int(s*0.5),oy-int(s*0.25),int(s*0.32),int(s*0.45)))
    pygame.draw.ellipse(g,eyes+(255,),(ox+int(s*0.18),oy-int(s*0.25),int(s*0.32),int(s*0.45)))
    pygame.draw.ellipse(g,eyes+(255,),(ox-int(s*0.18),oy+int(s*0.35),int(s*0.36),int(s*0.3)))
    surf.blit(g,(cx-ox,cy-oy+bob))

def draw_host(surf, kind, cx, cy, s, t):
    """The character that opens the door."""
    if kind=="ghost": draw_ghost(surf,cx,cy,s,t)
    elif kind=="pumpkin":
        pygame.draw.rect(surf,(40,20,60),(cx-s*0.6,cy+s*0.8,s*1.2,s*1.6),border_radius=int(s*0.3))
        ui_icon2(surf,"pumpkin",cx,cy,s*1.05,H_ORANGE,t)
        for ex in (-0.35,0.35): pygame.draw.polygon(surf,(255,230,90),[(cx+ex*s-s*0.15,cy-s*0.05),(cx+ex*s+s*0.15,cy-s*0.05),(cx+ex*s,cy-s*0.32)])
    elif kind=="skeleton":
        pygame.draw.rect(surf,(225,225,215),(cx-s*0.12,cy+s*0.8,s*0.24,s*1.5))
        for k in range(3): pygame.draw.rect(surf,(225,225,215),(cx-s*0.55,cy+s*(1.0+k*0.35),s*1.1,s*0.12),border_radius=4)
        ui_icon2(surf,"skull",cx,cy,s*0.95,(235,235,225),t)
    elif kind=="witch":
        pygame.draw.polygon(surf,(60,20,90),[(cx-s*0.9,cy+s*2.4),(cx+s*0.9,cy+s*2.4),(cx+s*0.4,cy+s*0.7),(cx-s*0.4,cy+s*0.7)])
        pygame.draw.circle(surf,(130,200,90),(int(cx),int(cy+s*0.2)),int(s*0.62))
        pygame.draw.polygon(surf,(40,15,60),[(cx-s*1.0,cy-s*0.25),(cx+s*1.0,cy-s*0.25),(cx+s*0.15,cy-s*1.6)])
        for ex in (-0.22,0.22): pygame.draw.circle(surf,(20,10,10),(int(cx+ex*s),int(cy+s*0.15)),max(2,int(s*0.08)))
        pygame.draw.arc(surf,(40,20,20),(cx-s*0.25,cy+s*0.25,s*0.5,s*0.35),3.4,6.0,2)
    elif kind=="vampire":
        pygame.draw.polygon(surf,(120,10,25),[(cx-s*1.1,cy+s*2.4),(cx+s*1.1,cy+s*2.4),(cx+s*0.7,cy+s*0.5),(cx-s*0.7,cy+s*0.5)])
        pygame.draw.circle(surf,(225,215,230),(int(cx),int(cy+s*0.1)),int(s*0.6))
        pygame.draw.polygon(surf,(20,10,20),[(cx-s*0.6,cy-s*0.1),(cx,cy-s*0.6),(cx+s*0.6,cy-s*0.1),(cx,cy-s*0.3)])
        for ex in (-0.22,0.22): pygame.draw.circle(surf,(200,20,30),(int(cx+ex*s),int(cy+s*0.08)),max(2,int(s*0.09)))
        for fx in (-0.1,0.1): pygame.draw.polygon(surf,WHITE,[(cx+fx*s-3,cy+s*0.35),(cx+fx*s+3,cy+s*0.35),(cx+fx*s,cy+s*0.5)])

def draw_candy(surf, cx, cy, s, col, ang=0.0):
    c,sn=math.cos(ang),math.sin(ang)
    for side in (-1,1):
        p=[(0.55*side,0),(1.0*side,-0.45),(1.0*side,0.45)]
        pygame.draw.polygon(surf,_mix(col,WHITE,0.25),[(cx+(x*c-y*sn)*s,cy+(x*sn+y*c)*s) for x,y in p])
    pygame.draw.circle(surf,col,(int(cx),int(cy)),max(2,int(s*0.55)))
    pygame.draw.circle(surf,_mix(col,WHITE,0.55),(int(cx-s*0.18),int(cy-s*0.18)),max(1,int(s*0.16)))

def draw_spooky_overlay(surf, t):
    """Extra layer for menus during THE HAUNT (or with the Halloween design)."""
    W,H=surf.get_size()
    o=pygame.Surface((W,H),pygame.SRCALPHA); o.fill((40,0,60,60)); surf.blit(o,(0,0))
    draw_moon(surf,W-90,int(H*0.2),int(min(W,H)*0.05))
    for i in range(5):
        x=(t*60*(0.6+i*0.15)+i*233)%(W+200)-100; y=int(H*0.12)+int(math.sin(t*1.5+i)*25)+i*28
        draw_bat(surf,x,y,10+i%3*4,t+i)
    for i in range(6):
        x=int(W*(0.06+i*0.18)); y=H-14
        surf.blit(_glow(26,H_ORANGE,int(40+30*math.sin(t*3+i))),(x-26,y-26-8))
        ui_icon2(surf,"pumpkin",x,y-8,13,H_ORANGE,t)

# =============================================================================
#  ORE MODE  —  MAN STUDIO  x  BURGERS STUDIOS   (15/11 - 5/12/2026)
#  You are told which ore to mine. Every ore you get is 5 MINE COINS.
#  Mine Coins buy pickaxes and skins, and a weaker pickaxe takes longer to swing.
#  On the last day the two studios fight, and you pick a side.
# =============================================================================
SEASONS["ore"] = {"start":"2026-11-15","end":"2026-12-05","name":"ORE MODE"}
ORE_BOSS_DAY   = "2026-12-05"          # the battle is the last day of the collab
ORE_PER_ORE    = 5                     # mine coins per ore
ORE_LIVES      = 3
ORE_BADGE_IDS  = ("miner_beginner","miner_advanced","miner_pro","miner_lover","mining_judge")
ORE_SKIN_IDS   = ("Deep Mine","Molten Core")
BURGER_COL     = (240, 170, 60)
RUSHY_COL      = (120, 205, 255)

# name -> (rock colour, ore-speck colour, how often it shows up, how hard it is)
ORES = {
    "COAL":    ((58,58,66),   (26,26,30),  1.0, 0.70),
    "IRON":    ((122,104,88), (214,186,150),1.0, 0.90),
    "REDSTONE":((96,58,58),   (228,52,52),  0.9, 1.00),
    "GOLD":    ((104,92,52),  (255,206,60), 0.9, 1.10),
    "DIAMOND": ((78,104,116), (110,236,255),0.7, 1.35),
    "EMERALD": ((66,104,76),  (70,226,120), 0.7, 1.50),
}
ORE_NAMES = list(ORES.keys())

# id, name, swings it takes on an average ore, price in mine coins
# YOU swing it - every click of the mouse is one hit. A worse pickaxe is more work.
PICKAXES = [
    ("stone",   "Stone Pickaxe",   8, 0),
    ("iron",    "Iron Pickaxe",    6, 150),
    ("gold",    "Gold Pickaxe",    5, 400),
    ("diamond", "Diamond Pickaxe", 4, 900),
    ("emerald", "Emerald Pickaxe", 3, 1800),
]
PICK_COL = {"stone":(150,150,158),"iron":(214,186,150),"gold":(255,206,60),
            "diamond":(110,236,255),"emerald":(70,226,120)}
ORE_SKIN_PRICE = {"Deep Mine":800, "Molten Core":1500}

def ore_state():
    """'before' / 'active' / 'after'. A DEV account can open it early."""
    if dev_mode(): return "active"
    if not ORE_ENABLED: return "before"
    return season_state("ore")

_ORE_SHOWN = {"v": ORE_ENABLED}
def _ore_sync(vis):
    """The two mine skins live in SKINS only while ORE MODE is visible. Both directions,
    so signing out of a DEV account puts them away again."""
    if vis == _ORE_SHOWN["v"]: return
    _ORE_SHOWN["v"] = vis
    for _k, _pal in list(_ORE_SKINS_HELD.items()):
        if vis: SKINS[_k] = _pal
        else:   SKINS.pop(_k, None)

def ore_visible():
    """ORE MODE is hidden from players until 15/11 - a DEV account sees it today.
    This is the ONLY question the rest of the game should ask about the collab."""
    v = True if ORE_ENABLED else dev_mode()
    _ore_sync(v)
    return v

def ore_boss_day():
    return _today() >= ORE_BOSS_DAY and ore_state() == "active"

def ore_data():
    """Self-healing, like haunt_data and streak_data: an old or broken save must
    never take the game down."""
    o = gd.get("ore")
    if not isinstance(o, dict):
        o = {}; gd["ore"] = o
    yr = _h_today().year if "_h_today" in globals() else 2026
    if o.get("year") != yr:
        keep = {k: o.get(k) for k in ("picks","skins") if isinstance(o.get(k), list)}
        o.clear(); o["year"] = yr; o.update(keep)
    for k, v, typ in (("coins",0,int),("mined",0,int),("best",0,int),
                      ("pick","stone",str),("boss_side","",str),("boss_done",False,bool),
                      ("boss_won",False,bool),("intro_seen",False,bool)):
        try: o[k] = typ(o[k]) if k in o and o[k] is not None else v
        except Exception: o[k] = v
    for k in ("picks","skins"):
        if not isinstance(o.get(k), list): o[k] = []
    if "stone" not in o["picks"]: o["picks"].append("stone")
    if o["pick"] not in [p[0] for p in PICKAXES]: o["pick"] = "stone"
    if o["pick"] not in o["picks"]: o["pick"] = "stone"
    o["coins"] = max(0, o["coins"]); o["mined"] = max(0, o["mined"])
    return o

def ore_pick_info(pid=None):
    o = ore_data(); pid = pid or o["pick"]
    for p in PICKAXES:
        if p[0] == pid: return p
    return PICKAXES[0]

def ore_swings(ore=None):
    """How many clicks this ore takes with the pickaxe you have equipped."""
    base = ore_pick_info()[2]
    hard = ORES.get(ore, (0,0,0,1.0))[3] if ore else 1.0
    return max(2, int(round(base * hard)))

def ore_check_badges():
    o = ore_data()
    if o["mined"] >= 25:  award_badge("miner_beginner")
    if o["mined"] >= 150: award_badge("miner_advanced")
    if o["mined"] >= 500: award_badge("miner_pro")
    if "emerald" in o["picks"]: award_badge("miner_lover")
    if o.get("boss_done"):     award_badge("mining_judge")

def ore_earn(n):
    o = ore_data(); o["coins"] += int(n); o["mined"] += 1
    o["best"] = max(o["best"], o["mined"])
    ore_check_badges(); save_gd(gd)

# ── drawing an ore ───────────────────────────────────────────────────────────
_ORE_CACHE = {}
def ore_tile_surf(name, w, h, lit=False):
    k = (name, w, h, lit)
    if k in _ORE_CACHE: return _ORE_CACHE[k]
    rock, spec = ORES.get(name, ORES["COAL"])[:2]
    s = pygame.Surface((w, h), pygame.SRCALPHA)
    r = max(6, min(w, h) // 7)
    pygame.draw.rect(s, rock, (0, 0, w, h), border_radius=r)
    rnd = random.Random(hash(name) & 0xffff)
    for _ in range(int(w * h / 900)):                    # rough stone
        x, y = rnd.randrange(w), rnd.randrange(h)
        d = rnd.choice([(0,0,0,40), (255,255,255,22)])
        pygame.draw.circle(s, d, (x, y), rnd.randint(1, max(2, w // 36)))
    for _ in range(7):                                    # the ore itself
        x = rnd.randint(int(w*.18), int(w*.82)); y = rnd.randint(int(h*.18), int(h*.82))
        rr = rnd.randint(max(3, w//16), max(5, w//9))
        pygame.draw.circle(s, spec, (x, y), rr)
        pygame.draw.circle(s, tuple(min(255, c+60) for c in spec), (x-rr//3, y-rr//3), max(1, rr//2))
    pygame.draw.rect(s, (255,255,255,38), (0, 0, w, h), 2, border_radius=r)
    if lit:
        gl = pygame.Surface((w, h), pygame.SRCALPHA)
        pygame.draw.rect(gl, spec + (70,), (0, 0, w, h), border_radius=r)
        s.blit(gl, (0, 0))
    _ORE_CACHE.clear() if len(_ORE_CACHE) > 60 else None
    _ORE_CACHE[k] = s
    return s

_CRACK_SEEDS = {}
def _ore_cracks(surf, rc, frac, name):
    """Cracks spreading across the rock as you hit it."""
    if frac <= 0: return
    key = (name, rc.w, rc.h)
    if key not in _CRACK_SEEDS:
        rnd = random.Random(hash(key) & 0xffff)
        legs = []
        for _ in range(7):
            a0 = rnd.uniform(0, math.tau)
            pts = [(rc.w/2, rc.h/2)]
            for _st in range(4):
                a0 += rnd.uniform(-.7, .7)
                L = min(rc.w, rc.h) * rnd.uniform(.10, .17)
                pts.append((pts[-1][0] + math.cos(a0)*L, pts[-1][1] + math.sin(a0)*L))
            legs.append(pts)
        if len(_CRACK_SEEDS) > 40: _CRACK_SEEDS.clear()
        _CRACK_SEEDS[key] = legs
    legs = _CRACK_SEEDS[key]
    n = max(1, int(len(legs) * min(1.0, frac)))
    for pts in legs[:n]:
        p2 = [(rc.x+x, rc.y+y) for x, y in pts]
        pygame.draw.lines(surf, (10, 8, 6), False, p2, max(4, int(rc.w*0.026)))
        pygame.draw.lines(surf, (248, 242, 230), False, p2, max(2, int(rc.w*0.011)))

def draw_pickaxe(surf, cx, cy, size, pid, t=0.0):
    col = PICK_COL.get(pid, (170,170,178))
    L = size
    ang = -0.6 + 0.25 * math.sin(t * 3.0)
    hx, hy = cx - math.cos(ang) * L * .55, cy + math.sin(ang) * L * .55
    tx, ty = cx + math.cos(ang) * L * .45, cy - math.sin(ang) * L * .45
    pygame.draw.line(surf, (110, 78, 46), (hx, hy), (tx, ty), max(3, int(L * .14)))
    px, py = tx, ty
    pygame.draw.arc(surf, col, (px - L*.42, py - L*.30, L*.84, L*.60), 0.15, math.pi - 0.15, max(3, int(L*.16)))
    pygame.draw.circle(surf, tuple(min(255, c+40) for c in col), (int(px), int(py)), max(2, int(L*.09)))

# ── the round ────────────────────────────────────────────────────────────────
class OreRound:
    """kind: 'mine' (endless, three lives) or 'boss' (the studios fight)."""
    def __init__(s, kind="mine"):
        s.kind = kind
        s.score = 0; s.mistakes = 0; s.coins = 0
        s.lives = ORE_LIVES
        s.intro = 2.0; s.result = None; s.result_t = 0.0
        s.hits = 0; s.hits_need = 0; s.swing_cell = None
        s.chips = []; s.kick = 0.0
        s.pops = []; s.flash = 0.0; s.flash_col = WHITE
        s.size = (0, 0)
        s.us = 0.0; s.them = 0.0            # boss bars
        s.boss_t = 0.0
        s.build(); s.new_q()

    def build(s):
        W, H = WIDTH, HEIGHT; s.size = (W, H)
        cols, rows = 4, 3
        top = int(H * 0.36); bot = H - int(H * 0.09); m = int(W * 0.11)
        cw = (W - 2*m) // cols; ch = (bot - top) // rows
        s.tw, s.th = cw - 12, ch - 12
        s.grid = []
        for r in range(rows):
            for c in range(cols):
                s.grid.append({"name": "COAL", "x": m + c*cw + 6, "y": top + r*ch + 6})

    def rect(s, c): return pygame.Rect(int(c["x"]), int(c["y"]), s.tw, s.th)

    def new_q(s):
        if (WIDTH, HEIGHT) != s.size: s.build()
        pool = []
        for n, v in ORES.items(): pool += [n] * int(v[2] * 10)
        random.shuffle(pool)
        for i, c in enumerate(s.grid): c["name"] = pool[i % len(pool)]
        s.target = random.choice(ORE_NAMES)
        if not any(c["name"] == s.target for c in s.grid):
            random.choice(s.grid)["name"] = s.target
        s.hits = 0; s.swing_cell = None; s.chips = []
        s.deadline = time.time() + s.tlim()

    def tlim(s):
        # finding it, plus a fair amount of time to actually swing at it
        base = 3.0 if s.kind == "mine" else 2.7
        return max(1.6, base * (0.985 ** s.score)) + ore_swings(s.target) * 0.42

    def update(s, dt):
        if s.result is not None:
            s.result_t += dt; return
        if s.intro > 0:
            s.intro -= dt; s.deadline = time.time() + s.tlim(); return
        s.flash = max(0.0, s.flash - dt * 2.4)
        for p in s.pops[:]:
            p["t"] += dt
            if p["t"] > 1.0: s.pops.remove(p)
        if s.kind == "boss":
            s.boss_t += dt
            s.them = min(1.0, s.them + dt * 0.030)         # the rival clears the bar in ~33s
            if s.them >= 1.0 and s.us < 1.0: s.finish(False)
        s.kick = max(0.0, s.kick - dt * 5.0)
        for ch in s.chips[:]:                               # flying rock
            ch["t"] += dt
            if ch["t"] > ch["life"]: s.chips.remove(ch); continue
            ch["x"] += ch["vx"] * dt; ch["y"] += ch["vy"] * dt; ch["vy"] += 900 * dt
        if time.time() > s.deadline:
            s.miss()

    def start_swing(s, cell):
        s.swing_cell = cell; s.hits = 0
        s.hits_need = ore_swings(cell["name"])
        s.swing_hit()                                        # the first click already counts

    def swing_hit(s):
        """One click of the mouse = one swing of the pickaxe."""
        c = s.swing_cell
        if c is None or s.result is not None: return
        s.hits += 1; s.kick = 1.0
        rc = s.rect(c); spec = ORES[c["name"]][1]
        for _ in range(9):                                   # chips fly off
            a_ = random.uniform(-math.pi, 0)
            sp = random.uniform(120, 420)
            s.chips.append({"x": rc.centerx + random.uniform(-rc.w*.22, rc.w*.22),
                            "y": rc.centery + random.uniform(-rc.h*.18, rc.h*.18),
                            "vx": math.cos(a_)*sp, "vy": math.sin(a_)*sp,
                            "c": spec if random.random() < .5 else ORES[c["name"]][0],
                            "r": random.uniform(2, 5), "t": 0.0, "life": random.uniform(.35, .75)})
        try:
            start_shake(3 + 2*(s.hits >= s.hits_need))
            (SND_CHIME if s.hits >= s.hits_need else SND_SELECT).play()
        except Exception: pass
        if s.hits >= s.hits_need: s.hit()

    def hit(s):
        c = s.swing_cell; s.swing_cell = None; s.kick = 1.0
        s.score += 1; s.coins += ORE_PER_ORE
        ore_earn(ORE_PER_ORE)
        _sp = ORES[s.target][1]
        s.flash = 1.0; s.flash_col = _sp if sum(_sp) > 300 else _mix(_sp, (255,255,255), 0.5)
        if c: s.pops.append({"x": c["x"] + s.tw/2, "y": c["y"], "t": 0.0, "txt": f"+{ORE_PER_ORE}"})
        try: SND_CORRECT.play()
        except Exception: pass
        if s.kind == "boss":
            s.us = min(1.0, s.us + 0.055)                   # 19 ores to win
            if s.us >= 1.0: s.finish(True); return
        s.new_q()

    def miss(s):
        s.mistakes += 1; s.lives -= 1
        s.flash = 1.0; s.flash_col = (235, 70, 70)
        s.swing_cell = None; s.chips = []
        try: SND_WRONG.play(); start_shake(8)
        except Exception: pass
        if s.kind == "boss":
            s.them = min(1.0, s.them + 0.035)
        if s.lives <= 0 and s.kind == "mine": s.finish(False)
        else: s.new_q()

    def finish(s, won):
        s.result = "win" if won else "lose"; s.result_t = 0.0
        o = ore_data()
        if s.kind == "boss":
            o["boss_done"] = True; o["boss_won"] = bool(won and o.get("boss_side") == "rushy")
            award_badge("mining_judge")
        ore_check_badges(); save_gd(gd)

    def click(s, pos):
        if s.result is not None or s.intro > 0: return
        if s.swing_cell is not None:
            s.swing_hit()                                    # already mining: keep swinging, anywhere
            return
        for c in s.grid:
            if s.rect(c).collidepoint(pos):
                if c["name"] == s.target: s.start_swing(c)
                else: s.miss()
                return

# ── the round on screen ──────────────────────────────────────────────────────
def draw_ore_round(surf, r, dt, mouse, events):
    W, H = surf.get_size(); m = min(W, H)
    rock, spec = ORES[r.target][:2]
    # COAL's ore colour is almost black - the headline needs a readable version of it
    hot = spec if sum(spec) > 300 else _mix(spec, (255, 255, 255), 0.62)
    for y in range(0, H, 6):
        q = y / float(H)
        pygame.draw.rect(surf, _mix((26,22,20), (10,9,8), q), (0, y, W, 6))
    for i in range(26):                                   # cave dust
        x = (i * 137 + int(pygame.time.get_ticks()*0.02)) % W
        y = (i * 311 + int(pygame.time.get_ticks()*0.012)) % H
        pygame.draw.circle(surf, (70, 62, 54), (x, y), 1)
    if r.flash > 0:
        o = pygame.Surface((W, H)); o.fill(r.flash_col); o.set_alpha(int(60*r.flash)); surf.blit(o, (0, 0))

    # what to mine
    hd = ui_font(m*0.030).render(tr("MINE THIS ORE"), True, (168, 152, 132))
    surf.blit(hd, hd.get_rect(center=(W//2, int(H*0.085))))
    surf.blit(_glow(int(m*0.16), hot, 44), (W//2-int(m*0.16), int(H*0.155)-int(m*0.16)))
    ts = _outlined(r.target, m*0.105, hot, (14,12,10), 5)
    surf.blit(ts, ts.get_rect(center=(W//2, int(H*0.155))))

    # time + lives + coins
    left = max(0.0, r.deadline - time.time())
    bw = int(W*0.44); bx = W//2 - bw//2; by = int(H*0.235)
    pygame.draw.rect(surf, (36,30,26), (bx, by, bw, 12), border_radius=6)
    fr = max(0.0, min(1.0, left / max(0.001, r.tlim())))
    pygame.draw.rect(surf, _mix((225,80,60), (120,210,120), fr), (bx, by, int(bw*fr), 12), border_radius=6)
    cs = ui_font(m*0.034).render(f"{tr('MINE COINS')}: {ore_data()['coins']}", True, (255, 206, 60))
    surf.blit(cs, (int(W*0.035), int(H*0.035)))
    if r.kind == "mine":
        for i in range(ORE_LIVES):
            col = (235,80,70) if i < r.lives else (60,52,46)
            pygame.draw.circle(surf, col, (W-int(W*0.04)-i*int(m*0.045), int(H*0.045)), max(5, int(m*0.016)))
    else:
        for side, val, col, y in (("MAN STUDIO", r.us, RUSHY_COL, int(H*0.028)),
                                  ("BURGERS STUDIOS", r.them, BURGER_COL, int(H*0.062))):
            bw2 = int(W*0.26); bx2 = W-int(W*0.035)-bw2
            pygame.draw.rect(surf, (36,30,26), (bx2, y, bw2, 14), border_radius=7)
            pygame.draw.rect(surf, col, (bx2, y, int(bw2*val), 14), border_radius=7)
            ls = ui_font(m*0.022).render(side, True, col)
            surf.blit(ls, ls.get_rect(midright=(bx2-10, y+7)))

    # the board
    for c in r.grid:
        rc = r.rect(c)
        lit = (r.swing_cell is c)
        if lit and r.kick > 0:                             # the rock jumps when you hit it
            k = max(1, int(r.kick * m * 0.014))
            rc = rc.move(random.randint(-k, k), random.randint(-k, k) + int(r.kick*m*0.008))
        surf.blit(ore_tile_surf(c["name"], rc.w, rc.h, lit), rc.topleft)
        if lit and r.hits_need:
            _ore_cracks(surf, rc, r.hits / float(r.hits_need), c["name"])
        nm = render_fit(ui_font(min(m*0.030, rc.h*0.26)), c["name"], (248,244,238), rc.w-14)
        sh = render_fit(ui_font(min(m*0.030, rc.h*0.26)), c["name"], (10,8,6), rc.w-14)
        surf.blit(sh, sh.get_rect(center=(rc.centerx+2, rc.centery+2)))
        surf.blit(nm, nm.get_rect(center=rc.center))
        if lit:
            left = max(0, r.hits_need - r.hits)
            br = max(12, int(min(rc.w, rc.h) * 0.19))       # inside the tile, not over the one above
            bc = (rc.right - br - 6, rc.y + br + 6)
            pygame.draw.circle(surf, (12, 10, 8), bc, br)
            pygame.draw.circle(surf, ORES[c["name"]][1], bc, br, 3)
            hs = ui_font(br * 1.5).render(str(left), True, (252, 248, 240))
            surf.blit(hs, hs.get_rect(center=bc))
            draw_pickaxe(surf, rc.x + br + 6, rc.y + br + 6, br * 1.25,
                         ore_data()["pick"], r.kick * 2.2)
    for ch in r.chips:                                      # chips of rock in the air
        a_ = max(0, min(255, int(255 * (1 - ch["t"]/ch["life"]))))
        cs_ = pygame.Surface((int(ch["r"]*2)+2, int(ch["r"]*2)+2), pygame.SRCALPHA)
        pygame.draw.circle(cs_, tuple(ch["c"]) + (a_,), (int(ch["r"])+1, int(ch["r"])+1), int(ch["r"]))
        surf.blit(cs_, (ch["x"], ch["y"]))
    if r.swing_cell is not None:
        kt = render_fit(ui_font(m*0.028), tr("KEEP CLICKING"), (236, 200, 120), int(W*0.5))
        surf.blit(kt, kt.get_rect(center=(W//2, int(H*0.300))))

    for p in r.pops:
        a = int(255 * max(0.0, 1-p["t"]))
        ps = ui_font(m*0.040).render(p["txt"], True, (255, 206, 60)); ps.set_alpha(a)
        surf.blit(ps, ps.get_rect(center=(p["x"], p["y"]-p["t"]*m*0.10)))

    if r.intro > 0:
        o = pygame.Surface((W, H), pygame.SRCALPHA); o.fill((8,7,6, int(190*min(1.0, r.intro/0.6))))
        surf.blit(o, (0, 0))
        big = _outlined(tr("GET MINING"), m*0.09, (255,206,60), (14,12,10), 5)
        surf.blit(big, big.get_rect(center=(W//2, int(H*0.44))))
        pk = ore_pick_info()
        sub = ui_font(m*0.032).render(f"{tr(pk[1])}  •  ~{pk[2]} {tr('swings per ore')}", True, (200,186,166))
        surf.blit(sub, sub.get_rect(center=(W//2, int(H*0.54))))
        draw_pickaxe(surf, W//2, int(H*0.65), m*0.12, ore_data()["pick"], pygame.time.get_ticks()/300.0)

def draw_ore_result(surf, r, dt, mouse):
    W, H = surf.get_size(); m = min(W, H)
    o = pygame.Surface((W, H), pygame.SRCALPHA); o.fill((8,7,6,225)); surf.blit(o, (0, 0))
    if r.kind == "boss":
        od = ore_data()
        won_side = "rushy" if r.result == "win" else "burgers"
        nm = "MAN STUDIO" if won_side == "rushy" else "BURGERS STUDIOS"
        col = RUSHY_COL if won_side == "rushy" else BURGER_COL
        ts = _outlined(nm + " " + tr("WINS"), m*0.072, col, (10,9,8), 5)
        surf.blit(ts, ts.get_rect(center=(W//2, int(H*0.30))))
        side = od.get("boss_side", "")
        msg = tr("You called it.") if side == won_side else tr("You backed the other one.")
        ms = ui_font(m*0.036).render(msg, True, (210,200,186))
        surf.blit(ms, ms.get_rect(center=(W//2, int(H*0.42))))
    else:
        ts = _outlined(tr("OUT OF LIVES"), m*0.070, (235,90,70), (10,9,8), 5)
        surf.blit(ts, ts.get_rect(center=(W//2, int(H*0.30))))
    for i, (lab, val) in enumerate(((tr("Ores mined"), r.score), (tr("Mine Coins earned"), r.coins))):
        y = int(H*0.50) + i*int(m*0.075)
        ls = ui_font(m*0.034).render(lab, True, (170,158,140)); surf.blit(ls, ls.get_rect(midright=(W//2-14, y)))
        vs = ui_font(m*0.044).render(str(val), True, (255,206,60)); surf.blit(vs, vs.get_rect(midleft=(W//2+14, y)))
    return ui_pill(surf, "ore_back", pygame.Rect(W//2-int(m*0.14), int(H*0.76), int(m*0.28), int(m*0.075)),
                   tr("BACK"), (200,160,70), 0.016, mouse, "back")

# ── the hub ──────────────────────────────────────────────────────────────────
OS_ = {"screen": "hub", "back": "limited_menu", "round": None, "t": 0.0}

def ore_open(screen="hub", back="limited_menu"):
    OS_.update({"screen": screen, "back": back, "round": None, "t": 0.0})
    ore_data()

def draw_ore_hub(surf, dt, mouse, events, t):
    W, H = surf.get_size(); m = min(W, H)
    o = ore_data()
    for y in range(0, H, 6):
        q = y/float(H); pygame.draw.rect(surf, _mix((34,28,24), (12,10,9), q), (0, y, W, 6))
    top = draw_header(surf, tr("ORE MODE"), "MAN STUDIO  x  BURGERS STUDIOS", (255,206,60), t)
    cs = ui_font(m*0.040).render(f"{o['coins']}  {tr('MINE COINS')}", True, (255,206,60))
    surf.blit(cs, cs.get_rect(center=(W//2, top+int(m*0.030))))
    st = ore_state()
    bot = H - int(m*0.095); y0 = top + int(m*0.070)
    gp = int(W*0.022); cw = int(min(W*0.27, (W*0.92-2*gp)/3)); x0 = (W-(3*cw+2*gp))//2
    ch = min(bot-y0, int(m*0.42))
    rects = {}
    play = pygame.Rect(x0, y0, cw, ch)
    ui_card(surf, "ore_play", play, (255,206,60), "star", tr("MINE"),
            tr("Name on screen, ore on the board"), t, dt, mouse,
            tag=("NOW" if st == "active" else None),
            extra=f"{tr('Best')}: {o['best']}  •  {tr('click to swing')}",
            locked=(st != "active"))
    rects["play"] = play
    shop = pygame.Rect(x0+cw+gp, y0, cw, ch)
    ui_card(surf, "ore_shop", shop, (150,215,255), "palette", tr("MINE SHOP"),
            tr("Pickaxes and skins"), t, dt, mouse,
            extra=f"{tr(ore_pick_info()[1])}", locked=(st != "active"))
    rects["shop"] = shop
    boss = pygame.Rect(x0+2*(cw+gp), y0, cw, ch)
    bday = ore_boss_day()
    ui_card(surf, "ore_boss", boss, BURGER_COL, "swords", tr("THE BATTLE"),
            "MAN STUDIO  vs  BURGERS", t, dt, mouse,
            tag=("TODAY" if bday else "5/12"),
            extra=(tr("Pick a side and mine") if bday else tr("The last day of the collab")),
            locked=not bday)
    rects["boss"] = boss
    bk = ui_back(surf, dt, mouse)
    return rects, bk

def draw_ore_shop(surf, dt, mouse, events, t):
    W, H = surf.get_size(); m = min(W, H)
    o = ore_data()
    for y in range(0, H, 6):
        q = y/float(H); pygame.draw.rect(surf, _mix((34,28,24), (12,10,9), q), (0, y, W, 6))
    top = draw_header(surf, tr("MINE SHOP"), tr("A better pickaxe swings faster"), (150,215,255), t)
    cs = ui_font(m*0.038).render(f"{o['coins']}  {tr('MINE COINS')}", True, (255,206,60))
    surf.blit(cs, cs.get_rect(center=(W//2, top+int(m*0.028))))
    rects = []
    y = top + int(m*0.070)
    rowh = int(m*0.082)
    for pid, name, secs, price in PICKAXES:   # secs is now the number of swings
        r = pygame.Rect(int(W*0.08), y, int(W*0.84), rowh-8)
        owned = pid in o["picks"]; eq = (o["pick"] == pid)
        col = PICK_COL[pid]
        pygame.draw.rect(surf, _mix((26,22,20), col, 0.10 if not eq else 0.22), r, border_radius=14)
        pygame.draw.rect(surf, col if owned else (70,62,56), r, 2, border_radius=14)
        draw_pickaxe(surf, r.x+int(m*0.045), r.centery, m*0.048, pid, t)
        ns = render_fit(ui_font(m*0.034), tr(name), (242,238,230) if owned else (150,142,132), int(r.w*0.42))
        surf.blit(ns, ns.get_rect(midleft=(r.x+int(m*0.090), r.centery-8)))
        ss = ui_font(m*0.024).render(f"~{secs} {tr('swings per ore')}", True, (170,160,146))
        surf.blit(ss, ss.get_rect(midleft=(r.x+int(m*0.090), r.centery+14)))
        if eq:     lab, lc = tr("EQUIPPED"), (120,220,140)
        elif owned:lab, lc = tr("EQUIP"), (150,215,255)
        else:      lab, lc = f"{price}", (255,206,60)
        bs = ui_font(m*0.030).render(lab, True, lc)
        surf.blit(bs, bs.get_rect(midright=(r.right-int(m*0.03), r.centery)))
        rects.append((r, "pick", pid, price, owned, eq))
        y += rowh
    y += int(m*0.012)
    for sk in ORE_SKIN_IDS:
        price = ORE_SKIN_PRICE[sk]
        owned = sk in (gd.get("unlocked_skins") or [])
        r = pygame.Rect(int(W*0.08), y, int(W*0.84), rowh-8)
        pygame.draw.rect(surf, (26,22,20), r, border_radius=14)
        pygame.draw.rect(surf, (200,160,255) if owned else (70,62,56), r, 2, border_radius=14)
        pal = SKINS.get(sk) or {}
        for i, cn in enumerate(COLOR_NAMES):
            if cn in pal:
                pygame.draw.rect(surf, pal[cn], (r.x+int(m*0.022)+i*int(m*0.028), r.centery-int(m*0.014),
                                                 int(m*0.024), int(m*0.028)), border_radius=5)
        ns = render_fit(ui_font(m*0.032), tr(sk), (242,238,230) if owned else (160,150,140), int(r.w*0.40))
        surf.blit(ns, ns.get_rect(midleft=(r.x+int(m*0.215), r.centery)))
        bs = ui_font(m*0.030).render(tr("OWNED") if owned else f"{price}", True,
                                     (120,220,140) if owned else (255,206,60))
        surf.blit(bs, bs.get_rect(midright=(r.right-int(m*0.03), r.centery)))
        rects.append((r, "skin", sk, price, owned, False))
        y += rowh
    return rects, ui_back(surf, dt, mouse)

def draw_ore_boss_pick(surf, dt, mouse, t):
    """Choose who you want to win before the battle."""
    W, H = surf.get_size(); m = min(W, H)
    for y in range(0, H, 6):
        q = y/float(H); pygame.draw.rect(surf, _mix((30,24,22), (10,9,8), q), (0, y, W, 6))
    top = draw_header(surf, tr("THE BATTLE"), tr("Who do you want to win?"), BURGER_COL, t)
    gp = int(W*0.04); cw = int(min(W*0.34, (W*0.86-gp)/2)); x0 = (W-(2*cw+gp))//2
    ch = int(m*0.42); y0 = top + int(m*0.060)
    out = {}
    for i, (key, nm, col, sub) in enumerate((("rushy", "MAN STUDIO", RUSHY_COL, tr("Color Under Pressure")),
                                             ("burgers", "BURGERS STUDIOS", BURGER_COL, tr("The challengers")))):
        r = pygame.Rect(x0+i*(cw+gp), y0, cw, ch)
        hov = r.collidepoint(mouse)
        pygame.draw.rect(surf, _mix((22,19,17), col, 0.12+0.12*hov), r, border_radius=20)
        pygame.draw.rect(surf, col, r, 3, border_radius=20)
        surf.blit(_glow(int(m*0.14), col, 40), (r.centerx-int(m*0.14), r.y+int(m*0.10)-int(m*0.14)))
        ui_icon2(surf, "swords" if key == "burgers" else "star", r.centerx, r.y+int(m*0.10), int(m*0.045), col, t)
        ns = render_fit(ui_font(m*0.040), nm, (245,242,236), r.w-24)
        surf.blit(ns, ns.get_rect(center=(r.centerx, r.y+int(m*0.21))))
        ss = render_fit(ui_font(m*0.026), sub, (180,170,158), r.w-24)
        surf.blit(ss, ss.get_rect(center=(r.centerx, r.y+int(m*0.26))))
        out[key] = r
    nt = render_fit(ui_font(m*0.026), tr("Your pick is remembered. Then you mine for them."), (170,160,148), int(W*0.7))
    surf.blit(nt, nt.get_rect(center=(W//2, y0+ch+int(m*0.045))))
    return out, ui_back(surf, dt, mouse)

def ore_screen(surf, dt, mouse, events):
    """Returns 'back' when the player leaves ORE MODE."""
    OS_["t"] += dt; t = OS_["t"]
    sc = OS_["screen"]
    if sc == "round":
        r = OS_["round"]
        if r is None: OS_["screen"] = "hub"; return None
        r.update(dt)
        draw_ore_round(surf, r, dt, mouse, events)
        if r.result is not None:
            bk = draw_ore_result(surf, r, dt, mouse)
            if ui_click(events, bk) or ui_esc(events):
                OS_["round"] = None; OS_["screen"] = "hub"; SND_SELECT.play()
        else:
            for ev in events:
                if ev.type == pygame.MOUSEBUTTONDOWN and ev.button == 1: r.click(ev.pos)
            if ui_esc(events): OS_["round"] = None; OS_["screen"] = "hub"
        return None
    if sc == "shop":
        rects, bk = draw_ore_shop(surf, dt, mouse, events, t)
        o = ore_data()
        for r, kind, key, price, owned, eq in rects:
            if not ui_click(events, r): continue
            if kind == "pick":
                if owned:
                    o["pick"] = key; save_gd(gd); SND_SELECT.play()
                elif o["coins"] >= price:
                    o["coins"] -= price; o["picks"].append(key); o["pick"] = key
                    ore_check_badges(); save_gd(gd); SND_CHIME.play()
                else: SND_WRONG.play()
            else:
                if owned: SND_SELECT.play()
                elif o["coins"] >= price:
                    o["coins"] -= price
                    gd.setdefault("unlocked_skins", ["Classic"]).append(key)
                    save_gd(gd); SND_CHIME.play()
                    try: check_skin_badges()
                    except Exception: pass
                else: SND_WRONG.play()
            break
        if ui_click(events, bk) or ui_esc(events): OS_["screen"] = "hub"; SND_SELECT.play()
        return None
    if sc == "boss_pick":
        sides, bk = draw_ore_boss_pick(surf, dt, mouse, t)
        for key, r in sides.items():
            if ui_click(events, r):
                o = ore_data(); o["boss_side"] = key; save_gd(gd); SND_SELECT.play()
                OS_["round"] = OreRound("boss"); OS_["screen"] = "round"
                return None
        if ui_click(events, bk) or ui_esc(events): OS_["screen"] = "hub"; SND_SELECT.play()
        return None
    rects, bk = draw_ore_hub(surf, dt, mouse, events, t)
    st = ore_state()
    if ui_click(events, rects["play"]):
        if st == "active": OS_["round"] = OreRound("mine"); OS_["screen"] = "round"; SND_SELECT.play()
        else: SND_WRONG.play()
    elif ui_click(events, rects["shop"]):
        if st == "active": OS_["screen"] = "shop"; SND_SELECT.play()
        else: SND_WRONG.play()
    elif ui_click(events, rects["boss"]):
        if ore_boss_day(): OS_["screen"] = "boss_pick"; SND_SELECT.play()
        else: SND_WRONG.play()
    elif ui_click(events, bk) or ui_esc(events):
        return "back"
    return None


# =============================================================================
#  DASH MODE  (a permanent mode - inspired by Geometry Dash)  ·  Manor, 6/11/2026
#  The cube runs by itself. JUMP over spikes and blocks.
#  COLOR GATES: a word appears at the top. Run THROUGH the gate the WORD names,
#  JUMP OVER the others. The ink lies - the word doesn't.
#  v2: an original song for every stage (synced to the beat), JUMP PADS, JUMP ORBS,
#  3 SECRET COINS per stage, PRACTICE MODE with checkpoints, and a lot more juice.
#  Hidden behind DASH_ENABLED (a DEV account sees it early), like FIRST FROST / ORE.
# =============================================================================
DASH_ENABLED = True           # ON (Manor, 6/11/2026)

