def _dash_sync(vis):
    """The Dash skin lives in SKINS only while DASH MODE is visible (signing out of DEV hides it again)."""
    if vis == _DASH_SHOWN["v"]: return
    _DASH_SHOWN["v"] = vis
    if vis: SKINS["Dash"] = _DASH_SKIN_PAL
    else:   SKINS.pop("Dash", None)

def dash_visible():
    """DASH MODE is hidden until 15/11 - a DEV account sees it today.
    This is the ONLY question the rest of the game should ask about it."""
    v = True if DASH_ENABLED else dev_mode()
    _dash_sync(v)
    return v
_dash_sync(DASH_ENABLED)

def dash_data():
    """Self-healing save, like ore_data: an old or broken save must never take the game down."""
    d = gd.get("dash")
    if not isinstance(d, dict): d = {}; gd["dash"] = d
    for k, v, typ in (("attempts",0,int),("endless_best",0,int),("endless_dist",0,int),
                      ("cube","classic",str),("cube_col","BLUE",str),("practice",False,bool)):
        try: d[k] = typ(d[k]) if k in d and d[k] is not None else v
        except Exception: d[k] = v
    for k in ("best","cleared"):
        lst = d.get(k)
        if not isinstance(lst, list): lst = []
        d[k] = (list(lst) + [0]*4)[:4]
    d["best"]    = [max(0, min(100, int(x or 0))) for x in d["best"]]
    d["cleared"] = [bool(x) for x in d["cleared"]]
    sc = d.get("scoins")
    if not isinstance(sc, list): sc = []
    sc = (list(sc) + [[]]*4)[:4]
    d["scoins"] = [sorted({int(i) for i in (s if isinstance(s, list) else []) if str(i).isdigit() and 0 <= int(i) < 3}) for s in sc]
    if d["cube_col"] not in COLOR_NAMES: d["cube_col"] = "BLUE"
    if not dash_cube_unlocked(d["cube"], d): d["cube"] = "classic"
    return d

def dash_cube_unlocked(cid, d=None):
    d = d if d is not None else gd.get("dash", {})
    cl = d.get("cleared") or [False]*4
    if cid == "classic": return True
    if cid in ("smile","eye","star","crown"): return bool(cl[["smile","eye","star","crown"].index(cid)])
    if cid == "bolt":    return int(d.get("endless_best",0) or 0) >= 25
    if cid == "skull":   return int(d.get("attempts",0) or 0) >= 100
    if cid == "rainbow": return all(has_badge(b) for b in DASH_BADGE_IDS)
    return False

def dash_scoin_total(d=None):
    d = d or dash_data(); return sum(len(s) for s in d["scoins"])

def dash_check_rewards():
    d = dash_data()
    if d["cleared"][0]: award_badge("first_dash")
    if all(d["cleared"]):
        award_badge("dash_cleared")
        sk = gd.setdefault("unlocked_skins", ["Classic"])
        if "Dash" not in sk: sk.append("Dash")
    if d["endless_best"] >= 50: award_badge("endless_runner")
    if d["attempts"] >= 100:    award_badge("one_more_try")
    if dash_scoin_total(d) >= 12: award_badge("coin_hunter")
    save_gd(gd)

def dash_pal():
    return SKINS.get(gd.get("current_skin","Classic"), SKINS["Classic"])

# ── drawing a cube ────────────────────────────────────────────────────────────
_DCUBE = {}
def draw_dash_cube(surf, cx, cy, s, design, col, rot=0.0, alpha=255):
    """s = side in pixels. Cached, then spun like in GD."""
    s = max(8, int(s)); key = (s, design, col)
    if key not in _DCUBE:
        if len(_DCUBE) > 200: _DCUBE.clear()
        pad = int(s*0.25); S = s + 2*pad
        c = pygame.Surface((S, S), pygame.SRCALPHA)
        r = pygame.Rect(pad, pad, s, s)
        dark = _mix(col, (0,0,0), 0.55); light = _mix(col, WHITE, 0.45)
        pygame.draw.rect(c, (12,10,24), r.inflate(6,6), border_radius=max(3,s//8))
        pygame.draw.rect(c, col, r, border_radius=max(2,s//10))
        pygame.draw.rect(c, light, (r.x+s*0.08, r.y+s*0.08, s*0.84, s*0.18), border_radius=max(2,s//14))
        lw = max(2, s//14); cx0, cy0 = r.centerx, r.centery
        if design == "classic":
            pygame.draw.rect(c, dark, r.inflate(-s*0.36, -s*0.36), lw, border_radius=max(2,s//14))
            pygame.draw.rect(c, light, r.inflate(-s*0.66, -s*0.66), border_radius=max(1,s//20))
        elif design == "smile":
            for ex in (-0.2, 0.2): pygame.draw.rect(c, dark, (cx0+ex*s-s*0.07, cy0-s*0.2, s*0.14, s*0.18), border_radius=2)
            pygame.draw.arc(c, dark, (cx0-s*0.28, cy0-s*0.2, s*0.56, s*0.42), math.pi*1.1, math.pi*1.9, lw)
        elif design == "eye":
            pygame.draw.ellipse(c, WHITE, (cx0-s*0.34, cy0-s*0.2, s*0.68, s*0.4))
            pygame.draw.circle(c, dark, (cx0, cy0), int(s*0.15)); pygame.draw.circle(c, (10,8,20), (cx0, cy0), int(s*0.07))
        elif design == "star":
            pts = [(cx0+math.cos(-math.pi/2+i*math.pi/5)*(s*0.34 if i%2==0 else s*0.15),
                    cy0+math.sin(-math.pi/2+i*math.pi/5)*(s*0.34 if i%2==0 else s*0.15)) for i in range(10)]
            pygame.draw.polygon(c, light, pts); pygame.draw.polygon(c, dark, pts, lw)
        elif design == "crown":
            pts = [(cx0-s*0.32, cy0+s*0.2), (cx0-s*0.32, cy0-s*0.18), (cx0-s*0.16, cy0), (cx0, cy0-s*0.26),
                   (cx0+s*0.16, cy0), (cx0+s*0.32, cy0-s*0.18), (cx0+s*0.32, cy0+s*0.2)]
            pygame.draw.polygon(c, (255,215,60), pts); pygame.draw.polygon(c, dark, pts, lw)
        elif design == "bolt":
            pts = [(cx0+s*0.06,cy0-s*0.36),(cx0-s*0.24,cy0+s*0.04),(cx0-s*0.02,cy0+s*0.04),(cx0-s*0.08,cy0+s*0.36),
                   (cx0+s*0.24,cy0-s*0.06),(cx0+s*0.02,cy0-s*0.06)]
            pygame.draw.polygon(c, (255,235,80), pts); pygame.draw.polygon(c, dark, pts, lw)
        elif design == "skull":
            pygame.draw.circle(c, (235,235,240), (cx0, int(cy0-s*0.04)), int(s*0.28))
            pygame.draw.rect(c, (235,235,240), (cx0-s*0.16, cy0+s*0.1, s*0.32, s*0.18), border_radius=2)
            for ex in (-0.12, 0.12): pygame.draw.circle(c, (15,12,25), (int(cx0+ex*s), int(cy0-s*0.04)), int(s*0.08))
        elif design == "rainbow":
            for i, k in enumerate(COLOR_NAMES):
                pygame.draw.rect(c, NEON[k], (r.x+s*0.12, r.y+s*0.14+i*s*0.12, s*0.76, s*0.12))
        pygame.draw.rect(c, (12,10,24), r, max(2, s//16), border_radius=max(2,s//10))
        _DCUBE[key] = c
    c = _DCUBE[key]
    if rot: c = pygame.transform.rotate(c, rot)
    if alpha < 255: c = c.copy(); c.set_alpha(alpha)
    surf.blit(c, c.get_rect(center=(int(cx), int(cy))))

# ── the level ─────────────────────────────────────────────────────────────────
def _dash_jumpdist(speed): return speed * 2 * DASH_JUMP / DASH_G

class DashLevel:
    """A track: spikes, blocks, pads, orbs, color gates and secret coins. Stages are fixed
    (same seed every time, so you can learn them like in GD). ENDLESS keeps building ahead."""
    def __init__(self, stage):
        self.stage = stage                         # 0..3, or -1 = ENDLESS
        self.rng = random.Random(9100 + stage*17 if stage >= 0 else random.randrange(1<<30))
        self.spikes = []; self.blocks = []; self.gates = []; self.groups = []
        self.pads = []; self.orbs = []; self.scoins = []
        self.sx = []; self.bx = []; self.gx = []; self.px = []; self.ox = []
        self.cblocks = []; self.cbx = []           # SHIP: blocks hanging from the roof
        self.saws = []; self.swx = []              # spinning saw blades
        self.zones = []; self.zx = []              # SHIP parts: (start, end)
        self.cursor = 14.0
        self.n = 0; self._ga = 0
        self.end = None
        self._coin_spots = []
        if stage >= 0:
            st = DASH_STAGES[stage]
            for _ in range(st[2]): self._chunk()
            self.end = self.cursor + 6.0
            sp = self._coin_spots
            if len(sp) >= 3:                       # 3 secret coins, spread over the stage
                for i, f in enumerate((0.22, 0.55, 0.85)):
                    x, y = sp[min(len(sp)-1, int(len(sp)*f))]
                    self.scoins.append({"x": x, "y": y, "i": i})
    def _spike(self, x, y=0.0): self.spikes.append((x, y)); self.sx.append(x)
    def _block(self, x, w, h):  self.blocks.append((x, w, h)); self.bx.append(x)
    def _pad(self, x):          self.pads.append(x); self.px.append(x)
    def _orb(self, x, y):       self.orbs.append({"x": x, "y": y, "id": len(self.orbs)}); self.ox.append(x)
    def _cblock(self, x, w, h): self.cblocks.append((x, w, h)); self.cbx.append(x)
    def _saw(self, x, y, r):    self.saws.append((x, y, r)); self.swx.append(x)
    def in_ship(self, x):
        import bisect
        i = bisect.bisect_right(self.zx, x) - 1
        return i >= 0 and self.zones[i][0] <= x < self.zones[i][1]
    def near(self, kind, x0, x1):
        """Only the objects between x0 and x1 - an ENDLESS run can have thousands."""
        import bisect
        if kind == "s":   lst, xs, back = self.spikes, self.sx, 1.0
        elif kind == "b": lst, xs, back = self.blocks, self.bx, 5.0
        elif kind == "p": lst, xs, back = self.pads, self.px, 1.0
        elif kind == "o": lst, xs, back = self.orbs, self.ox, 1.0
        elif kind == "c": lst, xs, back = self.cblocks, self.cbx, 3.0
        elif kind == "w": lst, xs, back = self.saws, self.swx, 2.0
        else:             lst, xs, back = self.gates, self.gx, 1.0
        return lst[bisect.bisect_left(xs, x0 - back): bisect.bisect_right(xs, x1)]
    def speed_at(self, x):
        if self.stage >= 0: return DASH_STAGES[self.stage][1]
        return min(13.5, 8.0 + x / 140.0)
    def _params(self):
        if self.stage >= 0:
            st = DASH_STAGES[self.stage]; return st[3], st[4], st[5], self.stage
        lvl = min(3, int(self.cursor // 220))      # ENDLESS gets harder as you go
        return (4, 3, 3, 3)[lvl], (2, 2, 3, 3)[lvl], (0.0, 0.3, 0.6, 0.9)[lvl], lvl
    def ensure(self, x):
        while self.stage < 0 and self.cursor < x + 40: self._chunk()
    def _chunk(self):
        rng = self.rng; every, ngates, trick, lvl = self._params()
        sp = self.speed_at(self.cursor); jd = _dash_jumpdist(sp)
        x = self.cursor; self.n += 1
        if (self.stage >= 0 and self.n in DASH_SHIP_AT.get(self.stage, ())) or \
           (self.stage < 0 and lvl >= 1 and self.n % 13 == 0):
            self._ship_part(x, lvl); return
        if self.n % every == 0:
            pal = list(COLOR_NAMES); rng.shuffle(pal); cols = pal[:ngates]
            ok = rng.randrange(ngates); word = cols[ok]
            others = [c for c in cols if c != word]
            ink = rng.choice(others) if (others and rng.random() < trick) else rng.choice([c for c in COLOR_NAMES if c not in cols])
            gsp = jd + 3.2
            for i, c in enumerate(cols):
                self.gates.append({"x": x + i*gsp, "col": c, "ok": i == ok, "grp": len(self.groups), "done": None}); self.gx.append(x + i*gsp)
            self.groups.append({"word": word, "ink": ink, "x0": x, "x1": x + (ngates-1)*gsp})
            self.cursor = x + (ngates-1)*gsp + jd + 3.0
            return
        kinds = ["spike", "spike", "spike2", "block"]
        if lvl >= 1: kinds += ["spike2", "stairs", "block", "pad_tower"]
        if lvl >= 2: kinds += ["spike3", "stairs", "orb_gap", "pad_tower"]
        if lvl >= 1: kinds += ["saw"]
        if lvl >= 2: kinds += ["saw2"]
        if lvl >= 3: kinds += ["orb_gap", "saw2"]
        k = rng.choice(kinds); w = 1
        if k == "spike":  self._spike(x)
        elif k == "spike2":
            self._spike(x); self._spike(x+1); w = 2; self._coin_spots.append((x + 1.0, 2.55))
        elif k == "spike3":
            self._spike(x); self._spike(x+1); self._spike(x+2); w = 3; self._coin_spots.append((x + 1.5, 2.45))
        elif k == "block":
            w = rng.choice((2, 3, 4)); self._block(x, w, 1.0)
            if lvl >= 1 and rng.random() < 0.5: self._spike(x + w + 2.0); w += 3
        elif k == "stairs":
            self._block(x, 2, 1.0); self._block(x+2, 2, 2.0); w = 4
        elif k == "pad_tower":                     # a yellow pad throws you over a tall wall
            pd = sp * 2 * DASH_PAD / DASH_G
            self._pad(x); bxp = x + pd * 0.42; self._block(bxp, 2, 3.0)
            w = (bxp + 2 - x)
        elif k == "saw":                           # a spinning saw blade on the floor
            self._saw(x + 0.5, 0.3, 0.8); w = 1
        elif k == "saw2":
            self._saw(x + 0.5, 0.3, 0.8); self._saw(x + 2.1, 0.3, 0.8); w = 3; self._coin_spots.append((x + 1.3, 2.6))
        elif k == "orb_gap":                       # too many spikes for one jump: hit the orb in the air
            L = int(round(jd * 1.4)); ox = x - 0.6 + jd * 0.8
            for i in range(L): self._spike(x + i)
            self._orb(ox, 1.75); w = L
        self.cursor = x + w + jd*0.65 + rng.uniform(2.5, 4.0)
    def _ship_part(self, x, lvl):
        """SHIP: a portal, then fly between pillars and through COLOR WINDOWS, then a portal back."""
        rng = self.rng; gap = 3.7 - 0.25 * lvl; npil = 5 + lvl
        nl = 0 if (self.stage == 0) else (1 if lvl < 3 else 2)
        lanes = set(rng.sample(range(1, npil), min(nl, npil - 1))) if nl else set()
        cx = x + 6.0; c = DASH_CEIL / 2; coin_done = False
        for i in range(npil):
            if i in lanes:                             # a wall with 3 colored windows: fly through the one the WORD says
                cx += 3.5                                  # room to steer to the right window
                pal = list(COLOR_NAMES); rng.shuffle(pal); cols = pal[:3]; ok = rng.randrange(3)
                word = cols[ok]; others = [cc for cc in cols if cc != word]
                trick = self._params()[2]
                ink = rng.choice(others) if rng.random() < max(0.3, trick) else rng.choice([cc for cc in COLOR_NAMES if cc not in cols])
                wins = [(0.2, 2.3), (2.55, 4.65), (4.9, 7.0)]
                g = {"x": cx, "lanes": [(wins[j][0], wins[j][1], cols[j], j == ok) for j in range(3)], "ok": True,
                     "col": word, "grp": len(self.groups), "done": None}
                self.gates.append(g); self.gx.append(cx)
                self.groups.append({"word": word, "ink": ink, "x0": cx, "x1": cx})
                cx += 9.0; continue
            c = max(gap / 2 + 0.35, min(DASH_CEIL - gap / 2 - 0.35, c + rng.uniform(-1.9, 1.9)))
            fh = c - gap / 2; ch = DASH_CEIL - (c + gap / 2)
            if fh > 0.25: self._block(cx, 1.2, round(fh, 2))
            if ch > 0.25: self._cblock(cx, 1.2, round(ch, 2))
            if not coin_done and i >= 2:
                self._coin_spots.append((cx + 0.6, c)); coin_done = True
            cx += rng.uniform(6.5, 8.0)
        x1 = cx + 1.0
        self.zones.append((x, x1)); self.zx.append(x)
        self.cursor = x1 + 11.0
    def floor_at(self, x0, x1):
        """The highest block top under the cube (cube spans x0..x1)."""
        f = 0.0
        for bx, bw, bh in self.near("b", x0, x1):
            if bx < x1 and bx + bw > x0: f = max(f, bh)
        return f
    def group_ahead(self, x):
        while self._ga < len(self.groups) and self.groups[self._ga]["x1"] + 0.6 < x: self._ga += 1
        if self._ga < len(self.groups): return self.groups[self._ga]
        return None
    def in_group(self, x):
        for g in self.groups[max(0, self._ga-1): self._ga+2]:
            if g["x0"] - 3 <= x <= g["x1"] + 2: return True
        return False

class DashRun:
    def __init__(self, stage, practice=False):
        self.stage = stage; self.lv = DashLevel(stage); self.practice = practice
        self.x = 0.0; self.y = 0.0; self.vy = 0.0; self.ground = True
        self.rot = 0.0; self.dead = 0.0; self.why = ""; self.done = False; self.done_t = 0.0
        self.gates = 0; self.t = 0.0; self.buf = 0.0
        self.parts = []; self.trail = []; self.flash = 0.0; self.ok_fx = []; self.shake = 0.0
        self.orbs_used = set(); self.coins_got = set(); self.coin_fx = []
        self.pad_fx = []; self.cps = []; self.last_cp = 0.0; self.new_best = 0; self.ship = False
        self.result = None
    def hold(self, down):
        if down: self.buf = 0.12
    def die(self, why):
        if self.dead: return
        self.dead = 0.001; self.why = why; self.shake = 0.35; SND_WRONG.play()
        for i in range(34):
            a = random.uniform(0, math.tau); v = random.uniform(3, 11)
            self.parts.append([self.x + 0.5, self.y + 0.5, math.cos(a)*v, math.sin(a)*v + 3, random.uniform(0.5, 1.1), None])
    def respawn(self):
        """PRACTICE: back to the last checkpoint."""
        cp = self.cps[-1] if self.cps else {"x": 0.0, "y": 0.0, "gates": 0, "coins": set()}
        self.x, self.y, self.vy, self.ground, self.rot = cp["x"], cp["y"], 0.0, True, 0.0; self.ship = False
        self.dead = 0.0; self.why = ""; self.gates = cp["gates"]; self.coins_got = set(cp["coins"])
        for g in self.lv.gates:
            if g["x"] > cp["x"]: g["done"] = None
        self.orbs_used = {o for o in self.orbs_used if self.lv.orbs[o]["x"] < cp["x"]}
        self.trail = []
    def _burst(self, x, y, col, n=14, spd=6):
        for i in range(n):
            a = random.uniform(0, math.tau); v = random.uniform(spd*0.4, spd)
            self.parts.append([x, y, math.cos(a)*v, math.sin(a)*v, random.uniform(0.3, 0.7), col])
    def update(self, dt, holding):
        self.t += dt
        for p in self.parts: p[0] += p[2]*dt; p[1] += p[3]*dt; p[3] -= 18*dt; p[4] -= dt
        self.parts = [p for p in self.parts if p[4] > 0]
        self.flash = max(0.0, self.flash - dt*3); self.shake = max(0.0, self.shake - dt)
        for lst in (self.ok_fx, self.coin_fx, self.pad_fx):
            for f in lst: f[-1] -= dt
        self.ok_fx = [f for f in self.ok_fx if f[-1] > 0]; self.coin_fx = [f for f in self.coin_fx if f[-1] > 0]
        self.pad_fx = [f for f in self.pad_fx if f[-1] > 0]
        if self.dead:
            self.dead += dt; return
        if self.done:
            self.done_t += dt; self.x += self.lv.speed_at(self.x) * dt; self.y += 9 * dt; self.rot -= 600 * dt
            if random.random() < dt * 14:
                self._burst(self.x + random.uniform(-6, 2), random.uniform(3, 7), random.choice(list(NEON.values())), 18, 7)
            return
        if holding: self.buf = 0.12
        steps = 4; h = min(dt, 1/30) / steps
        for _ in range(steps):
            sp = self.lv.speed_at(self.x); px = self.x
            self.x += sp * h; self.lv.ensure(self.x)
            self.buf = max(0.0, self.buf - h)
            ship = self.lv.in_ship(self.x + 0.5)
            if ship != self.ship:                                    # through a portal
                self.ship = ship; self.flash = 0.6; SND_WHOOSH.play() if "SND_WHOOSH" in globals() else None
                self._burst(self.x + 0.5, self.y + 0.5, (255,120,220) if ship else (80,200,255), 24, 8)
                if ship: self.ground = False
                else: self.rot = 0.0
            if ship:
                up = holding or self.buf > 0.06
                self.vy += (DASH_SHIP_UP if up else -DASH_SHIP_DOWN) * h
                self.vy = max(-DASH_SHIP_VMAX, min(DASH_SHIP_VMAX, self.vy))
                self.y += self.vy * h
                if self.y < 0: self.y = 0.0; self.vy = max(0.0, self.vy)
                if self.y > DASH_CEIL - 1: self.y = DASH_CEIL - 1; self.vy = min(0.0, self.vy)
                self.rot = self.vy * 3.0; self.ground = False
                if up and random.random() < 0.5:                     # the engine flame
                    self.parts.append([self.x, self.y + 0.35, -random.uniform(4, 8), random.uniform(-1, 1), 0.25, (255,170,60)])
                for bx, bw, bh in self.lv.near("b", self.x, self.x + 1):
                    if bx < self.x + 0.85 and bx + bw > self.x + 0.15 and self.y + 0.15 < bh:
                        self.die("CRASH!"); return
                for bx, bw, bh in self.lv.near("c", self.x, self.x + 1):
                    if bx < self.x + 0.85 and bx + bw > self.x + 0.15 and self.y + 0.85 > DASH_CEIL - bh:
                        self.die("CRASH!"); return
            else:
                if self.ground and self.buf > 0:
                    self.vy = DASH_JUMP; self.ground = False; self.buf = 0.0
                # yellow pads: touch them and you fly
                for pdx in self.lv.near("p", self.x, self.x + 1):
                    if pdx < self.x + 0.9 and pdx + 1 > self.x + 0.1 and self.y < 0.25 and self.vy <= 0.5:
                        self.vy = DASH_PAD; self.ground = False; self.pad_fx.append([pdx, 0.5])
                # yellow orbs: tap (or hold) while touching = jump in mid-air
                if not self.ground and self.buf > 0:
                    for o in self.lv.near("o", self.x - 0.5, self.x + 1.5):
                        if o["id"] in self.orbs_used: continue
                        if abs((self.x + 0.5) - o["x"]) < 0.95 and abs((self.y + 0.5) - o["y"]) < 0.95:
                            self.vy = DASH_ORB; self.buf = 0.0; self.orbs_used.add(o["id"])
                            self._burst(o["x"], o["y"], (255,230,60), 16, 6); SND_TICK.play(); break
                fl = self.lv.floor_at(self.x + 0.08, self.x + 0.92)
                if not self.ground:
                    self.vy -= DASH_G * h; py = self.y; self.y += self.vy * h
                    if self.vy <= 0 and self.y <= fl and py >= fl - 0.35:
                        self.y = fl; self.vy = 0.0; self.ground = True
                        self.rot = round(self.rot / 90.0) * 90.0
                        for i in range(5):                                   # a puff of dust when you land
                            self.parts.append([self.x + random.uniform(0.1, 0.9), self.y, random.uniform(-3, -0.5), random.uniform(0.5, 2.5), 0.3, (230,230,255)])
                    else:
                        self.rot -= 400 * h
                else:
                    if fl < self.y - 0.01:                           # walked off a block
                        self.ground = False; self.vy = 0.0
                if self.y < 0: self.y = 0.0; self.vy = 0.0; self.ground = True
                # blocks from the side
                for bx, bw, bh in self.lv.near("b", self.x, self.x + 1):
                    if bx < self.x + 0.9 and bx + bw > self.x + 0.1 and self.y < bh - 0.3:
                        self.die("CRASH!"); return
                # spikes (a smaller box than the triangle, like in GD)
                for sx, sy in self.lv.near("s", self.x, self.x + 1):
                    if sx + 0.2 < self.x + 0.88 and sx + 0.8 > self.x + 0.12 and self.y < sy + 0.55 and self.y + 1 > sy:
                        self.die("SPIKED!"); return
            # saw blades (both modes)
            for wx, wy, wr in self.lv.near("w", self.x - 1, self.x + 2):
                nx = max(self.x + 0.1, min(wx, self.x + 0.9)); ny = max(self.y + 0.1, min(wy, self.y + 0.9))
                if (nx - wx) ** 2 + (ny - wy) ** 2 < (wr * 0.8) ** 2:
                    self.die("SAWED!"); return
            # secret coins
            for c in self.lv.scoins:
                if c["i"] in self.coins_got: continue
                if abs((self.x + 0.5) - c["x"]) < 0.8 and abs((self.y + 0.5) - c["y"]) < 0.8:
                    self.coins_got.add(c["i"]); self.coin_fx.append([c["x"], c["y"], 1.0]); SND_CHIME.play()
                    self._burst(c["x"], c["y"], (255,215,60), 20, 7)
            # color gates (on the floor) and color windows (SHIP)
            for g in self.lv.near("g", px - 1, self.x + 1):
                if g["done"] is None and px + 0.5 < g["x"] + 0.25 <= self.x + 0.5:
                    if "lanes" in g:
                        cy = self.y + 0.5; hit = None
                        for y0, y1, col, ok in g["lanes"]:
                            if y0 <= cy <= y1: hit = (col, ok)
                        if hit and hit[1]:
                            g["done"] = True; self.gates += 1; self.flash = 1.0; SND_CORRECT.play()
                            self._burst(g["x"] + 0.25, cy, dash_pal().get(hit[0], NEON[hit[0]]), 26, 9)
                        else:
                            g["done"] = False; self.die("WRONG COLOR!" if hit else "CRASH!"); return
                        continue
                    through = self.y < DASH_GATE_H - 0.05
                    if g["ok"] and through:
                        g["done"] = True; self.gates += 1; self.flash = 1.0; SND_CORRECT.play()
                        self.ok_fx.append([g["x"], 0.8])
                        self._burst(g["x"] + 0.25, 0.8, dash_pal().get(g["col"], NEON[g["col"]]), 22, 8)
                    elif g["ok"]:
                        g["done"] = False; self.die("MISSED THE GATE!"); return
                    elif through:
                        g["done"] = False; self.die("WRONG COLOR!"); return
                    else:
                        g["done"] = True
            # PRACTICE: a checkpoint every so often, only on safe ground
            if self.practice and self.ground and not self.ship and self.x - self.last_cp > 16 and not self.lv.in_group(self.x) \
               and not self.lv.near("s", self.x - 1.5, self.x + 3) and not self.lv.near("p", self.x - 1, self.x + 3) \
               and not self.lv.near("w", self.x - 1.5, self.x + 3) and self.lv.floor_at(self.x - 1, self.x + 3) == self.y:
                self.cps.append({"x": self.x, "y": self.y, "gates": self.gates, "coins": set(self.coins_got)}); self.last_cp = self.x
            if self.lv.end is not None and self.x >= self.lv.end:
                self.done = True; SND_CHIME.play(); return
        if self.t % 0.03 < dt:
            self.trail.append([self.x, self.y, 0.35])
        for tr_ in self.trail: tr_[2] -= dt
        self.trail = [p for p in self.trail if p[2] > 0]
    def progress(self):
        if self.lv.end is None: return 0
        return max(0, min(100, int(self.x / self.lv.end * 100)))

# ── screens ───────────────────────────────────────────────────────────────────
DS = {"screen": "hub", "back": "modes", "run": None, "t": 0.0, "attempt": 1, "res": None, "mt": 0.0, "bpm": 128}

def _dash_song(stage):
    return DASH_STAGES[stage][7] if stage >= 0 else DASH_ENDLESS_SONG

def _dash_song_ready(k):
    return k in globals().get("MUSIC2", {})

def _dash_music(stage, restart=True):
    """Every attempt starts the song from the top, like in GD. If the DASH song is not
    made yet (the first launch makes it in the background, or numpy is missing),
    another song plays until it is ready - never silence."""
    k = _dash_song(stage); DS["want"] = None
    if not _dash_song_ready(k):
        DS["want"] = k
        m2 = globals().get("MUSIC2", {}); old = globals().get("_np") is None
        for fb in ("vibe", "fall", "boss", "haunt", "menu"):
            if fb in m2 or (old and ("MUSIC_" + fb.upper()) in globals()):
                k = fb; break
    if restart: globals()["_cur_music"] = None
    play_music(k); DS["mt"] = 0.0; DS["bpm"] = SONGS3.get(k, {}).get("bpm", 128) if "SONGS3" in globals() else 128

def dash_open(back="modes"):
    DS.update({"screen": "hub", "back": back, "run": None, "t": 0.0, "res": None})
    dash_data(); play_music("menu")

def _dash_start(stage):
    d = dash_data(); prac = bool(d.get("practice")) and stage >= 0
    DS["run"] = DashRun(stage, prac); DS["screen"] = "run"; DS["attempt"] = 1; DS["res"] = None
    _dash_music(stage)

def _dash_cols(stage):
    return DASH_STAGES[stage][6] if stage >= 0 else DASH_ENDLESS_COLS

def _dash_beat():
    """0..1, a hit on every beat of the song that is playing."""
    b = DS["mt"] * DS["bpm"] / 60.0
    return (1 - (b % 1.0)) ** 3, int(b)

_DGLOW = {}
def _dash_glow(r, col, a):
    k = (int(r), col, int(a) // 8)
    if k not in _DGLOW:
        if len(_DGLOW) > 300: _DGLOW.clear()
        _DGLOW[k] = _glow(int(r), col, int(a))
    return _DGLOW[k]

# ── the look: background layers, ground, blocks and spikes (all cached) ─────
def _dblur(sf, k=4):
    w, h = sf.get_size()
    sm = pygame.transform.smoothscale(sf, (max(1, w // k), max(1, h // k)))
    return pygame.transform.smoothscale(sm, (w, h))

_DBG = {}
def _dash_layer(stage, W, H, which):
    """A wide strip of silhouettes (city / hills / mountains / castle / planets), made once.
    which 0 = far (taller, lighter), 1 = near (lower, darker). It tiles left-right."""
    key = ("L", stage, W, H, which)
    if key in _DBG: return _DBG[key]
    if len(_DBG) > 40: _DBG.clear()
    top, bot, acc = _dash_cols(stage)
    LW = W * 2; LH = int(H * 0.62)
    sf = pygame.Surface((LW, LH), pygame.SRCALPHA)
    rr = random.Random(77 + stage * 13 + which * 5)
    base = _mix(top, (0,0,0), 0.62 if which == 0 else 0.82)
    edge = _mix(acc, top, 0.6 if which == 0 else 0.8)
    theme = stage if stage >= 0 else 4
    polys = []; wins = []
    if theme == 0:                                   # a neon city at night
        x = 0
        while x < LW:
            w = rr.randint(40, 100) * (1.0 if which == 0 else 1.5); h = rr.randint(int(LH * 0.25), int(LH * (0.85 if which == 0 else 0.5)))
            polys.append([(x, LH), (x, LH - h), (x + w, LH - h), (x + w, LH)])
            if which == 0:
                for wy in range(int(LH - h + 12), LH - 10, 16):
                    for wx in range(int(x + 8), int(x + w - 8), 14):
                        if rr.random() < 0.35: wins.append((wx, wy))
            x += w + rr.randint(6, 26)
    elif theme == 1:                                 # rolling hills, like waves
        n = 32; amp = 0.18 if which == 0 else 0.12; base_h = 0.45 if which == 0 else 0.28
        pts = [(0, LH)]
        for i in range(n + 1):
            a = i / n * math.tau
            pts.append((i * LW / n, LH - LH * (base_h + amp * math.sin(a * 3 + which) + amp * 0.5 * math.sin(a * 7 + 1.3))))
        pts.append((LW, LH)); polys.append(pts)
    elif theme == 2:                                 # crystal mountains
        x = -40
        while x < LW + 40:
            w = rr.randint(140, 260); h = rr.randint(int(LH * 0.35), int(LH * (0.95 if which == 0 else 0.6)))
            polys.append([(x, LH), (x + w * 0.5, LH - h), (x + w, LH)]); x += w * 0.55
    elif theme == 3:                                 # a dark castle under the ink
        x = 0
        while x < LW:
            w = rr.randint(50, 110); h = rr.randint(int(LH * 0.3), int(LH * (0.8 if which == 0 else 0.45)))
            polys.append([(x, LH), (x, LH - h), (x + w * 0.5, LH - h - w * 0.7), (x + w, LH - h), (x + w, LH)])
            x += w + rr.randint(10, 40)
    else:                                            # ENDLESS: jagged far mountains
        x = -40
        while x < LW + 40:
            w = rr.randint(80, 200); h = rr.randint(int(LH * 0.2), int(LH * (0.7 if which == 0 else 0.4)))
            polys.append([(x, LH), (x + w * 0.35, LH - h * 0.7), (x + w * 0.5, LH - h), (x + w * 0.7, LH - h * 0.6), (x + w, LH)]); x += w * 0.7
    glow = pygame.Surface((LW, LH), pygame.SRCALPHA)
    for off in (-LW, 0, LW):                         # drawn 3 times so the strip tiles with no seam
        for pl in polys:
            q = [(a + off, b) for a, b in pl]
            pygame.draw.polygon(sf, base + (255,), q)
            ep = q[1:-1] if len(q) > 3 else q
            pygame.draw.lines(glow, edge + (255,), False, ep, 6)
            pygame.draw.lines(sf, edge + (255,), False, ep, 1)
    g2 = _dblur(glow, 5); g2.set_alpha(60 if which == 0 else 30)
    out = pygame.Surface((LW, LH), pygame.SRCALPHA); out.blit(g2, (0, 0)); out.blit(sf, (0, 0))
    for wx, wy in wins:
        pygame.draw.rect(out, _mix(acc, (255,240,200), 0.5) + (150,), (wx, wy, 5, 7))
    _DBG[key] = out
    return out

def _dash_sky(stage, W, H, top, bot, acc):
    key = ("S", stage, W, H, top)
    if key not in _DBG:
        if len(_DBG) > 40: _DBG.clear()
        sf = pygame.Surface((W, H))
        for yy in range(0, H, 4): pygame.draw.rect(sf, _mix(top, bot, (yy / H) ** 0.8), (0, yy, W, 4))
        # a big soft moon / sun
        g = pygame.Surface((W, H), pygame.SRCALPHA)
        mx, my, mr = int(W * 0.72), int(H * 0.26), int(H * 0.11)
        pygame.draw.circle(g, _mix(acc, WHITE, 0.3) + (90,), (mx, my), int(mr * 2.6))
        pygame.draw.circle(g, _mix(acc, WHITE, 0.5) + (140,), (mx, my), int(mr * 1.5))
        g = _dblur(g, 8); sf.blit(g, (0, 0))
        pygame.draw.circle(sf, _mix(acc, WHITE, 0.65), (mx, my), mr)
        for k in range(5):                                       # stripes across it, retro style
            yy = my + mr * (0.15 + k * 0.17); hh = 3 + k
            pygame.draw.rect(sf, _mix(top, bot, 0.3), (mx - mr, int(yy), mr * 2, hh))
        rr = random.Random(stage + 3)
        for _ in range(70):
            x, y = rr.randrange(W), rr.randrange(int(H * 0.55)); c = rr.randint(150, 255)
            sf.set_at((x, y), (c, c, c))
        _DBG[key] = sf
    return _DBG[key]

def _dash_ground(W, H, gy, bot, acc):
    key = ("G", W, H, gy, bot, acc)
    if key not in _DBG:
        sf = pygame.Surface((W, H - gy))
        for yy in range(H - gy): pygame.draw.line(sf, _mix(_mix(acc, bot, 0.72), (0,0,0), yy / max(1, H - gy) * 0.9), (0, yy), (W, yy))
        _DBG[key] = sf
    return _DBG[key]

def _dash_block_surf(w, h, TS, acc, bot):
    """A glossy block (w x h tiles) with a neon edge."""
    key = ("B", w, h, int(TS), acc, bot)
    if key not in _DBG:
        pw, ph = int(w * TS), int(h * TS); pad = 10
        sf = pygame.Surface((pw + pad * 2, ph + pad * 2), pygame.SRCALPHA)
        gl = pygame.Surface(sf.get_size(), pygame.SRCALPHA)
        pygame.draw.rect(gl, acc + (200,), (pad - 2, pad - 2, pw + 4, ph + 4), 6, border_radius=6)
        sf.blit(_dblur(gl, 4), (0, 0))
        body = pygame.Surface((pw, ph))
        for yy in range(ph): pygame.draw.line(body, _mix(_mix(bot, acc, 0.32), (4,4,10), yy / max(1, ph)), (0, yy), (pw, yy))
        for i in range(int(w)):
            for j in range(int(h)):
                r = pygame.Rect(int(i * TS) + 4, int(j * TS) + 4, int(TS) - 8, int(TS) - 8)
                pygame.draw.rect(body, _mix(_mix(bot, acc, 0.45), (0,0,0), 0.25), r, 0, border_radius=4)
                pygame.draw.rect(body, _mix(acc, bot, 0.35), r, 2, border_radius=4)
                pygame.draw.line(body, _mix(acc, WHITE, 0.35), (r.x + 3, r.y + 3), (r.right - 4, r.y + 3), 1)
        sf.blit(body, (pad, pad))
        pygame.draw.rect(sf, _mix(acc, WHITE, 0.3), (pad, pad, pw, ph), 2, border_radius=3)
        pygame.draw.line(sf, _mix(acc, WHITE, 0.75), (pad + 2, pad + 1), (pad + pw - 3, pad + 1), 3)
        _DBG[key] = sf
    return _DBG[key]

def _dash_spike_surf(TS, acc):
    key = ("K", int(TS), acc)
    if key not in _DBG:
        pad = 10; w = int(TS); h = int(TS * 0.92)
        sf = pygame.Surface((w + pad * 2, h + pad * 2), pygame.SRCALPHA)
        pts = [(pad + 2, pad + h), (pad + w / 2, pad), (pad + w - 2, pad + h)]
        gl = pygame.Surface(sf.get_size(), pygame.SRCALPHA); pygame.draw.polygon(gl, acc + (255,), pts, 8)
        sf.blit(_dblur(gl, 3), (0, 0))
        body = pygame.Surface(sf.get_size(), pygame.SRCALPHA)
        for yy in range(h): pygame.draw.line(body, _mix((30,26,48), (6,5,12), yy / h) + (255,), (0, pad + yy), (sf.get_width(), pad + yy))
        m = pygame.Surface(sf.get_size(), pygame.SRCALPHA); pygame.draw.polygon(m, (255,255,255,255), pts)
        body.blit(m, (0, 0), special_flags=pygame.BLEND_RGBA_MULT); sf.blit(body, (0, 0))
        pygame.draw.polygon(sf, _mix(acc, WHITE, 0.75), pts, 3)
        pygame.draw.line(sf, WHITE, (pad + w / 2, pad + 3), (pad + w * 0.32, pad + h * 0.55), 1)
        _DBG[key] = (sf, pad)
    return _DBG[key]

def _dash_saw_surf(R, acc):
    key = ("W", int(R), acc)
    if key not in _DBG:
        S = int(R * 2 + 24); c = S // 2
        sf = pygame.Surface((S, S), pygame.SRCALPHA)
        gl = pygame.Surface((S, S), pygame.SRCALPHA); pygame.draw.circle(gl, acc + (200,), (c, c), int(R + 4)); sf.blit(_dblur(gl, 4), (0, 0))
        pts = []
        for i in range(24):
            a = i * math.pi / 12; r_ = R if i % 2 == 0 else R * 0.78
            pts.append((c + math.cos(a) * r_, c + math.sin(a) * r_))
        pygame.draw.polygon(sf, (22,18,34), pts); pygame.draw.polygon(sf, _mix(acc, WHITE, 0.6), pts, 2)
        pygame.draw.circle(sf, _mix(acc, (20,16,30), 0.5), (c, c), int(R * 0.55))
        pygame.draw.circle(sf, _mix(acc, WHITE, 0.4), (c, c), int(R * 0.55), 2)
        pygame.draw.circle(sf, (12,10,20), (c, c), int(R * 0.18))
        _DBG[key] = sf
    return _DBG[key]

def draw_dash_ship(surf, cx, cy, TS, col, design, rot):
    """The SHIP: a little rocket with your cube riding in it."""
    s = pygame.Surface((int(TS * 2.0), int(TS * 1.6)), pygame.SRCALPHA); W_, H_ = s.get_size()
    draw_dash_cube(s, W_ * 0.55, H_ * 0.36, TS * 0.52, design, col)
    body = [(W_ * 0.08, H_ * 0.55), (W_ * 0.3, H_ * 0.45), (W_ * 0.88, H_ * 0.52), (W_ * 0.98, H_ * 0.62),
            (W_ * 0.82, H_ * 0.8), (W_ * 0.22, H_ * 0.82), (W_ * 0.08, H_ * 0.72)]
    pygame.draw.polygon(s, (12,10,24), [(x, y + 3) for x, y in body])
    pygame.draw.polygon(s, _mix(col, (20,16,40), 0.25), body)
    pygame.draw.polygon(s, _mix(col, WHITE, 0.5), [(W_ * 0.3, H_ * 0.5), (W_ * 0.86, H_ * 0.56), (W_ * 0.84, H_ * 0.6), (W_ * 0.3, H_ * 0.56)])
    pygame.draw.polygon(s, (12,10,24), body, 3)
    pygame.draw.polygon(s, _mix(col, (0,0,0), 0.4), [(W_ * 0.12, H_ * 0.62), (W_ * 0.02, H_ * 0.4), (W_ * 0.22, H_ * 0.52)])
    s = pygame.transform.rotate(s, rot)
    surf.blit(s, s.get_rect(center=(int(cx), int(cy))))

_DVIG = {}
def _dash_vignette(W, H):
    if (W, H) not in _DVIG:
        sm = pygame.Surface((64, 48), pygame.SRCALPHA)
        for yy in range(48):
            for xx in range(64):
                d = math.hypot((xx - 31.5) / 32, (yy - 23.5) / 24)
                sm.set_at((xx, yy), (0, 0, 0, int(min(170, max(0, (d - 0.6) * 300)))))
        _DVIG.clear(); _DVIG[(W, H)] = pygame.transform.smoothscale(sm, (W, H))
    return _DVIG[(W, H)]

def draw_dash_world(surf, run, t):
    W, H = surf.get_size()
    top, bot, acc = _dash_cols(run.stage)
    sky = DASH_SKY[run.stage] if run.stage >= 0 else [DASH_ENDLESS_COLS[0], (70,10,60), (10,50,70), (60,40,10)]
    seg = run.x / 48.0; i0 = int(seg) % len(sky); i1 = (i0 + 1) % len(sky); f = seg - int(seg)
    f = max(0.0, min(1.0, (f - 0.8) / 0.2))                     # hold a color, then blend fast (like a GD color trigger)
    top = _mix(sky[i0], sky[i1], f)
    beat, nb = _dash_beat()
    TS = H / 13.0; gy = int(H * 0.80); cx0 = W * 0.28
    sx = lambda wx: cx0 + (wx - run.x) * TS
    st = run.stage
    surf.blit(_dash_sky(st, W, H, sky[i0], bot, acc), (0, 0))
    if f > 0:                                                    # the next color fades in over the old one
        s2 = _dash_sky(st, W, H, sky[i1], bot, acc); s2.set_alpha(int(255 * f)); surf.blit(s2, (0, 0)); s2.set_alpha(None)
    # two layers of scenery, far and near (parallax)
    for which, fac in ((0, 0.10), (1, 0.28)):
        lay = _dash_layer(st, W, H, which); LW = lay.get_width()
        ox = -int((run.x * TS * fac) % LW)
        y = gy - lay.get_height() + (0 if which == 1 else -int(H * 0.04))
        surf.blit(lay, (ox, y)); surf.blit(lay, (ox + LW, y))
    shade = _DBG.get(("shade", W, H))
    if shade is None:
        shade = pygame.Surface((W, int(H * 0.3)), pygame.SRCALPHA)
        for yy in range(shade.get_height()): pygame.draw.line(shade, (0, 0, 0, int(150 * (yy / shade.get_height()) ** 1.5)), (0, yy), (W, yy))
        _DBG[("shade", W, H)] = shade
    surf.blit(shade, (0, gy - shade.get_height()))
    # an equalizer on the horizon, dancing to the song
    nbars = 32; bw = W / nbars
    eq = pygame.Surface((W, int(H * 0.25)), pygame.SRCALPHA)
    for i in range(nbars):
        hh = (0.2 + 0.8 * abs(math.sin(i * 1.7 + nb * 0.9))) * beat * H * 0.2 + H * 0.01
        pygame.draw.rect(eq, (*_mix(acc, WHITE, 0.2), 70), (i * bw + 3, eq.get_height() - hh, bw - 6, hh), border_radius=3)
    surf.blit(eq, (0, gy - eq.get_height()))
    # floating squares in front of the sky
    for i in range(10):
        rr = random.Random(700 + i); size = TS * rr.uniform(0.5, 1.4) * (1 + 0.15 * beat)
        px = (rr.random() * W * 1.6 - run.x * TS * 0.45) % (W * 1.6) - W * 0.3
        py = rr.random() * (gy - size * 3)
        sq = pygame.Surface((int(size), int(size)), pygame.SRCALPHA)
        pygame.draw.rect(sq, (*_mix(acc, WHITE, 0.3), int(50 + 70 * beat)), sq.get_rect(), 2, border_radius=4)
        surf.blit(pygame.transform.rotate(sq, (t * 30 + i * 37) % 360), (px, py))
    # ground: gradient, moving tiles, a glowing edge
    surf.blit(_dash_ground(W, H, gy, bot, acc), (0, gy))
    off = (run.x * TS) % TS
    tl = pygame.Surface((W, H - gy), pygame.SRCALPHA)
    for i in range(int(W / TS) + 2):
        gx = int(i * TS - off)
        pygame.draw.rect(tl, (*_mix(acc, WHITE, 0.2), int(28 + 30 * beat)), (gx + 3, 3, int(TS) - 6, int(TS) - 6), 2, border_radius=4)
        pygame.draw.rect(tl, (*acc, 14), (gx + 3, int(TS) + 3, int(TS) - 6, int(TS) - 6), 2, border_radius=4)
    surf.blit(tl, (0, gy))
    gl = pygame.Surface((W, 30), pygame.SRCALPHA)
    for k in range(15): a = int((70 + 90 * beat) * (1 - k / 15) ** 2); pygame.draw.line(gl, (*acc, a), (0, 15 - k), (W, 15 - k)); pygame.draw.line(gl, (*acc, a), (0, 15 + k), (W, 15 + k))
    surf.blit(gl, (0, gy - 15))
    pygame.draw.line(surf, _mix(acc, WHITE, 0.55 + 0.4 * beat), (0, gy), (W, gy), 3)
    # ATTEMPT text in the world (like GD)
    at = ui_font(H * 0.07).render(f"{tr('ATTEMPT')} {DS['attempt']}" if not run.practice else tr("PRACTICE"), True, WHITE if not run.practice else (90,255,140))
    at.set_alpha(200); surf.blit(at, at.get_rect(midleft=(sx(3.0), gy - TS * 4.2)))
    vx0 = run.x - W * 0.28 / TS - 2; vx1 = run.x + W * 0.72 / TS + 2
    # practice checkpoints
    for cp in run.cps:
        x = sx(cp["x"] + 0.5)
        if -TS < x < W + TS:
            yy = gy - cp["y"] * TS - TS * 0.5
            pts = [(x, yy - TS * 0.35), (x + TS * 0.22, yy), (x, yy + TS * 0.35), (x - TS * 0.22, yy)]
            pygame.draw.polygon(surf, (60,230,120), pts); pygame.draw.polygon(surf, (12,40,20), pts, 2)
    # blocks
    for bx, bw_, bh in run.lv.near("b", vx0, vx1):
        bs = _dash_block_surf(bw_, bh, TS, acc, bot)
        surf.blit(bs, (int(sx(bx)) - 10, int(gy - bh * TS) - 10))
    # spikes
    ks, kp = _dash_spike_surf(TS, _mix(acc, WHITE, 0.15 * beat))
    for kx, ky in run.lv.near("s", vx0, vx1):
        surf.blit(ks, (int(sx(kx)) - kp, int(gy - ky * TS - TS * 0.92) - kp))
    # SHIP parts: the roof, and the two portals
    for zx0, zx1 in run.lv.zones:
        if zx1 < vx0 or zx0 > vx1: continue
        a = int(max(0, sx(zx0))); b = int(min(W, sx(zx1))); ry = int(gy - DASH_CEIL * TS)
        if b > a:
            roof = pygame.Surface((b - a, ry), pygame.SRCALPHA); roof.fill((*_mix(bot, (0,0,0), 0.4), 215)); surf.blit(roof, (a, 0))
            off2 = (run.x * TS) % TS
            for i in range(int((b - a) / TS) + 2):
                gx = a + int(i * TS - off2)
                if a <= gx < b: pygame.draw.rect(surf, (*_mix(acc, bot, 0.6),), (gx + 3, ry - int(TS) + 3, int(TS) - 6, int(TS) - 6), 1, border_radius=4)
            pygame.draw.line(surf, _mix(acc, WHITE, 0.5 + 0.4 * beat), (a, ry), (b, ry), 3)
        for px_, ship_in in ((zx0, True), (zx1, False)):
            x = sx(px_)
            if -TS * 2 < x < W + TS * 2:
                pc = (255,90,210) if ship_in else (70,190,255)
                r = pygame.Rect(0, 0, int(TS * 0.9), int(TS * 3.4)); r.center = (int(x), int(gy - TS * 1.9))
                surf.blit(_dash_glow(TS * 1.6, pc, 90 + 60 * beat), (r.centerx - int(TS * 1.6), r.centery - int(TS * 1.6)))
                pygame.draw.ellipse(surf, (12,10,24), r.inflate(10, 10)); pygame.draw.ellipse(surf, pc, r, 6)
                pygame.draw.ellipse(surf, _mix(pc, WHITE, 0.6), r.inflate(-14, -14), 2)
                for k in range(5):
                    a2 = t * 3 + k * 1.256
                    pygame.draw.circle(surf, WHITE, (int(r.centerx + math.cos(a2) * r.w * 0.3), int(r.centery + math.sin(a2) * r.h * 0.4)), 2)
                if ship_in:
                    hint = ui_font(H * 0.04).render(tr("HOLD = FLY UP"), True, (255,170,235)); hint.set_alpha(220)
                    surf.blit(hint, hint.get_rect(midbottom=(r.centerx, r.top - 10)))
    # roof blocks (SHIP)
    for bx, bw_, bh in run.lv.near("c", vx0, vx1):
        bs = pygame.transform.flip(_dash_block_surf(bw_, bh, TS, acc, bot), False, True)
        surf.blit(bs, (int(sx(bx)) - 10, int(gy - DASH_CEIL * TS) - 10))
    # saw blades
    for wx, wy, wr in run.lv.near("w", vx0, vx1):
        ss = pygame.transform.rotate(_dash_saw_surf(wr * TS, acc), (-t * 400) % 360)
        surf.blit(ss, ss.get_rect(center=(int(sx(wx)), int(gy - wy * TS))))
    # pads
    for pdx in run.lv.near("p", vx0, vx1):
        x = sx(pdx); r = pygame.Rect(int(x + TS * 0.08), int(gy - TS * 0.28), int(TS * 0.84), int(TS * 0.56))
        surf.blit(_dash_glow(TS * 0.9, (255,220,40), 70 + 50 * beat), (r.centerx - int(TS * 0.9), gy - int(TS * 0.9)))
        pygame.draw.ellipse(surf, (12,10,24), r.inflate(6, 6)); pygame.draw.ellipse(surf, (255,220,40), r)
        pygame.draw.rect(surf, _mix(bot, (0,0,0), 0.3), (r.x - 4, gy, r.w + 8, r.h))
        for k in range(3):                                       # little arrows going up
            yy = gy - TS * (0.4 + ((t * 2 + k / 3) % 1.0) * 0.9)
            pygame.draw.lines(surf, (255,240,150), False, [(r.centerx - 6, yy + 5), (r.centerx, yy), (r.centerx + 6, yy + 5)], 2)
    for pdx, life in run.pad_fx:
        x = sx(pdx) + TS / 2; rr_ = int(TS * (1.4 - life * 2)); pygame.draw.circle(surf, (255,230,80), (int(x), gy), max(2, rr_), 3)
    # orbs
    for o in run.lv.near("o", vx0, vx1):
        x = sx(o["x"]); y = gy - o["y"] * TS; used = o["id"] in run.orbs_used
        rr_ = TS * (0.36 + 0.05 * beat)
        if not used: surf.blit(_dash_glow(TS * 0.9, (255,220,40), 90), (int(x - TS * 0.9), int(y - TS * 0.9)))
        pygame.draw.circle(surf, (12,10,24), (int(x), int(y)), int(rr_ + 4))
        pygame.draw.circle(surf, (120,110,60) if used else (255,225,50), (int(x), int(y)), int(rr_))
        pygame.draw.circle(surf, (12,10,24), (int(x), int(y)), int(rr_ * 0.55))
        if not used:
            a = t * 4
            for k in range(4):
                aa = a + k * math.pi / 2
                pygame.draw.circle(surf, (255,250,190), (int(x + math.cos(aa) * TS * 0.62), int(y + math.sin(aa) * TS * 0.62)), 3)
    # secret coins (big, gold, spinning)
    d = dash_data()
    for c in run.lv.scoins:
        if c["i"] in run.coins_got: continue
        x = sx(c["x"]); y = gy - c["y"] * TS
        if x < -TS or x > W + TS: continue
        had = c["i"] in d["scoins"][run.stage] if run.stage >= 0 else False
        col = (255,210,50) if not had else (170,190,220)          # one you already have looks silver, like in GD
        sw = abs(math.cos(t * 3 + c["i"])); rr_ = TS * 0.42
        surf.blit(_dash_glow(TS * 1.1, col, 80), (int(x - TS * 1.1), int(y - TS * 1.1)))
        e = pygame.Rect(0, 0, max(4, int(rr_ * 2 * (0.25 + 0.75 * sw))), int(rr_ * 2)); e.center = (int(x), int(y))
        pygame.draw.ellipse(surf, (12,10,24), e.inflate(6, 6)); pygame.draw.ellipse(surf, col, e)
        pygame.draw.ellipse(surf, _mix(col, WHITE, 0.5), e.inflate(-e.w * 0.45, -e.h * 0.45), 2)
    for cx_, cy_, life in run.coin_fx:
        s = ui_font(H * 0.05).render("+1", True, (255,215,60)); s.set_alpha(int(255 * life))
        surf.blit(s, s.get_rect(center=(sx(cx_), gy - cy_ * TS - (1 - life) * TS * 1.5)))
    # color gates
    pal = dash_pal()
    for g in run.lv.near("g", vx0, vx1):
        x = sx(g["x"])
        if "lanes" in g:                                         # SHIP: a wall with 3 colored windows
            ry = gy - DASH_CEIL * TS
            pygame.draw.rect(surf, (12,10,24), (int(x) - 3, int(ry), int(TS * 0.5) + 6, int(DASH_CEIL * TS)))
            for y0, y1, col_, ok_ in g["lanes"]:
                cc = pal.get(col_, NEON[col_]); r = pygame.Rect(int(x), int(gy - y1 * TS), int(TS * 0.5), int((y1 - y0) * TS))
                glow = pygame.Surface((r.w + 30, r.h + 30), pygame.SRCALPHA)
                pygame.draw.rect(glow, (*cc, 55 + int(40 * beat) if g["done"] is not True else 20), glow.get_rect(), border_radius=12)
                surf.blit(glow, (r.x - 15, r.y - 15))
                pygame.draw.rect(surf, cc if g["done"] is not True else _mix(cc, WHITE, 0.6), r, border_radius=6)
                for k in range(3):
                    yy = r.bottom - ((t * 1.6 + k / 3) % 1.0) * r.h
                    pygame.draw.line(surf, _mix(cc, WHITE, 0.7), (r.x + 4, yy), (r.right - 4, yy), 2)
            continue
        col = pal.get(g["col"], NEON[g["col"]]); gh = DASH_GATE_H * TS
        r = pygame.Rect(int(x), int(gy - gh), int(TS * 0.5), int(gh))
        glow = pygame.Surface((r.w + 40, r.h + 40), pygame.SRCALPHA)
        pygame.draw.rect(glow, (*col, (50 + int(40 * beat)) if g["done"] is not True else 25), glow.get_rect(), border_radius=14)
        surf.blit(glow, (r.x - 20, r.y - 20))
        pygame.draw.rect(surf, (12,10,24), r.inflate(6, 6), border_radius=8)
        pygame.draw.rect(surf, col if g["done"] is not True else _mix(col, WHITE, 0.6), r, border_radius=6)
        pygame.draw.rect(surf, _mix(col, WHITE, 0.5), (r.x + 3, r.y + 3, r.w - 6, r.h * 0.2), border_radius=4)
        for k in range(3):                                       # energy lines running up the gate
            yy = r.bottom - ((t * 1.6 + k / 3) % 1.0) * r.h
            pygame.draw.line(surf, _mix(col, WHITE, 0.7), (r.x + 4, yy), (r.right - 4, yy), 2)
    for fx, life in run.ok_fx:
        x = sx(fx); rr_ = int(TS * (1.6 - life)); pygame.draw.circle(surf, WHITE, (int(x + TS * 0.25), int(gy - TS * 0.75)), rr_, 3)
    # finish line
    if run.lv.end is not None:
        x = sx(run.lv.end)
        if x < W:
            for j in range(int(gy / 20) + 1):
                pygame.draw.rect(surf, WHITE if j % 2 == 0 else (20,20,30), (int(x), j * 20, 14, 20))
    # trail + cube
    ccol = pal.get(d["cube_col"], NEON["BLUE"])
    for px, py, life in run.trail:
        a = int(255 * life / 0.35 * 0.5)
        sq = pygame.Surface((int(TS * 0.5), int(TS * 0.5)), pygame.SRCALPHA); sq.fill((*ccol, a))
        surf.blit(sq, (sx(px) + TS * 0.25, gy - py * TS - TS * 0.75))
    if not run.dead:
        surf.blit(_dash_glow(TS * 1.1, ccol, 70 + 40 * beat), (int(sx(run.x) + TS / 2 - TS * 1.1), int(gy - run.y * TS - TS / 2 - TS * 1.1)))
        if run.ship: draw_dash_ship(surf, sx(run.x) + TS / 2, gy - run.y * TS - TS / 2, TS, ccol, d["cube"], run.rot)
        else:        draw_dash_cube(surf, sx(run.x) + TS / 2, gy - run.y * TS - TS / 2, TS * 0.96, d["cube"], ccol, run.rot)
    for p in run.parts:
        sz = max(2, int(TS * 0.25 * min(1.0, p[4]))); pygame.draw.rect(surf, p[5] or ccol, (sx(p[0]), gy - p[1] * TS, sz, sz))
    if run.flash > 0:
        fl = pygame.Surface((W, H), pygame.SRCALPHA); fl.fill((255,255,255, int(60 * run.flash))); surf.blit(fl, (0, 0))
    amb = st if st >= 0 else 4
    for i in range(36):
        rr = random.Random(900 + i); sp_ = rr.uniform(0.6, 1.4)
        if amb == 0:                                             # neon rain
            x = (rr.random() * W - t * 120 * sp_ - run.x * TS * 0.6) % W; y = (rr.random() * H + t * 520 * sp_) % H
            pygame.draw.line(surf, (*_mix(acc, WHITE, 0.4),), (x, y), (x - 6, y + 16), 1)
        elif amb == 1:                                           # fireflies
            x = (rr.random() * W - run.x * TS * 0.3 + math.sin(t * sp_ + i) * 30) % W; y = gy - rr.random() * H * 0.5 + math.cos(t * 1.3 * sp_ + i) * 14
            a = int(120 + 120 * math.sin(t * 3 * sp_ + i)); dot = pygame.Surface((6, 6), pygame.SRCALPHA); pygame.draw.circle(dot, (*_mix(acc, WHITE, 0.5), max(0, a)), (3, 3), 3); surf.blit(dot, (x, y))
        elif amb == 2:                                           # crystal sparkles
            x = (rr.random() * W - run.x * TS * 0.5) % W; y = rr.random() * gy
            k = max(0.0, math.sin(t * 2.5 * sp_ + i * 1.7)); L = 2 + 6 * k
            if k > 0.3: pygame.draw.line(surf, WHITE, (x - L, y), (x + L, y), 1); pygame.draw.line(surf, WHITE, (x, y - L), (x, y + L), 1)
        elif amb == 3:                                           # ink dripping from above
            x = (rr.random() * W - run.x * TS * 0.4) % W; y = (rr.random() * H + t * 160 * sp_) % H
            pygame.draw.ellipse(surf, (14,8,20), (x, y, 5, 9))
        else:                                                    # shooting stars
            if i < 4:
                ph = (t * 0.35 * sp_ + rr.random()) % 1.0; x = W * (1.1 - ph * 1.3) + rr.random() * 200; y = H * (0.05 + rr.random() * 0.3) + ph * H * 0.2
                pygame.draw.line(surf, WHITE, (x, y), (x + 40, y - 8), 2)
    surf.blit(_dash_vignette(W, H), (0, 0))
    if run.shake > 0:
        k = int(run.shake * 30); surf.scroll(random.randint(-k, k), random.randint(-k, k))
    return TS, gy

def _dash_outlined(surf, text, size, col, center):
    f = ui_font(size)
    for ox, oy in ((-3,0),(3,0),(0,-3),(0,3),(3,3)):
        o = f.render(text, True, (10,8,20)); surf.blit(o, o.get_rect(center=(center[0] + ox, center[1] + oy)))
    s = f.render(text, True, col); surf.blit(s, s.get_rect(center=center))

def draw_dash_hud(surf, run, t):
    W, H = surf.get_size(); m = min(W, H)
    # the word for the next gate group
    g = run.lv.group_ahead(run.x + 0.5)
    if g is not None and not run.dead and not run.done:
        sp = run.lv.speed_at(run.x); dist = g["x0"] - run.x
        if dist < sp * 2.4:
            pal = dash_pal(); ink = pal.get(g["ink"], NEON[g["ink"]])
            pop = min(1.0, (sp * 2.4 - dist) / (sp * 0.25))       # the word pops in
            lab = ui_font(m * 0.034).render(tr("GO THROUGH"), True, (220,220,240))
            surf.blit(lab, lab.get_rect(center=(W // 2, int(H * 0.115))))
            _dash_outlined(surf, tr(g["word"]), m * 0.13 * (0.6 + 0.4 * pop), ink, (W // 2, int(H * 0.2)))
    # progress bar or ENDLESS counters
    if run.stage >= 0:
        d = dash_data(); bw = int(W * 0.42); r = pygame.Rect(W // 2 - bw // 2, 14, bw, 14)
        pygame.draw.rect(surf, (12,10,24), r.inflate(6, 6), border_radius=10)
        pygame.draw.rect(surf, (90,255,140) if run.practice else _dash_cols(run.stage)[2], (r.x, r.y, int(bw * run.progress() / 100), r.h), border_radius=8)
        if d["best"][run.stage] and not run.practice:
            bx = r.x + int(bw * d["best"][run.stage] / 100); pygame.draw.line(surf, WHITE, (bx, r.y - 4), (bx, r.bottom + 4), 2)
        ps = ui_font(m * 0.032).render(f"{run.progress()}%", True, WHITE); surf.blit(ps, ps.get_rect(midleft=(r.right + 12, r.centery)))
        ns = ui_font(m * 0.028).render(tr(DASH_STAGES[run.stage][0]), True, (200,200,230)); surf.blit(ns, ns.get_rect(midright=(r.x - 12, r.centery)))
        for i in range(3):                                         # the 3 secret coins of this stage
            cx = W - 30 - (2 - i) * 26; cy = 52
            got = i in run.coins_got; had = i in d["scoins"][run.stage]
            pygame.draw.circle(surf, (12,10,24), (cx, cy), 11)
            if got: pygame.draw.circle(surf, (255,210,50), (cx, cy), 9)
            else:   pygame.draw.circle(surf, (170,190,220) if had else (90,80,60), (cx, cy), 9, 2)
    else:
        s = ui_font(m * 0.04).render(f"{tr('GATES')}: {run.gates}    {int(run.x)} m", True, WHITE)
        surf.blit(s, s.get_rect(center=(W // 2, 22)))
    if run.practice:
        ps = ui_font(m * 0.03).render(tr("PRACTICE MODE - no rewards"), True, (90,255,140)); surf.blit(ps, ps.get_rect(topleft=(12, 40)))
    hint = ui_font(m * 0.026).render(tr("SPACE / CLICK = JUMP  •  ESC = back"), True, (170,170,200))
    hint.set_alpha(150); surf.blit(hint, hint.get_rect(bottomright=(W - 12, H - 8)))
    # stage name at the start of the first attempt
    if run.stage >= 0 and DS["attempt"] == 1 and run.t < 2.4 and not run.dead:
        a = 1.0 if run.t < 1.6 else max(0.0, 1 - (run.t - 1.6) / 0.8)
        s = ui_font(m * 0.11).render(tr(DASH_STAGES[run.stage][0]), True, _dash_cols(run.stage)[2]); s.set_alpha(int(255 * a))
        surf.blit(s, s.get_rect(center=(W // 2, int(H * 0.42))))
    if run.dead:
        _dash_outlined(surf, tr(run.why), m * 0.07, (255,90,110), (W // 2, int(H * 0.4)))
        if run.new_best:
            _dash_outlined(surf, f"{tr('NEW BEST!')}  {run.new_best}%", m * 0.06, (255,215,60), (W // 2, int(H * 0.5)))
    if run.done and run.done_t < 1.2:
        _dash_outlined(surf, tr("STAGE COMPLETE!") if run.stage >= 0 else "", m * 0.1, _dash_cols(run.stage)[2], (W // 2, int(H * 0.4)))

def _dash_panel(surf, title, lines, col, buttons, dt, mouse, coins=None):
    W, H = surf.get_size(); m = min(W, H)
    sh = pygame.Surface((W, H), pygame.SRCALPHA); sh.fill((0,0,0,150)); surf.blit(sh, (0, 0))
    r = pygame.Rect(0, 0, int(W * 0.58), int(H * 0.6)); r.center = (W // 2, H // 2)
    pygame.draw.rect(surf, (18,14,34), r, border_radius=22); pygame.draw.rect(surf, col, r, 3, border_radius=22)
    ts = render_fit(ui_font(m * 0.085), title, col, r.w - 40); surf.blit(ts, ts.get_rect(center=(r.centerx, r.y + int(r.h * 0.14))))
    y = r.y + int(r.h * 0.29)
    if coins is not None:                                           # the 3 secret coins: got / had / missing
        for i in range(3):
            cx = r.centerx + (i - 1) * int(m * 0.075); st = coins[i]
            pygame.draw.circle(surf, (12,10,24), (cx, y), int(m * 0.028))
            if st == 2:   pygame.draw.circle(surf, (255,210,50), (cx, y), int(m * 0.024))
            elif st == 1: pygame.draw.circle(surf, (170,190,220), (cx, y), int(m * 0.024))
            else:         pygame.draw.circle(surf, (90,80,60), (cx, y), int(m * 0.024), 2)
        y += int(m * 0.07)
    for ln, lc in lines:
        s = render_fit(ui_font(m * 0.04), ln, lc, r.w - 40); surf.blit(s, s.get_rect(center=(r.centerx, y))); y += int(m * 0.056)
    out = {}; n = len(buttons); bw = int(r.w * 0.28); gap = int(r.w * 0.04)
    x0 = r.centerx - (n * bw + (n - 1) * gap) // 2
    for i, (key, label, bc) in enumerate(buttons):
        br = pygame.Rect(x0 + i * (bw + gap), r.bottom - int(r.h * 0.18), bw, int(m * 0.065))
        ui_pill(surf, "dash_" + key, br, label, bc, dt, mouse); out[key] = br
    return out

def _dash_finish_stage(run):
    d = dash_data(); s = run.stage
    if run.practice:
        return {"kind": "practice", "coins": 0}
    first = not d["cleared"][s]
    d["cleared"][s] = True; d["best"][s] = 100
    coins = DASH_FIRST_COINS[s] if first else DASH_REPLAY_COINS
    newc = [i for i in sorted(run.coins_got) if i not in d["scoins"][s]]
    d["scoins"][s] = sorted(set(d["scoins"][s]) | set(run.coins_got))
    coins += DASH_SECRET_COINS * len(newc)
    add_coins(coins); dash_check_rewards(); save_gd(gd)
    unlock = ["SMILEY", "THE EYE", "STAR", "CROWN"][s] if first else None
    return {"kind": "clear", "coins": coins, "first": first, "unlock": unlock, "newc": len(newc)}

def _dash_finish_endless(run):
    d = dash_data(); new = run.gates > d["endless_best"]
    d["endless_best"] = max(d["endless_best"], run.gates); d["endless_dist"] = max(d["endless_dist"], int(run.x))
    coins = min(100, run.gates // 2)
    if coins: add_coins(coins)
    dash_check_rewards(); save_gd(gd)
    return {"kind": "endless", "coins": coins, "new": new}

def draw_dash_hub(surf, dt, mouse, t):
    W, H = surf.get_size(); m = min(W, H); d = dash_data()
    for yy in range(0, H, 6):
        pygame.draw.rect(surf, _mix((30,16,80), (6,4,18), yy / H), (0, yy, W, 6))
    for i in range(10):                                  # a few cubes jumping in the background
        rr = random.Random(40 + i); x = (rr.random() * W + t * 60 * rr.uniform(0.5, 1.5)) % (W + 80) - 40
        y = H * 0.9 - abs(math.sin(t * 2.2 + i)) * H * 0.08
        draw_dash_cube(surf, x, y, m * 0.035, DASH_CUBES[i % 8][0], NEON[COLOR_NAMES[i % 6]], -((t * 300 + i * 40) % 360), 90)
    top = draw_header(surf, tr("DASH MODE"), tr("Jump the spikes. Run through the color the WORD says."), (60,200,255), t)
    rects = {}
    n = 5; gp = int(W * 0.016); cw = int((W * 0.94 - (n - 1) * gp) / n); x0 = (W - (n * cw + (n - 1) * gp)) // 2
    ch = int(min(H * 0.46, H - top - m * 0.24))
    for i, st in enumerate(DASH_STAGES):
        lk = i > 0 and not d["cleared"][i - 1]
        r = pygame.Rect(x0 + i * (cw + gp), top + 6, cw, ch)
        ex = (tr("CLEARED") if d["cleared"][i] else f"{tr('Best')}: {d['best'][i]}%") + f"  •  {len(d['scoins'][i])}/3"
        ui_card(surf, f"dash_s{i}", r, st[6][2], "play", st[0], f"{tr('STAGE')} {i + 1}", t, dt, mouse,
                tag=("NEW" if (not lk and not d["cleared"][i] and d["best"][i] == 0) else None), extra=ex, locked=lk)
        if not lk:                                             # the 3 secret coins under the title
            for k in range(3):
                cx = r.centerx + (k - 1) * 16; cy = r.bottom - int(ch * 0.2)
                had = k in d["scoins"][i]
                pygame.draw.circle(surf, (12,10,24), (cx, cy), 7)
                if had: pygame.draw.circle(surf, (255,210,50), (cx, cy), 5)
                else:   pygame.draw.circle(surf, (110,100,80), (cx, cy), 5, 1)
        rects[f"s{i}"] = (r, lk)
    r = pygame.Rect(x0 + 4 * (cw + gp), top + 6, cw, ch)
    ui_card(surf, "dash_end", r, (150,120,255), "bolt", "ENDLESS", tr("How far can you go?"), t, dt, mouse,
            extra=f"{tr('Best')}: {d['endless_best']} {tr('gates')}")
    rects["endless"] = (r, False)
    # cube preview + CUBES + PRACTICE
    py = top + 6 + ch + int(m * 0.075)
    pal = dash_pal()
    draw_dash_cube(surf, W // 2 - int(m * 0.36), py, m * 0.07, d["cube"], pal.get(d["cube_col"], NEON["BLUE"]), math.sin(t * 2) * 8)
    cb = pygame.Rect(W // 2 - int(m * 0.28), py - int(m * 0.035), int(m * 0.26), int(m * 0.07))
    ui_pill(surf, "dash_cubes", cb, "CUBES", (60,200,255), dt, mouse, "palette")
    rects["cubes"] = (cb, False)
    pb = pygame.Rect(W // 2 + int(m * 0.02), py - int(m * 0.035), int(m * 0.34), int(m * 0.07))
    ui_pill(surf, "dash_prac", pb, f"{tr('PRACTICE')}: {tr('ON') if d['practice'] else tr('OFF')}", (60,220,120) if d["practice"] else (90,90,140), dt, mouse)
    rects["practice"] = (pb, False)
    at = ui_font(m * 0.028).render(f"{tr('Attempts')}: {d['attempts']}   •   {tr('Secret coins')}: {dash_scoin_total(d)}/12", True, (170,170,210))
    surf.blit(at, at.get_rect(midright=(W - 20, H - 40)))
    bk = ui_back(surf, dt, mouse)
    return rects, bk

def draw_dash_cubes(surf, dt, mouse, t):
    W, H = surf.get_size(); m = min(W, H); d = dash_data(); pal = dash_pal()
    for yy in range(0, H, 6):
        pygame.draw.rect(surf, _mix((30,16,80), (6,4,18), yy / H), (0, yy, W, 6))
    top = draw_header(surf, tr("CUBES"), tr("Pick your cube and its color"), (60,200,255), t)
    rects = []
    cols = 4; cw = int(W * 0.2); chh = int(m * 0.2); gp = int(W * 0.02); x0 = (W - (cols * cw + (cols - 1) * gp)) // 2
    for i, (cid, name, how) in enumerate(DASH_CUBES):
        r = pygame.Rect(x0 + (i % cols) * (cw + gp), top + 8 + (i // cols) * (chh + gp), cw, chh)
        un = dash_cube_unlocked(cid, d); sel = d["cube"] == cid
        hv = ui_hover("dcube" + cid, 1.0 if r.collidepoint(mouse) and un else 0.0, dt)
        pygame.draw.rect(surf, (22,18,44) if un else (16,14,26), r, border_radius=16)
        pygame.draw.rect(surf, (60,200,255) if sel else _mix((70,70,100), WHITE, 0.3 * hv), r, 3 if sel else 2, border_radius=16)
        draw_dash_cube(surf, r.centerx, r.y + r.h * 0.4, chh * 0.42, cid, pal.get(d["cube_col"], NEON["BLUE"]) if un else (70,70,90),
                       math.sin(t * 3 + i) * 10 * hv, 255 if un else 120)
        ns = render_fit(ui_font(m * 0.03), name, WHITE if un else (130,130,150), r.w - 16); surf.blit(ns, ns.get_rect(center=(r.centerx, r.bottom - chh * 0.24)))
        hs = render_fit(ui_font(m * 0.023), (tr("EQUIPPED") if sel else tr("Unlocked")) if un else how, (60,200,255) if sel else (150,150,180), r.w - 16)
        surf.blit(hs, hs.get_rect(center=(r.centerx, r.bottom - chh * 0.1)))
        if not un: ui_icon2(surf, "lock", r.right - 18, r.y + 18, 9, (140,140,170))
        rects.append(("cube", cid, r, un))
    yy = top + 8 + 2 * (chh + gp) + int(m * 0.05); sz = int(m * 0.06); n = len(COLOR_NAMES)
    xx = W // 2 - (n * sz + (n - 1) * 14) // 2
    for i, k in enumerate(COLOR_NAMES):
        r = pygame.Rect(xx + i * (sz + 14), yy, sz, sz); c = pal.get(k, NEON[k])
        pygame.draw.rect(surf, (12,10,24), r.inflate(6, 6), border_radius=10); pygame.draw.rect(surf, c, r, border_radius=8)
        if d["cube_col"] == k: pygame.draw.rect(surf, WHITE, r.inflate(10, 10), 3, border_radius=12)
        rects.append(("col", k, r, True))
    bk = ui_back(surf, dt, mouse)
    return rects, bk

def dash_screen(surf, dt, mouse, events):
    """Returns 'exit' when the player leaves DASH MODE."""
    DS["t"] += dt; DS["mt"] += dt; t = DS["t"]; sc = DS["screen"]
    if sc == "run":
        run = DS["run"]
        if DS.get("want") and _dash_song_ready(DS["want"]):      # the real song just finished rendering
            _dash_music(run.stage)
        keys = pygame.key.get_pressed()
        holding = keys[pygame.K_SPACE] or keys[pygame.K_UP] or keys[pygame.K_w] or pygame.mouse.get_pressed()[0]
        if DS["res"] is None:
            for ev in events:
                if (ev.type == pygame.KEYDOWN and ev.key in (pygame.K_SPACE, pygame.K_UP, pygame.K_w)) or \
                   (ev.type == pygame.MOUSEBUTTONDOWN and ev.button == 1): run.hold(True)
            run.update(dt, holding)
        draw_dash_world(surf, run, t); draw_dash_hud(surf, run, t)
        if DS["res"] is None:
            if ui_esc(events):
                DS["screen"] = "hub"; DS["run"] = None; play_music("menu"); SND_SELECT.play(); return None
            if run.dead and run.dead > 0.02 and not getattr(run, "_counted", False):
                run._counted = True
                d = dash_data()
                if not run.practice:
                    d["attempts"] += 1
                    if run.stage >= 0 and run.progress() > d["best"][run.stage]:
                        run.new_best = run.progress(); d["best"][run.stage] = run.progress()
                    dash_check_rewards()
            if run.dead and run.practice and run.dead > 0.55:
                run.respawn(); run._counted = False
            elif run.dead and run.dead > 1.0:
                if run.stage >= 0:
                    DS["run"] = DashRun(run.stage, False); DS["attempt"] += 1          # straight back in, like GD
                    _dash_music(run.stage)
                else:
                    DS["res"] = _dash_finish_endless(run)
            elif run.done and run.done_t > 1.3:
                DS["res"] = _dash_finish_stage(run)
            return None
        res = DS["res"]; d = dash_data()
        if res["kind"] in ("clear", "practice"):
            coins = None
            if run.stage >= 0:
                coins = [2 if i in run.coins_got else (1 if i in d["scoins"][run.stage] else 0) for i in range(3)]
            if res["kind"] == "practice":
                lines = [(tr("Practice run - no rewards."), (90,255,140)), (tr("Now try it for real!"), WHITE)]
                title = tr("PRACTICE COMPLETE!")
            else:
                lines = [(f"{tr('Attempts')}: {DS['attempt']}", WHITE),
                         (f"+{res['coins']} {tr('coins')}", (255,215,80))]
                if res.get("newc"): lines.append((f"{tr('Secret coins')}: +{res['newc']}", (255,215,80)))
                if res["unlock"]: lines.append((f"{tr('New cube')}: {res['unlock']}", (60,200,255)))
                if run.stage == 3 and res["first"]: lines.append((tr("New skin: Dash"), (255,90,200)))
                title = tr("STAGE COMPLETE!")
            btns = [("again", "AGAIN", (90,90,140)), ("hub", "STAGES", (60,200,255))]
            if run.stage < 3 and res["kind"] == "clear": btns.append(("next", "NEXT STAGE", (60,220,120)))
            out = _dash_panel(surf, title, lines, _dash_cols(run.stage)[2], btns, dt, mouse, coins)
        else:
            lines = [(f"{tr('GATES')}: {run.gates}" + (f"   {tr('NEW BEST!')}" if res["new"] else ""), (255,215,80) if res["new"] else WHITE),
                     (f"{tr('Best')}: {d['endless_best']}    {int(run.x)} m", (200,200,230)),
                     (f"+{res['coins']} {tr('coins')}", (255,215,80))]
            out = _dash_panel(surf, tr(run.why or "GAME OVER"), lines, (150,120,255),
                              [("again", "AGAIN", (60,220,120)), ("hub", "STAGES", (60,200,255))], dt, mouse)
        if ui_click(events, out.get("again", pygame.Rect(0,0,0,0))) or any(ev.type == pygame.KEYDOWN and ev.key == pygame.K_RETURN for ev in events):
            _dash_start(run.stage); SND_SELECT.play()
        elif "next" in out and ui_click(events, out["next"]):
            _dash_start(run.stage + 1); SND_SELECT.play()
        elif ui_click(events, out["hub"]) or ui_esc(events):
            DS["screen"] = "hub"; DS["run"] = None; DS["res"] = None; play_music("menu"); SND_SELECT.play()
        return None
    if sc == "cubes":
        rects, bk = draw_dash_cubes(surf, dt, mouse, t); d = dash_data()
        for kind, key, r, un in rects:
            if ui_click(events, r):
                if not un: SND_WRONG.play()
                elif kind == "cube": d["cube"] = key; save_gd(gd); SND_SELECT.play()
                else: d["cube_col"] = key; save_gd(gd); SND_SELECT.play()
        if ui_click(events, bk) or ui_esc(events): DS["screen"] = "hub"; SND_SELECT.play()
        return None
    rects, bk = draw_dash_hub(surf, dt, mouse, t)
    for key, (r, lk) in rects.items():
        if not ui_click(events, r): continue
        if lk: SND_WRONG.play(); break
        if key == "cubes": DS["screen"] = "cubes"; SND_SELECT.play()
        elif key == "practice":
            d = dash_data(); d["practice"] = not d["practice"]; save_gd(gd); SND_SELECT.play()
        elif key == "endless": _dash_start(-1); SND_SELECT.play()
        else: _dash_start(int(key[1:])); SND_SELECT.play()
        break
    else:
        if ui_click(events, bk) or ui_esc(events): return "exit"
    return None

