def draw_ore_info(surf, t, dt, mouse):
    """Everything in the collab announcement, on one page. Returns the BACK button."""
    W, H = surf.get_size(); m = min(W, H)
    draw_menu_bg(surf, t, (255, 206, 60))
    top = draw_header(surf, "ORE MODE", "MAN STUDIO  x  BURGERS STUDIOS", (255, 206, 60), t)
    bot = H - int(m*0.095)
    ds = render_fit(ui_font(m*0.034), "NOV 15  —  DEC 5,  2026", (210, 190, 150), int(W*0.8))
    surf.blit(ds, ds.get_rect(center=(W//2, top+int(m*0.034))))
    tag = render_fit(ui_font(m*0.042), tr("A collaboration, running next to FIRST FROST."),
                     (245, 236, 220), int(W*0.86))
    surf.blit(tag, tag.get_rect(center=(W//2, top+int(m*0.082))))

    y0 = top + int(m*0.118); n = len(ORE_INFO); gp = int(W*0.022)
    cw = int(min(W*0.30, (W*0.92-(n-1)*gp)/n)); x0 = (W-(n*cw+(n-1)*gp))//2
    ch = min(bot-y0-int(m*0.080), int(m*0.50))
    for i, (ic, title, lead, body) in enumerate(ORE_INFO):
        r = pygame.Rect(x0+i*(cw+gp), y0, cw, ch)
        ui_panel(surf, r, None, (255, 206, 60))
        surf.blit(_glow(int(m*0.11), (255,206,60), 32), (r.centerx-int(m*0.11), r.y+int(m*0.052)-int(m*0.11)))
        ui_icon2(surf, ic, r.centerx, r.y+int(m*0.052), int(m*0.038), (255, 206, 60), t)
        ts = render_fit(ui_font(m*0.036), tr(title), (255, 240, 212), r.w-28)
        surf.blit(ts, ts.get_rect(midtop=(r.centerx, r.y+int(m*0.094))))
        ls = render_fit(ui_font(m*0.026), tr(lead), (214, 188, 140), r.w-28)
        surf.blit(ls, ls.get_rect(midtop=(r.centerx, r.y+int(m*0.140))))
        yy = r.y+int(m*0.184); bf = ui_font(m*0.025)
        for ln in wrap_lines(bf, tr(body), r.w-36):
            if yy > r.bottom-20: break
            s_ = bf.render(ln, True, (206, 198, 186))
            surf.blit(s_, s_.get_rect(midtop=(r.centerx, yy)))
            yy += int(s_.get_height()*1.22)
    bl = render_fit(ui_font(m*0.027), tr("New badges") + ":  " + ORE_BADGE_LINE, (190, 180, 164), int(W*0.92))
    surf.blit(bl, bl.get_rect(center=(W//2, bot-int(m*0.042))))
    sg = ui_font(m*0.024).render("MAN STUDIO", True, RUSHY_COL)
    surf.blit(sg, sg.get_rect(center=(W//2, bot-int(m*0.010))))
    return ui_back(surf, dt, mouse)

