def frost_state():
    """'before' / 'active' / 'after' for FIRST FROST (DEV MODE opens it early)."""
    if dev_mode(): return "active"
    if not FROST_ENABLED: return "before"
    return season_state("frost")

def frost_data():
    f=gd.setdefault("frost",{})
    yr=_h_today().year
    if f.get("year")!=yr:
        f.clear(); f["year"]=yr
    f.setdefault("stations",[0]*LAKE_N)        # 0 = not reached, 1 = fell through, 2 = crossed
    f.setdefault("at",0)                       # the station you may walk to now
    for k,v in (("best",0),("runs",0),("longest",0.0),("intro_seen",False),("skin",False)):
        f.setdefault(k,v)
    st=f.get("stations")
    if not isinstance(st,list) or len(st)!=LAKE_N:
        f["stations"]=(list(st) if isinstance(st,list) else [])
        f["stations"]=(f["stations"]+[0]*LAKE_N)[:LAKE_N]
    f["at"]=max(0,min(LAKE_N-1,int(f.get("at",0) or 0)))
    return f

def frost_cleared(): return sum(1 for s in frost_data()["stations"] if s==2)
def frost_done():     return frost_cleared()>=LAKE_N

def frost_check_rewards():
    f=frost_data(); n=frost_cleared()
    if n>=1:      award_badge("frost_born")
    if n>=3:      award_badge("ice_walker")
    if n>=6 and not f.get("coins6"):
        f["coins6"]=True; add_coins(200)
    if frost_done():
        award_badge("lake_crosser")
        if not f.get("skin"):
            f["skin"]=True
            _ul=gd.setdefault("unlocked_skins",["Classic"])
            if "Deep Freeze" not in _ul: _ul.append("Deep Freeze")
    save_gd(gd)

# ── the palette the player is actually using ─────────────────────────────────
def _fr_pal(): return SKINS.get(gd.get("current_skin","Classic"),SKINS["Classic"])

def draw_snowfall(surf, t, amt=1.0, wind=0.0, seed=0):
    """Snow over the whole screen. Cheap: a fixed set of flakes, scrolled."""
    W,H=surf.get_size()
    n=int(70*amt)
    for i in range(n):
        ph=(i*0.6180339887+seed*0.311)%1.0
        z=0.35+0.65*((i*7%11)/10.0)
        y=(ph*H+t*(26+70*z))%(H+20)-10
        x=(ph*W*1.7+math.sin(t*0.5+i)*22*z+wind*t*34*z)%(W+20)-10
        r=max(1,int(1.4+2.2*z))
        a=int(90+120*z)
        s=pygame.Surface((r*2+2,r*2+2),pygame.SRCALPHA)
        pygame.draw.circle(s,(235,246,255,a),(r+1,r+1),r)
        surf.blit(s,(int(x),int(y)))

def draw_snowflake(surf, cx, cy, r, col, t=0.0, w=2):
    for k in range(6):
        a=math.tau*k/6+t*0.35
        x,y=cx+math.cos(a)*r, cy+math.sin(a)*r
        pygame.draw.line(surf,col,(cx,cy),(x,y),w)
        for b in (0.45,0.72):
            bx,by=cx+(x-cx)*b, cy+(y-cy)*b
            for s_ in (-1,1):
                pygame.draw.line(surf,col,(bx,by),
                                 (bx+math.cos(a+s_*1.05)*r*0.30, by+math.sin(a+s_*1.05)*r*0.30),max(1,w-1))

# ── real frost: dendrites that grow in from the edges (cached, 1 blit a frame) ──
_FROST_CACHE={}
_FROST_LEVELS=14

def _frost_build(W,H):
    """Grow a fractal frost pattern in from all four edges and bake it into
    cumulative layers, so a frame only costs one or two blits."""
    sw,sh=max(80,int(W*0.62)),max(80,int(H*0.62))
    reach=min(sw,sh)*0.72
    rnd=random.Random(20261115)
    segs=[]; facets=[]
    def depth_of(x,y,side):
        d=(y if side==0 else (sh-y) if side==1 else x if side==2 else (sw-x))
        return max(0.0,min(1.0,d/reach))
    def grow(x,y,ang,length,gen,side):
        if gen>7 or length<2.2: return
        x1=x+math.cos(ang)*length; y1=y+math.sin(ang)*length
        if not(-20<x1<sw+20 and -20<y1<sh+20): return
        d=depth_of(x1,y1,side)
        if d>=1.0: return
        segs.append((d,x,y,x1,y1,max(1,int(4.6-gen*0.62)),max(0.30,1.0-gen*0.095)))
        if gen>=3 and rnd.random()<0.22:
            facets.append((d,x1,y1,max(2.0,length*0.42),max(0.3,1.0-gen*0.1)))
        # two side branches at the classic frost angle, plus the trunk carrying on
        for k in (0,1):
            if gen<2 or rnd.random()<0.72:
                a=ang+rnd.uniform(0.42,0.80)*(1 if k else -1)
                grow(x1,y1,a,length*rnd.uniform(0.48,0.70),gen+1,side)
        if rnd.random()<0.86:
            grow(x1,y1,ang+rnd.uniform(-0.20,0.20),length*rnd.uniform(0.72,0.92),gen+1,side)
    for side in range(4):
        n=13 if side<2 else 11
        for i in range(n):
            p=(i+rnd.uniform(0.15,0.85))/n
            if side==0:   x,y,a=p*sw,0.0,math.pi/2
            elif side==1: x,y,a=p*sw,float(sh),-math.pi/2
            elif side==2: x,y,a=0.0,p*sh,0.0
            else:         x,y,a=float(sw),p*sh,math.pi
            grow(x,y,a+rnd.uniform(-0.30,0.30),reach*rnd.uniform(0.17,0.30),0,side)
    segs.sort(key=lambda s:s[0]); facets.sort(key=lambda f:f[0])
    # the sheet of ice itself: an irregular edge that creeps inward
    wob=[rnd.uniform(0.55,1.0) for _ in range(64)]
    layers=[]; cur=pygame.Surface((sw,sh),pygame.SRCALPHA)
    si=fi=0
    for L in range(_FROST_LEVELS+1):
        k=L/float(_FROST_LEVELS)
        lay=pygame.Surface((sw,sh),pygame.SRCALPHA)
        # the sheet
        for side in range(4):
            pts=[]; steps=24
            for i in range(steps+1):
                p=i/float(steps); w=wob[(side*17+i)%64]
                dd=reach*k*(0.42+0.58*w)
                if side==0:   pts.append((p*sw,dd))
                elif side==1: pts.append((p*sw,sh-dd))
                elif side==2: pts.append((dd,p*sh))
                else:         pts.append((sw-dd,p*sh))
            if side==0:   pts=[(0,0)]+pts+[(sw,0)]
            elif side==1: pts=[(0,sh)]+pts+[(sw,sh)]
            elif side==2: pts=[(0,0)]+pts+[(0,sh)]
            else:         pts=[(sw,0)]+pts+[(sw,sh)]
            if len(pts)>2:
                pygame.draw.polygon(lay,(170,218,255,int(26+54*k)),pts)
                pygame.draw.lines(lay,(238,250,255,int(80+100*k)),False,pts[1:-1],2)
        while si<len(segs) and segs[si][0]<=k:
            d,x0,y0,x1,y1,w,b=segs[si]; si+=1
            pygame.draw.line(lay,(int(186+62*b),int(224+28*b),255,int(120+125*b)),(x0,y0),(x1,y1),w)
            if w>2: pygame.draw.line(lay,(255,255,255,int(90+90*b)),(x0,y0),(x1,y1),max(1,w-2))
        while fi<len(facets) and facets[fi][0]<=k:
            d,fx,fy,fr,b=facets[fi]; fi+=1
            hexp=[(fx+math.cos(math.tau*j/6+0.3)*fr, fy+math.sin(math.tau*j/6+0.3)*fr) for j in range(6)]
            pygame.draw.polygon(lay,(222,243,255,int(55+45*b)),hexp)
            pygame.draw.polygon(lay,(250,254,255,int(110+90*b)),hexp,1)
        cur.blit(lay,(0,0))
        layers.append(pygame.transform.smoothscale(cur,(W,H)))
    _FROST_CACHE.clear(); _FROST_CACHE[(W,H)]=layers
    return layers

_FR_SPARK=[(random.Random(i*13+5).random(),random.Random(i*29+7).random(),
            random.Random(i*41+3).random()) for i in range(60)]

def draw_frost_edge(surf, k, t):
    """Ice growing in from the four edges. k = 0..1 how frozen the screen is."""
    if k<=0.004: return
    W,H=surf.get_size()
    layers=_FROST_CACHE.get((W,H)) or _frost_build(W,H)
    k=min(1.0,k)
    f=k*_FROST_LEVELS; i=int(f); fr=f-i
    surf.blit(layers[min(i,_FROST_LEVELS)],(0,0))
    if i<_FROST_LEVELS and fr>0.02:                       # fade the next layer in
        nx=layers[i+1].copy(); nx.set_alpha(int(255*fr)); surf.blit(nx,(0,0))
    for sx,sy,sp in _FR_SPARK:                            # the ice catches the light
        if sp>k*1.15: continue
        edge=min(sx,1-sx,sy,1-sy)
        if edge>0.30*k: continue
        tw=0.5+0.5*math.sin(t*(2.4+sp*5)+sp*30)
        if tw<0.45: continue
        r=int(min(W,H)*0.006*(0.6+tw))
        x,y=int(sx*W),int(sy*H)
        pygame.draw.line(surf,(255,255,255),(x-r*3,y),(x+r*3,y),1)
        pygame.draw.line(surf,(255,255,255),(x,y-r*3),(x,y+r*3),1)
        pygame.draw.circle(surf,(255,255,255),(x,y),max(1,r))
    if k>0.74:                                            # the last of the warmth going
        o=pygame.Surface((W,H),pygame.SRCALPHA); o.fill((176,222,255,int(165*(k-0.74)/0.26)))
        surf.blit(o,(0,0))


