# ── the screens ──────────────────────────────────────────────────────────────
OTS = {"screen":"hub","back":"limited_menu","round":None,"t":0.0,"want":None}

OTHER_MUSIC_FILE = "other_side_music.mp3"     # "Into the Void" - White Bat Audio (royalty free, credit below)
OTHER_MUSIC_CREDIT = "Music: Into the Void - White Bat Audio"
def _other_music_file():
    """The real song for THE OTHER SIDE, from the game folder (and the MSIX). True if it plays."""
    global _cur_music
    if _cur_music=="other_file":
        try:
            if pygame.mixer.music.get_busy(): return True
        except Exception: pass
    p=_res_path(OTHER_MUSIC_FILE)
    if not os.path.exists(p):
        print("[other music]",p,"NOT FOUND - using the built-in song"); return False
    try:
        pygame.mixer.music.load(p)                    # load first: if it fails, the old music keeps going
        pygame.mixer.stop(); _cur_music="other_file"
        pygame.mixer.music.set_volume(min(1.0,gd.get("music_volume",0.8)*0.6))
        pygame.mixer.music.play(-1)
        return True
    except Exception as e:
        print("[other music] error:",e); return False

def _other_music():
    """The song file if it is there. If not: our synthwave song, and until that one is
    made (first launch), another one plays - never silence."""
    OTS["want"]=None
    if _other_music_file(): return
    k="osd"
    if "MUSIC2" in globals() and globals().get("_np") is not None and k not in MUSIC2:
        OTS["want"]=k
        for fb in ("dsh2","vibe","haunt","menu"):
            if fb in MUSIC2: k=fb; break
    play_music(k)

def other_open(screen="hub", back="limited_menu"):
    o=other_data()
    if screen=="hub" and not o.get("intro_seen"):
        screen="intro"; other_intro_start()
    OTS.update({"screen":screen,"back":back,"round":None,"t":0.0})
    award_badge("night_rider")
    other_check_rewards()
    _other_music()

def draw_other_hub(surf, dt, mouse, t):
    W,H=surf.get_size(); m=min(W,H)
    o=other_data()
    surf.blit(_ot_town(W,H,False),(0,0))
    sh=pygame.Surface((W,H),pygame.SRCALPHA); sh.fill((6,4,16,110)); surf.blit(sh,(0,0))
    top=draw_header(surf,"THE OTHER SIDE",tr("The gate opens")+"  •  15/11 - 25/11",OT_PINK,t)
    ch=max(170,H-90-top-10); gp=int(W*0.026)
    lw=int(W*0.42); lh=int(ch*0.66)
    lr=pygame.Rect(int(W*0.05),top+10,lw,lh)
    ir=pygame.Rect(int(W*0.05),lr.bottom+gp,lw,ch-lh-gp)
    rw=int(W*0.95)-lr.right-gp; rh=(ch-gp*2)//3
    wr=pygame.Rect(lr.right+gp,top+10,rw,rh)
    fr=pygame.Rect(lr.right+gp,wr.bottom+gp,rw,rh)
    br=pygame.Rect(lr.right+gp,fr.bottom+gp,rw,ch-rh*2-gp*2)
    n=other_cleared()
    ui_card(surf,"ot_ride",lr,OT_PINK,"moon","NIGHT RIDE",tr("PART 1  •  Redon, Texas  •  1999"),t,dt,mouse,
            tag=("DONE" if other_done() else "RIDE"),extra=tr("Stations")+f": {n}/{RIDE_N}",big=True)
    ui_card(surf,"ot_intro",ir,(150,80,200),"eye","THE GATE OPENS",tr("Watch it again"),t,dt,mouse)
    ui_card(surf,"ot_lights",wr,OT_SUN,"spark","LIGHT WALL",tr("Best")+f": {o.get('lw_best',0)}",t,dt,mouse,tag="MODE")
    ui_card(surf,"ot_flip",fr,OT_CYAN,"door","FLIP SIDE",tr("Best")+f": {o.get('fs_best',0)}",t,dt,mouse,tag="MODE")
    got=sum(1 for b in OTHER_BADGES if has_badge(b))
    ui_card(surf,"ot_badges",br,(200,120,255),"crown","BADGES",f"{got}/{len(OTHER_BADGES)} "+tr("unlocked"),t,dt,mouse)
    cr_=ui_font(m*0.020).render(OTHER_MUSIC_CREDIT,True,(170,140,190))
    surf.blit(cr_,cr_.get_rect(right=W-14,bottom=H-10))
    return {"ride":lr,"intro":ir,"lights":wr,"flip":fr,"badges":br}

def draw_other_ride(surf, dt, mouse, t):
    """The route of NIGHT RIDE: 8 stations through town, then through the gate, then home."""
    W,H=surf.get_size(); m=min(W,H); o=other_data()
    surf.blit(_ot_town(W,H,False),(0,0))
    half=pygame.Surface((W//2,H),pygame.SRCALPHA)             # the right half is already the other side
    half.blit(_ot_town(W,H,True),(-(W//2),0)); half.set_alpha(150); surf.blit(half,(W//2,0))
    sh=pygame.Surface((W,H),pygame.SRCALPHA); sh.fill((6,4,16,120)); surf.blit(sh,(0,0))
    _ot_ash(surf,t,26,(200,160,190),3)
    top=draw_header(surf,"NIGHT RIDE",tr("PART 1")+"  •  "+tr("Redon, Texas  •  1999 - 2000"),OT_PINK,t)
    pts=[]
    for i in range(RIDE_N):
        u=i/(RIDE_N-1.0)
        x=int(W*0.09+u*W*0.82); y=int(H*0.55+math.sin(u*math.pi*1.8+0.4)*H*0.13)
        pts.append((x,y))
    for i in range(RIDE_N-1):
        a,b=pts[i],pts[i+1]; done=o["stations"][i]==2
        pygame.draw.line(surf,(255,110,190) if done else (70,46,96),a,b,5 if done else 3)
    hit=[]; hov=None
    for i,(x,y) in enumerate(pts):
        st=o["stations"][i]; reach=(i<=o["at"])
        r=int(m*0.045)
        base=OT_RED if i in (5,6) else OT_PINK
        col=(120,235,170) if st==2 else ((255,120,130) if st==1 else (base if reach else (70,56,90)))
        rr=pygame.Rect(x-r,y-r,r*2,r*2)
        if rr.collidepoint(mouse) and reach: hov=i; r=int(r*1.12); rr=pygame.Rect(x-r,y-r,r*2,r*2)
        pygame.draw.circle(surf,(10,6,20),(x,y+3),r)
        pygame.draw.circle(surf,_mix((16,10,30),col,0.30),(x,y),r)
        pygame.draw.circle(surf,col,(x,y),r,3)
        if st==2: ui_icon2(surf,"star",x,y,int(r*0.5),(190,255,220),t)
        elif not reach: ui_icon2(surf,"lock",x,y,int(r*0.5),(130,110,160),t)
        else:
            ns=ui_font(m*0.030).render(str(i+1),True,(255,226,240)); surf.blit(ns,ns.get_rect(center=(x,y)))
        hit.append((rr,i,reach))
    ax,ay=pts[o["at"]]                                         # you are here
    draw_ot_bike(surf,ax-int(m*0.03),ay-int(m*0.055),int(m*0.014),t,True)
    if hov is not None:
        tip=f"{hov+1}. {tr(RIDE_NAMES[hov])}  —  "+tr(RIDE_TWISTS[hov][1])
        ts=render_fit(ui_font(m*0.027),tip,(240,215,240),int(W*0.9))
        surf.blit(ts,ts.get_rect(centerx=W//2,y=int(H*0.80)))
    prog=ui_font(m*0.030).render(tr("Stations")+f": {other_cleared()} / {RIDE_N}",True,(255,226,240))
    surf.blit(prog,prog.get_rect(centerx=W//2,y=int(H*0.86)))
    story_r=None
    if o["seen"]:
        story_r=ui_pill(surf,"ot_story",pygame.Rect(W-int(W*0.05)-int(W*0.20),H-62,int(W*0.20),40),tr("THE STORY"),OT_PINK,dt,mouse,"book")
    bk=ui_back(surf,dt,mouse)
    return (hit,bk,story_r),bk

def draw_other_badges(surf, dt, mouse, t):
    W,H=surf.get_size(); m=min(W,H)
    surf.blit(_ot_town(W,H,True),(0,0))
    sh=pygame.Surface((W,H),pygame.SRCALPHA); sh.fill((6,4,16,140)); surf.blit(sh,(0,0))
    _ot_ash(surf,t,40)
    got=sum(1 for b in OTHER_BADGES if has_badge(b))
    top=draw_header(surf,"BADGES",f"{got} / {len(OTHER_BADGES)} "+tr("unlocked"),(200,120,255),t)
    lst=[get_badge(b) for b in OTHER_BADGES if get_badge(b)]
    cols=min(5,max(1,len(lst))); cw=int(W*0.86)//cols
    rr=int(min(cw*0.33,(H-top-150)*0.40))
    for i,b in enumerate(lst):
        x=int(W*0.07)+cw*i+cw//2; y=top+int((H-top-110)*0.36)
        earned=has_badge(b["id"])
        draw_badge_medal(surf,b,x,y,rr,earned,t,0.3)
        ns=render_fit(ui_font(m*0.026),tr(b["name"]),WHITE if earned else (170,150,190),cw-16)
        surf.blit(ns,ns.get_rect(centerx=x,y=y+rr+14))
        ds=render_fit(ui_font(m*0.021),tr(b["desc"]),(210,180,230) if earned else (130,110,150),cw-16)
        surf.blit(ds,ds.get_rect(centerx=x,y=y+rr+14+int(m*0.034)))
    rw_=ui_font(m*0.026).render(tr("Finish all 8 stations: the skin THE OTHER SIDE, the design 1986 and 300 coins"),True,(255,200,225))
    surf.blit(rw_,rw_.get_rect(centerx=W//2,y=int(H*0.80)))
    return ui_back(surf,dt,mouse)

def other_screen(surf, dt, mouse, events):
    """The whole of THE OTHER SIDE. Returns 'exit' or None."""
    t=pygame.time.get_ticks()/1000.0
    OTS["t"]+=dt
    if _cur_music=="other_file":                     # the song ended or something stopped it: start it again
        try:
            if not pygame.mixer.music.get_busy(): _other_music_file()
        except Exception: pass
    if OTS.get("want") and OTS["want"] in globals().get("MUSIC2",{}):      # our song is ready now
        OTS["want"]=None; globals()["_cur_music"]=None; play_music("osd")
    rnd=OTS["round"]
    if rnd is not None:
        rnd.update(dt); rnd.draw(surf,mouse,t)
        for ev in events:
            if ev.type==pygame.MOUSEBUTTONDOWN and ev.button==1:
                if rnd.result is None: rnd.click(ev.pos)
                elif rnd.result_t>0.9:
                    other_round_done(rnd)
                    OTS["round"]=None
                    OTS["screen"]="ride" if rnd.kind=="ride" else "hub"
                    o=other_data()
                    if rnd.kind=="ride" and rnd.station==RIDE_N-1 and rnd.result=="made_it" and 8 not in o["seen"]:
                        o["seen"].append(8); save_gd(gd)                       # the ending: TO BE CONTINUED
                        other_scene_start([8]); OTS["screen"]="scene"; OTS["after"]=None
                    return None
        if ui_esc(events) and rnd.result is None:
            rnd.finish({"ride":"caught","lights":"lights_out","flip":"dark"}[rnd.kind])
        return None
    sc=OTS["screen"]
    if sc=="scene":
        if draw_other_scene(surf,dt,events):
            nxt=OTS.get("after"); OTS["after"]=None
            if nxt is not None: OTS["round"]=OtherRound("ride",nxt)
            OTS["screen"]="ride"
        return None
    if sc=="intro":
        if draw_other_intro(surf,dt,events):
            o=other_data(); o["intro_seen"]=True; save_gd(gd)
            OTS["screen"]="hub"
        return None
    if sc=="hub":
        cards=draw_other_hub(surf,dt,mouse,t)
        bk=ui_back(surf,dt,mouse)
        if ui_click(events,cards["ride"]): OTS["screen"]="ride"; SND_SELECT.play()
        elif ui_click(events,cards["lights"]): OTS["round"]=OtherRound("lights"); SND_SELECT.play()
        elif ui_click(events,cards["flip"]): OTS["round"]=OtherRound("flip"); SND_SELECT.play()
        elif ui_click(events,cards["badges"]): OTS["screen"]="badges"; SND_SELECT.play()
        elif ui_click(events,cards["intro"]): other_intro_start(); OTS["screen"]="intro"; SND_SELECT.play()
        elif ui_click(events,bk) or ui_esc(events): return "exit"
    elif sc=="ride":
        hit,_bk=draw_other_ride(surf,dt,mouse,t)
        hit,bk,story_r=hit
        for rr,i,reach in hit:
            if reach and ui_click(events,rr):
                SND_SELECT.play(); o=other_data()
                if i not in o["seen"]:                                  # first time: the story scene first
                    o["seen"].append(i); save_gd(gd)
                    other_scene_start([i]); OTS["screen"]="scene"; OTS["after"]=i
                else:
                    OTS["round"]=OtherRound("ride",i)
                return None
        if story_r is not None and ui_click(events,story_r):
            SND_SELECT.play(); other_scene_start(sorted(other_data()["seen"])); OTS["screen"]="scene"; OTS["after"]=None
        elif ui_click(events,bk) or ui_esc(events): OTS["screen"]="hub"; SND_SELECT.play()
    elif sc=="badges":
        bk=draw_other_badges(surf,dt,mouse,t)
        if ui_click(events,bk) or ui_esc(events): OTS["screen"]="hub"; SND_SELECT.play()
    return None

# ── the 1986 design: the whole game as an 80s night, all year round ──────────
RETRO_PAL=[(255,70,170),(255,150,60),(255,225,90),(60,220,255),(190,90,255),(120,255,200)]
_r86_cache={}
def retro86_unlocked(): return bool(has_badge("back_home")) or dev_mode()
def retro86_theme():
    if gd.get("design")!="retro86": return False
    return retro86_unlocked()
def retro86_col(c):
    """Move any UI colour into the 1986 palette (hot pink / sunset / yellow / cyan / violet / mint)."""
    c=tuple(c[:3])
    if c in _r86_cache: return _r86_cache[c]
    import colorsys
    h,l,s=colorsys.rgb_to_hls(*(v/255 for v in c))
    if s<0.18: out=(236,214,240) if l>0.35 else (52,34,72)
    else:
        hd=h*360
        out=(RETRO_PAL[0] if hd<18 or hd>=300 else RETRO_PAL[1] if hd<45 else RETRO_PAL[2] if hd<70 else
             RETRO_PAL[5] if hd<165 else RETRO_PAL[3] if hd<235 else RETRO_PAL[4])
    _r86_cache[c]=out; return out

_r86_bg={}
def _r86_backdrop(W,H):
    """Sunset, a striped sun, mountains and a neon grid floor. Cached."""
    k=(W,H)
    if k in _r86_bg: return _r86_bg[k]
    bg=pygame.Surface((W,H)); m=min(W,H); HOR=int(H*0.58)
    for y in range(0,HOR,3):
        q=y/float(HOR)
        bg.fill(_mix((14,6,40),(120,30,90),q**1.4) if q<0.85 else _mix((120,30,90),(255,110,90),(q-0.85)/0.15),(0,y,W,3))
    rnd=random.Random(86)
    for i in range(90):
        x,y=rnd.randrange(W),rnd.randrange(int(HOR*0.6)); a=rnd.randint(80,220)
        pygame.draw.circle(bg,(a,a,min(255,a+30)),(x,y),1)
    R=int(m*0.20); cx,cy=W//2,HOR-int(R*0.35)
    sun=pygame.Surface((R*2,R*2),pygame.SRCALPHA)
    for y in range(R*2):
        q=y/float(R*2)
        col=_mix((255,230,90),(255,60,150),q)
        dx=int(math.sqrt(max(0,R*R-(y-R)**2)))
        if q>0.5 and int((q-0.5)*26)%2==1: continue        # the stripes
        pygame.draw.line(sun,col,(R-dx,y),(R+dx,y))
    bg.blit(sun,(cx-R,cy-R))
    for side,col in ((-1,(40,14,60)),(1,(30,10,50))):
        pts=[(W//2+side*int(W*0.08),HOR)]
        for j in range(7):
            pts.append((W//2+side*int(W*(0.12+j*0.065)),HOR-int(H*(0.05+0.10*abs(math.sin(j*1.9+side))))))
        pts.append((W//2+side*W,HOR)); pygame.draw.polygon(bg,col,pts)
    pygame.draw.rect(bg,(10,4,24),(0,HOR,W,H-HOR))
    pygame.draw.line(bg,(255,110,200),(0,HOR),(W,HOR),2)
    _r86_bg.clear(); _r86_bg[k]=bg; return bg

def draw_retro86_menu_bg(surf, t, accent=None):
    W,H=surf.get_size(); m=min(W,H); HOR=int(H*0.58)
    surf.blit(_r86_backdrop(W,H),(0,0))
    sp=(t*0.35)%1.0                                           # the grid floor moves toward you
    for i in range(14):
        q=((i+sp)/14.0)**2.2; y=int(HOR+(H-HOR)*q)
        pygame.draw.line(surf,_mix((90,20,110),(255,80,200),q),(0,y),(W,y),1)
    for i in range(-12,13):
        pygame.draw.line(surf,(150,40,170),(W//2+i*int(W*0.035),HOR),(W//2+i*int(W*0.20),H),1)
    if accent:
        surf.blit(_glow(int(m*0.36),retro86_col(accent),26),(W//2-int(m*0.36),int(H*0.5)-int(m*0.36)))
    sl=pygame.Surface((W,H),pygame.SRCALPHA)                  # scanlines
    for y in range(0,H,4): pygame.draw.line(sl,(0,0,0,40),(0,y),(W,y))
    surf.blit(sl,(0,0))

def draw_retro86_title(surf, t, y, scale=1.0):
    W,H=surf.get_size(); m=min(W,H)
    f1=ui_font(m*0.15*scale)
    word="COLOR"; letters=[]
    for i,ch in enumerate(word):
        k=i/4.0; letters.append((ch,_mix((255,230,90),(255,60,160),k)))
    surfs=[f1.render(ch,True,c) for ch,c in letters]
    tw=sum(s.get_width() for s in surfs)+6*4; x=W//2-tw//2
    for i,s in enumerate(surfs):
        dy=int(math.sin(t*2.0+i*0.7)*3*scale)
        sh=f1.render(word[i],True,(60,220,255)); sh.set_alpha(160); surf.blit(sh,(x+4,y+dy+4))
        surf.blit(s,(x,y+dy)); x+=s.get_width()+6
    f2=ui_font(m*0.075*scale); y2=y+int(m*0.12*scale)
    for off,c,a in ((-3,(255,70,170),170),(3,(60,220,255),170)):
        g=f2.render("UNDER PRESSURE",True,c); g.set_alpha(a); surf.blit(g,g.get_rect(centerx=W//2+off,y=y2))
    u=f2.render("UNDER PRESSURE",True,(255,240,250)); surf.blit(u,u.get_rect(centerx=W//2,y=y2))
    f3=ui_font(m*0.03*scale); st=f3.render("·  1 9 8 6  ·",True,(255,170,210))
    r=st.get_rect(centerx=W//2,y=y2+u.get_height()+6); surf.blit(st,r)
    return r.bottom


