def draw_flames(surf, rect, t, k=1.0, seed=0):
    """A sheet of fire drawn inside rect. k = 0..1 how strong it burns."""
    if k <= 0.01: return
    x0,y0,w,h = rect
    lay=pygame.Surface((w,h),pygame.SRCALPHA)
    cols=[(255,238,170),(255,186,46),(255,108,18),(186,32,10)]
    for li,col in enumerate(cols):
        amp=h*(0.72-0.14*li)*k; step=max(6,w//22)
        pts=[(0,h),(w,h)]
        row=[]
        for x in range(0,w+step,step):
            f=(math.sin(t*(4.4+li*1.1)+x*0.055+seed)*0.5+0.5)
            f*=(math.sin(t*(2.1+li*0.7)+x*0.021+seed*2)*0.35+0.65)
            row.append((x,h-amp*(0.35+0.65*f)))
        pts=row+[(w,h),(0,h)]
        pygame.draw.polygon(lay,(*col,int(228-li*18)),pts)
    for e in range(int(7*k)):                                  # embers lifting off
        ex=int((math.sin(t*1.7+e*2.3+seed)*0.5+0.5)*w)
        ey=int(h*(1.0-((t*0.55+e*0.17)%1.0))) - 4
        r=max(1,int(h*0.035))
        pygame.draw.circle(lay,(255,200,90,190),(ex,ey),r)
    surf.blit(lay,(x0,y0),special_flags=pygame.BLEND_RGBA_ADD if k<0.35 else 0)

