    W,H=surf.get_size(); h=haunt_data()
    surf.blit(haunt_background(W,H),(0,0)); draw_moon(surf,int(W*0.12),int(H*0.12),int(min(W,H)*0.05))
    for i in range(3): draw_bat(surf,(t*70+i*300)%(W+100)-50,int(H*0.06)+i*22,11,t+i)
    top=draw_header(surf,"THE HAUNT","Oct 25 – Nov 14  •  Halloween event",H_ORANGE,t); _candy_chip(surf,t)
    gp=int(W*0.025); ch=max(150,H-90-top-10)
    mr=pygame.Rect(int(W*0.05),top+10,int(W*0.42),ch)
    rw=int(W*0.9)-mr.w-gp; cw=(rw-gp)//2; chh=(ch-gp)//2; rx=mr.right+gp
    sr=pygame.Rect(rx,top+10,cw,chh); br=pygame.Rect(rx+cw+gp,top+10,cw,chh); qr=pygame.Rect(rx,top+10+chh+gp,rw,ch-chh-gp)
    cleared=sum(1 for r in h["rooms"] if r==2); got=sum(1 for b in HAUNT_BADGES if has_badge(b))
    ui_card(surf,"hh_mansion",mr,(210,90,30),"door","THE MANSION","21 rooms  •  Trick or Treat",t,dt,mouse,tag="ENTER",extra=f"Rooms cleared: {cleared}/{HAUNT_ROOMS}",big=True)
    ui_card(surf,"hh_shop",sr,(255,150,40),"gift","HALLOWEEN SHOP","Spend your candy",t,dt,mouse,extra=f"{h['candy']} candy")
    ui_card(surf,"hh_badges",br,(160,70,225),"crown","BADGES","Halloween badges",t,dt,mouse,extra=f"{got}/{len(HAUNT_BADGES)} unlocked")
    ui_card(surf,"hh_quests",qr,(120,220,40),"eye","THE GHOST'S QUESTS","5 quests  •  big rewards",t,dt,mouse,extra=f"{haunt_quests_done()}/5 done")
    draw_ghost(surf,qr.right-40,qr.y+30+int(math.sin(t*2)*6),20,t)
    rl=ui_pill(surf,"hh_rules",pygame.Rect(W-250,H-62,230,42),"HALLOWEEN RULES",(120,220,40),dt,mouse,"book")
    return {"mansion":mr,"shop":sr,"badges":br,"quests":qr,"rules":rl}

