    rewards=["Badge: Trick or Treater","Badge: Sugar Rush","Badge: Sugar Attack  +  THE SHADOW's door appears",
             "Badge: Shadow Seeker","Badge: Shadow Slammer  +  50 candy"]
    pnl=pygame.Rect(int(W*0.3),top+4,int(W*0.66),H-90-top-4); y=ui_panel(surf,pnl,None,(120,220,40))+6
    rowh=(pnl.h-90)//5
