        surf.blit(render_fit(ui_font(m*0.034),txt,(120,230,140) if done else WHITE,pnl.w-200),(pnl.x+56,ry+4))
        surf.blit(render_fit(ui_font(m*0.024),rewards[i],(255,200,120),pnl.w-80),(pnl.x+56,ry+8+int(m*0.036)))
