SND_THUNDER = _h_noise(1.6,0.55,70,28,0.9)

def _rs_rect(s, col, r, br=0): pygame.draw.rect(s,col,r,border_radius=br)
def _rs_candle(s, x, y, h=26):
    pygame.draw.rect(s,(232,222,196),(x-5,y-h,10,h),border_radius=2); pygame.draw.rect(s,(200,190,165),(x-5,y-h,10,4),border_radius=2)
def _rs_frame(s, r, inner=(40,30,50), gold=(150,110,50)):
    pygame.draw.rect(s,gold,r); pygame.draw.rect(s,inner,r.inflate(-12,-12))
def _rs_window(s, r):
    pygame.draw.rect(s,(16,20,44),r); pygame.draw.rect(s,(70,56,70),r,6)
    pygame.draw.line(s,(70,56,70),(r.centerx,r.y),(r.centerx,r.bottom),4); pygame.draw.line(s,(70,56,70),(r.x,r.centery),(r.right,r.centery),4)

ROOM_STYLE = [  # wall colour, floor colour, floor kind
    ((58,40,62),(70,46,30),"wood"),((52,36,30),(60,40,26),"wood"),((60,58,56),(80,76,70),"tile"),((60,30,70),(20,20,26),"check"),
    ((80,62,80),(90,70,50),"wood"),((70,30,36),(60,40,26),"wood"),((40,36,60),(50,34,24),"wood"),((24,50,40),(60,64,52),"tile"),
    ((50,40,34),(62,44,30),"wood"),((60,50,70),(60,44,30),"wood"),((60,80,90),(170,180,190),"tile"),((44,40,56),(60,56,60),"stone"),
    ((60,30,50),(64,44,30),"wood"),((46,40,30),(56,40,26),"wood"),((40,46,60),(30,30,40),"check"),((36,50,46),(70,74,76),"tile"),
    ((44,36,32),(46,40,36),"stone"),((54,42,34),(70,52,34),"wood"),((30,30,36),(40,38,40),"stone"),((36,34,44),(48,46,52),"stone"),
    ((78,26,14),(52,22,14),"stone")]                                                 # 21: THE FIRE ROOM
_ROOM_BG = {}
_ROOM_FX = {}           # room -> list of dynamic things (candles, windows...) in 0..1 coords

def _room_scene(W, H, room):
    key=(W,H,room)
    if key in _ROOM_BG: return _ROOM_BG[key]
    s=pygame.Surface((W,H)); wall,floor,fk=ROOM_STYLE[room]; fy=int(H*0.7); rnd=random.Random(100+room); fx=[]
    for y in range(fy): pygame.draw.line(s,_mix(_mix(wall,(0,0,0),0.35),wall,y/fy),(0,y),(W,y))
    for x in range(0,W,int(W*0.08)): pygame.draw.line(s,_mix(wall,(0,0,0),0.18),(x,0),(x,fy),3)        # wallpaper stripes
    pygame.draw.rect(s,floor,(0,fy,W,H-fy))
    if fk=="wood":
        for y in range(fy,H,14): pygame.draw.line(s,_mix(floor,(0,0,0),0.25),(0,y),(W,y),2)
    elif fk=="check":
        for i in range(0,W,48):
            for j in range(fy,H,24):
                if ((i//48)+(j//24))%2: pygame.draw.rect(s,(200,195,205),(i,j,48,24))
    elif fk=="tile":
        for i in range(0,W,36): pygame.draw.line(s,_mix(floor,(0,0,0),0.3),(i,fy),(i,H),1)
        for j in range(fy,H,18): pygame.draw.line(s,_mix(floor,(0,0,0),0.3),(0,j),(W,j),1)
    else:
        for i in range(30): pygame.draw.rect(s,_mix(floor,(0,0,0),rnd.uniform(0.05,0.3)),(rnd.randrange(W),rnd.randrange(fy,H),rnd.randint(30,70),rnd.randint(12,22)),border_radius=4)
    pygame.draw.rect(s,_mix(wall,(0,0,0),0.5),(0,fy-10,W,10))                                       # skirting board
    L=lambda a,b,c,d: pygame.Rect(int(W*a),int(H*b),int(W*c),int(H*d))
    if room==0:                                             # Hallway: portraits and a long carpet
        for k in range(4): _rs_frame(s,L(0.04+k*0.25,0.06,0.1,0.16)); pygame.draw.ellipse(s,(70,60,80),L(0.065+k*0.25,0.09,0.05,0.1))
        pygame.draw.polygon(s,(110,24,40),[(int(W*0.42),fy),(int(W*0.58),fy),(int(W*0.8),H),(int(W*0.2),H)])
        fx+= [("candle",0.02,0.62),("candle",0.97,0.62)]
    elif room==1:                                           # Library
        for side in (0,1):
            x0=0.0 if side==0 else 0.86
            for row in range(5):
                y=0.05+row*0.13; _rs_rect(s,(70,44,28),L(x0,y+0.1,0.14,0.02))
                for b in range(7): _rs_rect(s,[(140,40,40),(40,80,140),(60,120,60),(150,120,50),(110,60,130)][(b+row+side)%5],L(x0+0.005+b*0.019,y+0.02,0.016,0.08))
        fx+=[("float_book",0.5,0.12)]
    elif room==2:                                           # Kitchen: a cauldron and pots
        pygame.draw.ellipse(s,(30,30,34),L(0.02,0.55,0.16,0.18)); _rs_rect(s,(40,40,44),L(0.03,0.5,0.14,0.08),6)
        for k in range(4): pygame.draw.circle(s,(90,90,96),(int(W*(0.86+k%2*0.06)),int(H*(0.12+k//2*0.12))),int(H*0.035))
        fx+=[("bubbles",0.1,0.52),("fire",0.1,0.72)]
    elif room==3:                                           # Ballroom
        for k in range(5): pygame.draw.rect(s,(120,90,40),L(0.02+k*0.21,0.0,0.01,0.6))
        fx+=[("chandelier",0.5,0.03),("dancers",0.0,0.0)]
    elif room==4:                                           # Nursery
        _rs_rect(s,(150,110,170),L(0.02,0.5,0.14,0.18),8);
        for k in range(5): pygame.draw.line(s,(110,80,130),(int(W*(0.03+k*0.03)),int(H*0.5)),(int(W*(0.03+k*0.03)),int(H*0.4)),3)
        for k,c in enumerate(((230,80,80),(80,140,230),(240,200,60))): _rs_rect(s,c,L(0.86+k*0.035,0.62,0.03,0.05),3)
        fx+=[("rocking",0.92,0.5),("mobile",0.08,0.08)]
    elif room==5:                                           # Dining Hall
        _rs_rect(s,(90,50,30),L(0.0,0.62,1.0,0.06));
        for k in range(8): fx.append(("candle",0.06+k*0.125,0.62))
    elif room==6:                                           # Music Room
        _rs_rect(s,(20,18,22),L(0.0,0.42,0.17,0.24),10)
        for k in range(8): _rs_rect(s,(235,235,235),L(0.005+k*0.02,0.6,0.018,0.05),2)
        fx+=[("notes",0.1,0.4)]
    elif room==7:                                           # Greenhouse
        for i in range(0,W,int(W*0.1)): pygame.draw.line(s,(150,190,170),(i,0),(i,fy),3)
        for j in range(0,fy,int(H*0.12)): pygame.draw.line(s,(150,190,170),(0,j),(W,j),3)
        for k in range(10): pygame.draw.circle(s,(40,110,60),(rnd.randrange(W),rnd.randrange(int(H*0.5),fy)),rnd.randint(18,40))
        fx+=[("rain",0,0)]
    elif room==8:                                           # Study
        _rs_rect(s,(80,52,32),L(0.86,0.5,0.14,0.18),4); pygame.draw.circle(s,(60,110,160),(int(W*0.08),int(H*0.5)),int(H*0.06)); pygame.draw.circle(s,(80,150,90),(int(W*0.07),int(H*0.49)),int(H*0.025))
        for k in range(6): _rs_rect(s,(235,230,215),L(0.87+rnd.uniform(0,0.08),0.46+rnd.uniform(0,0.03),0.03,0.02))
        fx+=[("candle",0.95,0.5)]
    elif room==9:                                           # Gallery
        for k in range(6):
            r=L(0.01+k*0.165,0.04+(k%2)*0.06,0.12,0.18); _rs_frame(s,r,(rnd.randint(30,80),rnd.randint(30,60),rnd.randint(40,90)))
        fx+=[("eyes_frames",0,0)]
    elif room==10:                                          # Bathroom
        pygame.draw.ellipse(s,(225,225,230),L(0.0,0.52,0.18,0.14)); pygame.draw.ellipse(s,(150,190,210),L(0.015,0.54,0.15,0.08))
        _rs_frame(s,L(0.86,0.1,0.12,0.24),(160,190,200),(200,200,210))
        fx+=[("drip",0.08,0.5)]
    elif room==11:                                          # Chapel: stained glass, pews
        for k,c in enumerate(((180,40,60),(50,90,180),(200,160,40))):
            r=L(0.06+k*0.36,0.04,0.16,0.26); pygame.draw.ellipse(s,c,r); pygame.draw.ellipse(s,(30,26,30),r,6)
        for k in range(3): _rs_rect(s,(70,44,28),L(0.0,0.6+k*0.03,0.15,0.02)); _rs_rect(s,(70,44,28),L(0.85,0.6+k*0.03,0.15,0.02))
        fx+=[("lightning_glass",0,0)]
    elif room==12:                                          # Bedroom
        _rs_rect(s,(100,30,50),L(0.0,0.0,0.06,0.68)); _rs_rect(s,(100,30,50),L(0.94,0.0,0.06,0.68))
        _rs_rect(s,(140,60,80),L(0.84,0.52,0.16,0.14),8); _rs_rect(s,(230,230,235),L(0.86,0.5,0.06,0.04),6)
        fx+=[("under_bed",0.92,0.66)]
    elif room==13:                                          # Clock Room
        for k in range(5): fx.append(("clock",0.06+k*0.22,0.12))
    elif room==14:                                          # Mirror Room
        for k in range(5): _rs_frame(s,L(0.02+k*0.2,0.05,0.14,0.26),(120,140,160),(170,160,180))
        fx+=[("mirror_face",0,0)]
    elif room==15:                                          # Laboratory
        for k,c in enumerate(((80,220,120),(200,80,220),(240,200,60),(80,180,240))):
            pygame.draw.circle(s,c,(int(W*(0.03+k*0.04)),int(H*0.6)),int(H*0.025)); _rs_rect(s,c,L(0.025+k*0.04,0.52,0.012,0.06))
        _rs_rect(s,(90,90,100),L(0.88,0.3,0.03,0.38)); pygame.draw.circle(s,(120,120,140),(int(W*0.895),int(H*0.28)),int(H*0.04))
        fx+=[("tesla",0.895,0.28),("bubbles",0.07,0.55)]
    elif room==16:                                          # Cellar: barrels
        for k in range(3): pygame.draw.ellipse(s,(90,60,34),L(0.0+k*0.06,0.5,0.06,0.18)); pygame.draw.ellipse(s,(90,60,34),L(0.82+k*0.06,0.5,0.06,0.18))
        for k in range(3): pygame.draw.line(s,(50,34,20),(int(W*(0.03+k*0.06)),int(H*0.5)),(int(W*(0.03+k*0.06)),int(H*0.68)),3)
        fx+=[("bats",0,0)]
    elif room==17:                                          # Attic: beams, boxes
        for k in range(4): pygame.draw.polygon(s,(70,52,34),[(int(W*(k*0.33)),0),(int(W*(k*0.33+0.04)),0),(int(W*0.5+12),int(H*0.24)),(int(W*0.5-12),int(H*0.24))])
        for k in range(4): _rs_rect(s,(120,90,60),L(0.0+k*0.04,0.56,0.05,0.12)); _rs_rect(s,(120,90,60),L(0.82+k*0.045,0.58,0.05,0.1))
        fx+=[("cobwebs",0,0),("lightning_win",0.5,0.06)]
    elif room==18:                                          # Crypt: coffins, tombs
        for x in (0.02,0.86):
            pygame.draw.polygon(s,(60,40,30),[(int(W*x),int(H*0.68)),(int(W*(x+0.04)),int(H*0.36)),(int(W*(x+0.1)),int(H*0.36)),(int(W*(x+0.13)),int(H*0.68))])
            pygame.draw.line(s,(150,140,120),(int(W*(x+0.07)),int(H*0.42)),(int(W*(x+0.07)),int(H*0.56)),4); pygame.draw.line(s,(150,140,120),(int(W*(x+0.045)),int(H*0.46)),(int(W*(x+0.095)),int(H*0.46)),4)
        fx+=[("fog",0,0)]
    elif room==19:                                          # Tower: stone and a storm window
        for i in range(0,W,40):
            for j in range(0,fy,22): pygame.draw.rect(s,_mix(wall,(0,0,0),rnd.uniform(0,0.3)),(i+(j//22%2)*20,j,38,20),1)
        fx+=[("lightning_win",0.5,0.06),("lightning_win",0.06,0.2),("lightning_win",0.94,0.2)]
    else:                                                   # 21: THE FIRE ROOM — scorched stone, braziers, cracks of lava
        for i in range(0,W,44):
            for j in range(0,fy,24):
                pygame.draw.rect(s,_mix(wall,(0,0,0),rnd.uniform(0.1,0.45)),(i+(j//24%2)*22,j,42,22),1)
        for k in range(9):                                  # glowing cracks in the floor
            x0=rnd.randrange(W); y0=rnd.randrange(fy,H); pts=[(x0,y0)]
            for j in range(5): pts.append((pts[-1][0]+rnd.randint(-40,40),pts[-1][1]+rnd.randint(6,22)))
            pygame.draw.lines(s,(255,110,30),False,pts,rnd.randint(2,4))
            pygame.draw.lines(s,(255,210,110),False,pts,1)
        for x in (0.04,0.88):                               # iron braziers on both walls
            _rs_rect(s,(40,34,34),L(x,0.52,0.08,0.05)); _rs_rect(s,(28,24,24),L(x+0.03,0.57,0.02,0.12))
            _rs_rect(s,(40,34,34),L(x+0.005,0.69,0.07,0.02))
        _rs_rect(s,(26,16,14),L(0.40,0.30,0.20,0.26))       # the big furnace mouth
        pygame.draw.rect(s,(120,40,16),L(0.42,0.33,0.16,0.20),6)
        fx+=[("fire",0.08,0.54),("fire",0.92,0.54),("fire",0.50,0.56),("embers",0.5,0.5)]
    for k in range(2):
        if room not in (10,7): draw_cobweb(s,0 if k==0 else W,0,int(H*0.14),flip=bool(k),alpha=60)
    _ROOM_FX[room]=fx; _ROOM_BG[key]=s; return s

def _room_fx(surf, room, t, W, H):
    for kind,a,b in _ROOM_FX.get(room,[]):
        x,y=int(a*W),int(b*H)
        if kind=="candle":
            _rs_candle(surf,x,y); fl=6+2*math.sin(t*11+a*30)
            pygame.draw.ellipse(surf,(255,200,80),(x-4,y-26-fl*2,8,fl*2)); surf.blit(_glow(30,(255,170,60),int(45+20*math.sin(t*9+a*10))),(x-30,y-50))
        elif kind=="fire":
            for k in range(6):
                fh=int(H*0.03*(0.6+0.5*abs(math.sin(t*9+k)))); pygame.draw.ellipse(surf,(255,120+k*20,30),(x-30+k*10,y-fh,14,fh))
            surf.blit(_glow(60,(255,130,40),60),(x-60,y-80))
        elif kind=="embers":
            for k in range(16):
                ex=int(W*((k*0.0617+t*0.035)%1.0)); ey=int(H*(1.0-((t*0.11+k*0.0625)%1.0))*0.92)
                r=2+(k%3); a=int(150*(ey/float(H)))
                pygame.draw.circle(surf,(255,min(255,150+k*6),60),(ex,ey),r)
            surf.blit(_glow(int(H*0.42),(255,90,20),46),(W//2-int(H*0.42),int(H*0.62)-int(H*0.42)))
        elif kind=="bubbles":
            for k in range(8):
                by=y-int(((t*50+k*23)%60)); pygame.draw.circle(surf,(120,240,140),(x-30+k*8+int(math.sin(t*3+k)*3),by),4,1)
        elif kind=="chandelier":
            sw=math.sin(t*0.9)*0.03; cx_=int(W*(0.5+sw)); pygame.draw.line(surf,(150,120,60),(W//2,0),(cx_,int(H*0.06)),3)
            pygame.draw.ellipse(surf,(170,130,60),(cx_-int(W*0.08),int(H*0.06),int(W*0.16),int(H*0.03)),3)
            for k in range(6):
                px=cx_-int(W*0.07)+k*int(W*0.028); pygame.draw.ellipse(surf,(255,210,90),(px-3,int(H*0.05),6,10)); surf.blit(_glow(22,(255,200,90),50),(px-22,int(H*0.05)-22))
        elif kind=="dancers":
            for k in range(3):
                px=int(W*0.5+math.cos(t*0.8+k*2.1)*W*0.45); py=int(H*0.6+math.sin(t*1.6+k)*H*0.03)
                if px<W*0.14 or px>W*0.86: draw_ghost(surf,px,py,int(H*0.05),t+k,110)
        elif kind=="rocking":
            ang=math.sin(t*1.8)*12; hs=pygame.Surface((90,70),pygame.SRCALPHA)
            pygame.draw.ellipse(hs,(150,90,50),(10,20,60,26)); pygame.draw.circle(hs,(150,90,50),(70,18),14); pygame.draw.arc(hs,(110,60,30),(0,40,90,40),0.2,2.9,5)
            hs=pygame.transform.rotate(hs,ang); surf.blit(hs,hs.get_rect(center=(x,y)))
        elif kind=="mobile":
            for k in range(4):
                px=x+int(math.cos(t*0.7+k*1.57)*40); pygame.draw.line(surf,(180,170,190),(x,y),(px,y+40),1); pygame.draw.circle(surf,[(240,200,60),(120,200,240),(240,120,150),(150,230,150)][k],(px,y+46),7)
        elif kind=="notes":
            for k in range(5):
                u=(t*0.4+k*0.2)%1; px=x+int(u*W*0.06)+int(math.sin(t*2+k)*12); py=y-int(u*H*0.35)
                nc=(int(230*(1-u)),int(220*(1-u)),int(240*(1-u)))
                pygame.draw.ellipse(surf,nc,(px,py+14,12,9)); pygame.draw.line(surf,nc,(px+11,py+18),(px+11,py),2); pygame.draw.line(surf,nc,(px+11,py),(px+19,py+5),3)
        elif kind=="rain":
            for k in range(60):
                px=(k*97+int(t*40))%W; py=(k*53+int(t*500))%int(H*0.7); pygame.draw.line(surf,(150,190,220),(px,py),(px-2,py+10),1)
        elif kind=="float_book":
            for k in range(2):
                px=int(W*(0.2+k*0.6)+math.sin(t*0.9+k)*30); py=int(H*0.14+math.sin(t*1.4+k*2)*14)
                pygame.draw.polygon(surf,(150,40,40),[(px-22,py),(px,py-8+int(math.sin(t*6)*4)),(px+22,py),(px,py+6)])
        elif kind=="eyes_frames":
            for k in range(6):
                if int(t*0.7+k*1.9)%5: continue
                ex=int(W*(0.07+k*0.165)); ey=int(H*(0.12+(k%2)*0.06))
                for o in (-8,8): pygame.draw.circle(surf,(255,40,40),(ex+o,ey),4)
        elif kind=="drip":
            u=(t*0.8)%1; pygame.draw.circle(surf,(140,190,230),(x,y+int(u*H*0.12)),3)
        elif kind=="under_bed":
            if int(t*0.5)%3==0:
                for o in (-10,10): pygame.draw.ellipse(surf,(255,220,60),(x+o-5,y-4,10,6))
        elif kind=="clock":
            r=int(H*0.06); pygame.draw.circle(surf,(170,130,60),(x,y),r+5); pygame.draw.circle(surf,(235,228,205),(x,y),r)
            sp=(1 if int(a*10)%2 else -1)*(1.5+a*3)
            for ln,an in ((0.7,t*sp),(0.5,t*sp/12)): pygame.draw.line(surf,(30,20,20),(x,y),(x+int(math.cos(an)*r*ln),y+int(math.sin(an)*r*ln)),3)
            pl=math.sin(t*3+a*9)*0.4; pygame.draw.line(surf,(150,120,60),(x,y+r),(x+int(math.sin(pl)*r*1.6),y+r+int(math.cos(pl)*r*1.6)),3)
        elif kind=="mirror_face":
            k=int(t*0.6)%5
            if math.sin(t*0.6*6.28)>0.6:
                draw_ghost(surf,int(W*(0.09+k*0.2)),int(H*0.17),int(H*0.06),t,110,(150,0,0))
        elif kind=="tesla":
            if int(t*6)%4==0:
                pts=[(x,y)]
                for k in range(5): pts.append((pts[-1][0]+random.randint(-24,10),pts[-1][1]+random.randint(10,22)))
                pygame.draw.lines(surf,(180,220,255),False,pts,2); surf.blit(_glow(40,(140,200,255),70),(x-40,y-40))
        elif kind=="bats":
            for k in range(3): draw_bat(surf,(t*120+k*300)%(W+120)-60,H*0.1+math.sin(t*3+k)*30+k*40,14,t+k,(14,8,18))
        elif kind=="cobwebs":
            for k in range(3):
                sx=int(W*(0.2+k*0.3)); sl=int(H*0.08+math.sin(t*1.2+k)*H*0.04)
                pygame.draw.line(surf,(200,200,210),(sx,0),(sx,sl),1); pygame.draw.circle(surf,(20,16,20),(sx,sl),6)
                for o in (-1,1):
                    for j in range(3): pygame.draw.line(surf,(20,16,20),(sx,sl),(sx+o*10,sl-4+j*4),1)
        elif kind in ("lightning_win","lightning_glass"):
            flash=(t%7.0)<0.12 or 0.2<(t%7.0)<0.26
            if kind=="lightning_win":
                r=pygame.Rect(0,0,int(W*0.1),int(H*0.16)); r.midtop=(x,y); _rs_window(surf,r)
                if flash: pygame.draw.rect(surf,(220,230,255),r.inflate(-12,-12))
            if flash:
                o=pygame.Surface((W,H),pygame.SRCALPHA); o.fill((200,210,255,40)); surf.blit(o,(0,0))
        elif kind=="fog":
            f=pygame.Surface((W,int(H*0.2)),pygame.SRCALPHA)
            for k in range(6): pygame.draw.ellipse(f,(170,170,190,26),(int((t*25+k*W*0.25)%(W+300))-300,int(H*0.04),340,int(H*0.12)))
            surf.blit(f,(0,int(H*0.6)))

def room_backdrop(surf, rnd, t):
    """The room behind the board (rooms only). THE SHADOW / Halloween Mode keep the night sky."""
    W,H=surf.get_size()
    if getattr(rnd,"kind",None)!="room":
        surf.blit(haunt_background(W,H),(0,0)); return
    surf.blit(_room_scene(W,H,rnd.room),(0,0)); _room_fx(surf,rnd.room,t,W,H)
    o=pygame.Surface((W,H),pygame.SRCALPHA); o.fill((8,2,14,70)); surf.blit(o,(0,0))
    b=pygame.Surface((int(W*0.8),int(H*0.62)),pygame.SRCALPHA); pygame.draw.rect(b,(6,2,10,90),b.get_rect(),border_radius=30); surf.blit(b,(int(W*0.1),int(H*0.31)))
    draw_host(surf,ROOM_HOSTS[rnd.room],int(W*0.055),int(H*0.86)+int(math.sin(t*2)*3),int(min(W,H)*0.03),t)

# ── TREAT / TRICK / scares ───────────────────────────────────────────────────
def _outlined(text, size, col, out=(20,8,24), w=4):
    f=ui_font(size); base=f.render(text,True,col); o=f.render(text,True,out)
    s=pygame.Surface((base.get_width()+w*2,base.get_height()+w*2),pygame.SRCALPHA)
    for dx in (-w,0,w):
        for dy in (-w,0,w):
            if dx or dy: s.blit(o,(w+dx,w+dy))
    s.blit(base,(w,w)); return s

def _jump_scare(surf, kind, e, t):
    """1.5 s: lights flicker... then it rushes at you."""
    W,H=surf.get_size(); m=min(W,H); surf.fill((0,0,0))
    if e<0.35:                                                         # the lights go out, two eyes in the dark
        if int(e*30)%3==0: surf.fill((30,10,20))
        for o in (-0.05,0.05): pygame.draw.ellipse(surf,(255,40,40),(W//2+int(o*W)-10,int(H*0.45),20,10))
        return
    u=min(1.0,(e-0.35)/0.6); z=0.15+u**2.2*1.9
    jx=random.randint(-int(18*u),int(18*u)); jy=random.randint(-int(14*u),int(14*u))
    draw_host(surf,kind,W//2+jx,int(H*(0.48-0.18*u))+jy,int(m*0.12*z),t)
    for o in (-0.1,0.1): surf.blit(_glow(int(m*0.08*z),(255,0,0),120),(W//2+int(o*m*z)-int(m*0.08*z),int(H*0.4)-int(m*0.08*z)))
    if int(e*24)%2==0: o_=pygame.Surface((W,H),pygame.SRCALPHA); o_.fill((255,0,0,70)); surf.blit(o_,(0,0))
    if u>0.5:                                                          # torn picture
        snap=surf.copy()
        for _ in range(6):
            y=random.randrange(0,H-30); h=random.randrange(6,40); surf.blit(snap,(random.randint(-40,40),y),area=pygame.Rect(0,y,W,h))
    for _ in range(int(120*u)):
        x=random.randrange(W); y=random.randrange(H); c=random.randint(80,255); surf.fill((c,c,c),(x,y,2,2))

def _cracks(surf, k, seed=7):
    W,H=surf.get_size(); r=random.Random(seed); cx,cy=W//2,int(H*0.45)
    for i in range(11):
        a=i/11*6.283+r.uniform(-0.2,0.2); x,y=cx,cy; pts=[(x,y)]
        for j in range(6): x+=math.cos(a)*W*0.06*k+r.uniform(-14,14); y+=math.sin(a)*H*0.06*k+r.uniform(-14,14); pts.append((x,y))
        pygame.draw.lines(surf,(235,235,245),False,pts,2)

def draw_room_result(surf, t, rnd, mouse, dt):
    W,H=surf.get_size(); m=min(W,H); res=rnd.result; e=rnd.result_t
    host=ROOM_HOSTS[rnd.room] if getattr(rnd,"kind","")=="room" else "ghost"
    if res=="trick" and e>=0.35 and not getattr(rnd,"_scream",False):
        rnd._scream=True; SND_SCREAM.play(); start_shake(18,40)
    if res=="trick" and e<1.5: _jump_scare(surf,host,e,t); return None,None
    if getattr(rnd,"kind","")=="room": surf.blit(_room_scene(W,H,rnd.room),(0,0)); _room_fx(surf,rnd.room,t,W,H)
    else: surf.blit(haunt_background(W,H),(0,0))
    h=haunt_data(); big={"treat":"TREAT!","trick":"TRICK!","closed":"DOOR SLAMMED!","escaped":"HE GOT OUT...","over":"GAME OVER"}[res]
    if res=="treat":
        o=pygame.Surface((W,H),pygame.SRCALPHA); o.fill((30,10,40,150)); surf.blit(o,(0,0))
        surf.blit(_glow(int(m*0.45),(255,160,40),int(70+20*math.sin(t*3))),(W//2-int(m*0.45),int(H*0.5)-int(m*0.45)))
        bx,by=W//2,int(H*0.62)                                        # the jack-o-lantern bucket
        pygame.draw.ellipse(surf,(10,4,14),(bx-int(m*0.13),by+int(m*0.11),int(m*0.26),int(m*0.04)))
        ui_icon2(surf,"pumpkin",bx,by,int(m*0.12),H_ORANGE,t)
        pygame.draw.arc(surf,(60,40,30),(bx-int(m*0.1),by-int(m*0.2),int(m*0.2),int(m*0.2)),0.3,2.85,4)
        hx,hy=int(W*0.2),int(H*0.5); draw_host(surf,host,hx,hy+int(math.sin(t*3)*6),int(m*0.06),t)
        for i in range(10):                                           # candy flies from the host into the bucket
            u=((e*1.1)-i*0.09)
            if 0<u<1:
                px=hx+(bx-hx)*u; py=hy-int(m*0.1)+(by-hy)*u-math.sin(u*math.pi)*m*0.25
                draw_candy(surf,px,py,9,list(H_COL.values())[i%6],t*6+i)
        for i in range(36):                                           # candy rain
            x=(i*97+int(t*40))%W; y=(i*61+int(t*170+i*40))%(H+40)-20; draw_candy(surf,x,y,8,list(H_COL.values())[i%6],t+i)
        sc=min(1.0,e/0.35); sc=1+0.35*(1-sc)*math.sin(sc*9)                # elastic pop
        ts=_outlined(big,m*0.15,(255,200,80)); ts=pygame.transform.rotozoom(ts,math.sin(t*3)*3,sc*(1+0.03*math.sin(t*6)))
        surf.blit(ts,ts.get_rect(center=(W//2,int(H*0.22))))
        nm=f"ROOM {rnd.room+1}  •  {ROOM_NAMES[rnd.room].upper()}"; ns=ui_font(m*0.034).render(nm,True,(255,230,190)); surf.blit(ns,ns.get_rect(center=(W//2,int(H*0.34))))
        cnt=min(HAUNT_TREAT_CANDY,int(e*14)); cs=_outlined(f"+{cnt} candy",m*0.06,(255,230,120)); surf.blit(cs,cs.get_rect(center=(W//2+int(m*0.25),int(H*0.55)-int(min(1,e)*20))))
        done=sum(1 for r in h["rooms"] if r==2); bw=int(W*0.4); bar=pygame.Rect(W//2-bw//2,int(H*0.78),bw,16)
        pygame.draw.rect(surf,(30,16,40),bar,border_radius=8); pygame.draw.rect(surf,(255,170,50),(bar.x,bar.y,int(bw*done/HAUNT_ROOMS),16),border_radius=8)
        ps=ui_font(m*0.028).render(f"Rooms with a TREAT: {done} / {HAUNT_ROOMS}",True,(230,210,240)); surf.blit(ps,ps.get_rect(center=(W//2,bar.bottom+16)))
    elif res=="trick":
        u=e-1.5; o=pygame.Surface((W,H),pygame.SRCALPHA); o.fill((60,0,10,170)); surf.blit(o,(0,0))
        fx_=int(W*0.3+u*W*0.35); fy_=int(H*0.55-u*H*0.3)                   # the host flies away with your candy
        draw_host(surf,host,fx_,fy_+int(math.sin(t*8)*6),int(m*0.06),t)
        pygame.draw.circle(surf,(150,110,70),(fx_+int(m*0.08),fy_+int(m*0.12)),int(m*0.04))
        for i in range(8):
            cy_=fy_+int(m*0.15)+int(((u*300)+i*40)%(H*0.5)); draw_candy(surf,fx_+int(m*0.08)+int(math.sin(i)*30),cy_,7,list(H_COL.values())[i%6],t+i)
        if u<3:
            hh=_outlined("HE HE HE!",m*0.04,(255,220,230)); hh.set_alpha(int(255*max(0,1-u/3))); surf.blit(hh,(fx_+int(m*0.1),fy_-int(m*0.12)))
        ts=_outlined(big,m*0.15,(110,230,90),(20,40,10)); r=ts.get_rect(center=(W//2,int(H*0.24))); surf.blit(ts,r)
        for i in range(9):                                               # slime drips
            dx=r.x+int(r.w*(0.08+i*0.105)); dl=int((math.sin(i*1.7)*0.5+0.5)*m*0.05+min(1,u)*m*0.04+math.sin(t*2+i)*4)
            pygame.draw.line(surf,(110,230,90),(dx,r.bottom-12),(dx,r.bottom-12+dl),6); pygame.draw.circle(surf,(110,230,90),(dx,r.bottom-12+dl),5)
        if u<0.6: _cracks(surf,min(1,u*4))
    else:
        o=pygame.Surface((W,H),pygame.SRCALPHA); o.fill((10,4,18,120)); surf.blit(o,(0,0))
        if res in ("closed","over"):
            for i in range(30):
                x=(i*97+int(t*40))%W; y=(i*61+int(t*160+i*40))%(H+40)-20; draw_candy(surf,x,y,9,list(H_COL.values())[i%6],t+i)
        col={"closed":(120,230,140),"escaped":(200,80,80),"over":(255,150,60)}[res]
        ts=pygame.transform.rotozoom(_outlined(big,m*0.12,col),0,1+0.04*math.sin(t*5)); surf.blit(ts,ts.get_rect(center=(W//2,int(H*0.26))))
    lines=getattr(rnd,"lines",[])
    y0=int(H*0.42) if res!="treat" else int(H*0.88)
    if res=="treat": lines=[l for l in lines if not l.startswith("+")]
    for i,l in enumerate(lines):
        ls=_outlined(l,m*0.036,WHITE,(10,4,14),2); surf.blit(ls,ls.get_rect(center=(W//2,y0+i*int(H*0.065))))
    b1=b2=None
    if res=="trick" and e<2.0: return None,None                       # let the scare land before the buttons show
    if res in ("trick","escaped","over"): b2=_h_btn(surf,"h_again",pygame.Rect(W//2+10,H-90,240,50),"TRY AGAIN",H_ORANGE,dt,mouse)
    b1=_h_btn(surf,"h_backm",pygame.Rect(W//2-250 if b2 else W//2-120,H-90,240,50),"BACK",(110,70,150),dt,mouse,"back")
    return b1,b2

# ── a living mansion ─────────────────────────────────────────────────────────
_hm_static_map_base=_hm_static_map
HM_DECOR=[]          # (kind, x, y) on wall tiles that face a floor below
HM_FIREPLACE=(8,17); HM_CHANDELIER=(17.5,17.6)
def _hm_static_map():
    if "map2" in _hm_static: return _hm_static["map2"]
    s=_hm_static_map_base().copy(); T=HM_T; rnd=random.Random(13)
    portraits={(5,4),(10,4),(25,4),(30,4),(5,13),(29,13),(14,10),(21,10)}
    HM_DECOR.clear()
    for y in range(HM_H-1):
        for x in range(HM_W):
            if HM_GRID[y][x]!="#" or (x,y) in portraits or HM_GRID[y+1][x] in HM_SOLID: continue
            if rnd.random()<0.45: HM_DECOR.append((rnd.choice(("shelf","clock","armor","window","banner","shelf")),x,y))
    for kind,x,y in HM_DECOR:
        r=pygame.Rect(x*T,y*T,T,T)
        if kind=="shelf":
            pygame.draw.rect(s,(70,44,28),r.inflate(-6,-4))
            for row in range(3):
                for b in range(5): pygame.draw.rect(s,[(140,40,40),(40,80,140),(60,120,60),(150,120,50),(110,60,130)][(b+row+x)%5],(r.x+6+b*7,r.y+6+row*13,6,11))
        elif kind=="clock":
            pygame.draw.rect(s,(80,50,30),(r.centerx-9,r.y+2,18,T-4),border_radius=4); pygame.draw.circle(s,(230,220,190),(r.centerx,r.y+14),7)
        elif kind=="armor":
            pygame.draw.rect(s,(150,150,160),(r.centerx-7,r.y+16,14,24),border_radius=4); pygame.draw.circle(s,(170,170,180),(r.centerx,r.y+11),8)
            pygame.draw.line(s,(30,30,30),(r.centerx-4,r.y+11),(r.centerx+4,r.y+11),2); pygame.draw.line(s,(120,120,130),(r.right-8,r.y+4),(r.right-8,r.bottom-2),3)
        elif kind=="window":
            pygame.draw.rect(s,(14,18,40),r.inflate(-10,-12)); pygame.draw.rect(s,(80,64,80),r.inflate(-10,-12),3); pygame.draw.line(s,(80,64,80),(r.centerx,r.y+6),(r.centerx,r.bottom-6),2)
        else:
            pygame.draw.polygon(s,(120,24,40),[(r.x+10,r.y+4),(r.right-10,r.y+4),(r.right-10,r.bottom-4),(r.centerx,r.bottom-12),(r.x+10,r.bottom-4)])
            ui_icon2(s,"pumpkin",r.centerx,r.y+18,7,(230,170,60))
    for y in range(1,HM_H-1):                                           # cobwebs in the corners
        for x in range(1,HM_W-1):
            if HM_GRID[y][x] in HM_SOLID: continue
            up=HM_GRID[y-1][x] in HM_SOLID
            if up and HM_GRID[y][x-1]=="#" and rnd.random()<0.7: draw_cobweb(s,x*T,y*T,22,False,70)
            if up and HM_GRID[y][x+1]=="#" and rnd.random()<0.7: draw_cobweb(s,x*T+T,y*T,22,True,70)
            if HM_GRID[y][x] in ".~" and rnd.random()<0.06:            # things on the floor
                k=rnd.random(); cx_,cy_=x*T+rnd.randint(10,T-10),y*T+rnd.randint(10,T-10)
                if k<0.3: pygame.draw.line(s,(220,215,200),(cx_-8,cy_),(cx_+8,cy_+3),4); pygame.draw.circle(s,(220,215,200),(cx_-8,cy_),4); pygame.draw.circle(s,(220,215,200),(cx_+8,cy_+3),4)
                elif k<0.6: pygame.draw.rect(s,(120,40,40),(cx_-7,cy_-5,14,10)); pygame.draw.line(s,(230,220,200),(cx_-5,cy_),(cx_+5,cy_),1)
                else:
                    for j in range(3): pygame.draw.line(s,(30,20,14),(cx_,cy_),(cx_+rnd.randint(-14,14),cy_+rnd.randint(-14,14)),1)
    c=(int(HM_CHANDELIER[0]*T),int(HM_CHANDELIER[1]*T)); rr=int(T*2.3)       # the big round rug in the lobby
    pygame.draw.circle(s,(110,26,40),c,rr); pygame.draw.circle(s,(170,120,50),c,rr,4); pygame.draw.circle(s,(170,120,50),c,int(rr*0.7),2)
    for k in range(12): a=k/12*6.283; pygame.draw.circle(s,(170,120,50),(c[0]+int(math.cos(a)*rr*0.85),c[1]+int(math.sin(a)*rr*0.85)),4)
    fr=pygame.Rect(HM_FIREPLACE[0]*T+6,HM_FIREPLACE[1]*T-T//2,T-6,T*2)        # fireplace on the lobby's west wall
    pygame.draw.rect(s,(90,80,80),fr,border_radius=4); pygame.draw.rect(s,(20,10,10),fr.inflate(-14,-24).move(4,0))
    _hm_static["map2"]=s; return s

HM_FX={"t_light":5.0,"flash":0.0,"rats":[],"spiders":[],"steps":[],"last_step":0.0}
def _hm_dyn(surf, t, dt, cx, cy, W, H):
    """Under the darkness: fire, chandelier, rats, spiders, footprints, ghosts that drift through walls."""
    T=HM_T
    for f in HM_FX["steps"]: f[2]-=dt
    HM_FX["steps"]=[f for f in HM_FX["steps"] if f[2]>0]
    if HM["walk"]-HM_FX["last_step"]>0.28:
        HM_FX["last_step"]=HM["walk"]; HM_FX["steps"].append([HM["x"]+random.uniform(-5,5),HM["y"]+12,4.0])
    for x,y,l in HM_FX["steps"]: pygame.draw.ellipse(surf,(30,20,16),(int(x-cx)-4,int(y-cy)-2,8,5))
    fx_,fy_=HM_FIREPLACE[0]*T+T//2+4,HM_FIREPLACE[1]*T+T//2
    for k in range(5):
        fh=int(10+8*abs(math.sin(t*9+k))); pygame.draw.ellipse(surf,(255,120+k*24,30),(fx_-cx-12+k*5,fy_-cy-fh//2,8,fh))
    ch=(HM_CHANDELIER[0]*T+math.sin(t*0.8)*6,HM_CHANDELIER[1]*T)
    pygame.draw.circle(surf,(170,130,60),(int(ch[0]-cx),int(ch[1]-cy)),26,3)
    for k in range(8):
        a=k/8*6.283+t*0.1; px,py=ch[0]+math.cos(a)*26-cx,ch[1]+math.sin(a)*26-cy
        pygame.draw.circle(surf,(255,220,120),(int(px),int(py)),3)
    if not HM_FX["rats"]:
        HM_FX["rats"]=[{"x":random.uniform(3,33)*T,"y":random.choice((4.2,12.8,22.8))*T,"v":random.choice((-1,1))*random.uniform(90,160),"w":random.uniform(0,6)} for _ in range(4)]
    for r_ in HM_FX["rats"]:
        r_["x"]+=r_["v"]*dt; r_["w"]+=dt
        if not (1.5*T<r_["x"]<34.5*T): r_["v"]*=-1
        if random.random()<dt*0.3: r_["v"]*=-1
        x,y=int(r_["x"]-cx),int(r_["y"]-cy); d=1 if r_["v"]>0 else -1
        pygame.draw.ellipse(surf,(60,52,56),(x-9,y-4,18,9)); pygame.draw.circle(surf,(60,52,56),(x+d*9,y),4)
        pygame.draw.line(surf,(90,70,70),(x-d*9,y),(x-d*20,y+int(math.sin(r_["w"]*20)*3)),1)
    if not HM_FX["spiders"]:
        HM_FX["spiders"]=[{"x":random.uniform(2,34)*T,"y0":random.choice((2,11,21))*T,"ph":random.uniform(0,6)} for _ in range(5)]
    for sp in HM_FX["spiders"]:
        x=int(sp["x"]-cx); y0=int(sp["y0"]-cy); y=y0+int((0.5+0.5*math.sin(t*0.7+sp["ph"]))*T*0.9)
        pygame.draw.line(surf,(200,200,210),(x,y0),(x,y),1); pygame.draw.circle(surf,(20,14,20),(x,y),5)
        for o in (-1,1):
            for j in range(3): pygame.draw.line(surf,(20,14,20),(x,y),(x+o*9,y-3+j*3),1)

def _hm_lights(dk, t, cx, cy):
    T=HM_T; L=_hm_light
    fx_,fy_=HM_FIREPLACE[0]*T+T//2+4-cx,HM_FIREPLACE[1]*T+T//2-cy; rr=int(T*(2.8+0.15*math.sin(t*9)))
    dk.blit(L(rr),(int(fx_-rr),int(fy_-rr)),special_flags=pygame.BLEND_RGBA_MIN)
    rr=int(T*3.6); c=(int(HM_CHANDELIER[0]*T-cx+math.sin(t*0.8)*6),int(HM_CHANDELIER[1]*T-cy))
    dk.blit(L(rr),(c[0]-rr,c[1]-rr),special_flags=pygame.BLEND_RGBA_MIN)

def _hm_after(surf, t, dt):
    """Thunder: the windows flash and the whole mansion lights up for a moment."""
    HM_FX["t_light"]-=dt
    if HM_FX["t_light"]<=0:
        HM_FX["t_light"]=random.uniform(7,14); HM_FX["flash"]=0.35
        try: SND_THUNDER.play()
        except Exception: pass
    if HM_FX["flash"]>0:
        HM_FX["flash"]-=dt; a=int(95*(HM_FX["flash"]/0.35)) if int(HM_FX["flash"]*30)%3 else 30
        W,H=surf.get_size(); o=pygame.Surface((W,H),pygame.SRCALPHA); o.fill((190,200,255,a)); surf.blit(o,(0,0))
    W,H=surf.get_size()
    for k in range(18):                                                 # dust floating in your lantern light
        r=random.Random(k); px=W//2+int(math.sin(t*0.5+k*1.3)*r.uniform(30,120)); py=H//2+int(math.cos(t*0.4+k*2.1)*r.uniform(20,90))
        if math.sin(t*2+k)>0: pygame.draw.circle(surf,(230,210,170),(px,py),1)

for _en,_es,_he in [("HE HE HE!","¡JE JE JE!","חה חה חה!"),("Rooms with a TREAT: {0} / {1}","",""),]:
    if _es: TR['ES'][_en]=_es; TR['HE'][_en]=_he
TR_TEMPLATES.append((_re.compile(r"^Rooms with a TREAT: (\d+) / (\d+)$"),{"ES":"Habitaciones con TRATO: {0} / {1}","HE":"חדרים עם TREAT: {0} / {1}"}))
TR_TEMPLATES.append((_re.compile(r"^\+(\d+) candy$"),{"ES":"+{0} caramelos","HE":"+{0} ממתקים"}))

def haunt_screen(surf, dt, mouse, events):
    """Runs every Haunt screen. Returns 'exit' when the player leaves."""
    t=pygame.time.get_ticks()/1000; W,H=surf.get_size(); h=haunt_data(); sc=HS["screen"]; HS["t"]+=dt
    if sc=="trailer":                                   # first visit: mini trailer, then "IN PASS: SEASON 2"
        if draw_haunt_minitrailer(surf,dt,events):
            h["trailer_seen"]=True; save_gd(gd); HS["screen"]=HS.get("after_trailer","hub")
            if pass_season()==2: return "reveal"
            _teaser_music_stop()
        return None
    _rd=HS.get("round")
    haunt_music("haunt_boss" if sc=="boss" else ("haunt_rooms" if (sc=="round" and _rd is not None and _rd.result is None) or sc=="lia" else "haunt_mansion"))
    esc=ui_esc(events)
    if sc=="mansion" and not h["intro_seen"]: HS["screen"]=sc="intro"
    if sc=="hub":
        cards=draw_haunt_hub(surf,t,dt,mouse); bk=ui_back(surf,dt,mouse)
        if ui_click(events,cards["mansion"]): HS["screen"]="mansion"; SND_CREAK.play()
        elif ui_click(events,cards["shop"]): HS.update({"screen":"shop","shop_back":"hub"}); SND_SELECT.play()
        elif ui_click(events,cards["badges"]): HS["screen"]="hbadges"; SND_SELECT.play()
        elif ui_click(events,cards["quests"]): HS["screen"]="quests"; SND_SELECT.play()
        elif ui_click(events,cards["rules"]): HS["screen"]="rules"; SND_SELECT.play()
        elif ui_click(events,bk) or esc: SND_SELECT.play(); play_music("menu"); return "exit"
        return None
    if sc=="boss":
        bs=HS["boss"]
        for ev in events:
            if ev.type==pygame.MOUSEBUTTONDOWN and ev.button==1: bs.click(ev.pos)
        bs.update(dt); bs.draw(surf,mouse,t)
        done=(bs.state=="end" and bs.line>=len(BOSS_END_LINES)-1 and bs.t>1.0)
        if bs.state=="lose" and bs.t>1.0:
            again=_h_btn(surf,"bs_again",pygame.Rect(W//2+10,H-90,240,50),"TRY AGAIN",H_ORANGE,dt,mouse)
            back=_h_btn(surf,"bs_back",pygame.Rect(W//2-250,H-90,240,50),"BACK",(110,70,150),dt,mouse,"back")
            if ui_click(events,again): haunt_start_boss()
            elif ui_click(events,back) or esc: HS["screen"]="mansion"
        elif done:
            back=_h_btn(surf,"bs_done",pygame.Rect(W//2-130,H-70,260,50),"BACK TO THE MANSION",H_ORANGE,dt,mouse,"door")
            if ui_click(events,back) or esc: HS["screen"]="mansion"
        elif esc and bs.state in ("intro","fight"): HS["screen"]="mansion"
        return None
    if sc=="rules":
        draw_haunt_rules(surf,t); bk=ui_back(surf,dt,mouse)
        if ui_click(events,bk) or esc: HS["screen"]="hub"; SND_SELECT.play()
        return None
    if sc=="quests":
        draw_haunt_quests(surf,t); bk=ui_back(surf,dt,mouse)
        if ui_click(events,bk) or esc: HS["screen"]=HS.get("quests_back","hub"); HS["quests_back"]="hub"; SND_SELECT.play()
        return None
    if sc=="hbadges":
        rects=draw_haunt_badges(surf,t,dt,mouse); bk=ui_back(surf,dt,mouse)
        if _badge_pop["id"]: draw_badge_popup(surf,events,t)
        else:
            clk=next((b for r,b in rects if ui_click(events,r)),None)
            if clk: _badge_pop.update({"id":clk["id"],"t":time.time()}); SND_SELECT.play()
            elif ui_click(events,bk) or esc: HS["screen"]="hub"; SND_SELECT.play()
        return None
    if sc=="lia_page":
        rr=draw_lia_page(surf,t,dt,mouse); bk=ui_back(surf,dt,mouse)
        if ui_click(events,rr["play"]):
            HS.update({"screen":"lia","lia":LiaRound(from_mansion=haunt_state()=="active"),"lia_back":"lia_page"}); SND_SELECT.play()
        elif ui_click(events,rr["chan"]): lia_portal_start(rr["chan"].center)
        elif ui_click(events,bk) or esc: SND_SELECT.play(); play_music("menu"); return "exit"
        return None
    if sc=="lia_portal":
        if HS.get("portal_from")=="lia_page": draw_lia_page(surf,t,dt,(-99,-99))
        else: surf.fill((20,0,25))
        if draw_portal(surf,dt)=="done" or (esc and portal_fx["opened"]): HS["screen"]=HS.get("portal_from","lia_page")
        return None
    if sc=="intro":
        n=draw_haunt_intro(surf,t,HS["intro_page"])
        if any(ev.type==pygame.MOUSEBUTTONDOWN and ev.button==1 for ev in events) or esc:
            HS["intro_page"]+=1; SND_SELECT.play()
            if HS["intro_page"]>=n or esc:
                h["intro_seen"]=True; award_badge("the_mansion"); save_gd(gd); HS["screen"]="mansion"
        return None
    if sc=="mansion":
        held=HM.setdefault("held",set())
        for ev in events:
            if ev.type==pygame.KEYDOWN: held.add(getattr(ev,"scancode",0))
            elif ev.type==pygame.KEYUP: held.discard(getattr(ev,"scancode",0))
        kp=pygame.key.get_pressed()
        class _K:
            def __getitem__(self, k):
                sc_={pygame.K_w:26,pygame.K_a:4,pygame.K_s:22,pygame.K_d:7,pygame.K_UP:82,pygame.K_DOWN:81,pygame.K_LEFT:80,pygame.K_RIGHT:79}.get(k)
                return kp[k] or (sc_ in held)
        hm_update(dt,_K()); draw_hm(surf,t,dt,mouse)
        use=any(ev.type==pygame.KEYDOWN and (ev.key in (pygame.K_e,pygame.K_RETURN,pygame.K_SPACE) or getattr(ev,"scancode",0)==8) for ev in events)
        nr=HM["near"]
        if not use and nr:                                  # clicking the thing you stand next to works too
            kind,i_,(wx,wy)=nr
            mw,mh=_hm_static_map().get_size()
            cxx=int(min(max(HM["x"]-W/2,0),max(0,mw-W))); cyy=int(min(max(HM["y"]-H/2,0),max(0,mh-H)))
            if any(ev.type==pygame.MOUSEBUTTONDOWN and ev.button==1 and math.hypot(ev.pos[0]-(wx-cxx),ev.pos[1]-(wy-cyy))<HM_T for ev in events): use=True
        if use and nr:
            kind,i_,_=nr; held.clear()
            if kind=="door": HS.update({"screen":"door","room":i_,"t":0.0}); SND_CREAK.play()
            elif kind=="lia": HS.update({"screen":"lia","lia":LiaRound(from_mansion=True),"lia_back":"mansion"}); SND_SELECT.play()
            elif kind=="shop": HS.update({"screen":"shop","shop_back":"mansion"}); SND_SELECT.play()
            elif kind=="desk": HS.update({"screen":"quests","quests_back":"mansion"}); SND_SELECT.play()
            elif kind=="attic":
                if h["shadow_found"]: haunt_start_boss()
                elif h["candy_total"]>=500:
                    h["shadow_found"]=True; award_badge("shadow_seeker"); haunt_check_rewards()
                    HS.update({"screen":"found","t":0.0}); SND_SCREAM.play()
                else: hm_say(f"Locked tight... collect 500 candies first ({h['candy_total']}/500)"); SND_WRONG.play()
        if esc: SND_SELECT.play(); held.clear(); HS["screen"]="hub"
    elif sc=="found":
        surf.fill((0,0,0)); m=min(W,H); e=HS["t"]
        for ex in (-0.06,0.06):
            pygame.draw.ellipse(surf,(220,30,30),(W//2+int(ex*W)-12,int(H*0.38),24,12))
        for i,l in enumerate(["You found THE SHADOW.","...he found you too.","Close the door on him!"]):
            if e>0.8+i*0.9:
                ls=ui_font(m*0.05).render(l,True,(230,200,210)); surf.blit(ls,ls.get_rect(center=(W//2,int(H*0.55)+i*int(H*0.08))))
        if e>3.5:
            b=_h_btn(surf,"h_fight",pygame.Rect(W//2-130,H-80,260,50),"CLOSE THE DOOR!",(200,50,60),dt,mouse,"door")
            if ui_click(events,b): haunt_start_boss()
        if esc: HS["screen"]="mansion"
    elif sc=="door":
        k=min(1.0,HS["t"]/1.1)
        b=draw_door_scene(surf,t,HS["room"],k,mouse,dt); bk=ui_back(surf,dt,mouse)
        if b and ui_click(events,b): HS.update({"screen":"round","round":HRound("room",HS["room"])}); SND_SELECT.play()
        elif ui_click(events,bk) or esc: HS["screen"]="mansion"
    elif sc=="round":
        rnd=HS["round"]
        if rnd.result is not None and not getattr(rnd,"_done",False): rnd._done=True; haunt_round_done(rnd)
        if rnd.result is None:
            for ev in events:
                if ev.type==pygame.MOUSEBUTTONDOWN and ev.button==1: rnd.click(ev.pos)
                if ev.type==pygame.KEYDOWN and ev.key==pygame.K_f: rnd.use_freeze()
            rnd.update(dt); rnd.draw(surf,mouse,t)
            if rnd.result is not None and not getattr(rnd,"_done",False): rnd._done=True; haunt_round_done(rnd)
            if esc and rnd.result is None:
                if HS.get("standalone"): play_music("menu"); return "exit"
                HS["screen"]="mansion"
        else:
            rnd.update(dt); b1,b2=draw_room_result(surf,t,rnd,mouse,dt)
            if b2 and ui_click(events,b2):
                HS["round"]=HRound(rnd.kind,rnd.room) if rnd.kind!="shadow" else HRound("shadow"); SND_SELECT.play()
            elif (b1 and ui_click(events,b1)) or (esc and rnd.result_t>1.3):
                SND_SELECT.play()
                if HS.get("standalone"): play_music("menu"); return "exit"
                HS["screen"]="mansion"
    elif sc=="shop":
        rects=draw_haunt_shop(surf,t,dt,mouse); bk=ui_back(surf,dt,mouse)
        for r,key,price in rects:
            if ui_click(events,r): haunt_buy(key,price)
        if ui_click(events,bk) or esc: HS["screen"]=HS.get("shop_back","mansion"); SND_SELECT.play()
    elif sc=="lia":
        lr=HS["lia"]
        if not lr.res:
            for ev in events:
                if ev.type==pygame.MOUSEBUTTONDOWN and ev.button==1: lr.click(ev.pos)
            lr.update(dt); lr.draw(surf,mouse,t)
            if esc: lr.res="quit"; HS["screen"]=HS.get("lia_back","mansion")
        else:
            lr.draw(surf,(-99,-99),t); m=min(W,H)
            o=pygame.Surface((W,H),pygame.SRCALPHA); o.fill((20,0,25,240)); surf.blit(o,(0,0))
            bs=ui_font(m*0.1).render(f"{lr.score}",True,LIA_PINK); surf.blit(bs,bs.get_rect(center=(W//2,int(H*0.25))))
            ls=[f"Best: {gd.get('high_scores',{}).get('lia',0)}"]
            if getattr(lr,"candy",0): ls.append(f"+{lr.candy} candy")
            ls.append("Listened to Lia: reach 20 points" if not has_badge("listened_lia") else "You listened to Lia!")
            for i,l in enumerate(ls):
                s_=ui_font(m*0.04).render(l,True,WHITE); surf.blit(s_,s_.get_rect(center=(W//2,int(H*0.42)+i*int(H*0.07))))
            ch_=_h_btn(surf,"h_lch",pygame.Rect(W//2-150,int(H*0.66),300,46),"LIA'S CHANNEL",LIA_PINK,dt,mouse,"megaphone")
            again=_h_btn(surf,"h_lag",pygame.Rect(W//2+10,H-80,220,48),"PLAY AGAIN",LIA_PINK,dt,mouse)
            back=_h_btn(surf,"h_lbk",pygame.Rect(W//2-230,H-80,220,48),"BACK",(110,70,150),dt,mouse,"back")
            if ui_click(events,again): HS["lia"]=LiaRound(from_mansion=lr.from_mansion); SND_SELECT.play()
            elif ui_click(events,ch_): lia_portal_start(ch_.center)
            elif ui_click(events,back) or esc:
                SND_SELECT.play()
                HS["screen"]=HS.get("lia_back","mansion")
    msg=HS.get("msg")
    if msg and time.time()-msg[2]<2.2:
        ms=ui_font(min(W,H)*0.03).render(msg[0],True,msg[1]); mr=ms.get_rect(centerx=W//2,y=H-120).inflate(26,12)
        pygame.draw.rect(surf,(20,10,30),mr,border_radius=mr.h//2); surf.blit(ms,ms.get_rect(center=mr.center))
    return None



# =============================================================================
#  HALLOWEEN DESIGN  —  Settings > DESIGN > Halloween changes the WHOLE game look
# =============================================================================
SPOOKY_PAL = [(255,122,20),(160,70,225),(120,220,40),(255,196,60),(215,40,70),(90,150,255)]
_spk_cache = {}
def halloween_theme():
    if gd.get("design")!="halloween": return False
    return bool(gd.get("haunt",{}).get("design_unlocked")) or dev_mode()

def spooky_col(c):
    """Move any UI color into the Halloween palette (orange / purple / slime / candle / blood / moon)."""
    c=tuple(c[:3])
    if c in _spk_cache: return _spk_cache[c]
    import colorsys
    h,l,s=colorsys.rgb_to_hls(*(v/255 for v in c))
    if s<0.18: out=(150,120,170) if l>0.35 else (60,45,70)
    else:
        hd=h*360
        out=(SPOOKY_PAL[4] if hd<18 or hd>=330 else SPOOKY_PAL[0] if hd<45 else SPOOKY_PAL[3] if hd<70 else
             SPOOKY_PAL[2] if hd<165 else SPOOKY_PAL[5] if hd<235 else SPOOKY_PAL[1])
    _spk_cache[c]=out; return out

_vig_cache={}
def _vignette(W, H):
    if (W,H) not in _vig_cache:
        v=pygame.Surface((W,H),pygame.SRCALPHA)
        for k in range(12):
            r=pygame.Rect(0,0,W,H).inflate(-k*int(min(W,H)*0.02),-k*int(min(W,H)*0.02))
            pygame.draw.rect(v,(12,0,22,max(0,70-k*6)),r,int(min(W,H)*0.02))
        _vig_cache.clear(); _vig_cache[(W,H)]=v
    return _vig_cache[(W,H)]

def draw_cobweb(surf, x, y, s, flip=False, alpha=90):
    w=pygame.Surface((s,s),pygame.SRCALPHA); col=(220,220,235,alpha)
    o=(s,0) if flip else (0,0)
    for k in range(5):
        a=math.pi/2*k/4; ex=s*math.cos(a); ey=s*math.sin(a)
        pygame.draw.line(w,col,o,(s-ex if flip else ex,ey),1)
    for r in (0.3,0.55,0.8):
        pts=[]
        for k in range(5):
            a=math.pi/2*k/4; px=s*r*math.cos(a); py=s*r*math.sin(a); pts.append((s-px if flip else px,py))
        pygame.draw.lines(w,col,False,pts,1)
    surf.blit(w,(x-(s if flip else 0),y))

_hmb_cache={}
def _haunted_static(W, H):
    key=(W,H)
    if key in _hmb_cache: return _hmb_cache[key]
    s=pygame.Surface((W,H))
    for y in range(H): s.fill(_mix((30,10,48),(6,3,12),(y/H)**0.8),(0,y,W,1))
    rnd=random.Random(7)
    for _ in range(140):
        x=rnd.randint(0,W); y=rnd.randint(0,int(H*0.65)); c=rnd.randint(110,230); s.set_at((x,y),(c,c,min(255,c+25)))
    hz=int(H*0.78)
    pygame.draw.polygon(s,(16,8,24),[(0,hz)]+[(x,hz-int(18*math.sin(x/W*7))-12) for x in range(0,W+20,20)]+[(W,H),(0,H)])
    pygame.draw.rect(s,(10,5,16),(0,hz+10,W,H-hz))
    for tx,flip in ((int(W*0.06),1),(int(W*0.94),-1)):          # bare trees
        def br(x,y,a,l,w):
            if l<6: return
            x2=x+math.cos(a)*l; y2=y-math.sin(a)*l
            pygame.draw.line(s,(8,4,12),(x,y),(x2,y2),max(1,int(w)))
            br(x2,y2,a+0.45*flip,l*0.72,w*0.7); br(x2,y2,a-0.35*flip,l*0.68,w*0.7)
        br(tx,hz+10,math.pi/2,H*0.13,9)
    for i in range(9):                                          # tombstones + fence
        x=int(W*(0.12+i*0.095)); th=int(H*(0.04+0.015*(i%3)))
        pygame.draw.rect(s,(26,20,34),(x-10,hz+18-th,20,th),border_top_left_radius=10,border_top_right_radius=10)
        pygame.draw.line(s,(40,32,50),(x-4,hz+18-th+8),(x+4,hz+18-th+8),2)
    for x in range(0,W,14):
        pygame.draw.line(s,(12,8,18),(x,H-30),(x,H-58),3); pygame.draw.polygon(s,(12,8,18),[(x-3,H-58),(x+3,H-58),(x,H-64)])
    pygame.draw.line(s,(12,8,18),(0,H-50),(W,H-50),3); pygame.draw.line(s,(12,8,18),(0,H-36),(W,H-36),3)
    _hmb_cache.clear(); _hmb_cache[key]=s; return s

def draw_haunted_menu_bg(surf, t, accent=None):
    W,H=surf.get_size(); m=min(W,H)
    flash=(t%9.0)<0.12 or 0.25<(t%9.0)<0.32                     # lightning
    surf.blit(_haunted_static(W,H),(0,0))
    mx,my,mr=int(W*0.82),int(H*0.16),int(m*0.07)
    draw_moon(surf,mx,my,mr)
    for i in range(3):                                           # clouds over the moon
        cx=(t*12*(1+i*0.4)+i*W*0.4)%(W+300)-150; cy=int(H*(0.12+i*0.05))
        cl=pygame.Surface((240,60),pygame.SRCALPHA)
        for dx,rr in ((40,22),(80,30),(125,26),(170,20),(200,16)): pygame.draw.circle(cl,(40,25,60,110),(dx,32),rr)
        surf.blit(cl,(cx,cy))
    if accent: surf.blit(_glow(int(m*0.4),spooky_col(accent),26),(W//2-int(m*0.4),int(H*0.5)-int(m*0.4)))
    for wd in _bg_words:                                         # floating spooky words
        wd["y"]-=wd["v"]*0.012
        if wd["y"]<-0.1: wd["y"]=1.1; wd["x"]=random.random(); wd["w"]=random.choice(COLOR_NAMES)
        size=int(m*wd["s"]); key=("H",wd["w"],size,lang_code())
        if key not in _word_surf_cache:
            if len(_word_surf_cache)>80: _word_surf_cache.clear()
            ws=ui_font(size).render(H_NAME[wd["w"]],True,H_COL[H_NAME[wd["w"]]]); ws.set_alpha(22); _word_surf_cache[key]=ws
        surf.blit(_word_surf_cache[key],(int(wd["x"]*W),int(wd["y"]*H)))
    for i in range(5): draw_bat(surf,(t*55*(0.7+i*0.12)+i*260)%(W+160)-80,int(H*0.1)+i*24+int(math.sin(t*1.7+i)*18),9+i%3*4,t+i)
    for k in range(2):                                           # drifting fog
        fy=int(H*(0.74+k*0.08)); fo=pygame.Surface((W,int(H*0.12)),pygame.SRCALPHA)
        for i in range(8):
            fx=(t*(14+k*9)+i*W/6)%(W+260)-130
            pygame.draw.ellipse(fo,(150,120,190,18+k*6),(fx,int(H*0.02),260,int(H*0.08)))
        surf.blit(fo,(0,fy))
    for i in range(5):                                           # glowing pumpkins
        x=int(W*(0.1+i*0.2)); y=H-18; fl=0.6+0.4*math.sin(t*5+i*2)
        surf.blit(_glow(30,(255,120,20),int(60*fl)),(x-30,y-30)); ui_icon2(surf,"pumpkin",x,y,14,(255,120,20),t)
    if flash:
        o=pygame.Surface((W,H),pygame.SRCALPHA); o.fill((220,210,255,70)); surf.blit(o,(0,0))


# ── Halloween UI kit: gravestone cards, wooden-plank buttons, wood frames, bone sliders ──
_ht_tex={}
def _ht_stone(w, h, locked=False):
    k=("stone",w,h,locked)
    if k in _ht_tex: return _ht_tex[k]
    if len(_ht_tex)>120: _ht_tex.clear()
    s=pygame.Surface((w,h),pygame.SRCALPHA); rnd=random.Random(w*31+h)
    top=(78,70,92) if not locked else (55,52,60); bot=(38,32,48) if not locked else (28,26,32)
    for y in range(h): s.fill((*_mix(top,bot,y/max(1,h-1)),255),(0,y,w,1))
    for _ in range(w*h//70):                                    # speckles
        x=rnd.randint(0,w-1); y=rnd.randint(0,h-1); d=rnd.randint(-22,22)
        c=s.get_at((x,y)); s.set_at((x,y),(max(0,min(255,c[0]+d)),max(0,min(255,c[1]+d)),max(0,min(255,c[2]+d)),255))
    for _ in range(2):                                          # cracks
        x=rnd.randint(int(w*0.15),int(w*0.85)); y=rnd.randint(int(h*0.1),int(h*0.5)); pts=[(x,y)]
        for _ in range(rnd.randint(3,6)): x+=rnd.randint(-14,14); y+=rnd.randint(6,18); pts.append((x,y))
        pygame.draw.lines(s,(22,18,28,255),False,pts,2)
    rad=min(w//2,int(h*0.32))
    mask=pygame.Surface((w,h),pygame.SRCALPHA)
    pygame.draw.rect(mask,(255,255,255,255),(0,0,w,h),border_top_left_radius=rad,border_top_right_radius=rad,border_bottom_left_radius=8,border_bottom_right_radius=8)
    s.blit(mask,(0,0),special_flags=pygame.BLEND_RGBA_MIN)
    inner=pygame.Rect(10,10,w-20,h-20)                          # carved inner line
    pygame.draw.rect(s,(26,20,34,200),inner,2,border_top_left_radius=max(4,rad-10),border_top_right_radius=max(4,rad-10),border_bottom_left_radius=6,border_bottom_right_radius=6)
    if not locked:                                              # moss along the top
        for i in range(w//9):
            a=math.pi*(i/(w//9))
            mx=int(w/2-math.cos(a)*(w/2-4)); my=int(rad-math.sin(a)*(rad-4)) if rad>8 else 4
            pygame.draw.circle(s,(45,95,45,220),(mx,my),rnd.randint(3,6))
            if rnd.random()<0.25: pygame.draw.line(s,(45,95,45,200),(mx,my),(mx,my+rnd.randint(6,16)),2)
    _ht_tex[k]=(s,rad); return _ht_tex[k]

def _ht_wood(w, h, col_tint=None):
    k=("wood",w,h,col_tint)
    if k in _ht_tex: return _ht_tex[k]
    s=pygame.Surface((w,h),pygame.SRCALPHA); rnd=random.Random(w*7+h)
    base=(112,66,34); dark=(70,38,18)
    if col_tint: base=_mix(base,col_tint,0.18); dark=_mix(dark,col_tint,0.12)
    for y in range(h): s.fill((*_mix(base,dark,abs(y/h-0.45)*1.4),255),(0,y,w,1))
    for i in range(max(3,h//5)):                                 # wood grain
        y=rnd.randint(2,h-3); x0=rnd.randint(-20,w//2); ln=rnd.randint(w//4,w)
        pygame.draw.line(s,(*_mix(dark,(0,0,0),0.3),160),(x0,y),(x0+ln,y+rnd.randint(-2,2)),1)
    cut=min(10,h//3)                                             # chopped ends
    mask=pygame.Surface((w,h),pygame.SRCALPHA)
    pygame.draw.polygon(mask,(255,255,255,255),[(cut,0),(w-3,0),(w,cut),(w-cut//2,h),(3,h),(0,h-cut)])
    s.blit(mask,(0,0),special_flags=pygame.BLEND_RGBA_MIN)
    _ht_tex[k]=s; return s

def _ht_text(f, text, col=(240,228,210), shadow=(25,10,5)):
    a=f.render(text,True,col); b=f.render(text,True,shadow); return a,b

def _ht_card(surf, key, rect, col, icon, title, sub, t, dt, mouse, tag=None, extra=None, big=False, locked=False):
    col=spooky_col(col); hov=rect.collidepoint(mouse) and not locked
    h=ui_hover(key,1.0 if hov else 0.0,dt); W,H=surf.get_size()
    r=rect.move(int(math.sin(t*30)*1.5*h),-int(6*h))
    sh=pygame.Surface((r.w,18),pygame.SRCALPHA); pygame.draw.ellipse(sh,(0,0,0,120),sh.get_rect()); surf.blit(sh,(r.x,r.bottom-6))
    if h>0.02: surf.blit(_glow(int(max(r.w,r.h)*0.62),col,int(70*h)),(r.centerx-int(max(r.w,r.h)*0.62),r.centery-int(max(r.w,r.h)*0.62)))
    st,rad=_ht_stone(r.w,r.h,locked); surf.blit(st,r.topleft)
    pygame.draw.rect(surf,_mix((20,14,28),col,0.35+0.5*h) if not locked else (40,40,46),r,2,
                     border_top_left_radius=rad,border_top_right_radius=rad,border_bottom_left_radius=8,border_bottom_right_radius=8)
    m=min(r.w,r.h); isz=m*(0.2 if big else 0.16)*(1+0.08*h)
    iy=r.y+r.h*(0.36 if big else 0.36)+math.sin(t*2+r.x)*3*h
    if not locked: surf.blit(_glow(int(isz*2.0),col,90),(r.centerx-int(isz*2.0),iy-int(isz*2.0)))
    ui_icon2(surf,icon,r.centerx,iy,isz,_mix(col,WHITE,0.2) if not locked else (75,72,80),t)
    tf=ui_font(min(W,H)*(0.08 if big else 0.05))
    ty=int(r.y+r.h*(0.58 if big else 0.6))
    ts=render_fit(tf,title,(240,230,215) if not locked else (110,105,115),r.w-30); tsh=render_fit(tf,title,(15,8,20),r.w-30)
    surf.blit(tsh,tsh.get_rect(centerx=r.centerx+2,y=ty+2)); surf.blit(ts,ts.get_rect(centerx=r.centerx,y=ty))
    if sub:
        ss=render_fit(ui_font(min(W,H)*0.028),sub,(200,185,215) if not locked else (95,90,100),r.w-30)
        surf.blit(ss,ss.get_rect(centerx=r.centerx,y=ty+ts.get_height()+6))
    if extra:
        es=render_fit(ui_font(min(W,H)*0.027),extra,_mix(col,WHITE,0.35),r.w-30); surf.blit(es,es.get_rect(centerx=r.centerx,bottom=r.bottom-16))
    for cx in (r.x+16,r.right-16):                               # candles on the grave
        cy=r.bottom-6; pygame.draw.rect(surf,(235,225,200),(cx-4,cy-16,8,16),border_radius=2)
        if not locked:
            fl=0.7+0.3*math.sin(t*12+cx)
            surf.blit(_glow(14,(255,170,60),int(110*fl)),(cx-14,cy-30))
            pygame.draw.ellipse(surf,(255,200,80),(cx-3,cy-25,6,int(9*fl)+2))
    if tag:
        tf2=ui_font(min(W,H)*0.024); tsf=tf2.render(tag,True,(245,230,210))
        tr=tsf.get_rect(topright=(r.right-14,r.y+max(14,int(rad*0.35)))).inflate(16,8)
        pl=_ht_wood(tr.w,tr.h); surf.blit(pl,tr.topleft); pygame.draw.circle(surf,(200,190,170),(tr.x+5,tr.centery),2)
        surf.blit(tsf,tsf.get_rect(center=tr.center))
    if locked:
        for a in (-1,1): pygame.draw.line(surf,(120,115,125),(r.x+20,r.centery+a*r.h*0.25),(r.right-20,r.centery-a*r.h*0.25),5)
        ls=ui_font(min(W,H)*0.03).render("LOCKED",True,(170,165,175)); surf.blit(ls,ls.get_rect(center=(r.centerx,r.y+r.h*0.2)))
    return r

def _ht_pill(surf, key, rect, text, col, dt, mouse, icon=None):
    col=spooky_col(col); h=ui_hover(key,1.0 if rect.collidepoint(mouse) else 0.0,dt)
    r=rect.inflate(int(6*h),int(4*h)); t=pygame.time.get_ticks()/1000
    if h>0.02: surf.blit(_glow(int(r.w*0.6),col,int(70*h)),(r.centerx-int(r.w*0.6),r.centery-int(r.w*0.6)))
    sh=pygame.Surface((r.w,r.h),pygame.SRCALPHA); sh.fill((0,0,0,90)); surf.blit(sh,(r.x+3,r.y+4))
    surf.blit(_ht_wood(r.w,r.h,col),r.topleft)
    pygame.draw.line(surf,_mix(col,WHITE,0.3*h),(r.x+8,r.bottom-3),(r.right-8,r.bottom-3),3)
    for nx in (r.x+9,r.right-9): pygame.draw.circle(surf,(170,160,150),(nx,r.y+7),3); pygame.draw.circle(surf,(90,80,75),(nx,r.y+7),3,1)
    f=ui_font(min(surf.get_size())*0.032); s,shd=_ht_text(f,text)
    if icon:
        isz=r.h*0.26; total=isz*2+8+s.get_width(); x0=r.centerx-total/2
        ui_icon2(surf,icon,x0+isz,r.centery,isz,(245,230,210))
        surf.blit(shd,shd.get_rect(midleft=(x0+isz*2+10,r.centery+2))); surf.blit(s,s.get_rect(midleft=(x0+isz*2+8,r.centery)))
    else:
        surf.blit(shd,shd.get_rect(center=(r.centerx+2,r.centery+2))); surf.blit(s,s.get_rect(center=r.center))
    return r

def _ht_panel(surf, rect, title, col):
    col=spooky_col(col)
    p=pygame.Surface(rect.size,pygame.SRCALPHA)
    pygame.draw.rect(p,(18,10,24,232),p.get_rect(),border_radius=6); surf.blit(p,rect.topleft)
    fw=10                                                        # wooden frame
    for fr in (pygame.Rect(rect.x,rect.y,rect.w,fw),pygame.Rect(rect.x,rect.bottom-fw,rect.w,fw),
               pygame.Rect(rect.x,rect.y,fw,rect.h),pygame.Rect(rect.right-fw,rect.y,fw,rect.h)):
        surf.blit(_ht_wood(fr.w,fr.h),fr.topleft)
    for cx,cy in ((rect.x,rect.y),(rect.right,rect.y),(rect.x,rect.bottom),(rect.right,rect.bottom)):   # iron corners
        pygame.draw.circle(surf,(60,58,66),(cx+(8 if cx==rect.x else -8),cy+(8 if cy==rect.y else -8)),7)
        pygame.draw.circle(surf,(120,118,130),(cx+(8 if cx==rect.x else -8),cy+(8 if cy==rect.y else -8)),3)
    draw_cobweb(surf,rect.right-fw,rect.y+fw,min(56,rect.h//3),True,60)
    if title:
        f=ui_font(min(surf.get_size())*0.034); ts,tsh=_ht_text(f,title,col,(10,4,14))
        surf.blit(tsh,(rect.x+30,rect.y+18)); surf.blit(ts,(rect.x+28,rect.y+16))
        ui_icon2(surf,"pumpkin",rect.x+20,rect.y+16+ts.get_height()//2,7,(255,120,20))
        return rect.y+24+ts.get_height()
    return rect.y+16

def _ht_header(surf, title, sub, col, t):
    W,H=surf.get_size(); m=min(W,H); col=spooky_col(col)
    f=ui_font(m*0.10); s=f.render(title,True,(245,235,220)); r=s.get_rect(centerx=W//2,y=int(H*0.04))
    g=f.render(title,True,col); surf.blit(g,r.move(3,4)); surf.blit(s,r)
    rnd=random.Random(len(title))
    for i in range(max(3,len(title)//2)):                        # drips
        x=r.x+int(r.w*rnd.random()); ln=int(6+14*(0.5+0.5*math.sin(t*1.2+i*1.7)))
        pygame.draw.line(surf,col,(x,r.bottom-8),(x,r.bottom-8+ln),3); pygame.draw.circle(surf,col,(x,r.bottom-8+ln),3)
    for cx in (r.x-34,r.right+34):                               # candles
        cy=r.centery+10; pygame.draw.rect(surf,(235,225,200),(cx-6,cy-14,12,30),border_radius=3)
        fl=0.7+0.3*math.sin(t*11+cx); surf.blit(_glow(22,(255,170,60),int(120*fl)),(cx-22,cy-36))
        pygame.draw.ellipse(surf,(255,205,90),(cx-4,cy-30,8,int(12*fl)+4))
    if sub:
        ss=ui_font(m*0.034).render(sub,True,(200,180,215)); surf.blit(ss,ss.get_rect(centerx=W//2,y=r.bottom+18))
    return r.bottom+18+int(m*0.04)

def _ht_slider_draw(surf, key, rect, val, col, label, mouse):
    col=spooky_col(col); f=ui_font(min(surf.get_size())*0.03)
    surf.blit(f.render(label,True,(225,210,230)),(rect.x,rect.y-26))
    ps=f.render(f"{int(round(val*100))}%",True,col); surf.blit(ps,ps.get_rect(right=rect.right,y=rect.y-26))
    tr=rect.inflate(0,6); pygame.draw.rect(surf,(225,215,195),tr,border_radius=tr.h//2)          # bone
    for ex in (tr.x,tr.right):
        for dy in (-5,5): pygame.draw.circle(surf,(225,215,195),(ex,tr.centery+dy),6)
    fw=int(rect.w*val)
    if fw>0: pygame.draw.rect(surf,col,(rect.x,rect.y,fw,rect.h),border_radius=rect.h//2)
    kx=rect.x+fw; act=_slider_drag.get(key) or rect.inflate(24,30).collidepoint(mouse)
    surf.blit(_glow(24,(255,130,30),90 if act else 50),(kx-24,rect.centery-24))
    ui_icon2(surf,"pumpkin",kx,rect.centery,13 if act else 11,(255,125,25))

def draw_haunted_title(surf, t, y, scale=1.0):
    W,H=surf.get_size(); m=min(W,H)
    f1=ui_font(m*0.15*scale); word="COLOR"
    pal=[(255,122,20),(160,70,225),(120,220,40),(255,196,60),(215,40,70)]
    letters=[f1.render(ch,True,pal[i]) for i,ch in enumerate(word)]
    tw=sum(l.get_width() for l in letters)+6*4; x=W//2-tw//2
    for i,l in enumerate(letters):
        dy=int(math.sin(t*1.6+i*0.9)*5*scale)
        sh=f1.render(word[i],True,(0,0,0)); sh.set_alpha(150); surf.blit(sh,(x+4,y+dy+6))
        surf.blit(l,(x,y+dy))
        for d in range(2):                                         # slime drips
            dxp=x+int(l.get_width()*(0.3+0.4*d)); ln=int((6+10*((math.sin(t*1.3+i*2+d*3)+1)/2))*scale)
            by=y+dy+int(l.get_height()*0.82)
            pygame.draw.line(surf,pal[i],(dxp,by),(dxp,by+ln),3); pygame.draw.circle(surf,pal[i],(dxp,by+ln),3)
        x+=l.get_width()+6
    f2=ui_font(m*0.075*scale); y2=y+int(m*0.13*scale)
    g=f2.render("UNDER PRESSURE",True,(255,120,20)); g.set_alpha(140)
    for off in (-2,2): surf.blit(g,g.get_rect(centerx=W//2+off,y=y2+off))
    u=f2.render("UNDER PRESSURE",True,(245,235,250)); surf.blit(u,u.get_rect(centerx=W//2,y=y2))
    f3=ui_font(m*0.03*scale); st=f3.render("H A U N T E D   E D I T I O N",True,(190,140,230))
    r=st.get_rect(centerx=W//2,y=y2+u.get_height()+6); surf.blit(st,r)
    for sx in (r.left-30,r.right+30): ui_icon2(surf,"pumpkin",sx,r.centery,9,(255,120,20),t)
    return r.bottom


# =============================================================================
#  WINTER DESIGN  —  Settings > DESIGN > Winter puts the whole game under ice
#  Unlocked by crossing the frozen lake (The Far Shore). Works all year round.
# =============================================================================
ICE_PAL = [(90,170,255),(150,215,255),(70,230,210),(205,235,255),(120,140,255),(60,120,215)]
_ice_cache = {}

def winter_unlocked():
    return bool(has_badge("lake_crosser")) or dev_mode()

def winter_theme():
    if gd.get("design")!="winter": return False
    return winter_unlocked()

def winter_col(c):
    """Move any UI colour into the winter palette (ice blue / cyan / teal / frost / violet)."""
    c=tuple(c[:3])
    if c in _ice_cache: return _ice_cache[c]
    import colorsys
    h,l,s=colorsys.rgb_to_hls(*(v/255 for v in c))
    if s<0.18:
        out=(206,226,246) if l>0.35 else (46,62,92)
    else:
        hd=h*360
        out=(ICE_PAL[0] if hd<18 or hd>=330 else ICE_PAL[1] if hd<45 else ICE_PAL[3] if hd<70 else
             ICE_PAL[2] if hd<165 else ICE_PAL[5] if hd<235 else ICE_PAL[4])
    _ice_cache[c]=out; return out

_wt_bg_cache = {}
def _wt_backdrop(W,H):
    """The still part of the winter menu: sky, aurora, far pines, the frozen lake."""
    k=(W,H)
    if k in _wt_bg_cache: return _wt_bg_cache[k]
    bg=pygame.Surface((W,H)); m=min(W,H); HOR=int(H*0.52)
    for y in range(0,HOR,4):
        q=y/float(HOR)
        pygame.draw.rect(bg,_mix((7,16,38),(30,66,116),q),(0,y,W,4))
    rnd=random.Random(1511)
    for i in range(110):                                   # stars
        x,y=rnd.randrange(W),rnd.randrange(int(HOR*0.92))
        a=rnd.randint(70,210); pygame.draw.circle(bg,(a,a,min(255,a+20)),(x,y),1)
    au=pygame.Surface((W,H),pygame.SRCALPHA)               # aurora
    for rib in range(4):
        bx=rnd.uniform(-W*0.1,W*1.1); amp=rnd.uniform(W*0.05,W*0.16)
        wid=rnd.uniform(W*0.03,W*0.09)
        col=(70,230,190) if rib%2==0 else (110,150,255)
        ph=rnd.uniform(0,6.3)
        for i in range(44):
            t0=i/44.0; t1=(i+1)/44.0
            y0=H*0.02+(HOR*0.96-H*0.02)*t0; y1=H*0.02+(HOR*0.96-H*0.02)*t1
            x0=bx+math.sin(t0*2.6+ph)*amp; x1=bx+math.sin(t1*2.6+ph)*amp
            ww=wid*(0.35+0.95*(1-t0)); a=int(44*(1-t0)**1.4)
            if a<=2: continue
            pygame.draw.polygon(au,(*col,a),[(x0-ww,y0),(x0+ww,y0),(x1+ww,y1),(x1-ww,y1)])
    bg.blit(au,(0,0))
    pygame.draw.polygon(bg,(16,30,56),[(0,HOR),(W*0.2,HOR-H*0.055),(W*0.42,HOR-H*0.018),
                                       (W*0.63,HOR-H*0.068),(W*0.85,HOR-H*0.026),(W,HOR-H*0.012),(W,HOR)])
    x=-W*0.02                                              # far pines
    while x<W*1.02:
        th=H*rnd.uniform(0.015,0.040); tw=th*rnd.uniform(0.30,0.46)
        pygame.draw.polygon(bg,(9,20,40),[(x-tw*0.5,HOR+2),(x,HOR-th),(x+tw*0.5,HOR+2)])
        x+=tw*rnd.uniform(0.55,0.9)
    pygame.draw.line(bg,(190,224,255),(0,HOR),(W,HOR),max(1,int(m*0.004)))
    for y in range(HOR,H,4):                               # the ice
        q=(y-HOR)/float(max(1,H-HOR))
        pygame.draw.rect(bg,_mix((48,84,128),(104,146,190),q),(0,y,W,4))
    for i in range(26):                                    # perspective bands
        q=(i/26.0)**2.1; y=int(HOR+(H-HOR)*q)
        pygame.draw.line(bg,_mix((48,84,128),(230,244,255),0.12+0.10*q),(0,y),(W,y),max(1,int(m*0.003)))
    for i in range(5):                                     # fracture lines
        q=((i+0.4)/5.0)**1.35; y=HOR+(H-HOR)*q; ang=rnd.uniform(-0.14,0.14); px=-W*0.05
        pts=[(px,y)]
        for _ in range(7):
            ang+=rnd.uniform(-0.09,0.09)
            px+=W*1.2/7; y+=math.sin(ang)*H*0.02
            pts.append((px,y))
        pygame.draw.lines(bg,(216,236,255),False,pts,max(1,int(m*0.0025)))
    _wt_bg_cache.clear(); _wt_bg_cache[k]=bg
    return bg

def draw_winter_menu_bg(surf, t, accent=None):
    W,H=surf.get_size(); m=min(W,H)
    surf.blit(_wt_backdrop(W,H),(0,0))
    if accent:
        surf.blit(_glow(int(m*0.42),winter_col(accent),30),(W//2-int(m*0.42),int(H*0.5)-int(m*0.42)))
    draw_snowfall(surf,t,1.0,0.25)
    _wt_edges(surf,0.55)

_wt_edge_cache={}
def _wt_edges(surf, amt=1.0):
    """Frost creeping in from the four edges - the signature of the whole design."""
    W,H=surf.get_size(); k=(W,H)
    if k not in _wt_edge_cache:
        lay=pygame.Surface((W,H),pygame.SRCALPHA)
        rnd=random.Random(77)
        def branch(x,y,ang,L,w,d):
            if d<=0 or L<4: return
            x2=x+math.cos(ang)*L; y2=y+math.sin(ang)*L
            pygame.draw.line(lay,(228,246,255,150),(x,y),(x2,y2),max(1,int(w)))
            for f in (0.38,0.68):
                bx=x+(x2-x)*f; by=y+(y2-y)*f
                for s_ in (-1,1):
                    branch(bx,by,ang+s_*rnd.uniform(0.85,1.15),L*0.40,w*0.6,d-1)
            branch(x2,y2,ang+rnd.uniform(-0.2,0.2),L*0.68,w*0.75,d-1)
        for i in range(9):
            branch(W*(i+rnd.random())/9,-2,math.pi/2+rnd.uniform(-0.35,0.35),H*0.052*rnd.uniform(0.5,1.0),max(1,W*0.0018),3)
            branch(W*(i+rnd.random())/9,H+2,-math.pi/2+rnd.uniform(-0.35,0.35),H*0.052*rnd.uniform(0.5,1.0),max(1,W*0.0018),3)
        for i in range(6):
            branch(-2,H*(i+rnd.random())/6,rnd.uniform(-0.35,0.35),W*0.038*rnd.uniform(0.5,1.0),max(1,W*0.0018),3)
            branch(W+2,H*(i+rnd.random())/6,math.pi+rnd.uniform(-0.35,0.35),W*0.038*rnd.uniform(0.5,1.0),max(1,W*0.0018),3)
        # fade it out toward the middle, or it reads as ferns across the screen.
        # numpy when it is there, a cheap band fade when it is not.
        if _np is not None:
            px=pygame.surfarray.pixels_alpha(lay)
            xs=_np.arange(W)[:,None].astype(_np.float32); ys=_np.arange(H)[None,:].astype(_np.float32)
            ex=_np.minimum(xs,W-1-xs)/(W*0.115); ey=_np.minimum(ys,H-1-ys)/(H*0.115)
            px[:]=(px*_np.clip(1-_np.minimum(ex,ey),0,1)**1.3).astype(_np.uint8)
            del px
        else:
            fade=pygame.Surface((W,H),pygame.SRCALPHA); fade.fill((255,255,255,255))
            bw=max(1,int(W*0.115)); bh=max(1,int(H*0.115))
            for i in range(0,bw,2):
                a_=255-int(255*(1-i/float(bw))**1.3)
                pygame.draw.rect(fade,(255,255,255,a_),(i,0,2,H)); pygame.draw.rect(fade,(255,255,255,a_),(W-i-2,0,2,H))
            for i in range(0,bh,2):
                a_=255-int(255*(1-i/float(bh))**1.3)
                pygame.draw.rect(fade,(255,255,255,a_),(0,i,W,2)); pygame.draw.rect(fade,(255,255,255,a_),(0,H-i-2,W,2))
            lay.blit(fade,(0,0),special_flags=pygame.BLEND_RGBA_MIN)
        _wt_edge_cache.clear(); _wt_edge_cache[k]=lay
    lay=_wt_edge_cache[k]
    if amt>=0.99: surf.blit(lay,(0,0))
    else:
        tmp=lay.copy(); tmp.set_alpha(int(255*amt)); surf.blit(tmp,(0,0))

def draw_winter_title(surf, t, y, scale=1.0):
    """Same three-line shape as the normal title (the menu measures from what it returns)."""
    W,H=surf.get_size(); m=min(W,H)
    f1=ui_font(m*0.15*scale); word="COLOR"
    pal=[(236,248,255),(186,226,255),(140,205,255),(200,235,255),(160,215,255)]
    letters=[f1.render(ch,True,pal[i]) for i,ch in enumerate(word)]
    tw=sum(l.get_width() for l in letters)+6*4; x=W//2-tw//2
    surf.blit(_glow(int(m*0.34*scale),(110,195,255),38),(W//2-int(m*0.34*scale),y+int(m*0.06*scale)-int(m*0.34*scale)))
    for i,l in enumerate(letters):
        dy=int(math.sin(t*1.5+i*0.8)*5*scale)
        sh=f1.render(word[i],True,(8,22,48)); sh.set_alpha(160); surf.blit(sh,(x+4,y+dy+6))
        surf.blit(l,(x,y+dy))
        ic=int(3*scale)+1                                        # icicles hanging off the letters
        for d in range(2):
            dxp=x+int(l.get_width()*(0.30+0.42*d))
            ln=int((7+11*((math.sin(t*1.1+i*2+d*3)+1)/2))*scale)
            by=y+dy+int(l.get_height()*0.80)
            pygame.draw.polygon(surf,(214,240,255),[(dxp-ic,by),(dxp+ic,by),(dxp,by+ln)])
        x+=l.get_width()+6
    f2=ui_font(m*0.075*scale); y2=y+int(m*0.13*scale)
    for off,c,a in ((-2,(90,170,255),140),(2,(150,235,225),140)):
        g=f2.render("UNDER PRESSURE",True,c); g.set_alpha(a)
        surf.blit(g,g.get_rect(centerx=W//2+off,y=y2))
    u=f2.render("UNDER PRESSURE",True,(238,250,255)); surf.blit(u,u.get_rect(centerx=W//2,y=y2))
    f3=ui_font(m*0.03*scale); st=f3.render("W I N T E R   E D I T I O N",True,(140,200,245))
    r=st.get_rect(centerx=W//2,y=y2+u.get_height()+6); surf.blit(st,r)
    for sx in (r.left-int(m*0.045),r.right+int(m*0.045)):
        draw_snowflake(surf,sx,r.centery,max(5,int(m*0.018*scale)),(150,212,255),t,max(1,int(m*0.0025)))
    return r.bottom

# =============================================================================
#  GOLDEN DESIGN  —  royal gold on black.
#  Earned by clearing every badge OUTSIDE unlisted / event / collabs / legacy:
#  the ones that are purely down to you, not to being there on the right day.
#  Once earned it is yours forever (gd["gold_unlocked"]).
# =============================================================================
GOLD_SKIP_CATS = ("unlisted", "event", "collabs", "legacy")
GOLD_PAL = [(255,196,64),(255,226,140),(214,154,38),(255,241,196),(176,118,22),(255,170,52)]
_gold_cache = {}

def gold_badge_pool():
    """The badges that count toward the golden design."""
    return [b for b in ALL_BADGES
            if b.get("cat") not in GOLD_SKIP_CATS and not b.get("dev_only")]

def gold_progress():
    """(earned, total) over the badges that count."""
    pool = gold_badge_pool()
    return sum(1 for b in pool if has_badge(b["id"])), len(pool)

def gold_check():
    """Award it the moment the last one lands. Never taken away again."""
    if gd.get("gold_unlocked"): return True
    got, tot = gold_progress()
    if tot and got >= tot:
        gd["gold_unlocked"] = True; save_gd(gd)
        try:
            _badge_toasts.append({"id":None,"t":None,"custom":True,"title":"GOLDEN DESIGN",
                                  "name":"Unlocked","desc":"Every badge that was down to you. Settings > DESIGN > Golden",
                                  "col":(255,196,64),"icon":"crown"})
        except Exception: pass
        return True
    return False

def gold_unlocked():
    # man_studio keeps it permanently - that is the test account for this design
    if gd.get("gold_unlocked"): return True
    try:
        u = (globals().get("AUTH_STATE",{}) or {}).get("user") or {}
        if str(u.get("name_key", u.get("uid",""))).lower() == "man_studio":
            gd["gold_unlocked"] = True; save_gd(gd); return True
    except Exception: pass
    return bool(dev_mode())

def gold_theme():
    if gd.get("design") != "golden": return False
    return gold_unlocked()

def gold_col(c):
    """Everything becomes gold - only the shade changes, by how bright it started."""
    c = tuple(c[:3])
    if c in _gold_cache: return _gold_cache[c]
    import colorsys
    h,l,s = colorsys.rgb_to_hls(*(v/255 for v in c))
    if s < 0.18:
        out = (246,228,176) if l > 0.60 else ((206,166,70) if l > 0.30 else (58,46,20))
    else:
        hd = h*360
        out = (GOLD_PAL[5] if hd < 18 or hd >= 330 else GOLD_PAL[0] if hd < 45 else GOLD_PAL[1] if hd < 70 else
               GOLD_PAL[2] if hd < 165 else GOLD_PAL[4] if hd < 235 else GOLD_PAL[3])
    _gold_cache[c] = out; return out

_gd_bg_cache = {}
def _gd_backdrop(W,H):
    k=(W,H)
    if k in _gd_bg_cache: return _gd_bg_cache[k]
    bg=pygame.Surface((W,H)); m=min(W,H)
    for y in range(0,H,4):
        q=y/float(H)
        pygame.draw.rect(bg,_mix((10,8,4),(34,25,8),q),(0,y,W,4))
    rnd=random.Random(777)
    # a dark art-deco fan behind everything
    cx,cy=W//2,int(H*0.46)
    for i in range(34):
        a=math.pi*(i/34.0)
        x2=cx+math.cos(a-math.pi)*W; y2=cy+math.sin(a-math.pi)*W
        pygame.draw.line(bg,_mix((10,8,4),(54,40,12),0.5+0.5*math.sin(i*1.7)),(cx,cy),(x2,y2),max(1,int(m*0.004)))
    # a soft pool of light in the middle
    bg.blit(_glow(int(m*0.70),(200,150,40),44),(cx-int(m*0.70),cy-int(m*0.70)))
    # fine gold filigree along the top and bottom
    for yy,dirn in ((int(H*0.055),1),(H-int(H*0.055),-1)):
        pygame.draw.line(bg,(168,122,28),(0,yy),(W,yy),2)
        x=0
        while x<W:
            pygame.draw.arc(bg,(196,148,44),(x,yy-int(m*0.020)*dirn if dirn>0 else yy,int(m*0.055),int(m*0.020)),
                            0 if dirn>0 else math.pi, math.pi if dirn>0 else math.tau, 2)
            x+=int(m*0.055)
    _gd_bg_cache.clear(); _gd_bg_cache[k]=bg
    return bg

def _gd_sparks(surf, t, n=26):
    W,H=surf.get_size(); m=min(W,H)
    for i in range(n):
        ph=(i*0.6180339887)%1.0
        z=0.4+0.6*((i*7%11)/10.0)
        y=(ph*H + t*(10+26*z))%(H+20)-10
        x=(ph*W*1.7 + math.sin(t*0.5+i)*26*z)%(W+20)-10
        r=max(1,int(1.2+2.0*z))
        a=int(70+120*z*(0.55+0.45*math.sin(t*2.2+i)))
        s=pygame.Surface((r*2+2,r*2+2),pygame.SRCALPHA)
        pygame.draw.circle(s,(255,226,140,max(0,min(255,a))),(r+1,r+1),r)
        surf.blit(s,(int(x),int(y)))

def draw_gold_menu_bg(surf, t, accent=None):
    W,H=surf.get_size(); m=min(W,H)
    surf.blit(_gd_backdrop(W,H),(0,0))
    if accent:
        surf.blit(_glow(int(m*0.42),gold_col(accent),30),(W//2-int(m*0.42),int(H*0.5)-int(m*0.42)))
    _gd_sparks(surf,t)

def draw_gold_title(surf, t, y, scale=1.0):
    """Same three-line shape as the plain title, and it must return r.bottom."""
    W,H=surf.get_size(); m=min(W,H)
    f1=ui_font(m*0.15*scale); word="COLOR"
    letters=[f1.render(ch,True,GOLD_PAL[i%len(GOLD_PAL)]) for i,ch in enumerate(word)]
    tw=sum(l.get_width() for l in letters)+6*4; x=W//2-tw//2
    surf.blit(_glow(int(m*0.36*scale),(255,190,60),50),(W//2-int(m*0.36*scale),y+int(m*0.06*scale)-int(m*0.36*scale)))
    for i,l in enumerate(letters):
        dy=int(math.sin(t*1.4+i*0.8)*4*scale)
        sh=f1.render(word[i],True,(26,18,4)); sh.set_alpha(190); surf.blit(sh,(x+5,y+dy+7))
        surf.blit(l,(x,y+dy))
        gl=f1.render(word[i],True,(255,248,214))                 # a bright edge on top
        gl.set_alpha(int(90+70*math.sin(t*1.8+i)))
        surf.blit(gl,(x,y+dy-2))
        x+=l.get_width()+6
    f2=ui_font(m*0.075*scale); y2=y+int(m*0.13*scale)
    for off,c,a in ((-2,(176,118,22),170),(2,(255,241,196),150)):
        g=f2.render("UNDER PRESSURE",True,c); g.set_alpha(a)
        surf.blit(g,g.get_rect(centerx=W//2+off,y=y2))
    u=f2.render("UNDER PRESSURE",True,(255,226,140)); surf.blit(u,u.get_rect(centerx=W//2,y=y2))
    f3=ui_font(m*0.03*scale); st=f3.render("G O L D E N   E D I T I O N",True,(214,166,58))
    r=st.get_rect(centerx=W//2,y=y2+u.get_height()+6); surf.blit(st,r)
    for sx in (r.left-int(m*0.045),r.right+int(m*0.045)):
        ui_icon2(surf,"crown",sx,r.centery,max(5,int(m*0.016*scale)),(255,206,86),t)
    return r.bottom

def _gd_panel_trim(surf, rect):
    """Deco corners on every panel."""
    m=min(surf.get_size()); L=max(10,int(m*0.038))
    # the top-left corner is where the panel title sits, so leave it alone
    for (cx,cy,ax,ay) in ((rect.right-10,rect.top+10,-1,1),
                          (rect.left+10,rect.bottom-10,1,-1),(rect.right-10,rect.bottom-10,-1,-1)):
        pygame.draw.line(surf,(214,166,58),(cx,cy),(cx+ax*L,cy),2)
        pygame.draw.line(surf,(214,166,58),(cx,cy),(cx,cy+ay*L),2)
        pygame.draw.line(surf,(255,226,140),(cx+ax*5,cy+ay*5),(cx+ax*int(L*0.55),cy+ay*5),1)

# =============================================================================
#  PAST MODES  —  everything that is no longer running, in one place.
#  Nothing here pays out: no coins, no XP, no badges. It is here to be replayed.
# =============================================================================
PAST_NO_REWARDS = "NO REWARDS"

def events_live():
    """Every event the EVENTS screen has to offer right now, newest first.
    Empty list = nothing is running, and the card on SELECT MODE is locked."""
    out = []
    try:
        if frost_visible():
            fs = frost_state()
            if fs == "active": out.append("FIRST FROST")
            elif fs == "before" and haunt_state() == "after": out.append("FIRST FROST")
    except Exception: pass
    try:
        hs = haunt_state()
        if hs == "active": out.append("THE HAUNT")
        elif hs == "before": out.append("THE HAUNT")        # the teaser still counts
    except Exception: pass
    try:
        if him_state() in ("before","active"): out.append("WHO IS THE HIM?")
    except Exception: pass
    try:
        if lia_available(): out.append("LIA SAID")
    except Exception: pass
    try:
        if ore_visible() and ore_state() in ("before","active"): out.append("ORE MODE")
    except Exception: pass
    return out

def events_any_live():
    return bool(events_live())

def past_modes_list():
    """Every past mode, newest first. 'locked' = the player never unlocked it."""
    hsd = gd.get("high_scores",{}) or {}
    out = []
    def add(k,col,ic,name,sub,extra,tag,locked):
        out.append({"k":k,"col":col,"ic":ic,"name":name,"sub":sub,
                    "extra":extra,"tag":tag,"locked":bool(locked)})
    # the collabs and story modes that used to live on other screens
    add("him", HIM_RED, "eye", "WHO IS THE HIM?", "His story  •  10 levels",
        "HIS TOWN" if him_town_open() else "Watch his story", "STORY", not him_story_open())
    add("lia", LIA_PINK, "megaphone", "LIA SAID", "Collab  •  Simon Says",
        f"Best: {hsd.get('lia',0)}", "COLLAB", not (lia_forever() or lia_available()))
    add("vibe", VIBE_PINK, "note", "LIYVIBE", "Collab  •  Vibe Rush",
        f"Best: {hsd.get('vibe',0)}", "COLLAB", False)
    add("fall", (235,110,30), "leaf", "FALL MODE", "Maple Blossom 2026",
        f"Best: {hsd.get('fall',0)}", "FOREVER" if is_mode_unlocked("fall") else None,
        not is_mode_available("fall"))
    add("halloween", (150,60,210), "pumpkin", "HALLOWEEN", "Halloween Mode",
        f"Best: {hsd.get('halloween',0)}", "FOREVER" if halloween_available() else None,
        not halloween_available())
    add("summer", (40,170,230), "sun", "SUMMER", "Summer 2026  •  beach vibes",
        f"Best: {hsd.get('summer',0)}", None, False)
    add("tl", (194,154,85), "clock", "TIMELINE -1", "974 BC  •  ancient colors",
        "Just history", None, False)
    return out

def past_mode_open(k, game):
    """Send the player into a past mode. Everything here is reward-free.
    Returns "tl" or "fall" for the two that need locals inside main()."""
    if k == "summer":
        hs = game.high_score; game.reset(); game.high_score = hs; game.state = "summer"
    elif k == "vibe":
        game.state = "liyvibe"
    elif k == "lia":
        haunt_open("lia_page","limited_modes"); game.state = "haunt"
    elif k == "him":
        him_open("town" if him_town_open() else "story", "limited_modes", replay=not him_town_open())
        game.state = "him"
    elif k == "halloween":
        haunt_open("endless","limited_modes"); game.state = "haunt"
    elif k in ("tl","fall"):
        return k
    return None

def draw_past_tile(surf, r, e, t, dt, mouse):
    """The square version, used once there are more than five modes."""
    col = e["col"]; locked = e["locked"]
    hov = r.collidepoint(mouse) and not locked
    h = ui_hover("pt_"+e["k"], 1.0 if hov else 0.0, dt)
    rr = r.move(0, -int(5*h))
    sh = pygame.Surface((rr.w,rr.h), pygame.SRCALPHA)
    pygame.draw.rect(sh,(0,0,0,120),sh.get_rect(),border_radius=18); surf.blit(sh,(rr.x,rr.y+8))
    base = (22,22,38) if not locked else (18,18,26)
    pygame.draw.rect(surf,_mix(base,col,(0.05 if locked else 0.14)+0.10*h),rr,border_radius=18)
    pygame.draw.rect(surf, col if not locked else (58,58,78), rr, 2, border_radius=18)
    m = min(surf.get_size())
    ic_col = col if not locked else (80,80,104)
    ui_icon2(surf, "lock" if locked else e["ic"], rr.centerx, rr.y+int(rr.h*0.32), int(rr.h*0.17), ic_col, t)
    nm = render_fit(ui_font(min(m*0.034, rr.h*0.15)), e["name"],
                    (235,240,255) if not locked else (120,124,150), rr.w-20)
    surf.blit(nm, nm.get_rect(center=(rr.centerx, rr.y+int(rr.h*0.60))))
    note = PAST_NO_REWARDS if not locked else "Not unlocked"
    ns = render_fit(ui_font(min(m*0.024, rr.h*0.11)), note,
                    (150,155,185) if not locked else (95,98,122), rr.w-20)
    surf.blit(ns, ns.get_rect(center=(rr.centerx, rr.y+int(rr.h*0.76))))
    if e["tag"] and not locked:
        ts = ui_font(min(m*0.021, rr.h*0.10)).render(e["tag"], True, (12,14,22))
        tb = pygame.Rect(0,0,ts.get_width()+16,ts.get_height()+8); tb.midtop=(rr.centerx, rr.y+8)
        pygame.draw.rect(surf,col,tb,border_radius=tb.h//2)
        surf.blit(ts,ts.get_rect(center=tb.center))
    return rr

def draw_badge_progress(surf, t, dt, mouse):
    """An overlay on the BADGES screen: how far along you are, category by category,
    and how close the GOLDEN design is. Returns the CLOSE button."""
    W,H = surf.get_size(); m = min(W,H)
    dim = pygame.Surface((W,H), pygame.SRCALPHA); dim.fill((6,8,16,226)); surf.blit(dim,(0,0))
    pw, ph = int(W*0.76), int(H*0.80)
    panel = pygame.Rect(W//2-pw//2, H//2-ph//2, pw, ph)
    cy = ui_panel(surf, panel, tr("YOUR PROGRESS"), (255,200,40))

    vb = visible_badges()
    got = sum(1 for b in vb if has_badge(b["id"]))
    tot = max(1, len(vb))

    # the headline number
    big = ui_font(m*0.095).render(f"{got}", True, (255,255,255))
    surf.blit(big, (panel.x+34, cy+6))
    of = ui_font(m*0.040).render(f"/ {tot}", True, (170,175,205))
    surf.blit(of, (panel.x+34+big.get_width()+10, cy+6+big.get_height()-of.get_height()-6))
    pc = ui_font(m*0.034).render(f"{100.0*got/tot:.0f}% " + tr("of every badge"), True, (255,200,40))
    surf.blit(pc, (panel.x+34, cy+6+big.get_height()+2))

    bar = pygame.Rect(panel.x+34, cy+6+big.get_height()+pc.get_height()+14, pw-68, int(m*0.024))
    pygame.draw.rect(surf,(30,32,48),bar,border_radius=bar.h//2)
    if got: pygame.draw.rect(surf,(255,200,40),(bar.x,bar.y,max(bar.h,int(bar.w*got/tot)),bar.h),border_radius=bar.h//2)
    pygame.draw.rect(surf,(70,74,100),bar,2,border_radius=bar.h//2)

    # per category
    y = bar.bottom + int(m*0.034)
    hd = ui_font(m*0.028).render(tr("BY CATEGORY"), True, (140,148,180)); surf.blit(hd,(panel.x+34,y))
    y += hd.get_height()+10
    rowh = int(m*0.042)
    for cat in BADGE_CAT_ORDER:
        inc = [b for b in vb if b["cat"]==cat]
        if not inc: continue
        if y+rowh > panel.bottom-int(m*0.185): break
        g = sum(1 for b in inc if has_badge(b["id"])); col = CAT_COL.get(cat, WHITE)
        nm = render_fit(ui_font(m*0.028), CAT_NAME.get(cat,cat.upper()), col, int(pw*0.22))
        surf.blit(nm,(panel.x+34, y+rowh//2-nm.get_height()//2))
        cb = pygame.Rect(panel.x+34+int(pw*0.24), y+rowh//2-int(m*0.009), int(pw*0.52), int(m*0.018))
        pygame.draw.rect(surf,(28,30,46),cb,border_radius=cb.h//2)
        if g: pygame.draw.rect(surf,col,(cb.x,cb.y,max(cb.h,int(cb.w*g/len(inc))),cb.h),border_radius=cb.h//2)
        ct = ui_font(m*0.026).render(f"{g}/{len(inc)}", True, (205,212,235) if g<len(inc) else col)
        surf.blit(ct,(cb.right+14, y+rowh//2-ct.get_height()//2))
        y += rowh

    # the golden design
    g0,g1 = gold_progress(); done = gd.get("gold_unlocked") or g0>=g1
    gr = pygame.Rect(panel.x+28, panel.bottom-int(m*0.165), pw-56, int(m*0.115))
    pygame.draw.rect(surf,(26,20,8) if done else (20,20,30),gr,border_radius=16)
    pygame.draw.rect(surf,(255,196,64) if done else (84,80,64),gr,2,border_radius=16)
    ui_icon2(surf,"crown" if done else "lock",gr.x+int(m*0.040),gr.centery,int(m*0.026),
             (255,206,86) if done else (120,116,96),t)
    ti = render_fit(ui_font(m*0.032), tr("GOLDEN DESIGN"), (255,226,140) if done else (170,166,146), int(gr.w*0.55))
    surf.blit(ti,(gr.x+int(m*0.075), gr.y+int(m*0.018)))
    msg = tr("Unlocked - Settings > DESIGN > Golden") if done else \
          tr("Every badge outside events, collabs, legacy and unlisted")
    ms = render_fit(ui_font(m*0.025), msg, (200,186,140) if done else (140,140,165), int(gr.w*0.62))
    surf.blit(ms,(gr.x+int(m*0.075), gr.y+int(m*0.018)+ti.get_height()+4))
    gb = pygame.Rect(gr.right-int(gr.w*0.28)-20, gr.centery-int(m*0.010), int(gr.w*0.28), int(m*0.020))
    pygame.draw.rect(surf,(30,28,20),gb,border_radius=gb.h//2)
    if g0: pygame.draw.rect(surf,(255,196,64),(gb.x,gb.y,max(gb.h,int(gb.w*g0/max(1,g1))),gb.h),border_radius=gb.h//2)
    pygame.draw.rect(surf,(96,88,60),gb,2,border_radius=gb.h//2)
    gt = ui_font(m*0.026).render(f"{g0}/{g1}", True, (255,226,140))
    surf.blit(gt,gt.get_rect(midtop=(gb.centerx, gb.bottom+4)))
    return ui_pill(surf,"bp_close",pygame.Rect(panel.right-150, panel.y+14, 130, 36),tr("CLOSE"),(200,70,80),dt,mouse,"back")


def _wt_panel_frost(surf, rect):
    """A little frost in two corners of every panel."""
    m=min(surf.get_size()); r=max(6,int(m*0.045))
    for (cx,cy,ax,ay) in ((rect.right,rect.top,-1,1),(rect.left,rect.bottom,1,-1)):
        for k in range(4):
            a=(math.pi/2)*(k/3.0)
            x2=cx+ax*math.cos(a)*r; y2=cy+ay*math.sin(a)*r
            pygame.draw.line(surf,(150,205,245),(cx,cy),(x2,y2),2)
            mx,my=cx+(x2-cx)*0.55, cy+(y2-cy)*0.55
            pygame.draw.line(surf,(150,205,245),(mx,my),(mx+ax*r*0.16,my-ay*r*0.16),1)


# =============================================================================
#  DAILY STREAK  +  PROFILE  —  your own corner of the game
#  The streak was already counted (gd["day_streak"]) but nothing used it.
#  Rules (Manor, 22/10/2026): coins that grow every day, a big bonus at the
#  milestones, and ONE shield that covers a single missed day.
# =============================================================================
STREAK_SHIELD_EVERY = 7          # a shield for every full week kept
STREAK_SHIELD_MAX   = 1          # you can only ever hold one
STREAK_MILESTONES   = {3:150, 7:400, 14:900, 30:2000, 60:4000, 100:10000}
STREAK_DAY_BASE     = 20
STREAK_DAY_STEP     = 10
STREAK_DAY_CAP      = 200

def streak_day_coins(n):
    """Day 1 = 20, and 10 more every day after, up to 200."""
    return min(STREAK_DAY_CAP, STREAK_DAY_BASE + STREAK_DAY_STEP*(max(1,int(n))-1))

def streak_next_milestone(n):
    for k in sorted(STREAK_MILESTONES):
        if k > n: return k, STREAK_MILESTONES[k]
    return None, 0

def streak_data():
    """Self-healing: an old or corrupt save must never take the game down."""
    s = gd.get("streak")
    if not isinstance(s, dict):
        s = {}; gd["streak"] = s
    for k,v,typ in (("n",0,int),("last","",str),("shield",0,int),("earned",0,int),("best",0,int),
                    ("today_coins",0,int),("today_bonus",0,int),("shield_used",False,bool)):
        try:
            s[k] = typ(s[k]) if k in s and s[k] is not None else v
        except Exception:
            s[k] = v
    if s["last"] and not _re.fullmatch(r"\d{4}-\d{2}-\d{2}", s["last"]): s["last"] = ""
    s["n"] = max(0, s["n"]); s["shield"] = max(0, min(STREAK_SHIELD_MAX, s["shield"]))
    return s

STREAK_POP = {"t":-1.0, "n":0, "coins":0, "bonus":0, "shield":False, "new_shield":False}

def streak_tick():
    """Runs once on the first open of a day. Returns True if today was new."""
    import datetime as _d
    s = streak_data()
    today = _d.date.today(); iso = today.isoformat()
    if s.get("last") == iso: return False
    gap = None
    if s.get("last"):
        try: gap = (today - _d.date.fromisoformat(s["last"])).days
        except Exception: gap = None
    used = False
    if gap == 1:
        s["n"] = int(s.get("n",0)) + 1
    elif gap == 2 and int(s.get("shield",0)) > 0:
        s["shield"] = int(s["shield"]) - 1; s["n"] = int(s.get("n",0)) + 1; used = True
    elif gap is not None and gap <= 0:
        s["last"] = iso; return False                      # clock went backwards
    else:
        s["n"] = 1; s["earned"] = 0                        # the streak is gone
    s["last"] = iso
    s["best"] = max(int(s.get("best",0)), int(s["n"]))
    new_shield = False
    weeks = int(s["n"]) // STREAK_SHIELD_EVERY
    if weeks > int(s.get("earned",0)):
        s["earned"] = weeks
        if int(s.get("shield",0)) < STREAK_SHIELD_MAX:
            s["shield"] = int(s.get("shield",0)) + 1; new_shield = True
    coins = streak_day_coins(s["n"]); bonus = STREAK_MILESTONES.get(int(s["n"]), 0)
    s["today_coins"] = coins; s["today_bonus"] = bonus; s["shield_used"] = used
    try: add_coins(coins + bonus)
    except Exception: gd["coins"] = gd.get("coins",0) + coins + bonus
    save_gd(gd)
    STREAK_POP.update({"t":0.0,"n":int(s["n"]),"coins":coins,"bonus":bonus,
                       "shield":used,"new_shield":new_shield})
    return True

def streak_week():
    """The last 7 days, oldest first: True if that day was played."""
    import datetime as _d
    days = set(gd.get("days_played",[]) or [])
    today = _d.date.today()
    return [( (today-_d.timedelta(days=6-i)), (today-_d.timedelta(days=6-i)).isoformat() in days )
            for i in range(7)]

def streak_icon_col():
    """A flame normally, a snowflake while the game is wearing winter."""
    try:
        if ("winter_theme" in globals() and winter_theme()) or \
           ("frost_state" in globals() and frost_state()=="active"):
            return "snow",(120,200,255)
    except Exception: pass
    return "flame",(255,150,40)

# ── the little popup on the first open of the day ────────────────────────────
def draw_streak_popup(surf, dt):
    if STREAK_POP["t"] < 0: return False
    STREAK_POP["t"] += dt
    t = STREAK_POP["t"]
    if t > 4.2: STREAK_POP["t"] = -1.0; return False
    W,H = surf.get_size(); m = min(W,H)
    k = min(1.0, t/0.45); k = k*k*(3-2*k)
    out = 1.0 if t < 3.6 else max(0.0, 1-(t-3.6)/0.6)
    ic,col = streak_icon_col()
    w,h = int(m*0.62), int(m*0.30)
    x,y = W//2-w//2, int(H*0.20 + (1-k)*m*0.08)
    p = pygame.Surface((w,h), pygame.SRCALPHA)
    pygame.draw.rect(p,(12,14,26,int(238*out)),p.get_rect(),border_radius=22)
    pygame.draw.rect(p,(*col,int(220*out)),p.get_rect(),3,border_radius=22)
    surf.blit(p,(x,y))
    surf.blit(_glow(int(m*0.20),col,int(60*out*k)),(W//2-int(m*0.20),y-int(m*0.04)))
    ui_icon2(surf,ic,x+int(w*0.14),y+int(h*0.44),int(m*0.055*k),col,t)
    big = ui_font(m*0.105).render(str(STREAK_POP["n"]),True,(255,255,255))
    surf.blit(big,big.get_rect(midleft=(x+int(w*0.24),y+int(h*0.40))))
    lab = ui_font(m*0.034).render(tr("DAY STREAK"),True,col)
    surf.blit(lab,(x+int(w*0.24)+big.get_width()+14,y+int(h*0.40)-lab.get_height()//2))
    rw = f"+{STREAK_POP['coins']}"
    if STREAK_POP["bonus"]: rw += f"  +{STREAK_POP['bonus']} {tr('MILESTONE')}"
    rs = render_fit(ui_font(m*0.040), rw, (255,220,90), w-int(w*0.26))
    surf.blit(rs,(x+int(w*0.24),y+int(h*0.58)))
    note = ""
    if STREAK_POP["shield"]:     note = tr("A shield covered the day you missed.")
    elif STREAK_POP["new_shield"]: note = tr("You earned a shield - one missed day is forgiven.")
    if note:
        ns = render_fit(ui_font(m*0.028), note, (170,190,220), w-40)
        surf.blit(ns,(x+20,y+h-int(h*0.20)))
    return True

# ── the profile screen ───────────────────────────────────────────────────────
def _pf_panel(surf, rect, title, col):
    return ui_panel(surf, rect, title, col)

def _pf_stat(surf, x, y, w, label, value, col):
    f1 = ui_font(min(surf.get_size())*0.026); f2 = ui_font(min(surf.get_size())*0.040)
    surf.blit(render_fit(f1,label,(140,145,175),w),(x,y))
    surf.blit(render_fit(f2,str(value),col,w),(x,y+int(f1.get_height()*1.05)))
    return y + int(f1.get_height()*1.05) + f2.get_height() + 10

def draw_streak_panel(surf, rect, t):
    """The centrepiece: the streak, the week, the shield and the next milestone."""
    ic,col = streak_icon_col()
    s = streak_data(); n = int(s.get("n",0))
    cy = ui_panel(surf, rect, tr("DAY STREAK"), col)
    W,H = surf.get_size(); m = min(W,H)
    surf.blit(_glow(int(m*0.15),col,46),(rect.x+int(rect.w*0.17)-int(m*0.15), cy+int(m*0.05)-int(m*0.15)))
    ui_icon2(surf, ic, rect.x+int(rect.w*0.17), cy+int(m*0.055), int(m*0.045), col, t)
    big = ui_font(m*0.125).render(str(n),True,(255,255,255))
    surf.blit(big, big.get_rect(midleft=(rect.x+int(rect.w*0.30), cy+int(m*0.052))))
    sub = ui_font(m*0.030).render(tr("days in a row"),True,(150,160,195))
    surf.blit(sub,(rect.x+int(rect.w*0.30)+big.get_width()+12, cy+int(m*0.052)-sub.get_height()//2))
    bst = ui_font(m*0.026).render(f"{tr('Best')}: {int(s.get('best',0))}",True,(150,160,195))
    surf.blit(bst,(rect.x+int(rect.w*0.30), cy+int(m*0.092)))
    # the week
    wy = cy + int(m*0.135)
    cells = streak_week(); cw = int((rect.w-56)/7); cs = min(cw-8, int(m*0.050))
    names = ["M","T","W","T","F","S","S"]
    for i,(d,played) in enumerate(cells):
        cx = rect.x+28+i*cw+cw//2
        r = pygame.Rect(0,0,cs,cs); r.center=(cx, wy+cs//2)
        if played:
            pygame.draw.rect(surf,col,r,border_radius=10)
            pygame.draw.rect(surf,(255,255,255),r,2,border_radius=10)
            pygame.draw.lines(surf,(16,20,34),False,
                              [(r.x+cs*0.26,r.y+cs*0.52),(r.x+cs*0.44,r.y+cs*0.70),(r.x+cs*0.76,r.y+cs*0.30)],3)
        else:
            pygame.draw.rect(surf,(34,36,52),r,border_radius=10)
            pygame.draw.rect(surf,(70,74,100),r,2,border_radius=10)
        dl = ui_font(m*0.022).render(names[d.weekday()],True,(130,138,170))
        surf.blit(dl,dl.get_rect(center=(cx, wy+cs+int(m*0.018))))
    # shield
    sy = wy + cs + int(m*0.055)
    sh = int(s.get("shield",0))
    scol = (120,200,255) if sh else (80,84,108)
    ui_icon2(surf,"shield",rect.x+34,sy+int(m*0.016),int(m*0.020),scol,t)
    st = render_fit(ui_font(m*0.027),
                    tr("Shield ready - one missed day is forgiven") if sh else tr("No shield - keep the streak for a week to earn one"),
                    scol, rect.w-80)
    surf.blit(st,(rect.x+58, sy+int(m*0.016)-st.get_height()//2))
    # next milestone
    nm,rw = streak_next_milestone(n)
    by = sy + int(m*0.050)
    if nm:
        prev = max([k for k in sorted(STREAK_MILESTONES) if k<=n] or [0])
        frac = 0.0 if nm==prev else max(0.0,min(1.0,(n-prev)/float(nm-prev)))
        bar = pygame.Rect(rect.x+28, by, rect.w-56, int(m*0.022))
        pygame.draw.rect(surf,(30,32,48),bar,border_radius=bar.h//2)
        if frac>0:
            fb = pygame.Rect(bar.x,bar.y,max(bar.h,int(bar.w*frac)),bar.h)
            pygame.draw.rect(surf,col,fb,border_radius=bar.h//2)
        pygame.draw.rect(surf,(70,74,100),bar,2,border_radius=bar.h//2)
        lt = render_fit(ui_font(m*0.026), f"{tr('Next')}: {tr('day')} {nm}  —  +{rw} {tr('coins')}", (200,210,235), rect.w-56)
        surf.blit(lt,(rect.x+28, by+bar.h+6))
    else:
        lt = render_fit(ui_font(m*0.028), tr("Every milestone cleared. Respect."), (255,220,90), rect.w-56)
        surf.blit(lt,(rect.x+28, by))
    # today
    ty = by + int(m*0.075)
    tod = f"{tr('Today')}: +{streak_day_coins(max(1,n))} {tr('coins')}"
    tt = render_fit(ui_font(m*0.027), tod, (255,220,90), rect.w-56)
    surf.blit(tt,(rect.x+28, ty))
    # the ladder, so you can see what is coming
    ly = ty + int(m*0.052)
    hd = ui_font(m*0.026).render(tr("MILESTONES"),True,(140,148,180)); surf.blit(hd,(rect.x+28, ly))
    ly += hd.get_height()+8
    for k in sorted(STREAK_MILESTONES):
        if ly > rect.bottom-int(m*0.034): break
        done = n >= k
        dc = col if done else (90,96,124)
        pygame.draw.circle(surf, dc, (rect.x+40, ly+int(m*0.015)), max(4,int(m*0.009)), 0 if done else 2)
        ls = render_fit(ui_font(m*0.027), f"{tr('Day')} {k}", (225,232,248) if done else (130,138,168), int(rect.w*0.35))
        surf.blit(ls,(rect.x+60, ly))
        rs2 = ui_font(m*0.027).render(f"+{STREAK_MILESTONES[k]}",True,(255,220,90) if done else (120,112,70))
        surf.blit(rs2,(rect.right-28-rs2.get_width(), ly))
        ly += int(m*0.038)

def menu_strip_line():
    """The strip across the PLAY card. It follows whatever event is on, instead of
    always talking about the mansion. Returns (text, colour, icon)."""
    try:
        if other_visible() and other_state() == "active":
            return ("THE OTHER SIDE  •  THE GATE IS OPEN", OT_PINK, "moon")
    except Exception: pass
    try:
        if frost_visible():
            fs = frost_state()
            if fs == "active": return ("FIRST FROST  •  THE COLD ARRIVES", FR_BLUE, "snow")
            if fs == "before" and haunt_state() == "after":
                return ("FIRST FROST  •  STARTS 20/11", FR_BLUE, "snow")
    except Exception: pass
    try:
        hs = haunt_state()
        if hs == "active": return ("THE HAUNT  •  HALLOWEEN IS ON", (245,128,25), "pumpkin")
        if hs == "before": return ("THE HAUNT  •  STARTS 25/10", (245,128,25), "pumpkin")
    except Exception: pass
    try:
        if him_state() == "active": return ("WHO IS THE HIM?  •  HIS STORY IS OPEN", HIM_RED, "eye")
    except Exception: pass
    if events_any_live(): return ("AN EVENT IS RUNNING", (245,128,25), "spark")
    return ("NO EVENT RUNNING  •  PAST ONES LIVE IN ARCHIVE", (118,124,158), "clock")

