def draw_profile(surf, t, dt, mouse, events):
    """The player's own page: who they are, the streak, and everything they have."""
    W,H = surf.get_size(); m = min(W,H)
    draw_menu_bg(surf, t)
    top = draw_header(surf, tr("PROFILE"), tr("Everything you have"), (120,205,255), t)
    gap = int(m*0.022); bot = H - int(m*0.095)
    lw = int(W*0.30); cwid = int(W*0.36)
    lx = int(W*0.035); cx = lx+lw+gap; rx = cx+cwid+gap
    rw = W-int(W*0.035)-rx

    # ---- who you are ----
    idr = pygame.Rect(lx, top, lw, int((bot-top)*0.46))
    cy = ui_panel(surf, idr, tr("PLAYER"), (235,70,160))
    pn = "Guest" if is_guest() else gd.get("player_name","Player")
    rp = gd.get("rank_points",0); rname,rcol = get_rank(rp)
    av = (idr.x+int(m*0.075), cy+int(m*0.072))
    pygame.draw.circle(surf, rcol, av, int(m*0.055))
    pygame.draw.circle(surf, (255,255,255), av, int(m*0.055), 3)
    ini = ui_font(m*0.075).render((pn[:1] or "P").upper(), True, (18,14,28))
    surf.blit(ini, ini.get_rect(center=av))
    draw_equipped_badge(surf, av[0]+int(m*0.042), av[1]+int(m*0.040), int(m*0.024))
    ny = cy + int(m*0.145)
    def mid(sfc, y):
        surf.blit(sfc, sfc.get_rect(midtop=(idr.centerx, y)))
        return y + sfc.get_height() + int(m*0.012)
    ny = mid(render_fit(ui_font(m*0.050), pn, WHITE, idr.w-40), ny)
    ttl = gd.get("current_title","")
    if ttl: ny = mid(render_fit(ui_font(m*0.030), f'"{ttl}"', (200,160,255), idr.w-40), ny)
    ny = mid(render_fit(ui_font(m*0.032), f"{rname}  •  {rp} RP", rcol, idr.w-40), ny)
    days = gd.get("days_played",[]) or []
    if days:
        ny = mid(render_fit(ui_font(m*0.025), f"{tr('Playing since')} {min(days)}", (140,148,180), idr.w-40), ny)
    if is_guest():
        ny = mid(render_fit(ui_font(m*0.026), tr("Not saved - sign in!"), (255,150,60), idr.w-40), ny)

    # ---- what you own ----
    owr = pygame.Rect(lx, idr.bottom+gap, lw, bot-(idr.bottom+gap))
    cy2 = ui_panel(surf, owr, tr("COLLECTION"), (230,160,50))
    allb = visible_badges(); got = len([b for b in allb if has_badge(b["id"])])
    y = cy2 + 10
    y = _pf_stat(surf, owr.x+22, y, owr.w-44, tr("Badges"), f"{got} / {len(allb)}", (255,205,90))
    y = _pf_stat(surf, owr.x+22, y, owr.w-44, tr("Skins"), len(set(gd.get("unlocked_skins",["Classic"]) or ["Classic"])), (150,215,255))
    y = _pf_stat(surf, owr.x+22, y, owr.w-44, tr("Coins"), gd.get("coins",0), (255,220,90))
    y = _pf_stat(surf, owr.x+22, y, owr.w-44, tr("Titles"), len(set(gd.get("unlocked_titles",[]) or [])), (200,160,255))
    _pl = int(gd.get("pass_level",0) or 0)
    y = _pf_stat(surf, owr.x+22, y, owr.w-44, tr("Color Pass"), f"{tr('Level')} {_pl}", (235,70,160))

    # ---- the streak, centre stage ----
    draw_streak_panel(surf, pygame.Rect(cx, top, cwid, bot-top), t)

    # ---- the numbers ----
    str_ = pygame.Rect(rx, top, rw, bot-top)
    cy3 = ui_panel(surf, str_, tr("STATS"), NEON["GREEN"])
    s = gd.get("stats",{}) or {}
    hs = gd.get("high_scores",{}) or {}
    corr = int(s.get("total_correct",0)); wrong = int(s.get("total_wrong",0))
    acc = f"{(100.0*corr/max(1,corr+wrong)):.0f}%" if (corr+wrong) else "-"
    pt = int(s.get("total_playtime",0)); hrs = pt//3600; mins = (pt%3600)//60
    rows = [(tr("Games played"), int(s.get("games_played",0)), (200,210,235)),
            (tr("Days played"),  len(days),                    (200,210,235)),
            (tr("Best score"),   int(hs.get("classic",0)),     (120,205,255)),
            (tr("Best combo"),   int(s.get("best_combo",0)),   (255,150,40)),
            (tr("Accuracy"),     acc,                          (120,230,140)),
            (tr("Time played"),  f"{hrs}h {mins}m" if pt else "-", (200,210,235))]
    y = cy3 + 10
    for lab,val,col in rows:
        y = _pf_stat(surf, str_.x+22, y, str_.w-44, lab, val, col)
        if y > str_.bottom-40: break
    return ui_back(surf, dt, mouse)


# =============================================================================
#  COLOR PASS SEASONS  •  SKIN SHOP  •  INVENTORY  •  HAUNT MINI TRAILER  •  SEASON 2 REVEAL
# =============================================================================
def _iso_today(): return __import__("datetime").date.today().isoformat()

def pass_season():
    """1 = Season 1 (until 24/10/2026), 2 = Season 2 NIGHTFALL (25/10-31/12/2026), 3 = Season 2 is over."""
    d=_iso_today(); s2=PASS_SEASONS[2]
    if d<s2["start"]: return 2 if dev_mode() else 1
    return 2 if d<=s2["end"] else 3

def pass2():
    p=gd.setdefault("pass2",{})
    for k,v in (("level",0),("xp",0),("premium",False),("cf",[]),("cp",[])): p.setdefault(k,v)
    return p

def pass_info():
    s=pass_season()
    if s==1:
        return {"season":1,"level":gd.get("pass_level",0),"xp":gd.get("pass_xp",0),"need":5,"premium":gd.get("has_premium",False),
                "cf":gd.setdefault("claimed_free",[]),"cp":gd.setdefault("claimed_premium",[]),"free":CP_FREE,"prem":CP_PREM,
                "max":20,"ended":False,"name":"SEASON 1","col":(255,190,40)}
    p=pass2()
    return {"season":2,"level":p["level"],"xp":p["xp"],"need":PASS_SEASONS[2]["xp"],"premium":p["premium"],"cf":p["cf"],"cp":p["cp"],
            "free":CP2_FREE,"prem":CP2_PREM,"max":PASS_SEASONS[2]["levels"],"ended":s==3,"name":"SEASON 2: NIGHTFALL","col":(160,110,255)}

def pass_premium(): return pass_info()["premium"]

def pass_add_xp(n):
    """XP goes to the season that is running now. Season 2: 10 XP a level, 30 levels."""
    s=pass_season()
    if s==1:
        gd["pass_xp"]=gd.get("pass_xp",0)+n
        while gd["pass_xp"]>=5: gd["pass_xp"]-=5; gd["pass_level"]=gd.get("pass_level",0)+1
    elif s==2:
        p=pass2(); mx=PASS_SEASONS[2]["levels"]; need=PASS_SEASONS[2]["xp"]
        if p["level"]>=mx: return
        p["xp"]+=n
        while p["xp"]>=need and p["level"]<mx: p["xp"]-=need; p["level"]+=1
        if p["level"]>=mx: p["xp"]=0

def pass_days_left():
    import datetime as _d
    end=_d.date.fromisoformat(PASS_SEASONS[2]["end"]); return max(0,(end-_d.date.fromisoformat(_iso_today())).days+1)

def merge_pass2(a, b):
    a=a or {}; b=b or {}
    best=a if (a.get("level",0),a.get("xp",0))>=(b.get("level",0),b.get("xp",0)) else b
    out=dict(best)
    for k in ("cf","cp"):
        l=list(a.get(k,[]) or [])
        for v in (b.get(k,[]) or []):
            if v not in l: l.append(v)
        out[k]=l
    out["premium"]=bool(a.get("premium") or b.get("premium"))
    return out

def skin_cost(sname):
    """(price, 'coins'/'candy') if the skin is for sale right now, else None."""
    if sname in SKIN_PRICE: return (SKIN_PRICE[sname],"coins")
    if sname in S1_SHOP_PRICE and pass_season()>=2: return (S1_SHOP_PRICE[sname],"coins")
    if sname in CANDY_SKIN_PRICE: return (CANDY_SKIN_PRICE[sname],"candy")
    return None

def shop_skins():
    lst=[s for s in SKINS if skin_cost(s)]
    return sorted(lst,key=lambda s:(skin_cost(s)[1]=="candy",skin_cost(s)[0]))

def owned_skins():
    ul=gd.get("unlocked_skins",["Classic"]) or ["Classic"]
    return [s for s in SKINS if s in ul or s=="Classic"]

def skin_source(sname):
    if sname=="Classic": return "Starter skin"
    if sname in RETIRED_SKINS: return "Season 1  •  Retired"
    if sname in S2_SKINS: return "Color Pass  •  Season 2"
    if sname in S1_SHOP_PRICE: return "Color Pass  •  Season 1" if pass_season()==1 else "Season 1  •  Skin Shop"
    if sname in SKIN_PRICE: return "Skin Shop"
    if sname=="Maple": return "Maple Blossom event"
    if sname=="Pumpkin Patch": return "THE HAUNT"
    return ""

def buy_skin(sname):
    """Returns (ok, message, colour)."""
    c=skin_cost(sname)
    if not c: return False,"Not for sale",(255,110,110)
    price,cur=c; ul=gd.setdefault("unlocked_skins",["Classic"])
    if sname in ul: return False,"You already have it",(200,200,220)
    if cur=="candy":
        if haunt_state()!="active": return False,"Candy skins are sold during THE HAUNT",(255,160,80)
        h=haunt_data()
        if h["candy"]<price: return False,f"You need {price-h['candy']} more candy",(255,110,110)
        h["candy"]-=price
    else:
        if gd.get("coins",0)<price: return False,f"You need {price-gd.get('coins',0)} more coins",(255,110,110)
        gd["coins"]-=price
    ul.append(sname); gd["current_skin"]=sname; save_gd(gd); check_skin_badges()
    if AUTH_STATE.get("user"): threading.Thread(target=cloud_save,args=("unlocked_skins",ul),daemon=True).start()
    return True,f"You bought {sname}!",(90,230,120)

_PASS_NAV={"shop_back":"pass","inv_back":"pass","sel":None}

def _season_chip(surf, cx, y, t):
    """Small animated 'SEASON 2 • NIGHTFALL • N DAYS LEFT' pill."""
    s=pass_season(); m=min(surf.get_size())
    if s==1: txt,col="SEASON 1",(255,190,40)
    elif s==2: txt,col=f"SEASON 2  •  NIGHTFALL  •  {pass_days_left()} DAYS LEFT",(170,120,255)
    else: txt,col="SEASON 2 HAS ENDED  •  SEASON 3 SOON",(150,150,180)
    f=ui_font(m*0.026); ts=f.render(txt,True,WHITE); r=ts.get_rect(centerx=cx,y=y).inflate(34,12)
    pygame.draw.rect(surf,_mix(col,(10,8,20),0.55),r,border_radius=r.h//2)
    k=(t*0.5)%1.0; gx=int(r.x+k*r.w)
    sh=pygame.Surface(r.size,pygame.SRCALPHA); pygame.draw.polygon(sh,(255,255,255,40),[(gx-r.x,0),(gx-r.x+30,0),(gx-r.x+10,r.h),(gx-r.x-20,r.h)])
    surf.blit(sh,r.topleft); pygame.draw.rect(surf,col,r,2,border_radius=r.h//2); surf.blit(ts,ts.get_rect(center=r.center))
    return r

# ── PASS hub: COLOR PASS / SKIN SHOP / INVENTORY ─────────────────────────────
def draw_pass_hub(surf, t, dt, mouse):
    W,H=surf.get_size(); pi=pass_info()
    draw_menu_bg(surf,t,(235,70,160))
    top=draw_header(surf,"PASS","Color Pass  •  Skin Shop  •  Inventory",(235,70,160),t)
    _season_chip(surf,W//2,top-4,t); top+=34
    gp=int(W*0.025); ch=max(160,H-90-top-10)
    pr=pygame.Rect(int(W*0.05),top,int(W*0.44),ch)
    rw=int(W*0.9)-pr.w-gp; sr=pygame.Rect(pr.right+gp,top,rw,(ch-gp)//2); ir=pygame.Rect(pr.right+gp,sr.bottom+gp,rw,ch-sr.h-gp)
    claim=sum(1 for i,r in enumerate(pi["free"]) if pi["level"]>=r["level"] and i not in pi["cf"])
    if pi["premium"]: claim+=sum(1 for i,r in enumerate(pi["prem"]) if pi["level"]>=r["level"] and i not in pi["cp"])
    ex=f"Level {pi['level']} / {pi['max']}" + (f"  •  {claim} to claim!" if claim else "")
    ui_card(surf,"ph_cp",pr,pi["col"],"ticket","COLOR PASS",pi["name"],t,dt,mouse,tag="NEW" if pi["season"]==2 else None,extra=ex,big=True)
    ns=len([s for s in shop_skins() if s not in owned_skins()])
    ui_card(surf,"ph_shop",sr,(255,190,40),"coin","SKIN SHOP","Buy skins with coins",t,dt,mouse,extra=f"{ns} skins for sale")
    ui_card(surf,"ph_inv",ir,(60,200,255),"palette","INVENTORY","All your skins",t,dt,mouse,extra=f"{len(owned_skins())} skins owned")
    return {"cp":pr,"shop":sr,"inv":ir}

# ── SKIN SHOP ────────────────────────────────────────────────────────────────
def draw_skin_shop(surf, t, dt, mouse, events):
    """Returns 'back' when leaving."""
    W,H=surf.get_size(); m=min(W,H)
    draw_menu_bg(surf,t,(255,190,40))
    top=draw_header(surf,"SKIN SHOP",f"{gd.get('coins',0)} coins  •  click a skin to buy it",(255,190,40),t)
    lst=shop_skins(); cols=5; gp=int(W*0.016); cw=(int(W*0.92)-(cols-1)*gp)//cols
    rows=max(1,math.ceil(len(lst)/cols)); ch=min(int(H*0.3),(H-100-top-(rows-1)*gp)//rows)
    x0=W//2-(cols*cw+(cols-1)*gp)//2; rects=[]; ul=owned_skins()
    for i,s in enumerate(lst):
        r=pygame.Rect(x0+(i%cols)*(cw+gp),top+6+(i//cols)*(ch+gp),cw,ch); rects.append((r,s))
        draw_skin_card(surf,r,s,s not in ul,s==gd.get("current_skin","Classic"),t,dt,mouse)
        if s in S1_SHOP_PRICE: _corner_tag(surf,r,"SEASON 1",(255,190,40))
        elif s in ul: _corner_tag(surf,r,"OWNED",(90,220,130))
    if pass_season()>=2:
        nt=render_fit(ui_font(m*0.024),"Season 1 Pass skins are in the shop now!  Galaxy is retired - if you have it, it's yours forever.",(190,170,240),W-300)
        surf.blit(nt,nt.get_rect(centerx=W//2+60,y=H-46))
    if _skin_msg["t"] and time.time()-_skin_msg["t"]<2.2:
        mm_=ui_font(m*0.03).render(_skin_msg["text"],True,_skin_msg["col"]); surf.blit(mm_,mm_.get_rect(centerx=W//2,bottom=H-74))
    inv=ui_pill(surf,"shop_inv",pygame.Rect(W-230,H-62,210,42),"INVENTORY",(60,200,255),dt,mouse,"palette")
    bk=ui_back(surf,dt,mouse)
    for r,s in rects:
        if not ui_click(events,r): continue
        if s in ul: gd["current_skin"]=s; save_gd(gd); SND_SELECT.play(); check_skin_badges(); _skin_msg.update({"text":f"{s} equipped","col":(120,180,255),"t":time.time()})
        else:
            ok,msg,col=buy_skin(s); (SND_CHIME if ok else SND_WRONG).play(); _skin_msg.update({"text":msg,"col":col,"t":time.time()})
    if ui_click(events,inv): _PASS_NAV["inv_back"]="skinshop"; return "inv"
    if ui_click(events,bk) or ui_esc(events): return "back"
    return None

def _corner_tag(surf, r, text, col):
    f=ui_font(min(surf.get_size())*0.017); ts=f.render(text,True,(15,12,25))
    tr_=ts.get_rect(topright=(r.right-10,r.y+7)).inflate(12,4)
    pygame.draw.rect(surf,col,tr_,border_radius=tr_.h//2); surf.blit(ts,ts.get_rect(center=tr_.center))

# ── INVENTORY ────────────────────────────────────────────────────────────────
def draw_inventory(surf, t, dt, mouse, events):
    W,H=surf.get_size(); m=min(W,H); own=owned_skins(); cur=gd.get("current_skin","Classic")
    if cur not in own: cur="Classic"
    sel=_PASS_NAV.get("sel") if _PASS_NAV.get("sel") in own else cur
    draw_menu_bg(surf,t,(60,200,255))
    top=draw_header(surf,"INVENTORY",f"{len(own)} skins owned  •  click to look, EQUIP to wear",(60,200,255),t)
    # left: big preview of the selected skin
    pw=int(W*0.3); pv=pygame.Rect(int(W*0.04),top+4,pw,H-92-top)
    ui_panel(surf,pv,None,(60,200,255))
    sk=SKINS[sel]; rar=SKIN_RARITY.get(sel,"COMMON"); rc=RARITY_COL[rar]
    surf.blit(_glow(int(pw*0.42),rc,40),(pv.centerx-int(pw*0.42),pv.y+int(pv.h*0.32)-int(pw*0.42)))
    names=["RED","BLUE","GREEN","YELLOW","PURPLE","ORANGE"]; tw=(pv.w-60)//3; th=int(min(tw*0.75,pv.h*0.17))
    for j,cn in enumerate(names):
        bob=int(math.sin(t*2.2+j*0.9)*3)
        tr_=pygame.Rect(pv.x+20+(j%3)*(tw+10),pv.y+28+(j//3)*(th+10)+bob,tw,th)
        pygame.draw.rect(surf,_mix(sk[cn],(0,0,0),0.4),tr_.move(0,4),border_radius=10)
        pygame.draw.rect(surf,sk[cn],tr_,border_radius=10)
        wl=render_fit(ui_font(th*0.36),names[(j+2)%6],WHITE,tw-8); surf.blit(wl,wl.get_rect(center=tr_.center))
    y=pv.y+40+2*(th+10)
    nm=render_fit(ui_font(m*0.05),sel,WHITE,pv.w-30); surf.blit(nm,nm.get_rect(centerx=pv.centerx,y=y)); y+=nm.get_height()+8
    rs=ui_font(m*0.022).render(rar,True,(15,15,25)); rb=rs.get_rect(centerx=pv.centerx,y=y).inflate(18,6)
    pygame.draw.rect(surf,rc,rb,border_radius=rb.h//2); surf.blit(rs,rs.get_rect(center=rb.center)); y=rb.bottom+10
    src=render_fit(ui_font(m*0.026),skin_source(sel),(185,195,225),pv.w-30); surf.blit(src,src.get_rect(centerx=pv.centerx,y=y))
    eq=pygame.Rect(0,0,min(220,pv.w-40),46); eq.midbottom=(pv.centerx,pv.bottom-18)
    is_eq=sel==cur
    eqb=ui_pill(surf,"inv_eq",eq,"EQUIPPED" if is_eq else "EQUIP",(255,200,40) if is_eq else (60,200,255),dt,mouse,"star" if is_eq else None)
    # right: grid of owned skins
    gx=pv.right+int(W*0.025); gw=int(W*0.96)-gx; cols=4; gp=int(W*0.012); cw=(gw-(cols-1)*gp)//cols
    rows=max(1,math.ceil(len(own)/cols)); ch=max(80,min(int(H*0.26),(H-96-top-(rows-1)*gp)//rows))
    rects=[]
    for i,s in enumerate(own):
        r=pygame.Rect(gx+(i%cols)*(cw+gp),top+4+(i//cols)*(ch+gp),cw,ch); rects.append((r,s))
        draw_skin_card(surf,r,s,False,s==cur,t,dt,mouse)
        if s==sel and s!=cur: pygame.draw.rect(surf,(60,200,255),r.inflate(6,6),3,border_radius=18)
        if s in RETIRED_SKINS: _corner_tag(surf,r,"RETIRED",(255,120,160))
        elif s in S2_SKINS: _corner_tag(surf,r,"SEASON 2",(170,120,255))
    sh=ui_pill(surf,"inv_shop",pygame.Rect(W-230,H-62,210,42),"SKIN SHOP",(255,190,40),dt,mouse,"coin")
    bk=ui_back(surf,dt,mouse)
    for r,s in rects:
        if ui_click(events,r):
            if s==sel: gd["current_skin"]=s; save_gd(gd); check_skin_badges(); SND_CHIME.play()
            else: _PASS_NAV["sel"]=s; SND_SELECT.play()
    if ui_click(events,eqb) and not is_eq: gd["current_skin"]=sel; save_gd(gd); check_skin_badges(); SND_CHIME.play()
    if ui_click(events,sh): _PASS_NAV["shop_back"]="inventory"; return "shop"
    if ui_click(events,bk) or ui_esc(events): return "back"
    return None

# ── THE HAUNT: mini trailer (first time you enter) ───────────────────────────
_MT={"t":0.0}
MT_LEN=18.6
def minitrailer_start():
    W,H=WIDTH,HEIGHT; rnd=random.Random(7)
    _MT.update({"t":0.0,"rain":[[rnd.random(),rnd.random(),rnd.uniform(0.6,1.4)] for _ in range(140)],
                "candy":[[rnd.uniform(0.02,0.98),rnd.uniform(-1.4,-0.05),rnd.uniform(0.5,1.1),rnd.uniform(0,6),
                          rnd.choice([(255,120,170),(255,170,40),(140,230,90),(170,110,255),(255,90,90)])] for _ in range(70)],
                "bats":[(rnd.uniform(-0.4,-0.05),rnd.uniform(0.1,0.35),rnd.uniform(0.25,0.45),rnd.uniform(0,6)) for _ in range(8)],
                "music":_teaser_music_play()})
    if not _MT["music"]: play_music("haunt")

def _mt_text(surf, text, y, size, col, a=255, spacing=0.0, glow=None):
    W,H=surf.get_size(); f=ui_font(min(W,H)*size)
    s=f.render(text,True,col)
    if spacing>0:
        chars=[f.render(c,True,col) for c in tr(text)]; gap=int(min(W,H)*size*spacing)
        tw=sum(c.get_width() for c in chars)+gap*(len(chars)-1); s=pygame.Surface((tw,max(c.get_height() for c in chars)),pygame.SRCALPHA); x=0
        for c in chars: s.blit(c,(x,0)); x+=c.get_width()+gap
    if glow: surf.blit(_glow(int(s.get_width()*0.45),glow,int(50*a/255)),(W//2-int(s.get_width()*0.45),int(y)+s.get_height()//2-int(s.get_width()*0.45)))
    s.set_alpha(int(a)); surf.blit(s,s.get_rect(centerx=W//2,y=int(y)))

def draw_haunt_minitrailer(surf, dt, events):
    """~18s 'what's inside THE HAUNT' trailer. Returns True when done / skipped."""
    W,H=surf.get_size(); m=min(W,H); T=_MT; T["t"]+=dt; t=T["t"]
    def fade(a,b,f=0.4):                                # alpha for a text shown between a and b
        if t<a or t>b: return 0
        return 255*min(1.0,(t-a)/f,(b-t)/f)
    flash=0.0
    for ft in (0.9,1.15,3.4,5.0,13.0,15.0):
        if ft<=t<ft+0.18: flash=max(flash,1-(t-ft)/0.18)
    shake=(0,0)
    if t<2.6:                                           # A: storm, "THIS HALLOWEEN..."
        surf.fill((6,4,10))
        _mt_text(surf,"THIS HALLOWEEN...",H*0.44,0.07,(235,225,255),fade(1.2,2.6),0.12)
    elif t<6.2:                                         # B: the mansion
        k=(t-2.6)/3.6; z=0.82+0.1*k
        bg=haunt_background(W,H); surf.blit(bg,(0,0)); draw_moon(surf,int(W*0.2),int(H*0.14),int(m*0.075))
        ms=_mansion_static(W,H)[0]; body,doors,attic=_mansion_layout(W,H)
        ox,oy=W/2-body.centerx*z, H*0.53-body.centery*z+H*0.04*(1-k)      # centre the house, slow push-in
        zs=pygame.transform.scale(ms,(int(W*z),int(H*z))); surf.blit(zs,(int(ox),int(oy)))
        for i,d in enumerate(doors):                    # windows light up one by one
            if t-2.6>i*0.12:
                dr=pygame.Rect(int(ox+d.x*z),int(oy+d.y*z),int(d.w*z),int(d.h*z))
                gl=pygame.Surface(dr.size,pygame.SRCALPHA); gl.fill((255,150,40,int(70+50*math.sin(t*6+i)))); surf.blit(gl,dr.topleft)
        for b in T["bats"]:
            x=(b[0]+(t-2.6)*b[2])*W; y=(b[1]+0.03*math.sin(t*3+b[3]))*H; draw_bat(surf,x,y,m*0.018,t+b[3])
        sh=pygame.Surface((W,int(H*0.2)),pygame.SRCALPHA); sh.fill((0,0,0,150)); surf.blit(sh,(0,int(H*0.8)))
        _mt_text(surf,"THE MANSION IS OPEN",H*0.84,0.06,(255,170,60),fade(3.0,6.2),0.1,H_ORANGE)
    elif t<9.8:                                         # C: doors open, hosts appear
        surf.blit(haunt_background(W,H),(0,0))
        kinds=["ghost","witch","vampire","skeleton"]; dw=int(W*0.16); dh=int(H*0.46); gp=int(W*0.05)
        x0=W//2-(4*dw+3*gp)//2; y0=int(H*0.2)
        for i,kd in enumerate(kinds):
            to=6.4+i*0.7; op=max(0.0,min(1.0,(t-to)/0.35))
            if 0<t-to<0.12: shake=(random.randint(-8,8),random.randint(-6,6))
            r=pygame.Rect(x0+i*(dw+gp),y0,dw,dh)
            pygame.draw.rect(surf,(28,20,38),r.inflate(18,18),border_radius=10)
            inside=pygame.Surface(r.size,pygame.SRCALPHA); inside.fill((255,140,40,int(60+120*op))); surf.blit(inside,r.topleft)
            if op>0: draw_host(surf,kd,r.centerx,r.y+int(dh*0.32),dw*0.22,t+i)
            pw_=int(dw*(1-op))
            if pw_>2:
                pygame.draw.rect(surf,(70,40,25),(r.x,r.y,pw_,r.h)); pygame.draw.rect(surf,(40,22,14),(r.x,r.y,pw_,r.h),3)
                pygame.draw.circle(surf,(220,180,60),(r.x+pw_-12,r.centery),5)
            n=ui_font(m*0.03).render(str(1+i*5+(i%2)*2),True,(255,220,150)); surf.blit(n,n.get_rect(centerx=r.centerx,bottom=r.y-14))
        _mt_text(surf,"20 ROOMS." if t<8.2 else "20 TWISTS.",H*0.76,0.075,WHITE,fade(6.3,9.8),0.1,(255,140,40))
    elif t<12.4:                                        # D: TRICK OR TREAT + candy rain
        surf.fill((22,8,30))
        for c in T["candy"]:
            cy_=c[1]+(t-9.8)*c[2]*0.9
            if cy_>-0.1: draw_candy(surf,int(c[0]*W),int(cy_*H),m*0.022,c[4],t*2+c[3])
        pul=1+0.06*math.sin(t*9)
        f=ui_font(m*0.12*pul); s1=f.render("TRICK",True,(255,90,60)); s2=f.render("OR TREAT?",True,(255,200,60))
        a=fade(9.9,12.4,0.25); s1.set_alpha(int(a)); s2.set_alpha(int(a))
        surf.blit(s1,s1.get_rect(center=(W//2,int(H*0.38)))); surf.blit(s2,s2.get_rect(center=(W//2,int(H*0.52))))
        cnt=int(min(500,max(0,(t-10.3)/1.8*500)))
        _mt_text(surf,f"CANDY  {cnt}",H*0.68,0.045,(255,220,150),fade(10.3,12.4,0.3))
    elif t<15.0:                                        # E: something in the attic
        surf.fill((4,2,6))
        ax,ay=W//2,int(H*0.36)
        pygame.draw.polygon(surf,(20,14,26),[(ax-int(W*0.3),ay+int(H*0.15)),(ax,ay-int(H*0.2)),(ax+int(W*0.3),ay+int(H*0.15))])
        hr=pygame.Rect(0,0,int(W*0.12),int(H*0.14)); hr.center=(ax,ay); pygame.draw.rect(surf,(10,6,12),hr); pygame.draw.rect(surf,(60,30,40),hr,3)
        if t>13.2:
            eo=min(1.0,(t-13.2)/0.4)
            for ex in (-1,1):
                pygame.draw.ellipse(surf,(230,20,30),(ax+ex*int(m*0.025)-int(m*0.012),ay-int(m*0.006*eo),int(m*0.024),max(1,int(m*0.014*eo))))
            surf.blit(_glow(int(m*0.08),(200,0,20),int(60*eo)),(ax-int(m*0.08),ay-int(m*0.08)))
        if t>13.9: draw_shadow_figure(surf,W//2,int(H*0.64),m*0.09,t,alpha=int(min(255,(t-13.9)*300)))
        txt="SOMETHING WAITS IN THE ATTIC..."; n=int(max(0,(t-12.6))*22)
        _mt_text(surf,txt[:n],H*0.84,0.045,(220,190,210),fade(12.6,15.0,0.2))
    else:                                               # F: title card
        surf.blit(haunt_background(W,H),(0,0)); draw_moon(surf,int(W*0.85),int(H*0.16),int(m*0.06))
        for i in range(4): draw_bat(surf,(t*90+i*260)%(W+100)-50,int(H*0.1)+i*24,13,t+i)
        k=min(1.0,(t-15.0)/0.5); sc=1+(1-k)*1.8
        f=ui_font(m*0.16*sc); ts=f.render("THE HAUNT",True,H_ORANGE)
        surf.blit(_glow(int(ts.get_width()*0.55),H_ORANGE,60),(W//2-int(ts.get_width()*0.55),int(H*0.36)-int(ts.get_width()*0.55)))
        sh_=f.render("THE HAUNT",True,(40,10,0)); surf.blit(sh_,sh_.get_rect(center=(W//2+4,int(H*0.36)+6))); surf.blit(ts,ts.get_rect(center=(W//2,int(H*0.36))))
        for i in range(9):                              # slime drips
            dx=W//2-ts.get_width()//2+int((i+0.5)*ts.get_width()/9); dl=int(min(1,(t-15.3)*0.8)*(10+i*7%30))*m//400
            if dl>0: pygame.draw.line(surf,(120,220,40),(dx,int(H*0.36)+ts.get_height()//3),(dx,int(H*0.36)+ts.get_height()//3+dl),3)
        _pumpkin2(surf,int(W*0.2),int(H*0.78),int(m*0.08),1.0,t); _pumpkin2(surf,int(W*0.8),int(H*0.78),int(m*0.08),1.0,t+1)
        _mt_text(surf,"OCT 25 - NOV 14  •  NOW OPEN",H*0.56,0.045,(255,225,190),fade(15.6,18.6,0.4),0.04)
    for d in T["rain"]:                                 # rain over everything
        d[1]=(d[1]+dt*1.1*d[2])%1.05; x=d[0]*W+d[1]*30; y=d[1]*H
        pygame.draw.line(surf,(80,80,120),(x,y),(x-4,y+12*d[2]),1)
    if shake!=(0,0): surf.blit(surf.copy(),shake)
    if flash>0:
        fl=pygame.Surface((W,H)); fl.fill((235,230,255)); fl.set_alpha(int(200*flash)); surf.blit(fl,(0,0))
    if t>MT_LEN-0.6:
        bl=pygame.Surface((W,H)); bl.set_alpha(int(255*min(1,(t-(MT_LEN-0.6))/0.6))); surf.blit(bl,(0,0))
    sk=ui_font(m*0.022).render("Click or ESC to skip",True,(150,140,170)); surf.blit(sk,sk.get_rect(bottomright=(W-16,H-12)))
    skip=t>0.5 and any((e.type==pygame.MOUSEBUTTONDOWN and e.button==1) or (e.type==pygame.KEYDOWN and e.key in (pygame.K_ESCAPE,pygame.K_SPACE,pygame.K_RETURN)) for e in events)
    return t>=MT_LEN or skip

# ── "IN PASS: SEASON 2" reveal ───────────────────────────────────────────────
_S2R={"t":0.0,"back":"pass","haunt":False}
def s2_reveal_start(back, from_haunt=False):
    rnd=random.Random(3); W,H=WIDTH,HEIGHT
    _S2R.update({"t":0.0,"back":back,"haunt":from_haunt,"menu_music":False,
                 "shards":[[rnd.uniform(-0.5,0.5),rnd.uniform(-0.5,0.5),rnd.uniform(-1,1),rnd.uniform(-0.6,0.2),rnd.uniform(-4,4)] for _ in range(14)],
                 "sparks":[[rnd.uniform(0,6.28),rnd.uniform(0.3,1.0),rnd.choice(list(NEON.values()))] for _ in range(60)],
                 "stars":[(rnd.random(),rnd.random(),rnd.uniform(0,6)) for _ in range(90)]})
    if not from_haunt: play_music("menu")

def draw_season_reveal(surf, dt, events, mouse):
    """IN PASS: SEASON 2 -> Season 1 ended -> Season 2 arrived. Returns 'pass' / 'continue' / None."""
    W,H=surf.get_size(); m=min(W,H); R=_S2R; R["t"]+=dt; t=R["t"]; tm=pygame.time.get_ticks()/1000
    if not R["menu_music"] and t>3 and R["haunt"]:
        try: busy=pygame.mixer.music.get_busy()
        except Exception: busy=False
        if not busy: R["menu_music"]=True; play_music("menu")
    for i in range(0,H,6):
        k=i/H; pygame.draw.rect(surf,_mix((26,10,48),(4,3,12),k),(0,i,W,6))
    for x,y,p in R["stars"]:
        a=int(90+120*(0.5+0.5*math.sin(tm*2+p))); pygame.draw.circle(surf,(a,a,min(255,a+30)),(int(x*W),int(y*H)),1+(p>5))
    surf.blit(_glow(int(m*0.6),(140,80,255),35),(W//2-int(m*0.6),int(H*0.3)-int(m*0.6)))
    shake=(0,0)
    if 2.05<t<2.35: shake=(random.randint(-10,10),random.randint(-8,8))
    # 0-1: intro line
    if R["haunt"] and t<1.4:
        a=255*min(1,t/0.3,(1.4-t)/0.3); _mt_text(surf,"...AND THERE'S MORE",H*0.45,0.05,(220,210,255),a,0.08)
    # title: IN PASS  /  SEASON 2
    ty=H*0.3 if t<3.2 else H*0.3-(H*0.24)*min(1,(t-3.2)/0.5)
    ts_=1.0 if t<3.2 else 1-0.45*min(1,(t-3.2)/0.5)
    if t>1.0:
        f=ui_font(m*0.08*ts_); word="IN PASS"; x=W//2-sum(f.size(c)[0] for c in word)//2
        for i,c in enumerate(word):
            k=min(1.0,max(0.0,(t-1.0-i*0.09)/0.3))
            if k<=0: x+=f.size(c)[0]; continue
            yy=ty-(1-k)**2*H*0.4+math.sin(min(1,k)*math.pi)*-8
            cs=f.render(c,True,(255,210,90)); cs.set_alpha(int(255*k)); surf.blit(cs,(x+shake[0],int(yy)+shake[1])); x+=f.size(c)[0]
    if t>2.0:
        k=min(1.0,(t-2.0)/0.22); sc=(3.0-2.0*k)*ts_
        f2=ui_font(m*0.15*sc); s2=f2.render("SEASON 2",True,WHITE)
        cy=ty+m*0.13*ts_
        surf.blit(_glow(int(s2.get_width()*0.5),(170,110,255),int(90*k)),(W//2-int(s2.get_width()*0.5),int(cy)-int(s2.get_width()*0.5)))
        sh=f2.render("SEASON 2",True,(90,40,170)); sh.set_alpha(int(255*k)); surf.blit(sh,sh.get_rect(center=(W//2+5+shake[0],int(cy)+6+shake[1])))
        s2.set_alpha(int(255*k)); surf.blit(s2,s2.get_rect(center=(W//2+shake[0],int(cy)+shake[1])))
        if t<3.4:
            for a_,sp,col in R["sparks"]:
                d=(t-2.2)*m*0.9*sp
                if d>0: pygame.draw.circle(surf,col,(int(W//2+math.cos(a_)*d),int(cy+math.sin(a_)*d*0.6)),max(1,int(4*(1-(t-2.2)/1.2))))
        if t>3.6:
            st=ui_font(m*0.034).render("N I G H T F A L L",True,(200,175,255)); st.set_alpha(int(255*min(1,(t-3.6)/0.5)))
            surf.blit(st,st.get_rect(center=(W//2,int(cy+m*0.075*ts_+10))))
    if 2.0<t<2.3:
        fl=pygame.Surface((W,H)); fl.fill(WHITE); fl.set_alpha(int(220*(1-(t-2.0)/0.3))); surf.blit(fl,(0,0))
    # Season 1 card: ENDED stamp, then shatters
    if 3.8<t<7.0:
        cw,ch=int(W*0.3),int(H*0.36); k=min(1,(t-3.8)/0.4); cx=W//2; cyc=int(H*0.58)
        card=pygame.Rect(0,0,cw,ch); card.center=(cx,cyc+int((1-k)*H*0.3))
        if t<5.6:
            pygame.draw.rect(surf,(40,30,20),card,border_radius=18); pygame.draw.rect(surf,(255,190,40),card,3,border_radius=18)
            hs=ui_font(m*0.045).render("SEASON 1",True,(255,210,90)); surf.blit(hs,hs.get_rect(centerx=card.centerx,y=card.y+14))
            sw=(cw-50)//3
            for i,sn in enumerate(["Pastel","Dark Gold","Retro","Neon Fire","Ocean","Galaxy"]):
                rr=pygame.Rect(card.x+15+(i%3)*(sw+10),card.y+int(ch*0.3)+(i//3)*int(ch*0.3),sw,int(ch*0.25))
                pygame.draw.rect(surf,SKIN_BG[sn][0],rr,border_radius=8)
                for j,cn in enumerate(["RED","BLUE","GREEN","YELLOW","PURPLE","ORANGE"]):
                    pygame.draw.rect(surf,SKINS[sn][cn],(rr.x+6+j*((rr.w-12)//6),rr.y+6,max(2,(rr.w-12)//6-2),rr.h//2),border_radius=3)
                nl=render_fit(ui_font(rr.h*0.28),sn,WHITE,rr.w-6); surf.blit(nl,nl.get_rect(centerx=rr.centerx,bottom=rr.bottom-3))
            if t>4.5:                                    # red ENDED stamp
                k2=min(1,(t-4.5)/0.18); sf=ui_font(m*0.09*(2-k2)); ss=sf.render("ENDED",True,(235,40,50))
                box=pygame.Surface((ss.get_width()+30,ss.get_height()+10),pygame.SRCALPHA); pygame.draw.rect(box,(235,40,50),box.get_rect(),5,border_radius=10)
                box.blit(ss,(15,5)); box=pygame.transform.rotate(box,14); box.set_alpha(int(255*k2)); surf.blit(box,box.get_rect(center=card.center))
            if t>5.2:                                    # cracks
                for i in range(5):
                    a_=i*1.25+0.3; pygame.draw.line(surf,(255,240,200),card.center,(card.centerx+math.cos(a_)*cw*0.6,card.centery+math.sin(a_)*ch*0.6),2)
        else:                                            # shards falling
            g=t-5.6
            for sx,sy,vx,vy,rot in R["shards"]:
                px=card.centerx+sx*cw+vx*g*m*0.4; py=card.centery+sy*ch+vy*g*m*0.4+0.5*m*1.6*g*g
                pts=[(px+math.cos(rot*g+q*2.1)*m*0.03,py+math.sin(rot*g+q*2.1)*m*0.03) for q in range(3)]
                pygame.draw.polygon(surf,(255,190,40) if (sx>0)^(sy>0) else (70,50,30),pts)
        _mt_text(surf,"SEASON 1 HAS ENDED",H*0.86,0.045,(255,200,120),255*min(1,(t-4.0)/0.3,(7.0-t)/0.3),0.06)
    # Season 2 arrives: 6 new skins flip in
    if t>7.0:
        cols=6; gp=int(W*0.014); cw=(int(W*0.92)-(cols-1)*gp)//cols; ch=int(H*0.34); x0=W//2-(cols*cw+(cols-1)*gp)//2; y0=int(H*0.36)
        tags=["FREE  LV 1","FREE  LV 10","FREE  LV 20","PREMIUM  LV 1","PREMIUM  LV 10","PREMIUM  LV 20"]
        for i,sn in enumerate(S2_SKINS):
            k=min(1.0,max(0.0,(t-7.3-i*0.3)/0.5)); r=pygame.Rect(x0+i*(cw+gp),y0,cw,ch)
            if k<=0: continue
            if k<0.5:                                    # card back
                w_=max(4,int(cw*(1-k*2))); rb=pygame.Rect(0,0,w_,ch); rb.center=r.center
                pygame.draw.rect(surf,(60,30,110),rb,border_radius=14); pygame.draw.rect(surf,(170,120,255),rb,2,border_radius=14)
                if w_>30: q=ui_font(m*0.08).render("?",True,(200,170,255)); surf.blit(q,q.get_rect(center=rb.center))
            else:
                w_=max(40,int(cw*(k-0.5)*2)); rf=pygame.Rect(0,0,w_,ch); rf.center=r.center
                if k>=1: surf.blit(_glow(int(cw*0.55),RARITY_COL[SKIN_RARITY[sn]],int(30+20*math.sin(tm*3+i))),(r.centerx-int(cw*0.55),r.centery-int(cw*0.55)))
                draw_skin_card(surf,rf,sn,False,False,tm,dt,(-99,-99))
                cov=pygame.Rect(0,0,max(10,rf.w-16),int(m*0.042)); cov.midbottom=(rf.centerx,rf.bottom-6)   # hide EQUIP: not yours yet
                pygame.draw.rect(surf,_mix(SKIN_BG[sn][1],(0,0,0),0.2),cov,border_radius=cov.h//2)
                if k>=1:
                    nw=ui_font(m*0.024).render("NEW!",True,(255,230,120)); surf.blit(nw,nw.get_rect(center=cov.center))
                    tg=ui_font(m*0.02).render(tags[i],True,(15,10,25)); tb=tg.get_rect(centerx=r.centerx,y=r.bottom+8).inflate(14,6)
                    pygame.draw.rect(surf,(120,200,255) if i<3 else (255,200,50),tb,border_radius=tb.h//2); surf.blit(tg,tg.get_rect(center=tb.center))
        _mt_text(surf,"SEASON 2 HAS ARRIVED!",H*0.27,0.048,(235,220,255),255*min(1,(t-7.0)/0.4),0.05,(170,110,255))
    done=t>9.6
    res=None
    if done:
        a=min(1,(t-9.6)/0.4)
        _mt_text(surf,"30 LEVELS  •  6 NEW SKINS  •  UNTIL DEC 31",H*0.76,0.032,(255,225,150),255*a)
        _mt_text(surf,"Season 1 skins are now in the SKIN SHOP",H*0.81,0.026,(190,180,230),255*a)
        pb=ui_pill(surf,"s2r_pass",pygame.Rect(W//2-260,H-76,250,52),"OPEN PASS",(170,110,255),dt,mouse,"ticket")
        cb=ui_pill(surf,"s2r_go",pygame.Rect(W//2+10,H-76,250,52),"ENTER THE HAUNT" if R["haunt"] else "CONTINUE",H_ORANGE if R["haunt"] else (60,200,255),dt,mouse,"door" if R["haunt"] else None)
        if ui_click(events,pb): res="pass"
        elif ui_click(events,cb) or ui_esc(events): res="continue"
    else:
        sk=ui_font(m*0.022).render("Click to skip",True,(150,140,180)); surf.blit(sk,sk.get_rect(bottomright=(W-16,H-12)))
        if t>0.4 and any((e.type==pygame.MOUSEBUTTONDOWN and e.button==1) or (e.type==pygame.KEYDOWN and e.key in (pygame.K_ESCAPE,pygame.K_SPACE,pygame.K_RETURN)) for e in events):
            R["t"]=9.7; SND_SELECT.play()
    if res:
        gd["season_seen"]=2; save_gd(gd); SND_SELECT.play()
    return res

def need_season_reveal():
    return pass_season()==2 and gd.get("season_seen",1)<2

