# =============================================================================
#  PAUSE MENU — ESC / P during a game: RESUME (3-2-1), SETTINGS, MAIN MENU
# =============================================================================
PAUSE_STATES = ("playing","boss","summer","fall_mode","vibe_rush","flow","timeline_playing")
PAUSE = {"on":False,"t0":0.0,"snap":None,"view":"main","count":None,"sure":0.0,"state":None}
PAUSE_MODE_NAMES = {"playing":"CLASSIC","boss":"BOSS MODE","summer":"SUMMER","fall_mode":"FALL MODE","vibe_rush":"VIBE RUSH",
                    "flow":"FLOW","timeline_playing":"TIMELINE -1"}

def pause_open(state, screen_surf):
    if PAUSE["on"]: return
    W,H=screen_surf.get_size()
    small=pygame.transform.smoothscale(screen_surf,(max(1,W//14),max(1,H//14)))   # blurred: you can't study the board
    snap=pygame.transform.smoothscale(small,(W,H))
    PAUSE.update({"on":True,"t0":time.time(),"snap":snap,"view":"main","count":None,"sure":0.0,"state":state})
    try: pygame.mixer.pause(); pygame.mixer.music.pause()
    except Exception: pass
    SND_SELECT.play()

def _shift_ts(obj, d, depth=0):
    """Move every timestamp (seconds since 1970) forward by d -> the timers don't count the pause."""
    if depth>3: return
    items=obj.items() if isinstance(obj,dict) else []
    for k,v in list(items):
        if isinstance(v,float) and 1e9<v<4e9: obj[k]=v+d
        elif isinstance(v,dict): _shift_ts(v,d,depth+1)
        elif isinstance(v,list):
            for it in v:
                if isinstance(it,dict): _shift_ts(it,d,depth+1)

def pause_close(objs):
    d=time.time()-PAUSE["t0"]
    for o in objs:
        if o is None: continue
        _shift_ts(o if isinstance(o,dict) else o.__dict__,d)
    PAUSE.update({"on":False,"snap":None,"count":None})
    try: pygame.mixer.unpause(); pygame.mixer.music.unpause()
    except Exception: pass

def draw_pause(surf, events, mouse, dt, game):
    """Returns None / 'resume' (countdown finished) / 'menu'."""
    W,H=surf.get_size(); m=min(W,H); t=pygame.time.get_ticks()/1000
    if PAUSE["snap"] is not None:
        if PAUSE["snap"].get_size()!=(W,H): PAUSE["snap"]=pygame.transform.smoothscale(PAUSE["snap"],(W,H))
        surf.blit(PAUSE["snap"],(0,0))
    dim=pygame.Surface((W,H),pygame.SRCALPHA); dim.fill((6,6,16,150 if PAUSE["count"] is None else 90)); surf.blit(dim,(0,0))
    # ---- 3-2-1 after RESUME ----
    if PAUSE["count"] is not None:
        left=3-(time.time()-PAUSE["count"])
        if left<=0: return "resume"
        n=int(math.ceil(left)); frac=left-math.floor(left) if left%1 else 1.0
        num=ui_font(m*0.22*(0.8+0.5*frac)).render(str(n),True,WHITE); num.set_alpha(int(255*min(1,frac*2.5)))
        surf.blit(_glow(int(m*0.16),(90,170,255),int(80*frac)),(W//2-int(m*0.16),H//2-int(m*0.16)))
        surf.blit(num,num.get_rect(center=(W//2,H//2)))
        gt=ui_font(m*0.035).render("GET READY!",True,(190,210,255)); surf.blit(gt,gt.get_rect(centerx=W//2,y=H//2+int(m*0.14)))
        return None
    pw,ph=int(min(W*0.5,560)),int(min(H*0.78,560)); pr=pygame.Rect(0,0,pw,ph); pr.center=(W//2,H//2)
    k=min(1.0,(time.time()-PAUSE["t0"])/0.18); pr.y+=int((1-k)*40)
    ui_panel(surf,pr,None,(90,170,255))
    esc=ui_esc(events)
    if PAUSE["view"]=="main":
        tl=ui_font(m*0.085).render("PAUSED",True,WHITE); surf.blit(tl,tl.get_rect(centerx=pr.centerx,y=pr.y+int(ph*0.06)))
        mode=PAUSE_MODE_NAMES.get(PAUSE["state"],"")
        sc=getattr(game,"score",0) if PAUSE["state"]!="flow" else None
        info=mode+(f"  •  Score {sc}" if sc is not None else "")
        it=render_fit(ui_font(m*0.03),info,(170,185,230),pw-40); surf.blit(it,it.get_rect(centerx=pr.centerx,y=pr.y+int(ph*0.21)))
        bw,bh=int(pw*0.72),int(min(64,ph*0.13)); x=pr.centerx-bw//2; y0=pr.y+int(ph*0.33); gp=int(bh*0.38)
        b1=ui_pill(surf,"p_resume",pygame.Rect(x,y0,bw,bh),"RESUME",(60,200,110),dt,mouse,"bolt")
        b2=ui_pill(surf,"p_sett",pygame.Rect(x,y0+(bh+gp),bw,bh),"SETTINGS",(90,140,255),dt,mouse,"gear")
        sure=time.time()-PAUSE["sure"]<2.5
        b3=ui_pill(surf,"p_menu",pygame.Rect(x,y0+2*(bh+gp),bw,bh),"SURE? CLICK AGAIN" if sure else "MAIN MENU",(235,80,90) if sure else (150,70,90),dt,mouse,"door")
        hint=render_fit(ui_font(m*0.022),"This game won't be saved if you leave" if sure else "ESC = resume",(150,150,185),pw-40)
        surf.blit(hint,hint.get_rect(centerx=pr.centerx,bottom=pr.bottom-16))
        if ui_click(events,b1) or esc or any(ev.type==pygame.KEYDOWN and ev.key==pygame.K_p for ev in events):
            PAUSE["count"]=time.time(); SND_SELECT.play()
        elif ui_click(events,b2): PAUSE["view"]="settings"; SND_SELECT.play()
        elif ui_click(events,b3):
            if sure: SND_SELECT.play(); return "menu"
            PAUSE["sure"]=time.time(); SND_WRONG.play()
        return None
    # ---- settings view ----
    tl=ui_font(m*0.06).render("SETTINGS",True,WHITE); surf.blit(tl,tl.get_rect(centerx=pr.centerx,y=pr.y+int(ph*0.05)))
    sl1=pygame.Rect(pr.x+40,pr.y+int(ph*0.27),pw-80,12); sl2=pygame.Rect(pr.x+40,pr.y+int(ph*0.43),pw-80,12)
    mv=ui_slider(surf,"p_mus",sl1,gd.get("music_volume",0.8),NEON["BLUE"],"Music",events,mouse)
    sv=ui_slider(surf,"p_sfx",sl2,gd.get("sfx_volume",0.8),NEON["ORANGE"],"Sound effects",events,mouse)
    if abs(mv-gd.get("music_volume",0.8))>0.004 or abs(sv-gd.get("sfx_volume",0.8))>0.004:
        gd["music_volume"]=round(mv,2); gd["sfx_volume"]=round(sv,2); update_music_volume()
    if any(ev.type==pygame.MOUSEBUTTONUP for ev in events): save_gd(gd)
    lf=ui_font(m*0.03); surf.blit(lf.render("Language",True,(200,200,225)),(pr.x+40,pr.y+int(ph*0.53)))
    lw_=(pw-80-20)//3; lh=min(44,int(ph*0.09)); cl_=lang_code(); lrs=[]
    for j,(c_,lbl) in enumerate((("EN","English"),("ES","Español"),("HE","עברית"))):
        r_=pygame.Rect(pr.x+40+j*(lw_+10),pr.y+int(ph*0.60),lw_,lh); lrs.append((r_,c_))
        ui_pill(surf,"p_lang_"+c_,r_,lbl,NEON["GREEN"] if cl_==c_ else (70,70,100),dt,mouse)
    fs_=render_fit(ui_font(m*0.024),"F11 = fullscreen",(140,140,175),pw-80); surf.blit(fs_,fs_.get_rect(centerx=pr.centerx,y=pr.y+int(ph*0.73)))
    bk=ui_pill(surf,"p_back",pygame.Rect(pr.centerx-110,pr.bottom-int(ph*0.16),220,int(min(54,ph*0.11))),"BACK",(90,140,255),dt,mouse,"back")
    for r_,c_ in lrs:
        if ui_click(events,r_):
            if gd.get("lang")!=c_: award_badge("world_traveler")
            globals()["current_lang"]=c_; gd["lang"]=c_; gd["language"]=c_.lower(); save_gd(gd); SND_SELECT.play()
    if ui_click(events,bk) or esc: PAUSE["view"]="main"; save_gd(gd); SND_SELECT.play()
    return None

