def itch_countdown_on(): return BUILD_PLATFORM=="itch" and not BUILD_DEMO
def draw_itch_countdown(surf, cx, y, dt, mouse, events, t):
    """itch.io version only: countdown to the end of the last itch.io event -> then 'new events are on the Microsoft Store'."""
    import datetime as _d
    end=_d.datetime.fromisoformat(ITCH_LAST_END+"T23:59:59"); left=(end-_d.datetime.now()).total_seconds()
    m=min(surf.get_size()); f=ui_font(m*0.024)
    if left>0:
        dd=int(left//86400); hh=int(left%86400//3600); mm=int(left%3600//60); ss=int(left%60)
        txt=f"LAST ITCH.IO EVENT ENDS IN  {dd}d {hh:02d}:{mm:02d}:{ss:02d}"; col=(255,150,50) if dd>=3 else (255,80,80)
    else: txt,col="New events are on the Microsoft Store  >",(90,170,255)
    ts=f.render(txt,True,WHITE); r=ts.get_rect(centerx=cx,y=y).inflate(70,12)
    hv=ui_hover("itchcd",1.0 if r.collidepoint(mouse) else 0.0,dt)
    if left>0 and dd<3: surf.blit(_glow(int(r.w*0.35),col,int(30+25*math.sin(t*5))),(r.centerx-int(r.w*0.35),r.centery-int(r.w*0.35)))
    pygame.draw.rect(surf,_mix((20,14,26),col,0.18+0.15*hv),r,border_radius=r.h//2); pygame.draw.rect(surf,col,r,2,border_radius=r.h//2)
    ui_icon2(surf,"hourglass" if left>0 else "bolt",r.x+20,r.centery,int(r.h*0.3),col,t)
    surf.blit(ts,ts.get_rect(midleft=(r.x+36,r.centery)))
    ui_icon2(surf,"star",r.right-20,r.centery,int(r.h*0.26),col,t)
    if ui_click(events,r):
        try: webbrowser.open(MSSTORE_URL)
        except Exception: pass
        SND_SELECT.play()
    return r
_tpl(r"^LAST ITCH\.IO EVENT ENDS IN  (\d+)d (\d+):(\d+):(\d+)$","EL ÚLTIMO EVENTO DE ITCH.IO TERMINA EN  {0}d {1}:{2}:{3}","האירוע האחרון ב-ITCH.IO נגמר בעוד  {0} ימים {1}:{2}:{3}")


