#  SOUNDTRACK ROOM — Pixel Manor's songs (Collab #3: Pixel Manor x The Glitch Storm x Man Studio)
#  The mp3 files live next to the game (like the Haunt music). Locked until the collab starts.
# =============================================================================
SOUNDTRACK_OPEN = "2026-12-05"          # Winter Wonderland + Collab #3
SOUNDTRACK_OPEN_UTC = (2026,12,5,15,0)   # = 17:00 Israel time (UTC+2 in December) - the update comes out then, for everyone at the same moment
SOUNDTRACK = [
    {"file":"pixel_manor_nope.mp3","title":"NOPE","artist":"Pixel Manor","length":151.2,"cover":None,"col":(120,170,230)},
    {"file":"pixel_manor_oxygen.mp3","title":"OXYGEN","artist":"Pixel Manor","length":217.8,"cover":None,"col":(210,140,80)},
    {"file":"pixel_manor_why_are_you_crying.mp3","title":"Why Are You Crying","artist":"Pixel Manor","length":209.7,"cover":None,"col":(170,170,190)},
    {"file":"pixel_manor_blinding_chaos.mp3","title":"Blinding Chaos","artist":"Pixel Manor","length":219.4,"cover":None,"col":(230,80,160)},
]
ST = {"i":0,"playing":False,"t0":0.0,"off":0.0,"paused_at":None,"covers":{},"msg":None,"bars":[0.0]*32}

def soundtrack_open():
    import datetime as _d
    return dev_mode() or _d.datetime.utcnow()>=_d.datetime(*SOUNDTRACK_OPEN_UTC)

def _st_cover(i, size):
    """The cover art, drawn by the game. No packed-in picture to go wrong."""
    k=(i,size)
    if k in ST["covers"]: return ST["covers"][k]
    tr_=SOUNDTRACK[i]; col=tuple(tr_.get("col",(255,120,30)))
    img=pygame.Surface((size,size),pygame.SRCALPHA)
    deep=_mix(col,(0,0,0),0.80); lite=_mix(col,(255,255,255),0.22)
    for y in range(size):                                   # the sleeve
        pygame.draw.line(img,_mix(lite,deep,(y/float(size))**0.85),(0,y),(size,y))
    rnd=random.Random(40+i)
    for b in range(26):                                     # a soft bloom of colour
        bx,by=rnd.randrange(size),rnd.randrange(size); br=int(size*rnd.uniform(0.05,0.22))
        sp=pygame.Surface((br*2,br*2),pygame.SRCALPHA)
        pygame.draw.circle(sp,(*lite,22),(br,br),br); img.blit(sp,(bx-br,by-br))
    cx=cy=size//2                                           # a record, turning
    pygame.draw.circle(img,(16,14,22),(cx,cy),int(size*0.33))
    for r in range(int(size*0.13),int(size*0.33),max(2,size//44)):
        pygame.draw.circle(img,_mix((16,14,22),lite,0.12),(cx,cy),r,1)
    pygame.draw.circle(img,col,(cx,cy),int(size*0.12))
    pygame.draw.circle(img,(16,14,22),(cx,cy),max(2,int(size*0.028)))
    hl=pygame.Surface((size,size),pygame.SRCALPHA)          # a sheen across it
    pygame.draw.polygon(hl,(255,255,255,26),[(0,size),(size*0.55,0),(size*0.80,0),(0,size)])
    img.blit(hl,(0,0))
    ns=ui_font(size*0.17).render(str(i+1),True,(255,255,255))
    ns.set_alpha(70); img.blit(ns,ns.get_rect(bottomright=(size-int(size*0.06),size-int(size*0.03))))
    pygame.draw.rect(img,_mix(col,(255,255,255),0.30),(0,0,size,size),max(1,size//70))
    ST["covers"][k]=img; return img

def st_pos():
    if ST["paused_at"] is not None: return ST["paused_at"]
    if not ST["playing"]: return 0.0
    return ST["off"]+time.time()-ST["t0"]

def st_play(i, start=0.0):
    global _cur_music
    tr_=SOUNDTRACK[i]; p=_res_path(tr_["file"])
    if not os.path.exists(p):
        ST.update(msg=f"Put {tr_['file']} next to the game",playing=False,paused_at=None); SND_WRONG.play(); return
    try:
        pygame.mixer.stop(); pygame.mixer.music.load(p)
        pygame.mixer.music.set_volume(min(1.0,gd.get("music_volume",0.8)*0.9))
        pygame.mixer.music.play(0,start=max(0.0,start)); _cur_music="soundtrack"
        ST.update(i=i,playing=True,t0=time.time(),off=start,paused_at=None,msg=None)
    except Exception as e:
        print("[soundtrack]",e); ST.update(msg="Could not play this song",playing=False)

def st_stop():
    try: pygame.mixer.music.stop()
    except Exception: pass
    ST.update(playing=False,paused_at=None)

def draw_soundtrack(surf, t, dt, mouse, events):
    """Returns 'back' when leaving."""
    W,H=surf.get_size(); m=min(W,H); tr_=SOUNDTRACK[ST["i"]]; col=tr_["col"]
    if ST["playing"] and ST["paused_at"] is None:
        if st_pos()>=tr_["length"]-0.05 or not pygame.mixer.music.get_busy():      # song ended -> next one
            if st_pos()>1.0: st_play((ST["i"]+1)%len(SOUNDTRACK))
    draw_menu_bg(surf,t,col)
    top=draw_header(surf,"SOUNDTRACK ROOM","Pixel Manor  •  original music",col,t)
    # ---- vinyl + cover (left) ----
    cx,cy=int(W*0.3),int(top+(H-top-90)*0.48); R=int(min(W*0.2,(H-top-120)*0.46))
    spin=st_pos()*0.9 if (ST["playing"] and ST["paused_at"] is None) else st_pos()*0.9
    surf.blit(_glow(int(R*1.35),col,60 if ST["playing"] else 25),(cx-int(R*1.35),cy-int(R*1.35)))
    pygame.draw.circle(surf,(8,8,12),(cx,cy),R);
    for k in range(6): pygame.draw.circle(surf,(28,28,36),(cx,cy),int(R*(0.55+k*0.075)),1)
    a=spin; pygame.draw.arc(surf,(90,90,110),(cx-R+6,cy-R+6,2*R-12,2*R-12),a,a+0.6,2)
    cv=_st_cover(ST["i"],int(R*1.2))
    if cv:
        rot=pygame.transform.rotate(cv,-math.degrees(spin)); mask=pygame.Surface(rot.get_size(),pygame.SRCALPHA)
        pygame.draw.circle(mask,(255,255,255,255),(rot.get_width()//2,rot.get_height()//2),int(R*0.5))
        lab=pygame.Surface(rot.get_size(),pygame.SRCALPHA); lab.blit(rot,(0,0)); lab.blit(mask,(0,0),special_flags=pygame.BLEND_RGBA_MIN)
        surf.blit(lab,lab.get_rect(center=(cx,cy)))
    pygame.draw.circle(surf,(230,230,240),(cx,cy),max(4,R//18))
    # tone arm
    arm_a=-0.5 if ST["playing"] and ST["paused_at"] is None else -1.0
    ax,ay=cx+int(R*1.05),cy-int(R*0.95); ex,ey=ax+int(math.cos(math.pi/2+0.55-arm_a*0.3)*R*0.95),ay+int(math.sin(math.pi/2+0.55-arm_a*0.3)*R*0.95)
    pygame.draw.line(surf,(200,200,210),(ax,ay),(ex,ey),6); pygame.draw.circle(surf,(170,170,185),(ax,ay),12)
    pygame.draw.rect(surf,(220,220,230),(ex-9,ey-6,18,18),border_radius=4)
    # ---- info + controls (right) ----
    px=int(W*0.52); pw=int(W*0.42); y=top+int(H*0.04)
    tl=render_fit(ui_font(m*0.08),tr_["title"],WHITE,pw); surf.blit(tl,(px,y)); y+=tl.get_height()+4
    ar=ui_font(m*0.034).render(tr_["artist"],True,col); surf.blit(ar,(px,y)); y+=ar.get_height()+int(H*0.03)
    # visualizer
    vb=pygame.Rect(px,y,pw,int(H*0.16)); n=len(ST["bars"]); bw_=vb.w/n
    for k in range(n):
        target=0.0
        if ST["playing"] and ST["paused_at"] is None:
            target=0.25+0.75*abs(math.sin(t*(3.1+k*0.37)+k*1.7)*math.sin(t*1.3+k*0.5))
        ST["bars"][k]+=(target-ST["bars"][k])*min(1,dt*10)
        h_=max(3,int(vb.h*ST["bars"][k])); r_=pygame.Rect(int(vb.x+k*bw_+2),vb.bottom-h_,max(2,int(bw_-4)),h_)
        pygame.draw.rect(surf,_mix(col,WHITE,0.4*k/n),r_,border_radius=3)
    y=vb.bottom+int(H*0.035)
    # progress bar (click to seek)
    pos=min(st_pos(),tr_["length"]); pb=pygame.Rect(px,y,pw,10)
    pygame.draw.rect(surf,(30,30,50),pb,border_radius=5)
    pygame.draw.rect(surf,col,(pb.x,pb.y,int(pb.w*pos/tr_["length"]),pb.h),border_radius=5)
    pygame.draw.circle(surf,WHITE,(pb.x+int(pb.w*pos/tr_["length"]),pb.centery),8)
    fmt=lambda s:f"{int(s)//60}:{int(s)%60:02d}"
    f2=ui_font(m*0.024); surf.blit(f2.render(fmt(pos),True,(170,170,200)),(pb.x,pb.bottom+6))
    tt=f2.render(fmt(tr_["length"]),True,(170,170,200)); surf.blit(tt,tt.get_rect(right=pb.right,y=pb.bottom+6))
    y=pb.bottom+int(H*0.07); bh=52
    is_play=ST["playing"] and ST["paused_at"] is None
    b_prev=ui_pill(surf,"st_prev",pygame.Rect(px,y,90,bh),"<<",(80,80,120),dt,mouse)
    b_play=ui_pill(surf,"st_play",pygame.Rect(px+105,y,180,bh),"PAUSE" if is_play else "PLAY",col,dt,mouse,"note")
    b_next=ui_pill(surf,"st_next",pygame.Rect(px+300,y,90,bh),">>",(80,80,120),dt,mouse)
    # track list
    ly=y+bh+int(H*0.04); rows=[]
    for k,s_ in enumerate(SOUNDTRACK):
        r_=pygame.Rect(px,ly+k*40,pw,34); rows.append((r_,k)); cur=k==ST["i"]
        pygame.draw.rect(surf,(30,30,52) if not cur else _mix((30,30,52),s_["col"],0.35),r_,border_radius=10)
        surf.blit(ui_font(m*0.026).render(f"{k+1}.  {s_['title']}  —  {s_['artist']}",True,WHITE if cur else (190,190,210)),(r_.x+14,r_.y+6))
        lt=ui_font(m*0.024).render(fmt(s_["length"]),True,(160,160,190)); surf.blit(lt,lt.get_rect(right=r_.right-12,centery=r_.centery))
    if ST["msg"]:
        ms=render_fit(ui_font(m*0.026),ST["msg"],(255,140,120),W-200); surf.blit(ms,ms.get_rect(centerx=W//2,y=H-48))
    else:
        cr_=ui_font(m*0.022).render("© 2026 Man Studio  •  music by Pixel Manor",True,(140,140,175)); surf.blit(cr_,cr_.get_rect(centerx=W//2+60,y=H-46))
    bk=ui_back(surf,dt,mouse)
    for ev in events:
        if ev.type==pygame.MOUSEBUTTONDOWN and ev.button==1 and pb.inflate(0,20).collidepoint(ev.pos):
            st_play(ST["i"],(ev.pos[0]-pb.x)/pb.w*tr_["length"]); SND_SELECT.play()
        if ev.type==pygame.KEYDOWN and ev.key==pygame.K_SPACE: events.append(pygame.event.Event(pygame.USEREVENT,st="toggle"))
    toggle=ui_click(events,b_play) or any(getattr(e,"st",None)=="toggle" for e in events)
    if toggle:
        if is_play:
            ST["paused_at"]=st_pos(); pygame.mixer.music.pause()
        elif ST["paused_at"] is not None:
            ST["off"]=ST["paused_at"]; ST["t0"]=time.time(); ST["paused_at"]=None; pygame.mixer.music.unpause()
        else: st_play(ST["i"])
    elif ui_click(events,b_prev): st_play((ST["i"]-1)%len(SOUNDTRACK)) if st_pos()<3 else st_play(ST["i"])
    elif ui_click(events,b_next): st_play((ST["i"]+1)%len(SOUNDTRACK))
    for r_,k in rows:
        if ui_click(events,r_): st_play(k)
    if ui_click(events,bk) or ui_esc(events): st_stop(); return "back"
    return None

for _en,_es,_he in [("SOUNDTRACK ROOM","SALA DE MÚSICA","חדר המוזיקה"),("Pixel Manor  •  original music","Pixel Manor  •  música original","Pixel Manor  •  מוזיקה מקורית"),
                    ("PLAY","REPRODUCIR","נגן"),("PAUSE","PAUSA","השהה"),("SOUNDTRACK","BANDA SONORA","פסקול"),("Music by Pixel Manor","Música de Pixel Manor","מוזיקה של Pixel Manor"),
                    ("Coming December 5","Llega el 5 de diciembre","מגיע ב-5 בדצמבר"),("© 2026 Man Studio  •  music by Pixel Manor","© 2026 Man Studio  •  música de Pixel Manor","© 2026 Man Studio  •  מוזיקה של Pixel Manor"),
                    ("Could not play this song","No se pudo reproducir","לא הצלחנו לנגן את השיר")]:
    TR["ES"].setdefault(_en,_es); TR["HE"].setdefault(_en,_he)
_tpl(r"^Put (.+) next to the game$","Pon {0} junto al juego","שים את {0} ליד המשחק")



# ══════════════════════════════════════════════════════════════════════════════
# THE HIM  (5/11 - 7/11/2026)  —  "HE IS COMING."
# A room covered in the words they said to him. A big YOU. Click it.
# His story -> 10 levels (5 COLOR + 5 FLOW) -> how he became THE HIM.
# Reward: badge HIS ONLY FRIEND + skin "The Him". After 7/11 the story stays in ARCHIVE.
# ══════════════════════════════════════════════════════════════════════════════
HIM_START = "2026-11-05"
HIM_END   = "2026-11-07"
HIM_RED   = (215,20,30)
HIM_SKIN  = "The Him"
HIM_BADGE = "his_only_friend"
HIM_WORDS = ["SCARY","FREAK","WEIRD","GO AWAY","NOBODY LIKES YOU","MONSTER","CREEPY","LOSER","NO FRIENDS",
             "STAY AWAY","YOU'RE SCARY","GET LOST","ALONE","HA HA HA","DON'T SIT HERE","NOBODY CARES"]
HIM_LEVELS = [("color",i) for i in range(5)]+[("flow",i) for i in range(5)]
HIM = {"screen":"hall","t":0.0,"back":"limited_menu","story":None,"st":0.0,"scene":0,"replay":False,
       "round":None,"flow":None,"drag":False,"lives":3,"lvl":0,"res":None,"res_t":0.0,"cues":set(),"click_t":0.0}

def him_state():
    """'before' / 'active' / 'after'  (DEV MODE opens it early)."""
    if dev_mode(): return "active"
    d=_today()
    return "before" if d<HIM_START else ("after" if d>HIM_END else "active")

def him_data():
    h=gd.setdefault("him",{})
    for k,v in (("lvl",0),("seen1",False),("done",False)): h.setdefault(k,v)
    return h

def him_story_open():
    """After 7/11 everyone can watch the story in ARCHIVE (the levels and the prize are gone)."""
    return him_state()=="after" or him_data().get("done") or dev_mode()

def him_open(screen="hall", back="limited_menu", replay=False):
    HIM.update({"screen":screen,"t":0.0,"back":back,"replay":replay,"round":None,"flow":None,"drag":False,"res":None,"cues":set()})
    if screen=="hall": SND_STATIC.play()
    if screen=="story": him_story_start("full" if replay else "part1")

# ── little people ────────────────────────────────────────────────────────────
def _him_person(surf, x, y, h, body, head, hair=None, mouth="smile", eyes=(30,25,35), bob=0.0, dress=False,
                glasses=False, bun=False, long_hair=False, tear=False, face=1, arm_up=0):
    """A simple cartoon person standing on (x,y). h = full height."""
    x=int(x); y=int(y-bob); hr=int(h*0.17); bw=int(h*0.32); bh=int(h*0.42)
    by=y-int(h*0.08)-bh; hy=by-hr+2
    for lx in (-bw//4,bw//4):                                         # legs
        pygame.draw.line(surf,_mix(body,(0,0,0),0.45),(x+lx,by+bh-4),(x+lx,y),max(3,int(h*0.06)))
    if dress:
        pygame.draw.polygon(surf,body,[(x-bw//3,by),(x+bw//3,by),(x+int(bw*0.75),by+bh),(x-int(bw*0.75),by+bh)])
    else:
        pygame.draw.rect(surf,body,(x-bw//2,by,bw,bh),border_radius=max(3,bw//3))
    aw=max(3,int(h*0.05))                                              # arms
    pygame.draw.line(surf,_mix(body,(0,0,0),0.2),(x-bw//2,by+6),(x-bw//2-int(h*0.08),by+int(bh*0.75)),aw)
    if arm_up: pygame.draw.line(surf,_mix(body,(0,0,0),0.2),(x+bw//2,by+6),(x+bw//2+int(h*0.12),by-int(h*0.12)),aw)
    else: pygame.draw.line(surf,_mix(body,(0,0,0),0.2),(x+bw//2,by+6),(x+bw//2+int(h*0.08),by+int(bh*0.75)),aw)
    if long_hair and hair:                                             # hair falls on both sides, behind the head
        for sx in (-1,1): pygame.draw.rect(surf,hair,(x+sx*int(hr*0.82)-int(hr*0.32),hy-hr//2,int(hr*0.64),int(hr*1.9)),border_radius=hr//3)
    pygame.draw.circle(surf,head,(x,hy),hr)
    if hair:
        pygame.draw.circle(surf,hair,(x,hy-hr//3),hr,0,draw_top_right=True,draw_top_left=True)
        pygame.draw.rect(surf,head,(x-hr+3,hy-hr//3,2*hr-6,hr//3+1))
    if bun and hair: pygame.draw.circle(surf,hair,(x,hy-hr-hr//3),hr//2)
    ex=int(hr*0.38); ey=hy-int(hr*0.1); er=max(2,hr//6); fx=int(hr*0.15*face)
    for sx in (-ex,ex):
        pygame.draw.circle(surf,eyes,(x+sx+fx,ey),er)
        if glasses: pygame.draw.circle(surf,(60,50,60),(x+sx+fx,ey),er+4,2)
    mw=int(hr*0.55); my=hy+int(hr*0.42)
    if mouth=="laugh":
        pygame.draw.ellipse(surf,(60,15,20),(x-mw//2+fx,my-int(hr*0.18),mw,int(hr*0.5)))
    elif mouth=="sad":
        pygame.draw.arc(surf,(40,30,40),(x-mw//2+fx,my,mw,int(hr*0.4)),0.3,2.85,2)
    elif mouth=="none": pass
    else:
        pygame.draw.arc(surf,(40,30,40),(x-mw//2+fx,my-int(hr*0.35),mw,int(hr*0.4)),3.5,5.9,2)
    if tear: pygame.draw.circle(surf,(120,190,255),(x+ex+fx,ey+er*3),max(2,er-1))

def _him_kid(surf, x, y, h, t, mood="sad", grow=0.0, red=0.0, tear=False, face=1, arm_up=0):
    """THE HIM as a kid (grow>0 = older, red = how evil he got)."""
    body=_mix((70,66,80),(14,10,16),min(1,red*1.3)); head=_mix((96,90,104),(20,14,22),min(1,red*1.3))
    eyes=_mix((240,240,245),(255,30,30),red)
    _him_person(surf,x,y,h*(1+grow),body,head,hair=(30,26,34),mouth=mood if red<0.5 else "none",eyes=eyes,tear=tear,face=face,arm_up=arm_up)
    if red>0.4:                                                        # glowing red eyes
        hr=int(h*(1+grow)*0.17); hy=int(y-h*(1+grow)*0.08-h*(1+grow)*0.42-hr+2); ex=int(hr*0.38)
        g=pygame.Surface((hr*4,hr*2),pygame.SRCALPHA)
        for sx in (-ex,ex): pygame.draw.circle(g,(255,30,30,int(90*red)),(hr*2+sx,hr),hr//2)
        surf.blit(g,(int(x)-hr*2,hy-int(hr*0.1)-hr))

def _him_bubble(surf, text, x, y, bg=(250,250,250), fg=(25,20,30), size=None, alpha=255, tail=(0,1)):
    W,H=surf.get_size(); f=ui_font(size or min(W,H)*0.032)
    ts=f.render(text,True,fg); pad=12
    r=pygame.Rect(0,0,ts.get_width()+2*pad,ts.get_height()+2*pad); r.midbottom=(int(x),int(y)-14)
    r.clamp_ip(pygame.Rect(8,8,W-16,H-16))
    b=pygame.Surface((r.w,r.h+16),pygame.SRCALPHA)
    pygame.draw.rect(b,(*bg,alpha),(0,0,r.w,r.h),border_radius=14)
    tx=max(14,min(r.w-14,int(x)-r.x))
    pygame.draw.polygon(b,(*bg,alpha),[(tx-9,r.h-2),(tx+9,r.h-2),(tx+tail[0]*6,r.h+14)])
    ts.set_alpha(alpha); b.blit(ts,(pad,pad)); surf.blit(b,r.topleft)

def _him_caption(surf, text, u, col=(235,230,240)):
    """Bottom caption that types itself."""
    W,H=surf.get_size(); txt=tr(text); n=max(1,int(len(txt)*min(1.0,u/max(0.6,len(txt)*0.035))))
    bar=pygame.Surface((W,int(H*0.12)),pygame.SRCALPHA); bar.fill((0,0,0,170)); surf.blit(bar,(0,H-bar.get_height()))
    f=ui_font(min(W,H)*0.04); shown=txt if n>=len(txt) else txt[:n]
    s=f.render(shown,True,col); surf.blit(s,s.get_rect(center=(W//2,H-bar.get_height()//2)))

def _him_room(surf, W, H, wall, floor, split=0.62):
    surf.fill(wall); pygame.draw.rect(surf,floor,(0,int(H*split),W,H-int(H*split)))
    pygame.draw.line(surf,_mix(wall,(0,0,0),0.4),(0,int(H*split)),(W,int(H*split)),4)

def _him_vignette(surf, W, H, col=(0,0,0), k=200):
    v=pygame.Surface((W,H),pygame.SRCALPHA)
    for i in range(10):
        a=int(k*(i/10)**2); pygame.draw.rect(v,(*col,a),(0,0,W,H),int(min(W,H)*0.05*(10-i)/10)+1)
    surf.blit(v,(0,0))

def _him_plane(surf, x, y, s, ang=0.0, col=(235,238,245), window_face=False):
    p=pygame.Surface((int(s*2.4),int(s*1.2)),pygame.SRCALPHA); w,h=p.get_size(); cy=h//2
    pygame.draw.ellipse(p,col,(int(w*0.08),cy-int(s*0.16),int(w*0.84),int(s*0.32)))
    pygame.draw.polygon(p,_mix(col,(80,90,110),0.3),[(int(w*0.42),cy),(int(w*0.58),cy),(int(w*0.38),cy+int(s*0.5))])
    pygame.draw.polygon(p,_mix(col,(80,90,110),0.3),[(int(w*0.42),cy),(int(w*0.58),cy),(int(w*0.38),cy-int(s*0.45))])
    pygame.draw.polygon(p,(200,40,50),[(int(w*0.1),cy),(int(w*0.2),cy),(int(w*0.08),cy-int(s*0.38))])
    for k in range(6): pygame.draw.circle(p,(70,110,170),(int(w*(0.3+k*0.08)),cy-2),max(2,int(s*0.04)))
    if window_face:                                                    # she waves from a window
        pygame.draw.circle(p,(255,215,190),(int(w*0.62),cy-2),max(3,int(s*0.07)))
        pygame.draw.circle(p,(110,60,30),(int(w*0.62),cy-4-int(s*0.03)),max(3,int(s*0.07)),0,draw_top_left=True,draw_top_right=True)
    if ang: p=pygame.transform.rotate(p,ang)
    surf.blit(p,p.get_rect(center=(int(x),int(y))))

def _him_heart(surf, x, y, s, col, split=0.0):
    for side in (-1,1):
        h=pygame.Surface((s*2,s*2),pygame.SRCALPHA)
        pygame.draw.circle(h,col,(s-int(s*0.38)*1,int(s*0.7)),int(s*0.42))
        pygame.draw.circle(h,col,(s+int(s*0.38),int(s*0.7)),int(s*0.42))
        pygame.draw.polygon(h,col,[(int(s*0.22),int(s*0.85)),(int(s*1.78),int(s*0.85)),(s,int(s*1.75))])
        half=pygame.Surface((s,s*2),pygame.SRCALPHA); half.blit(h,(0 if side<0 else -s,0))
        if split>0:
            for k in range(6):                                             # the crack
                yy=int(s*0.5+k*s*0.2); xx=s if side<0 else 0
                pygame.draw.line(half,(10,5,10),(xx,yy),(xx-side*int(s*0.1)*(1 if k%2 else -1),yy+int(s*0.2)),3)
        half=pygame.transform.rotate(half,-side*split*25)
        surf.blit(half,half.get_rect(center=(int(x+side*(s*0.5+split*s*0.9)),int(y+split*s*0.6))))

# ── the story scenes ─────────────────────────────────────────────────────────
def _sc_school(surf, W, H, u):
    _him_room(surf,W,H,(78,92,108),(84,62,46),0.6)
    cb=pygame.Rect(int(W*0.25),int(H*0.08),int(W*0.5),int(H*0.25))
    pygame.draw.rect(surf,(120,85,50),cb.inflate(14,14),border_radius=6); pygame.draw.rect(surf,(28,64,46),cb)
    cf=ui_font(min(W,H)*0.05)
    surf.blit(cf.render("A  B  C     2 + 2 = 4",True,(220,230,220)),(cb.x+20,cb.y+16))
    wr=pygame.Rect(int(W*0.04),int(H*0.1),int(W*0.14),int(H*0.24)); pygame.draw.rect(surf,(170,210,240),wr); pygame.draw.rect(surf,(230,230,235),wr,6)
    laugh=u>1.4; kids=[]
    cols=[(230,80,90),(70,150,240),(60,190,110),(240,190,50),(170,90,230),(240,130,60)]
    heads=[(255,214,180),(200,150,110),(240,195,160),(150,100,70),(255,220,190),(210,160,120)]
    for i in range(6):
        row=i//3; x=W*(0.2+(i%3)*0.22)+(row*W*0.05); y=H*(0.66+row*0.13)
        bob=abs(math.sin(u*11+i))*H*0.012 if laugh else 0
        _him_person(surf,x,y,H*0.24,cols[i],heads[i],hair=(60,40,30),mouth="laugh" if laugh else "smile",bob=bob,face=1 if x<W*0.6 else -1)
        pygame.draw.rect(surf,(150,105,65),(x-W*0.07,y-H*0.11,W*0.14,H*0.05),border_radius=4)
        kids.append((x,y-H*0.24-bob))
    kx,ky=W*0.82,H*0.92                                                # THE HIM, alone in the front
    _him_kid(surf,kx,ky,H*0.27,u,mood="sad",tear=u>5.5,face=-1)
    pygame.draw.rect(surf,(150,105,65),(kx-W*0.08,ky-H*0.12,W*0.16,H*0.055),border_radius=4)
    if 2.0<u: _him_bubble(surf,"YOU'RE SCARY!",kids[0][0],kids[0][1],alpha=int(255*min(1,(u-2.0)*4)))
    if 3.3<u: _him_bubble(surf,"NOBODY WANTS TO BE YOUR FRIEND!",kids[4][0],kids[4][1],alpha=int(255*min(1,(u-3.3)*4)))
    if 4.6<u: _him_bubble(surf,"HA HA HA!",kids[2][0],kids[2][1],alpha=int(255*min(1,(u-4.6)*4)))
    _him_vignette(surf,W,H)
    if u<1.6: _him_caption(surf,"Years ago...",u)
    elif u<5.0: _him_caption(surf,"At school, everyone laughed at him.",u-1.6)
    else: _him_caption(surf,"They said he was scary. Nobody was his friend.",u-5.0)

def _sc_home(surf, W, H, u):
    _him_room(surf,W,H,(112,86,72),(92,64,44),0.64)
    win=pygame.Rect(int(W*0.62),int(H*0.1),int(W*0.18),int(H*0.24)); pygame.draw.rect(surf,(20,26,60),win)
    pygame.draw.circle(surf,(240,240,210),(win.x+int(win.w*0.7),win.y+int(win.h*0.35)),int(win.h*0.12)); pygame.draw.rect(surf,(225,215,200),win,6)
    so=pygame.Rect(int(W*0.42),int(H*0.5),int(W*0.46),int(H*0.2)); pygame.draw.rect(surf,(150,60,60),so,border_radius=18)
    pygame.draw.rect(surf,(125,45,48),(so.x,so.y-int(H*0.08),so.w,int(H*0.12)),border_radius=18)
    laugh=u>3.0
    bob=lambda i: abs(math.sin(u*10+i))*H*0.012 if laugh else 0
    _him_person(surf,W*0.56,H*0.72,H*0.36,(70,110,170),(235,195,160),hair=(70,45,30),mouth="laugh" if laugh else "smile",bob=bob(0),face=-1)
    _him_person(surf,W*0.75,H*0.72,H*0.34,(190,90,140),(245,205,175),hair=(120,70,40),long_hair=True,mouth="laugh" if laugh else "smile",bob=bob(1),face=-1)
    _him_kid(surf,W*0.2,H*0.9,H*0.27,u,mood="sad",face=1)
    if 1.0<u: _him_bubble(surf,"Mom, Dad... the kids laughed at me.",W*0.2,H*0.6,alpha=int(255*min(1,(u-1.0)*4)))
    if 3.0<u: _him_bubble(surf,"HA HA! Well... you ARE a little scary!",W*0.56,H*0.34,alpha=int(255*min(1,(u-3.0)*4)))
    if 4.3<u: _him_bubble(surf,"HA HA HA!",W*0.78,H*0.36,alpha=int(255*min(1,(u-4.3)*4)))
    _him_vignette(surf,W,H)
    _him_caption(surf,"He went home and told his parents." if u<4.6 else "They laughed too.",u if u<4.6 else u-4.6)

def _sc_grandma(surf, W, H, u):
    _him_room(surf,W,H,(96,70,88),(80,58,46),0.64)
    for k in range(0,W,int(W*0.06)): pygame.draw.line(surf,(104,78,96),(k,0),(k,int(H*0.64)),8)
    fp=pygame.Rect(int(W*0.06),int(H*0.36),int(W*0.22),int(H*0.28)); pygame.draw.rect(surf,(120,70,55),fp)
    fr=fp.inflate(-int(fp.w*0.35),-int(fp.h*0.3)); fr.bottom=fp.bottom; pygame.draw.rect(surf,(20,10,8),fr)
    for k in range(5):
        fh=int(fr.h*(0.4+0.3*abs(math.sin(u*7+k))))
        pygame.draw.ellipse(surf,(255,140+k*15,40),(fr.x+k*fr.w//5,fr.bottom-fh,fr.w//4,fh))
    rock=math.sin(u*1.6)*4; ch=pygame.Rect(int(W*0.58),int(H*0.44),int(W*0.24),int(H*0.3))
    pygame.draw.rect(surf,(120,60,90),ch.move(0,int(rock)),border_radius=26)
    laugh=u>4.0
    _him_person(surf,W*0.7,H*0.74+rock,H*0.33,(130,90,170),(245,215,195),hair=(205,205,212),bun=True,glasses=True,
                mouth="laugh" if laugh else "smile",bob=abs(math.sin(u*9))*H*0.012 if laugh else 0,face=-1)
    kx=W*(0.12+0.24*min(1,u/2.0))
    _him_kid(surf,kx,H*0.92,H*0.27,u,mood="sad" if u>4.0 else "smile",face=1,tear=u>5.2)
    if 2.0<u: _him_bubble(surf,"Grandma... am I scary?",kx,H*0.62,alpha=int(255*min(1,(u-2.0)*4)))
    if 4.0<u: _him_bubble(surf,"Oh sweetie... HA HA HA! Yes!",W*0.7,H*0.36,alpha=int(255*min(1,(u-4.0)*4)))
    _him_vignette(surf,W,H)
    _him_caption(surf,"He went to the one he trusted most. His grandma." if u<4.6 else "Even she laughed.",u if u<4.6 else u-4.6)

def _sc_plea(surf, W, H, u):
    surf.fill((6,4,8)); _him_vignette(surf,W,H,(90,0,0),120)
    k=min(1.0,u/4.0); s=H*(0.25+0.45*k)
    _him_kid(surf,W//2,H*(0.82+0.12*k),s,u,mood="sad",tear=True,face=0)
    if 4.0<u: _him_bubble(surf,"Please... help me.",W//2,H*0.82+0.12*k*H-s*1.05,alpha=int(255*min(1,(u-4.0)*4)))
    _him_caption(surf,"He had nobody left." if u<2.5 else ("...except YOU." if u<5.6 else "Pass 10 levels for me. 5 COLOR and 5 FLOW."),
                 u if u<2.5 else (u-2.5 if u<5.6 else u-5.6),HIM_RED if 2.5<=u<5.6 else (235,230,240))

def _street(surf, W, H, u, sky=(125,185,240)):
    surf.fill(sky); pygame.draw.circle(surf,(255,230,120),(int(W*0.86),int(H*0.14)),int(H*0.06))
    for i in range(6):
        x=int(W*(i*0.18-0.02)); hh=int(H*(0.24+0.06*(i%3))); col=[(210,120,90),(120,160,200),(230,200,120),(150,190,130)][i%4]
        pygame.draw.rect(surf,col,(x,int(H*0.62)-hh,int(W*0.15),hh))
        pygame.draw.polygon(surf,_mix(col,(0,0,0),0.3),[(x-6,int(H*0.62)-hh),(x+int(W*0.075),int(H*0.62)-hh-int(H*0.08)),(x+int(W*0.15)+6,int(H*0.62)-hh)])
        for k in range(2): pygame.draw.rect(surf,(250,240,200),(x+12+k*int(W*0.07),int(H*0.62)-hh+16,int(W*0.04),int(H*0.05)))
    pygame.draw.rect(surf,(150,150,155),(0,int(H*0.62),W,int(H*0.1))); pygame.draw.rect(surf,(70,72,80),(0,int(H*0.72),W,H))
    for k in range(0,W,80): pygame.draw.rect(surf,(230,230,120),(k+int(-u*60)%80,int(H*0.85),40,6))

def _him_couple(surf, W, H, u, x, look_up=False):
    y=H*0.72; arm=1 if look_up else 0
    _him_kid(surf,x,y,H*0.3,u,mood="smile",grow=0.25,face=1,arm_up=0)
    _him_person(surf,x+W*0.09,y,H*0.33,(240,120,160),(250,215,190),hair=(110,60,30),long_hair=True,dress=True,mouth="smile",face=1,arm_up=arm)
    pygame.draw.line(surf,(200,170,160),(x+W*0.035,y-H*0.18),(x+W*0.055,y-H*0.18),5)

def _sc_street(surf, W, H, u):
    _street(surf,W,H,u)
    x=W*(0.12+u*0.045); _him_couple(surf,W,H,u,x)
    for k in range(4):
        hy=(u*40+k*60)%180; _him_heart(surf,x+W*0.045+math.sin(u*2+k)*20,H*0.36-hy,10,(255,90,120))
    _him_caption(surf,"You helped him. For the first time, he was happy." if u<3.4 else "He even had a girlfriend.",u if u<3.4 else u-3.4)

def _sc_sky(surf, W, H, u):
    _street(surf,W,H,0)
    _him_plane(surf,W*(-0.1+u*0.22),H*0.16,H*0.09)
    _him_couple(surf,W,H,u,W*0.4,look_up=u>1.0)
    if 1.5<u: _him_bubble(surf,"Wow... I want to fly!",W*0.49,H*0.38,alpha=int(255*min(1,(u-1.5)*4)))
    if 3.4<u: _him_bubble(surf,"Then you will!",W*0.4,H*0.42,alpha=int(255*min(1,(u-3.4)*4)))
    _him_caption(surf,"One day, she saw a plane.",u)

def _sc_later(surf, W, H, u):
    surf.fill((0,0,0)); a=int(255*min(1,u/0.8)*min(1,(3.2-u)/0.5 if u>2.7 else 1))
    s=ui_font(min(W,H)*0.09).render("3 DAYS LATER",True,(235,235,240)); s.set_alpha(max(0,a)); surf.blit(s,s.get_rect(center=(W//2,H//2)))

def _sc_airport(surf, W, H, u):
    surf.fill((150,200,240)); pygame.draw.rect(surf,(110,170,90),(0,int(H*0.6),W,H))
    pygame.draw.rect(surf,(90,92,100),(0,int(H*0.66),W,int(H*0.14)))
    for k in range(0,W,90): pygame.draw.rect(surf,(240,240,240),(k,int(H*0.725),50,6))
    tm=pygame.Rect(int(W*0.02),int(H*0.36),int(W*0.3),int(H*0.24)); pygame.draw.rect(surf,(200,205,215),tm); pygame.draw.rect(surf,(120,170,210),tm.inflate(-20,-int(tm.h*0.5)))
    lift=max(0.0,u-2.6); px=W*(0.35+u*0.09+lift*lift*0.03); py=H*0.69-lift*lift*H*0.05
    _him_plane(surf,px,py,H*0.16,ang=min(14,lift*9),window_face=True)
    if 0.8<u<3.2: _him_bubble(surf,"Bye! See you soon!",px+H*0.08,py-H*0.04,alpha=int(255*min(1,(u-0.8)*4)))
    for k in range(10): pygame.draw.line(surf,(160,160,170),(int(W*0.02)+k*int(W*0.035),int(H*0.82)),(int(W*0.02)+k*int(W*0.035),int(H*0.95)),3)
    pygame.draw.line(surf,(160,160,170),(0,int(H*0.85)),(int(W*0.36),int(H*0.85)),3)
    _him_kid(surf,W*0.16,H*0.98,H*0.3,u,mood="smile",grow=0.25,face=1,arm_up=1)
    _him_caption(surf,"She got on a plane.",u)

def _sc_crash(surf, W, H, u):
    top=(255,170,110); bot=(120,70,140)
    for y in range(0,H,6): pygame.draw.rect(surf,_mix(top,bot,y/H),(0,y,W,6))
    hz=int(H*0.66)
    if u>3.6:                                                          # far away: a glow and smoke. That's all.
        g=min(1.0,(u-3.6)/0.6); gl=pygame.Surface((W,H),pygame.SRCALPHA)
        pygame.draw.ellipse(gl,(255,120,40,int(120*g)),(int(W*0.62),hz-int(H*0.08),int(W*0.2),int(H*0.14)))
        surf.blit(gl,(0,0))
        for k in range(12):
            a=(u-3.6)*0.9-k*0.12
            if a>0: pygame.draw.circle(surf,(70,64,70),(int(W*0.72+math.sin(k*1.7)*10+a*20),int(hz-a*H*0.12)),int(10+a*18))
    if u<3.5:
        d=max(0.0,u-2.2); px=W*(0.1+u*0.18); py=H*0.2+d*d*H*0.12
        _him_plane(surf,px,py,H*0.06,ang=-d*28)
        if d>0:
            for k in range(8): pygame.draw.circle(surf,(90,85,90),(int(px-k*12),int(py-k*4*d)),3+k)
    pygame.draw.polygon(surf,(40,30,50),[(0,hz),(int(W*0.2),hz-int(H*0.08)),(int(W*0.45),hz-int(H*0.02)),(int(W*0.7),hz-int(H*0.09)),(W,hz-int(H*0.03)),(W,H),(0,H)])
    _him_person(surf,W*0.3,H*1.02,H*0.42,(12,10,16),(14,12,18),hair=(8,6,10),mouth="none",eyes=(14,12,18),arm_up=1 if u>3.6 else 0)
    if u>3.6: _him_caption(surf,"But the plane never landed.",u-3.6)

def _sc_broken(surf, W, H, u):
    surf.fill((10,12,22))
    for k in range(70):
        x=(k*97+u*60)%W; y=(k*53+u*900)%H; pygame.draw.line(surf,(90,110,150),(x,y),(x-4,y+18),1)
    pygame.draw.rect(surf,(60,45,35),(int(W*0.38),int(H*0.74),int(W*0.24),int(H*0.03)))
    for lx in (0.4,0.6): pygame.draw.rect(surf,(50,38,30),(int(W*lx)-4,int(H*0.77),8,int(H*0.08)))
    _him_kid(surf,W*0.5,H*0.8,H*0.3,u,mood="sad",grow=0.25,tear=True,face=0)
    split=0.0 if u<2.0 else min(1.0,(u-2.0)/0.6)
    if u>2.0 and "crack" not in HIM["cues"]: HIM["cues"].add("crack"); SND_SLAM.play()
    _him_heart(surf,W*0.5,H*0.28,int(H*0.09),(230,40,60) if split<1 else (130,30,40),split)
    _him_caption(surf,"First, everyone laughed at him." if u<2.8 else "Then he lost the only one who loved him.",u if u<2.8 else u-2.8)

def _sc_turn(surf, W, H, u):
    surf.fill((4,2,4))
    red=min(1.0,max(0.0,(u-1.6)/1.6))
    if red>0:
        rnd=random.Random(7)
        for k,w in enumerate(HIM_WORDS):
            s=ui_font(min(W,H)*rnd.uniform(0.03,0.06)).render(w,True,(120,10,16)); s.set_alpha(int(150*red*(0.5+0.5*math.sin(u*2+k))))
            surf.blit(s,(int(rnd.uniform(0.02,0.8)*W),int(rnd.uniform(0.05,0.85)*H)))
    if 1.6<u<3.3 and int(u*8)%3==0: o=pygame.Surface((W,H),pygame.SRCALPHA); o.fill((160,0,0,50)); surf.blit(o,(0,0))
    _him_kid(surf,W//2,H*0.92,H*0.42,u,mood="sad" if red<0.3 else "none",grow=0.25+0.35*red,red=red,face=0)
    for i,(tt,snd) in enumerate(((1.0,SND_SHORT_BEEP),(1.4,SND_SHORT_BEEP),(1.8,SND_SHORT_BEEP),(2.4,SND_LONG_BEEP),(3.2,SND_LONG_BEEP))):
        if u>tt and ("b%d"%i) not in HIM["cues"]: HIM["cues"].add("b%d"%i); snd.play()
    if u>5.4:
        if "slam" not in HIM["cues"]: HIM["cues"].add("slam"); SND_SLAM.play(); start_shake(14,30)
        o=pygame.Surface((W,H),pygame.SRCALPHA); o.fill((0,0,0,int(235*min(1,(u-5.4)/0.15)))); surf.blit(o,(0,0))
        s=ui_font(min(W,H)*0.12).render("HE IS COMING.",True,WHITE); surf.blit(s,s.get_rect(center=(W//2,H//2)))
    elif u<2.2: _him_caption(surf,"He stopped crying.",u)
    elif u<3.9: _him_caption(surf,"He stopped being sad.",u-2.2)
    else: _him_caption(surf,"He became... THE HIM.",u-3.9,HIM_RED)

HIM_STORY = {
    "part1":[(_sc_school,8.0),(_sc_home,7.0),(_sc_grandma,7.5),(_sc_plea,8.4)],
    "part2":[(_sc_street,7.0),(_sc_sky,5.6),(_sc_later,3.2),(_sc_airport,6.2),(_sc_crash,7.2),(_sc_broken,7.0),(_sc_turn,8.6)],
}
HIM_STORY["full"]=HIM_STORY["part1"][:3]+HIM_STORY["part2"]

def him_story_start(which):
    HIM.update({"screen":"story","story":which,"scene":0,"st":0.0,"cues":set(),"click_t":0.0})

def _him_story_end():
    h=him_data(); which=HIM["story"]
    if HIM["replay"]: return "exit"
    if which=="part1":
        h["seen1"]=True; save_gd(gd); HIM["screen"]="map"; HIM["t"]=0.0
    else:
        HIM["screen"]="reward"; HIM["t"]=0.0
        if not h.get("done"):
            h["done"]=True
            us=gd.setdefault("unlocked_skins",["Classic"])
            if HIM_SKIN not in us: us.append(HIM_SKIN); check_skin_badges()
            award_badge(HIM_BADGE); save_gd(gd); SND_CHIME.play()
    return None

def _him_story(surf, dt, events):
    W,H=surf.get_size(); sc=HIM_STORY[HIM["story"]]
    HIM["st"]+=dt; HIM["click_t"]+=dt
    fn,ln=sc[HIM["scene"]]
    skip=any(ev.type==pygame.MOUSEBUTTONDOWN and ev.button==1 for ev in events) and HIM["click_t"]>0.6
    if HIM["st"]>=ln or skip:
        HIM["scene"]+=1; HIM["st"]=0.0; HIM["click_t"]=0.0
        if HIM["scene"]>=len(sc): return _him_story_end()
        fn,ln=sc[HIM["scene"]]
    fn(surf,W,H,HIM["st"])
    fade=min(1.0,HIM["st"]/0.35)
    if fade<1: o=pygame.Surface((W,H),pygame.SRCALPHA); o.fill((0,0,0,int(255*(1-fade)))); surf.blit(o,(0,0))
    for i in range(len(sc)):                                           # progress dots
        pygame.draw.circle(surf,(230,40,50) if i==HIM["scene"] else ((200,200,210) if i<HIM["scene"] else (70,70,80)),(W-20-(len(sc)-1-i)*16,18),5)
    hs=ui_font(min(W,H)*0.022).render("Click = next   •   ESC = leave",True,(150,140,160)); surf.blit(hs,(14,10))
    if ui_esc(events): return "exit" if HIM["replay"] else "hall"
    return None

# ── the hall: words on the walls, a big YOU ──────────────────────────────────
def _him_hall_bg(surf, W, H, t, dim=1.0):
    surf.fill((14,10,12))
    bw=pygame.Rect(int(W*0.22),int(H*0.12),int(W*0.56),int(H*0.56))
    pygame.draw.polygon(surf,(30,24,26),[(0,0),(bw.x,bw.y),(bw.x,bw.bottom),(0,H)])
    pygame.draw.polygon(surf,(30,24,26),[(W,0),(bw.right,bw.y),(bw.right,bw.bottom),(W,H)])
    pygame.draw.polygon(surf,(20,15,16),[(0,H),(bw.x,bw.bottom),(bw.right,bw.bottom),(W,H)])
    pygame.draw.polygon(surf,(12,9,10),[(0,0),(bw.x,bw.y),(bw.right,bw.y),(W,0)])
    pygame.draw.rect(surf,(40,32,34),bw)
    rnd=random.Random(38)
    for k in range(46):                                                # the words they said
        w=HIM_WORDS[k%len(HIM_WORDS)]; side=k%3
        col=rnd.choice(((150,20,26),(190,185,180),(120,15,20)))
        s=ui_font(min(W,H)*rnd.uniform(0.026,0.05)).render(w,True,col)
        s=pygame.transform.rotate(s,rnd.uniform(-14,14)); s.set_alpha(int(200*dim*(0.75+0.25*math.sin(t*1.3+k))))
        keep=pygame.Rect(int(W*0.27),int(H*0.25),int(W*0.46),int(H*0.31))   # nothing written over YOU
        for _ in range(12):
            if side==0: x=rnd.uniform(0.0,0.2)*W-s.get_width()*0.3; y=rnd.uniform(0.1,0.82)*H
            elif side==1: x=rnd.uniform(0.79,0.98)*W-s.get_width()*0.6; y=rnd.uniform(0.1,0.82)*H
            else: x=rnd.uniform(0.23,0.77)*W-s.get_width()*0.5; y=rnd.uniform(0.13,0.64)*H
            if not s.get_rect(topleft=(int(x),int(y))).colliderect(keep): break
        else: continue
        surf.blit(s,(int(x),int(y)))
    if int(t*7)%23==0 or (int(t*13)%41==0):                            # the light flickers
        o=pygame.Surface((W,H),pygame.SRCALPHA); o.fill((0,0,0,150)); surf.blit(o,(0,0))
    pygame.draw.line(surf,(60,55,50),(W//2,0),(W//2,int(H*0.06)),2)
    pygame.draw.circle(surf,(255,230,170) if int(t*7)%23 else (60,55,50),(W//2,int(H*0.07)),7)
    _him_vignette(surf,W,H,(0,0,0),220)

def _him_hall(surf, dt, mouse, events):
    W,H=surf.get_size(); t=HIM["t"]
    _him_hall_bg(surf,W,H,t)
    big=ui_font(min(W,H)*0.28); ys=big.render("YOU",True,HIM_RED); r=ys.get_rect(center=(W//2,int(H*0.4)))
    hv=ui_hover("him_you",1.0 if r.inflate(30,30).collidepoint(mouse) else 0.0,dt)
    sc=1.0+0.05*hv+0.02*math.sin(t*3)
    g=pygame.transform.smoothscale(ys,(int(ys.get_width()*sc*1.08),int(ys.get_height()*sc*1.08))); g.set_alpha(int(60+60*hv+30*math.sin(t*4)))
    surf.blit(g,g.get_rect(center=r.center))
    yy=pygame.transform.smoothscale(ys,(int(ys.get_width()*sc),int(ys.get_height()*sc))); surf.blit(yy,yy.get_rect(center=r.center))
    tt=ui_font(min(W,H)*0.05).render("THE HIM",True,(210,200,210)); surf.blit(tt,tt.get_rect(centerx=W//2,y=int(H*0.73)))
    st=him_state()
    sub="5/11 - 7/11  •  Click YOU" if st=="active" else "Click YOU"
    if t>1.5:
        ss=ui_font(min(W,H)*0.03).render(sub,True,(170,150,170)); ss.set_alpha(int(255*min(1,(t-1.5)*2))); surf.blit(ss,ss.get_rect(centerx=W//2,y=int(H*0.79)))
    bk=ui_back(surf,dt,mouse)
    if ui_click(events,bk) or ui_esc(events): return "exit"
    if ui_click(events,r.inflate(30,30)):
        SND_SLAM.play(); start_shake(10,20)
        h=him_data()
        if st!="active": him_story_start("full"); HIM["replay"]=True
        elif h.get("seen1"): HIM["screen"]="map"; HIM["t"]=0.0
        else: him_story_start("part1")
    return None

# ── the 10 levels ────────────────────────────────────────────────────────────
class HimRound:
    """COLOR level: go by the WORD, not the ink. need = right answers, 3 mistakes = fail."""
    def __init__(s, i):
        s.i=i; s.need=8+2*i; s.right_n=0; s.lives=3; s.intro=2.2; s.res=None; s.res_t=0.0
        s.flash=0.0; s.fcol=WHITE; s.pops=[]; s.size=(0,0); s.build(); s.new_q()
    def tlim(s): return max(2.2,4.0-0.35*s.i)
    def build(s):
        W,H=WIDTH,HEIGHT; s.size=(W,H); top=int(H*0.34); bot=H-int(H*0.1); m=int(W*0.12)
        cw=(W-2*m)//4; ch=(bot-top)//3
        s.grid=[{"rect":pygame.Rect(m+c*cw+6,top+r*ch+6,cw-12,ch-12),"name":"RED","ph":random.uniform(0,6.3)} for r in range(3) for c in range(4)]
    def new_q(s):
        if (WIDTH,HEIGHT)!=s.size: s.build()
        names=COLOR_NAMES*2; random.shuffle(names)
        for c,n in zip(s.grid,names): c["name"]=n
        s.target=random.choice(COLOR_NAMES)
        if not any(c["name"]==s.target for c in s.grid): random.choice(s.grid)["name"]=s.target
        s.ink=random.choice([c for c in COLOR_NAMES if c!=s.target]) if random.random()<0.45+0.08*s.i else s.target
        s.deadline=time.time()+s.tlim()
    def update(s, dt):
        if s.res: s.res_t+=dt; return
        if s.intro>0: s.intro-=dt; s.deadline=time.time()+s.tlim(); return
        if time.time()>s.deadline: s.wrong(True)
        for p in s.pops: p["y"]-=40*dt; p["life"]-=dt
        s.pops=[p for p in s.pops if p["life"]>0]; s.flash=max(0.0,s.flash-dt*3)
    def click(s, pos):
        if s.res or s.intro>0: return
        for c in s.grid:
            if c["rect"].collidepoint(pos):
                if c["name"]==s.target:
                    s.right_n+=1; SND_CORRECT.play(); s.flash=1.0; s.fcol=NEON[s.target]
                    if s.right_n>=s.need: s.res="win"; s.res_t=0.0; SND_CHIME.play(); return
                    s.new_q()
                else: s.wrong()
                return
    def wrong(s, timeout=False):
        s.lives-=1; SND_WRONG.play(); start_shake(8,18); s.flash=1.0; s.fcol=(200,0,0)
        s.pops.append({"t":"TOO SLOW!" if timeout else "WRONG!","x":WIDTH//2,"y":int(HEIGHT*0.3),"life":0.9})
        if s.lives<=0: s.res="lose"; s.res_t=0.0; SND_SCREAM.play(); return
        s.new_q()
    def draw(s, surf, mouse, t):
        W,H=surf.get_size(); _him_hall_bg(surf,W,H,t,0.35)
        o=pygame.Surface((W,H),pygame.SRCALPHA); o.fill((0,0,0,120)); surf.blit(o,(0,0))
        f=ui_font(min(W,H)*0.07); cmd=f"FIND  {s.target}!"
        a=f.render(cmd,True,NEON[s.ink]); b_=f.render(cmd,True,(5,2,6)); r=a.get_rect(centerx=W//2,y=int(H*0.15))
        surf.blit(b_,r.move(3,3)); surf.blit(a,r)
        ratio=max(0.0,min(1.0,(s.deadline-time.time())/s.tlim()))
        bx,bw=int(W*0.12),W-int(W*0.24); pygame.draw.rect(surf,(30,15,20),(bx,r.bottom+8,bw,10),border_radius=5)
        pygame.draw.rect(surf,(120,220,40) if ratio>0.5 else (255,170,40) if ratio>0.25 else HIM_RED,(bx,r.bottom+8,int(bw*ratio),10),border_radius=5)
        for c in s.grid:
            rr=c["rect"].inflate(int(3*math.sin(t*2+c["ph"])),int(3*math.sin(t*2+c["ph"]))); col=NEON[c["name"]]; hv=rr.collidepoint(mouse)
            pygame.draw.rect(surf,(col[0]//4,col[1]//4,col[2]//4),rr.move(0,4),border_radius=14)
            pygame.draw.rect(surf,_mix(col,WHITE,0.15) if hv else col,rr,border_radius=14)
            lb=ui_font(min(rr.w,rr.h)*0.26).render(c["name"],True,_text_on(col)); surf.blit(lb,lb.get_rect(center=rr.center))
        for p in s.pops:
            ps=ui_font(min(W,H)*0.045).render(p["t"],True,(255,90,90)); ps.set_alpha(int(255*min(1,p["life"]*2))); surf.blit(ps,ps.get_rect(center=(int(p["x"]),int(p["y"]))))
        if s.flash>0: o=pygame.Surface((W,H),pygame.SRCALPHA); o.fill((*s.fcol,int(55*s.flash))); surf.blit(o,(0,0))
        _him_hud(surf,W,H,t,f"{s.right_n} / {s.need}",s.lives)
        if s.intro>0:
            o=pygame.Surface((W,H),pygame.SRCALPHA); o.fill((6,2,4,215)); surf.blit(o,(0,0))
            for k,(ln,sz,col) in enumerate(((f"LEVEL {s.i+1}  •  COLOR",0.07,HIM_RED),(f"Get {s.need} right. 3 mistakes = you lose.",0.032,(225,215,225)),
                                           ("Go by the WORD, not the ink!",0.032,(225,215,225)))):
                ls=ui_font(min(W,H)*sz).render(ln,True,col); surf.blit(ls,ls.get_rect(center=(W//2,int(H*(0.34+k*0.08)))))
            n=ui_font(min(W,H)*0.1).render(str(int(math.ceil(s.intro))),True,WHITE); surf.blit(n,n.get_rect(center=(W//2,int(H*0.7))))

def _him_hud(surf, W, H, t, left_txt, lives):
    hud=pygame.Rect(20,14,W-40,62); hp=pygame.Surface(hud.size,pygame.SRCALPHA)
    pygame.draw.rect(hp,(18,8,10,225),hp.get_rect(),border_radius=20); pygame.draw.rect(hp,(140,20,30,200),hp.get_rect(),2,border_radius=20); surf.blit(hp,hud.topleft)
    lv=him_data()["lvl"]
    lt=ui_font(30).render(f"THE HIM  •  LEVEL {HIM['lvl']+1} / 10",True,WHITE); surf.blit(lt,lt.get_rect(centerx=W//2,y=hud.y+6))
    for k in range(10):
        c_=(220,220,230) if k<lv else (HIM_RED if k==HIM["lvl"] else (60,40,45))
        pygame.draw.circle(surf,c_,(W//2-5*16+k*16+8,hud.y+48),5 if k==HIM["lvl"] else 4)
    surf.blit(ui_font(26).render(left_txt,True,(230,220,230)),(hud.x+22,hud.centery-12))
    for k in range(3): ui_icon2(surf,"heart",hud.right-36-k*38,hud.centery,13,(255,70,90) if k<lives else (60,50,60),t)

def him_start_level(i):
    HIM["lvl"]=i; HIM["res"]=None; HIM["res_t"]=0.0; kind,idx=HIM_LEVELS[i]
    if kind=="color": HIM["round"]=HimRound(idx); HIM["flow"]=None; HIM["screen"]="round"
    else: HIM["flow"]=FlowLevel(idx); HIM["round"]=None; HIM["lives"]=3; HIM["drag"]=False; HIM["screen"]="flow"; HIM["intro"]=2.2
    SND_SELECT.play()

def _him_level_won():
    h=him_data()
    if HIM["lvl"]>=h["lvl"]: h["lvl"]=HIM["lvl"]+1; save_gd(gd)

def _him_result(surf, dt, mouse, events, won):
    """LEVEL CLEAR / TRY AGAIN panel on top of the level. Returns 'next' / 'retry' / 'map' / None."""
    W,H=surf.get_size(); HIM["res_t"]+=dt
    o=pygame.Surface((W,H),pygame.SRCALPHA); o.fill((6,2,4,int(200*min(1,HIM["res_t"]*3)))); surf.blit(o,(0,0))
    ti=ui_font(min(W,H)*0.09).render("LEVEL CLEAR!" if won else "TRY AGAIN",True,(240,240,245) if won else HIM_RED)
    surf.blit(ti,ti.get_rect(center=(W//2,int(H*0.36))))
    msg=("He smiles a little." if HIM["lvl"]<9 else "He is smiling. For real.") if won else "He is still waiting for you..."
    ms=ui_font(min(W,H)*0.035).render(msg,True,(210,195,210)); surf.blit(ms,ms.get_rect(center=(W//2,int(H*0.46))))
    if HIM["res_t"]<0.5: return None
    b1=ui_pill(surf,"him_r1",pygame.Rect(W//2-230,int(H*0.58),210,50),"NEXT" if won else "RETRY",HIM_RED if not won else (60,190,110),dt,mouse,"play" if won else "back")
    b2=ui_pill(surf,"him_r2",pygame.Rect(W//2+20,int(H*0.58),210,50),"MAP",(90,80,110),dt,mouse,"back")
    if ui_click(events,b1): return "next" if won else "retry"
    if ui_click(events,b2) or ui_esc(events): return "map"
    return None

def _him_after_result(r):
    if r=="retry": him_start_level(HIM["lvl"])
    elif r=="map": HIM["screen"]="map"; HIM["t"]=0.0
    elif r=="next":
        if him_data()["lvl"]>=10: him_story_start("part2")
        else: him_start_level(him_data()["lvl"])

def _him_map(surf, dt, mouse, events):
    W,H=surf.get_size(); t=HIM["t"]; h=him_data()
    _him_hall_bg(surf,W,H,t,0.4); o=pygame.Surface((W,H),pygame.SRCALPHA); o.fill((0,0,0,130)); surf.blit(o,(0,0))
    tt=ui_font(min(W,H)*0.07).render("HELP THE HIM",True,HIM_RED); surf.blit(tt,tt.get_rect(centerx=W//2,y=int(H*0.05)))
    st=ui_font(min(W,H)*0.03).render("Pass 10 levels: 5 COLOR + 5 FLOW",True,(210,200,210)); surf.blit(st,st.get_rect(centerx=W//2,y=int(H*0.05)+tt.get_height()+4))
    nodes=[]; rad=int(min(W,H)*0.045)
    for i in range(10):
        row=i//5; col=i%5 if row==0 else 4-i%5
        nodes.append((int(W*(0.16+col*0.17)),int(H*(0.36 if row==0 else 0.64))))
    for i in range(9): pygame.draw.line(surf,(200,200,210) if i<h["lvl"] else (60,45,50),nodes[i],nodes[i+1],5)
    hov=None
    for i,(x,y) in enumerate(nodes):
        done=i<h["lvl"]; cur=i==h["lvl"] and h["lvl"]<10; ok=done or cur
        r=pygame.Rect(x-rad,y-rad,2*rad,2*rad); hv=ui_hover("him_n%d"%i,1.0 if (ok and r.collidepoint(mouse)) else 0.0,dt)
        if r.collidepoint(mouse): hov=i
        rr=int(rad*(1+0.1*hv+(0.06*math.sin(t*4) if cur else 0)))
        pygame.draw.circle(surf,(240,240,245) if done else (HIM_RED if cur else (45,35,40)),(x,y),rr)
        pygame.draw.circle(surf,(20,10,12),(x,y),rr,3)
        ns=ui_font(rad*1.0).render(str(i+1),True,(30,20,25) if done else (WHITE if cur else (110,95,100))); surf.blit(ns,ns.get_rect(center=(x,y)))
        kl=ui_font(min(W,H)*0.022).render("COLOR" if i<5 else "FLOW",True,(190,180,190) if ok else (90,80,85)); surf.blit(kl,kl.get_rect(centerx=x,y=y+rad+6))
        if ok and ui_click(events,r): him_start_level(i); return None
    if hov is not None:
        tip=("Find the WORD, not the ink." if hov<5 else "Connect every color before time runs out.")
        ts=ui_font(min(W,H)*0.03).render(tip,True,(230,220,230)); surf.blit(ts,ts.get_rect(centerx=W//2,y=int(H*0.78)))
    bk=ui_back(surf,dt,mouse)
    wa=ui_pill(surf,"him_watch",pygame.Rect(W-250,H-62,230,42),"WATCH AGAIN",(110,30,40),dt,mouse,"play")
    if h.get("done"):
        en=ui_pill(surf,"him_end",pygame.Rect(W-500,H-62,230,42),"THE END",(60,60,80),dt,mouse,"play")
        tw_=ui_pill(surf,"him_town",pygame.Rect(W//2-130,int(H*0.84),260,46),"VISIT HIS TOWN",(150,30,45),dt,mouse,"play")
        if ui_click(events,tw_): HIM["screen"]="town"; HIM["t"]=0.0; SND_SELECT.play(); return None
        if ui_click(events,en): him_story_start("part2"); HIM["replay"]=True; HIM["after_story"]="map"; return None
    if ui_click(events,wa): him_story_start("part1"); return None
    if ui_click(events,bk) or ui_esc(events): HIM["screen"]="hall"; HIM["t"]=0.0
    return None

def _him_reward(surf, dt, mouse, events):
    W,H=surf.get_size(); t=HIM["t"]; surf.fill((6,3,5)); _him_vignette(surf,W,H,(90,0,0),140)
    tt=ui_font(min(W,H)*0.06).render("You were his only friend.",True,(235,225,235)); surf.blit(tt,tt.get_rect(centerx=W//2,y=int(H*0.1)))
    b=get_badge(HIM_BADGE)
    if b: draw_badge_medal(surf,b,int(W*0.32),int(H*0.45),int(min(W,H)*0.12),True,t,0.0)
    bl=ui_font(min(W,H)*0.032).render("BADGE: HIS ONLY FRIEND",True,(255,215,90)); surf.blit(bl,bl.get_rect(centerx=int(W*0.32),y=int(H*0.62)))
    sk=SKINS[HIM_SKIN]; sw=int(min(W,H)*0.06)
    for k,n in enumerate(COLOR_NAMES):
        r=pygame.Rect(int(W*0.68)-int(1.5*sw)+(k%3)*sw,int(H*0.35)+(k//3)*sw,sw-6,sw-6); pygame.draw.rect(surf,sk[n],r,border_radius=8)
    sl=ui_font(min(W,H)*0.032).render("SKIN: The Him",True,(255,215,90)); surf.blit(sl,sl.get_rect(centerx=int(W*0.68),y=int(H*0.62)))
    hc=ui_font(min(W,H)*0.03).render("HE IS COMING.",True,HIM_RED); hc.set_alpha(int(160+90*math.sin(t*2))); surf.blit(hc,hc.get_rect(centerx=W//2,y=int(H*0.74)))
    vt=ui_pill(surf,"him_visit",pygame.Rect(W-280,H-62,260,42),"VISIT HIS TOWN",(150,30,45),dt,mouse,"play")
    if ui_click(events,vt): HIM["screen"]="town"; HIM["t"]=0.0; SND_SELECT.play(); return None
    bk=ui_back(surf,dt,mouse)
    if ui_click(events,bk) or ui_esc(events): return "exit"
    return None

def _him_teaser(surf, dt, events):
    """Before 5/11: the date, then HE IS COMING."""
    W,H=surf.get_size(); t=HIM["t"]; surf.fill((0,0,0))
    txt="5.11.2026" if t<3.0 else "HE IS COMING."
    a=min(1.0,(t%3.0)/0.6) if t<6.0 else max(0.0,1-(t-6.0)/0.8)
    s=ui_font(min(W,H)*0.12).render(txt,True,WHITE); s.set_alpha(int(255*a)); surf.blit(s,s.get_rect(center=(W//2,H//2)))
    if t>3.0 and "t_beep" not in HIM["cues"]: HIM["cues"].add("t_beep"); SND_LONG_BEEP.play()
    if t>7.0 or (t>0.5 and (ui_esc(events) or any(ev.type==pygame.MOUSEBUTTONDOWN for ev in events))): return "exit"
    return None

