TOWN_PLACES = ["school","home","grandma","airport","crash"]
TOWN_NAME = {"school":"SCHOOL","home":"HIS PARENTS' HOUSE","grandma":"GRANDMA'S HOUSE","airport":"AIRPORT","crash":"CRASH SITE"}
TOWN_POS  = {"school":(0.2,0.36),"home":(0.47,0.58),"grandma":(0.75,0.36),"airport":(0.22,0.76),"crash":(0.8,0.76)}

def him_town_open():
    return has_badge(HIM_BADGE) or dev_mode()

def _town_data():
    h=him_data(); h.setdefault("visited",[]); h.setdefault("candles",0); return h

def _him_dialog(lines):
    HIM["dlg"]=list(lines); HIM["dlg_i"]=0; HIM["dlg_t"]=0.0

def _draw_dialog(surf, dt, events):
    """Bottom dialog box. Returns True while it is open."""
    if not HIM.get("dlg"): return False
    W,H=surf.get_size(); HIM["dlg_t"]+=dt
    who,txt=HIM["dlg"][HIM["dlg_i"]]
    box=pygame.Rect(int(W*0.08),int(H*0.72),int(W*0.84),int(H*0.22))
    b=pygame.Surface(box.size,pygame.SRCALPHA); pygame.draw.rect(b,(10,6,10,235),b.get_rect(),border_radius=18)
    pygame.draw.rect(b,(150,30,40,220),b.get_rect(),2,border_radius=18); surf.blit(b,box.topleft)
    if who:
        ws=ui_font(min(W,H)*0.03).render(who,True,(255,200,120))
        surf.blit(ws,ws.get_rect(topright=(box.right-24,box.y+14)) if lang_code()=="HE" else (box.x+24,box.y+14))
    t_=tr(txt); n=max(1,int(len(t_)*min(1.0,HIM["dlg_t"]/max(0.5,len(t_)*0.03))))
    f=ui_font(min(W,H)*0.036); words=(t_ if n>=len(t_) else t_[:n]).split(" "); line=""; y=box.y+(52 if who else 26); rows=[]
    for w_ in words:
        if f.size(line+" "+w_)[0]>box.w-48 and line: rows.append(line); line=w_
        else: line=(line+" "+w_).strip()
    rows.append(line)
    for r_ in rows[:3]:
        rs=f.render(r_,True,(240,232,240)); surf.blit(rs,rs.get_rect(topright=(box.right-24,y)) if lang_code()=="HE" else (box.x+24,y)); y+=f.get_linesize()+2
    if HIM["dlg_t"]>0.4:
        hs=ui_font(min(W,H)*0.022).render("Click to continue",True,(150,135,150)); surf.blit(hs,hs.get_rect(bottomright=(box.right-18,box.bottom-10)))
    if HIM["dlg_t"]>0.25 and any(ev.type==pygame.MOUSEBUTTONDOWN and ev.button==1 for ev in events):
        if n<len(t_): HIM["dlg_t"]=99
        else:
            HIM["dlg_i"]+=1; HIM["dlg_t"]=0.0
            if HIM["dlg_i"]>=len(HIM["dlg"]):
                HIM["dlg"]=None; done=HIM.pop("dlg_done",None)
                if done: done()
    return True

