def _pl_school(surf, W, H, t):
    _him_room(surf,W,H,(34,40,56),(46,36,30),0.6)
    cb=pygame.Rect(int(W*0.25),int(H*0.08),int(W*0.5),int(H*0.25))
    pygame.draw.rect(surf,(80,58,36),cb.inflate(14,14),border_radius=6); pygame.draw.rect(surf,(18,40,30),cb)
    cs=ui_font(min(W,H)*0.05).render("WE'RE SORRY.",True,(215,225,215)); surf.blit(cs,cs.get_rect(center=cb.center))
    wr=pygame.Rect(int(W*0.04),int(H*0.1),int(W*0.14),int(H*0.24)); pygame.draw.rect(surf,(16,20,46),wr)
    pygame.draw.circle(surf,(235,235,210),(wr.x+int(wr.w*0.65),wr.y+int(wr.h*0.35)),int(wr.h*0.13)); pygame.draw.rect(surf,(120,120,130),wr,6)
    for i in range(6):
        row=i//3; x=W*(0.2+(i%3)*0.22)+(row*W*0.05); y=H*(0.66+row*0.13)
        pygame.draw.rect(surf,(90,64,42),(x-W*0.07,y-H*0.11,W*0.14,H*0.05),border_radius=4)
    d=pygame.Rect(int(W*0.74),int(H*0.8),int(W*0.16),int(H*0.055)); pygame.draw.rect(surf,(96,68,44),d,border_radius=4)
    sc=ui_font(min(W,H)*0.02).render("WHY ME?",True,(50,30,20)); surf.blit(sc,sc.get_rect(center=d.center))
    _him_vignette(surf,W,H,(0,0,0),210)
    return {"desk":d,"board":cb}

