    ph=pygame.Rect(int(W*0.2),int(H*0.14),int(W*0.12),int(H*0.17)); pygame.draw.rect(surf,(150,110,60),ph.inflate(12,12)); pygame.draw.rect(surf,(170,200,230),ph)
