def _pl_grandma(surf, W, H, t):
    _him_room(surf,W,H,(80,58,74),(70,50,40),0.64)
    for k in range(0,W,int(W*0.06)): pygame.draw.line(surf,(88,66,82),(k,0),(k,int(H*0.64)),8)
    fp=pygame.Rect(int(W*0.06),int(H*0.36),int(W*0.22),int(H*0.28)); pygame.draw.rect(surf,(110,64,50),fp)
    fr=fp.inflate(-int(fp.w*0.35),-int(fp.h*0.3)); fr.bottom=fp.bottom; pygame.draw.rect(surf,(20,10,8),fr)
    for k in range(5):
        fh=int(fr.h*(0.3+0.2*abs(math.sin(t*5+k)))); pygame.draw.ellipse(surf,(240,120+k*15,40),(fr.x+k*fr.w//5,fr.bottom-fh,fr.w//4,fh))
    rock=math.sin(t*1.2)*3; ch=pygame.Rect(int(W*0.58),int(H*0.44),int(W*0.24),int(H*0.3))
    pygame.draw.rect(surf,(110,55,85),ch.move(0,int(rock)),border_radius=26)
    _him_person(surf,W*0.7,H*0.74+rock,H*0.33,(120,85,160),(240,210,190),hair=(205,205,212),bun=True,glasses=True,mouth="sad",face=-1)
    sc=pygame.Rect(int(W*0.36),int(H*0.66),int(W*0.12),int(H*0.08))           # the scarf she knits
    pygame.draw.rect(surf,(200,30,40),sc,border_radius=8)
    for k in range(5): pygame.draw.line(surf,(150,20,30),(sc.x+8+k*int(sc.w/5),sc.y+4),(sc.x+8+k*int(sc.w/5),sc.bottom-4),2)
    pygame.draw.line(surf,(200,200,210),(sc.right-6,sc.y-10),(sc.right+16,sc.y+20),3)
    _him_vignette(surf,W,H,(0,0,0),170)
    return {"grandma":pygame.Rect(int(W*0.58),int(H*0.24),int(W*0.24),int(H*0.5)),"scarf":sc}

