    pygame.draw.rect(surf,(240,200,120),tm.inflate(-20,-int(tm.h*0.5)))
    bd=pygame.Rect(int(W*0.44),int(H*0.12),int(W*0.36),int(H*0.3)); pygame.draw.rect(surf,(18,18,24),bd,border_radius=8); pygame.draw.rect(surf,(90,90,100),bd,4,border_radius=8)
    f=ui_font(min(W,H)*0.028)
    surf.blit(f.render("DEPARTURES",True,(255,200,60)),(bd.x+16,bd.y+12))
    for i,(fl,st,col) in enumerate((("FLIGHT 12","ON TIME",(120,230,120)),("FLIGHT 38","BOARDING",(120,230,120)),("FLIGHT 61","---",(255,70,70)),("FLIGHT 77","DELAYED",(255,200,60)))):
        y=bd.y+int(bd.h*0.3)+i*int(bd.h*0.16)
