def _town_fx(surf, W, H, t):
    hz=int(H*0.24)
    for j in range(3):                                                 # clouds drifting by the moon
        x=int((t*12+j*W*0.4)%(W+300))-150; y=int(hz*(0.25+j*0.18))
        c=pygame.Surface((260,60),pygame.SRCALPHA)
        for dx,rr in ((40,22),(90,30),(140,26),(190,20)): pygame.draw.circle(c,(70,50,90,90),(dx,32),rr)
        surf.blit(c,(x,y))
    for j in range(3):                                                 # bats
        x=(t*70+j*400)%(W+200)-100; draw_bat(surf,x,hz*0.5+math.sin(t*2+j)*20,10,t+j,(14,8,18))
    for j in range(40):                                                # fireflies
        r=random.Random(j); x=r.uniform(0,W)+math.sin(t*0.6+j)*30; y=r.uniform(hz+20,H*0.95)+math.cos(t*0.8+j*2)*16
        a=int(120+120*math.sin(t*3+j*1.7))
        if a>60: pygame.draw.circle(surf,(255,240,140),(int(x),int(y)),2); _hglow(surf,x,y,8,(255,230,120),a//4)
    f=pygame.Surface((W,int(H*0.12)),pygame.SRCALPHA)                  # low fog
    for k in range(5):
        x=int((t*20+k*W*0.3)%(W+400))-200; pygame.draw.ellipse(f,(150,140,170,22),(x,int(H*0.03),420,int(H*0.08)))
    surf.blit(f,(0,int(H*0.72)))
    ry=int(H*0.95)
    for k in range(18):
        x=int((k*97+t*30)%W); pygame.draw.line(surf,(70,96,140),(x,ry+6+(k%4)*int((H-ry)/5)),(x+24,ry+6+(k%4)*int((H-ry)/5)),2)

def _him_town(surf, dt, mouse, events):
    W,H=surf.get_size(); t=HIM["t"]; d=_town_data()
    surf.blit(_town_static(W,H),(0,0)); _town_fx(surf,W,H,t)
    allv=set(TOWN_PLACES)<=set(d["visited"]); s=int(min(W*0.12,H*0.17)); hov=None
    for k in sorted(TOWN_PLACES,key=lambda q: TOWN_POS[q][1]):
        cx,cy=int(TOWN_POS[k][0]*W),int(TOWN_POS[k][1]*H); r=pygame.Rect(0,0,int(s*1.4),int(s*1.2)); r.center=(cx,cy-int(s*0.05))
        hv=ui_hover("town_"+k,1.0 if r.collidepoint(mouse) else 0.0,dt)
        if r.collidepoint(mouse): hov=k
        _bldg(surf,k,cx,cy,s,t,hv,dark_eyes=(k=="home" and allv))
        nm=ui_font(min(W,H)*0.024).render(TOWN_NAME[k],True,(250,240,245) if hv>0 else (200,190,200))
        pl=pygame.Rect(0,0,nm.get_width()+22,nm.get_height()+8); pl.midtop=(cx,cy+int(s*0.44))
        p_=pygame.Surface(pl.size,pygame.SRCALPHA); pygame.draw.rect(p_,(10,6,12,190),p_.get_rect(),border_radius=pl.h//2)
        pygame.draw.rect(p_,(*_mix((80,60,80),HIM_RED,hv),220),p_.get_rect(),2,border_radius=pl.h//2); surf.blit(p_,pl.topleft); surf.blit(nm,nm.get_rect(center=pl.center))
        if k in d["visited"]:
            pygame.draw.circle(surf,(60,170,90),(pl.right+2,pl.centery),9)
            pygame.draw.lines(surf,WHITE,False,[(pl.right-3,pl.centery),(pl.right+1,pl.centery+4),(pl.right+7,pl.centery-4)],2)
        if ui_click(events,r):
            HIM["screen"]="place"; HIM["place"]=k; HIM["t"]=0.0; HIM["dlg"]=None; HIM["letter"]=None; SND_SELECT.play()
            if k not in d["visited"]: d["visited"].append(k); save_gd(gd)
            return None
    _him_vignette(surf,W,H,(0,0,0),170)
    tt=ui_font(min(W,H)*0.06).render("HIS TOWN",True,(245,235,245)); surf.blit(tt,tt.get_rect(centerx=W//2,y=int(H*0.025)))
    st=ui_font(min(W,H)*0.026).render(f"Visited {len(set(d['visited'])&set(TOWN_PLACES))} / {len(TOWN_PLACES)}",True,(210,190,210)); surf.blit(st,st.get_rect(centerx=W//2,y=int(H*0.025)+tt.get_height()))
    if allv:
        _hg=d.get("hugged"); hs=ui_font(min(W,H)*0.026).render("He is smiling now." if _hg else "...he knows you were here.",True,(255,170,190) if _hg else HIM_RED); hs.set_alpha(int(150+100*math.sin(t*1.5))); surf.blit(hs,hs.get_rect(centerx=W//2,y=int(H*0.025)+tt.get_height()+st.get_height()+4))
    bk=ui_back(surf,dt,mouse)
    ws=ui_pill(surf,"town_story",pygame.Rect(W-260,H-62,240,42),"WATCH HIS STORY",(110,30,40),dt,mouse,"play")
    if HIM["t"]<0.4: o=pygame.Surface((W,H),pygame.SRCALPHA); o.fill((0,0,0,int(255*(1-HIM["t"]/0.4)))); surf.blit(o,(0,0))
    if ui_click(events,ws): him_story_start("full"); HIM["replay"]=True; HIM["after_story"]="town"; return None
    if ui_click(events,bk) or ui_esc(events): return "exit"
    return None

