    g=pygame.transform.smoothscale(ys,(int(ys.get_width()*1.06),int(ys.get_height()*1.06))); g.set_alpha(int(60+30*math.sin(t*3))); surf.blit(g,g.get_rect(center=r.center)); surf.blit(ys,r)
