def _letter_overlay(surf, dt, events, t):
    """Her letter. One click opens it, one click closes it."""
    W,H=surf.get_size(); HIM["letter"]+=dt; u=HIM["letter"]
    o=pygame.Surface((W,H),pygame.SRCALPHA); o.fill((0,0,0,int(190*min(1,u*4)))); surf.blit(o,(0,0))
    k=ease_out(min(1.0,u/0.45)) if "ease_out" in globals() else min(1.0,u/0.45)
    pw,ph=int(W*0.56),int(H*0.86*max(0.06,k)); p=pygame.Rect(0,0,pw,ph); p.center=(W//2,H//2)
    pygame.draw.rect(surf,(250,244,230),p,border_radius=6)
    for y in range(p.y+int(H*0.12),p.bottom-10,int(H*0.05)): pygame.draw.line(surf,(200,215,235),(p.x+20,y),(p.right-20,y),1)
    pygame.draw.line(surf,(240,170,180),(p.x+int(pw*0.09),p.y),(p.x+int(pw*0.09),p.bottom),2)
    if k>=1:
        f=ui_font(min(W,H)*0.032); y=p.y+int(H*0.05); he=lang_code()=="HE"
        for line in LETTER_EN:
            t_=tr(line); words=t_.split(" "); row=""
            rows=[]
            for w_ in words:
                if f.size(row+" "+w_)[0]>pw-int(pw*0.2) and row: rows.append(row); row=w_
                else: row=(row+" "+w_).strip()
            rows.append(row)
            for r_ in rows:
                rs=f.render(r_,True,(40,50,120)); surf.blit(rs,rs.get_rect(topright=(p.right-int(pw*0.06),y)) if he else (p.x+int(pw*0.13),y)); y+=int(H*0.05)
            if line=="Dear H,": y+=int(H*0.01)
        _him_heart(surf,p.right-int(pw*0.14),p.bottom-int(H*0.09),int(H*0.03),(235,70,100))
        hs=ui_font(min(W,H)*0.022).render("Click to close",True,(150,140,150)); surf.blit(hs,hs.get_rect(centerx=W//2,y=p.bottom+8))
    if u>0.6 and any(ev.type==pygame.MOUSEBUTTONDOWN and ev.button==1 for ev in events): HIM["letter"]=None; SND_SELECT.play()

