def _place_fx(surf, k, W, H, t):
    """A bit of life in every place."""
    if k in ("school","home","grandma","room"):                         # dust in the light
        for j in range(30):
            r=random.Random(j); x=(r.uniform(0,W)+t*8*(1+j%3))%W; y=(r.uniform(0,H*0.7)+math.sin(t+j)*10)
            pygame.draw.circle(surf,(230,220,200),(int(x),int(y)),1)
    if k=="school":                                                    # moonlight through the window
        beam=pygame.Surface((W,H),pygame.SRCALPHA); pygame.draw.polygon(beam,(180,200,255,26),[(int(W*0.04),int(H*0.1)),(int(W*0.18),int(H*0.1)),(int(W*0.5),int(H*0.95)),(int(W*0.2),int(H*0.95))]); surf.blit(beam,(0,0))
    if k=="grandma": _hglow(surf,W*0.17,H*0.55,int(H*0.35),(255,140,60),int(36+10*math.sin(t*7)))
    if k=="home": _hglow(surf,W*0.5,H*0.12,int(H*0.3),(255,210,140),26)
    if k in ("crash","airport"):
        for j in range(25):
            r=random.Random(j+9); x=r.uniform(0,W)+math.sin(t*0.6+j)*30; y=r.uniform(H*0.45,H*0.95)+math.cos(t*0.8+j)*14
            if math.sin(t*3+j*1.7)>0: pygame.draw.circle(surf,(255,240,140),(int(x),int(y)),2)

def _him_place(surf, dt, mouse, events):
    W,H=surf.get_size(); t=HIM["t"]; k=HIM["place"]; fn,talks=PLACES[k]
    spots=fn(surf,W,H,t); _place_fx(surf,k,W,H,t)
    nm=ui_font(min(W,H)*0.045).render(TOWN_NAME[k],True,(245,235,245))
    pl=pygame.Rect(14,12,nm.get_width()+28,nm.get_height()+12); p_=pygame.Surface(pl.size,pygame.SRCALPHA)
    pygame.draw.rect(p_,(10,6,12,200),p_.get_rect(),border_radius=14); pygame.draw.rect(p_,(150,30,45,220),p_.get_rect(),2,border_radius=14); surf.blit(p_,pl.topleft); surf.blit(nm,nm.get_rect(center=pl.center))
    if t<0.4: o=pygame.Surface((W,H),pygame.SRCALPHA); o.fill((0,0,0,int(255*(1-t/0.4)))); surf.blit(o,(0,0))
    if HIM.get("letter") is not None: _letter_overlay(surf,dt,events,t); return None
    if HIM.get("dlg"): _draw_dialog(surf,dt,events); return None
    hov=None
    for key,r in spots.items():
        if key in talks and r.collidepoint(mouse): hov=key
    for key,r in spots.items():
        if key not in talks: continue
        pulse=0.5+0.5*math.sin(t*3+len(key))
        _hglow(surf,r.centerx,r.y-8,16,(255,220,140),int(60+60*pulse)); pygame.draw.circle(surf,(255,236,170),(r.centerx,r.y-8),5 if hov!=key else 8)
        if hov==key: pygame.draw.rect(surf,(255,220,140),r.inflate(10,10),2,border_radius=10)
    hint=ui_font(min(W,H)*0.024).render("Click the glowing things",True,(210,200,210)); surf.blit(hint,hint.get_rect(centerx=W//2,y=H-40))
    bk=ui_back(surf,dt,mouse)
    if ui_click(events,bk) or ui_esc(events): HIM["screen"]="town"; HIM["t"]=0.0; return None
    if hov and ui_click(events,spots[hov]):
        SND_SELECT.play()
        if callable(talks[hov]): talks[hov](); return None              # a little script (talking to THE HIM)
        _him_dialog(talks[hov])
        if k=="crash" and hov=="candles": HIM["dlg_done"]=_light_candle
        if k=="crash" and hov=="letter": HIM["dlg_done"]=lambda: HIM.update({"letter":0.0})
    return None

