def _bldg_hishouse(surf, cx, cy, s, t, hv, warm):
    b=pygame.Rect(0,0,int(s*0.72),int(s*0.5)); b.midbottom=(cx,cy+int(s*0.36))
    pygame.draw.rect(surf,(58,44,40),b)
    for k in range(5): pygame.draw.line(surf,(46,34,32),(b.x,b.y+k*int(b.h/5)),(b.right,b.y+k*int(b.h/5)),2)      # old planks
    pygame.draw.polygon(surf,(30,22,24),[(b.x-int(s*0.08),b.y+2),(cx-int(s*0.1),b.y-int(s*0.34)),(b.right+int(s*0.04),b.y+2)])
    for j,wx in enumerate((0.12,0.6)):
        wr=pygame.Rect(b.x+int(b.w*wx),b.y+int(b.h*0.25),int(b.w*0.26),int(b.h*0.32))
        if warm: pygame.draw.rect(surf,(255,214,120),wr); _hglow(surf,wr.centerx,wr.centery,int(s*0.25),(255,190,90),70)
        else:
            pygame.draw.rect(surf,(14,10,14),wr)
            if j==0: pygame.draw.circle(surf,(255,200,90),(wr.centerx,wr.centery+4),3); _hglow(surf,wr.centerx,wr.centery,int(s*0.14),(255,170,60),40)
            for k in (-1,1): pygame.draw.line(surf,(90,70,56),(wr.x-3,wr.centery+k*6),(wr.right+3,wr.centery-k*6),4)       # boarded up
            if j==1 and int(t*2)%6:
                for ex in (-5,5): pygame.draw.ellipse(surf,(255,30,30),(wr.centerx+ex-3,wr.centery-2,6,4))
    pygame.draw.rect(surf,(36,26,24),(cx-int(s*0.07),b.bottom-int(s*0.22),int(s*0.14),int(s*0.22)))
    if hv>0: _hglow(surf,cx,cy,int(s*0.9),(255,60,70),int(50*hv))

_bldg_old=_bldg
def _bldg(surf, k, cx, cy, s, t, hv, dark_eyes=False):
    if k=="hishouse": return _bldg_hishouse(surf,cx,cy,s,t,hv,_town_data().get("hugged"))
    return _bldg_old(surf,k,cx,cy,s,t,hv,dark_eyes=dark_eyes and not _town_data().get("hugged"))

def _pl_hishouse(surf, W, H, t):
    d=_town_data(); hug=d.get("hugged")
    _him_room(surf,W,H,(34,28,32) if not hug else (70,52,46),(30,22,20) if not hug else (60,42,32),0.66)
    for k in range(0,W,int(W*0.05)): pygame.draw.line(surf,(28,22,26) if not hug else (62,46,40),(k,0),(k,int(H*0.66)),3)
    wr=pygame.Rect(int(W*0.06),int(H*0.1),int(W*0.16),int(H*0.22)); pygame.draw.rect(surf,(18,22,48),wr)
    pygame.draw.circle(surf,(235,235,210),(wr.x+int(wr.w*0.6),wr.y+int(wr.h*0.4)),int(wr.h*0.13))
    if not hug:
        for k in (-1,1): pygame.draw.line(surf,(80,60,48),(wr.x-6,wr.centery+k*20),(wr.right+6,wr.centery-k*20),10)
    pygame.draw.rect(surf,(80,64,56),wr,6)
    bed=pygame.Rect(int(W*0.04),int(H*0.62),int(W*0.26),int(H*0.14)); pygame.draw.rect(surf,(60,50,70),bed,border_radius=10); pygame.draw.rect(surf,(200,200,210),(bed.x+10,bed.y-12,int(bed.w*0.28),26),border_radius=8)
    dr=[]                                                               # his crayon drawings on the wall
    for j in range(3):
        p=pygame.Rect(int(W*(0.3+j*0.12)),int(H*(0.12+0.05*(j%2))),int(W*0.1),int(H*0.13)); pygame.draw.rect(surf,(240,236,226),p)
        if j==0: _him_kid(surf,p.centerx-12,p.bottom-6,p.h*0.7,t,mood="smile",face=0); _him_person(surf,p.centerx+14,p.bottom-6,p.h*0.72,(240,120,160),(250,215,190),hair=(110,60,30),long_hair=True,dress=True)
        elif j==1: _him_plane(surf,p.centerx,p.centery,p.h*0.4); pygame.draw.circle(surf,(255,210,60),(p.right-14,p.y+14),8)
        else: _him_heart(surf,p.centerx,p.centery,int(p.h*0.22),(230,60,90))
        dr.append(p)
    ph=pygame.Rect(int(W*0.68),int(H*0.5),int(W*0.06),int(H*0.08)); pygame.draw.rect(surf,(120,90,60),(ph.x-4,ph.bottom,ph.w+8,int(H*0.16)))   # small table + her photo
    pygame.draw.rect(surf,(150,110,60),ph.inflate(8,8)); pygame.draw.rect(surf,(170,210,240),ph)
    _him_person(surf,ph.centerx,ph.bottom-2,ph.h*0.9,(240,120,160),(250,215,190),hair=(110,60,30),long_hair=True,dress=True,mouth="smile",face=0)
    cx_=ph.right+int(W*0.03); pygame.draw.rect(surf,(240,235,220),(cx_-5,ph.bottom-20,10,20)); fl=6+2*math.sin(t*9)
    pygame.draw.ellipse(surf,(255,190,60),(cx_-4,ph.bottom-20-fl*2,8,fl*2)); _hglow(surf,cx_,ph.bottom-26,int(H*0.2),(255,170,60),int(55+15*math.sin(t*7)))
    # THE HIM himself
    red=HIM.get("hh_red",0.0 if hug else 1.0); st=HIM.get("hh_step",0.0)
    x=W*(0.56-0.06*st); y=H*(0.9+0.04*st); sz=H*(0.36+0.08*st)
    _him_kid(surf,x,y,sz,t,mood="smile" if red<0.4 else "sad",grow=0.35,red=red,face=-1 if st<0.5 else 0,arm_up=1 if st>0.6 else 0)
    if hug:
        for j in range(3): _him_heart(surf,x+math.sin(t*2+j)*30,y-sz*1.6-((t*30+j*40)%120),8,(255,120,150))
    _him_vignette(surf,W,H,(0,0,0),200 if not hug else 120)
    return {"him":pygame.Rect(int(x-sz*0.3),int(y-sz*1.45),int(sz*0.6),int(sz*1.45)),"drawings":dr[0].union(dr[2]),"photo":ph}

def _him_choice(opts):
    HIM["choice"]=opts; HIM["choice_t"]=0.0

def _draw_choice(surf, dt, mouse, events):
    if not HIM.get("choice"): return False
    W,H=surf.get_size(); HIM["choice_t"]+=dt
    o=pygame.Surface((W,H),pygame.SRCALPHA); o.fill((0,0,0,110)); surf.blit(o,(0,0))
    for i,(txt,fn) in enumerate(HIM["choice"]):
        r=pygame.Rect(0,0,int(W*0.5),int(H*0.08)); r.center=(W//2,int(H*(0.74+i*0.11)))
        hv=r.collidepoint(mouse)
        pygame.draw.rect(surf,(150,30,45) if hv else (30,16,22),r,border_radius=16); pygame.draw.rect(surf,(230,90,100),r,2,border_radius=16)
        ts=ui_font(min(W,H)*0.036).render(txt,True,WHITE); surf.blit(ts,ts.get_rect(center=r.center))
        if HIM["choice_t"]>0.3 and ui_click(events,r): HIM["choice"]=None; SND_SELECT.play(); fn(); return True
    return True

def _hh_talk():
    d=_town_data()
    if d.get("hugged"):
        _him_dialog([("THE HIM","Hey, friend."),("THE HIM","I read her letter again today. Every day, actually."),
                     ("THE HIM","Thank you for not being scared of me.")]); return
    _him_dialog([("THE HIM","..."),("THE HIM","What do you want?")])
    HIM["dlg_done"]=lambda: _him_choice([("You're not scary.",_hh_notscary),("Nothing... sorry.",_hh_leave)])

def _hh_leave(): _him_dialog([("THE HIM","Then leave.")])

def _hh_notscary():
    _him_dialog([("You","You're not scary."),("THE HIM","...What did you say?"),("You","You're not scary. You never were."),
                 ("THE HIM","Nobody... ever said that to me.")])
    HIM["dlg_done"]=lambda: HIM.update({"hh_anim":"step","hh_anim_t":0.0})

def _hh_wait():
    if _town_data().get("has_letter"):
        _him_dialog([("You","WAIT!"),("You","I found something at the crash site. It's from her.")])
        HIM["dlg_done"]=lambda: HIM.update({"letter":0.0,"after_letter":_hh_after_letter})
    else:
        _him_dialog([("You","WAIT!"),("You","I want to bring you something first."),("","Maybe there is something at the CRASH SITE..."),("THE HIM","...I'll be here.")])
        HIM["dlg_done"]=lambda: HIM.update({"hh_step":0.0})

def _hh_after_letter():
    HIM["hh_anim"]="eyes"; HIM["hh_anim_t"]=0.0
    _him_dialog([("THE HIM","She... she wrote to me."),("THE HIM","\"You're the kindest boy I know.\""),("THE HIM","...Thank you. For everything.")])
    HIM["dlg_done"]=lambda: HIM.update({"hug":0.0})

def _hh_update(dt):
    a=HIM.get("hh_anim")
    if not a: return
    HIM["hh_anim_t"]=HIM.get("hh_anim_t",0.0)+dt; u=HIM["hh_anim_t"]
    if a=="step":                                                       # he comes closer to hug you...
        HIM["hh_step"]=min(1.0,u/1.2)
        if u>1.3: HIM["hh_anim"]=None; _hh_wait()
    elif a=="eyes":                                                     # ...and the red goes away
        HIM["hh_red"]=max(0.0,1.0-u/2.5)
        if u>2.5: HIM["hh_anim"]=None

def _draw_hug(surf, dt, events):
    W,H=surf.get_size(); HIM["hug"]+=dt; u=HIM["hug"]
    if u<0.05: SND_CHIME.play()
    a=min(1.0,u/1.2); o=pygame.Surface((W,H),pygame.SRCALPHA); o.fill((255,226,200,int(235*a))); surf.blit(o,(0,0))
    for j in range(14):
        r=random.Random(j); x=r.uniform(0.05,0.95)*W; y=H-((u*90*r.uniform(0.6,1.4)+r.uniform(0,H))%(H+60))
        _him_heart(surf,x,y,int(r.uniform(8,20)),(235,80,110))
    if u>0.9:
        s1=ui_font(min(W,H)*0.07).render("He hugged you.",True,(120,30,50)); s1.set_alpha(int(255*min(1,(u-0.9)/0.5))); surf.blit(s1,s1.get_rect(center=(W//2,int(H*0.42))))
    if u>2.0:
        s2=ui_font(min(W,H)*0.036).render("For the first time in a long time... THE HIM smiled.",True,(140,60,70)); s2.set_alpha(int(255*min(1,(u-2.0)/0.5))); surf.blit(s2,s2.get_rect(center=(W//2,int(H*0.52))))
    if u>3.0:
        s3=ui_font(min(W,H)*0.024).render("Click to continue",True,(150,110,110)); surf.blit(s3,s3.get_rect(center=(W//2,int(H*0.62))))
        if any(ev.type==pygame.MOUSEBUTTONDOWN and ev.button==1 for ev in events):
            d=_town_data(); d["hugged"]=True; save_gd(gd); HIM["hug"]=None; HIM["hh_red"]=0.0; HIM["hh_step"]=0.0
            award_badge("not_scary")                                   # SECRET badge

