    if HIM.get("choice"): PLACES[k][0](surf,W,H,HIM["t"]); _draw_choice(surf,dt,mouse,events); return None
    if HIM.get("hh_anim") and k=="hishouse": PLACES[k][0](surf,W,H,HIM["t"]); return None
    return _him_place_old(surf,dt,mouse,events)

