# ── THE HIM: music + sounds of every place (files next to the game, like THE HAUNT) ──
HIM_MUSIC_FILES={"theme":"him_theme.ogg","levels":"him_levels.ogg","town":"him_town.ogg"}
HIM_AMB_FILES={"rain":"him_amb_rain.ogg","fire":"him_amb_fire.ogg","clock":"him_amb_clock.ogg","crickets":"him_amb_crickets.ogg",
               "wind":"him_amb_wind.ogg","airport":"him_amb_airport.ogg","room":"him_amb_room.ogg"}
PLACE_AMB={"room":"room","school":"clock","home":"clock","grandma":"fire","street":"crickets","park":"rain","airport":"airport","crash":"wind"}
_HIM_SND={}; _HIM_AUD={"amb":None,"music":None}

def _him_sound(name):
    if name not in _HIM_SND:
        _HIM_SND[name]=None
        p=_res_path(name)
        if os.path.exists(p):
            try: _HIM_SND[name]=pygame.mixer.Sound(p)
            except Exception as e: print("[him] could not load",p,"->",e)
    return _HIM_SND[name]

def _him_amb_channel():
    try:
        if pygame.mixer.get_num_channels()<9: pygame.mixer.set_num_channels(9)
        pygame.mixer.set_reserved(1); return pygame.mixer.Channel(0)
    except Exception: return None

def him_amb(key):
    """Loop the sound of a place (rain, fire, clock...). None = silence."""
    if _HIM_AUD["amb"]==key: return
    _HIM_AUD["amb"]=key; ch=_him_amb_channel()
    if ch is None: return
    ch.fadeout(400)
    snd=_him_sound(HIM_AMB_FILES[key]) if key else None
    if snd:
        snd.set_volume(min(1.0,gd.get("sfx_volume",0.8)*0.75)); ch.play(snd,loops=-1,fade_ms=600)

def him_music(key):
    """THE HIM soundtrack: theme / levels / town. None = quiet."""
    global _cur_music
    k2="him_"+key if key else None
    if _HIM_AUD["music"]==k2 and _cur_music==k2: return
    _HIM_AUD["music"]=k2
    try:
        if key is None: pygame.mixer.music.fadeout(600); _cur_music=None; return
        p=_res_path(HIM_MUSIC_FILES[key])
        if not os.path.exists(p): pygame.mixer.music.fadeout(600); _cur_music=k2; return
        pygame.mixer.music.load(p); pygame.mixer.music.set_volume(min(1.0,gd.get("music_volume",0.8)*0.7)); pygame.mixer.music.play(-1,fade_ms=800)
        _cur_music=k2
    except Exception as e: print("[him music]",e); _cur_music=k2

def him_audio_tick():
    """Pick the right music and place sound for whatever screen THE HIM is on."""
    scr=HIM.get("screen")
    if HIM.get("hug") is not None:
        him_music(None); him_amb(None)
        if not HIM.get("hug_snd"):
            HIM["hug_snd"]=True; s=_him_sound("him_hug.ogg")
            if s: s.set_volume(min(1.0,gd.get("music_volume",0.8)*0.8)); s.play()
        return
    HIM["hug_snd"]=False
    if scr=="teaser": him_music(None); him_amb(None)
    elif scr in ("round","flow"): him_music("levels"); him_amb(None)
    elif scr=="town": him_music("town"); him_amb("crickets")
    elif scr=="place":
        k=HIM.get("place"); him_music("town")
        if k=="hishouse": him_amb("fire" if _town_data().get("hugged") else "room")
        else: him_amb(PLACE_AMB.get(k))
    else:
        him_music("theme"); him_amb("room" if scr=="hall" else None)

def him_audio_stop():
    him_amb(None); _HIM_AUD["music"]=None

def him_screen(surf, dt, mouse, events):
    """state 'him'. Returns 'exit' when the player leaves."""
    HIM["t"]+=dt; scr=HIM["screen"]
    try: him_audio_tick()
    except Exception as e: print("[him audio]",e)
    if scr=="teaser": return _him_teaser(surf,dt,events)
    if scr=="hall": return _him_hall(surf,dt,mouse,events)
    if scr=="story":
        r=_him_story(surf,dt,events)
        if r=="hall": HIM["screen"]="hall"; HIM["t"]=0.0; return None
        if r=="exit" and HIM.get("after_story")=="map": HIM["after_story"]=None; HIM["replay"]=False; HIM["screen"]="map"; HIM["t"]=0.0; return None
        if r=="exit" and HIM.get("after_story")=="town": HIM["after_story"]=None; HIM["replay"]=False; HIM["screen"]="town"; HIM["t"]=0.0; return None
        return r
    if scr=="town": return _him_town(surf,dt,mouse,events)
    if scr=="place": return _him_place(surf,dt,mouse,events)
    if scr=="map": return _him_map(surf,dt,mouse,events)
    if scr=="reward": return _him_reward(surf,dt,mouse,events)
    t=pygame.time.get_ticks()/1000
    if scr=="round":
        rd=HIM["round"]; rd.update(dt)
        for ev in events:
            if ev.type==pygame.MOUSEBUTTONDOWN and ev.button==1: rd.click(ev.pos)
        rd.draw(surf,mouse,t)
        if rd.res:
            if rd.res=="win" and HIM["res"] is None: _him_level_won(); HIM["res"]="win"
            r=_him_result(surf,dt,mouse,events,rd.res=="win")
            if r: _him_after_result(r)
        elif ui_esc(events): HIM["screen"]="map"
        return None
    if scr=="flow":
        lv=HIM["flow"]
        if HIM["res"] is None and HIM.get("intro",0)<=0:
            lv.tick(dt)
            if lv.all_done():
                _him_level_won(); HIM["res"]="win"; HIM["res_t"]=0.0; SND_CHIME.play()
            elif lv.time_left<=0:
                HIM["lives"]-=1; SND_WRONG.play(); start_shake(8,18)
                if HIM["lives"]<=0: HIM["res"]="lose"; HIM["res_t"]=0.0; SND_SCREAM.play()
                else: lv.time_left=lv.time_lim; lv.paths=[[] for _ in lv.pairs]; lv.active=-1
            else:
                for ev in events:
                    if ev.type==pygame.MOUSEBUTTONDOWN and ev.button==1:
                        cell=flow_cell(ev.pos,lv.gs)
                        if cell and lv.grab(cell): HIM["drag"]=True
                    if ev.type==pygame.MOUSEMOTION and HIM["drag"]:
                        cell=flow_cell(ev.pos,lv.gs)
                        if cell: lv.drag_to(cell)
                    if ev.type==pygame.MOUSEBUTTONUP and ev.button==1: lv.stop(); HIM["drag"]=False
                if HIM["drag"] and pygame.mouse.get_pressed()[0]:
                    cell=flow_cell(pygame.mouse.get_pos(),lv.gs)
                    if cell: lv.drag_to(cell)
        _mb=globals()["draw_menu_bg"]                                 # his room behind the board, not the menu
        globals()["draw_menu_bg"]=lambda s_,t_,a_=None: _him_hall_bg(s_,*s_.get_size(),t_,0.3)
        try: draw_flow(surf,lv,0,0,HIM["lives"])
        finally: globals()["draw_menu_bg"]=_mb
        W,H=surf.get_size(); _him_vignette(surf,W,H,(120,0,0),150)
        _him_hud(surf,W,H,t,f"{lv.n_done()} / {len(lv.pairs)}",HIM["lives"])
        if HIM.get("intro",0)>0:
            HIM["intro"]-=dt; lv.time_left=lv.time_lim
            o=pygame.Surface((W,H),pygame.SRCALPHA); o.fill((6,2,4,215)); surf.blit(o,(0,0))
            for k,(ln,sz,col) in enumerate(((f"LEVEL {HIM['lvl']+1}  •  FLOW",0.07,HIM_RED),("Connect every color before time runs out.",0.032,(225,215,225)),("3 lives",0.032,(225,215,225)))):
                ls=ui_font(min(W,H)*sz).render(ln,True,col); surf.blit(ls,ls.get_rect(center=(W//2,int(H*(0.34+k*0.08)))))
            n=ui_font(min(W,H)*0.1).render(str(int(math.ceil(HIM["intro"]))),True,WHITE); surf.blit(n,n.get_rect(center=(W//2,int(H*0.7))))
        if HIM["res"]:
            r=_him_result(surf,dt,mouse,events,HIM["res"]=="win")
            if r: _him_after_result(r)
        elif ui_esc(events): HIM["screen"]="map"
        return None
    return "exit"

