# ══════════════════════════════════════════════════════════════════════════════
# STUDIO SPLASH — the Man Studio intro that plays every time the game opens
# ══════════════════════════════════════════════════════════════════════════════
INTRO_WIPE = {"t": None}                 # the colour bars that hand over to the menu
SPLASH_BARS = ["RED","ORANGE","YELLOW","GREEN","BLUE","PURPLE"]
_SPL_COVER = 0.46                        # how long one bar needs to cross the screen
_SPL_STAG  = 0.045                       # delay between bars

def _spl_snd(kind):
    """Small original sounds for the intro (pure python, no extra libraries)."""
    sr=44100
    def build(dur,fn,vol):
        n=int(sr*dur); buf=bytearray()
        for i in range(n):
            t=i/sr
            v=fn(t)*vol*min(1.0,t/0.004)*min(1.0,(n-i)/(sr*0.05))
            s=max(-32767,min(32767,int(v*32767)))
            buf+=bytes((s&0xFF,(s>>8)&0xFF))*2
        return pygame.mixer.Sound(buffer=bytes(buf))
    try:
        if kind=="fall":        # soft air whoosh
            return build(0.55,lambda t: math.sin(2*math.pi*(160+900*t)*t)*0.25*(t/0.55)
                                        + random.uniform(-1,1)*0.18*(t/0.55),0.55)
        if kind=="impact":      # the squares landing
            return build(0.70,lambda t: math.sin(2*math.pi*(150*math.exp(-t*9)+45)*t)*math.exp(-t*4.2)
                                        + random.uniform(-1,1)*0.25*math.exp(-t*26),0.85)
        if kind=="pop":         # one letter appearing
            return build(0.13,lambda t: math.sin(2*math.pi*(820+560*t)*t)*math.exp(-t*22),0.30)
        if kind=="shine":       # the light sweeping over the logo
            return build(0.85,lambda t: (math.sin(2*math.pi*1250*t)+math.sin(2*math.pi*1870*t)*0.6)
                                        *math.exp(-abs(t-0.30)*6)*0.35,0.42)
        if kind=="swipe":       # the colour bars taking over
            return build(0.60,lambda t: random.uniform(-1,1)*math.exp(-abs(t-0.22)*7)*0.5
                                        + math.sin(2*math.pi*(90+520*t)*t)*0.3*math.exp(-t*3),0.70)
    except Exception:
        return None
    return None

_SPLASH_MUSIC_VER = 2
_SPL_MUSIC = {"snd": None, "tried": False}

def _spl_music():
    """The tiny Man Studio jingle (original). Rendered once, then cached on disk."""
    if _SPL_MUSIC["tried"]: return _SPL_MUSIC["snd"]
    _SPL_MUSIC["tried"]=True
    try:
        import wave
        path=os.path.join(_music_cache_dir(),f"splash_v{_SPLASH_MUSIC_VER}.wav")
        if os.path.exists(path):
            _SPL_MUSIC["snd"]=pygame.mixer.Sound(path); return _SPL_MUSIC["snd"]
        DUR=3.45
        if _np is not None:
            sr=44100; n=int(sr*DUR); t=_np.arange(n)/sr
            L=_np.zeros(n); R=_np.zeros(n)
            def put(t0,sig,pan=0.0,v=1.0):
                i=int(t0*sr)
                if i>=n: return
                j=min(n,i+len(sig)); s=sig[:j-i]*v
                L[i:j]+=s*(0.5-pan*0.5+0.5); R[i:j]+=s*(0.5+pan*0.5+0.5)
            def env(d,a,dec):
                x=_np.arange(int(sr*d))/sr
                return _np.minimum(1,x/max(a,1e-4))*_np.exp(-_np.maximum(0,x-a)*dec)
            def tone(note,d,a=0.01,dec=3.0,harm=(1,0.45,0.22,0.1),vib=0.0):
                x=_np.arange(int(sr*d))/sr; f=_m_hz(note)
                w=sum(h*_np.sin(2*_np.pi*f*k*x*(1+vib*_np.sin(2*_np.pi*5*x))) for k,h in enumerate(harm,1))
                return w*env(d,a,dec)/max(1,sum(harm))
            def bell_(note,d,v=1.0):
                x=_np.arange(int(sr*d))/sr; f=_m_hz(note)
                w=(_np.sin(2*_np.pi*f*x)+0.5*_np.sin(2*_np.pi*f*2.76*x)*_np.exp(-x*5)
                   +0.25*_np.sin(2*_np.pi*f*5.4*x)*_np.exp(-x*8))
                return w*_np.exp(-x*3.4)*_np.minimum(1,x/0.004)*v
            def pad_(notes,d,v=1.0,a=0.5,dec=1.2):
                x=_np.arange(int(sr*d))/sr; w=_np.zeros(len(x))
                for nn in notes:
                    for det in (-0.04,0.0,0.05):
                        f=_m_hz(nn+det); w+=_np.sin(2*_np.pi*f*x)+0.3*_np.sin(2*_np.pi*f*2*x)
                return w/(len(notes)*3)*env(d,a,dec)*v
            def sweep(d,f0,f1,v=1.0):
                x=_np.arange(int(sr*d))/sr; u=x/d; f=f0*(f1/f0)**(u**1.8)
                return _np.sin(2*_np.pi*_np.cumsum(f)/sr)*(u**2)*v
            # ── the jingle ───────────────────────────────────────────────
            put(0.00,pad_([38,45,50],1.05,0.30,0.45,1.4),-0.2)
            put(0.03,pad_([45,57],1.00,0.22,0.50,1.6),0.2)
            put(0.70,pad_([50,54,57,62],2.40,0.34,0.02,0.55))          # the landing chord
            put(0.70,tone(38,1.6,0.005,1.6,(1,0.25),0.0),0.0,0.45)    # soft sub
            for t0,nt in ((0.98,69),(1.13,74),(1.28,78),(1.45,81)):   # the little melody
                put(t0,bell_(nt,1.5,0.34),0.12*(nt-74)/7)
                put(t0,tone(nt,0.9,0.004,4.5,(1,0.3,0.12)),0.0,0.12)
            put(1.58,bell_(86,1.4,0.20),0.25)
            put(1.62,pad_([50,57,62,66,76],1.80,0.36,0.06,0.30))      # warm D add9
            put(2.86,sweep(0.52,240,1500,0.16),0.0)
            put(3.00,pad_([50,57,62,69],0.45,0.30,0.02,2.2))          # last bright chord
            put(3.00,bell_(74,0.45,0.22),0.0)
            mx=max(float(_np.abs(L).max()),float(_np.abs(R).max()),1e-6)
            L=L/mx*0.72; R=R/mx*0.72
            fade=int(sr*0.22); L[-fade:]*=_np.linspace(1,0,fade); R[-fade:]*=_np.linspace(1,0,fade)
            data=_np.stack([L,R],1)
            data=_np.tanh(data*1.25)/_np.tanh(1.25)*0.80
            raw=(data*32000).astype(_np.int16).tobytes()
            ch,rate=2,sr
        else:
            sr=22050; n=int(sr*DUR); buf=[0.0]*n
            def add(t0,d,fn,v=1.0):
                i0=int(t0*sr); nn=int(d*sr)
                for k in range(nn):
                    if i0+k>=n: break
                    buf[i0+k]+=fn(k/sr)*v
            def ev(x,a,dec): return min(1.0,x/max(a,1e-4))*math.exp(-max(0.0,x-a)*dec)
            def chord(notes,a,dec):
                fs=[_m_hz(q) for q in notes]
                return lambda x: sum(math.sin(2*math.pi*f*x) for f in fs)/len(fs)*ev(x,a,dec)
            def bl(note,dec=3.4):
                f=_m_hz(note)
                return lambda x: (math.sin(2*math.pi*f*x)+0.4*math.sin(2*math.pi*f*2.76*x)*math.exp(-x*5))*math.exp(-x*dec)
            add(0.00,1.05,chord([38,45,50],0.45,1.4),0.30)
            add(0.70,2.40,chord([50,54,57,62],0.02,0.55),0.34)
            for t0,nt in ((0.98,69),(1.13,74),(1.28,78),(1.45,81)): add(t0,1.2,bl(nt),0.32)
            add(1.58,1.2,bl(86),0.18)
            add(1.62,1.80,chord([50,57,62,66,76],0.06,0.30),0.32)
            add(3.00,0.45,chord([50,57,62,69],0.02,2.2),0.30)
            mx=max(1e-6,max(abs(q) for q in buf))
            fade=int(sr*0.22)
            raw=bytearray()
            for k,q in enumerate(buf):
                g=1.0 if k<n-fade else (n-k)/fade
                s=max(-32000,min(32000,int(q/mx*0.72*g*32000)))
                raw+=bytes((s&0xFF,(s>>8)&0xFF))
            raw=bytes(raw); ch,rate=1,sr
        try:
            with wave.open(path+".tmp","wb") as w:
                w.setnchannels(ch); w.setsampwidth(2); w.setframerate(rate); w.writeframes(raw)
            os.replace(path+".tmp",path)
            _SPL_MUSIC["snd"]=pygame.mixer.Sound(path)
        except Exception:
            _SPL_MUSIC["snd"]=pygame.mixer.Sound(buffer=raw) if ch==2 else None
    except Exception as e:
        try: print("splash music:",e)
        except Exception: pass
        _SPL_MUSIC["snd"]=None
    return _SPL_MUSIC["snd"]

def _spl_play(snd):
    try:
        if snd: snd.set_volume(max(0.0,min(1.0,gd.get("sfx_volume",0.8)*0.8))); snd.play()
    except Exception: pass

def _spl_bars(surf,prog,retract=False):
    """prog 0..1 ; cover: bars rise and fill the screen. retract: they carry on up and off."""
    w=WIDTH/len(SPLASH_BARS)
    for i,name in enumerate(SPLASH_BARS):
        p=max(0.0,min(1.0,(prog-i*_SPL_STAG/_SPL_COVER)/(1-(len(SPLASH_BARS)-1)*_SPL_STAG/_SPL_COVER)))
        p=p*p*(3-2*p)                                     # smooth
        y = -HEIGHT*p if retract else HEIGHT*(1-p)
        x=int(i*w)
        pygame.draw.rect(surf,NEON[name],(x,int(y),int(w)+2,HEIGHT))
        edge=int(y+HEIGHT) if retract else int(y)
        if -20<edge<HEIGHT+20:
            gl=pygame.Surface((int(w)+2,26),pygame.SRCALPHA)
            for k in range(13):
                a=int(150*(1-k/13))
                pygame.draw.rect(gl,NEON[name]+(a,),(0,13-k,int(w)+2,2))
                pygame.draw.rect(gl,(255,255,255,a//3),(0,13+k,int(w)+2,2))
            surf.blit(gl,(x,edge-13),special_flags=pygame.BLEND_PREMULTIPLIED if False else 0)

def studio_splash():
    """The Man Studio intro. Returns when the colour bars have covered the screen."""
    global WIDTH,HEIGHT,screen
    if os.environ.get("CUP_NO_SPLASH"): return
    if os.environ.get("SDL_VIDEODRIVER")=="dummy" and not os.environ.get("CUP_FORCE_SPLASH"): return
    if not gd.get("splash",True): return
    try:
        base=min(WIDTH,HEIGHT)
        s_fall=_spl_snd("fall"); s_hit=_spl_snd("impact"); s_pop=_spl_snd("pop")
        s_shine=_spl_snd("shine"); s_swipe=_spl_snd("swipe")
        TITLE="MAN STUDIO"
        def build_text():
            # The size comes down until the whole studio name fits the window, so a
            # longer name can never run off the edge.
            sz=max(24,int(min(WIDTH,HEIGHT)*0.20))
            track=max(2,int(min(WIDTH,HEIGHT)*0.006))
            for _ in range(28):
                f=pygame.font.SysFont(None,sz,bold=True)
                gl=[(c,f.render(c,True,(255,255,255))) for c in TITLE]
                tot=sum(g.get_width() for _,g in gl)+track*(len(gl)-1)
                if tot<=WIDTH*0.86 or sz<=24: break
                sz=max(24,int(sz*0.93))
            f2=pygame.font.SysFont(None,max(12,int(min(WIDTH,HEIGHT)*0.045)),bold=True)
            return f,f2,gl,track,tot
        font_big,font_sub,glyphs,track,total_w=build_text()
        sub=font_sub.render("G A M E S",True,(210,215,255))
        cx,cy=WIDTH//2,int(HEIGHT*0.46)
        N=len(SPLASH_BARS)
        sq=max(14,int(base*0.052))
        dots=[]
        for i in range(N):
            dots.append({"c":NEON[SPLASH_BARS[i]],
                         "x0":WIDTH*(0.5+(i-(N-1)/2)*0.17), "y0":-base*0.30-i*base*0.07,
                         "x1":WIDTH*(0.5+(i-(N-1)/2)*0.085),"y1":cy,
                         "d":0.045*i,"rot":random.uniform(-3,3)})
        parts=[]
        played={"fall":False,"hit":False,"shine":False,"swipe":False}
        popped=set()
        T_LAND=0.70; T_LET=0.98; T_SUB=1.58; T_SHINE=1.46; T_HOLD=2.80
        t=0.0; skipping=False
        _jingle=_spl_music()
        if _jingle:
            try:
                _jingle.set_volume(max(0.0,min(1.0,gd.get("music_volume",0.8)*0.75)))
                _jch=_jingle.play()
            except Exception: _jch=None
        else: _jch=None
        _spl_play(s_fall); played["fall"]=True
        while True:
            dt=min(0.05,clock.tick(60)/1000.0); t+=dt
            _HB["t"]=time.time(); _HB["where"]="splash"     # the intro beats too
            for ev in pygame.event.get():
                if ev.type==pygame.QUIT:
                    try: quit_game()
                    except Exception: pygame.quit(); sys.exit()
                if ev.type==pygame.VIDEORESIZE:
                    WIDTH,HEIGHT=ev.w,ev.h
                    screen=pygame.display.set_mode((WIDTH,HEIGHT),pygame.RESIZABLE)
                    make_fonts(); base=min(WIDTH,HEIGHT)
                    font_big,font_sub,glyphs,track,total_w=build_text()
                    sub=font_sub.render("G A M E S",True,(210,215,255))
                    cx,cy=WIDTH//2,int(HEIGHT*0.46)
                if ev.type==pygame.KEYDOWN and ev.key==pygame.K_F11:
                    pygame.display.toggle_fullscreen(); WIDTH,HEIGHT=screen.get_size()
                    make_fonts(); base=min(WIDTH,HEIGHT)
                    font_big,font_sub,glyphs,track,total_w=build_text()
                    sub=font_sub.render("G A M E S",True,(210,215,255))
                    cx,cy=WIDTH//2,int(HEIGHT*0.46)
                if ev.type in (pygame.KEYDOWN,pygame.MOUSEBUTTONDOWN) and not skipping:
                    skipping=True; t=max(t,T_HOLD)            # any key / click -> straight to the transition
                    try:
                        if _jch: _jch.fadeout(320)
                    except Exception: pass

            cv=pygame.Surface((WIDTH,HEIGHT)); cv.fill((8,8,16))
            # soft breathing glow behind everything
            for r,a in ((int(base*0.62),16),(int(base*0.42),22),(int(base*0.26),26)):
                g=pygame.Surface((r*2,r*2),pygame.SRCALPHA)
                pygame.draw.circle(g,(40,45,90,int(a*(0.6+0.4*math.sin(t*1.6)))),(r,r),r)
                cv.blit(g,(cx-r,cy-r))

            # ── the six colour squares fall in and land ──────────────────────
            if t<T_LET+0.35:
                for i,d in enumerate(dots):
                    u=max(0.0,min(1.0,(t-d["d"])/(T_LAND-d["d"]+0.0001)))
                    e=1-(1-u)**3
                    x=d["x0"]+(d["x1"]-d["x0"])*e; y=d["y0"]+(d["y1"]-d["y0"])*e
                    sqz=1.0
                    if u>=1.0:
                        b=min(1.0,(t-T_LAND)/0.26)
                        sqz=1+0.5*math.sin(b*math.pi)*(1-b)        # squash & settle
                        y=d["y1"]-abs(math.sin(b*math.pi*2))*base*0.05*(1-b)
                    sz=int(sq*(1.0 if t<T_LAND else max(0.0,1-(t-T_LET+0.2)/0.45)))
                    if sz<2: continue
                    w_=int(sz*sqz); h_=int(sz/max(0.4,sqz))
                    s=pygame.Surface((w_*2,h_*2),pygame.SRCALPHA)
                    pygame.draw.rect(s,d["c"]+(70,),(0,0,w_*2,h_*2),border_radius=w_//2)
                    cv.blit(s,(int(x-w_),int(y-h_)))
                    pygame.draw.rect(cv,d["c"],(int(x-w_//2),int(y-h_//2),w_,h_),border_radius=max(2,w_//4))
                    pygame.draw.rect(cv,(255,255,255),(int(x-w_//2),int(y-h_//2),w_,h_),2,border_radius=max(2,w_//4))
            if t>=T_LAND and not played["hit"]:
                played["hit"]=True; _spl_play(s_hit)
                try: start_shake(6,16)
                except Exception: pass
                for i,d in enumerate(dots):
                    for _ in range(14):
                        a=random.uniform(0,math.tau); sp=random.uniform(60,330)
                        parts.append({"x":d["x1"],"y":d["y1"],"vx":math.cos(a)*sp,"vy":math.sin(a)*sp-80,
                                      "c":d["c"],"life":random.uniform(0.5,1.2),"r":random.uniform(1.5,4)})
            # shock ring
            if T_LAND<=t<T_LAND+0.55:
                u=(t-T_LAND)/0.55; r=int(base*(0.08+0.75*u)); a=int(150*(1-u))
                ring=pygame.Surface((r*2+8,r*2+8),pygame.SRCALPHA)
                pygame.draw.circle(ring,(255,255,255,a),(r+4,r+4),r,max(1,int(7*(1-u))))
                cv.blit(ring,(cx-r-4,cy-r-4))

            # ── the letters pop out one by one ───────────────────────────────
            if t>=T_LET:
                x=cx-total_w//2
                for i,(ch,g) in enumerate(glyphs):
                    st=T_LET+i*0.042
                    u=max(0.0,min(1.0,(t-st)/0.30))
                    if u>0:
                        if i not in popped and ch.strip():
                            popped.add(i); _spl_play(s_pop)
                        k=1.7; e=1+ (k+1)*((u-1)**3) + k*((u-1)**2)     # easeOutBack
                        sc=max(0.05,0.35+0.65*e)
                        w_,h_=max(1,int(g.get_width()*sc)),max(1,int(g.get_height()*sc))
                        gs=pygame.transform.smoothscale(g,(w_,h_))
                        col=NEON[SPLASH_BARS[i%len(SPLASH_BARS)]]
                        sh=pygame.Surface(gs.get_size(),pygame.SRCALPHA)
                        sh.fill(col+(0,)); sh.blit(gs,(0,0),special_flags=pygame.BLEND_RGBA_MULT)
                        tint=pygame.Surface(gs.get_size(),pygame.SRCALPHA); tint.fill(col+(255,))
                        tint.blit(gs,(0,0),special_flags=pygame.BLEND_RGBA_MULT)
                        off=int(base*0.012*(1-u)+base*0.006)
                        px=int(x+g.get_width()//2-w_//2); py=int(cy-h_//2-base*0.02*(1-u))
                        cv.blit(tint,(px+off,py+off))
                        cv.blit(gs,(px,py))
                    x+=g.get_width()+track
            # ── sweep of light over the logo ─────────────────────────────────
            if T_SHINE<=t<T_SHINE+0.9:
                if not played["shine"]: played["shine"]=True; _spl_play(s_shine)
                u=(t-T_SHINE)/0.9
                bw=int(base*0.20); bx=int(cx-total_w//2-bw+ (total_w+bw*2)*u)
                mask=pygame.Surface((total_w+8,font_big.get_height()+8),pygame.SRCALPHA)
                xx=0
                for ch,g in glyphs:
                    mask.blit(g,(xx,0)); xx+=g.get_width()+track
                beam=pygame.Surface(mask.get_size(),pygame.SRCALPHA)
                for k in range(bw):
                    a=int(205*math.sin(math.pi*k/bw)**3)
                    pygame.draw.line(beam,(a,a,a,255),(bx-(cx-total_w//2)+k,0),
                                     (bx-(cx-total_w//2)+k-int(bw*0.4),mask.get_height()))
                beam.blit(mask,(0,0),special_flags=pygame.BLEND_RGBA_MULT)
                cv.blit(beam,(cx-total_w//2,cy-font_big.get_height()//2),special_flags=pygame.BLEND_RGB_ADD)
            # ── the line + GAMES ─────────────────────────────────────────────
            if t>=T_SUB:
                u=min(1.0,(t-T_SUB)/0.45)
                lw=int(total_w*0.55*u)
                ly=cy+int(font_big.get_height()*0.42)
                pygame.draw.rect(cv,(150,160,220),(cx-lw//2,ly,lw,2))
                s2=sub.copy(); s2.set_alpha(int(255*u))
                cv.blit(s2,(cx-sub.get_width()//2,ly+int(base*0.022)))
            # ── particles ────────────────────────────────────────────────────
            for p in parts[:]:
                p["life"]-=dt
                if p["life"]<=0: parts.remove(p); continue
                p["x"]+=p["vx"]*dt; p["y"]+=p["vy"]*dt; p["vy"]+=620*dt
                a=max(0,min(255,int(255*p["life"])))
                ps=pygame.Surface((int(p["r"]*2)+2,int(p["r"]*2)+2),pygame.SRCALPHA)
                pygame.draw.circle(ps,p["c"]+(a,),(int(p["r"])+1,int(p["r"])+1),int(p["r"]))
                cv.blit(ps,(p["x"],p["y"]))
            # floating dust while the logo is held
            if t>T_LET:
                for i in range(18):
                    px=(cx+math.sin(t*0.5+i*2.1)*base*0.55)%WIDTH
                    py=(cy+math.cos(t*0.37+i*1.7)*base*0.38+math.sin(t*0.8+i)*8)
                    a=int(70+50*math.sin(t*2+i))
                    pygame.draw.circle(cv,(170,180,230),(int(px),int(py)),1)
            # ── the hand-over: colour bars sweep up ──────────────────────────
            done=False
            if t>=T_HOLD:
                if not played["swipe"]: played["swipe"]=True; _spl_play(s_swipe)
                p=(t-T_HOLD)/_SPL_COVER
                _spl_bars(cv,min(1.0,p))
                if p>=1.0: done=True
            try: screen.blit(cv,get_shake())
            except Exception: screen.blit(cv,(0,0))
            pygame.display.flip()
            if done: break
        INTRO_WIPE["t"]=0.0
    except Exception as e:
        try:
            print("splash skipped:",repr(e))
            if os.environ.get("CUP_SPLASH_DEBUG"):
                import traceback; traceback.print_exc()
        except Exception: pass
        INTRO_WIPE["t"]=None

