def _crash_text(exc):
    import traceback as _tb, datetime as _dtm, platform as _pf
    head=["Color Under Pressure  -  error report",
          "when    : %s"%_dtm.datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
          "version : %s"%GAME_VERSION,
          "frozen  : %s"%bool(getattr(sys,"frozen",False)),
          "python  : %s   %s"%(sys.version.split()[0],_pf.platform())]
    try: head.append("pygame  : %s   sdl %s"%(pygame.version.ver,".".join(str(x) for x in pygame.get_sdl_version())))
    except Exception: pass
    try: head.append("screen  : %sx%s   skin %s   lang %s"%(WIDTH,HEIGHT,gd.get("current_skin"),current_lang))
    except Exception: pass
    return "\n".join(head)+"\n\n"+"".join(_tb.format_exception(type(exc),exc,exc.__traceback__))

def _copy_to_clipboard(text):
    """Windows first (clip.exe), then tkinter. Returns True if it worked."""
    try:
        import subprocess
        si=None
        if os.name=="nt":
            si=subprocess.STARTUPINFO(); si.dwFlags|=subprocess.STARTF_USESHOWWINDOW
            subprocess.run(["clip"],input=text.encode("utf-16-le"),check=True,startupinfo=si)
            return True
    except Exception: pass
    try:
        import tkinter as _tk
        r=_tk.Tk(); r.withdraw(); r.clipboard_clear(); r.clipboard_append(text)
        r.update(); r.destroy(); return True
    except Exception: pass
    return False

def _crash_screen(exc, fatal=True):
    """Shows what went wrong. DEV MODE gets the whole error; everyone can copy it.
    Returns 'continue' / 'quit'."""
    txt=_crash_text(exc)
    try: dev=bool(dev_mode())
    except Exception: dev=False
    body=[l.rstrip() for l in txt.splitlines() if l.strip()]
    if not dev:
        body=[l for l in body if l.startswith(("version","when"))]+["",
              str(type(exc).__name__)+": "+str(exc)[:90],"",
              "Press C to copy the full report and send it to Man Studio."]
    else:
        body=body[-26:]
    copied=0.0
    try:
        if not pygame.display.get_surface(): pygame.display.set_mode((900,700),pygame.RESIZABLE)
        sc=pygame.display.get_surface()
        f1=pygame.font.SysFont("consolas,couriernew,monospace",26,bold=True)
        f2=pygame.font.SysFont("consolas,couriernew,monospace",14)
        f3=pygame.font.SysFont("consolas,couriernew,monospace",17,bold=True)
        clk=pygame.time.Clock()
        while True:
            for ev in pygame.event.get():
                if ev.type==pygame.QUIT: return "quit"
                if ev.type==pygame.VIDEORESIZE:
                    try: pygame.display.set_mode(ev.size,pygame.RESIZABLE); sc=pygame.display.get_surface()
                    except Exception: pass
                if ev.type==pygame.KEYDOWN:
                    if ev.key==pygame.K_c:
                        copied=time.time() if _copy_to_clipboard(txt) else -1
                    elif ev.key in (pygame.K_r,pygame.K_RETURN,pygame.K_SPACE): return "continue"
                    elif ev.key in (pygame.K_ESCAPE,pygame.K_q): return "quit"
            W,H=sc.get_size(); sc.fill((12,9,20))
            pygame.draw.rect(sc,(200,45,70),(0,0,W,7))
            sc.blit(f1.render("Something went wrong." if not dev else "DEV: error",True,(255,120,140)),(28,26))
            y=74
            sc.blit(f2.render("A report was saved to:",True,(190,190,215)),(28,y)); y+=20
            sc.blit(f2.render(CRASH_FILE[:150],True,(255,205,110)),(28,y)); y+=28
            pygame.draw.line(sc,(55,45,78),(28,y),(W-28,y),1); y+=12
            for t_ in body:
                sc.blit(f2.render(t_[:150],True,(175,180,205)),(28,y)); y+=18
                if y>H-96: break
            keys="C = copy the error     R = keep playing     ESC = quit"
            sc.blit(f3.render(keys,True,(130,205,255)),(28,H-44))
            if copied>0 and time.time()-copied<2.5:
                sc.blit(f3.render("copied!",True,(110,235,150)),(28,H-70))
            elif copied<0:
                sc.blit(f3.render("could not copy - send crash.txt instead",True,(255,180,90)),(28,H-70))
            pygame.display.flip(); clk.tick(30)
    except Exception:
        return "quit"

_FRAME_ERR={"n":0,"seen":set()}
_LAST_ERR={"exc":None,"shown":0.0}          # F12 brings the last one back up
def _frame_error(exc, where=None):
    """One frame blew up. Log it, keep the game alive. True = give up."""
    log_problem("frame"+(" on screen '%s'"%where if where else ""),exc)
    _FRAME_ERR["n"]+=1
    _LAST_ERR["exc"]=exc
    sig=(type(exc).__name__,str(exc)[:90])
    first=sig not in _FRAME_ERR["seen"]
    _FRAME_ERR["seen"].add(sig)
    try: dev=bool(dev_mode())
    except Exception: dev=False
    # the same failure can happen every frame: show it once, not 60 times a second
    if first:
        if dev:
            if _crash_screen(exc,fatal=False)=="quit": return True
        else:
            try:
                _badge_toasts.append({"id":None,"t":None,"custom":True,"title":"OOPS  (F12)",
                    "name":"Something went wrong","desc":"F12 shows what happened","col":(230,80,90),"icon":"bug"})
            except Exception: pass
    # the frame died before it could be shown, so keep the window alive by hand
    try:
        pygame.event.pump(); pygame.display.flip()
    except Exception: pass
    return _FRAME_ERR["n"]>600         # ~10 seconds of solid failure: stop instead of spinning

def _boot():
    _tee_output()
    _start_watchdog()
    tries=0
    while True:
        try:
            main(); return
        except SystemExit:
            raise
        except BaseException as e:
            log_problem("fatal",e,fatal=True)
            try:
                import traceback; traceback.print_exc()
            except Exception: pass
            tries+=1
            if tries>3: return
            if _crash_screen(e,fatal=True)!="continue": return

if __name__=="__main__":
    _boot()
